VirtIODevice *virtio_net_init(DeviceState *dev)

{

    VirtIONet *n;

    static int virtio_net_id;



    n = (VirtIONet *)virtio_common_init("virtio-net", VIRTIO_ID_NET,

                                        sizeof(struct virtio_net_config),

                                        sizeof(VirtIONet));



    n->vdev.get_config = virtio_net_get_config;

    n->vdev.set_config = virtio_net_set_config;

    n->vdev.get_features = virtio_net_get_features;

    n->vdev.set_features = virtio_net_set_features;

    n->vdev.bad_features = virtio_net_bad_features;

    n->vdev.reset = virtio_net_reset;

    n->rx_vq = virtio_add_queue(&n->vdev, 256, virtio_net_handle_rx);

    n->tx_vq = virtio_add_queue(&n->vdev, 256, virtio_net_handle_tx);

    n->ctrl_vq = virtio_add_queue(&n->vdev, 16, virtio_net_handle_ctrl);

    qdev_get_macaddr(dev, n->mac);

    n->status = VIRTIO_NET_S_LINK_UP;

    n->vc = qdev_get_vlan_client(dev,

                                 virtio_net_can_receive,

                                 virtio_net_receive, NULL,

                                 virtio_net_cleanup, n);

    n->vc->link_status_changed = virtio_net_set_link_status;



    qemu_format_nic_info_str(n->vc, n->mac);



    n->tx_timer = qemu_new_timer(vm_clock, virtio_net_tx_timer, n);

    n->tx_timer_active = 0;

    n->mergeable_rx_bufs = 0;

    n->promisc = 1; /* for compatibility */



    n->mac_table.macs = qemu_mallocz(MAC_TABLE_ENTRIES * ETH_ALEN);



    n->vlans = qemu_mallocz(MAX_VLAN >> 3);



    register_savevm("virtio-net", virtio_net_id++, VIRTIO_NET_VM_VERSION,

                    virtio_net_save, virtio_net_load, n);



    return &n->vdev;

}

static RAMBlock *qemu_get_ram_block(ram_addr_t addr)

{

    RAMBlock *block;



    /* The list is protected by the iothread lock here.  */

    block = ram_list.mru_block;

    if (block && addr - block->offset < block->max_length) {

        goto found;

    }

    QTAILQ_FOREACH(block, &ram_list.blocks, next) {

        if (addr - block->offset < block->max_length) {

            goto found;

        }

    }



    fprintf(stderr, "Bad ram offset %" PRIx64 "\n", (uint64_t)addr);

    abort();



found:

    ram_list.mru_block = block;

    return block;

}

static uint32_t mvc_asc(CPUS390XState *env, int64_t l, uint64_t a1,

                        uint64_t mode1, uint64_t a2, uint64_t mode2)

{

    CPUState *cs = CPU(s390_env_get_cpu(env));

    target_ulong src, dest;

    int flags, cc = 0, i;



    if (!l) {

        return 0;

    } else if (l > 256) {

        /* max 256 */

        l = 256;

        cc = 3;

    }



    if (mmu_translate(env, a1, 1, mode1, &dest, &flags, true)) {

        cpu_loop_exit(CPU(s390_env_get_cpu(env)));

    }

    dest |= a1 & ~TARGET_PAGE_MASK;



    if (mmu_translate(env, a2, 0, mode2, &src, &flags, true)) {

        cpu_loop_exit(CPU(s390_env_get_cpu(env)));

    }

    src |= a2 & ~TARGET_PAGE_MASK;



    /* XXX replace w/ memcpy */

    for (i = 0; i < l; i++) {

        /* XXX be more clever */

        if ((((dest + i) & TARGET_PAGE_MASK) != (dest & TARGET_PAGE_MASK)) ||

            (((src + i) & TARGET_PAGE_MASK) != (src & TARGET_PAGE_MASK))) {

            mvc_asc(env, l - i, a1 + i, mode1, a2 + i, mode2);

            break;

        }

        stb_phys(cs->as, dest + i, ldub_phys(cs->as, src + i));

    }



    return cc;

}

int av_set_string3(void *obj, const char *name, const char *val, int alloc, const AVOption **o_out)

{

    int ret;

    const AVOption *o = av_opt_find(obj, name, NULL, 0, 0);

    if (o_out)

        *o_out = o;

    if (!o)

        return AVERROR_OPTION_NOT_FOUND;

    if (!val || o->offset<=0)

        return AVERROR(EINVAL);



    if (o->type == FF_OPT_TYPE_BINARY) {

        uint8_t **dst = (uint8_t **)(((uint8_t*)obj) + o->offset);

        int *lendst = (int *)(dst + 1);

        uint8_t *bin, *ptr;

        int len = strlen(val);

        av_freep(dst);

        *lendst = 0;

        if (len & 1) return AVERROR(EINVAL);

        len /= 2;

        ptr = bin = av_malloc(len);

        while (*val) {

            int a = hexchar2int(*val++);

            int b = hexchar2int(*val++);

            if (a < 0 || b < 0) {

                av_free(bin);

                return AVERROR(EINVAL);

            }

            *ptr++ = (a << 4) | b;

        }

        *dst = bin;

        *lendst = len;

        return 0;

    }

    if (o->type != FF_OPT_TYPE_STRING) {

        int notfirst=0;

        for (;;) {

            int i;

            char buf[256];

            int cmd=0;

            double d;



            if (*val == '+' || *val == '-')

                cmd= *(val++);



            for (i=0; i<sizeof(buf)-1 && val[i] && val[i]!='+' && val[i]!='-'; i++)

                buf[i]= val[i];

            buf[i]=0;



            {

                const AVOption *o_named = av_opt_find(obj, buf, o->unit, 0, 0);

                if (o_named && o_named->type == FF_OPT_TYPE_CONST)

                    d= o_named->default_val.dbl;

                else if (!strcmp(buf, "default")) d= o->default_val.dbl;

                else if (!strcmp(buf, "max"    )) d= o->max;

                else if (!strcmp(buf, "min"    )) d= o->min;

                else if (!strcmp(buf, "none"   )) d= 0;

                else if (!strcmp(buf, "all"    )) d= ~0;

                else {

                    int res = av_expr_parse_and_eval(&d, buf, const_names, const_values, NULL, NULL, NULL, NULL, NULL, 0, obj);

                    if (res < 0) {

                        av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\"\n", val);

                        return res;

                    }

                }

            }

            if (o->type == FF_OPT_TYPE_FLAGS) {

                if      (cmd=='+') d= av_get_int(obj, name, NULL) | (int64_t)d;

                else if (cmd=='-') d= av_get_int(obj, name, NULL) &~(int64_t)d;

            } else {

                if      (cmd=='+') d= notfirst*av_get_double(obj, name, NULL) + d;

                else if (cmd=='-') d= notfirst*av_get_double(obj, name, NULL) - d;

            }



            if ((ret = av_set_number2(obj, name, d, 1, 1, o_out)) < 0)

                return ret;

            val+= i;

            if (!*val)

                return 0;

            notfirst=1;

        }

        return AVERROR(EINVAL);

    }



    if (alloc) {

        av_free(*(void**)(((uint8_t*)obj) + o->offset));

        val= av_strdup(val);

    }



    memcpy(((uint8_t*)obj) + o->offset, &val, sizeof(val));

    return 0;

}

