static int asf_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    ASFContext *asf = s->priv_data;

    ASFStream *asf_st = 0;

    ByteIOContext *pb = &s->pb;

    //static int pc = 0;

    for (;;) {

        int rsize = 0;

        if (asf->packet_size_left < FRAME_HEADER_SIZE

            || asf->packet_segments < 1) {

            //asf->packet_size_left <= asf->packet_padsize) {

            int ret = asf->packet_size_left + asf->packet_padsize;

            //printf("PacketLeftSize:%d  Pad:%d Pos:%Ld\n", asf->packet_size_left, asf->packet_padsize, url_ftell(pb));

            if((url_ftell(&s->pb) + ret - s->data_offset) % asf->packet_size)

                ret += asf->packet_size - ((url_ftell(&s->pb) + ret - s->data_offset) % asf->packet_size);

            /* fail safe */

            url_fskip(pb, ret);

            asf->packet_pos= url_ftell(&s->pb);




            ret = asf_get_packet(s);

            //printf("READ ASF PACKET  %d   r:%d   c:%d\n", ret, asf->packet_size_left, pc++);

            if (ret < 0 || url_feof(pb))

                return AVERROR_IO;

            asf->packet_time_start = 0;

            continue;

        }

        if (asf->packet_time_start == 0) {

            /* read frame header */

            int num = get_byte(pb);

            asf->packet_segments--;

            rsize++;

            asf->packet_key_frame = (num & 0x80) >> 7;

            asf->stream_index = asf->asfid2avid[num & 0x7f];

            // sequence should be ignored!

            DO_2BITS(asf->packet_property >> 4, asf->packet_seq, 0);

            DO_2BITS(asf->packet_property >> 2, asf->packet_frag_offset, 0);

            DO_2BITS(asf->packet_property, asf->packet_replic_size, 0);

//printf("key:%d stream:%d seq:%d offset:%d replic_size:%d\n", asf->packet_key_frame, asf->stream_index, asf->packet_seq, //asf->packet_frag_offset, asf->packet_replic_size);

            if (asf->packet_replic_size > 1) {

                assert(asf->packet_replic_size >= 8);

                // it should be always at least 8 bytes - FIXME validate

                asf->packet_obj_size = get_le32(pb);

                asf->packet_frag_timestamp = get_le32(pb); // timestamp

                if (asf->packet_replic_size > 8)

                    url_fskip(pb, asf->packet_replic_size - 8);

                rsize += asf->packet_replic_size; // FIXME - check validity

            } else if (asf->packet_replic_size==1){

                // multipacket - frag_offset is begining timestamp

                asf->packet_time_start = asf->packet_frag_offset;

                asf->packet_frag_offset = 0;

                asf->packet_frag_timestamp = asf->packet_timestamp;



                asf->packet_time_delta = get_byte(pb);

                rsize++;

            }else{

                assert(asf->packet_replic_size==0);

            }

            if (asf->packet_flags & 0x01) {

                DO_2BITS(asf->packet_segsizetype >> 6, asf->packet_frag_size, 0); // 0 is illegal

#undef DO_2BITS

                //printf("Fragsize %d\n", asf->packet_frag_size);

            } else {

                asf->packet_frag_size = asf->packet_size_left - rsize;

                //printf("Using rest  %d %d %d\n", asf->packet_frag_size, asf->packet_size_left, rsize);

            }

            if (asf->packet_replic_size == 1) {

                asf->packet_multi_size = asf->packet_frag_size;

                if (asf->packet_multi_size > asf->packet_size_left) {

                    asf->packet_segments = 0;

                    continue;

                }

            }

            asf->packet_size_left -= rsize;

            //printf("___objsize____  %d   %d    rs:%d\n", asf->packet_obj_size, asf->packet_frag_offset, rsize);



            if (asf->stream_index < 0

                || s->streams[asf->stream_index]->discard >= AVDISCARD_ALL

                || (!asf->packet_key_frame && s->streams[asf->stream_index]->discard >= AVDISCARD_NONKEY)

                ) {

                asf->packet_time_start = 0;

                /* unhandled packet (should not happen) */

                url_fskip(pb, asf->packet_frag_size);

                asf->packet_size_left -= asf->packet_frag_size;

                if(asf->stream_index < 0)

                    av_log(s, AV_LOG_ERROR, "ff asf skip %d  %d\n", asf->packet_frag_size, num & 0x7f);

                continue;

            }

            asf->asf_st = s->streams[asf->stream_index]->priv_data;

        }

        asf_st = asf->asf_st;



        if ((asf->packet_frag_offset != asf_st->frag_offset

             || (asf->packet_frag_offset

                 && asf->packet_seq != asf_st->seq)) // seq should be ignored

           ) {

            /* cannot continue current packet: free it */

            // FIXME better check if packet was already allocated

            av_log(s, AV_LOG_INFO, "ff asf parser skips: %d - %d     o:%d - %d    %d %d   fl:%d\n",

                   asf_st->pkt.size,

                   asf->packet_obj_size,

                   asf->packet_frag_offset, asf_st->frag_offset,

                   asf->packet_seq, asf_st->seq, asf->packet_frag_size);

            if (asf_st->pkt.size)

                av_free_packet(&asf_st->pkt);

            asf_st->frag_offset = 0;

            if (asf->packet_frag_offset != 0) {

                url_fskip(pb, asf->packet_frag_size);

                av_log(s, AV_LOG_INFO, "ff asf parser skipping %db\n", asf->packet_frag_size);

                asf->packet_size_left -= asf->packet_frag_size;

                continue;

            }

        }

        if (asf->packet_replic_size == 1) {

            // frag_offset is here used as the begining timestamp

            asf->packet_frag_timestamp = asf->packet_time_start;

            asf->packet_time_start += asf->packet_time_delta;

            asf->packet_obj_size = asf->packet_frag_size = get_byte(pb);

            asf->packet_size_left--;

            asf->packet_multi_size--;

            if (asf->packet_multi_size < asf->packet_obj_size)

            {

                asf->packet_time_start = 0;

                url_fskip(pb, asf->packet_multi_size);

                asf->packet_size_left -= asf->packet_multi_size;

                continue;

            }

            asf->packet_multi_size -= asf->packet_obj_size;

            //printf("COMPRESS size  %d  %d  %d   ms:%d\n", asf->packet_obj_size, asf->packet_frag_timestamp, asf->packet_size_left, asf->packet_multi_size);

        }

        if (asf_st->frag_offset == 0) {

            /* new packet */

            av_new_packet(&asf_st->pkt, asf->packet_obj_size);

            asf_st->seq = asf->packet_seq;

            asf_st->pkt.pts = asf->packet_frag_timestamp;

            asf_st->pkt.stream_index = asf->stream_index;

            asf_st->pkt.pos =

            asf_st->packet_pos= asf->packet_pos;

//printf("new packet: stream:%d key:%d packet_key:%d audio:%d size:%d\n",

//asf->stream_index, asf->packet_key_frame, asf_st->pkt.flags & PKT_FLAG_KEY,

//s->streams[asf->stream_index]->codec->codec_type == CODEC_TYPE_AUDIO, asf->packet_obj_size);

            if (s->streams[asf->stream_index]->codec->codec_type == CODEC_TYPE_AUDIO)

                asf->packet_key_frame = 1;

            if (asf->packet_key_frame)

                asf_st->pkt.flags |= PKT_FLAG_KEY;

        }



        /* read data */

        //printf("READ PACKET s:%d  os:%d  o:%d,%d  l:%d   DATA:%p\n",

        //       asf->packet_size, asf_st->pkt.size, asf->packet_frag_offset,

        //       asf_st->frag_offset, asf->packet_frag_size, asf_st->pkt.data);

        asf->packet_size_left -= asf->packet_frag_size;

        if (asf->packet_size_left < 0)

            continue;

        get_buffer(pb, asf_st->pkt.data + asf->packet_frag_offset,

                   asf->packet_frag_size);

        asf_st->frag_offset += asf->packet_frag_size;

        /* test if whole packet is read */

        if (asf_st->frag_offset == asf_st->pkt.size) {

            /* return packet */

            if (asf_st->ds_span > 1) {

                /* packet descrambling */

                char* newdata = av_malloc(asf_st->pkt.size);

                if (newdata) {

                    int offset = 0;

                    while (offset < asf_st->pkt.size) {

                        int off = offset / asf_st->ds_chunk_size;

                        int row = off / asf_st->ds_span;

                        int col = off % asf_st->ds_span;

                        int idx = row + col * asf_st->ds_packet_size / asf_st->ds_chunk_size;

                        //printf("off:%d  row:%d  col:%d  idx:%d\n", off, row, col, idx);

                        memcpy(newdata + offset,

                               asf_st->pkt.data + idx * asf_st->ds_chunk_size,

                               asf_st->ds_chunk_size);

                        offset += asf_st->ds_chunk_size;

                    }

                    av_free(asf_st->pkt.data);

                    asf_st->pkt.data = newdata;

                }

            }

            asf_st->frag_offset = 0;

            memcpy(pkt, &asf_st->pkt, sizeof(AVPacket));

            //printf("packet %d %d\n", asf_st->pkt.size, asf->packet_frag_size);

            asf_st->pkt.size = 0;

            asf_st->pkt.data = 0;

            break; // packet completed

        }

    }

    return 0;

}

static void gen_ldarx(DisasContext *ctx)

{

    TCGv t0;

    gen_set_access_type(ctx, ACCESS_RES);

    t0 = tcg_temp_local_new();

    gen_addr_reg_index(ctx, t0);

    gen_check_align(ctx, t0, 0x07);

    gen_qemu_ld64(ctx, cpu_gpr[rD(ctx->opcode)], t0);

    tcg_gen_mov_tl(cpu_reserve, t0);

    tcg_temp_free(t0);

}

static struct omap_watchdog_timer_s *omap_wd_timer_init(MemoryRegion *memory,

                hwaddr base,

                qemu_irq irq, omap_clk clk)

{

    struct omap_watchdog_timer_s *s = (struct omap_watchdog_timer_s *)

            g_malloc0(sizeof(struct omap_watchdog_timer_s));



    s->timer.irq = irq;

    s->timer.clk = clk;

    s->timer.timer = timer_new_ns(QEMU_CLOCK_VIRTUAL, omap_timer_tick, &s->timer);

    omap_wd_timer_reset(s);

    omap_timer_clk_setup(&s->timer);



    memory_region_init_io(&s->iomem, NULL, &omap_wd_timer_ops, s,

                          "omap-wd-timer", 0x100);

    memory_region_add_subregion(memory, base, &s->iomem);



    return s;

}

static void ripemd160_transform(uint32_t *state, const uint8_t buffer[64], int ext)

{

    uint32_t a, b, c, d, e, f, g, h, i, j;

    uint32_t block[16];

    int n;



    if (ext) {

        a = state[0]; b = state[1]; c = state[2]; d = state[3]; e = state[4];

        f = state[5]; g = state[6]; h = state[7]; i = state[8]; j = state[9];

    } else {

        a = f = state[0];

        b = g = state[1];

        c = h = state[2];

        d = i = state[3];

        e = j = state[4];

    }



    for (n = 0; n < 16; n++)

        block[n] = AV_RL32(buffer + 4 * n);



    for (n = 0; n < 16 - 1;) {

        ROUND160_0_TO_15(a,b,c,d,e,f,g,h,i,j);

        ROUND160_0_TO_15(e,a,b,c,d,j,f,g,h,i);

        ROUND160_0_TO_15(d,e,a,b,c,i,j,f,g,h);

        ROUND160_0_TO_15(c,d,e,a,b,h,i,j,f,g);

        ROUND160_0_TO_15(b,c,d,e,a,g,h,i,j,f);

    }

    ROUND160_0_TO_15(a,b,c,d,e,f,g,h,i,j);

    SWAP(a,f)



    for (; n < 32 - 1;) {

        ROUND160_16_TO_31(e,a,b,c,d,j,f,g,h,i);

        ROUND160_16_TO_31(d,e,a,b,c,i,j,f,g,h);

        ROUND160_16_TO_31(c,d,e,a,b,h,i,j,f,g);

        ROUND160_16_TO_31(b,c,d,e,a,g,h,i,j,f);

        ROUND160_16_TO_31(a,b,c,d,e,f,g,h,i,j);

    }

    ROUND160_16_TO_31(e,a,b,c,d,j,f,g,h,i);

    SWAP(b,g)



    for (; n < 48 - 1;) {

        ROUND160_32_TO_47(d,e,a,b,c,i,j,f,g,h);

        ROUND160_32_TO_47(c,d,e,a,b,h,i,j,f,g);

        ROUND160_32_TO_47(b,c,d,e,a,g,h,i,j,f);

        ROUND160_32_TO_47(a,b,c,d,e,f,g,h,i,j);

        ROUND160_32_TO_47(e,a,b,c,d,j,f,g,h,i);

    }

    ROUND160_32_TO_47(d,e,a,b,c,i,j,f,g,h);

    SWAP(c,h)



    for (; n < 64 - 1;) {

        ROUND160_48_TO_63(c,d,e,a,b,h,i,j,f,g);

        ROUND160_48_TO_63(b,c,d,e,a,g,h,i,j,f);

        ROUND160_48_TO_63(a,b,c,d,e,f,g,h,i,j);

        ROUND160_48_TO_63(e,a,b,c,d,j,f,g,h,i);

        ROUND160_48_TO_63(d,e,a,b,c,i,j,f,g,h);

    }

    ROUND160_48_TO_63(c,d,e,a,b,h,i,j,f,g);

    SWAP(d,i)



    for (; n < 75;) {

        ROUND160_64_TO_79(b,c,d,e,a,g,h,i,j,f);

        ROUND160_64_TO_79(a,b,c,d,e,f,g,h,i,j);

        ROUND160_64_TO_79(e,a,b,c,d,j,f,g,h,i);

        ROUND160_64_TO_79(d,e,a,b,c,i,j,f,g,h);

        ROUND160_64_TO_79(c,d,e,a,b,h,i,j,f,g);

    }

    ROUND160_64_TO_79(b,c,d,e,a,g,h,i,j,f);

    SWAP(e,j)



    if (ext) {

        state[0] += a; state[1] += b; state[2] += c; state[3] += d; state[4] += e;

        state[5] += f; state[6] += g; state[7] += h; state[8] += i; state[9] += j;

    } else {

        i += c + state[1];

        state[1] = state[2] + d + j;

        state[2] = state[3] + e + f;

        state[3] = state[4] + a + g;

        state[4] = state[0] + b + h;

        state[0] = i;

    }

}

struct vhost_net *vhost_net_init(VhostNetOptions *options)

{

    int r;

    bool backend_kernel = options->backend_type == VHOST_BACKEND_TYPE_KERNEL;

    struct vhost_net *net = g_malloc(sizeof *net);



    if (!options->net_backend) {

        fprintf(stderr, "vhost-net requires net backend to be setup\n");

        goto fail;

    }



    if (backend_kernel) {

        r = vhost_net_get_fd(options->net_backend);

        if (r < 0) {

            goto fail;

        }

        net->dev.backend_features = qemu_has_vnet_hdr(options->net_backend)

            ? 0 : (1ULL << VHOST_NET_F_VIRTIO_NET_HDR);

        net->backend = r;

    } else {

        net->dev.backend_features = 0;

        net->backend = -1;

    }

    net->nc = options->net_backend;



    net->dev.nvqs = 2;

    net->dev.vqs = net->vqs;

    net->dev.vq_index = net->nc->queue_index;



    r = vhost_dev_init(&net->dev, options->opaque,

                       options->backend_type, options->force);

    if (r < 0) {

        goto fail;

    }

    if (backend_kernel) {

        if (!qemu_has_vnet_hdr_len(options->net_backend,

                               sizeof(struct virtio_net_hdr_mrg_rxbuf))) {

            net->dev.features &= ~(1ULL << VIRTIO_NET_F_MRG_RXBUF);

        }

        if (~net->dev.features & net->dev.backend_features) {

            fprintf(stderr, "vhost lacks feature mask %" PRIu64

                   " for backend\n",

                   (uint64_t)(~net->dev.features & net->dev.backend_features));

            vhost_dev_cleanup(&net->dev);

            goto fail;

        }

    }

    /* Set sane init value. Override when guest acks. */

    vhost_net_ack_features(net, 0);

    return net;

fail:

    g_free(net);

    return NULL;

}

void ff_h264_direct_dist_scale_factor(H264Context * const h){

    const int poc = h->cur_pic_ptr->field_poc[h->picture_structure == PICT_BOTTOM_FIELD];

    const int poc1 = h->ref_list[1][0].poc;

    int i, field;



    if (FRAME_MBAFF(h))

        for (field = 0; field < 2; field++){

            const int poc  = h->cur_pic_ptr->field_poc[field];

            const int poc1 = h->ref_list[1][0].field_poc[field];

            for (i = 0; i < 2 * h->ref_count[0]; i++)

                h->dist_scale_factor_field[field][i^field] =

                    get_scale_factor(h, poc, poc1, i+16);

        }



    for (i = 0; i < h->ref_count[0]; i++){

        h->dist_scale_factor[i] = get_scale_factor(h, poc, poc1, i);

    }

}

