static inline void hScale_altivec_real(int16_t *dst, int dstW, uint8_t *src, int srcW, int xInc, int16_t *filter, int16_t *filterPos, int filterSize) {

  register int i;

  int __attribute__ ((aligned (16))) tempo[4];



  if (filterSize % 4) {

    for(i=0; i<dstW; i++) {

      register int j;

      register int srcPos = filterPos[i];

      register int val = 0;

      for(j=0; j<filterSize; j++) {

	val += ((int)src[srcPos + j])*filter[filterSize*i + j];

      }

      dst[i] = av_clip(val>>7, 0, (1<<15)-1);

    }

  }

  else

  switch (filterSize) {

  case 4:

    {

      for(i=0; i<dstW; i++) {

	register int srcPos = filterPos[i];



	vector unsigned char src_v0 = vec_ld(srcPos, src);

	vector unsigned char src_v1, src_vF;

	vector signed short src_v, filter_v;

	vector signed int val_vEven, val_s;

	if ((((int)src + srcPos)% 16) > 12) {

	  src_v1 = vec_ld(srcPos + 16, src);

	}

	src_vF = vec_perm(src_v0, src_v1, vec_lvsl(srcPos, src));



	src_v = // vec_unpackh sign-extends...

	  (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

	// now put our elements in the even slots

	src_v = vec_mergeh(src_v, (vector signed short)vzero);



	filter_v = vec_ld(i << 3, filter);

        // the 3 above is 2 (filterSize == 4) + 1 (sizeof(short) == 2)



        // the neat trick : we only care for half the elements,

        // high or low depending on (i<<3)%16 (it's 0 or 8 here),

        // and we're going to use vec_mule, so we chose

        // carefully how to "unpack" the elements into the even slots

	if ((i << 3) % 16)

	  filter_v = vec_mergel(filter_v,(vector signed short)vzero);

	else

	  filter_v = vec_mergeh(filter_v,(vector signed short)vzero);



	val_vEven = vec_mule(src_v, filter_v);

	val_s = vec_sums(val_vEven, vzero);

	vec_st(val_s, 0, tempo);

	dst[i] = av_clip(tempo[3]>>7, 0, (1<<15)-1);

      }

    }

    break;



  case 8:

    {

      for(i=0; i<dstW; i++) {

	register int srcPos = filterPos[i];



	vector unsigned char src_v0 = vec_ld(srcPos, src);

	vector unsigned char src_v1, src_vF;

	vector signed short src_v, filter_v;

	vector signed int val_v, val_s;

	if ((((int)src + srcPos)% 16) > 8) {

	  src_v1 = vec_ld(srcPos + 16, src);

	}

	src_vF = vec_perm(src_v0, src_v1, vec_lvsl(srcPos, src));



	src_v = // vec_unpackh sign-extends...

	  (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

	filter_v = vec_ld(i << 4, filter);

        // the 4 above is 3 (filterSize == 8) + 1 (sizeof(short) == 2)



	val_v = vec_msums(src_v, filter_v, (vector signed int)vzero);

	val_s = vec_sums(val_v, vzero);

	vec_st(val_s, 0, tempo);

	dst[i] = av_clip(tempo[3]>>7, 0, (1<<15)-1);

      }

    }

    break;



  case 16:

    {

      for(i=0; i<dstW; i++) {

	register int srcPos = filterPos[i];



	vector unsigned char src_v0 = vec_ld(srcPos, src);

	vector unsigned char src_v1 = vec_ld(srcPos + 16, src);

	vector unsigned char src_vF = vec_perm(src_v0, src_v1, vec_lvsl(srcPos, src));



	vector signed short src_vA = // vec_unpackh sign-extends...

	  (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

	vector signed short src_vB = // vec_unpackh sign-extends...

	  (vector signed short)(vec_mergel((vector unsigned char)vzero, src_vF));



	vector signed short filter_v0 = vec_ld(i << 5, filter);

       	vector signed short filter_v1 = vec_ld((i << 5) + 16, filter);

        // the 5 above are 4 (filterSize == 16) + 1 (sizeof(short) == 2)



	vector signed int val_acc = vec_msums(src_vA, filter_v0, (vector signed int)vzero);

	vector signed int val_v = vec_msums(src_vB, filter_v1, val_acc);



	vector signed int val_s = vec_sums(val_v, vzero);



	vec_st(val_s, 0, tempo);

	dst[i] = av_clip(tempo[3]>>7, 0, (1<<15)-1);

      }

    }

    break;



  default:

    {

      for(i=0; i<dstW; i++) {

	register int j;

	register int srcPos = filterPos[i];



        vector signed int val_s, val_v = (vector signed int)vzero;

	vector signed short filter_v0R = vec_ld(i * 2 * filterSize, filter);

        vector unsigned char permF = vec_lvsl((i * 2 * filterSize), filter);



        vector unsigned char src_v0 = vec_ld(srcPos, src);

        vector unsigned char permS = vec_lvsl(srcPos, src);



        for (j = 0 ; j < filterSize - 15; j += 16) {

          vector unsigned char src_v1 = vec_ld(srcPos + j + 16, src);

          vector unsigned char src_vF = vec_perm(src_v0, src_v1, permS);



          vector signed short src_vA = // vec_unpackh sign-extends...

            (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

          vector signed short src_vB = // vec_unpackh sign-extends...

            (vector signed short)(vec_mergel((vector unsigned char)vzero, src_vF));



          vector signed short filter_v1R = vec_ld((i * 2 * filterSize) + (j * 2) + 16, filter);

          vector signed short filter_v2R = vec_ld((i * 2 * filterSize) + (j * 2) + 32, filter);

          vector signed short filter_v0 = vec_perm(filter_v0R, filter_v1R, permF);

          vector signed short filter_v1 = vec_perm(filter_v1R, filter_v2R, permF);



          vector signed int val_acc = vec_msums(src_vA, filter_v0, val_v);

          val_v = vec_msums(src_vB, filter_v1, val_acc);



          filter_v0R = filter_v2R;

          src_v0 = src_v1;

        }



        if (j < (filterSize-7)) {

          // loading src_v0 is useless, it's already done above

          //vector unsigned char src_v0 = vec_ld(srcPos + j, src);

          vector unsigned char src_v1, src_vF;

          vector signed short src_v, filter_v1R, filter_v;

          if ((((int)src + srcPos)% 16) > 8) {

            src_v1 = vec_ld(srcPos + j + 16, src);

          }

          src_vF = vec_perm(src_v0, src_v1, permS);



          src_v = // vec_unpackh sign-extends...

            (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

          // loading filter_v0R is useless, it's already done above

          //vector signed short filter_v0R = vec_ld((i * 2 * filterSize) + j, filter);

          filter_v1R = vec_ld((i * 2 * filterSize) + (j * 2) + 16, filter);

          filter_v = vec_perm(filter_v0R, filter_v1R, permF);



          val_v = vec_msums(src_v, filter_v, val_v);

        }



        val_s = vec_sums(val_v, vzero);



        vec_st(val_s, 0, tempo);

        dst[i] = av_clip(tempo[3]>>7, 0, (1<<15)-1);

      }



    }

  }

}

static uint64_t imx_avic_read(void *opaque,

                             target_phys_addr_t offset, unsigned size)

{

    IMXAVICState *s = (IMXAVICState *)opaque;





    DPRINTF("read(offset = 0x%x)\n", offset >> 2);

    switch (offset >> 2) {

    case 0: /* INTCNTL */

        return s->intcntl;



    case 1: /* Normal Interrupt Mask Register, NIMASK */

        return s->intmask;



    case 2: /* Interrupt Enable Number Register, INTENNUM */

    case 3: /* Interrupt Disable Number Register, INTDISNUM */

        return 0;



    case 4: /* Interrupt Enabled Number Register High */

        return s->enabled >> 32;



    case 5: /* Interrupt Enabled Number Register Low */

        return s->enabled & 0xffffffffULL;



    case 6: /* Interrupt Type Register High */

        return s->is_fiq >> 32;



    case 7: /* Interrupt Type Register Low */

        return s->is_fiq & 0xffffffffULL;



    case 8: /* Normal Interrupt Priority Register 7 */

    case 9: /* Normal Interrupt Priority Register 6 */

    case 10:/* Normal Interrupt Priority Register 5 */

    case 11:/* Normal Interrupt Priority Register 4 */

    case 12:/* Normal Interrupt Priority Register 3 */

    case 13:/* Normal Interrupt Priority Register 2 */

    case 14:/* Normal Interrupt Priority Register 1 */

    case 15:/* Normal Interrupt Priority Register 0 */

        return s->prio[15-(offset>>2)];



    case 16: /* Normal interrupt vector and status register */

    {

        /*

         * This returns the highest priority

         * outstanding interrupt.  Where there is more than

         * one pending IRQ with the same priority,

         * take the highest numbered one.

         */

        uint64_t flags = s->pending & s->enabled & ~s->is_fiq;

        int i;

        int prio = -1;

        int irq = -1;

        for (i = 63; i >= 0; --i) {

            if (flags & (1ULL<<i)) {

                int irq_prio = imx_avic_prio(s, i);

                if (irq_prio > prio) {

                    irq = i;

                    prio = irq_prio;

                }

            }

        }

        if (irq >= 0) {

            imx_avic_set_irq(s, irq, 0);

            return irq << 16 | prio;

        }

        return 0xffffffffULL;

    }

    case 17:/* Fast Interrupt vector and status register */

    {

        uint64_t flags = s->pending & s->enabled & s->is_fiq;

        int i = ctz64(flags);

        if (i < 64) {

            imx_avic_set_irq(opaque, i, 0);

            return i;

        }

        return 0xffffffffULL;

    }

    case 18:/* Interrupt source register high */

        return s->pending >> 32;



    case 19:/* Interrupt source register low */

        return s->pending & 0xffffffffULL;



    case 20:/* Interrupt Force Register high */

    case 21:/* Interrupt Force Register low */

        return 0;



    case 22:/* Normal Interrupt Pending Register High */

        return (s->pending & s->enabled & ~s->is_fiq) >> 32;



    case 23:/* Normal Interrupt Pending Register Low */

        return (s->pending & s->enabled & ~s->is_fiq) & 0xffffffffULL;



    case 24: /* Fast Interrupt Pending Register High  */

        return (s->pending & s->enabled & s->is_fiq) >> 32;



    case 25: /* Fast Interrupt Pending Register Low  */

        return (s->pending & s->enabled & s->is_fiq) & 0xffffffffULL;



    case 0x40:            /* AVIC vector 0, use for WFI WAR */

        return 0x4;



    default:

        IPRINTF("imx_avic_read: Bad offset 0x%x\n", (int)offset);

        return 0;

    }

}

static int kvm_s390_io_adapter_map(S390FLICState *fs, uint32_t id,

                                   uint64_t map_addr, bool do_map)

{

    struct kvm_s390_io_adapter_req req = {

        .id = id,

        .type = do_map ? KVM_S390_IO_ADAPTER_MAP : KVM_S390_IO_ADAPTER_UNMAP,

        .addr = map_addr,

    };

    struct kvm_device_attr attr = {

        .group = KVM_DEV_FLIC_ADAPTER_MODIFY,

        .addr = (uint64_t)&req,

    };

    KVMS390FLICState *flic = KVM_S390_FLIC(fs);

    int r;



    if (!kvm_check_extension(kvm_state, KVM_CAP_IRQ_ROUTING)) {

        /* nothing to do */

        return 0;

    }



    r = ioctl(flic->fd, KVM_SET_DEVICE_ATTR, &attr);

    return r ? -errno : 0;

}

static void pl050_write(void *opaque, hwaddr offset,

                        uint64_t value, unsigned size)

{

    pl050_state *s = (pl050_state *)opaque;

    switch (offset >> 2) {

    case 0: /* KMICR */

        s->cr = value;

        pl050_update(s, s->pending);

        /* ??? Need to implement the enable/disable bit.  */

        break;

    case 2: /* KMIDATA */

        /* ??? This should toggle the TX interrupt line.  */

        /* ??? This means kbd/mouse can block each other.  */

        if (s->is_mouse) {

            ps2_write_mouse(s->dev, value);

        } else {

            ps2_write_keyboard(s->dev, value);

        }

        break;

    case 3: /* KMICLKDIV */

        s->clk = value;

        return;

    default:

        hw_error("pl050_write: Bad offset %x\n", (int)offset);

    }

}

