void ide_init2(IDEBus *bus, DriveInfo *hd0, DriveInfo *hd1,

               qemu_irq irq)

{

    IDEState *s;

    static int drive_serial = 1;

    int i, cylinders, heads, secs;

    uint64_t nb_sectors;



    for(i = 0; i < 2; i++) {

        s = bus->ifs + i;

        s->bus = bus;

        s->unit = i;

        if (i == 0 && hd0)

            s->bs = hd0->bdrv;

        if (i == 1 && hd1)

            s->bs = hd1->bdrv;

        s->io_buffer = qemu_blockalign(s->bs, IDE_DMA_BUF_SECTORS*512 + 4);

        if (s->bs) {

            bdrv_get_geometry(s->bs, &nb_sectors);

            bdrv_guess_geometry(s->bs, &cylinders, &heads, &secs);

            s->cylinders = cylinders;

            s->heads = heads;

            s->sectors = secs;

            s->nb_sectors = nb_sectors;

	    /* The SMART values should be preserved across power cycles

	       but they aren't.  */

	    s->smart_enabled = 1;

	    s->smart_autosave = 1;

	    s->smart_errors = 0;

	    s->smart_selftest_count = 0;

	    s->smart_selftest_data = qemu_blockalign(s->bs, 512);

            if (bdrv_get_type_hint(s->bs) == BDRV_TYPE_CDROM) {

                s->is_cdrom = 1;

		bdrv_set_change_cb(s->bs, cdrom_change_cb, s);

            }

        }

        s->drive_serial = drive_serial++;

        strncpy(s->drive_serial_str, drive_get_serial(s->bs),

                sizeof(s->drive_serial_str));

        if (strlen(s->drive_serial_str) == 0)

            snprintf(s->drive_serial_str, sizeof(s->drive_serial_str),

                    "QM%05d", s->drive_serial);

        s->sector_write_timer = qemu_new_timer(vm_clock,

                                               ide_sector_write_timer_cb, s);

        ide_reset(s);

    }

    bus->irq = irq;

}

static int decompress_i(AVCodecContext *avctx, uint32_t *dst, int linesize)

{

    SCPRContext *s = avctx->priv_data;

    GetByteContext *gb = &s->gb;

    int cx = 0, cx1 = 0, k = 0, clr = 0;

    int run, r, g, b, off, y = 0, x = 0, ret;

    const int cxshift = s->cxshift;

    unsigned lx, ly, ptype;



    reinit_tables(s);

    bytestream2_skip(gb, 2);

    init_rangecoder(&s->rc, gb);



    while (k < avctx->width + 1) {

        ret = decode_unit(s, &s->pixel_model[0][cx + cx1], 400, &r);

        if (ret < 0)

            return ret;



        cx1 = (cx << 6) & 0xFC0;

        cx = r >> cxshift;

        ret = decode_unit(s, &s->pixel_model[1][cx + cx1], 400, &g);

        if (ret < 0)

            return ret;



        cx1 = (cx << 6) & 0xFC0;

        cx = g >> cxshift;

        ret = decode_unit(s, &s->pixel_model[2][cx + cx1], 400, &b);

        if (ret < 0)

            return ret;



        cx1 = (cx << 6) & 0xFC0;

        cx = b >> cxshift;



        ret = decode_value(s, s->run_model[0], 256, 400, &run);

        if (ret < 0)

            return ret;



        clr = (b << 16) + (g << 8) + r;

        k += run;

        while (run-- > 0) {

            dst[y * linesize + x] = clr;

            lx = x;

            ly = y;

            x++;

            if (x >= avctx->width) {

                x = 0;

                y++;

            }

        }

    }

    off = -linesize - 1;

    ptype = 0;



    while (x < avctx->width && y < avctx->height) {

        ret = decode_value(s, s->op_model[ptype], 6, 1000, &ptype);

        if (ret < 0)

            return ret;

        if (ptype == 0) {

            ret = decode_unit(s, &s->pixel_model[0][cx + cx1], 400, &r);

            if (ret < 0)

                return ret;



            cx1 = (cx << 6) & 0xFC0;

            cx = r >> cxshift;

            ret = decode_unit(s, &s->pixel_model[1][cx + cx1], 400, &g);

            if (ret < 0)

                return ret;



            cx1 = (cx << 6) & 0xFC0;

            cx = g >> cxshift;

            ret = decode_unit(s, &s->pixel_model[2][cx + cx1], 400, &b);

            if (ret < 0)

                return ret;



            cx1 = (cx << 6) & 0xFC0;

            cx = b >> cxshift;

            clr = (b << 16) + (g << 8) + r;

        }

        if (ptype > 5)

            return AVERROR_INVALIDDATA;

        ret = decode_value(s, s->run_model[ptype], 256, 400, &run);

        if (ret < 0)

            return ret;



        switch (ptype) {

        case 0:

            while (run-- > 0) {

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        case 1:

            while (run-- > 0) {

                dst[y * linesize + x] = dst[ly * linesize + lx];

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            clr = dst[ly * linesize + lx];

            break;

        case 2:

            while (run-- > 0) {

                clr = dst[y * linesize + x + off + 1];

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        case 4:

            while (run-- > 0) {

                uint8_t *odst = (uint8_t *)dst;

                r = odst[(ly * linesize + lx) * 4] +

                    odst[((y * linesize + x) + off) * 4 + 4] -

                    odst[((y * linesize + x) + off) * 4];

                g = odst[(ly * linesize + lx) * 4 + 1] +

                    odst[((y * linesize + x) + off) * 4 + 5] -

                    odst[((y * linesize + x) + off) * 4 + 1];

                b = odst[(ly * linesize + lx) * 4 + 2] +

                    odst[((y * linesize + x) + off) * 4 + 6] -

                    odst[((y * linesize + x) + off) * 4 + 2];

                clr = ((b & 0xFF) << 16) + ((g & 0xFF) << 8) + (r & 0xFF);

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        case 5:

            while (run-- > 0) {

                clr = dst[y * linesize + x + off];

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        }



        if (avctx->bits_per_coded_sample == 16) {

            cx1 = (clr & 0xFF00) >> 2;

            cx = (clr & 0xFFFFFF) >> 16;

        } else {

            cx1 = (clr & 0xFC00) >> 4;

            cx = (clr & 0xFFFFFF) >> 18;

        }

    }



    return 0;

}

