static int h264_slice_init(H264Context *h, H264SliceContext *sl,

                           const H2645NAL *nal)

{

    int i, j, ret = 0;



    if (h->picture_idr && nal->type != H264_NAL_IDR_SLICE) {

        av_log(h->avctx, AV_LOG_ERROR, "Invalid mix of IDR and non-IDR slices\n");

        return AVERROR_INVALIDDATA;

    }



    av_assert1(h->mb_num == h->mb_width * h->mb_height);

    if (sl->first_mb_addr << FIELD_OR_MBAFF_PICTURE(h) >= h->mb_num ||

        sl->first_mb_addr >= h->mb_num) {

        av_log(h->avctx, AV_LOG_ERROR, "first_mb_in_slice overflow\n");

        return AVERROR_INVALIDDATA;

    }

    sl->resync_mb_x = sl->mb_x =  sl->first_mb_addr % h->mb_width;

    sl->resync_mb_y = sl->mb_y = (sl->first_mb_addr / h->mb_width) <<

                                 FIELD_OR_MBAFF_PICTURE(h);

    if (h->picture_structure == PICT_BOTTOM_FIELD)

        sl->resync_mb_y = sl->mb_y = sl->mb_y + 1;

    av_assert1(sl->mb_y < h->mb_height);



    ret = ff_h264_build_ref_list(h, sl);

    if (ret < 0)

        return ret;



    if (h->ps.pps->weighted_bipred_idc == 2 &&

        sl->slice_type_nos == AV_PICTURE_TYPE_B) {

        implicit_weight_table(h, sl, -1);

        if (FRAME_MBAFF(h)) {

            implicit_weight_table(h, sl, 0);

            implicit_weight_table(h, sl, 1);

        }

    }



    if (sl->slice_type_nos == AV_PICTURE_TYPE_B && !sl->direct_spatial_mv_pred)

        ff_h264_direct_dist_scale_factor(h, sl);

    ff_h264_direct_ref_list_init(h, sl);



    if (h->avctx->skip_loop_filter >= AVDISCARD_ALL ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONKEY &&

         h->nal_unit_type != H264_NAL_IDR_SLICE) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONINTRA &&

         sl->slice_type_nos != AV_PICTURE_TYPE_I) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_BIDIR  &&

         sl->slice_type_nos == AV_PICTURE_TYPE_B) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONREF &&

         nal->ref_idc == 0))

        sl->deblocking_filter = 0;



    if (sl->deblocking_filter == 1 && h->nb_slice_ctx > 1) {

        if (h->avctx->flags2 & AV_CODEC_FLAG2_FAST) {

            /* Cheat slightly for speed:

             * Do not bother to deblock across slices. */

            sl->deblocking_filter = 2;

        } else {

            h->postpone_filter = 1;

        }

    }

    sl->qp_thresh = 15 -

                   FFMIN(sl->slice_alpha_c0_offset, sl->slice_beta_offset) -

                   FFMAX3(0,

                          h->ps.pps->chroma_qp_index_offset[0],

                          h->ps.pps->chroma_qp_index_offset[1]) +

                   6 * (h->ps.sps->bit_depth_luma - 8);



    sl->slice_num       = ++h->current_slice;



    if (sl->slice_num)

        h->slice_row[(sl->slice_num-1)&(MAX_SLICES-1)]= sl->resync_mb_y;

    if (   h->slice_row[sl->slice_num&(MAX_SLICES-1)] + 3 >= sl->resync_mb_y

        && h->slice_row[sl->slice_num&(MAX_SLICES-1)] <= sl->resync_mb_y

        && sl->slice_num >= MAX_SLICES) {

        //in case of ASO this check needs to be updated depending on how we decide to assign slice numbers in this case

        av_log(h->avctx, AV_LOG_WARNING, "Possibly too many slices (%d >= %d), increase MAX_SLICES and recompile if there are artifacts\n", sl->slice_num, MAX_SLICES);

    }



    for (j = 0; j < 2; j++) {

        int id_list[16];

        int *ref2frm = h->ref2frm[sl->slice_num & (MAX_SLICES - 1)][j];

        for (i = 0; i < 16; i++) {

            id_list[i] = 60;

            if (j < sl->list_count && i < sl->ref_count[j] &&

                sl->ref_list[j][i].parent->f->buf[0]) {

                int k;

                AVBuffer *buf = sl->ref_list[j][i].parent->f->buf[0]->buffer;

                for (k = 0; k < h->short_ref_count; k++)

                    if (h->short_ref[k]->f->buf[0]->buffer == buf) {

                        id_list[i] = k;

                        break;

                    }

                for (k = 0; k < h->long_ref_count; k++)

                    if (h->long_ref[k] && h->long_ref[k]->f->buf[0]->buffer == buf) {

                        id_list[i] = h->short_ref_count + k;

                        break;

                    }

            }

        }



        ref2frm[0] =

        ref2frm[1] = -1;

        for (i = 0; i < 16; i++)

            ref2frm[i + 2] = 4 * id_list[i] + (sl->ref_list[j][i].reference & 3);

        ref2frm[18 + 0] =

        ref2frm[18 + 1] = -1;

        for (i = 16; i < 48; i++)

            ref2frm[i + 4] = 4 * id_list[(i - 16) >> 1] +

                             (sl->ref_list[j][i].reference & 3);

    }



    if (h->avctx->debug & FF_DEBUG_PICT_INFO) {

        av_log(h->avctx, AV_LOG_DEBUG,

               "slice:%d %s mb:%d %c%s%s frame:%d poc:%d/%d ref:%d/%d qp:%d loop:%d:%d:%d weight:%d%s %s\n",

               sl->slice_num,

               (h->picture_structure == PICT_FRAME ? "F" : h->picture_structure == PICT_TOP_FIELD ? "T" : "B"),

               sl->mb_y * h->mb_width + sl->mb_x,

               av_get_picture_type_char(sl->slice_type),

               sl->slice_type_fixed ? " fix" : "",

               nal->type == H264_NAL_IDR_SLICE ? " IDR" : "",

               h->poc.frame_num,

               h->cur_pic_ptr->field_poc[0],

               h->cur_pic_ptr->field_poc[1],

               sl->ref_count[0], sl->ref_count[1],

               sl->qscale,

               sl->deblocking_filter,

               sl->slice_alpha_c0_offset, sl->slice_beta_offset,

               sl->pwt.use_weight,

               sl->pwt.use_weight == 1 && sl->pwt.use_weight_chroma ? "c" : "",

               sl->slice_type == AV_PICTURE_TYPE_B ? (sl->direct_spatial_mv_pred ? "SPAT" : "TEMP") : "");

    }



    return 0;

}

static int allocate_buffers(ALACContext *alac)

{

    int ch;

    int buf_size = alac->max_samples_per_frame * sizeof(int32_t);



    for (ch = 0; ch < FFMIN(alac->channels, 2); ch++) {

        FF_ALLOC_OR_GOTO(alac->avctx, alac->predict_error_buffer[ch],

                         buf_size, buf_alloc_fail);



        alac->direct_output = alac->sample_size > 16 && av_sample_fmt_is_planar(alac->avctx->sample_fmt);

        if (!alac->direct_output) {

            FF_ALLOC_OR_GOTO(alac->avctx, alac->output_samples_buffer[ch],

                             buf_size, buf_alloc_fail);

        }



        FF_ALLOC_OR_GOTO(alac->avctx, alac->extra_bits_buffer[ch],

                         buf_size, buf_alloc_fail);

    }

    return 0;

buf_alloc_fail:

    alac_decode_close(alac->avctx);

    return AVERROR(ENOMEM);

}

int qcow2_get_refcount(BlockDriverState *bs, int64_t cluster_index,

                       uint64_t *refcount)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t refcount_table_index, block_index;

    int64_t refcount_block_offset;

    int ret;

    uint16_t *refcount_block;



    refcount_table_index = cluster_index >> s->refcount_block_bits;

    if (refcount_table_index >= s->refcount_table_size) {

        *refcount = 0;

        return 0;

    }

    refcount_block_offset =

        s->refcount_table[refcount_table_index] & REFT_OFFSET_MASK;

    if (!refcount_block_offset) {

        *refcount = 0;

        return 0;

    }



    if (offset_into_cluster(s, refcount_block_offset)) {

        qcow2_signal_corruption(bs, true, -1, -1, "Refblock offset %#" PRIx64

                                " unaligned (reftable index: %#" PRIx64 ")",

                                refcount_block_offset, refcount_table_index);

        return -EIO;

    }



    ret = qcow2_cache_get(bs, s->refcount_block_cache, refcount_block_offset,

        (void**) &refcount_block);

    if (ret < 0) {

        return ret;

    }



    block_index = cluster_index & (s->refcount_block_size - 1);

    *refcount = be16_to_cpu(refcount_block[block_index]);



    ret = qcow2_cache_put(bs, s->refcount_block_cache,

        (void**) &refcount_block);

    if (ret < 0) {

        return ret;

    }



    return 0;

}

static int filter_frame(AVFilterLink *inlink, AVFrame *frame)

{

    AVFilterContext *ctx = inlink->dst;

    APadContext *apad = ctx->priv;



    if (apad->whole_len)

        apad->whole_len -= frame->nb_samples;



    apad->next_pts = frame->pts + av_rescale_q(frame->nb_samples, (AVRational){1, inlink->sample_rate}, inlink->time_base);

    return ff_filter_frame(ctx->outputs[0], frame);

}

static size_t v9fs_packunpack(void *addr, struct iovec *sg, int sg_count,

                              size_t offset, size_t size, int pack)

{

    int i = 0;

    size_t copied = 0;



    for (i = 0; size && i < sg_count; i++) {

        size_t len;

        if (offset >= sg[i].iov_len) {

            /* skip this sg */

            offset -= sg[i].iov_len;

            continue;

        } else {

            len = MIN(sg[i].iov_len - offset, size);

            if (pack) {

                memcpy(sg[i].iov_base + offset, addr, len);

            } else {

                memcpy(addr, sg[i].iov_base + offset, len);

            }

            size -= len;

            copied += len;

            addr += len;

            if (size) {

                offset = 0;

                continue;

            }

        }

    }



    return copied;

}

static int test_vector_fmul_reverse(AVFloatDSPContext *fdsp, AVFloatDSPContext *cdsp,

                                    const float *v1, const float *v2)

{

    LOCAL_ALIGNED(32, float, cdst, [LEN]);

    LOCAL_ALIGNED(32, float, odst, [LEN]);

    int ret;



    cdsp->vector_fmul_reverse(cdst, v1, v2, LEN);

    fdsp->vector_fmul_reverse(odst, v1, v2, LEN);



    if (ret = compare_floats(cdst, odst, LEN, FLT_EPSILON))

        av_log(NULL, AV_LOG_ERROR, "vector_fmul_reverse failed\n");



    return ret;

}

static int hls_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    HLSContext *c = s->priv_data;

    int ret, i, minvariant = -1;



    if (c->first_packet) {

        recheck_discard_flags(s, 1);

        c->first_packet = 0;

    }



start:

    c->end_of_segment = 0;

    for (i = 0; i < c->n_variants; i++) {

        struct variant *var = c->variants[i];

        /* Make sure we've got one buffered packet from each open variant

         * stream */

        if (var->needed && !var->pkt.data) {

            while (1) {

                int64_t ts_diff;

                AVStream *st;

                ret = av_read_frame(var->ctx, &var->pkt);

                if (ret < 0) {

                    if (!var->pb.eof_reached)

                        return ret;


                    break;

                } else {

                    if (c->first_timestamp == AV_NOPTS_VALUE &&

                        var->pkt.dts       != AV_NOPTS_VALUE)

                        c->first_timestamp = av_rescale_q(var->pkt.dts,

                            var->ctx->streams[var->pkt.stream_index]->time_base,

                            AV_TIME_BASE_Q);

                }



                if (c->seek_timestamp == AV_NOPTS_VALUE)

                    break;



                if (var->pkt.dts == AV_NOPTS_VALUE) {

                    c->seek_timestamp = AV_NOPTS_VALUE;

                    break;

                }



                st = var->ctx->streams[var->pkt.stream_index];

                ts_diff = av_rescale_rnd(var->pkt.dts, AV_TIME_BASE,

                                         st->time_base.den, AV_ROUND_DOWN) -

                          c->seek_timestamp;

                if (ts_diff >= 0 && (c->seek_flags  & AVSEEK_FLAG_ANY ||

                                     var->pkt.flags & AV_PKT_FLAG_KEY)) {

                    c->seek_timestamp = AV_NOPTS_VALUE;

                    break;

                }



            }

        }

        /* Check if this stream still is on an earlier segment number, or

         * has the packet with the lowest dts */

        if (var->pkt.data) {

            struct variant *minvar = c->variants[minvariant];

            if (minvariant < 0 || var->cur_seq_no < minvar->cur_seq_no) {

                minvariant = i;

            } else if (var->cur_seq_no == minvar->cur_seq_no) {

                int64_t dts     =    var->pkt.dts;

                int64_t mindts  = minvar->pkt.dts;

                AVStream *st    =    var->ctx->streams[var->pkt.stream_index];

                AVStream *minst = minvar->ctx->streams[minvar->pkt.stream_index];



                if (dts == AV_NOPTS_VALUE) {

                    minvariant = i;

                } else if (mindts != AV_NOPTS_VALUE) {

                    if (st->start_time    != AV_NOPTS_VALUE)

                        dts    -= st->start_time;

                    if (minst->start_time != AV_NOPTS_VALUE)

                        mindts -= minst->start_time;



                    if (av_compare_ts(dts, st->time_base,

                                      mindts, minst->time_base) < 0)

                        minvariant = i;

                }

            }

        }

    }

    if (c->end_of_segment) {

        if (recheck_discard_flags(s, 0))

            goto start;

    }

    /* If we got a packet, return it */

    if (minvariant >= 0) {

        *pkt = c->variants[minvariant]->pkt;

        pkt->stream_index += c->variants[minvariant]->stream_offset;

        reset_packet(&c->variants[minvariant]->pkt);

        return 0;

    }

    return AVERROR_EOF;

}

static int64_t coroutine_fn qcow_co_get_block_status(BlockDriverState *bs,

        int64_t sector_num, int nb_sectors, int *pnum)

{

    BDRVQcowState *s = bs->opaque;

    int index_in_cluster, n;

    uint64_t cluster_offset;



    qemu_co_mutex_lock(&s->lock);

    cluster_offset = get_cluster_offset(bs, sector_num << 9, 0, 0, 0, 0);

    qemu_co_mutex_unlock(&s->lock);

    index_in_cluster = sector_num & (s->cluster_sectors - 1);

    n = s->cluster_sectors - index_in_cluster;

    if (n > nb_sectors)

        n = nb_sectors;

    *pnum = n;

    if (!cluster_offset) {

        return 0;

    }

    if ((cluster_offset & QCOW_OFLAG_COMPRESSED) || s->cipher) {

        return BDRV_BLOCK_DATA;

    }

    cluster_offset |= (index_in_cluster << BDRV_SECTOR_BITS);

    return BDRV_BLOCK_DATA | BDRV_BLOCK_OFFSET_VALID | cluster_offset;

}

static int cfhd_decode(AVCodecContext *avctx, void *data, int *got_frame,

                       AVPacket *avpkt)

{

    CFHDContext *s = avctx->priv_data;

    GetByteContext gb;

    ThreadFrame frame = { .f = data };

    AVFrame *pic = data;

    int ret = 0, i, j, planes, plane, got_buffer = 0;

    int16_t *coeff_data;



    s->coded_format = AV_PIX_FMT_YUV422P10;

    init_frame_defaults(s);

    planes = av_pix_fmt_count_planes(s->coded_format);



    bytestream2_init(&gb, avpkt->data, avpkt->size);



    while (bytestream2_get_bytes_left(&gb) > 4) {

        /* Bit weird but implement the tag parsing as the spec says */

        uint16_t tagu   = bytestream2_get_be16(&gb);

        int16_t tag     = (int16_t)tagu;

        int8_t tag8     = (int8_t)(tagu >> 8);

        uint16_t abstag = abs(tag);

        int8_t abs_tag8 = abs(tag8);

        uint16_t data   = bytestream2_get_be16(&gb);

        if (abs_tag8 >= 0x60 && abs_tag8 <= 0x6f) {

            av_log(avctx, AV_LOG_DEBUG, "large len %x\n", ((tagu & 0xff) << 16) | data);

        } else if (tag == 20) {

            av_log(avctx, AV_LOG_DEBUG, "Width %"PRIu16"\n", data);

            s->coded_width = data;

        } else if (tag == 21) {

            av_log(avctx, AV_LOG_DEBUG, "Height %"PRIu16"\n", data);

            s->coded_height = data;

        } else if (tag == 101) {

            av_log(avctx, AV_LOG_DEBUG, "Bits per component: %"PRIu16"\n", data);

            s->bpc = data;

        } else if (tag == 12) {

            av_log(avctx, AV_LOG_DEBUG, "Channel Count: %"PRIu16"\n", data);

            s->channel_cnt = data;

            if (data > 4) {

                av_log(avctx, AV_LOG_ERROR, "Channel Count of %"PRIu16" is unsupported\n", data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

        } else if (tag == 14) {

            av_log(avctx, AV_LOG_DEBUG, "Subband Count: %"PRIu16"\n", data);

            if (data != SUBBAND_COUNT) {

                av_log(avctx, AV_LOG_ERROR, "Subband Count of %"PRIu16" is unsupported\n", data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

        } else if (tag == 62) {

            s->channel_num = data;

            av_log(avctx, AV_LOG_DEBUG, "Channel number %"PRIu16"\n", data);

            if (s->channel_num >= planes) {

                av_log(avctx, AV_LOG_ERROR, "Invalid channel number\n");

                ret = AVERROR(EINVAL);

                break;

            }

            init_plane_defaults(s);

        } else if (tag == 48) {

            if (s->subband_num != 0 && data == 1)  // hack

                s->level++;

            av_log(avctx, AV_LOG_DEBUG, "Subband number %"PRIu16"\n", data);

            s->subband_num = data;

            if (s->level >= DWT_LEVELS) {

                av_log(avctx, AV_LOG_ERROR, "Invalid level\n");

                ret = AVERROR(EINVAL);

                break;

            }

            if (s->subband_num > 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid subband number\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 51) {

            av_log(avctx, AV_LOG_DEBUG, "Subband number actual %"PRIu16"\n", data);

            s->subband_num_actual = data;

            if (s->subband_num_actual >= 10) {

                av_log(avctx, AV_LOG_ERROR, "Invalid subband number actual\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 35)

            av_log(avctx, AV_LOG_DEBUG, "Lowpass precision bits: %"PRIu16"\n", data);

        else if (tag == 53) {

            s->quantisation = data;

            av_log(avctx, AV_LOG_DEBUG, "Quantisation: %"PRIu16"\n", data);

        } else if (tag == 109) {

            s->prescale_shift[0] = (data >> 0) & 0x7;

            s->prescale_shift[1] = (data >> 3) & 0x7;

            s->prescale_shift[2] = (data >> 6) & 0x7;

            av_log(avctx, AV_LOG_DEBUG, "Prescale shift (VC-5): %x\n", data);

        } else if (tag == 27) {

            s->plane[s->channel_num].band[0][0].width  = data;

            s->plane[s->channel_num].band[0][0].stride = data;

            av_log(avctx, AV_LOG_DEBUG, "Lowpass width %"PRIu16"\n", data);

            if (data < 3 || data > s->plane[s->channel_num].band[0][0].a_width) {

                av_log(avctx, AV_LOG_ERROR, "Invalid lowpass width\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 28) {

            s->plane[s->channel_num].band[0][0].height = data;

            av_log(avctx, AV_LOG_DEBUG, "Lowpass height %"PRIu16"\n", data);

            if (data < 3 || data > s->plane[s->channel_num].band[0][0].height) {

                av_log(avctx, AV_LOG_ERROR, "Invalid lowpass height\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 1)

            av_log(avctx, AV_LOG_DEBUG, "Sample type? %"PRIu16"\n", data);

        else if (tag == 10) {

            if (data != 0) {

                avpriv_report_missing_feature(avctx, "Transform type of %"PRIu16, data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

            av_log(avctx, AV_LOG_DEBUG, "Transform-type? %"PRIu16"\n", data);

        } else if (abstag >= 0x4000 && abstag <= 0x40ff) {

            av_log(avctx, AV_LOG_DEBUG, "Small chunk length %d %s\n", data * 4, tag < 0 ? "optional" : "required");

            bytestream2_skipu(&gb, data * 4);

        } else if (tag == 23) {

            av_log(avctx, AV_LOG_DEBUG, "Skip frame\n");

            avpriv_report_missing_feature(avctx, "Skip frame");

            ret = AVERROR_PATCHWELCOME;

            break;

        } else if (tag == 2) {

            av_log(avctx, AV_LOG_DEBUG, "tag=2 header - skipping %i tag/value pairs\n", data);

            if (data > bytestream2_get_bytes_left(&gb) / 4) {

                av_log(avctx, AV_LOG_ERROR, "too many tag/value pairs (%d)\n", data);

                ret = AVERROR_INVALIDDATA;

                break;

            }

            for (i = 0; i < data; i++) {

                uint16_t tag2 = bytestream2_get_be16(&gb);

                uint16_t val2 = bytestream2_get_be16(&gb);

                av_log(avctx, AV_LOG_DEBUG, "Tag/Value = %x %x\n", tag2, val2);

            }

        } else if (tag == 41) {

            s->plane[s->channel_num].band[s->level][s->subband_num].width  = data;

            s->plane[s->channel_num].band[s->level][s->subband_num].stride = FFALIGN(data, 8);

            av_log(avctx, AV_LOG_DEBUG, "Highpass width %i channel %i level %i subband %i\n", data, s->channel_num, s->level, s->subband_num);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass width\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 42) {

            s->plane[s->channel_num].band[s->level][s->subband_num].height = data;

            av_log(avctx, AV_LOG_DEBUG, "Highpass height %i\n", data);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass height\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 49) {

            s->plane[s->channel_num].band[s->level][s->subband_num].width  = data;

            s->plane[s->channel_num].band[s->level][s->subband_num].stride = FFALIGN(data, 8);

            av_log(avctx, AV_LOG_DEBUG, "Highpass width2 %i\n", data);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass width2\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 50) {

            s->plane[s->channel_num].band[s->level][s->subband_num].height = data;

            av_log(avctx, AV_LOG_DEBUG, "Highpass height2 %i\n", data);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass height2\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 71) {

            s->codebook = data;

            av_log(avctx, AV_LOG_DEBUG, "Codebook %i\n", s->codebook);

        } else if (tag == 72) {

            s->codebook = data;

            av_log(avctx, AV_LOG_DEBUG, "Other codebook? %i\n", s->codebook);

        } else if (tag == 70) {

            av_log(avctx, AV_LOG_DEBUG, "Subsampling or bit-depth flag? %i\n", data);

            s->bpc = data;

            if (!(s->bpc == 10 || s->bpc == 12)) {

                av_log(avctx, AV_LOG_ERROR, "Invalid bits per channel\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 84) {

            av_log(avctx, AV_LOG_DEBUG, "Sample format? %i\n", data);

            if (data == 1)

                s->coded_format = AV_PIX_FMT_YUV422P10;

            else if (data == 3)

                s->coded_format = AV_PIX_FMT_GBRP12;

            else if (data == 4)

                s->coded_format = AV_PIX_FMT_GBRAP12;

            else {

                avpriv_report_missing_feature(avctx, "Sample format of %"PRIu16, data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

            planes = av_pix_fmt_count_planes(s->coded_format);

        } else

            av_log(avctx, AV_LOG_DEBUG,  "Unknown tag %i data %x\n", tag, data);



        /* Some kind of end of header tag */

        if (tag == 4 && data == 0x1a4a && s->coded_width && s->coded_height &&

            s->coded_format != AV_PIX_FMT_NONE) {

            if (s->a_width != s->coded_width || s->a_height != s->coded_height ||

                s->a_format != s->coded_format) {

                free_buffers(avctx);

                if ((ret = alloc_buffers(avctx)) < 0) {

                    free_buffers(avctx);

                    return ret;

                }

            }

            ret = ff_set_dimensions(avctx, s->coded_width, s->coded_height);

            if (ret < 0)

                return ret;

            frame.f->width =

            frame.f->height = 0;



            if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0)

                return ret;



            s->coded_width = 0;

            s->coded_height = 0;

            s->coded_format = AV_PIX_FMT_NONE;

            got_buffer = 1;

        }

        coeff_data = s->plane[s->channel_num].subband[s->subband_num_actual];



        /* Lowpass coefficients */

        if (tag == 4 && data == 0xf0f && s->a_width && s->a_height) {

            int lowpass_height = s->plane[s->channel_num].band[0][0].height;

            int lowpass_width  = s->plane[s->channel_num].band[0][0].width;

            int lowpass_a_height = s->plane[s->channel_num].band[0][0].a_height;

            int lowpass_a_width  = s->plane[s->channel_num].band[0][0].a_width;



            if (!got_buffer) {

                av_log(avctx, AV_LOG_ERROR, "No end of header tag found\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            if (lowpass_height > lowpass_a_height || lowpass_width > lowpass_a_width ||

                lowpass_a_width * lowpass_a_height * sizeof(int16_t) > bytestream2_get_bytes_left(&gb)) {

                av_log(avctx, AV_LOG_ERROR, "Too many lowpass coefficients\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            av_log(avctx, AV_LOG_DEBUG, "Start of lowpass coeffs component %d height:%d, width:%d\n", s->channel_num, lowpass_height, lowpass_width);

            for (i = 0; i < lowpass_height; i++) {

                for (j = 0; j < lowpass_width; j++)

                    coeff_data[j] = bytestream2_get_be16u(&gb);



                coeff_data += lowpass_width;

            }



            /* Align to mod-4 position to continue reading tags */

            bytestream2_seek(&gb, bytestream2_tell(&gb) & 3, SEEK_CUR);



            /* Copy last line of coefficients if odd height */

            if (lowpass_height & 1) {

                memcpy(&coeff_data[lowpass_height * lowpass_width],

                       &coeff_data[(lowpass_height - 1) * lowpass_width],

                       lowpass_width * sizeof(*coeff_data));

            }



            av_log(avctx, AV_LOG_DEBUG, "Lowpass coefficients %d\n", lowpass_width * lowpass_height);

        }



        if (tag == 55 && s->subband_num_actual != 255 && s->a_width && s->a_height) {

            int highpass_height = s->plane[s->channel_num].band[s->level][s->subband_num].height;

            int highpass_width  = s->plane[s->channel_num].band[s->level][s->subband_num].width;

            int highpass_a_width = s->plane[s->channel_num].band[s->level][s->subband_num].a_width;

            int highpass_a_height = s->plane[s->channel_num].band[s->level][s->subband_num].a_height;

            int highpass_stride = s->plane[s->channel_num].band[s->level][s->subband_num].stride;

            int expected = highpass_height * highpass_stride;

            int a_expected = highpass_a_height * highpass_a_width;

            int level, run, coeff;

            int count = 0, bytes;



            if (!got_buffer) {

                av_log(avctx, AV_LOG_ERROR, "No end of header tag found\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            if (highpass_height > highpass_a_height || highpass_width > highpass_a_width || a_expected < expected) {

                av_log(avctx, AV_LOG_ERROR, "Too many highpass coefficients\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            av_log(avctx, AV_LOG_DEBUG, "Start subband coeffs plane %i level %i codebook %i expected %i\n", s->channel_num, s->level, s->codebook, expected);



            init_get_bits(&s->gb, gb.buffer, bytestream2_get_bytes_left(&gb) * 8);

            {

                OPEN_READER(re, &s->gb);

                if (!s->codebook) {

                    while (1) {

                        UPDATE_CACHE(re, &s->gb);

                        GET_RL_VLC(level, run, re, &s->gb, s->table_9_rl_vlc,

                                   VLC_BITS, 3, 1);



                        /* escape */

                        if (level == 64)

                            break;



                        count += run;



                        if (count > expected)

                            break;



                        coeff = dequant_and_decompand(level, s->quantisation);

                        for (i = 0; i < run; i++)

                            *coeff_data++ = coeff;

                    }

                } else {

                    while (1) {

                        UPDATE_CACHE(re, &s->gb);

                        GET_RL_VLC(level, run, re, &s->gb, s->table_18_rl_vlc,

                                   VLC_BITS, 3, 1);



                        /* escape */

                        if (level == 255 && run == 2)

                            break;



                        count += run;



                        if (count > expected)

                            break;



                        coeff = dequant_and_decompand(level, s->quantisation);

                        for (i = 0; i < run; i++)

                            *coeff_data++ = coeff;

                    }

                }

                CLOSE_READER(re, &s->gb);

            }



            if (count > expected) {

                av_log(avctx, AV_LOG_ERROR, "Escape codeword not found, probably corrupt data\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            bytes = FFALIGN(FF_CEIL_RSHIFT(get_bits_count(&s->gb), 3), 4);

            if (bytes > bytestream2_get_bytes_left(&gb)) {

                av_log(avctx, AV_LOG_ERROR, "Bitstream overread error\n");

                ret = AVERROR(EINVAL);

                goto end;

            } else

                bytestream2_seek(&gb, bytes, SEEK_CUR);



            av_log(avctx, AV_LOG_DEBUG, "End subband coeffs %i extra %i\n", count, count - expected);

            s->codebook = 0;



            /* Copy last line of coefficients if odd height */

            if (highpass_height & 1) {

                memcpy(&coeff_data[highpass_height * highpass_stride],

                       &coeff_data[(highpass_height - 1) * highpass_stride],

                       highpass_stride * sizeof(*coeff_data));

            }

        }

    }



    if (!s->a_width || !s->a_height || s->a_format == AV_PIX_FMT_NONE ||

        s->coded_width || s->coded_height || s->coded_format != AV_PIX_FMT_NONE) {

        av_log(avctx, AV_LOG_ERROR, "Invalid dimensions\n");

        ret = AVERROR(EINVAL);

        goto end;

    }



    if (!got_buffer) {

        av_log(avctx, AV_LOG_ERROR, "No end of header tag found\n");

        ret = AVERROR(EINVAL);

        goto end;

    }



    planes = av_pix_fmt_count_planes(avctx->pix_fmt);

    for (plane = 0; plane < planes && !ret; plane++) {

        /* level 1 */

        int lowpass_height  = s->plane[plane].band[0][0].height;

        int lowpass_width   = s->plane[plane].band[0][0].width;

        int highpass_stride = s->plane[plane].band[0][1].stride;

        int act_plane = plane == 1 ? 2 : plane == 2 ? 1 : plane;

        int16_t *low, *high, *output, *dst;



        if (lowpass_height > s->plane[plane].band[0][0].a_height || lowpass_width > s->plane[plane].band[0][0].a_width ||

            !highpass_stride || s->plane[plane].band[0][1].width > s->plane[plane].band[0][1].a_width) {

            av_log(avctx, AV_LOG_ERROR, "Invalid plane dimensions\n");

            ret = AVERROR(EINVAL);

            goto end;

        }



        av_log(avctx, AV_LOG_DEBUG, "Decoding level 1 plane %i %i %i %i\n", plane, lowpass_height, lowpass_width, highpass_stride);



        low    = s->plane[plane].subband[0];

        high   = s->plane[plane].subband[2];

        output = s->plane[plane].l_h[0];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, lowpass_width, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].subband[1];

        high   = s->plane[plane].subband[3];

        output = s->plane[plane].l_h[1];



        for (i = 0; i < lowpass_width; i++) {

            // note the stride of "low" is highpass_stride

            vert_filter(output, lowpass_width, low, highpass_stride, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].l_h[0];

        high   = s->plane[plane].l_h[1];

        output = s->plane[plane].subband[0];

        for (i = 0; i < lowpass_height * 2; i++) {

            horiz_filter(output, low, high, lowpass_width);

            low    += lowpass_width;

            high   += lowpass_width;

            output += lowpass_width * 2;

        }

        if (s->bpc == 12) {

            output = s->plane[plane].subband[0];

            for (i = 0; i < lowpass_height * 2; i++) {

                for (j = 0; j < lowpass_width * 2; j++)

                    output[j] <<= 2;



                output += lowpass_width * 2;

            }

        }



        /* level 2 */

        lowpass_height  = s->plane[plane].band[1][1].height;

        lowpass_width   = s->plane[plane].band[1][1].width;

        highpass_stride = s->plane[plane].band[1][1].stride;



        if (lowpass_height > s->plane[plane].band[1][1].a_height || lowpass_width > s->plane[plane].band[1][1].a_width ||

            !highpass_stride || s->plane[plane].band[1][1].width > s->plane[plane].band[1][1].a_width) {

            av_log(avctx, AV_LOG_ERROR, "Invalid plane dimensions\n");

            ret = AVERROR(EINVAL);

            goto end;

        }



        av_log(avctx, AV_LOG_DEBUG, "Level 2 plane %i %i %i %i\n", plane, lowpass_height, lowpass_width, highpass_stride);



        low    = s->plane[plane].subband[0];

        high   = s->plane[plane].subband[5];

        output = s->plane[plane].l_h[3];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, lowpass_width, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].subband[4];

        high   = s->plane[plane].subband[6];

        output = s->plane[plane].l_h[4];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, highpass_stride, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].l_h[3];

        high   = s->plane[plane].l_h[4];

        output = s->plane[plane].subband[0];

        for (i = 0; i < lowpass_height * 2; i++) {

            horiz_filter(output, low, high, lowpass_width);

            low    += lowpass_width;

            high   += lowpass_width;

            output += lowpass_width * 2;

        }



        output = s->plane[plane].subband[0];

        for (i = 0; i < lowpass_height * 2; i++) {

            for (j = 0; j < lowpass_width * 2; j++)

                output[j] <<= 2;



            output += lowpass_width * 2;

        }



        /* level 3 */

        lowpass_height  = s->plane[plane].band[2][1].height;

        lowpass_width   = s->plane[plane].band[2][1].width;

        highpass_stride = s->plane[plane].band[2][1].stride;



        if (lowpass_height > s->plane[plane].band[2][1].a_height || lowpass_width > s->plane[plane].band[2][1].a_width ||

            !highpass_stride || s->plane[plane].band[2][1].width > s->plane[plane].band[2][1].a_width) {

            av_log(avctx, AV_LOG_ERROR, "Invalid plane dimensions\n");

            ret = AVERROR(EINVAL);

            goto end;

        }



        av_log(avctx, AV_LOG_DEBUG, "Level 3 plane %i %i %i %i\n", plane, lowpass_height, lowpass_width, highpass_stride);



        low    = s->plane[plane].subband[0];

        high   = s->plane[plane].subband[8];

        output = s->plane[plane].l_h[6];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, lowpass_width, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].subband[7];

        high   = s->plane[plane].subband[9];

        output = s->plane[plane].l_h[7];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, highpass_stride, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        dst = (int16_t *)pic->data[act_plane];

        low  = s->plane[plane].l_h[6];

        high = s->plane[plane].l_h[7];

        for (i = 0; i < lowpass_height * 2; i++) {

            horiz_filter_clip(dst, low, high, lowpass_width, s->bpc);

            low  += lowpass_width;

            high += lowpass_width;

            dst  += pic->linesize[act_plane] / 2;

        }

    }





end:

    if (ret < 0)

        return ret;



    *got_frame = 1;

    return avpkt->size;

}

static int decode_b_picture_secondary_header(VC9Context *v)

{

    GetBitContext *gb = &v->s.gb;

    int status;



    bitplane_decoding(&v->skip_mb_plane, v);

    if (status < 0) return -1;

#if TRACE

    if (v->mv_mode == MV_PMODE_MIXED_MV)

    {

        status = bitplane_decoding(&v->mv_type_mb_plane, v);

        if (status < 0)

            return -1;

#if TRACE

        av_log(v->s.avctx, AV_LOG_DEBUG, "MB MV Type plane encoding: "

               "Imode: %i, Invert: %i\n", status>>1, status&1);

#endif

    }



    //bitplane

    status = bitplane_decoding(&v->direct_mb_plane, v);

    if (status < 0) return -1;

#if TRACE

    av_log(v->s.avctx, AV_LOG_DEBUG, "MB Direct plane encoding: "

           "Imode: %i, Invert: %i\n", status>>1, status&1);

#endif



    av_log(v->s.avctx, AV_LOG_DEBUG, "Skip MB plane encoding: "

           "Imode: %i, Invert: %i\n", status>>1, status&1);

#endif



    /* FIXME: what is actually chosen for B frames ? */

    v->s.mv_table_index = get_bits(gb, 2); //but using vc9_ tables

    v->cbpcy_vlc = &vc9_cbpcy_p_vlc[get_bits(gb, 2)];



    if (v->dquant)

    {

        vop_dquant_decoding(v);

    }



    if (v->vstransform)

    {

        v->ttmbf = get_bits(gb, 1);

        if (v->ttmbf)

        {

            v->ttfrm = get_bits(gb, 2);

            av_log(v->s.avctx, AV_LOG_INFO, "Transform used: %ix%i\n",

                   (v->ttfrm & 2) ? 4 : 8, (v->ttfrm & 1) ? 4 : 8);

        }

    }

    /* Epilog (AC/DC syntax) should be done in caller */

    return 0;

}

static void lan9118_writel(void *opaque, hwaddr offset,

                           uint64_t val, unsigned size)

{

    lan9118_state *s = (lan9118_state *)opaque;

    offset &= 0xff;



    //DPRINTF("Write reg 0x%02x = 0x%08x\n", (int)offset, val);

    if (offset >= 0x20 && offset < 0x40) {

        /* TX FIFO */

        tx_fifo_push(s, val);

        return;

    }

    switch (offset) {

    case CSR_IRQ_CFG:

        /* TODO: Implement interrupt deassertion intervals.  */

        val &= (IRQ_EN | IRQ_POL | IRQ_TYPE);

        s->irq_cfg = (s->irq_cfg & IRQ_INT) | val;

        break;

    case CSR_INT_STS:

        s->int_sts &= ~val;

        break;

    case CSR_INT_EN:

        s->int_en = val & ~RESERVED_INT;

        s->int_sts |= val & SW_INT;

        break;

    case CSR_FIFO_INT:

        DPRINTF("FIFO INT levels %08x\n", val);

        s->fifo_int = val;

        break;

    case CSR_RX_CFG:

        if (val & 0x8000) {

            /* RX_DUMP */

            s->rx_fifo_used = 0;

            s->rx_status_fifo_used = 0;

            s->rx_packet_size_tail = s->rx_packet_size_head;

            s->rx_packet_size[s->rx_packet_size_head] = 0;

        }

        s->rx_cfg = val & 0xcfff1ff0;

        break;

    case CSR_TX_CFG:

        if (val & 0x8000) {

            s->tx_status_fifo_used = 0;

        }

        if (val & 0x4000) {

            s->txp->state = TX_IDLE;

            s->txp->fifo_used = 0;

            s->txp->cmd_a = 0xffffffff;

        }

        s->tx_cfg = val & 6;

        break;

    case CSR_HW_CFG:

        if (val & 1) {

            /* SRST */

            lan9118_reset(DEVICE(s));

        } else {

            s->hw_cfg = (val & 0x003f300) | (s->hw_cfg & 0x4);

        }

        break;

    case CSR_RX_DP_CTRL:

        if (val & 0x80000000) {

            /* Skip forward to next packet.  */

            s->rxp_pad = 0;

            s->rxp_offset = 0;

            if (s->rxp_size == 0) {

                /* Pop a word to start the next packet.  */

                rx_fifo_pop(s);

                s->rxp_pad = 0;

                s->rxp_offset = 0;

            }

            s->rx_fifo_head += s->rxp_size;

            if (s->rx_fifo_head >= s->rx_fifo_size) {

                s->rx_fifo_head -= s->rx_fifo_size;

            }

        }

        break;

    case CSR_PMT_CTRL:

        if (val & 0x400) {

            phy_reset(s);

        }

        s->pmt_ctrl &= ~0x34e;

        s->pmt_ctrl |= (val & 0x34e);

        break;

    case CSR_GPIO_CFG:

        /* Probably just enabling LEDs.  */

        s->gpio_cfg = val & 0x7777071f;

        break;

    case CSR_GPT_CFG:

        if ((s->gpt_cfg ^ val) & GPT_TIMER_EN) {

            if (val & GPT_TIMER_EN) {

                ptimer_set_count(s->timer, val & 0xffff);

                ptimer_run(s->timer, 0);

            } else {

                ptimer_stop(s->timer);

                ptimer_set_count(s->timer, 0xffff);

            }

        }

        s->gpt_cfg = val & (GPT_TIMER_EN | 0xffff);

        break;

    case CSR_WORD_SWAP:

        /* Ignored because we're in 32-bit mode.  */

        s->word_swap = val;

        break;

    case CSR_MAC_CSR_CMD:

        s->mac_cmd = val & 0x4000000f;

        if (val & 0x80000000) {

            if (val & 0x40000000) {

                s->mac_data = do_mac_read(s, val & 0xf);

                DPRINTF("MAC read %d = 0x%08x\n", val & 0xf, s->mac_data);

            } else {

                DPRINTF("MAC write %d = 0x%08x\n", val & 0xf, s->mac_data);

                do_mac_write(s, val & 0xf, s->mac_data);

            }

        }

        break;

    case CSR_MAC_CSR_DATA:

        s->mac_data = val;

        break;

    case CSR_AFC_CFG:

        s->afc_cfg = val & 0x00ffffff;

        break;

    case CSR_E2P_CMD:

        lan9118_eeprom_cmd(s, (val >> 28) & 7, val & 0x7f);

        break;

    case CSR_E2P_DATA:

        s->e2p_data = val & 0xff;

        break;



    default:

        hw_error("lan9118_write: Bad reg 0x%x = %x\n", (int)offset, (int)val);

        break;

    }

    lan9118_update(s);

}

