static void dump_sprs (CPUPPCState *env)

{

    ppc_spr_t *spr;

    uint32_t pvr = env->spr[SPR_PVR];

    uint32_t sr, sw, ur, uw;

    int i, j, n;



    printf("* SPRs for PVR=%08x\n", pvr);

    for (i = 0; i < 32; i++) {

        for (j = 0; j < 32; j++) {

            n = (i << 5) | j;

            spr = &env->spr_cb[n];

#if !defined(CONFIG_USER_ONLY)

            sw = spr->oea_write != NULL && spr->oea_write != SPR_NOACCESS;

            sr = spr->oea_read != NULL && spr->oea_read != SPR_NOACCESS;

#else

            sw = 0;

            sr = 0;

#endif

            uw = spr->uea_write != NULL && spr->uea_write != SPR_NOACCESS;

            ur = spr->uea_read != NULL && spr->uea_read != SPR_NOACCESS;

            if (sw || sr || uw || ur) {

                printf("%4d (%03x) %8s s%c%c u%c%c\n",

                       (i << 5) | j, (i << 5) | j, spr->name,

                       sw ? 'w' : '-', sr ? 'r' : '-',

                       uw ? 'w' : '-', ur ? 'r' : '-');

            }

        }

    }

    fflush(stdout);

    fflush(stderr);

}

static void lm32_uclinux_init(QEMUMachineInitArgs *args)

{

    const char *cpu_model = args->cpu_model;

    const char *kernel_filename = args->kernel_filename;

    const char *kernel_cmdline = args->kernel_cmdline;

    const char *initrd_filename = args->initrd_filename;

    LM32CPU *cpu;

    CPULM32State *env;

    DriveInfo *dinfo;

    MemoryRegion *address_space_mem =  get_system_memory();

    MemoryRegion *phys_ram = g_new(MemoryRegion, 1);

    qemu_irq *cpu_irq, irq[32];

    HWSetup *hw;

    ResetInfo *reset_info;

    int i;



    /* memory map */

    target_phys_addr_t flash_base   = 0x04000000;

    size_t flash_sector_size        = 256 * 1024;

    size_t flash_size               = 32 * 1024 * 1024;

    target_phys_addr_t ram_base     = 0x08000000;

    size_t ram_size                 = 64 * 1024 * 1024;

    target_phys_addr_t uart0_base   = 0x80000000;

    target_phys_addr_t timer0_base  = 0x80002000;

    target_phys_addr_t timer1_base  = 0x80010000;

    target_phys_addr_t timer2_base  = 0x80012000;

    int uart0_irq                   = 0;

    int timer0_irq                  = 1;

    int timer1_irq                  = 20;

    int timer2_irq                  = 21;

    target_phys_addr_t hwsetup_base = 0x0bffe000;

    target_phys_addr_t cmdline_base = 0x0bfff000;

    target_phys_addr_t initrd_base  = 0x08400000;

    size_t initrd_max               = 0x01000000;



    reset_info = g_malloc0(sizeof(ResetInfo));



    if (cpu_model == NULL) {

        cpu_model = "lm32-full";

    }

    cpu = cpu_lm32_init(cpu_model);

    env = &cpu->env;

    reset_info->cpu = cpu;



    reset_info->flash_base = flash_base;



    memory_region_init_ram(phys_ram, "lm32_uclinux.sdram", ram_size);

    vmstate_register_ram_global(phys_ram);

    memory_region_add_subregion(address_space_mem, ram_base, phys_ram);



    dinfo = drive_get(IF_PFLASH, 0, 0);

    /* Spansion S29NS128P */

    pflash_cfi02_register(flash_base, NULL, "lm32_uclinux.flash", flash_size,

                          dinfo ? dinfo->bdrv : NULL, flash_sector_size,

                          flash_size / flash_sector_size, 1, 2,

                          0x01, 0x7e, 0x43, 0x00, 0x555, 0x2aa, 1);



    /* create irq lines */

    cpu_irq = qemu_allocate_irqs(cpu_irq_handler, env, 1);

    env->pic_state = lm32_pic_init(*cpu_irq);

    for (i = 0; i < 32; i++) {

        irq[i] = qdev_get_gpio_in(env->pic_state, i);

    }



    sysbus_create_simple("lm32-uart", uart0_base, irq[uart0_irq]);

    sysbus_create_simple("lm32-timer", timer0_base, irq[timer0_irq]);

    sysbus_create_simple("lm32-timer", timer1_base, irq[timer1_irq]);

    sysbus_create_simple("lm32-timer", timer2_base, irq[timer2_irq]);



    /* make sure juart isn't the first chardev */

    env->juart_state = lm32_juart_init();



    reset_info->bootstrap_pc = flash_base;



    if (kernel_filename) {

        uint64_t entry;

        int kernel_size;



        kernel_size = load_elf(kernel_filename, NULL, NULL, &entry, NULL, NULL,

                               1, ELF_MACHINE, 0);

        reset_info->bootstrap_pc = entry;



        if (kernel_size < 0) {

            kernel_size = load_image_targphys(kernel_filename, ram_base,

                                              ram_size);

            reset_info->bootstrap_pc = ram_base;

        }



        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    kernel_filename);

            exit(1);

        }

    }



    /* generate a rom with the hardware description */

    hw = hwsetup_init();

    hwsetup_add_cpu(hw, "LM32", 75000000);

    hwsetup_add_flash(hw, "flash", flash_base, flash_size);

    hwsetup_add_ddr_sdram(hw, "ddr_sdram", ram_base, ram_size);

    hwsetup_add_timer(hw, "timer0", timer0_base, timer0_irq);

    hwsetup_add_timer(hw, "timer1_dev_only", timer1_base, timer1_irq);

    hwsetup_add_timer(hw, "timer2_dev_only", timer2_base, timer2_irq);

    hwsetup_add_uart(hw, "uart", uart0_base, uart0_irq);

    hwsetup_add_trailer(hw);

    hwsetup_create_rom(hw, hwsetup_base);

    hwsetup_free(hw);



    reset_info->hwsetup_base = hwsetup_base;



    if (kernel_cmdline && strlen(kernel_cmdline)) {

        pstrcpy_targphys("cmdline", cmdline_base, TARGET_PAGE_SIZE,

                kernel_cmdline);

        reset_info->cmdline_base = cmdline_base;

    }



    if (initrd_filename) {

        size_t initrd_size;

        initrd_size = load_image_targphys(initrd_filename, initrd_base,

                initrd_max);

        reset_info->initrd_base = initrd_base;

        reset_info->initrd_size = initrd_size;

    }



    qemu_register_reset(main_cpu_reset, reset_info);

}

static void qcow2_aio_read_cb(void *opaque, int ret)

{

    QCowAIOCB *acb = opaque;

    BlockDriverState *bs = acb->common.bs;

    BDRVQcowState *s = bs->opaque;

    int index_in_cluster, n1;



    acb->hd_aiocb = NULL;

    if (ret < 0)

        goto done;



    /* post process the read buffer */

    if (!acb->cluster_offset) {

        /* nothing to do */

    } else if (acb->cluster_offset & QCOW_OFLAG_COMPRESSED) {

        /* nothing to do */

    } else {

        if (s->crypt_method) {

            qcow2_encrypt_sectors(s, acb->sector_num,  acb->cluster_data,

                acb->cluster_data, acb->cur_nr_sectors, 0, &s->aes_decrypt_key);

            qemu_iovec_reset(&acb->hd_qiov);

            qemu_iovec_copy(&acb->hd_qiov, acb->qiov, acb->bytes_done,

                acb->cur_nr_sectors * 512);

            qemu_iovec_from_buffer(&acb->hd_qiov, acb->cluster_data,

                512 * acb->cur_nr_sectors);

        }

    }



    acb->remaining_sectors -= acb->cur_nr_sectors;

    acb->sector_num += acb->cur_nr_sectors;

    acb->bytes_done += acb->cur_nr_sectors * 512;



    if (acb->remaining_sectors == 0) {

        /* request completed */

        ret = 0;

        goto done;

    }



    /* prepare next AIO request */

    acb->cur_nr_sectors = acb->remaining_sectors;

    if (s->crypt_method) {

        acb->cur_nr_sectors = MIN(acb->cur_nr_sectors,

            QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors);

    }



    ret = qcow2_get_cluster_offset(bs, acb->sector_num << 9,

        &acb->cur_nr_sectors, &acb->cluster_offset);

    if (ret < 0) {

        goto done;

    }



    index_in_cluster = acb->sector_num & (s->cluster_sectors - 1);



    qemu_iovec_reset(&acb->hd_qiov);

    qemu_iovec_copy(&acb->hd_qiov, acb->qiov, acb->bytes_done,

        acb->cur_nr_sectors * 512);



    if (!acb->cluster_offset) {



        if (bs->backing_hd) {

            /* read from the base image */

            n1 = qcow2_backing_read1(bs->backing_hd, &acb->hd_qiov,

                acb->sector_num, acb->cur_nr_sectors);

            if (n1 > 0) {

                BLKDBG_EVENT(bs->file, BLKDBG_READ_BACKING_AIO);

                acb->hd_aiocb = bdrv_aio_readv(bs->backing_hd, acb->sector_num,

                                    &acb->hd_qiov, acb->cur_nr_sectors,

				    qcow2_aio_read_cb, acb);

                if (acb->hd_aiocb == NULL)

                    goto done;

            } else {

                ret = qcow2_schedule_bh(qcow2_aio_read_bh, acb);

                if (ret < 0)

                    goto done;

            }

        } else {

            /* Note: in this case, no need to wait */

            qemu_iovec_memset(&acb->hd_qiov, 0, 512 * acb->cur_nr_sectors);

            ret = qcow2_schedule_bh(qcow2_aio_read_bh, acb);

            if (ret < 0)

                goto done;

        }

    } else if (acb->cluster_offset & QCOW_OFLAG_COMPRESSED) {

        /* add AIO support for compressed blocks ? */

        if (qcow2_decompress_cluster(bs, acb->cluster_offset) < 0)

            goto done;



        qemu_iovec_from_buffer(&acb->hd_qiov,

            s->cluster_cache + index_in_cluster * 512,

            512 * acb->cur_nr_sectors);



        ret = qcow2_schedule_bh(qcow2_aio_read_bh, acb);

        if (ret < 0)

            goto done;

    } else {

        if ((acb->cluster_offset & 511) != 0) {

            ret = -EIO;

            goto done;

        }



        if (s->crypt_method) {

            /*

             * For encrypted images, read everything into a temporary

             * contiguous buffer on which the AES functions can work.

             */

            if (!acb->cluster_data) {

                acb->cluster_data =

                    qemu_mallocz(QCOW_MAX_CRYPT_CLUSTERS * s->cluster_size);

            }



            assert(acb->cur_nr_sectors <=

                QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors);

            qemu_iovec_reset(&acb->hd_qiov);

            qemu_iovec_add(&acb->hd_qiov, acb->cluster_data,

                512 * acb->cur_nr_sectors);

        }



        BLKDBG_EVENT(bs->file, BLKDBG_READ_AIO);

        acb->hd_aiocb = bdrv_aio_readv(bs->file,

                            (acb->cluster_offset >> 9) + index_in_cluster,

                            &acb->hd_qiov, acb->cur_nr_sectors,

                            qcow2_aio_read_cb, acb);

        if (acb->hd_aiocb == NULL) {

            ret = -EIO;

            goto done;

        }

    }



    return;

done:

    acb->common.cb(acb->common.opaque, ret);

    qemu_iovec_destroy(&acb->hd_qiov);

    qemu_aio_release(acb);

}

