static int scan_mmco_reset(AVCodecParserContext *s)

{

    H264ParseContext *p = s->priv_data;

    H264Context      *h = &p->h;

    H264SliceContext *sl = &h->slice_ctx[0];



    sl->slice_type_nos = s->pict_type & 3;



    if (h->pps.redundant_pic_cnt_present)

        get_ue_golomb(&sl->gb); // redundant_pic_count



    if (ff_set_ref_count(h, sl) < 0)

        return AVERROR_INVALIDDATA;



    if (sl->slice_type_nos != AV_PICTURE_TYPE_I) {

        int list;

        for (list = 0; list < sl->list_count; list++) {

            if (get_bits1(&sl->gb)) {

                int index;

                for (index = 0; ; index++) {

                    unsigned int reordering_of_pic_nums_idc = get_ue_golomb_31(&sl->gb);



                    if (reordering_of_pic_nums_idc < 3)

                        get_ue_golomb(&sl->gb);

                    else if (reordering_of_pic_nums_idc > 3) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "illegal reordering_of_pic_nums_idc %d\n",

                               reordering_of_pic_nums_idc);

                        return AVERROR_INVALIDDATA;

                    } else

                        break;



                    if (index >= sl->ref_count[list]) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "reference count %d overflow\n", index);

                        return AVERROR_INVALIDDATA;

                    }

                }

            }

        }

    }



    if ((h->pps.weighted_pred && sl->slice_type_nos == AV_PICTURE_TYPE_P) ||

        (h->pps.weighted_bipred_idc == 1 && sl->slice_type_nos == AV_PICTURE_TYPE_B))

        ff_pred_weight_table(h, sl);



    if (get_bits1(&sl->gb)) { // adaptive_ref_pic_marking_mode_flag

        int i;

        for (i = 0; i < MAX_MMCO_COUNT; i++) {

            MMCOOpcode opcode = get_ue_golomb_31(&sl->gb);

            if (opcode > (unsigned) MMCO_LONG) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "illegal memory management control operation %d\n",

                       opcode);

                return AVERROR_INVALIDDATA;

            }

            if (opcode == MMCO_END)

               return 0;

            else if (opcode == MMCO_RESET)

                return 1;



            if (opcode == MMCO_SHORT2UNUSED || opcode == MMCO_SHORT2LONG)

                get_ue_golomb(&sl->gb);

            if (opcode == MMCO_SHORT2LONG || opcode == MMCO_LONG2UNUSED ||

                opcode == MMCO_LONG || opcode == MMCO_SET_MAX_LONG)

                get_ue_golomb_31(&sl->gb);

        }

    }



    return 0;

}

static void dec_modu(DisasContext *dc)

{

    int l1;



    LOG_DIS("modu r%d, r%d, %d\n", dc->r2, dc->r0, dc->r1);



    if (!(dc->features & LM32_FEATURE_DIVIDE)) {

        qemu_log_mask(LOG_GUEST_ERROR, "hardware divider is not available\n");

        t_gen_illegal_insn(dc);

        return;

    }



    l1 = gen_new_label();

    tcg_gen_brcondi_tl(TCG_COND_NE, cpu_R[dc->r1], 0, l1);

    tcg_gen_movi_tl(cpu_pc, dc->pc);

    t_gen_raise_exception(dc, EXCP_DIVIDE_BY_ZERO);

    gen_set_label(l1);

    tcg_gen_remu_tl(cpu_R[dc->r2], cpu_R[dc->r0], cpu_R[dc->r1]);

}

static int vmdk_add_extent(BlockDriverState *bs,

                           BlockDriverState *file, bool flat, int64_t sectors,

                           int64_t l1_offset, int64_t l1_backup_offset,

                           uint32_t l1_size,

                           int l2_size, uint64_t cluster_sectors,

                           VmdkExtent **new_extent,

                           Error **errp)

{

    VmdkExtent *extent;

    BDRVVmdkState *s = bs->opaque;



    if (cluster_sectors > 0x200000) {

        /* 0x200000 * 512Bytes = 1GB for one cluster is unrealistic */

        error_setg(errp, "Invalid granularity, image may be corrupt");

        return -EFBIG;

    }

    if (l1_size > 512 * 1024 * 1024) {

        /* Although with big capacity and small l1_entry_sectors, we can get a

         * big l1_size, we don't want unbounded value to allocate the table.

         * Limit it to 512M, which is 16PB for default cluster and L2 table

         * size */

        error_setg(errp, "L1 size too big");

        return -EFBIG;

    }



    s->extents = g_realloc(s->extents,

                              (s->num_extents + 1) * sizeof(VmdkExtent));

    extent = &s->extents[s->num_extents];

    s->num_extents++;



    memset(extent, 0, sizeof(VmdkExtent));

    extent->file = file;

    extent->flat = flat;

    extent->sectors = sectors;

    extent->l1_table_offset = l1_offset;

    extent->l1_backup_table_offset = l1_backup_offset;

    extent->l1_size = l1_size;

    extent->l1_entry_sectors = l2_size * cluster_sectors;

    extent->l2_size = l2_size;

    extent->cluster_sectors = flat ? sectors : cluster_sectors;



    if (!flat) {

        bs->bl.write_zeroes_alignment =

            MAX(bs->bl.write_zeroes_alignment, cluster_sectors);

    }

    if (s->num_extents > 1) {

        extent->end_sector = (*(extent - 1)).end_sector + extent->sectors;

    } else {

        extent->end_sector = extent->sectors;

    }

    bs->total_sectors = extent->end_sector;

    if (new_extent) {

        *new_extent = extent;

    }

    return 0;

}

static int escape(char **dst, const char *src, const char *special_chars,

                  enum EscapeMode mode)

{

    AVBPrint dstbuf;



    av_bprint_init(&dstbuf, 1, AV_BPRINT_SIZE_UNLIMITED);



    switch (mode) {

    case ESCAPE_MODE_FULL:

    case ESCAPE_MODE_LAZY:

        /* \-escape characters */



        if (mode == ESCAPE_MODE_LAZY && strchr(WHITESPACES, *src))

            av_bprintf(&dstbuf, "\\%c", *src++);



        for (; *src; src++) {

            if ((special_chars && strchr(special_chars, *src)) ||

                strchr("'\\", *src) ||

                (mode == ESCAPE_MODE_FULL && strchr(WHITESPACES, *src)))

                av_bprintf(&dstbuf, "\\%c", *src);

            else

                av_bprint_chars(&dstbuf, *src, 1);

        }



        if (mode == ESCAPE_MODE_LAZY && strchr(WHITESPACES, dstbuf.str[dstbuf.len-1])) {

            char c = dstbuf.str[dstbuf.len-1];

            dstbuf.str[dstbuf.len-1] = '\\';

            av_bprint_chars(&dstbuf, c, 1);

        }

        break;



    case ESCAPE_MODE_QUOTE:

        /* enclose between '' the string */

        av_bprint_chars(&dstbuf, '\'', 1);

        for (; *src; src++) {

            if (*src == '\'')

                av_bprintf(&dstbuf, "'\\''");

            else

                av_bprint_chars(&dstbuf, *src, 1);

        }

        av_bprint_chars(&dstbuf, '\'', 1);

        break;



    default:

        /* unknown escape mode */

        return AVERROR(EINVAL);

    }



    if (!av_bprint_is_complete(&dstbuf)) {

        av_bprint_finalize(&dstbuf, NULL);

        return AVERROR(ENOMEM);

    } else {

        av_bprint_finalize(&dstbuf, dst);

        return 0;

    }

}

void ff_snow_pred_block(SnowContext *s, uint8_t *dst, uint8_t *tmp, int stride, int sx, int sy, int b_w, int b_h, BlockNode *block, int plane_index, int w, int h){

    if(block->type & BLOCK_INTRA){

        int x, y;

        const unsigned color  = block->color[plane_index];

        const unsigned color4 = color*0x01010101;

        if(b_w==32){

            for(y=0; y < b_h; y++){

                *(uint32_t*)&dst[0 + y*stride]= color4;

                *(uint32_t*)&dst[4 + y*stride]= color4;

                *(uint32_t*)&dst[8 + y*stride]= color4;

                *(uint32_t*)&dst[12+ y*stride]= color4;

                *(uint32_t*)&dst[16+ y*stride]= color4;

                *(uint32_t*)&dst[20+ y*stride]= color4;

                *(uint32_t*)&dst[24+ y*stride]= color4;

                *(uint32_t*)&dst[28+ y*stride]= color4;

            }

        }else if(b_w==16){

            for(y=0; y < b_h; y++){

                *(uint32_t*)&dst[0 + y*stride]= color4;

                *(uint32_t*)&dst[4 + y*stride]= color4;

                *(uint32_t*)&dst[8 + y*stride]= color4;

                *(uint32_t*)&dst[12+ y*stride]= color4;

            }

        }else if(b_w==8){

            for(y=0; y < b_h; y++){

                *(uint32_t*)&dst[0 + y*stride]= color4;

                *(uint32_t*)&dst[4 + y*stride]= color4;

            }

        }else if(b_w==4){

            for(y=0; y < b_h; y++){

                *(uint32_t*)&dst[0 + y*stride]= color4;

            }

        }else{

            for(y=0; y < b_h; y++){

                for(x=0; x < b_w; x++){

                    dst[x + y*stride]= color;

                }

            }

        }

    }else{

        uint8_t *src= s->last_picture[block->ref]->data[plane_index];

        const int scale= plane_index ?  (2*s->mv_scale)>>s->chroma_h_shift : 2*s->mv_scale;

        int mx= block->mx*scale;

        int my= block->my*scale;

        const int dx= mx&15;

        const int dy= my&15;

        const int tab_index= 3 - (b_w>>2) + (b_w>>4);

        sx += (mx>>4) - (HTAPS_MAX/2-1);

        sy += (my>>4) - (HTAPS_MAX/2-1);

        src += sx + sy*stride;

        if(   (unsigned)sx >= FFMAX(w - b_w - (HTAPS_MAX-2), 0)

           || (unsigned)sy >= FFMAX(h - b_h - (HTAPS_MAX-2), 0)){

            s->vdsp.emulated_edge_mc(tmp + MB_SIZE, src, stride, b_w+HTAPS_MAX-1, b_h+HTAPS_MAX-1, sx, sy, w, h);

            src= tmp + MB_SIZE;

        }



        av_assert2(s->chroma_h_shift == s->chroma_v_shift); // only one mv_scale



        av_assert2(b_w>1 && b_h>1);

        av_assert2((tab_index>=0 && tab_index<4) || b_w==32);

        if((dx&3) || (dy&3) || !(b_w == b_h || 2*b_w == b_h || b_w == 2*b_h) || (b_w&(b_w-1)) || !s->plane[plane_index].fast_mc )

            mc_block(&s->plane[plane_index], dst, src, stride, b_w, b_h, dx, dy);

        else if(b_w==32){

            int y;

            for(y=0; y<b_h; y+=16){

                s->h264qpel.put_h264_qpel_pixels_tab[0][dy+(dx>>2)](dst + y*stride, src + 3 + (y+3)*stride,stride);

                s->h264qpel.put_h264_qpel_pixels_tab[0][dy+(dx>>2)](dst + 16 + y*stride, src + 19 + (y+3)*stride,stride);

            }

        }else if(b_w==b_h)

            s->h264qpel.put_h264_qpel_pixels_tab[tab_index  ][dy+(dx>>2)](dst,src + 3 + 3*stride,stride);

        else if(b_w==2*b_h){

            s->h264qpel.put_h264_qpel_pixels_tab[tab_index+1][dy+(dx>>2)](dst    ,src + 3       + 3*stride,stride);

            s->h264qpel.put_h264_qpel_pixels_tab[tab_index+1][dy+(dx>>2)](dst+b_h,src + 3 + b_h + 3*stride,stride);

        }else{

            av_assert2(2*b_w==b_h);

            s->h264qpel.put_h264_qpel_pixels_tab[tab_index  ][dy+(dx>>2)](dst           ,src + 3 + 3*stride           ,stride);

            s->h264qpel.put_h264_qpel_pixels_tab[tab_index  ][dy+(dx>>2)](dst+b_w*stride,src + 3 + 3*stride+b_w*stride,stride);

        }

    }

}

static inline void RENAME(bgr32ToUV)(uint8_t *dstU, uint8_t *dstV, uint8_t *src1, uint8_t *src2, int width)

{

	int i;

        assert(src1 == src2);

	for(i=0; i<width; i++)

	{

		const int a= ((uint32_t*)src1)[2*i+0];

		const int e= ((uint32_t*)src1)[2*i+1];

		const int l= (a&0xFF00FF) + (e&0xFF00FF);

		const int h= (a&0x00FF00) + (e&0x00FF00);

 		const int b=  l&0x3FF;

		const int g=  h>>8;

		const int r=  l>>16;



		dstU[i]= ((RU*r + GU*g + BU*b)>>(RGB2YUV_SHIFT+1)) + 128;

		dstV[i]= ((RV*r + GV*g + BV*b)>>(RGB2YUV_SHIFT+1)) + 128;

	}

}

int kvm_arch_put_registers(CPUState *cs, int level)

{

    S390CPU *cpu = S390_CPU(cs);

    CPUS390XState *env = &cpu->env;

    struct kvm_sregs sregs;

    struct kvm_regs regs;

    struct kvm_fpu fpu;

    int r;

    int i;



    /* always save the PSW  and the GPRS*/

    cs->kvm_run->psw_addr = env->psw.addr;

    cs->kvm_run->psw_mask = env->psw.mask;



    if (cap_sync_regs && cs->kvm_run->kvm_valid_regs & KVM_SYNC_GPRS) {

        for (i = 0; i < 16; i++) {

            cs->kvm_run->s.regs.gprs[i] = env->regs[i];

            cs->kvm_run->kvm_dirty_regs |= KVM_SYNC_GPRS;

        }

    } else {

        for (i = 0; i < 16; i++) {

            regs.gprs[i] = env->regs[i];

        }

        r = kvm_vcpu_ioctl(cs, KVM_SET_REGS, &regs);

        if (r < 0) {

            return r;

        }

    }



    /* Floating point */

    for (i = 0; i < 16; i++) {

        fpu.fprs[i] = env->fregs[i].ll;

    }

    fpu.fpc = env->fpc;



    r = kvm_vcpu_ioctl(cs, KVM_SET_FPU, &fpu);

    if (r < 0) {

        return r;

    }



    /* Do we need to save more than that? */

    if (level == KVM_PUT_RUNTIME_STATE) {

        return 0;

    }



    /*

     * These ONE_REGS are not protected by a capability. As they are only

     * necessary for migration we just trace a possible error, but don't

     * return with an error return code.

     */

    kvm_set_one_reg(cs, KVM_REG_S390_CPU_TIMER, &env->cputm);

    kvm_set_one_reg(cs, KVM_REG_S390_CLOCK_COMP, &env->ckc);

    kvm_set_one_reg(cs, KVM_REG_S390_TODPR, &env->todpr);

    kvm_set_one_reg(cs, KVM_REG_S390_GBEA, &env->gbea);

    kvm_set_one_reg(cs, KVM_REG_S390_PP, &env->pp);



    if (cap_async_pf) {

        r = kvm_set_one_reg(cs, KVM_REG_S390_PFTOKEN, &env->pfault_token);

        if (r < 0) {

            return r;

        }

        r = kvm_set_one_reg(cs, KVM_REG_S390_PFCOMPARE, &env->pfault_compare);

        if (r < 0) {

            return r;

        }

        r = kvm_set_one_reg(cs, KVM_REG_S390_PFSELECT, &env->pfault_select);

        if (r < 0) {

            return r;

        }

    }



    if (cap_sync_regs &&

        cs->kvm_run->kvm_valid_regs & KVM_SYNC_ACRS &&

        cs->kvm_run->kvm_valid_regs & KVM_SYNC_CRS) {

        for (i = 0; i < 16; i++) {

            cs->kvm_run->s.regs.acrs[i] = env->aregs[i];

            cs->kvm_run->s.regs.crs[i] = env->cregs[i];

        }

        cs->kvm_run->kvm_dirty_regs |= KVM_SYNC_ACRS;

        cs->kvm_run->kvm_dirty_regs |= KVM_SYNC_CRS;

    } else {

        for (i = 0; i < 16; i++) {

            sregs.acrs[i] = env->aregs[i];

            sregs.crs[i] = env->cregs[i];

        }

        r = kvm_vcpu_ioctl(cs, KVM_SET_SREGS, &sregs);

        if (r < 0) {

            return r;

        }

    }



    /* Finally the prefix */

    if (cap_sync_regs && cs->kvm_run->kvm_valid_regs & KVM_SYNC_PREFIX) {

        cs->kvm_run->s.regs.prefix = env->psa;

        cs->kvm_run->kvm_dirty_regs |= KVM_SYNC_PREFIX;

    } else {

        /* prefix is only supported via sync regs */

    }

    return 0;

}

static inline uint16_t mipsdsp_lshift16(uint16_t a, uint8_t s,

                                        CPUMIPSState *env)

{

    uint8_t  sign;

    uint16_t discard;



    if (s == 0) {

        return a;

    } else {

        sign = (a >> 15) & 0x01;

        if (sign != 0) {

            discard = (((0x01 << (16 - s)) - 1) << s) |

                      ((a >> (14 - (s - 1))) & ((0x01 << s) - 1));

        } else {

            discard = a >> (14 - (s - 1));

        }



        if ((discard != 0x0000) && (discard != 0xFFFF)) {

            set_DSPControl_overflow_flag(1, 22, env);

        }

        return a << s;

    }

}

