static always_inline void gen_load_mem (DisasContext *ctx,

                                        void (*tcg_gen_qemu_load)(TCGv t0, TCGv t1, int flags),

                                        int ra, int rb, int32_t disp16,

                                        int fp, int clear)

{

    TCGv addr;



    if (unlikely(ra == 31))

        return;



    addr = tcg_temp_new(TCG_TYPE_I64);

    if (rb != 31) {

        tcg_gen_addi_i64(addr, cpu_ir[rb], disp16);

        if (clear)

            tcg_gen_andi_i64(addr, addr, ~0x7);

    } else {

        if (clear)

            disp16 &= ~0x7;

        tcg_gen_movi_i64(addr, disp16);

    }

    if (fp)

        tcg_gen_qemu_load(cpu_fir[ra], addr, ctx->mem_idx);

    else

        tcg_gen_qemu_load(cpu_ir[ra], addr, ctx->mem_idx);

    tcg_temp_free(addr);

}

static void vmxnet3_handle_command(VMXNET3State *s, uint64_t cmd)

{

    s->last_command = cmd;



    switch (cmd) {

    case VMXNET3_CMD_GET_PERM_MAC_HI:

        VMW_CBPRN("Set: Get upper part of permanent MAC");

        break;



    case VMXNET3_CMD_GET_PERM_MAC_LO:

        VMW_CBPRN("Set: Get lower part of permanent MAC");

        break;



    case VMXNET3_CMD_GET_STATS:

        VMW_CBPRN("Set: Get device statistics");

        vmxnet3_fill_stats(s);

        break;



    case VMXNET3_CMD_ACTIVATE_DEV:

        VMW_CBPRN("Set: Activating vmxnet3 device");

        vmxnet3_activate_device(s);

        break;



    case VMXNET3_CMD_UPDATE_RX_MODE:

        VMW_CBPRN("Set: Update rx mode");

        vmxnet3_update_rx_mode(s);

        break;



    case VMXNET3_CMD_UPDATE_VLAN_FILTERS:

        VMW_CBPRN("Set: Update VLAN filters");

        vmxnet3_update_vlan_filters(s);

        break;



    case VMXNET3_CMD_UPDATE_MAC_FILTERS:

        VMW_CBPRN("Set: Update MAC filters");

        vmxnet3_update_mcast_filters(s);

        break;



    case VMXNET3_CMD_UPDATE_FEATURE:

        VMW_CBPRN("Set: Update features");

        vmxnet3_update_features(s);

        break;



    case VMXNET3_CMD_UPDATE_PMCFG:

        VMW_CBPRN("Set: Update power management config");

        vmxnet3_update_pm_state(s);

        break;



    case VMXNET3_CMD_GET_LINK:

        VMW_CBPRN("Set: Get link");

        break;



    case VMXNET3_CMD_RESET_DEV:

        VMW_CBPRN("Set: Reset device");

        vmxnet3_reset(s);

        break;



    case VMXNET3_CMD_QUIESCE_DEV:

        VMW_CBPRN("Set: VMXNET3_CMD_QUIESCE_DEV - pause the device");

        vmxnet3_deactivate_device(s);

        break;



    case VMXNET3_CMD_GET_CONF_INTR:

        VMW_CBPRN("Set: VMXNET3_CMD_GET_CONF_INTR - interrupt configuration");

        break;



    case VMXNET3_CMD_GET_ADAPTIVE_RING_INFO:

        VMW_CBPRN("Set: VMXNET3_CMD_GET_ADAPTIVE_RING_INFO - "

                  "adaptive ring info flags");

        break;



    default:

        VMW_CBPRN("Received unknown command: %" PRIx64, cmd);

        break;

    }

}

static void megasas_command_complete(SCSIRequest *req, uint32_t status,

                                     size_t resid)

{

    MegasasCmd *cmd = req->hba_private;

    uint8_t cmd_status = MFI_STAT_OK;



    trace_megasas_command_complete(cmd->index, status, resid);



    if (req->io_canceled) {

        return;

    }



    if (cmd->req == NULL) {

        /*

         * Internal command complete

         */

        cmd_status = megasas_finish_internal_dcmd(cmd, req, resid);

        if (cmd_status == MFI_STAT_INVALID_STATUS) {

            return;

        }

    } else {

        req->status = status;

        trace_megasas_scsi_complete(cmd->index, req->status,

                                    cmd->iov_size, req->cmd.xfer);

        if (req->status != GOOD) {

            cmd_status = MFI_STAT_SCSI_DONE_WITH_ERROR;

        }

        if (req->status == CHECK_CONDITION) {

            megasas_copy_sense(cmd);

        }



        cmd->frame->header.scsi_status = req->status;

    }

    cmd->frame->header.cmd_status = cmd_status;

    megasas_complete_command(cmd);

}

static int decode_frame_headers(Indeo3DecodeContext *ctx, AVCodecContext *avctx,

                                const uint8_t *buf, int buf_size)

{

    GetByteContext gb;

    const uint8_t   *bs_hdr;

    uint32_t        frame_num, word2, check_sum, data_size;

    uint32_t        y_offset, u_offset, v_offset, starts[3], ends[3];

    uint16_t        height, width;

    int             i, j;



    bytestream2_init(&gb, buf, buf_size);



    /* parse and check the OS header */

    frame_num = bytestream2_get_le32(&gb);

    word2     = bytestream2_get_le32(&gb);

    check_sum = bytestream2_get_le32(&gb);

    data_size = bytestream2_get_le32(&gb);



    if ((frame_num ^ word2 ^ data_size ^ OS_HDR_ID) != check_sum) {

        av_log(avctx, AV_LOG_ERROR, "OS header checksum mismatch!\n");

        return AVERROR_INVALIDDATA;

    }



    /* parse the bitstream header */

    bs_hdr = gb.buffer;



    if (bytestream2_get_le16(&gb) != 32) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported codec version!\n");

        return AVERROR_INVALIDDATA;

    }



    ctx->frame_num   =  frame_num;

    ctx->frame_flags =  bytestream2_get_le16(&gb);

    ctx->data_size   = (bytestream2_get_le32(&gb) + 7) >> 3;

    ctx->cb_offset   =  bytestream2_get_byte(&gb);



    if (ctx->data_size == 16)

        return 4;

    if (ctx->data_size > buf_size)

        ctx->data_size = buf_size;



    bytestream2_skip(&gb, 3); // skip reserved byte and checksum



    /* check frame dimensions */

    height = bytestream2_get_le16(&gb);

    width  = bytestream2_get_le16(&gb);

    if (av_image_check_size(width, height, 0, avctx))

        return AVERROR_INVALIDDATA;



    if (width != ctx->width || height != ctx->height) {

        int res;



        av_dlog(avctx, "Frame dimensions changed!\n");



        if (width  < 16 || width  > 640 ||

            height < 16 || height > 480 ||

            width  &  3 || height &   3) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid picture dimensions: %d x %d!\n", width, height);

            return AVERROR_INVALIDDATA;

        }



        ctx->width  = width;

        ctx->height = height;



        free_frame_buffers(ctx);

        if ((res = allocate_frame_buffers(ctx, avctx)) < 0)

             return res;

        avcodec_set_dimensions(avctx, width, height);

    }



    y_offset = bytestream2_get_le32(&gb);

    v_offset = bytestream2_get_le32(&gb);

    u_offset = bytestream2_get_le32(&gb);

    bytestream2_skip(&gb, 4);



    /* unfortunately there is no common order of planes in the buffer */

    /* so we use that sorting algo for determining planes data sizes  */

    starts[0] = y_offset;

    starts[1] = v_offset;

    starts[2] = u_offset;



    for (j = 0; j < 3; j++) {

        ends[j] = ctx->data_size;

        for (i = 2; i >= 0; i--)

            if (starts[i] < ends[j] && starts[i] > starts[j])

                ends[j] = starts[i];

    }



    ctx->y_data_size = ends[0] - starts[0];

    ctx->v_data_size = ends[1] - starts[1];

    ctx->u_data_size = ends[2] - starts[2];

    if (FFMAX3(y_offset, v_offset, u_offset) >= ctx->data_size - 16 ||

        FFMIN3(y_offset, v_offset, u_offset) < gb.buffer - bs_hdr + 16 ||

        FFMIN3(ctx->y_data_size, ctx->v_data_size, ctx->u_data_size) <= 0) {

        av_log(avctx, AV_LOG_ERROR, "One of the y/u/v offsets is invalid\n");

        return AVERROR_INVALIDDATA;

    }



    ctx->y_data_ptr = bs_hdr + y_offset;

    ctx->v_data_ptr = bs_hdr + v_offset;

    ctx->u_data_ptr = bs_hdr + u_offset;

    ctx->alt_quant  = gb.buffer;



    if (ctx->data_size == 16) {

        av_log(avctx, AV_LOG_DEBUG, "Sync frame encountered!\n");

        return 16;

    }



    if (ctx->frame_flags & BS_8BIT_PEL) {

        avpriv_request_sample(avctx, "8-bit pixel format");

        return AVERROR_PATCHWELCOME;

    }



    if (ctx->frame_flags & BS_MV_X_HALF || ctx->frame_flags & BS_MV_Y_HALF) {

        avpriv_request_sample(avctx, "Halfpel motion vectors");

        return AVERROR_PATCHWELCOME;

    }



    return 0;

}

static void png_save2(const char *filename, uint32_t *bitmap, int w, int h)

{

    int x, y, v;

    FILE *f;

    char fname[40], fname2[40];

    char command[1024];



    snprintf(fname, 40, "%s.ppm", filename);



    f = fopen(fname, "w");

    if (!f) {

        perror(fname);

        exit(1);

    }

    fprintf(f, "P6\n"

            "%d %d\n"

            "%d\n",

            w, h, 255);

    for(y = 0; y < h; y++) {

        for(x = 0; x < w; x++) {

            v = bitmap[y * w + x];

            putc((v >> 16) & 0xff, f);

            putc((v >> 8) & 0xff, f);

            putc((v >> 0) & 0xff, f);

        }

    }

    fclose(f);





    snprintf(fname2, 40, "%s-a.pgm", filename);



    f = fopen(fname2, "w");

    if (!f) {

        perror(fname2);

        exit(1);

    }

    fprintf(f, "P5\n"

            "%d %d\n"

            "%d\n",

            w, h, 255);

    for(y = 0; y < h; y++) {

        for(x = 0; x < w; x++) {

            v = bitmap[y * w + x];

            putc((v >> 24) & 0xff, f);

        }

    }

    fclose(f);



    snprintf(command, 1024, "pnmtopng -alpha %s %s > %s.png 2> /dev/null", fname2, fname, filename);

    system(command);



    snprintf(command, 1024, "rm %s %s", fname, fname2);

    system(command);

}

static unsigned int dec_addu_r(DisasContext *dc)

{

	TCGv t0;

	int size = memsize_z(dc);

	DIS(fprintf (logfile, "addu.%c $r%u, $r%u\n",

		    memsize_char(size),

		    dc->op1, dc->op2));



	cris_cc_mask(dc, CC_MASK_NZVC);

	t0 = tcg_temp_new(TCG_TYPE_TL);

	/* Size can only be qi or hi.  */

	t_gen_zext(t0, cpu_R[dc->op1], size);

	cris_alu(dc, CC_OP_ADD,

		    cpu_R[dc->op2], cpu_R[dc->op2], t0, 4);

	tcg_temp_free(t0);

	return 2;

}

uint64_t helper_efdctsidz (uint64_t val)

{

    CPU_DoubleU u;



    u.ll = val;

    /* NaN are not treated the same way IEEE 754 does */

    if (unlikely(float64_is_nan(u.d)))

        return 0;



    return float64_to_int64_round_to_zero(u.d, &env->vec_status);

}

flac_header (AVFormatContext * s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    AVStream *st = s->streams[idx];

    GetBitContext gb;

    FLACStreaminfo si;

    int mdt;



    if (os->buf[os->pstart] == 0xff)

        return 0;



    init_get_bits(&gb, os->buf + os->pstart, os->psize*8);

    skip_bits1(&gb); /* metadata_last */

    mdt = get_bits(&gb, 7);



    if (mdt == OGG_FLAC_METADATA_TYPE_STREAMINFO) {

        uint8_t *streaminfo_start = os->buf + os->pstart + 5 + 4 + 4 + 4;

        skip_bits_long(&gb, 4*8); /* "FLAC" */

        if(get_bits(&gb, 8) != 1) /* unsupported major version */

            return -1;

        skip_bits_long(&gb, 8 + 16); /* minor version + header count */

        skip_bits_long(&gb, 4*8); /* "fLaC" */



        /* METADATA_BLOCK_HEADER */

        if (get_bits_long(&gb, 32) != FLAC_STREAMINFO_SIZE)

            return -1;



        avpriv_flac_parse_streaminfo(st->codec, &si, streaminfo_start);



        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_id = AV_CODEC_ID_FLAC;

        st->need_parsing = AVSTREAM_PARSE_HEADERS;



        ff_alloc_extradata(st->codec, FLAC_STREAMINFO_SIZE);

        memcpy(st->codec->extradata, streaminfo_start, st->codec->extradata_size);



        avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);

    } else if (mdt == FLAC_METADATA_TYPE_VORBIS_COMMENT) {

        ff_vorbis_comment (s, &st->metadata, os->buf + os->pstart + 4, os->psize - 4);

    }



    return 1;

}

static av_always_inline void RENAME(decode_line)(FFV1Context *s, int w,

                                                 TYPE *sample[2],

                                                 int plane_index, int bits)

{

    PlaneContext *const p = &s->plane[plane_index];

    RangeCoder *const c   = &s->c;

    int x;

    int run_count = 0;

    int run_mode  = 0;

    int run_index = s->run_index;



    if (s->slice_coding_mode == 1) {

        int i;

        for (x = 0; x < w; x++) {

            int v = 0;

            for (i=0; i<bits; i++) {

                uint8_t state = 128;

                v += v + get_rac(c, &state);

            }

            sample[1][x] = v;

        }

        return;

    }



    for (x = 0; x < w; x++) {

        int diff, context, sign;



        context = RENAME(get_context)(p, sample[1] + x, sample[0] + x, sample[1] + x);

        if (context < 0) {

            context = -context;

            sign    = 1;

        } else

            sign = 0;



        av_assert2(context < p->context_count);



        if (s->ac != AC_GOLOMB_RICE) {

            diff = get_symbol_inline(c, p->state[context], 1);

        } else {

            if (context == 0 && run_mode == 0)

                run_mode = 1;



            if (run_mode) {

                if (run_count == 0 && run_mode == 1) {

                    if (get_bits1(&s->gb)) {

                        run_count = 1 << ff_log2_run[run_index];

                        if (x + run_count <= w)

                            run_index++;

                    } else {

                        if (ff_log2_run[run_index])

                            run_count = get_bits(&s->gb, ff_log2_run[run_index]);

                        else

                            run_count = 0;

                        if (run_index)

                            run_index--;

                        run_mode = 2;

                    }

                }

                run_count--;

                if (run_count < 0) {

                    run_mode  = 0;

                    run_count = 0;

                    diff      = get_vlc_symbol(&s->gb, &p->vlc_state[context],

                                               bits);

                    if (diff >= 0)

                        diff++;

                } else

                    diff = 0;

            } else

                diff = get_vlc_symbol(&s->gb, &p->vlc_state[context], bits);



            ff_dlog(s->avctx, "count:%d index:%d, mode:%d, x:%d pos:%d\n",

                    run_count, run_index, run_mode, x, get_bits_count(&s->gb));

        }



        if (sign)

            diff = -diff;



        sample[1][x] = av_mod_uintp2(RENAME(predict)(sample[1] + x, sample[0] + x) + (SUINT)diff, bits);

    }

    s->run_index = run_index;

}

static int revert_channel_correlation(ALSDecContext *ctx, ALSBlockData *bd,

                                       ALSChannelData **cd, int *reverted,

                                       unsigned int offset, int c)

{

    ALSChannelData *ch = cd[c];

    unsigned int   dep = 0;

    unsigned int channels = ctx->avctx->channels;



    if (reverted[c])

        return 0;



    reverted[c] = 1;



    while (dep < channels && !ch[dep].stop_flag) {

        revert_channel_correlation(ctx, bd, cd, reverted, offset,

                                   ch[dep].master_channel);



        dep++;

    }



    if (dep == channels) {

        av_log(ctx->avctx, AV_LOG_WARNING, "Invalid channel correlation.\n");

        return AVERROR_INVALIDDATA;

    }



    bd->const_block = ctx->const_block + c;

    bd->shift_lsbs  = ctx->shift_lsbs + c;

    bd->opt_order   = ctx->opt_order + c;

    bd->store_prev_samples = ctx->store_prev_samples + c;

    bd->use_ltp     = ctx->use_ltp + c;

    bd->ltp_lag     = ctx->ltp_lag + c;

    bd->ltp_gain    = ctx->ltp_gain[c];

    bd->lpc_cof     = ctx->lpc_cof[c];

    bd->quant_cof   = ctx->quant_cof[c];

    bd->raw_samples = ctx->raw_samples[c] + offset;



    dep = 0;

    while (!ch[dep].stop_flag) {

        unsigned int smp;

        unsigned int begin = 1;

        unsigned int end   = bd->block_length - 1;

        int64_t y;

        int32_t *master = ctx->raw_samples[ch[dep].master_channel] + offset;



        if (ch[dep].time_diff_flag) {

            int t = ch[dep].time_diff_index;



            if (ch[dep].time_diff_sign) {

                t      = -t;

                begin -= t;

            } else {

                end   -= t;

            }



            for (smp = begin; smp < end; smp++) {

                y  = (1 << 6) +

                     MUL64(ch[dep].weighting[0], master[smp - 1    ]) +

                     MUL64(ch[dep].weighting[1], master[smp        ]) +

                     MUL64(ch[dep].weighting[2], master[smp + 1    ]) +

                     MUL64(ch[dep].weighting[3], master[smp - 1 + t]) +

                     MUL64(ch[dep].weighting[4], master[smp     + t]) +

                     MUL64(ch[dep].weighting[5], master[smp + 1 + t]);



                bd->raw_samples[smp] += y >> 7;

            }

        } else {

            for (smp = begin; smp < end; smp++) {

                y  = (1 << 6) +

                     MUL64(ch[dep].weighting[0], master[smp - 1]) +

                     MUL64(ch[dep].weighting[1], master[smp    ]) +

                     MUL64(ch[dep].weighting[2], master[smp + 1]);



                bd->raw_samples[smp] += y >> 7;

            }

        }



        dep++;

    }



    return 0;

}

static int caf_write_trailer(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    AVCodecContext *enc = s->streams[0]->codec;



    if (pb->seekable) {

        CAFContext *caf = s->priv_data;

        int64_t file_size = avio_tell(pb);



        avio_seek(pb, caf->data, SEEK_SET);

        avio_wb64(pb, file_size - caf->data - 8);

        avio_seek(pb, file_size, SEEK_SET);

        if (!enc->block_align) {

            ffio_wfourcc(pb, "pakt");

            avio_wb64(pb, caf->size_entries_used + 24);

            avio_wb64(pb, caf->packets); ///< mNumberPackets

            avio_wb64(pb, caf->packets * samples_per_packet(enc->codec_id, enc->channels)); ///< mNumberValidFrames

            avio_wb32(pb, 0); ///< mPrimingFrames

            avio_wb32(pb, 0); ///< mRemainderFrames

            avio_write(pb, caf->pkt_sizes, caf->size_entries_used);

            av_freep(&caf->pkt_sizes);

            caf->size_buffer_size = 0;

        }

        avio_flush(pb);

    }

    return 0;

}

static inline int check_input_motion(MpegEncContext * s, int mb_x, int mb_y, int p_type){

    MotionEstContext * const c= &s->me;

    Picture *p= s->current_picture_ptr;

    int mb_xy= mb_x + mb_y*s->mb_stride;

    int xy= 2*mb_x + 2*mb_y*s->b8_stride;

    int mb_type= s->current_picture.mb_type[mb_xy];

    int flags= c->flags;

    int shift= (flags&FLAG_QPEL) + 1;

    int mask= (1<<shift)-1;

    int x, y, i;

    int d=0;

    me_cmp_func cmpf= s->dsp.sse[0];

    me_cmp_func chroma_cmpf= s->dsp.sse[1];



    assert(p_type==0 || !USES_LIST(mb_type, 1));

    assert(IS_INTRA(mb_type) || USES_LIST(mb_type,0) || USES_LIST(mb_type,1));



    if(IS_INTERLACED(mb_type)){

        int xy2= xy  + s->b8_stride;

        s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTRA;

        c->stride<<=1;

        c->uvstride<<=1;



        if(!(s->flags & CODEC_FLAG_INTERLACED_ME)){

            av_log(c->avctx, AV_LOG_ERROR, "Interlaced macroblock selected but interlaced motion estimation disabled\n");

            return -1;

        }



        if(USES_LIST(mb_type, 0)){

            int field_select0= p->ref_index[0][xy ];

            int field_select1= p->ref_index[0][xy2];

            assert(field_select0==0 ||field_select0==1);

            assert(field_select1==0 ||field_select1==1);

            init_interlaced_ref(s, 0);



            if(p_type){

                s->p_field_select_table[0][mb_xy]= field_select0;

                s->p_field_select_table[1][mb_xy]= field_select1;

                *(uint32_t*)s->p_field_mv_table[0][field_select0][mb_xy]= *(uint32_t*)p->motion_val[0][xy ];

                *(uint32_t*)s->p_field_mv_table[1][field_select1][mb_xy]= *(uint32_t*)p->motion_val[0][xy2];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTER_I;

            }else{

                s->b_field_select_table[0][0][mb_xy]= field_select0;

                s->b_field_select_table[0][1][mb_xy]= field_select1;

                *(uint32_t*)s->b_field_mv_table[0][0][field_select0][mb_xy]= *(uint32_t*)p->motion_val[0][xy ];

                *(uint32_t*)s->b_field_mv_table[0][1][field_select1][mb_xy]= *(uint32_t*)p->motion_val[0][xy2];

                s->mb_type[mb_xy]= CANDIDATE_MB_TYPE_FORWARD_I;

            }



            x= p->motion_val[0][xy ][0]; 

            y= p->motion_val[0][xy ][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select0, 0, cmpf, chroma_cmpf, flags);

            x= p->motion_val[0][xy2][0]; 

            y= p->motion_val[0][xy2][1];

            d+= cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select1, 1, cmpf, chroma_cmpf, flags);

        }

        if(USES_LIST(mb_type, 1)){

            int field_select0= p->ref_index[1][xy ];

            int field_select1= p->ref_index[1][xy2];

            assert(field_select0==0 ||field_select0==1);

            assert(field_select1==0 ||field_select1==1);

            init_interlaced_ref(s, 2);



            s->b_field_select_table[1][0][mb_xy]= field_select0;

            s->b_field_select_table[1][1][mb_xy]= field_select1;

            *(uint32_t*)s->b_field_mv_table[1][0][field_select0][mb_xy]= *(uint32_t*)p->motion_val[1][xy ];

            *(uint32_t*)s->b_field_mv_table[1][1][field_select1][mb_xy]= *(uint32_t*)p->motion_val[1][xy2];

            if(USES_LIST(mb_type, 0)){

                s->mb_type[mb_xy]= CANDIDATE_MB_TYPE_BIDIR_I;

            }else{

                s->mb_type[mb_xy]= CANDIDATE_MB_TYPE_BACKWARD_I;

            }



            x= p->motion_val[1][xy ][0]; 

            y= p->motion_val[1][xy ][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select0+2, 0, cmpf, chroma_cmpf, flags);

            x= p->motion_val[1][xy2][0]; 

            y= p->motion_val[1][xy2][1];

            d+= cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select1+2, 1, cmpf, chroma_cmpf, flags);

            //FIXME bidir scores

        }

        c->stride>>=1;

        c->uvstride>>=1;

    }else if(IS_8X8(mb_type)){

        if(!(s->flags & CODEC_FLAG_4MV)){

            av_log(c->avctx, AV_LOG_ERROR, "4MV macroblock selected but 4MV encoding disabled\n");

            return -1;

        }

        cmpf= s->dsp.sse[1];

        chroma_cmpf= s->dsp.sse[1];

        init_mv4_ref(c);

        for(i=0; i<4; i++){

            xy= s->block_index[i];

            x= p->motion_val[0][xy][0]; 

            y= p->motion_val[0][xy][1];

            d+= cmp(s, x>>shift, y>>shift, x&mask, y&mask, 1, 8, i, i, cmpf, chroma_cmpf, flags);

        }

        s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTER4V;

    }else{

        if(USES_LIST(mb_type, 0)){

            if(p_type){

                *(uint32_t*)s->p_mv_table[mb_xy]= *(uint32_t*)p->motion_val[0][xy];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTER;

            }else if(USES_LIST(mb_type, 1)){

                *(uint32_t*)s->b_bidir_forw_mv_table[mb_xy]= *(uint32_t*)p->motion_val[0][xy];

                *(uint32_t*)s->b_bidir_back_mv_table[mb_xy]= *(uint32_t*)p->motion_val[1][xy];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_BIDIR;

            }else{

                *(uint32_t*)s->b_forw_mv_table[mb_xy]= *(uint32_t*)p->motion_val[0][xy];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_FORWARD;

            }

            x= p->motion_val[0][xy][0]; 

            y= p->motion_val[0][xy][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 16, 0, 0, cmpf, chroma_cmpf, flags);

        }else if(USES_LIST(mb_type, 1)){

            *(uint32_t*)s->b_back_mv_table[mb_xy]= *(uint32_t*)p->motion_val[1][xy];

            s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_BACKWARD;



            x= p->motion_val[1][xy][0]; 

            y= p->motion_val[1][xy][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 16, 2, 0, cmpf, chroma_cmpf, flags);

        }else

            s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTRA;

    }

    return d;

}

