void ff_h264_init_cabac_states(const H264Context *h, H264SliceContext *sl)

{

    int i;

    const int8_t (*tab)[2];

    const int slice_qp = av_clip(sl->qscale - 6*(h->sps.bit_depth_luma-8), 0, 51);



    if (sl->slice_type_nos == AV_PICTURE_TYPE_I) tab = cabac_context_init_I;

    else                                 tab = cabac_context_init_PB[sl->cabac_init_idc];



    /* calculate pre-state */

    for( i= 0; i < 1024; i++ ) {

        int pre = 2*(((tab[i][0] * slice_qp) >>4 ) + tab[i][1]) - 127;



        pre^= pre>>31;

        if(pre > 124)

            pre= 124 + (pre&1);



        sl->cabac_state[i] =  pre;

    }

}

static BlockDriverAIOCB *iscsi_aio_ioctl(BlockDriverState *bs,

        unsigned long int req, void *buf,

        BlockDriverCompletionFunc *cb, void *opaque)

{

    IscsiLun *iscsilun = bs->opaque;

    struct iscsi_context *iscsi = iscsilun->iscsi;

    struct iscsi_data data;

    IscsiAIOCB *acb;



    assert(req == SG_IO);



    acb = qemu_aio_get(&iscsi_aiocb_info, bs, cb, opaque);



    acb->iscsilun = iscsilun;

    acb->canceled    = 0;

    acb->bh          = NULL;

    acb->status      = -EINPROGRESS;

    acb->buf         = NULL;

    acb->ioh         = buf;



    acb->task = malloc(sizeof(struct scsi_task));

    if (acb->task == NULL) {

        error_report("iSCSI: Failed to allocate task for scsi command. %s",

                     iscsi_get_error(iscsi));

        qemu_aio_release(acb);

        return NULL;

    }

    memset(acb->task, 0, sizeof(struct scsi_task));



    switch (acb->ioh->dxfer_direction) {

    case SG_DXFER_TO_DEV:

        acb->task->xfer_dir = SCSI_XFER_WRITE;

        break;

    case SG_DXFER_FROM_DEV:

        acb->task->xfer_dir = SCSI_XFER_READ;

        break;

    default:

        acb->task->xfer_dir = SCSI_XFER_NONE;

        break;

    }



    acb->task->cdb_size = acb->ioh->cmd_len;

    memcpy(&acb->task->cdb[0], acb->ioh->cmdp, acb->ioh->cmd_len);

    acb->task->expxferlen = acb->ioh->dxfer_len;



    data.size = 0;

    if (acb->task->xfer_dir == SCSI_XFER_WRITE) {

        if (acb->ioh->iovec_count == 0) {

            data.data = acb->ioh->dxferp;

            data.size = acb->ioh->dxfer_len;

        } else {

#if defined(LIBISCSI_FEATURE_IOVECTOR)

            scsi_task_set_iov_out(acb->task,

                                 (struct scsi_iovec *) acb->ioh->dxferp,

                                 acb->ioh->iovec_count);

#else

            struct iovec *iov = (struct iovec *)acb->ioh->dxferp;



            acb->buf = g_malloc(acb->ioh->dxfer_len);

            data.data = acb->buf;

            data.size = iov_to_buf(iov, acb->ioh->iovec_count, 0,

                                   acb->buf, acb->ioh->dxfer_len);

#endif

        }

    }



    if (iscsi_scsi_command_async(iscsi, iscsilun->lun, acb->task,

                                 iscsi_aio_ioctl_cb,

                                 (data.size > 0) ? &data : NULL,

                                 acb) != 0) {

        scsi_free_scsi_task(acb->task);

        qemu_aio_release(acb);

        return NULL;

    }



    /* tell libiscsi to read straight into the buffer we got from ioctl */

    if (acb->task->xfer_dir == SCSI_XFER_READ) {

        if (acb->ioh->iovec_count == 0) {

            scsi_task_add_data_in_buffer(acb->task,

                                         acb->ioh->dxfer_len,

                                         acb->ioh->dxferp);

        } else {

#if defined(LIBISCSI_FEATURE_IOVECTOR)

            scsi_task_set_iov_in(acb->task,

                                 (struct scsi_iovec *) acb->ioh->dxferp,

                                 acb->ioh->iovec_count);

#else

            int i;

            for (i = 0; i < acb->ioh->iovec_count; i++) {

                struct iovec *iov = (struct iovec *)acb->ioh->dxferp;



                scsi_task_add_data_in_buffer(acb->task,

                    iov[i].iov_len,

                    iov[i].iov_base);

            }

#endif

        }

    }



    iscsi_set_events(iscsilun);



    return &acb->common;

}

void intra_predict(VP8Context *s, VP8ThreadData *td, uint8_t *dst[3],

                   VP8Macroblock *mb, int mb_x, int mb_y)

{

    int x, y, mode, nnz;

    uint32_t tr;



    /* for the first row, we need to run xchg_mb_border to init the top edge

     * to 127 otherwise, skip it if we aren't going to deblock */

    if (mb_y && (s->deblock_filter || !mb_y) && td->thread_nr == 0)

        xchg_mb_border(s->top_border[mb_x + 1], dst[0], dst[1], dst[2],

                       s->linesize, s->uvlinesize, mb_x, mb_y, s->mb_width,

                       s->filter.simple, 1);



    if (mb->mode < MODE_I4x4) {

        mode = check_intra_pred8x8_mode_emuedge(mb->mode, mb_x, mb_y);

        s->hpc.pred16x16[mode](dst[0], s->linesize);

    } else {

        uint8_t *ptr = dst[0];

        uint8_t *intra4x4 = mb->intra4x4_pred_mode_mb;

        uint8_t tr_top[4] = { 127, 127, 127, 127 };



        // all blocks on the right edge of the macroblock use bottom edge

        // the top macroblock for their topright edge

        uint8_t *tr_right = ptr - s->linesize + 16;



        // if we're on the right edge of the frame, said edge is extended

        // from the top macroblock

        if (mb_y && mb_x == s->mb_width - 1) {

            tr       = tr_right[-1] * 0x01010101u;

            tr_right = (uint8_t *) &tr;

        }



        if (mb->skip)

            AV_ZERO128(td->non_zero_count_cache);



        for (y = 0; y < 4; y++) {

            uint8_t *topright = ptr + 4 - s->linesize;

            for (x = 0; x < 4; x++) {

                int copy = 0, linesize = s->linesize;

                uint8_t *dst = ptr + 4 * x;

                DECLARE_ALIGNED(4, uint8_t, copy_dst)[5 * 8];



                if ((y == 0 || x == 3) && mb_y == 0) {

                    topright = tr_top;

                } else if (x == 3)

                    topright = tr_right;



                mode = check_intra_pred4x4_mode_emuedge(intra4x4[x],

                                                        mb_x + x, mb_y + y,

                                                        &copy);

                if (copy) {

                    dst      = copy_dst + 12;

                    linesize = 8;

                    if (!(mb_y + y)) {

                        copy_dst[3] = 127U;

                        AV_WN32A(copy_dst + 4, 127U * 0x01010101U);

                    } else {

                        AV_COPY32(copy_dst + 4, ptr + 4 * x - s->linesize);

                        if (!(mb_x + x)) {

                            copy_dst[3] = 129U;

                        } else {

                            copy_dst[3] = ptr[4 * x - s->linesize - 1];

                        }

                    }

                    if (!(mb_x + x)) {

                        copy_dst[11] =

                        copy_dst[19] =

                        copy_dst[27] =

                        copy_dst[35] = 129U;

                    } else {

                        copy_dst[11] = ptr[4 * x                   - 1];

                        copy_dst[19] = ptr[4 * x + s->linesize     - 1];

                        copy_dst[27] = ptr[4 * x + s->linesize * 2 - 1];

                        copy_dst[35] = ptr[4 * x + s->linesize * 3 - 1];

                    }

                }

                s->hpc.pred4x4[mode](dst, topright, linesize);

                if (copy) {

                    AV_COPY32(ptr + 4 * x,                   copy_dst + 12);

                    AV_COPY32(ptr + 4 * x + s->linesize,     copy_dst + 20);

                    AV_COPY32(ptr + 4 * x + s->linesize * 2, copy_dst + 28);

                    AV_COPY32(ptr + 4 * x + s->linesize * 3, copy_dst + 36);

                }



                nnz = td->non_zero_count_cache[y][x];

                if (nnz) {

                    if (nnz == 1)

                        s->vp8dsp.vp8_idct_dc_add(ptr + 4 * x,

                                                  td->block[y][x], s->linesize);

                    else

                        s->vp8dsp.vp8_idct_add(ptr + 4 * x,

                                               td->block[y][x], s->linesize);

                }

                topright += 4;

            }



            ptr      += 4 * s->linesize;

            intra4x4 += 4;

        }

    }



    mode = check_intra_pred8x8_mode_emuedge(mb->chroma_pred_mode, mb_x, mb_y);

    s->hpc.pred8x8[mode](dst[1], s->uvlinesize);

    s->hpc.pred8x8[mode](dst[2], s->uvlinesize);



    if (mb_y && (s->deblock_filter || !mb_y) && td->thread_nr == 0)

        xchg_mb_border(s->top_border[mb_x + 1], dst[0], dst[1], dst[2],

                       s->linesize, s->uvlinesize, mb_x, mb_y, s->mb_width,

                       s->filter.simple, 0);

}

