static int mkv_write_chapters(AVFormatContext *s)

{

    MatroskaMuxContext *mkv = s->priv_data;

    AVIOContext *pb = s->pb;

    ebml_master chapters, editionentry;

    AVRational scale = {1, 1E9};

    int i, ret;



    if (!s->nb_chapters || mkv->wrote_chapters)

        return 0;



    ret = mkv_add_seekhead_entry(mkv->main_seekhead, MATROSKA_ID_CHAPTERS, avio_tell(pb));

    if (ret < 0) return ret;



    chapters     = start_ebml_master(pb, MATROSKA_ID_CHAPTERS    , 0);

    editionentry = start_ebml_master(pb, MATROSKA_ID_EDITIONENTRY, 0);

    put_ebml_uint(pb, MATROSKA_ID_EDITIONFLAGDEFAULT, 1);

    put_ebml_uint(pb, MATROSKA_ID_EDITIONFLAGHIDDEN , 0);

    for (i = 0; i < s->nb_chapters; i++) {

        ebml_master chapteratom, chapterdisplay;

        AVChapter *c     = s->chapters[i];

        AVDictionaryEntry *t = NULL;



        chapteratom = start_ebml_master(pb, MATROSKA_ID_CHAPTERATOM, 0);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERUID, c->id);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERTIMESTART,

                      av_rescale_q(c->start, c->time_base, scale));

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERTIMEEND,

                      av_rescale_q(c->end,   c->time_base, scale));

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERFLAGHIDDEN , 0);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERFLAGENABLED, 1);

        if ((t = av_dict_get(c->metadata, "title", NULL, 0))) {

            chapterdisplay = start_ebml_master(pb, MATROSKA_ID_CHAPTERDISPLAY, 0);

            put_ebml_string(pb, MATROSKA_ID_CHAPSTRING, t->value);

            put_ebml_string(pb, MATROSKA_ID_CHAPLANG  , "und");

            end_ebml_master(pb, chapterdisplay);

        }

        end_ebml_master(pb, chapteratom);

    }

    end_ebml_master(pb, editionentry);

    end_ebml_master(pb, chapters);



    mkv->wrote_chapters = 1;

    return 0;

}

void qpci_device_foreach(QPCIBus *bus, int vendor_id, int device_id,

                         void (*func)(QPCIDevice *dev, int devfn, void *data),

                         void *data)

{

    int slot;



    for (slot = 0; slot < 32; slot++) {

        int fn;



        for (fn = 0; fn < 8; fn++) {

            QPCIDevice *dev;



            dev = qpci_device_find(bus, QPCI_DEVFN(slot, fn));

            if (!dev) {

                continue;

            }



            if (vendor_id != -1 &&

                qpci_config_readw(dev, PCI_VENDOR_ID) != vendor_id) {


                continue;

            }



            if (device_id != -1 &&

                qpci_config_readw(dev, PCI_DEVICE_ID) != device_id) {


                continue;

            }



            func(dev, QPCI_DEVFN(slot, fn), data);

        }

    }

}

static void tosa_init(ram_addr_t ram_size, int vga_ram_size,

                const char *boot_device,

                const char *kernel_filename, const char *kernel_cmdline,

                const char *initrd_filename, const char *cpu_model)

{

    struct pxa2xx_state_s *cpu;

    struct tc6393xb_s *tmio;

    struct scoop_info_s *scp0, *scp1;



    if (ram_size < (TOSA_RAM + TOSA_ROM + PXA2XX_INTERNAL_SIZE + TC6393XB_RAM)) {

        fprintf(stderr, "This platform requires %i bytes of memory\n",

                TOSA_RAM + TOSA_ROM + PXA2XX_INTERNAL_SIZE);

        exit(1);

    }



    if (!cpu_model)

        cpu_model = "pxa255";



    cpu = pxa255_init(tosa_binfo.ram_size);



    cpu_register_physical_memory(0, TOSA_ROM,

                    qemu_ram_alloc(TOSA_ROM) | IO_MEM_ROM);



    tmio = tc6393xb_init(0x10000000,

            pxa2xx_gpio_in_get(cpu->gpio)[TOSA_GPIO_TC6393XB_INT]);



    scp0 = scoop_init(cpu, 0, 0x08800000);

    scp1 = scoop_init(cpu, 1, 0x14800040);



    tosa_gpio_setup(cpu, scp0, scp1, tmio);



    tosa_microdrive_attach(cpu);



    tosa_tg_init(cpu);



    /* Setup initial (reset) machine state */

    cpu->env->regs[15] = tosa_binfo.loader_start;



    tosa_binfo.kernel_filename = kernel_filename;

    tosa_binfo.kernel_cmdline = kernel_cmdline;

    tosa_binfo.initrd_filename = initrd_filename;

    tosa_binfo.board_id = 0x208;

    arm_load_kernel(cpu->env, &tosa_binfo);

    sl_bootparam_write(SL_PXA_PARAM_BASE);

}

void helper_wrmsr(void)

{

    uint64_t val;



    helper_svm_check_intercept_param(SVM_EXIT_MSR, 1);



    val = ((uint32_t)EAX) | ((uint64_t)((uint32_t)EDX) << 32);



    switch((uint32_t)ECX) {

    case MSR_IA32_SYSENTER_CS:

        env->sysenter_cs = val & 0xffff;


    case MSR_IA32_SYSENTER_ESP:

        env->sysenter_esp = val;


    case MSR_IA32_SYSENTER_EIP:

        env->sysenter_eip = val;


    case MSR_IA32_APICBASE:

        cpu_set_apic_base(env, val);


    case MSR_EFER:

        {

            uint64_t update_mask;

            update_mask = 0;

            if (env->cpuid_ext2_features & CPUID_EXT2_SYSCALL)

                update_mask |= MSR_EFER_SCE;

            if (env->cpuid_ext2_features & CPUID_EXT2_LM)

                update_mask |= MSR_EFER_LME;

            if (env->cpuid_ext2_features & CPUID_EXT2_FFXSR)

                update_mask |= MSR_EFER_FFXSR;

            if (env->cpuid_ext2_features & CPUID_EXT2_NX)

                update_mask |= MSR_EFER_NXE;

            if (env->cpuid_ext3_features & CPUID_EXT3_SVM)

                update_mask |= MSR_EFER_SVME;

            cpu_load_efer(env, (env->efer & ~update_mask) |

                          (val & update_mask));

        }


    case MSR_STAR:

        env->star = val;


    case MSR_PAT:

        env->pat = val;


    case MSR_VM_HSAVE_PA:

        env->vm_hsave = val;


#ifdef TARGET_X86_64

    case MSR_LSTAR:

        env->lstar = val;


    case MSR_CSTAR:

        env->cstar = val;


    case MSR_FMASK:

        env->fmask = val;


    case MSR_FSBASE:

        env->segs[R_FS].base = val;


    case MSR_GSBASE:

        env->segs[R_GS].base = val;


    case MSR_KERNELGSBASE:

        env->kernelgsbase = val;


#endif









































    default:

        /* XXX: exception ? */


    }

}

