			"m" (yalpha1), "m" (uvalpha1)

			: "%eax"

			);

		}

	}

	else

	{

		if(dstbpp == 32)

		{

			asm volatile(

				YSCALEYUV2RGB1b

				WRITEBGR32

			:: "r" (buf0), "r" (buf0), "r" (uvbuf0), "r" (uvbuf1), "r" (dest), "m" (dstW),

