static BlockDriverAIOCB *raw_aio_submit(BlockDriverState *bs,

        int64_t sector_num, QEMUIOVector *qiov, int nb_sectors,

        BlockDriverCompletionFunc *cb, void *opaque, int type)

{

    BDRVRawState *s = bs->opaque;



    if (fd_open(bs) < 0)

        return NULL;



    /*

     * If O_DIRECT is used the buffer needs to be aligned on a sector

     * boundary.  Check if this is the case or tell the low-level

     * driver that it needs to copy the buffer.

     */

    if ((bs->open_flags & BDRV_O_NOCACHE)) {

        if (!qiov_is_aligned(bs, qiov)) {

            type |= QEMU_AIO_MISALIGNED;

#ifdef CONFIG_LINUX_AIO

        } else if (s->use_aio) {

            return laio_submit(bs, s->aio_ctx, s->fd, sector_num, qiov,

                               nb_sectors, cb, opaque, type);

#endif

        }

    }



    return paio_submit(bs, s->fd, sector_num, qiov, nb_sectors,

                       cb, opaque, type);

}

void avfilter_draw_slice(AVFilterLink *link, int y, int h)

{

    uint8_t *src[4], *dst[4];

    int i, j, hsub, vsub;



    /* copy the slice if needed for permission reasons */

    if(link->srcpic) {

        avcodec_get_chroma_sub_sample(link->format, &hsub, &vsub);



        src[0] = link->srcpic-> data[0] + y * link->srcpic-> linesize[0];

        dst[0] = link->cur_pic->data[0] + y * link->cur_pic->linesize[0];

        for(i = 1; i < 4; i ++) {

            if(link->srcpic->data[i]) {

                src[i] = link->srcpic-> data[i] + (y >> vsub) * link->srcpic-> linesize[i];

                dst[i] = link->cur_pic->data[i] + (y >> vsub) * link->cur_pic->linesize[i];

            } else

                src[i] = dst[i] = NULL;

        }

        for(j = 0; j < h; j ++) {

            memcpy(dst[0], src[0], link->cur_pic->linesize[0]);

            src[0] += link->srcpic ->linesize[0];

            dst[0] += link->cur_pic->linesize[0];

        }

        for(i = 1; i < 4; i ++) {

            if(!src[i]) continue;



            for(j = 0; j < h >> vsub; j ++) {

                memcpy(dst[i], src[i], link->cur_pic->linesize[i]);

                src[i] += link->srcpic ->linesize[i];

                dst[i] += link->cur_pic->linesize[i];

            }

        }

    }



    if(!link_dpad(link).draw_slice)

        return;



    link_dpad(link).draw_slice(link, y, h);

}

void tlb_flush_page(CPUState *env, target_ulong addr)

{

    int i;



#if defined(DEBUG_TLB)

    printf("tlb_flush_page: " TARGET_FMT_lx "\n", addr);

#endif

    /* must reset current TB so that interrupts cannot modify the

       links while we are modifying them */

    env->current_tb = NULL;



    addr &= TARGET_PAGE_MASK;

    i = (addr >> TARGET_PAGE_BITS) & (CPU_TLB_SIZE - 1);

    tlb_flush_entry(&env->tlb_table[0][i], addr);

    tlb_flush_entry(&env->tlb_table[1][i], addr);

#if (NB_MMU_MODES >= 3)

    tlb_flush_entry(&env->tlb_table[2][i], addr);

#if (NB_MMU_MODES == 4)

    tlb_flush_entry(&env->tlb_table[3][i], addr);

#endif

#endif



    tlb_flush_jmp_cache(env, addr);



#ifdef USE_KQEMU

    if (env->kqemu_enabled) {

        kqemu_flush_page(env, addr);

    }

#endif

}

int av_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret, i;

    AVStream *st;



    for(;;){

        AVPacketList *pktl = s->raw_packet_buffer;



        if (pktl) {

            *pkt = pktl->pkt;

            if(s->streams[pkt->stream_index]->codec->codec_id != CODEC_ID_PROBE ||

               !s->streams[pkt->stream_index]->probe_packets){

                s->raw_packet_buffer = pktl->next;

                av_free(pktl);

                return 0;

            }

        }



        av_init_packet(pkt);

        ret= s->iformat->read_packet(s, pkt);

        if (ret < 0) {

            if (!pktl || ret == AVERROR(EAGAIN))

                return ret;

            for (i = 0; i < s->nb_streams; i++)

                s->streams[i]->probe_packets = 0;

            continue;

        }

        st= s->streams[pkt->stream_index];



        switch(st->codec->codec_type){

        case CODEC_TYPE_VIDEO:

            if(s->video_codec_id)   st->codec->codec_id= s->video_codec_id;

            break;

        case CODEC_TYPE_AUDIO:

            if(s->audio_codec_id)   st->codec->codec_id= s->audio_codec_id;

            break;

        case CODEC_TYPE_SUBTITLE:

            if(s->subtitle_codec_id)st->codec->codec_id= s->subtitle_codec_id;

            break;

        }



        if(!pktl && (st->codec->codec_id != CODEC_ID_PROBE ||

                     !st->probe_packets))

            return ret;



        add_to_pktbuf(&s->raw_packet_buffer, pkt, &s->raw_packet_buffer_end);



        if(st->codec->codec_id == CODEC_ID_PROBE){

            AVProbeData *pd = &st->probe_data;



            --st->probe_packets;



            pd->buf = av_realloc(pd->buf, pd->buf_size+pkt->size+AVPROBE_PADDING_SIZE);

            memcpy(pd->buf+pd->buf_size, pkt->data, pkt->size);

            pd->buf_size += pkt->size;

            memset(pd->buf+pd->buf_size, 0, AVPROBE_PADDING_SIZE);



            if(av_log2(pd->buf_size) != av_log2(pd->buf_size - pkt->size)){

                set_codec_from_probe_data(st, pd, 1);

                if(st->codec->codec_id != CODEC_ID_PROBE){

                    pd->buf_size=0;

                    av_freep(&pd->buf);

                }

            }

        }

    }

}

