uint32_t helper_fcmp_un(uint32_t a, uint32_t b)

{

    CPU_FloatU fa, fb;

    uint32_t r = 0;



    fa.l = a;

    fb.l = b;



    if (float32_is_signaling_nan(fa.f) || float32_is_signaling_nan(fb.f)) {

        update_fpu_flags(float_flag_invalid);

        r = 1;

    }



    if (float32_is_nan(fa.f) || float32_is_nan(fb.f)) {

        r = 1;

    }



    return r;

}

static int sdp_read_header(AVFormatContext *s)

{

    RTSPState *rt = s->priv_data;

    RTSPStream *rtsp_st;

    int size, i, err;

    char *content;

    char url[1024];



    if (!ff_network_init())

        return AVERROR(EIO);



    if (s->max_delay < 0) /* Not set by the caller */

        s->max_delay = DEFAULT_REORDERING_DELAY;

    if (rt->rtsp_flags & RTSP_FLAG_CUSTOM_IO)

        rt->lower_transport = RTSP_LOWER_TRANSPORT_CUSTOM;



    /* read the whole sdp file */

    /* XXX: better loading */

    content = av_malloc(SDP_MAX_SIZE);



    size = avio_read(s->pb, content, SDP_MAX_SIZE - 1);

    if (size <= 0) {

        av_free(content);

        return AVERROR_INVALIDDATA;

    }

    content[size] ='\0';



    err = ff_sdp_parse(s, content);

    av_freep(&content);

    if (err) goto fail;



    /* open each RTP stream */

    for (i = 0; i < rt->nb_rtsp_streams; i++) {

        char namebuf[50];

        rtsp_st = rt->rtsp_streams[i];



        if (!(rt->rtsp_flags & RTSP_FLAG_CUSTOM_IO)) {

            AVDictionary *opts = map_to_opts(rt);



            getnameinfo((struct sockaddr*) &rtsp_st->sdp_ip, sizeof(rtsp_st->sdp_ip),

                        namebuf, sizeof(namebuf), NULL, 0, NI_NUMERICHOST);

            ff_url_join(url, sizeof(url), "rtp", NULL,

                        namebuf, rtsp_st->sdp_port,

                        "?localport=%d&ttl=%d&connect=%d&write_to_source=%d",

                        rtsp_st->sdp_port, rtsp_st->sdp_ttl,

                        rt->rtsp_flags & RTSP_FLAG_FILTER_SRC ? 1 : 0,

                        rt->rtsp_flags & RTSP_FLAG_RTCP_TO_SOURCE ? 1 : 0);



            append_source_addrs(url, sizeof(url), "sources",

                                rtsp_st->nb_include_source_addrs,

                                rtsp_st->include_source_addrs);

            append_source_addrs(url, sizeof(url), "block",

                                rtsp_st->nb_exclude_source_addrs,

                                rtsp_st->exclude_source_addrs);

            err = ffurl_open(&rtsp_st->rtp_handle, url, AVIO_FLAG_READ_WRITE,

                           &s->interrupt_callback, &opts);



            av_dict_free(&opts);



            if (err < 0) {

                err = AVERROR_INVALIDDATA;

                goto fail;

            }

        }

        if ((err = ff_rtsp_open_transport_ctx(s, rtsp_st)))

            goto fail;

    }

    return 0;

fail:

    ff_rtsp_close_streams(s);

    ff_network_close();

    return err;

}

static void allocate_buffers(FLACContext *s){

    int i;



    assert(s->max_blocksize);



    if(s->max_framesize == 0 && s->max_blocksize){

        s->max_framesize= (s->channels * s->bps * s->max_blocksize + 7)/ 8; //FIXME header overhead

    }



    for (i = 0; i < s->channels; i++)

    {

        s->decoded[i] = av_realloc(s->decoded[i], sizeof(int32_t)*s->max_blocksize);

    }



    s->bitstream= av_fast_realloc(s->bitstream, &s->allocated_bitstream_size, s->max_framesize);

}

static void multi_serial_pci_realize(PCIDevice *dev, Error **errp)

{

    PCIDeviceClass *pc = PCI_DEVICE_GET_CLASS(dev);

    PCIMultiSerialState *pci = DO_UPCAST(PCIMultiSerialState, dev, dev);

    SerialState *s;

    Error *err = NULL;

    int i;



    switch (pc->device_id) {

    case 0x0003:

        pci->ports = 2;

        break;

    case 0x0004:

        pci->ports = 4;

        break;

    }

    assert(pci->ports > 0);

    assert(pci->ports <= PCI_SERIAL_MAX_PORTS);



    pci->dev.config[PCI_CLASS_PROG] = pci->prog_if;

    pci->dev.config[PCI_INTERRUPT_PIN] = 0x01;

    memory_region_init(&pci->iobar, OBJECT(pci), "multiserial", 8 * pci->ports);

    pci_register_bar(&pci->dev, 0, PCI_BASE_ADDRESS_SPACE_IO, &pci->iobar);

    pci->irqs = qemu_allocate_irqs(multi_serial_irq_mux, pci,

                                   pci->ports);



    for (i = 0; i < pci->ports; i++) {

        s = pci->state + i;

        s->baudbase = 115200;

        serial_realize_core(s, &err);

        if (err != NULL) {

            error_propagate(errp, err);

            return;

        }

        s->irq = pci->irqs[i];

        pci->name[i] = g_strdup_printf("uart #%d", i+1);

        memory_region_init_io(&s->io, OBJECT(pci), &serial_io_ops, s,

                              pci->name[i], 8);

        memory_region_add_subregion(&pci->iobar, 8 * i, &s->io);

    }

}

