static void gain_scale(G723_1_Context *p, int16_t * buf, int energy)

{

    int num, denom, gain, bits1, bits2;

    int i;



    num   = energy;

    denom = 0;

    for (i = 0; i < SUBFRAME_LEN; i++) {

        int64_t temp = buf[i] >> 2;

        temp  = av_clipl_int32(MUL64(temp, temp) << 1);

        denom = av_clipl_int32(denom + temp);

    }



    if (num && denom) {

        bits1   = normalize_bits(num,   31);

        bits2   = normalize_bits(denom, 31);

        num     = num << bits1 >> 1;

        denom <<= bits2;



        bits2 = 5 + bits1 - bits2;

        bits2 = FFMAX(0, bits2);



        gain = (num >> 1) / (denom >> 16);

        gain = square_root(gain << 16 >> bits2);

    } else {

        gain = 1 << 12;

    }



    for (i = 0; i < SUBFRAME_LEN; i++) {

        p->pf_gain = (15 * p->pf_gain + gain + (1 << 3)) >> 4;

        buf[i]     = av_clip_int16((buf[i] * (p->pf_gain + (p->pf_gain >> 4)) +

                                   (1 << 10)) >> 11);

    }

}

static void draw_curves(AVFilterContext *ctx, AVFilterLink *inlink, AVFrame *out)

{

    AudioNEqualizerContext *s = ctx->priv;

    char *colors, *color, *saveptr = NULL;

    int ch, i, n;



    colors = av_strdup(s->colors);

    if (!colors)

        return;



    memset(out->data[0], 0, s->h * out->linesize[0]);



    for (ch = 0; ch < inlink->channels; ch++) {

        uint8_t fg[4] = { 0xff, 0xff, 0xff, 0xff };

        int prev_v = -1;

        double f;



        color = av_strtok(ch == 0 ? colors : NULL, " |", &saveptr);

        if (color)

            av_parse_color(fg, color, -1, ctx);



        for (f = 0; f < s->w; f++) {

            double complex z;

            double complex H = 1;

            double w;

            int v, y, x;



            w = M_PI * (s->fscale ? pow(s->w - 1, f / s->w) : f) / (s->w - 1);

            z = 1. / cexp(I * w);



            for (n = 0; n < s->nb_filters; n++) {

                if (s->filters[n].channel != ch ||

                    s->filters[n].ignore)

                    continue;



                for (i = 0; i < FILTER_ORDER / 2; i++) {

                    FoSection *S = &s->filters[n].section[i];



                    H *= (((((S->b4 * z + S->b3) * z + S->b2) * z + S->b1) * z + S->b0) /

                          ((((S->a4 * z + S->a3) * z + S->a2) * z + S->a1) * z + S->a0));

                }

            }



            v = av_clip((1. + -20 * log10(cabs(H)) / s->mag) * s->h / 2, 0, s->h - 1);

            x = lrint(f);

            if (prev_v == -1)

                prev_v = v;

            if (v <= prev_v) {

                for (y = v; y <= prev_v; y++)

                    AV_WL32(out->data[0] + y * out->linesize[0] + x * 4, AV_RL32(fg));

            } else {

                for (y = prev_v; y <= v; y++)

                    AV_WL32(out->data[0] + y * out->linesize[0] + x * 4, AV_RL32(fg));

            }



            prev_v = v;

        }

    }



    av_free(colors);

}

void ff_rtp_send_aac(AVFormatContext *s1, const uint8_t *buff, int size)

{

    RTPMuxContext *s = s1->priv_data;

    int len, max_packet_size;

    uint8_t *p;

    const int max_frames_per_packet = s->max_frames_per_packet ? s->max_frames_per_packet : 5;

    const int max_au_headers_size = 2 + 2 * max_frames_per_packet;



    /* skip ADTS header, if present */

    if ((s1->streams[0]->codec->extradata_size) == 0) {

        size -= 7;

        buff += 7;

    }

    max_packet_size = s->max_payload_size - max_au_headers_size;



    /* test if the packet must be sent */

    len = (s->buf_ptr - s->buf);

    if ((s->num_frames == max_frames_per_packet) || (len && (len + size) > s->max_payload_size)) {

        int au_size = s->num_frames * 2;



        p = s->buf + max_au_headers_size - au_size - 2;

        if (p != s->buf) {

            memmove(p + 2, s->buf + 2, au_size);

        }

        /* Write the AU header size */

        p[0] = ((au_size * 8) & 0xFF) >> 8;

        p[1] = (au_size * 8) & 0xFF;



        ff_rtp_send_data(s1, p, s->buf_ptr - p, 1);



        s->num_frames = 0;

    }

    if (s->num_frames == 0) {

        s->buf_ptr = s->buf + max_au_headers_size;

        s->timestamp = s->cur_timestamp;

    }



    if (size <= max_packet_size) {

        p = s->buf + s->num_frames++ * 2 + 2;

        *p++ = size >> 5;

        *p = (size & 0x1F) << 3;

        memcpy(s->buf_ptr, buff, size);

        s->buf_ptr += size;

    } else {

        int au_size = size;



        max_packet_size = s->max_payload_size - 4;

        p = s->buf;

        p[0] = 0;

        p[1] = 16;

        while (size > 0) {

            len = FFMIN(size, max_packet_size);

            p[2] = au_size >> 5;

            p[3] = (au_size & 0x1F) << 3;

            memcpy(p + 4, buff, len);

            ff_rtp_send_data(s1, p, len + 4, len == size);

            size -= len;

            buff += len;

        }

    }

}

static BlockDriverAIOCB *raw_aio_writev(BlockDriverState *bs,

    int64_t sector_num, QEMUIOVector *qiov, int nb_sectors,

    BlockDriverCompletionFunc *cb, void *opaque)

{

    const uint8_t *first_buf;

    int first_buf_index = 0, i;



    /* This is probably being paranoid, but handle cases of zero size

       vectors. */

    for (i = 0; i < qiov->niov; i++) {

        if (qiov->iov[i].iov_len) {

            assert(qiov->iov[i].iov_len >= 512);

            first_buf_index = i;

            break;

        }

    }



    first_buf = qiov->iov[first_buf_index].iov_base;



    if (check_write_unsafe(bs, sector_num, first_buf, nb_sectors)) {

        RawScrubberBounce *b;

        int ret;



        /* write the first sector using sync I/O */

        ret = raw_write_scrubbed_bootsect(bs, first_buf);

        if (ret < 0) {

            return NULL;

        }



        /* adjust request to be everything but first sector */



        b = qemu_malloc(sizeof(*b));

        b->cb = cb;

        b->opaque = opaque;



        qemu_iovec_init(&b->qiov, qiov->nalloc);

        qemu_iovec_concat(&b->qiov, qiov, qiov->size);



        b->qiov.size -= 512;

        b->qiov.iov[first_buf_index].iov_base += 512;

        b->qiov.iov[first_buf_index].iov_len -= 512;



        return bdrv_aio_writev(bs->file, sector_num + 1, &b->qiov,

                               nb_sectors - 1, raw_aio_writev_scrubbed, b);

    }



    return bdrv_aio_writev(bs->file, sector_num, qiov, nb_sectors, cb, opaque);

}

