static MemTxResult gic_cpu_read(GICState *s, int cpu, int offset,

                                uint64_t *data, MemTxAttrs attrs)

{

    switch (offset) {

    case 0x00: /* Control */

        *data = s->cpu_enabled[cpu];

        break;

    case 0x04: /* Priority mask */

        *data = s->priority_mask[cpu];

        break;

    case 0x08: /* Binary Point */

        if (s->security_extn && !attrs.secure) {

            /* BPR is banked. Non-secure copy stored in ABPR. */

            *data = s->abpr[cpu];

        } else {

            *data = s->bpr[cpu];

        }

        break;

    case 0x0c: /* Acknowledge */

        *data = gic_acknowledge_irq(s, cpu);

        break;

    case 0x14: /* Running Priority */

        *data = s->running_priority[cpu];

        break;

    case 0x18: /* Highest Pending Interrupt */

        *data = s->current_pending[cpu];

        break;

    case 0x1c: /* Aliased Binary Point */

        /* GIC v2, no security: ABPR

         * GIC v1, no security: not implemented (RAZ/WI)

         * With security extensions, secure access: ABPR (alias of NS BPR)

         * With security extensions, nonsecure access: RAZ/WI

         */

        if (!gic_has_groups(s) || (s->security_extn && !attrs.secure)) {

            *data = 0;

        } else {

            *data = s->abpr[cpu];

        }

        break;

    case 0xd0: case 0xd4: case 0xd8: case 0xdc:

        *data = s->apr[(offset - 0xd0) / 4][cpu];

        break;

    default:

        qemu_log_mask(LOG_GUEST_ERROR,

                      "gic_cpu_read: Bad offset %x\n", (int)offset);

        return MEMTX_ERROR;

    }

    return MEMTX_OK;

}

static void msix_mmio_writel(void *opaque, target_phys_addr_t addr,

                             uint32_t val)

{

    PCIDevice *dev = opaque;

    unsigned int offset = addr & (MSIX_PAGE_SIZE - 1) & ~0x3;

    int vector = offset / MSIX_ENTRY_SIZE;

    pci_set_long(dev->msix_table_page + offset, val);

    if (!msix_is_masked(dev, vector) && msix_is_pending(dev, vector)) {

        msix_clr_pending(dev, vector);

        msix_notify(dev, vector);

    }

}

static void exynos4210_combiner_write(void *opaque, target_phys_addr_t offset,

        uint64_t val, unsigned size)

{

    struct Exynos4210CombinerState *s =

            (struct Exynos4210CombinerState *)opaque;

    uint32_t req_quad_base_n;    /* Base of registers quad. Multiply it by 4 and

                                   get a start of corresponding group quad */

    uint32_t grp_quad_base_n;    /* Base of group quad */

    uint32_t reg_n;              /* Register number inside the quad */



    req_quad_base_n = offset >> 4;

    grp_quad_base_n = req_quad_base_n << 2;

    reg_n = (offset - (req_quad_base_n << 4)) >> 2;



    if (req_quad_base_n >= IIC_NGRP) {

        hw_error("exynos4210.combiner: unallowed write access at offset 0x"

                TARGET_FMT_plx "\n", offset);

        return;

    }



    if (reg_n > 1) {

        hw_error("exynos4210.combiner: unallowed write access at offset 0x"

                TARGET_FMT_plx "\n", offset);

        return;

    }



    if (offset >> 2 >= IIC_REGSET_SIZE) {

        hw_error("exynos4210.combiner: overflow of reg_set by 0x"

                TARGET_FMT_plx "offset\n", offset);

    }

    s->reg_set[offset >> 2] = val;



    switch (reg_n) {

    /* IIESR */

    case 0:

        /* FIXME: what if irq is pending, allowed by mask, and we allow it

         * again. Interrupt will rise again! */



        DPRINTF("%s enable IRQ for groups %d, %d, %d, %d\n",

                s->external ? "EXT" : "INT",

                grp_quad_base_n,

                grp_quad_base_n + 1,

                grp_quad_base_n + 2,

                grp_quad_base_n + 3);



        /* Enable interrupt sources */

        s->group[grp_quad_base_n].src_mask |= val & 0xFF;

        s->group[grp_quad_base_n + 1].src_mask |= (val & 0xFF00) >> 8;

        s->group[grp_quad_base_n + 2].src_mask |= (val & 0xFF0000) >> 16;

        s->group[grp_quad_base_n + 3].src_mask |= (val & 0xFF000000) >> 24;



        exynos4210_combiner_update(s, grp_quad_base_n);

        exynos4210_combiner_update(s, grp_quad_base_n + 1);

        exynos4210_combiner_update(s, grp_quad_base_n + 2);

        exynos4210_combiner_update(s, grp_quad_base_n + 3);

        break;

        /* IIECR */

    case 1:

        DPRINTF("%s disable IRQ for groups %d, %d, %d, %d\n",

                s->external ? "EXT" : "INT",

                grp_quad_base_n,

                grp_quad_base_n + 1,

                grp_quad_base_n + 2,

                grp_quad_base_n + 3);



        /* Disable interrupt sources */

        s->group[grp_quad_base_n].src_mask &= ~(val & 0xFF);

        s->group[grp_quad_base_n + 1].src_mask &= ~((val & 0xFF00) >> 8);

        s->group[grp_quad_base_n + 2].src_mask &= ~((val & 0xFF0000) >> 16);

        s->group[grp_quad_base_n + 3].src_mask &= ~((val & 0xFF000000) >> 24);



        exynos4210_combiner_update(s, grp_quad_base_n);

        exynos4210_combiner_update(s, grp_quad_base_n + 1);

        exynos4210_combiner_update(s, grp_quad_base_n + 2);

        exynos4210_combiner_update(s, grp_quad_base_n + 3);

        break;

    default:

        hw_error("exynos4210.combiner: unallowed write access at offset 0x"

                TARGET_FMT_plx "\n", offset);

        break;

    }

}

void qmp_blockdev_change_medium(bool has_device, const char *device,

                                bool has_id, const char *id,

                                const char *filename,

                                bool has_format, const char *format,

                                bool has_read_only,

                                BlockdevChangeReadOnlyMode read_only,

                                Error **errp)

{

    BlockBackend *blk;

    BlockDriverState *medium_bs = NULL;

    int bdrv_flags;

    int rc;

    QDict *options = NULL;

    Error *err = NULL;



    blk = qmp_get_blk(has_device ? device : NULL,

                      has_id ? id : NULL,

                      errp);

    if (!blk) {

        goto fail;

    }



    if (blk_bs(blk)) {

        blk_update_root_state(blk);

    }



    bdrv_flags = blk_get_open_flags_from_root_state(blk);

    bdrv_flags &= ~(BDRV_O_TEMPORARY | BDRV_O_SNAPSHOT | BDRV_O_NO_BACKING |

        BDRV_O_PROTOCOL);



    if (!has_read_only) {

        read_only = BLOCKDEV_CHANGE_READ_ONLY_MODE_RETAIN;

    }



    switch (read_only) {

    case BLOCKDEV_CHANGE_READ_ONLY_MODE_RETAIN:

        break;



    case BLOCKDEV_CHANGE_READ_ONLY_MODE_READ_ONLY:

        bdrv_flags &= ~BDRV_O_RDWR;

        break;



    case BLOCKDEV_CHANGE_READ_ONLY_MODE_READ_WRITE:

        bdrv_flags |= BDRV_O_RDWR;

        break;



    default:

        abort();

    }



    if (has_format) {

        options = qdict_new();

        qdict_put(options, "driver", qstring_from_str(format));

    }



    medium_bs = bdrv_open(filename, NULL, options, bdrv_flags, errp);

    if (!medium_bs) {

        goto fail;

    }



    bdrv_add_key(medium_bs, NULL, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    rc = do_open_tray(has_device ? device : NULL,

                      has_id ? id : NULL,

                      false, &err);

    if (rc && rc != -ENOSYS) {

        error_propagate(errp, err);

        goto fail;

    }

    error_free(err);

    err = NULL;



    qmp_x_blockdev_remove_medium(has_device, device, has_id, id, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    qmp_blockdev_insert_anon_medium(blk, medium_bs, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    blk_apply_root_state(blk, medium_bs);



    qmp_blockdev_close_tray(has_device, device, has_id, id, errp);



fail:

    /* If the medium has been inserted, the device has its own reference, so

     * ours must be relinquished; and if it has not been inserted successfully,

     * the reference must be relinquished anyway */

    bdrv_unref(medium_bs);

}

