static void gen_adc(TCGv t0, TCGv t1)

{

    TCGv tmp;

    tcg_gen_add_i32(t0, t0, t1);

    tmp = load_cpu_field(CF);

    tcg_gen_add_i32(t0, t0, tmp);

    dead_tmp(tmp);

}

static void integratorcm_write(void *opaque, target_phys_addr_t offset,

                               uint64_t value, unsigned size)

{

    integratorcm_state *s = (integratorcm_state *)opaque;

    switch (offset >> 2) {

    case 2: /* CM_OSC */

        if (s->cm_lock == 0xa05f)

            s->cm_osc = value;

        break;

    case 3: /* CM_CTRL */

        integratorcm_set_ctrl(s, value);

        break;

    case 5: /* CM_LOCK */

        s->cm_lock = value & 0xffff;

        break;

    case 7: /* CM_AUXOSC */

        if (s->cm_lock == 0xa05f)

            s->cm_auxosc = value;

        break;

    case 8: /* CM_SDRAM */

        s->cm_sdram = value;

        break;

    case 9: /* CM_INIT */

        /* ??? This can change the memory bus frequency.  */

        s->cm_init = value;

        break;

    case 12: /* CM_FLAGSS */

        s->cm_flags |= value;

        break;

    case 13: /* CM_FLAGSC */

        s->cm_flags &= ~value;

        break;

    case 14: /* CM_NVFLAGSS */

        s->cm_nvflags |= value;

        break;

    case 15: /* CM_NVFLAGSS */

        s->cm_nvflags &= ~value;

        break;

    case 18: /* CM_IRQ_ENSET */

        s->irq_enabled |= value;

        integratorcm_update(s);

        break;

    case 19: /* CM_IRQ_ENCLR */

        s->irq_enabled &= ~value;

        integratorcm_update(s);

        break;

    case 20: /* CM_SOFT_INTSET */

        s->int_level |= (value & 1);

        integratorcm_update(s);

        break;

    case 21: /* CM_SOFT_INTCLR */

        s->int_level &= ~(value & 1);

        integratorcm_update(s);

        break;

    case 26: /* CM_FIQ_ENSET */

        s->fiq_enabled |= value;

        integratorcm_update(s);

        break;

    case 27: /* CM_FIQ_ENCLR */

        s->fiq_enabled &= ~value;

        integratorcm_update(s);

        break;

    case 32: /* CM_VOLTAGE_CTL0 */

    case 33: /* CM_VOLTAGE_CTL1 */

    case 34: /* CM_VOLTAGE_CTL2 */

    case 35: /* CM_VOLTAGE_CTL3 */

        /* ??? Voltage control unimplemented.  */

        break;

    default:

        hw_error("integratorcm_write: Unimplemented offset 0x%x\n",

                 (int)offset);

        break;

    }

}

static int get_stream_blocksize(BlockDriverState *bdrv)

{

    uint8_t cmd[6];

    uint8_t buf[12];

    uint8_t sensebuf[8];

    sg_io_hdr_t io_header;

    int ret;



    memset(cmd, 0, sizeof(cmd));

    memset(buf, 0, sizeof(buf));

    cmd[0] = MODE_SENSE;

    cmd[4] = sizeof(buf);



    memset(&io_header, 0, sizeof(io_header));

    io_header.interface_id = 'S';

    io_header.dxfer_direction = SG_DXFER_FROM_DEV;

    io_header.dxfer_len = sizeof(buf);

    io_header.dxferp = buf;

    io_header.cmdp = cmd;

    io_header.cmd_len = sizeof(cmd);

    io_header.mx_sb_len = sizeof(sensebuf);

    io_header.sbp = sensebuf;

    io_header.timeout = 6000; /* XXX */



    ret = bdrv_ioctl(bdrv, SG_IO, &io_header);

    if (ret < 0 || io_header.driver_status || io_header.host_status) {

        return -1;

    }

    return (buf[9] << 16) | (buf[10] << 8) | buf[11];

}

static ExitStatus trans_log(DisasContext *ctx, uint32_t insn,

                            const DisasInsn *di)

{

    unsigned r2 = extract32(insn, 21, 5);

    unsigned r1 = extract32(insn, 16, 5);

    unsigned cf = extract32(insn, 12, 4);

    unsigned rt = extract32(insn,  0, 5);

    TCGv tcg_r1, tcg_r2;

    ExitStatus ret;



    if (cf) {

        nullify_over(ctx);

    }

    tcg_r1 = load_gpr(ctx, r1);

    tcg_r2 = load_gpr(ctx, r2);

    ret = do_log(ctx, rt, tcg_r1, tcg_r2, cf, di->f_ttt);

    return nullify_end(ctx, ret);

}

static int decode(AVCodecContext *avctx, void *data, int *got_sub, AVPacket *avpkt)

{

    CCaptionSubContext *ctx = avctx->priv_data;

    AVSubtitle *sub = data;

    const int64_t start_time = sub->pts;

    uint8_t *bptr = NULL;

    int len = avpkt->size;

    int ret = 0;

    int i;



    if (ctx->pktbuf->size < len) {

        ret = av_buffer_realloc(&ctx->pktbuf, len);

         if (ret < 0) {

            av_log(ctx, AV_LOG_WARNING, "Insufficient Memory of %d truncated to %d\n", len, ctx->pktbuf->size);

            len = ctx->pktbuf->size;

            ret = 0;

        }

    }

    memcpy(ctx->pktbuf->data, avpkt->data, len);

    bptr = ctx->pktbuf->data;



    for (i  = 0; i < len; i += 3) {

        uint8_t cc_type = *(bptr + i) & 3;

        if (validate_cc_data_pair(bptr + i))

            continue;

        /* ignoring data field 1 */

        if(cc_type == 1)

            continue;

        else

            process_cc608(ctx, start_time, *(bptr + i + 1) & 0x7f, *(bptr + i + 2) & 0x7f);



        if (!ctx->buffer_changed)

            continue;

        ctx->buffer_changed = 0;



        if (*ctx->buffer.str || ctx->real_time)

        {

            ff_dlog(ctx, "cdp writing data (%s)\n",ctx->buffer.str);

            ret = ff_ass_add_rect(sub, ctx->buffer.str, ctx->readorder++, 0, NULL, NULL);

            if (ret < 0)

                return ret;

            sub->pts = ctx->start_time;

            if (!ctx->real_time)

                sub->end_display_time = av_rescale_q(ctx->end_time - ctx->start_time,

                                                     AV_TIME_BASE_Q, ms_tb);

            else

                sub->end_display_time = -1;

            ctx->buffer_changed = 0;

            ctx->last_real_time = sub->pts;

            ctx->screen_touched = 0;

        }

    }



    if (ctx->real_time && ctx->screen_touched &&

        sub->pts > ctx->last_real_time + av_rescale_q(200, ms_tb, AV_TIME_BASE_Q)) {

        ctx->last_real_time = sub->pts;

        ctx->screen_touched = 0;



        capture_screen(ctx);

        ctx->buffer_changed = 0;



        ret = ff_ass_add_rect(sub, ctx->buffer.str, ctx->readorder++, 0, NULL, NULL);

        if (ret < 0)

            return ret;

        sub->end_display_time = -1;

    }



    *got_sub = sub->num_rects > 0;

    return ret;

}

static TraceEvent* find_trace_event_by_name(const char *tname)

{

    unsigned int i;



    if (!tname) {

        return NULL;

    }



    for (i = 0; i < NR_TRACE_EVENTS; i++) {

        if (!strcmp(trace_list[i].tp_name, tname)) {

            return &trace_list[i];

        }

    }

    return NULL; /* indicates end of list reached without a match */

}

