static int vmdk_read(BlockDriverState *bs, int64_t sector_num,

                    uint8_t *buf, int nb_sectors)

{

    BDRVVmdkState *s = bs->opaque;

    int ret;

    uint64_t n, index_in_cluster;

    VmdkExtent *extent = NULL;

    uint64_t cluster_offset;



    while (nb_sectors > 0) {

        extent = find_extent(s, sector_num, extent);

        if (!extent) {

            return -EIO;

        }

        ret = get_cluster_offset(

                            bs, extent, NULL,

                            sector_num << 9, 0, &cluster_offset);

        index_in_cluster = sector_num % extent->cluster_sectors;

        n = extent->cluster_sectors - index_in_cluster;

        if (n > nb_sectors)

            n = nb_sectors;

        if (ret) {

            /* if not allocated, try to read from parent image, if exist */

            if (bs->backing_hd) {

                if (!vmdk_is_cid_valid(bs))

                    return -EINVAL;

                ret = bdrv_read(bs->backing_hd, sector_num, buf, n);

                if (ret < 0)

                    return ret;

            } else {

                memset(buf, 0, 512 * n);

            }

        } else {

            ret = bdrv_pread(extent->file,

                            cluster_offset + index_in_cluster * 512,

                            buf, n * 512);

            if (ret < 0) {

                return ret;

            }

        }

        nb_sectors -= n;

        sector_num += n;

        buf += n * 512;

    }

    return 0;

}

static av_cold int X264_init(AVCodecContext *avctx)

{

    X264Context *x4 = avctx->priv_data;

    int sw,sh;



    if (avctx->global_quality > 0)

        av_log(avctx, AV_LOG_WARNING, "-qscale is ignored, -crf is recommended.\n");



    x264_param_default(&x4->params);



    x4->params.b_deblocking_filter         = avctx->flags & CODEC_FLAG_LOOP_FILTER;



    if (x4->preset || x4->tune)

        if (x264_param_default_preset(&x4->params, x4->preset, x4->tune) < 0) {

            int i;

            av_log(avctx, AV_LOG_ERROR, "Error setting preset/tune %s/%s.\n", x4->preset, x4->tune);

            av_log(avctx, AV_LOG_INFO, "Possible presets:");

            for (i = 0; x264_preset_names[i]; i++)

                av_log(avctx, AV_LOG_INFO, " %s", x264_preset_names[i]);

            av_log(avctx, AV_LOG_INFO, "\n");

            av_log(avctx, AV_LOG_INFO, "Possible tunes:");

            for (i = 0; x264_tune_names[i]; i++)

                av_log(avctx, AV_LOG_INFO, " %s", x264_tune_names[i]);

            av_log(avctx, AV_LOG_INFO, "\n");

            return AVERROR(EINVAL);

        }



    if (avctx->level > 0)

        x4->params.i_level_idc = avctx->level;



    x4->params.pf_log               = X264_log;

    x4->params.p_log_private        = avctx;

    x4->params.i_log_level          = X264_LOG_DEBUG;

    x4->params.i_csp                = convert_pix_fmt(avctx->pix_fmt);



    OPT_STR("weightp", x4->wpredp);



    if (avctx->bit_rate) {

        x4->params.rc.i_bitrate   = avctx->bit_rate / 1000;

        x4->params.rc.i_rc_method = X264_RC_ABR;

    }

    x4->params.rc.i_vbv_buffer_size = avctx->rc_buffer_size / 1000;

    x4->params.rc.i_vbv_max_bitrate = avctx->rc_max_rate    / 1000;

    x4->params.rc.b_stat_write      = avctx->flags & CODEC_FLAG_PASS1;

    if (avctx->flags & CODEC_FLAG_PASS2) {

        x4->params.rc.b_stat_read = 1;

    } else {

        if (x4->crf >= 0) {

            x4->params.rc.i_rc_method   = X264_RC_CRF;

            x4->params.rc.f_rf_constant = x4->crf;

        } else if (x4->cqp >= 0) {

            x4->params.rc.i_rc_method   = X264_RC_CQP;

            x4->params.rc.i_qp_constant = x4->cqp;

        }



        if (x4->crf_max >= 0)

            x4->params.rc.f_rf_constant_max = x4->crf_max;

    }



    if (avctx->rc_buffer_size && avctx->rc_initial_buffer_occupancy > 0 &&

        (avctx->rc_initial_buffer_occupancy <= avctx->rc_buffer_size)) {

        x4->params.rc.f_vbv_buffer_init =

            (float)avctx->rc_initial_buffer_occupancy / avctx->rc_buffer_size;

    }



    OPT_STR("level", x4->level);



    if (avctx->i_quant_factor > 0)

        x4->params.rc.f_ip_factor         = 1 / fabs(avctx->i_quant_factor);

    if (avctx->b_quant_factor > 0)

        x4->params.rc.f_pb_factor         = avctx->b_quant_factor;

    if (avctx->chromaoffset)

        x4->params.analyse.i_chroma_qp_offset = avctx->chromaoffset;



    if (avctx->me_method == ME_EPZS)

        x4->params.analyse.i_me_method = X264_ME_DIA;

    else if (avctx->me_method == ME_HEX)

        x4->params.analyse.i_me_method = X264_ME_HEX;

    else if (avctx->me_method == ME_UMH)

        x4->params.analyse.i_me_method = X264_ME_UMH;

    else if (avctx->me_method == ME_FULL)

        x4->params.analyse.i_me_method = X264_ME_ESA;

    else if (avctx->me_method == ME_TESA)

        x4->params.analyse.i_me_method = X264_ME_TESA;



    if (avctx->gop_size >= 0)

        x4->params.i_keyint_max         = avctx->gop_size;

    if (avctx->max_b_frames >= 0)

        x4->params.i_bframe             = avctx->max_b_frames;

    if (avctx->scenechange_threshold >= 0)

        x4->params.i_scenecut_threshold = avctx->scenechange_threshold;

    if (avctx->qmin >= 0)

        x4->params.rc.i_qp_min          = avctx->qmin;

    if (avctx->qmax >= 0)

        x4->params.rc.i_qp_max          = avctx->qmax;

    if (avctx->max_qdiff >= 0)

        x4->params.rc.i_qp_step         = avctx->max_qdiff;

    if (avctx->qblur >= 0)

        x4->params.rc.f_qblur           = avctx->qblur;     /* temporally blur quants */

    if (avctx->qcompress >= 0)

        x4->params.rc.f_qcompress       = avctx->qcompress; /* 0.0 => cbr, 1.0 => constant qp */

    if (avctx->refs >= 0)

        x4->params.i_frame_reference    = avctx->refs;

    else if (x4->level) {

        int i;

        int mbn = FF_CEIL_RSHIFT(avctx->width, 4) * FF_CEIL_RSHIFT(avctx->height, 4);

        int level_id = -1;

        char *tail;

        int scale = X264_BUILD < 129 ? 384 : 1;



        if (!strcmp(x4->level, "1b")) {

            level_id = 9;

        } else if (strlen(x4->level) <= 3){

            level_id = av_strtod(x4->level, &tail) * 10 + 0.5;

            if (*tail)

                level_id = -1;

        }

        if (level_id <= 0)

            av_log(avctx, AV_LOG_WARNING, "Failed to parse level\n");



        for (i = 0; i<x264_levels[i].level_idc; i++)

            if (x264_levels[i].level_idc == level_id)

                x4->params.i_frame_reference = av_clip(x264_levels[i].dpb / mbn / scale, 1, x4->params.i_frame_reference);

    }



    if (avctx->trellis >= 0)

        x4->params.analyse.i_trellis    = avctx->trellis;

    if (avctx->me_range >= 0)

        x4->params.analyse.i_me_range   = avctx->me_range;

    if (avctx->noise_reduction >= 0)

        x4->params.analyse.i_noise_reduction = avctx->noise_reduction;

    if (avctx->me_subpel_quality >= 0)

        x4->params.analyse.i_subpel_refine   = avctx->me_subpel_quality;

    if (avctx->b_frame_strategy >= 0)

        x4->params.i_bframe_adaptive = avctx->b_frame_strategy;

    if (avctx->keyint_min >= 0)

        x4->params.i_keyint_min = avctx->keyint_min;

    if (avctx->coder_type >= 0)

        x4->params.b_cabac = avctx->coder_type == FF_CODER_TYPE_AC;

    if (avctx->me_cmp >= 0)

        x4->params.analyse.b_chroma_me = avctx->me_cmp & FF_CMP_CHROMA;



    if (x4->aq_mode >= 0)

        x4->params.rc.i_aq_mode = x4->aq_mode;

    if (x4->aq_strength >= 0)

        x4->params.rc.f_aq_strength = x4->aq_strength;

    PARSE_X264_OPT("psy-rd", psy_rd);

    PARSE_X264_OPT("deblock", deblock);

    PARSE_X264_OPT("partitions", partitions);

    PARSE_X264_OPT("stats", stats);

    if (x4->psy >= 0)

        x4->params.analyse.b_psy  = x4->psy;

    if (x4->rc_lookahead >= 0)

        x4->params.rc.i_lookahead = x4->rc_lookahead;

    if (x4->weightp >= 0)

        x4->params.analyse.i_weighted_pred = x4->weightp;

    if (x4->weightb >= 0)

        x4->params.analyse.b_weighted_bipred = x4->weightb;

    if (x4->cplxblur >= 0)

        x4->params.rc.f_complexity_blur = x4->cplxblur;



    if (x4->ssim >= 0)

        x4->params.analyse.b_ssim = x4->ssim;

    if (x4->intra_refresh >= 0)

        x4->params.b_intra_refresh = x4->intra_refresh;

    if (x4->bluray_compat >= 0) {

        x4->params.b_bluray_compat = x4->bluray_compat;

        x4->params.b_vfr_input = 0;

    }

    if (x4->avcintra_class >= 0)

#if X264_BUILD >= 142

        x4->params.i_avcintra_class = x4->avcintra_class;

#else

        av_log(avctx, AV_LOG_ERROR,

               "x264 too old for AVC Intra, at least version 142 needed\n");

#endif

    if (x4->b_bias != INT_MIN)

        x4->params.i_bframe_bias              = x4->b_bias;

    if (x4->b_pyramid >= 0)

        x4->params.i_bframe_pyramid = x4->b_pyramid;

    if (x4->mixed_refs >= 0)

        x4->params.analyse.b_mixed_references = x4->mixed_refs;

    if (x4->dct8x8 >= 0)

        x4->params.analyse.b_transform_8x8    = x4->dct8x8;

    if (x4->fast_pskip >= 0)

        x4->params.analyse.b_fast_pskip       = x4->fast_pskip;

    if (x4->aud >= 0)

        x4->params.b_aud                      = x4->aud;

    if (x4->mbtree >= 0)

        x4->params.rc.b_mb_tree               = x4->mbtree;

    if (x4->direct_pred >= 0)

        x4->params.analyse.i_direct_mv_pred   = x4->direct_pred;



    if (x4->slice_max_size >= 0)

        x4->params.i_slice_max_size =  x4->slice_max_size;

    else {

        /*

         * Allow x264 to be instructed through AVCodecContext about the maximum

         * size of the RTP payload. For example, this enables the production of

         * payload suitable for the H.264 RTP packetization-mode 0 i.e. single

         * NAL unit per RTP packet.

         */

        if (avctx->rtp_payload_size)

            x4->params.i_slice_max_size = avctx->rtp_payload_size;

    }



    if (x4->fastfirstpass)

        x264_param_apply_fastfirstpass(&x4->params);



    /* Allow specifying the x264 profile through AVCodecContext. */

    if (!x4->profile)

        switch (avctx->profile) {

        case FF_PROFILE_H264_BASELINE:

            x4->profile = av_strdup("baseline");

            break;

        case FF_PROFILE_H264_HIGH:

            x4->profile = av_strdup("high");

            break;

        case FF_PROFILE_H264_HIGH_10:

            x4->profile = av_strdup("high10");

            break;

        case FF_PROFILE_H264_HIGH_422:

            x4->profile = av_strdup("high422");

            break;

        case FF_PROFILE_H264_HIGH_444:

            x4->profile = av_strdup("high444");

            break;

        case FF_PROFILE_H264_MAIN:

            x4->profile = av_strdup("main");

            break;

        default:

            break;

        }



    if (x4->nal_hrd >= 0)

        x4->params.i_nal_hrd = x4->nal_hrd;



    if (x4->profile)

        if (x264_param_apply_profile(&x4->params, x4->profile) < 0) {

            int i;

            av_log(avctx, AV_LOG_ERROR, "Error setting profile %s.\n", x4->profile);

            av_log(avctx, AV_LOG_INFO, "Possible profiles:");

            for (i = 0; x264_profile_names[i]; i++)

                av_log(avctx, AV_LOG_INFO, " %s", x264_profile_names[i]);

            av_log(avctx, AV_LOG_INFO, "\n");

            return AVERROR(EINVAL);

        }



    x4->params.i_width          = avctx->width;

    x4->params.i_height         = avctx->height;

    av_reduce(&sw, &sh, avctx->sample_aspect_ratio.num, avctx->sample_aspect_ratio.den, 4096);

    x4->params.vui.i_sar_width  = sw;

    x4->params.vui.i_sar_height = sh;

    x4->params.i_timebase_den = avctx->time_base.den;

    x4->params.i_timebase_num = avctx->time_base.num;

    x4->params.i_fps_num = avctx->time_base.den;

    x4->params.i_fps_den = avctx->time_base.num * avctx->ticks_per_frame;



    x4->params.analyse.b_psnr = avctx->flags & CODEC_FLAG_PSNR;



    x4->params.i_threads      = avctx->thread_count;

    if (avctx->thread_type)

        x4->params.b_sliced_threads = avctx->thread_type == FF_THREAD_SLICE;



    x4->params.b_interlaced   = avctx->flags & CODEC_FLAG_INTERLACED_DCT;



    x4->params.b_open_gop     = !(avctx->flags & CODEC_FLAG_CLOSED_GOP);



    x4->params.i_slice_count  = avctx->slices;



    x4->params.vui.b_fullrange = avctx->pix_fmt == AV_PIX_FMT_YUVJ420P ||

                                 avctx->pix_fmt == AV_PIX_FMT_YUVJ422P ||

                                 avctx->pix_fmt == AV_PIX_FMT_YUVJ444P ||

                                 avctx->color_range == AVCOL_RANGE_JPEG;



    if (avctx->colorspace != AVCOL_SPC_UNSPECIFIED)

        x4->params.vui.i_colmatrix = avctx->colorspace;

    if (avctx->color_primaries != AVCOL_PRI_UNSPECIFIED)

        x4->params.vui.i_colorprim = avctx->color_primaries;

    if (avctx->color_trc != AVCOL_TRC_UNSPECIFIED)

        x4->params.vui.i_transfer  = avctx->color_trc;



    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER)

        x4->params.b_repeat_headers = 0;



    if(x4->x264opts){

        const char *p= x4->x264opts;

        while(p){

            char param[256]={0}, val[256]={0};

            if(sscanf(p, "%255[^:=]=%255[^:]", param, val) == 1){

                OPT_STR(param, "1");

            }else

                OPT_STR(param, val);

            p= strchr(p, ':');

            p+=!!p;

        }

    }



    if (x4->x264_params) {

        AVDictionary *dict    = NULL;

        AVDictionaryEntry *en = NULL;



        if (!av_dict_parse_string(&dict, x4->x264_params, "=", ":", 0)) {

            while ((en = av_dict_get(dict, "", en, AV_DICT_IGNORE_SUFFIX))) {

                if (x264_param_parse(&x4->params, en->key, en->value) < 0)

                    av_log(avctx, AV_LOG_WARNING,

                           "Error parsing option '%s = %s'.\n",

                            en->key, en->value);

            }



            av_dict_free(&dict);

        }

    }



    // update AVCodecContext with x264 parameters

    avctx->has_b_frames = x4->params.i_bframe ?

        x4->params.i_bframe_pyramid ? 2 : 1 : 0;

    if (avctx->max_b_frames < 0)

        avctx->max_b_frames = 0;



    avctx->bit_rate = x4->params.rc.i_bitrate*1000;



    x4->enc = x264_encoder_open(&x4->params);

    if (!x4->enc)

        return -1;



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame)

        return AVERROR(ENOMEM);



    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER) {

        x264_nal_t *nal;

        uint8_t *p;

        int nnal, s, i;



        s = x264_encoder_headers(x4->enc, &nal, &nnal);

        avctx->extradata = p = av_malloc(s);





        for (i = 0; i < nnal; i++) {

            /* Don't put the SEI in extradata. */

            if (nal[i].i_type == NAL_SEI) {

                av_log(avctx, AV_LOG_INFO, "%s\n", nal[i].p_payload+25);

                x4->sei_size = nal[i].i_payload;

                x4->sei      = av_malloc(x4->sei_size);

                if (!x4->sei)


                memcpy(x4->sei, nal[i].p_payload, nal[i].i_payload);

                continue;

            }

            memcpy(p, nal[i].p_payload, nal[i].i_payload);

            p += nal[i].i_payload;

        }

        avctx->extradata_size = p - avctx->extradata;

    }



    return 0;

nomem:

    X264_close(avctx);

    return AVERROR(ENOMEM);

}

static void memcard_write(void *opaque, target_phys_addr_t addr, uint64_t value,

                          unsigned size)

{

    MilkymistMemcardState *s = opaque;



    trace_milkymist_memcard_memory_write(addr, value);



    addr >>= 2;

    switch (addr) {

    case R_PENDING:

        /* clear rx pending bits */

        s->regs[R_PENDING] &= ~(value & (PENDING_CMD_RX | PENDING_DAT_RX));

        update_pending_bits(s);

        break;

    case R_CMD:

        if (!s->enabled) {

            break;

        }

        if (s->ignore_next_cmd) {

            s->ignore_next_cmd = 0;

            break;

        }

        s->command[s->command_write_ptr] = value & 0xff;

        s->command_write_ptr = (s->command_write_ptr + 1) % 6;

        if (s->command_write_ptr == 0) {

            memcard_sd_command(s);

        }

        break;

    case R_DAT:

        if (!s->enabled) {

            break;

        }

        sd_write_data(s->card, (value >> 24) & 0xff);

        sd_write_data(s->card, (value >> 16) & 0xff);

        sd_write_data(s->card, (value >> 8) & 0xff);

        sd_write_data(s->card, value & 0xff);

        break;

    case R_ENABLE:

        s->regs[addr] = value;

        update_pending_bits(s);

        break;

    case R_CLK2XDIV:

    case R_START:

        s->regs[addr] = value;

        break;



    default:

        error_report("milkymist_memcard: write access to unknown register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    }

}

