static void rtas_ibm_slot_error_detail(PowerPCCPU *cpu,

                                       sPAPREnvironment *spapr,

                                       uint32_t token, uint32_t nargs,

                                       target_ulong args, uint32_t nret,

                                       target_ulong rets)

{

    sPAPRPHBState *sphb;

    sPAPRPHBClass *spc;

    int option;

    uint64_t buid;



    if ((nargs != 8) || (nret != 1)) {

        goto param_error_exit;

    }



    buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    sphb = find_phb(spapr, buid);

    if (!sphb) {

        goto param_error_exit;

    }



    spc = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(sphb);

    if (!spc->eeh_set_option) {

        goto param_error_exit;

    }



    option = rtas_ld(args, 7);

    switch (option) {

    case RTAS_SLOT_TEMP_ERR_LOG:

    case RTAS_SLOT_PERM_ERR_LOG:

        break;

    default:

        goto param_error_exit;

    }



    /* We don't have error log yet */

    rtas_st(rets, 0, RTAS_OUT_NO_ERRORS_FOUND);

    return;



param_error_exit:

    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

}

static uint32_t ide_ioport_read(void *opaque, uint32_t addr1)

{

    IDEState *ide_if = opaque;

    IDEState *s = ide_if->cur_drive;

    uint32_t addr;

    int ret, hob;



    addr = addr1 & 7;

    /* FIXME: HOB readback uses bit 7, but it's always set right now */

    //hob = s->select & (1 << 7);

    hob = 0;

    switch(addr) {

    case 0:

        ret = 0xff;

        break;

    case 1:

        if (!ide_if[0].bs && !ide_if[1].bs)

            ret = 0;

        else if (!hob)

            ret = s->error;

	else

	    ret = s->hob_feature;

        break;

    case 2:

        if (!ide_if[0].bs && !ide_if[1].bs)

            ret = 0;

        else if (!hob)

            ret = s->nsector & 0xff;

	else

	    ret = s->hob_nsector;

        break;

    case 3:

        if (!ide_if[0].bs && !ide_if[1].bs)

            ret = 0;

        else if (!hob)

            ret = s->sector;

	else

	    ret = s->hob_sector;

        break;

    case 4:

        if (!ide_if[0].bs && !ide_if[1].bs)

            ret = 0;

        else if (!hob)

            ret = s->lcyl;

	else

	    ret = s->hob_lcyl;

        break;

    case 5:

        if (!ide_if[0].bs && !ide_if[1].bs)

            ret = 0;

        else if (!hob)

            ret = s->hcyl;

	else

	    ret = s->hob_hcyl;

        break;

    case 6:

        if (!ide_if[0].bs && !ide_if[1].bs)

            ret = 0;

        else

            ret = s->select;

        break;

    default:

    case 7:

        if ((!ide_if[0].bs && !ide_if[1].bs) ||

            (s != ide_if && !s->bs))

            ret = 0;

        else

            ret = s->status;

        qemu_irq_lower(s->irq);

        break;

    }

#ifdef DEBUG_IDE

    printf("ide: read addr=0x%x val=%02x\n", addr1, ret);

#endif

    return ret;

}

int main(int argc, char *argv[])

{

    int fd_in, fd_out, comp_len, uncomp_len, i, last_out;

    char buf_in[1024], buf_out[65536];

    z_stream zstream;

    struct stat statbuf;



    if (argc < 3) {

        printf("Usage: %s <infile.swf> <outfile.swf>\n", argv[0]);

        return 1;

    }



    fd_in = open(argv[1], O_RDONLY);

    if (fd_in < 0) {

        perror("Error opening input file");

        return 1;

    }



    fd_out = open(argv[2], O_WRONLY | O_CREAT, 00644);

    if (fd_out < 0) {

        perror("Error opening output file");

        close(fd_in);

        return 1;

    }



    if (read(fd_in, &buf_in, 8) != 8) {

        printf("Header error\n");

        close(fd_in);

        close(fd_out);

        return 1;

    }



    if (buf_in[0] != 'C' || buf_in[1] != 'W' || buf_in[2] != 'S') {

        printf("Not a compressed flash file\n");

        return 1;

    }



    fstat(fd_in, &statbuf);

    comp_len   = statbuf.st_size;

    uncomp_len = buf_in[4] | (buf_in[5] << 8) | (buf_in[6] << 16) | (buf_in[7] << 24);



    printf("Compressed size: %d Uncompressed size: %d\n",

           comp_len - 4, uncomp_len - 4);



    // write out modified header

    buf_in[0] = 'F';

    if (write(fd_out, &buf_in, 8) < 8) {

        perror("Error writing output file");

        return 1;

    }



    zstream.zalloc = NULL;

    zstream.zfree  = NULL;

    zstream.opaque = NULL;

    if (inflateInit(&zstream) != Z_OK) {

        fprintf(stderr, "inflateInit failed\n");

        return 1;

    }



    for (i = 0; i < comp_len - 8;) {

        int ret, len = read(fd_in, &buf_in, 1024);



        dbgprintf("read %d bytes\n", len);



        last_out = zstream.total_out;



        zstream.next_in   = &buf_in[0];

        zstream.avail_in  = len;

        zstream.next_out  = &buf_out[0];

        zstream.avail_out = 65536;



        ret = inflate(&zstream, Z_SYNC_FLUSH);

        if (ret != Z_STREAM_END && ret != Z_OK) {

            printf("Error while decompressing: %d\n", ret);

            inflateEnd(&zstream);

            return 1;

        }



        dbgprintf("a_in: %d t_in: %lu a_out: %d t_out: %lu -- %lu out\n",

                  zstream.avail_in, zstream.total_in, zstream.avail_out,

                  zstream.total_out, zstream.total_out - last_out);



        if (write(fd_out, &buf_out, zstream.total_out - last_out) <

            zstream.total_out - last_out) {

            perror("Error writing output file");

            return 1;

        }



        i += len;



        if (ret == Z_STREAM_END || ret == Z_BUF_ERROR)

            break;

    }



    if (zstream.total_out != uncomp_len - 8) {

        printf("Size mismatch (%lu != %d), updating header...\n",

               zstream.total_out, uncomp_len - 8);



        buf_in[0] =  (zstream.total_out + 8)        & 0xff;

        buf_in[1] = ((zstream.total_out + 8) >>  8) & 0xff;

        buf_in[2] = ((zstream.total_out + 8) >> 16) & 0xff;

        buf_in[3] = ((zstream.total_out + 8) >> 24) & 0xff;



        if (   lseek(fd_out, 4, SEEK_SET) < 0

            || write(fd_out, &buf_in, 4) < 4) {

            perror("Error writing output file");

            return 1;

        }

    }



    inflateEnd(&zstream);

    close(fd_in);

    close(fd_out);

    return 0;

}

static void virtio_blk_update_config(VirtIODevice *vdev, uint8_t *config)

{

    VirtIOBlock *s = to_virtio_blk(vdev);

    struct virtio_blk_config blkcfg;

    uint64_t capacity;

    int cylinders, heads, secs;



    bdrv_get_geometry(s->bs, &capacity);

    bdrv_get_geometry_hint(s->bs, &cylinders, &heads, &secs);

    stq_raw(&blkcfg.capacity, capacity);

    stl_raw(&blkcfg.seg_max, 128 - 2);

    stw_raw(&blkcfg.cylinders, cylinders);

    blkcfg.heads = heads;

    blkcfg.sectors = secs;


    memcpy(config, &blkcfg, sizeof(blkcfg));

}

static int output_data_internal(MLPDecodeContext *m, unsigned int substr,

                                uint8_t *data, unsigned int *data_size, int is32)

{

    SubStream *s = &m->substream[substr];

    unsigned int i, out_ch = 0;

    int32_t *data_32 = (int32_t*) data;

    int16_t *data_16 = (int16_t*) data;



    if (*data_size < (s->max_channel + 1) * s->blockpos * (is32 ? 4 : 2))

        return -1;



    for (i = 0; i < s->blockpos; i++) {

        for (out_ch = 0; out_ch <= s->max_matrix_channel; out_ch++) {

            int mat_ch = s->ch_assign[out_ch];

            int32_t sample = m->sample_buffer[i][mat_ch]

                          << s->output_shift[mat_ch];

            s->lossless_check_data ^= (sample & 0xffffff) << mat_ch;

            if (is32) *data_32++ = sample << 8;

            else      *data_16++ = sample >> 8;

        }

    }



    *data_size = i * out_ch * (is32 ? 4 : 2);



    return 0;

}

