static int rsd_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    int i, ret, version, start = 0x800;

    AVCodecParameters *par;

    AVStream *st = avformat_new_stream(s, NULL);



    if (!st)

        return AVERROR(ENOMEM);



    avio_skip(pb, 3); // "RSD"

    version = avio_r8(pb) - '0';



    par = st->codecpar;

    par->codec_type = AVMEDIA_TYPE_AUDIO;

    par->codec_tag  = avio_rl32(pb);

    par->codec_id   = ff_codec_get_id(rsd_tags, par->codec_tag);

    if (!par->codec_id) {

        char tag_buf[32];



        av_get_codec_tag_string(tag_buf, sizeof(tag_buf), par->codec_tag);

        for (i=0; i < FF_ARRAY_ELEMS(rsd_unsupported_tags); i++) {

            if (par->codec_tag == rsd_unsupported_tags[i]) {

                avpriv_request_sample(s, "Codec tag: %s", tag_buf);

                return AVERROR_PATCHWELCOME;

            }

        }

        av_log(s, AV_LOG_ERROR, "Unknown codec tag: %s\n", tag_buf);

        return AVERROR_INVALIDDATA;

    }



    par->channels = avio_rl32(pb);

    if (!par->channels)

        return AVERROR_INVALIDDATA;



    avio_skip(pb, 4); // Bit depth

    par->sample_rate = avio_rl32(pb);

    if (!par->sample_rate)

        return AVERROR_INVALIDDATA;



    avio_skip(pb, 4); // Unknown



    switch (par->codec_id) {

    case AV_CODEC_ID_XMA2:

        par->block_align = 2048;

        ff_alloc_extradata(par, 34);

        if (!par->extradata)

            return AVERROR(ENOMEM);

        memset(par->extradata, 0, 34);

        break;

    case AV_CODEC_ID_ADPCM_PSX:

        par->block_align = 16 * par->channels;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_IMA_RAD:

        par->block_align = 20 * par->channels;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_IMA_WAV:

        if (version == 2)

            start = avio_rl32(pb);



        par->bits_per_coded_sample = 4;

        par->block_align = 36 * par->channels;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_THP_LE:

        /* RSD3GADP is mono, so only alloc enough memory

           to store the coeff table for a single channel. */



        start = avio_rl32(pb);



        if ((ret = ff_get_extradata(s, par, s->pb, 32)) < 0)

            return ret;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_THP:

        par->block_align = 8 * par->channels;

        avio_skip(s->pb, 0x1A4 - avio_tell(s->pb));



        if ((ret = ff_alloc_extradata(st->codecpar, 32 * par->channels)) < 0)

            return ret;



        for (i = 0; i < par->channels; i++) {

            avio_read(s->pb, st->codecpar->extradata + 32 * i, 32);

            avio_skip(s->pb, 8);

        }

        if (pb->seekable)

            st->duration = (avio_size(pb) - start) / (8 * par->channels) * 14;

        break;

    case AV_CODEC_ID_PCM_S16LE:

    case AV_CODEC_ID_PCM_S16BE:

        if (version != 4)

            start = avio_rl32(pb);



        if (pb->seekable)

            st->duration = (avio_size(pb) - start) / 2 / par->channels;

        break;

    }



    avio_skip(pb, start - avio_tell(pb));

    if (par->codec_id == AV_CODEC_ID_XMA2) {

        avio_skip(pb, avio_rb32(pb) + avio_rb32(pb));

        st->duration = avio_rb32(pb);

    }



    avpriv_set_pts_info(st, 64, 1, par->sample_rate);



    return 0;

}

PCIBus *pci_grackle_init(uint32_t base, qemu_irq *pic)

{

    DeviceState *dev;

    SysBusDevice *s;

    GrackleState *d;



    dev = qdev_create(NULL, "grackle");

    qdev_init(dev);

    s = sysbus_from_qdev(dev);

    d = FROM_SYSBUS(GrackleState, s);

    d->host_state.bus = pci_register_bus(&d->busdev.qdev, "pci",

                                         pci_grackle_set_irq,

                                         pci_grackle_map_irq,

                                         pic, 0, 4);



    pci_create_simple(d->host_state.bus, 0, "grackle");



    sysbus_mmio_map(s, 0, base);

    sysbus_mmio_map(s, 1, base + 0x00200000);



    return d->host_state.bus;

}

static CharDriverState *qemu_chr_open_socket_fd(int fd, bool do_nodelay,

                                                bool is_listen, bool is_telnet,

                                                bool is_waitconnect,

                                                Error **errp)

{

    CharDriverState *chr = NULL;

    TCPCharDriver *s = NULL;

    char host[NI_MAXHOST], serv[NI_MAXSERV];

    const char *left = "", *right = "";

    struct sockaddr_storage ss;

    socklen_t ss_len = sizeof(ss);



    memset(&ss, 0, ss_len);

    if (getsockname(fd, (struct sockaddr *) &ss, &ss_len) != 0) {

        error_setg_errno(errp, errno, "getsockname");

        return NULL;

    }



    chr = g_malloc0(sizeof(CharDriverState));

    s = g_malloc0(sizeof(TCPCharDriver));



    s->connected = 0;

    s->fd = -1;

    s->listen_fd = -1;

    s->read_msgfds = 0;

    s->read_msgfds_num = 0;

    s->write_msgfds = 0;

    s->write_msgfds_num = 0;



    chr->filename = g_malloc(256);

    switch (ss.ss_family) {

#ifndef _WIN32

    case AF_UNIX:

        s->is_unix = 1;

        snprintf(chr->filename, 256, "unix:%s%s",

                 ((struct sockaddr_un *)(&ss))->sun_path,

                 is_listen ? ",server" : "");

        break;

#endif

    case AF_INET6:

        left  = "[";

        right = "]";

        /* fall through */

    case AF_INET:

        s->do_nodelay = do_nodelay;

        getnameinfo((struct sockaddr *) &ss, ss_len, host, sizeof(host),

                    serv, sizeof(serv), NI_NUMERICHOST | NI_NUMERICSERV);

        snprintf(chr->filename, 256, "%s:%s%s%s:%s%s",

                 is_telnet ? "telnet" : "tcp",

                 left, host, right, serv,

                 is_listen ? ",server" : "");

        break;

    }



    chr->opaque = s;

    chr->chr_write = tcp_chr_write;

    chr->chr_sync_read = tcp_chr_sync_read;

    chr->chr_close = tcp_chr_close;

    chr->get_msgfds = tcp_get_msgfds;

    chr->set_msgfds = tcp_set_msgfds;

    chr->chr_add_client = tcp_chr_add_client;

    chr->chr_add_watch = tcp_chr_add_watch;

    chr->chr_update_read_handler = tcp_chr_update_read_handler;

    /* be isn't opened until we get a connection */

    chr->explicit_be_open = true;



    if (is_listen) {

        s->listen_fd = fd;

        s->listen_chan = io_channel_from_socket(s->listen_fd);

        s->listen_tag = g_io_add_watch(s->listen_chan, G_IO_IN, tcp_chr_accept, chr);

        if (is_telnet) {

            s->do_telnetopt = 1;

        }

    } else {

        s->connected = 1;

        s->fd = fd;

        socket_set_nodelay(fd);

        s->chan = io_channel_from_socket(s->fd);

        tcp_chr_connect(chr);

    }



    if (is_listen && is_waitconnect) {

        fprintf(stderr, "QEMU waiting for connection on: %s\n",

                chr->filename);

        tcp_chr_accept(s->listen_chan, G_IO_IN, chr);

        qemu_set_nonblock(s->listen_fd);

    }

    return chr;

}

static int swf_write_header(AVFormatContext *s)

{

    SWFContext *swf = s->priv_data;

    AVIOContext *pb = s->pb;

    PutBitContext p;

    uint8_t buf1[256];

    int i, width, height, rate, rate_base;

    int version;



    swf->sound_samples = 0;

    swf->swf_frame_number = 0;

    swf->video_frame_number = 0;



    for(i=0;i<s->nb_streams;i++) {

        AVCodecContext *enc = s->streams[i]->codec;

        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            if (swf->audio_enc) {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports 1 audio stream\n");

                return AVERROR_INVALIDDATA;


            if (enc->codec_id == AV_CODEC_ID_MP3) {

                if (!enc->frame_size) {

                    av_log(s, AV_LOG_ERROR, "audio frame size not set\n");

                    return -1;


                swf->audio_enc = enc;

                swf->audio_fifo= av_fifo_alloc(AUDIO_FIFO_SIZE);

                if (!swf->audio_fifo)

                    return AVERROR(ENOMEM);

            } else {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports MP3\n");

                return -1;


        } else {

            if (swf->video_enc) {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports 1 video stream\n");

                return AVERROR_INVALIDDATA;


            if (enc->codec_id == AV_CODEC_ID_VP6F ||

                enc->codec_id == AV_CODEC_ID_FLV1 ||

                enc->codec_id == AV_CODEC_ID_MJPEG) {

                swf->video_st  = s->streams[i];

                swf->video_enc = enc;

            } else {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports VP6, FLV1 and MJPEG\n");

                return -1;






    if (!swf->video_enc) {

        /* currently, cannot work correctly if audio only */

        width = 320;

        height = 200;

        rate = 10;

        rate_base= 1;

    } else {

        width = swf->video_enc->width;

        height = swf->video_enc->height;

        // TODO: should be avg_frame_rate

        rate = swf->video_st->time_base.den;

        rate_base = swf->video_st->time_base.num;




    if (!swf->audio_enc)

        swf->samples_per_frame = (44100LL * rate_base) / rate;

    else

        swf->samples_per_frame = (swf->audio_enc->sample_rate * rate_base) / rate;



    avio_write(pb, "FWS", 3);



    if (!strcmp("avm2", s->oformat->name))

        version = 9;

    else if (swf->video_enc && swf->video_enc->codec_id == AV_CODEC_ID_VP6F)

        version = 8; /* version 8 and above support VP6 codec */

    else if (swf->video_enc && swf->video_enc->codec_id == AV_CODEC_ID_FLV1)

        version = 6; /* version 6 and above support FLV1 codec */

    else

        version = 4; /* version 4 for mpeg audio support */

    avio_w8(pb, version);



    avio_wl32(pb, DUMMY_FILE_SIZE); /* dummy size

                                      (will be patched if not streamed) */



    put_swf_rect(pb, 0, width * 20, 0, height * 20);





    avio_wl16(pb, (rate * 256) / rate_base); /* frame rate */

    swf->duration_pos = avio_tell(pb);

    avio_wl16(pb, (uint16_t)(DUMMY_DURATION * (int64_t)rate / rate_base)); /* frame count */



    /* avm2/swf v9 (also v8?) files require a file attribute tag */

    if (version == 9) {

        put_swf_tag(s, TAG_FILEATTRIBUTES);

        avio_wl32(pb, 1<<3); /* set ActionScript v3/AVM2 flag */

        put_swf_end_tag(s);




    /* define a shape with the jpeg inside */

    if (swf->video_enc && swf->video_enc->codec_id == AV_CODEC_ID_MJPEG) {

        put_swf_tag(s, TAG_DEFINESHAPE);



        avio_wl16(pb, SHAPE_ID); /* ID of shape */

        /* bounding rectangle */

        put_swf_rect(pb, 0, width, 0, height);

        /* style info */

        avio_w8(pb, 1); /* one fill style */

        avio_w8(pb, 0x41); /* clipped bitmap fill */

        avio_wl16(pb, BITMAP_ID); /* bitmap ID */

        /* position of the bitmap */

        put_swf_matrix(pb, 1 << FRAC_BITS, 0,

                       0,  1 << FRAC_BITS, 0, 0);

        avio_w8(pb, 0); /* no line style */



        /* shape drawing */

        init_put_bits(&p, buf1, sizeof(buf1));

        put_bits(&p, 4, 1); /* one fill bit */

        put_bits(&p, 4, 0); /* zero line bit */



        put_bits(&p, 1, 0); /* not an edge */

        put_bits(&p, 5, FLAG_MOVETO | FLAG_SETFILL0);

        put_bits(&p, 5, 1); /* nbits */

        put_bits(&p, 1, 0); /* X */

        put_bits(&p, 1, 0); /* Y */

        put_bits(&p, 1, 1); /* set fill style 1 */



        /* draw the rectangle ! */

        put_swf_line_edge(&p, width, 0);

        put_swf_line_edge(&p, 0, height);

        put_swf_line_edge(&p, -width, 0);

        put_swf_line_edge(&p, 0, -height);



        /* end of shape */

        put_bits(&p, 1, 0); /* not an edge */

        put_bits(&p, 5, 0);



        flush_put_bits(&p);

        avio_write(pb, buf1, put_bits_ptr(&p) - p.buf);



        put_swf_end_tag(s);




    if (swf->audio_enc && swf->audio_enc->codec_id == AV_CODEC_ID_MP3) {

        int v = 0;



        /* start sound */

        put_swf_tag(s, TAG_STREAMHEAD2);

        switch(swf->audio_enc->sample_rate) {

        case 11025: v |= 1 << 2; break;

        case 22050: v |= 2 << 2; break;

        case 44100: v |= 3 << 2; break;

        default:

            /* not supported */

            av_log(s, AV_LOG_ERROR, "swf does not support that sample rate, choose from (44100, 22050, 11025).\n");

            return -1;


        v |= 0x02; /* 16 bit playback */

        if (swf->audio_enc->channels == 2)

            v |= 0x01; /* stereo playback */

        avio_w8(s->pb, v);

        v |= 0x20; /* mp3 compressed */

        avio_w8(s->pb, v);

        avio_wl16(s->pb, swf->samples_per_frame);  /* avg samples per frame */

        avio_wl16(s->pb, 0);



        put_swf_end_tag(s);




    avio_flush(s->pb);

    return 0;

