static gboolean guest_exec_output_watch(GIOChannel *ch,

        GIOCondition cond, gpointer p_)

{

    GuestExecIOData *p = (GuestExecIOData *)p_;

    gsize bytes_read;

    GIOStatus gstatus;



    if (cond == G_IO_HUP || cond == G_IO_ERR) {

        goto close;

    }



    if (p->size == p->length) {

        gpointer t = NULL;

        if (!p->truncated && p->size < GUEST_EXEC_MAX_OUTPUT) {

            t = g_try_realloc(p->data, p->size + GUEST_EXEC_IO_SIZE);

        }

        if (t == NULL) {

            /* ignore truncated output */

            gchar buf[GUEST_EXEC_IO_SIZE];



            p->truncated = true;

            gstatus = g_io_channel_read_chars(ch, buf, sizeof(buf),

                                              &bytes_read, NULL);

            if (gstatus == G_IO_STATUS_EOF || gstatus == G_IO_STATUS_ERROR) {

                goto close;

            }



            return true;

        }

        p->size += GUEST_EXEC_IO_SIZE;

        p->data = t;

    }



    /* Calling read API once.

     * On next available data our callback will be called again */

    gstatus = g_io_channel_read_chars(ch, (gchar *)p->data + p->length,

            p->size - p->length, &bytes_read, NULL);

    if (gstatus == G_IO_STATUS_EOF || gstatus == G_IO_STATUS_ERROR) {

        goto close;

    }



    p->length += bytes_read;



    return true;



close:


    g_io_channel_unref(ch);

    g_atomic_int_set(&p->closed, 1);

    return false;

}

static void virtio_gpu_handle_cursor(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOGPU *g = VIRTIO_GPU(vdev);

    VirtQueueElement elem;

    size_t s;

    struct virtio_gpu_update_cursor cursor_info;



    if (!virtio_queue_ready(vq)) {

        return;

    }

    while (virtqueue_pop(vq, &elem)) {

        s = iov_to_buf(elem.out_sg, elem.out_num, 0,

                       &cursor_info, sizeof(cursor_info));

        if (s != sizeof(cursor_info)) {

            qemu_log_mask(LOG_GUEST_ERROR,

                          "%s: cursor size incorrect %zu vs %zu\n",

                          __func__, s, sizeof(cursor_info));

        } else {

            update_cursor(g, &cursor_info);

        }

        virtqueue_push(vq, &elem, 0);

        virtio_notify(vdev, vq);

    }

}

static int set_boot_dev(ISADevice *s, const char *boot_device)

{

#define PC_MAX_BOOT_DEVICES 3

    int nbds, bds[3] = { 0, };

    int i;



    nbds = strlen(boot_device);

    if (nbds > PC_MAX_BOOT_DEVICES) {

        error_report("Too many boot devices for PC");

        return(1);

    }

    for (i = 0; i < nbds; i++) {

        bds[i] = boot_device2nibble(boot_device[i]);

        if (bds[i] == 0) {

            error_report("Invalid boot device for PC: '%c'",

                         boot_device[i]);

            return(1);

        }

    }

    rtc_set_memory(s, 0x3d, (bds[1] << 4) | bds[0]);

    rtc_set_memory(s, 0x38, (bds[2] << 4) | (fd_bootchk ? 0x0 : 0x1));

    return(0);

}

static size_t pdu_marshal(V9fsPDU *pdu, size_t offset, const char *fmt, ...)

{

    size_t old_offset = offset;

    va_list ap;

    int i;



    va_start(ap, fmt);

    for (i = 0; fmt[i]; i++) {

        switch (fmt[i]) {

        case 'b': {

            uint8_t val = va_arg(ap, int);

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'w': {

            uint16_t val;

            cpu_to_le16w(&val, va_arg(ap, int));

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'd': {

            uint32_t val;

            cpu_to_le32w(&val, va_arg(ap, uint32_t));

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'q': {

            uint64_t val;

            cpu_to_le64w(&val, va_arg(ap, uint64_t));

            offset += pdu_pack(pdu, offset, &val, sizeof(val));

            break;

        }

        case 'v': {

            struct iovec *iov = va_arg(ap, struct iovec *);

            int *iovcnt = va_arg(ap, int *);

            *iovcnt = pdu_copy_sg(pdu, offset, 1, iov);

            break;

        }

        case 's': {

            V9fsString *str = va_arg(ap, V9fsString *);

            offset += pdu_marshal(pdu, offset, "w", str->size);

            offset += pdu_pack(pdu, offset, str->data, str->size);

            break;

        }

        case 'Q': {

            V9fsQID *qidp = va_arg(ap, V9fsQID *);

            offset += pdu_marshal(pdu, offset, "bdq",

                        qidp->type, qidp->version, qidp->path);

            break;

        }

        case 'S': {

            V9fsStat *statp = va_arg(ap, V9fsStat *);

            offset += pdu_marshal(pdu, offset, "wwdQdddqsssssddd",

                        statp->size, statp->type, statp->dev,

                        &statp->qid, statp->mode, statp->atime,

                        statp->mtime, statp->length, &statp->name,

                        &statp->uid, &statp->gid, &statp->muid,

                        &statp->extension, statp->n_uid,

                        statp->n_gid, statp->n_muid);

            break;

        }

        case 'A': {

            V9fsStatDotl *statp = va_arg(ap, V9fsStatDotl *);

            offset += pdu_marshal(pdu, offset, "qQdddqqqqqqqqqqqqqqq",

                        statp->st_result_mask,

                        &statp->qid, statp->st_mode,

                        statp->st_uid, statp->st_gid,

                        statp->st_nlink, statp->st_rdev,

                        statp->st_size, statp->st_blksize, statp->st_blocks,

                        statp->st_atime_sec, statp->st_atime_nsec,

                        statp->st_mtime_sec, statp->st_mtime_nsec,

                        statp->st_ctime_sec, statp->st_ctime_nsec,

                        statp->st_btime_sec, statp->st_btime_nsec,

                        statp->st_gen, statp->st_data_version);

            break;

        }

        default:

            break;

        }

    }

    va_end(ap);



    return offset - old_offset;

}

static void flush_buffered(AVFormatContext *s1, int last)

{

    RTPMuxContext *s = s1->priv_data;

    if (s->buf_ptr != s->buf) {

        // If only sending one single NAL unit, skip the aggregation framing

        if (s->buffered_nals == 1)

            ff_rtp_send_data(s1, s->buf + 4, s->buf_ptr - s->buf - 4, last);

        else

            ff_rtp_send_data(s1, s->buf, s->buf_ptr - s->buf, last);

    }

    s->buf_ptr = s->buf;

    s->buffered_nals = 0;

}

static void tcg_out_insn_3314(TCGContext *s, AArch64Insn insn,

                              TCGReg r1, TCGReg r2, TCGReg rn,

                              tcg_target_long ofs, bool pre, bool w)

{

    insn |= 1u << 31; /* ext */

    insn |= pre << 24;

    insn |= w << 23;



    assert(ofs >= -0x200 && ofs < 0x200 && (ofs & 7) == 0);

    insn |= (ofs & (0x7f << 3)) << (15 - 3);



    tcg_out32(s, insn | r2 << 10 | rn << 5 | r1);

}

static int read_header_openmpt(AVFormatContext *s)

{

    AVStream *st;

    OpenMPTContext *openmpt = s->priv_data;

    int64_t size = avio_size(s->pb);

    if (!size)

        return AVERROR_INVALIDDATA;

    char *buf = av_malloc(size);

    int ret;





    if (!buf)

        return AVERROR(ENOMEM);

    size = avio_read(s->pb, buf, size);

    if (size < 0) {

        av_log(s, AV_LOG_ERROR, "Reading input buffer failed.\n");

        av_freep(&buf);

        return size;

    }



    openmpt->module = openmpt_module_create_from_memory(buf, size, openmpt_logfunc, s, NULL);

    av_freep(&buf);

    if (!openmpt->module)

            return AVERROR_INVALIDDATA;



    openmpt->channels   = av_get_channel_layout_nb_channels(openmpt->layout);

    openmpt->duration   = openmpt_module_get_duration_seconds(openmpt->module);



    add_meta(s, "artist",  openmpt_module_get_metadata(openmpt->module, "artist"));

    add_meta(s, "title",   openmpt_module_get_metadata(openmpt->module, "title"));

    add_meta(s, "encoder", openmpt_module_get_metadata(openmpt->module, "tracker"));

    add_meta(s, "comment", openmpt_module_get_metadata(openmpt->module, "message"));

    add_meta(s, "date",    openmpt_module_get_metadata(openmpt->module, "date"));



    if (openmpt->subsong >= openmpt_module_get_num_subsongs(openmpt->module)) {

        openmpt_module_destroy(openmpt->module);

        av_log(s, AV_LOG_ERROR, "Invalid subsong index: %d\n", openmpt->subsong);

        return AVERROR(EINVAL);

    }



    if (openmpt->subsong != -2) {

        if (openmpt->subsong >= 0) {

            av_dict_set_int(&s->metadata, "track", openmpt->subsong + 1, 0);

        }

        ret = openmpt_module_select_subsong(openmpt->module, openmpt->subsong);

        if (!ret){

            openmpt_module_destroy(openmpt->module);

            av_log(s, AV_LOG_ERROR, "Could not select requested subsong: %d", openmpt->subsong);

            return AVERROR(EINVAL);

        }

    }



    st = avformat_new_stream(s, NULL);

    if (!st) {

        openmpt_module_destroy(openmpt->module);

        openmpt->module = NULL;

        return AVERROR(ENOMEM);

    }

    avpriv_set_pts_info(st, 64, 1, AV_TIME_BASE);

    st->duration = llrint(openmpt->duration*AV_TIME_BASE);



    st->codecpar->codec_type  = AVMEDIA_TYPE_AUDIO;

    st->codecpar->codec_id    = AV_NE(AV_CODEC_ID_PCM_F32BE, AV_CODEC_ID_PCM_F32LE);

    st->codecpar->channels    = openmpt->channels;

    st->codecpar->sample_rate = openmpt->sample_rate;



    return 0;

}

static void show_stream(AVFormatContext *fmt_ctx, int stream_idx)

{

    AVStream *stream = fmt_ctx->streams[stream_idx];

    AVCodecContext *dec_ctx;

    AVCodec *dec;

    const char *profile;

    char val_str[128];

    AVRational display_aspect_ratio;



    probe_object_header("stream");



    probe_int("index", stream->index);



    if ((dec_ctx = stream->codec)) {

        if ((dec = dec_ctx->codec)) {

            probe_str("codec_name", dec->name);

            probe_str("codec_long_name", dec->long_name);

        } else {

            probe_str("codec_name", "unknown");

        }



        probe_str("codec_type", media_type_string(dec_ctx->codec_type));

        probe_str("codec_time_base",

                  rational_string(val_str, sizeof(val_str),

                                  "/", &dec_ctx->time_base));



        /* print AVI/FourCC tag */

        av_get_codec_tag_string(val_str, sizeof(val_str), dec_ctx->codec_tag);

        probe_str("codec_tag_string", val_str);

        probe_str("codec_tag", tag_string(val_str, sizeof(val_str),

                                          dec_ctx->codec_tag));



        /* print profile, if there is one */

        if (dec && (profile = av_get_profile_name(dec, dec_ctx->profile)))

            probe_str("profile", profile);



        switch (dec_ctx->codec_type) {

        case AVMEDIA_TYPE_VIDEO:

            probe_int("width", dec_ctx->width);

            probe_int("height", dec_ctx->height);

            probe_int("has_b_frames", dec_ctx->has_b_frames);

            if (dec_ctx->sample_aspect_ratio.num) {

                probe_str("sample_aspect_ratio",

                          rational_string(val_str, sizeof(val_str), ":",

                          &dec_ctx->sample_aspect_ratio));

                av_reduce(&display_aspect_ratio.num, &display_aspect_ratio.den,

                          dec_ctx->width  * dec_ctx->sample_aspect_ratio.num,

                          dec_ctx->height * dec_ctx->sample_aspect_ratio.den,

                          1024*1024);

                probe_str("display_aspect_ratio",

                          rational_string(val_str, sizeof(val_str), ":",

                          &display_aspect_ratio));

            }

            probe_str("pix_fmt",

                      dec_ctx->pix_fmt != PIX_FMT_NONE ? av_pix_fmt_descriptors[dec_ctx->pix_fmt].name

                                                    : "unknown");

            probe_int("level", dec_ctx->level);

            break;



        case AVMEDIA_TYPE_AUDIO:

            probe_str("sample_rate",

                      value_string(val_str, sizeof(val_str),

                                   dec_ctx->sample_rate,

                                   unit_hertz_str));

            probe_int("channels", dec_ctx->channels);

            probe_int("bits_per_sample",

                      av_get_bits_per_sample(dec_ctx->codec_id));

            break;

        }

    } else {

        probe_str("codec_type", "unknown");

    }



    if (fmt_ctx->iformat->flags & AVFMT_SHOW_IDS)

        probe_int("id", stream->id);

    probe_str("r_frame_rate",

              rational_string(val_str, sizeof(val_str), "/",

              &stream->r_frame_rate));

    probe_str("avg_frame_rate",

              rational_string(val_str, sizeof(val_str), "/",

              &stream->avg_frame_rate));

    probe_str("time_base",

              rational_string(val_str, sizeof(val_str), "/",

              &stream->time_base));

    probe_str("start_time",

              time_value_string(val_str, sizeof(val_str),

                                stream->start_time, &stream->time_base));

    probe_str("duration",

              time_value_string(val_str, sizeof(val_str),

                                stream->duration, &stream->time_base));

    if (stream->nb_frames)

        probe_int("nb_frames", stream->nb_frames);



    probe_dict(stream->metadata, "tags");



    probe_object_footer("stream");

}

static int mov_read_stsz(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    MOVStreamContext *sc = st->priv_data;

    unsigned int i, entries, sample_size, field_size, num_bytes;

    GetBitContext gb;

    unsigned char* buf;



    get_byte(pb); /* version */

    get_be24(pb); /* flags */



    if (atom.type == MKTAG('s','t','s','z')) {

        sample_size = get_be32(pb);

        if (!sc->sample_size) /* do not overwrite value computed in stsd */

            sc->sample_size = sample_size;

        field_size = 32;

    } else {

        sample_size = 0;

        get_be24(pb); /* reserved */

        field_size = get_byte(pb);

    }

    entries = get_be32(pb);



    dprintf(c->fc, "sample_size = %d sample_count = %d\n", sc->sample_size, entries);



    sc->sample_count = entries;

    if (sample_size)

        return 0;



    if (field_size != 4 && field_size != 8 && field_size != 16 && field_size != 32) {

        av_log(c->fc, AV_LOG_ERROR, "Invalid sample field size %d\n", field_size);

        return -1;

    }



    if(entries >= UINT_MAX / sizeof(int))

        return -1;

    sc->sample_sizes = av_malloc(entries * sizeof(int));

    if (!sc->sample_sizes)

        return AVERROR(ENOMEM);



    num_bytes = (entries*field_size+4)>>3;



    buf = av_malloc(num_bytes+FF_INPUT_BUFFER_PADDING_SIZE);

    if (!buf) {

        av_freep(&sc->sample_sizes);

        return AVERROR(ENOMEM);

    }



    if (get_buffer(pb, buf, num_bytes) < num_bytes) {

        av_freep(&sc->sample_sizes);

        av_free(buf);

        return -1;

    }



    init_get_bits(&gb, buf, 8*num_bytes);



    for(i=0; i<entries; i++)

        sc->sample_sizes[i] = get_bits_long(&gb, field_size);



    av_free(buf);

    return 0;

}

static bool cmd_set_features(IDEState *s, uint8_t cmd)

{

    uint16_t *identify_data;



    if (!s->bs) {

        ide_abort_command(s);

        return true;

    }



    /* XXX: valid for CDROM ? */

    switch (s->feature) {

    case 0x02: /* write cache enable */

        bdrv_set_enable_write_cache(s->bs, true);

        identify_data = (uint16_t *)s->identify_data;

        put_le16(identify_data + 85, (1 << 14) | (1 << 5) | 1);

        return true;

    case 0x82: /* write cache disable */

        bdrv_set_enable_write_cache(s->bs, false);

        identify_data = (uint16_t *)s->identify_data;

        put_le16(identify_data + 85, (1 << 14) | 1);

        ide_flush_cache(s);

        return false;

    case 0xcc: /* reverting to power-on defaults enable */

    case 0x66: /* reverting to power-on defaults disable */

    case 0xaa: /* read look-ahead enable */

    case 0x55: /* read look-ahead disable */

    case 0x05: /* set advanced power management mode */

    case 0x85: /* disable advanced power management mode */

    case 0x69: /* NOP */

    case 0x67: /* NOP */

    case 0x96: /* NOP */

    case 0x9a: /* NOP */

    case 0x42: /* enable Automatic Acoustic Mode */

    case 0xc2: /* disable Automatic Acoustic Mode */

        return true;

    case 0x03: /* set transfer mode */

        {

            uint8_t val = s->nsector & 0x07;

            identify_data = (uint16_t *)s->identify_data;



            switch (s->nsector >> 3) {

            case 0x00: /* pio default */

            case 0x01: /* pio mode */

                put_le16(identify_data + 62, 0x07);

                put_le16(identify_data + 63, 0x07);

                put_le16(identify_data + 88, 0x3f);

                break;

            case 0x02: /* sigle word dma mode*/

                put_le16(identify_data + 62, 0x07 | (1 << (val + 8)));

                put_le16(identify_data + 63, 0x07);

                put_le16(identify_data + 88, 0x3f);

                break;

            case 0x04: /* mdma mode */

                put_le16(identify_data + 62, 0x07);

                put_le16(identify_data + 63, 0x07 | (1 << (val + 8)));

                put_le16(identify_data + 88, 0x3f);

                break;

            case 0x08: /* udma mode */

                put_le16(identify_data + 62, 0x07);

                put_le16(identify_data + 63, 0x07);

                put_le16(identify_data + 88, 0x3f | (1 << (val + 8)));

                break;

            default:

                goto abort_cmd;

            }

            return true;

        }

    }



abort_cmd:

    ide_abort_command(s);

    return true;

}

static inline int check_input_motion(MpegEncContext * s, int mb_x, int mb_y, int p_type){

    MotionEstContext * const c= &s->me;

    Picture *p= s->current_picture_ptr;

    int mb_xy= mb_x + mb_y*s->mb_stride;

    int xy= 2*mb_x + 2*mb_y*s->b8_stride;

    int mb_type= s->current_picture.mb_type[mb_xy];

    int flags= c->flags;

    int shift= (flags&FLAG_QPEL) + 1;

    int mask= (1<<shift)-1;

    int x, y, i;

    int d=0;

    me_cmp_func cmpf= s->dsp.sse[0];

    me_cmp_func chroma_cmpf= s->dsp.sse[1];



    assert(p_type==0 || !USES_LIST(mb_type, 1));

    assert(IS_INTRA(mb_type) || USES_LIST(mb_type,0) || USES_LIST(mb_type,1));



    if(IS_INTERLACED(mb_type)){

        int xy2= xy  + s->b8_stride;

        s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTRA;

        c->stride<<=1;

        c->uvstride<<=1;

        init_interlaced_ref(s, 2);



        assert(s->flags & CODEC_FLAG_INTERLACED_ME);



        if(USES_LIST(mb_type, 0)){

            int field_select0= p->ref_index[0][xy ];

            int field_select1= p->ref_index[0][xy2];

            assert(field_select0==0 ||field_select0==1);

            assert(field_select1==0 ||field_select1==1);

            if(p_type){

                s->p_field_select_table[0][mb_xy]= field_select0;

                s->p_field_select_table[1][mb_xy]= field_select1;

                *(uint32_t*)s->p_field_mv_table[0][field_select0][mb_xy]= *(uint32_t*)p->motion_val[0][xy ];

                *(uint32_t*)s->p_field_mv_table[1][field_select1][mb_xy]= *(uint32_t*)p->motion_val[0][xy2];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTER_I;

            }else{

                s->b_field_select_table[0][0][mb_xy]= field_select0;

                s->b_field_select_table[0][1][mb_xy]= field_select1;

                *(uint32_t*)s->b_field_mv_table[0][0][field_select0][mb_xy]= *(uint32_t*)p->motion_val[0][xy ];

                *(uint32_t*)s->b_field_mv_table[0][1][field_select1][mb_xy]= *(uint32_t*)p->motion_val[0][xy2];

                s->mb_type[mb_xy]= CANDIDATE_MB_TYPE_FORWARD_I;

            }



            x= p->motion_val[0][xy ][0]; 

            y= p->motion_val[0][xy ][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select0, 0, cmpf, chroma_cmpf, flags);

            x= p->motion_val[0][xy2][0]; 

            y= p->motion_val[0][xy2][1];

            d+= cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select1, 1, cmpf, chroma_cmpf, flags);

        }

        if(USES_LIST(mb_type, 1)){

            int field_select0= p->ref_index[1][xy ];

            int field_select1= p->ref_index[1][xy2];

            assert(field_select0==0 ||field_select0==1);

            assert(field_select1==0 ||field_select1==1);

            s->b_field_select_table[1][0][mb_xy]= field_select0;

            s->b_field_select_table[1][1][mb_xy]= field_select1;

            *(uint32_t*)s->b_field_mv_table[1][0][field_select0][mb_xy]= *(uint32_t*)p->motion_val[1][xy ];

            *(uint32_t*)s->b_field_mv_table[1][1][field_select1][mb_xy]= *(uint32_t*)p->motion_val[1][xy2];

            if(USES_LIST(mb_type, 0)){

                s->mb_type[mb_xy]= CANDIDATE_MB_TYPE_BIDIR_I;

            }else{

                s->mb_type[mb_xy]= CANDIDATE_MB_TYPE_BACKWARD_I;

            }



            x= p->motion_val[1][xy ][0]; 

            y= p->motion_val[1][xy ][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select0+2, 0, cmpf, chroma_cmpf, flags);

            x= p->motion_val[1][xy2][0]; 

            y= p->motion_val[1][xy2][1];

            d+= cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 8, field_select1+2, 1, cmpf, chroma_cmpf, flags);

            //FIXME bidir scores

        }

        c->stride>>=1;

        c->uvstride>>=1;

    }else if(IS_8X8(mb_type)){


        cmpf= s->dsp.sse[1];

        chroma_cmpf= s->dsp.sse[1];

        init_mv4_ref(s);

        for(i=0; i<4; i++){

            xy= s->block_index[i];

            x= p->motion_val[0][xy][0]; 

            y= p->motion_val[0][xy][1];

            d+= cmp(s, x>>shift, y>>shift, x&mask, y&mask, 1, 8, i, i, cmpf, chroma_cmpf, flags);

        }

        s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTER4V;

    }else{

        if(USES_LIST(mb_type, 0)){

            if(p_type){

                *(uint32_t*)s->p_mv_table[mb_xy]= *(uint32_t*)p->motion_val[0][xy];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTER;

            }else if(USES_LIST(mb_type, 1)){

                *(uint32_t*)s->b_bidir_forw_mv_table[mb_xy]= *(uint32_t*)p->motion_val[0][xy];

                *(uint32_t*)s->b_bidir_back_mv_table[mb_xy]= *(uint32_t*)p->motion_val[1][xy];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_BIDIR;

            }else{

                *(uint32_t*)s->b_forw_mv_table[mb_xy]= *(uint32_t*)p->motion_val[0][xy];

                s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_FORWARD;

            }

            x= p->motion_val[0][xy][0]; 

            y= p->motion_val[0][xy][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 16, 0, 0, cmpf, chroma_cmpf, flags);

        }else if(USES_LIST(mb_type, 1)){

            *(uint32_t*)s->b_back_mv_table[mb_xy]= *(uint32_t*)p->motion_val[1][xy];

            s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_BACKWARD;



            x= p->motion_val[1][xy][0]; 

            y= p->motion_val[1][xy][1];

            d = cmp(s, x>>shift, y>>shift, x&mask, y&mask, 0, 16, 2, 0, cmpf, chroma_cmpf, flags);

        }else

            s->mb_type[mb_xy]=CANDIDATE_MB_TYPE_INTRA;

    }

    return d;

}

static int find_partition(BlockBackend *blk, int partition,

                          off_t *offset, off_t *size)

{

    struct partition_record mbr[4];

    uint8_t data[512];

    int i;

    int ext_partnum = 4;

    int ret;



    if ((ret = blk_read(blk, 0, data, 1)) < 0) {

        error_report("error while reading: %s", strerror(-ret));

        exit(EXIT_FAILURE);

    }



    if (data[510] != 0x55 || data[511] != 0xaa) {

        return -EINVAL;

    }



    for (i = 0; i < 4; i++) {

        read_partition(&data[446 + 16 * i], &mbr[i]);



        if (!mbr[i].system || !mbr[i].nb_sectors_abs) {

            continue;

        }



        if (mbr[i].system == 0xF || mbr[i].system == 0x5) {

            struct partition_record ext[4];

            uint8_t data1[512];

            int j;



            if ((ret = blk_read(blk, mbr[i].start_sector_abs, data1, 1)) < 0) {

                error_report("error while reading: %s", strerror(-ret));

                exit(EXIT_FAILURE);

            }



            for (j = 0; j < 4; j++) {

                read_partition(&data1[446 + 16 * j], &ext[j]);

                if (!ext[j].system || !ext[j].nb_sectors_abs) {

                    continue;

                }



                if ((ext_partnum + j + 1) == partition) {

                    *offset = (uint64_t)ext[j].start_sector_abs << 9;

                    *size = (uint64_t)ext[j].nb_sectors_abs << 9;

                    return 0;

                }

            }

            ext_partnum += 4;

        } else if ((i + 1) == partition) {

            *offset = (uint64_t)mbr[i].start_sector_abs << 9;

            *size = (uint64_t)mbr[i].nb_sectors_abs << 9;

            return 0;

        }

    }



    return -ENOENT;

}

static int save_zero_page(RAMState *rs, RAMBlock *block, ram_addr_t offset,

                          uint8_t *p)

{

    int pages = -1;



    if (is_zero_range(p, TARGET_PAGE_SIZE)) {

        rs->zero_pages++;

        rs->bytes_transferred +=

            save_page_header(rs, block, offset | RAM_SAVE_FLAG_COMPRESS);

        qemu_put_byte(rs->f, 0);

        rs->bytes_transferred += 1;

        pages = 1;

    }



    return pages;

}

static int htab_save_complete(QEMUFile *f, void *opaque)

{

    sPAPRMachineState *spapr = opaque;



    /* Iteration header */

    qemu_put_be32(f, 0);



    if (!spapr->htab) {

        int rc;



        assert(kvm_enabled());



        rc = spapr_check_htab_fd(spapr);

        if (rc < 0) {

            return rc;

        }



        rc = kvmppc_save_htab(f, spapr->htab_fd, MAX_KVM_BUF_SIZE, -1);

        if (rc < 0) {

            return rc;

        }

        close(spapr->htab_fd);

        spapr->htab_fd = -1;

    } else {

        htab_save_later_pass(f, spapr, -1);

    }



    /* End marker */

    qemu_put_be32(f, 0);

    qemu_put_be16(f, 0);

    qemu_put_be16(f, 0);



    return 0;

}

void tlb_reset_dirty(CPUState *cpu, ram_addr_t start1, ram_addr_t length)

{

    CPUArchState *env;



    int mmu_idx;



    assert_cpu_is_self(cpu);



    env = cpu->env_ptr;

    for (mmu_idx = 0; mmu_idx < NB_MMU_MODES; mmu_idx++) {

        unsigned int i;



        for (i = 0; i < CPU_TLB_SIZE; i++) {

            tlb_reset_dirty_range(&env->tlb_table[mmu_idx][i],

                                  start1, length);

        }



        for (i = 0; i < CPU_VTLB_SIZE; i++) {

            tlb_reset_dirty_range(&env->tlb_v_table[mmu_idx][i],

                                  start1, length);

        }

    }

}

static void reconstruct_stereo_16(int32_t *buffer[MAX_CHANNELS],

                                  int16_t *buffer_out,

                                  int numchannels, int numsamples,

                                  uint8_t interlacing_shift,

                                  uint8_t interlacing_leftweight)

{

    int i;

    if (numsamples <= 0)

        return;



    /* weighted interlacing */

    if (interlacing_leftweight) {

        for (i = 0; i < numsamples; i++) {

            int32_t a, b;



            a = buffer[0][i];

            b = buffer[1][i];



            a -= (b * interlacing_leftweight) >> interlacing_shift;

            b += a;



            buffer_out[i*numchannels] = b;

            buffer_out[i*numchannels + 1] = a;

        }



        return;

    }



    /* otherwise basic interlacing took place */

    for (i = 0; i < numsamples; i++) {

        int16_t left, right;



        left = buffer[0][i];

        right = buffer[1][i];



        buffer_out[i*numchannels] = left;

        buffer_out[i*numchannels + 1] = right;

    }

}

