void ff_compute_frame_duration(AVFormatContext *s, int *pnum, int *pden, AVStream *st,

                               AVCodecParserContext *pc, AVPacket *pkt)

{

    AVRational codec_framerate = s->iformat ? st->codec->framerate :

                                              av_inv_q(st->codec->time_base);

    int frame_size;



    *pnum = 0;

    *pden = 0;

    switch (st->codec->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        if (st->r_frame_rate.num && !pc) {

            *pnum = st->r_frame_rate.den;

            *pden = st->r_frame_rate.num;

        } else if (st->time_base.num * 1000LL > st->time_base.den) {

            *pnum = st->time_base.num;

            *pden = st->time_base.den;

        } else if (codec_framerate.den * 1000LL > codec_framerate.num) {

            *pnum = codec_framerate.den;

            *pden = codec_framerate.num;



            *pden *= st->codec->ticks_per_frame;

            av_assert0(st->codec->ticks_per_frame);

            if (pc && pc->repeat_pict) {

                av_assert0(s->iformat); // this may be wrong for interlaced encoding but its not used for that case

                if (*pnum > INT_MAX / (1 + pc->repeat_pict))

                    *pden /= 1 + pc->repeat_pict;

                else

                    *pnum *= 1 + pc->repeat_pict;

            }

            /* If this codec can be interlaced or progressive then we need

             * a parser to compute duration of a packet. Thus if we have

             * no parser in such case leave duration undefined. */

            if (st->codec->ticks_per_frame > 1 && !pc)

                *pnum = *pden = 0;

        }

        break;

    case AVMEDIA_TYPE_AUDIO:

        frame_size = av_get_audio_frame_duration(st->codec, pkt->size);

        if (frame_size <= 0 || st->codec->sample_rate <= 0)

            break;

        *pnum = frame_size;

        *pden = st->codec->sample_rate;

        break;

    default:

        break;

    }

}

static void type_initialize(TypeImpl *ti)

{

    TypeImpl *parent;



    if (ti->class) {

        return;

    }



    ti->class_size = type_class_get_size(ti);

    ti->instance_size = type_object_get_size(ti);



    ti->class = g_malloc0(ti->class_size);



    parent = type_get_parent(ti);

    if (parent) {

        type_initialize(parent);

        GSList *e;

        int i;



        g_assert(parent->class_size <= ti->class_size);

        memcpy(ti->class, parent->class, parent->class_size);

        ti->class->interfaces = NULL;



        for (e = parent->class->interfaces; e; e = e->next) {

            ObjectClass *iface = e->data;

            type_initialize_interface(ti, object_class_get_name(iface));

        }



        for (i = 0; i < ti->num_interfaces; i++) {

            TypeImpl *t = type_get_by_name(ti->interfaces[i].typename);

            for (e = ti->class->interfaces; e; e = e->next) {

                TypeImpl *target_type = OBJECT_CLASS(e->data)->type;



                if (type_is_ancestor(target_type, t)) {

                    break;

                }

            }



            if (e) {

                continue;

            }



            type_initialize_interface(ti, ti->interfaces[i].typename);

        }

    }



    ti->class->type = ti;



    while (parent) {

        if (parent->class_base_init) {

            parent->class_base_init(ti->class, ti->class_data);

        }

        parent = type_get_parent(parent);

    }



    if (ti->class_init) {

        ti->class_init(ti->class, ti->class_data);

    }





}

static void stream_process_mem2s(struct Stream *s,

                                 StreamSlave *tx_dev)

{

    uint32_t prev_d;

    unsigned char txbuf[16 * 1024];

    unsigned int txlen;

    uint32_t app[6];



    if (!stream_running(s) || stream_idle(s)) {

        return;

    }



    while (1) {

        stream_desc_load(s, s->regs[R_CURDESC]);



        if (s->desc.status & SDESC_STATUS_COMPLETE) {

            s->regs[R_DMASR] |= DMASR_HALTED;

            break;

        }



        if (stream_desc_sof(&s->desc)) {

            s->pos = 0;

            memcpy(app, s->desc.app, sizeof app);

        }



        txlen = s->desc.control & SDESC_CTRL_LEN_MASK;

        if ((txlen + s->pos) > sizeof txbuf) {

            hw_error("%s: too small internal txbuf! %d\n", __func__,

                     txlen + s->pos);

        }



        cpu_physical_memory_read(s->desc.buffer_address,

                                 txbuf + s->pos, txlen);

        s->pos += txlen;



        if (stream_desc_eof(&s->desc)) {

            stream_push(tx_dev, txbuf, s->pos, app);

            s->pos = 0;

            stream_complete(s);

        }



        /* Update the descriptor.  */

        s->desc.status = txlen | SDESC_STATUS_COMPLETE;

        stream_desc_store(s, s->regs[R_CURDESC]);



        /* Advance.  */

        prev_d = s->regs[R_CURDESC];

        s->regs[R_CURDESC] = s->desc.nxtdesc;

        if (prev_d == s->regs[R_TAILDESC]) {

            s->regs[R_DMASR] |= DMASR_IDLE;

            break;

        }

    }

}

