static int r3d_read_reda(AVFormatContext *s, AVPacket *pkt, Atom *atom)

{

    AVStream *st = s->streams[1];

    int av_unused tmp, tmp2;

    int samples, size;

    uint64_t pos = avio_tell(s->pb);

    unsigned dts;

    int ret;



    dts = avio_rb32(s->pb);



    st->codec->sample_rate = avio_rb32(s->pb);



    samples = avio_rb32(s->pb);



    tmp = avio_rb32(s->pb);

    av_dlog(s, "packet num %d\n", tmp);



    tmp = avio_rb16(s->pb); // unknown

    av_dlog(s, "unknown %d\n", tmp);



    tmp  = avio_r8(s->pb); // major version

    tmp2 = avio_r8(s->pb); // minor version

    av_dlog(s, "version %d.%d\n", tmp, tmp2);



    tmp = avio_rb32(s->pb); // unknown

    av_dlog(s, "unknown %d\n", tmp);



    size = atom->size - 8 - (avio_tell(s->pb) - pos);

    if (size < 0)

        return -1;

    ret = av_get_packet(s->pb, pkt, size);

    if (ret < 0) {

        av_log(s, AV_LOG_ERROR, "error reading audio packet\n");

        return ret;

    }



    pkt->stream_index = 1;

    pkt->dts = dts;

    pkt->duration = av_rescale(samples, st->time_base.den, st->codec->sample_rate);

    av_dlog(s, "pkt dts %"PRId64" duration %d samples %d sample rate %d\n",

            pkt->dts, pkt->duration, samples, st->codec->sample_rate);



    return 0;

}

I2CAdapter *omap_i2c_create(uint64_t addr)

{

    OMAPI2C *s = g_malloc0(sizeof(*s));

    I2CAdapter *i2c = (I2CAdapter *)s;

    uint16_t data;



    s->addr = addr;



    i2c->send = omap_i2c_send;

    i2c->recv = omap_i2c_recv;



    /* verify the mmio address by looking for a known signature */

    memread(addr + OMAP_I2C_REV, &data, 2);

    g_assert_cmphex(data, ==, 0x34);



    return i2c;

}

float32 float32_sqrt( float32 a STATUS_PARAM )

{

    flag aSign;

    int16 aExp, zExp;

    bits32 aSig, zSig;

    bits64 rem, term;



    aSig = extractFloat32Frac( a );

    aExp = extractFloat32Exp( a );

    aSign = extractFloat32Sign( a );

    if ( aExp == 0xFF ) {

        if ( aSig ) return propagateFloat32NaN( a, 0 STATUS_VAR );

        if ( ! aSign ) return a;

        float_raise( float_flag_invalid STATUS_VAR);

        return float32_default_nan;

    }

    if ( aSign ) {

        if ( ( aExp | aSig ) == 0 ) return a;

        float_raise( float_flag_invalid STATUS_VAR);

        return float32_default_nan;

    }

    if ( aExp == 0 ) {

        if ( aSig == 0 ) return 0;

        normalizeFloat32Subnormal( aSig, &aExp, &aSig );

    }

    zExp = ( ( aExp - 0x7F )>>1 ) + 0x7E;

    aSig = ( aSig | 0x00800000 )<<8;

    zSig = estimateSqrt32( aExp, aSig ) + 2;

    if ( ( zSig & 0x7F ) <= 5 ) {

        if ( zSig < 2 ) {

            zSig = 0x7FFFFFFF;

            goto roundAndPack;

        }

        aSig >>= aExp & 1;

        term = ( (bits64) zSig ) * zSig;

        rem = ( ( (bits64) aSig )<<32 ) - term;

        while ( (sbits64) rem < 0 ) {

            --zSig;

            rem += ( ( (bits64) zSig )<<1 ) | 1;

        }

        zSig |= ( rem != 0 );

    }

    shift32RightJamming( zSig, 1, &zSig );

 roundAndPack:

    return roundAndPackFloat32( 0, zExp, zSig STATUS_VAR );



}

static MigrationState *migrate_init(Monitor *mon, int detach, int blk, int inc)

{

    MigrationState *s = migrate_get_current();

    int64_t bandwidth_limit = s->bandwidth_limit;



    memset(s, 0, sizeof(*s));

    s->bandwidth_limit = bandwidth_limit;

    s->blk = blk;

    s->shared = inc;



    /* s->mon is used for two things:

       - pass fd in fd migration

       - suspend/resume monitor for not detached migration

    */

    s->mon = mon;

    s->bandwidth_limit = bandwidth_limit;

    s->state = MIG_STATE_SETUP;



    if (!detach) {

        migrate_fd_monitor_suspend(s, mon);

    }



    return s;

}

bool qvirtio_wait_queue_isr(const QVirtioBus *bus, QVirtioDevice *d,

                                            QVirtQueue *vq, uint64_t timeout)

{

