int ppc_radix64_handle_mmu_fault(PowerPCCPU *cpu, vaddr eaddr, int rwx,

                                 int mmu_idx)

{

    CPUState *cs = CPU(cpu);

    CPUPPCState *env = &cpu->env;

    PPCVirtualHypervisorClass *vhc =

        PPC_VIRTUAL_HYPERVISOR_GET_CLASS(cpu->vhyp);

    hwaddr raddr, pte_addr;

    uint64_t lpid = 0, pid = 0, offset, size, patbe, prtbe0, pte;

    int page_size, prot, fault_cause = 0;



    assert((rwx == 0) || (rwx == 1) || (rwx == 2));

    assert(!msr_hv); /* For now there is no Radix PowerNV Support */

    assert(cpu->vhyp);

    assert(ppc64_use_proc_tbl(cpu));



    /* Real Mode Access */

    if (((rwx == 2) && (msr_ir == 0)) || ((rwx != 2) && (msr_dr == 0))) {

        /* In real mode top 4 effective addr bits (mostly) ignored */

        raddr = eaddr & 0x0FFFFFFFFFFFFFFFULL;



        tlb_set_page(cs, eaddr & TARGET_PAGE_MASK, raddr & TARGET_PAGE_MASK,

                     PAGE_READ | PAGE_WRITE | PAGE_EXEC, mmu_idx,

                     TARGET_PAGE_SIZE);

        return 0;

    }



    /* Virtual Mode Access - get the fully qualified address */

    if (!ppc_radix64_get_fully_qualified_addr(env, eaddr, &lpid, &pid)) {

        ppc_radix64_raise_segi(cpu, rwx, eaddr);

        return 1;

    }



    /* Get Process Table */

    patbe = vhc->get_patbe(cpu->vhyp);



    /* Index Process Table by PID to Find Corresponding Process Table Entry */

    offset = pid * sizeof(struct prtb_entry);

    size = 1ULL << ((patbe & PATBE1_R_PRTS) + 12);

    if (offset >= size) {

        /* offset exceeds size of the process table */

        ppc_radix64_raise_si(cpu, rwx, eaddr, DSISR_NOPTE);

        return 1;

    }

    prtbe0 = ldq_phys(cs->as, (patbe & PATBE1_R_PRTB) + offset);



    /* Walk Radix Tree from Process Table Entry to Convert EA to RA */

    page_size = PRTBE_R_GET_RTS(prtbe0);

    pte = ppc_radix64_walk_tree(cpu, rwx, eaddr & R_EADDR_MASK,

                                prtbe0 & PRTBE_R_RPDB, prtbe0 & PRTBE_R_RPDS,

                                &raddr, &page_size, &fault_cause, &prot,

                                &pte_addr);

    if (!pte) {

        ppc_radix64_raise_si(cpu, rwx, eaddr, fault_cause);

        return 1;

    }



    /* Update Reference and Change Bits */

    ppc_radix64_set_rc(cpu, rwx, pte, pte_addr, &prot);



    tlb_set_page(cs, eaddr & TARGET_PAGE_MASK, raddr & TARGET_PAGE_MASK,

                 prot, mmu_idx, 1UL << page_size);

    return 0;

}

static void amdvi_realize(DeviceState *dev, Error **err)

{

    int ret = 0;

    AMDVIState *s = AMD_IOMMU_DEVICE(dev);

    X86IOMMUState *x86_iommu = X86_IOMMU_DEVICE(dev);

    MachineState *ms = MACHINE(qdev_get_machine());

    MachineClass *mc = MACHINE_GET_CLASS(ms);

    PCMachineState *pcms =

        PC_MACHINE(object_dynamic_cast(OBJECT(ms), TYPE_PC_MACHINE));

    PCIBus *bus;



    if (!pcms) {

        error_setg(err, "Machine-type '%s' not supported by amd-iommu",

                   mc->name);

        return;

    }



    bus = pcms->bus;

    s->iotlb = g_hash_table_new_full(amdvi_uint64_hash,

                                     amdvi_uint64_equal, g_free, g_free);



    /* This device should take care of IOMMU PCI properties */

    x86_iommu->type = TYPE_AMD;

    qdev_set_parent_bus(DEVICE(&s->pci), &bus->qbus);

    object_property_set_bool(OBJECT(&s->pci), true, "realized", err);

    ret = pci_add_capability(&s->pci.dev, AMDVI_CAPAB_ID_SEC, 0,

                                         AMDVI_CAPAB_SIZE, err);

    if (ret < 0) {

        return;

    }

    s->capab_offset = ret;



    ret = pci_add_capability(&s->pci.dev, PCI_CAP_ID_MSI, 0,

                             AMDVI_CAPAB_REG_SIZE, err);

    if (ret < 0) {

        return;

    }

    ret = pci_add_capability(&s->pci.dev, PCI_CAP_ID_HT, 0,

                             AMDVI_CAPAB_REG_SIZE, err);

    if (ret < 0) {

        return;

    }



    /* set up MMIO */

    memory_region_init_io(&s->mmio, OBJECT(s), &mmio_mem_ops, s, "amdvi-mmio",

                          AMDVI_MMIO_SIZE);



    sysbus_init_mmio(SYS_BUS_DEVICE(s), &s->mmio);

    sysbus_mmio_map(SYS_BUS_DEVICE(s), 0, AMDVI_BASE_ADDR);

    pci_setup_iommu(bus, amdvi_host_dma_iommu, s);

    s->devid = object_property_get_int(OBJECT(&s->pci), "addr", err);

    msi_init(&s->pci.dev, 0, 1, true, false, err);

    amdvi_init(s);

}

static void vnc_write_u32(VncState *vs, uint32_t value)

{

    uint8_t buf[4];



    buf[0] = (value >> 24) & 0xFF;

    buf[1] = (value >> 16) & 0xFF;

    buf[2] = (value >>  8) & 0xFF;

    buf[3] = value & 0xFF;



    vnc_write(vs, buf, 4);

}

static void av_update_stream_timings(AVFormatContext *ic)

{

    int64_t start_time, start_time1, end_time, end_time1;

    int64_t duration, duration1;

    int i;

    AVStream *st;



    start_time = INT64_MAX;

    end_time = INT64_MIN;

    duration = INT64_MIN;

    for(i = 0;i < ic->nb_streams; i++) {

        st = ic->streams[i];

        if (st->start_time != AV_NOPTS_VALUE) {

            start_time1= av_rescale_q(st->start_time, st->time_base, AV_TIME_BASE_Q);

            if (start_time1 < start_time)

                start_time = start_time1;

            if (st->duration != AV_NOPTS_VALUE) {

                end_time1 = start_time1

                          + av_rescale_q(st->duration, st->time_base, AV_TIME_BASE_Q);

                if (end_time1 > end_time)

                    end_time = end_time1;

            }

        }

        if (st->duration != AV_NOPTS_VALUE) {

            duration1 = av_rescale_q(st->duration, st->time_base, AV_TIME_BASE_Q);

            if (duration1 > duration)

                duration = duration1;

        }

    }

    if (start_time != INT64_MAX) {

        ic->start_time = start_time;

        if (end_time != INT64_MIN) {

            if (end_time - start_time > duration)

                duration = end_time - start_time;

        }

    }

    if (duration != INT64_MIN) {

        ic->duration = duration;

        if (ic->file_size > 0) {

            /* compute the bitrate */

            ic->bit_rate = (double)ic->file_size * 8.0 * AV_TIME_BASE /

                (double)ic->duration;

        }

    }

}

static int nprobe(AVFormatContext *s, uint8_t *enc_header, unsigned size,

                  const uint8_t *n_val)

{

    OMAContext *oc = s->priv_data;

    uint64_t pos;

    uint32_t taglen, datalen;

    struct AVDES av_des;



    if (!enc_header || !n_val ||

        size < OMA_ENC_HEADER_SIZE + oc->k_size + 4)

        return -1;



    pos = OMA_ENC_HEADER_SIZE + oc->k_size;

    if (!memcmp(&enc_header[pos], "EKB ", 4))

        pos += 32;



    if (size < pos + 44)

        return -1;



    if (AV_RB32(&enc_header[pos]) != oc->rid)

        av_log(s, AV_LOG_DEBUG, "Mismatching RID\n");



    taglen  = AV_RB32(&enc_header[pos + 32]);

    datalen = AV_RB32(&enc_header[pos + 36]) >> 4;



    pos += 44;

    if (size - pos < taglen)

        return -1;



    pos += taglen;



    if (pos + (((uint64_t)datalen) << 4) > size)

        return -1;



    av_des_init(&av_des, n_val, 192, 1);

    while (datalen-- > 0) {

        av_des_crypt(&av_des, oc->r_val, &enc_header[pos], 2, NULL, 1);

        kset(s, oc->r_val, NULL, 16);

        if (!rprobe(s, enc_header, size, oc->r_val))

            return 0;

        pos += 16;

    }



    return -1;

}

static bool cmd_write_multiple(IDEState *s, uint8_t cmd)

{

    bool lba48 = (cmd == WIN_MULTWRITE_EXT);

    int n;



    if (!s->bs || !s->mult_sectors) {

        ide_abort_command(s);

        return true;

    }



    ide_cmd_lba48_transform(s, lba48);



    s->req_nb_sectors = s->mult_sectors;

    n = MIN(s->nsector, s->req_nb_sectors);



    s->status = SEEK_STAT | READY_STAT;

    ide_transfer_start(s, s->io_buffer, 512 * n, ide_sector_write);



    s->media_changed = 1;



    return false;

}

static void add_codec(FFServerStream *stream, AVCodecContext *av,

                      FFServerConfig *config)

{

    AVStream *st;

    AVDictionary **opts, *recommended = NULL;

    char *enc_config;



    if(stream->nb_streams >= FF_ARRAY_ELEMS(stream->streams))

        return;



    opts = av->codec_type == AVMEDIA_TYPE_AUDIO ?

           &config->audio_opts : &config->video_opts;

    av_dict_copy(&recommended, *opts, 0);

    av_opt_set_dict2(av->priv_data, opts, AV_OPT_SEARCH_CHILDREN);

    av_opt_set_dict2(av, opts, AV_OPT_SEARCH_CHILDREN);

    if (av_dict_count(*opts))

        av_log(NULL, AV_LOG_WARNING,

               "Something is wrong, %d options are not set!\n", av_dict_count(*opts));



    if (config->stream_use_defaults) {

    //TODO: reident

    /* compute default parameters */

    switch(av->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        if (av->bit_rate == 0) {

            av->bit_rate = 64000;

            av_dict_set_int(&recommended, "ab", av->bit_rate, 0);

        }

        if (av->sample_rate == 0) {

            av->sample_rate = 22050;

            av_dict_set_int(&recommended, "ar", av->sample_rate, 0);

        }

        if (av->channels == 0) {

            av->channels = 1;

            av_dict_set_int(&recommended, "ac", av->channels, 0);

        }

        break;

    case AVMEDIA_TYPE_VIDEO:

        if (av->bit_rate == 0) {

            av->bit_rate = 64000;

            av_dict_set_int(&recommended, "b", av->bit_rate, 0);

        }

        if (av->time_base.num == 0){

            av->time_base.den = 5;

            av->time_base.num = 1;

            av_dict_set(&recommended, "time_base", "1/5", 0);

        }

        if (av->width == 0 || av->height == 0) {

            av->width = 160;

            av->height = 128;

            av_dict_set(&recommended, "video_size", "160x128", 0);

        }

        /* Bitrate tolerance is less for streaming */

        if (av->bit_rate_tolerance == 0) {

            av->bit_rate_tolerance = FFMAX(av->bit_rate / 4,

                      (int64_t)av->bit_rate*av->time_base.num/av->time_base.den);

            av_dict_set_int(&recommended, "bt", av->bit_rate_tolerance, 0);

        }



        if (!av->rc_eq) {

            av->rc_eq = av_strdup("tex^qComp");

            av_dict_set(&recommended, "rc_eq", "tex^qComp", 0);

        }

        if (!av->rc_max_rate) {

            av->rc_max_rate = av->bit_rate * 2;

            av_dict_set_int(&recommended, "maxrate", av->rc_max_rate, 0);

        }



        if (av->rc_max_rate && !av->rc_buffer_size) {

            av->rc_buffer_size = av->rc_max_rate;

            av_dict_set_int(&recommended, "bufsize", av->rc_buffer_size, 0);

        }

        break;

    default:

        abort();

    }

    } else {

        switch(av->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            if (av->bit_rate == 0)

                report_config_error(config->filename, config->line_num, AV_LOG_ERROR,

                                    &config->errors, "audio bit rate is not set\n");

            if (av->sample_rate == 0)

                report_config_error(config->filename, config->line_num, AV_LOG_ERROR,

                                    &config->errors, "audio sample rate is not set\n");

            break;

        case AVMEDIA_TYPE_VIDEO:

            if (av->width == 0 || av->height == 0)

                report_config_error(config->filename, config->line_num, AV_LOG_ERROR,

                                    &config->errors, "video size is not set\n");

            break;

        default:

            av_assert0(0);

        }

    }



    st = av_mallocz(sizeof(AVStream));

    if (!st)

        return;

    av_dict_get_string(recommended, &enc_config, '=', ',');

    av_dict_free(&recommended);

    av_stream_set_recommended_encoder_configuration(st, enc_config);

    st->codec = av;

    stream->streams[stream->nb_streams++] = st;

}

int ff_lock_avcodec(AVCodecContext *log_ctx, const AVCodec *codec)

{

    if (codec->caps_internal & FF_CODEC_CAP_INIT_THREADSAFE || !codec->init)

        return 0;



    if (ff_mutex_lock(&codec_mutex))

        return -1;



    if (atomic_fetch_add(&entangled_thread_counter, 1)) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Insufficient thread locking. At least %d threads are "

               "calling avcodec_open2() at the same time right now.\n",

               atomic_load(&entangled_thread_counter));

        ff_avcodec_locked = 1;

        ff_unlock_avcodec(codec);

        return AVERROR(EINVAL);

    }

    av_assert0(!ff_avcodec_locked);

    ff_avcodec_locked = 1;

    return 0;

}

int tcp_start_outgoing_migration(MigrationState *s, const char *host_port,

                                 Error **errp)

{

    s->get_error = socket_errno;

    s->write = socket_write;

    s->close = tcp_close;



    s->fd = inet_connect(host_port, false, NULL, errp);



    if (!error_is_set(errp)) {

        migrate_fd_connect(s);

    } else if (error_is_type(*errp, QERR_SOCKET_CONNECT_IN_PROGRESS)) {

        DPRINTF("connect in progress\n");

        qemu_set_fd_handler2(s->fd, NULL, NULL, tcp_wait_for_connect, s);

    } else if (error_is_type(*errp, QERR_SOCKET_CREATE_FAILED)) {

        DPRINTF("connect failed\n");

        return -1;

    } else if (error_is_type(*errp, QERR_SOCKET_CONNECT_FAILED)) {

        DPRINTF("connect failed\n");

        migrate_fd_error(s);

        return -1;

    } else {

        DPRINTF("unknown error\n");

        return -1;

    }



    return 0;

}

