static int mov_read_stco(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    MOVStreamContext *sc = st->priv_data;

    unsigned int i, entries;



    get_byte(pb); /* version */

    get_be24(pb); /* flags */



    entries = get_be32(pb);



    if(entries >= UINT_MAX/sizeof(int64_t))

        return -1;



    sc->chunk_offsets = av_malloc(entries * sizeof(int64_t));

    if (!sc->chunk_offsets)

        return AVERROR(ENOMEM);

    sc->chunk_count = entries;



    if      (atom.type == MKTAG('s','t','c','o'))

        for(i=0; i<entries; i++)

            sc->chunk_offsets[i] = get_be32(pb);

    else if (atom.type == MKTAG('c','o','6','4'))

        for(i=0; i<entries; i++)

            sc->chunk_offsets[i] = get_be64(pb);

    else

        return -1;



    return 0;

}

static void do_program_interrupt(CPUS390XState *env)

{

    uint64_t mask, addr;

    LowCore *lowcore;

    hwaddr len = TARGET_PAGE_SIZE;

    int ilen = env->int_pgm_ilen;



    switch (ilen) {

    case ILEN_LATER:

        ilen = get_ilen(cpu_ldub_code(env, env->psw.addr));

        break;

    case ILEN_LATER_INC:

        ilen = get_ilen(cpu_ldub_code(env, env->psw.addr));

        env->psw.addr += ilen;

        break;

    default:

        assert(ilen == 2 || ilen == 4 || ilen == 6);

    }



    qemu_log_mask(CPU_LOG_INT, "%s: code=0x%x ilen=%d\n",

                  __func__, env->int_pgm_code, ilen);



    lowcore = cpu_physical_memory_map(env->psa, &len, 1);



    lowcore->pgm_ilen = cpu_to_be16(ilen);

    lowcore->pgm_code = cpu_to_be16(env->int_pgm_code);

    lowcore->program_old_psw.mask = cpu_to_be64(get_psw_mask(env));

    lowcore->program_old_psw.addr = cpu_to_be64(env->psw.addr);

    mask = be64_to_cpu(lowcore->program_new_psw.mask);

    addr = be64_to_cpu(lowcore->program_new_psw.addr);



    cpu_physical_memory_unmap(lowcore, len, 1, len);



    DPRINTF("%s: %x %x %" PRIx64 " %" PRIx64 "\n", __func__,

            env->int_pgm_code, ilen, env->psw.mask,

            env->psw.addr);



    load_psw(env, mask, addr);

}

static int flac_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    FlacEncodeContext *s;

    const int16_t *samples;

    int frame_bytes, out_bytes, ret;



    s = avctx->priv_data;



    /* when the last block is reached, update the header in extradata */

    if (!frame) {

        s->max_framesize = s->max_encoded_framesize;

        av_md5_final(s->md5ctx, s->md5sum);

        write_streaminfo(s, avctx->extradata);

        return 0;

    }

    samples = (const int16_t *)frame->data[0];



    /* change max_framesize for small final frame */

    if (frame->nb_samples < s->frame.blocksize) {

        s->max_framesize = ff_flac_get_max_frame_size(frame->nb_samples,

                                                      s->channels, 16);

    }



    init_frame(s, frame->nb_samples);



    copy_samples(s, samples);



    channel_decorrelation(s);



    remove_wasted_bits(s);



    frame_bytes = encode_frame(s);



    /* fallback to verbatim mode if the compressed frame is larger than it

       would be if encoded uncompressed. */

    if (frame_bytes > s->max_framesize) {

        s->frame.verbatim_only = 1;

        frame_bytes = encode_frame(s);

    }



    if ((ret = ff_alloc_packet(avpkt, frame_bytes))) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet\n");

        return ret;

    }



    out_bytes = write_frame(s, avpkt);



    s->frame_count++;

    s->sample_count += frame->nb_samples;

    if ((ret = update_md5_sum(s, samples)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error updating MD5 checksum\n");

        return ret;

    }

    if (out_bytes > s->max_encoded_framesize)

        s->max_encoded_framesize = out_bytes;

    if (out_bytes < s->min_framesize)

        s->min_framesize = out_bytes;



    avpkt->pts      = frame->pts;

    avpkt->duration = ff_samples_to_time_base(avctx, frame->nb_samples);

    avpkt->size     = out_bytes;

    *got_packet_ptr = 1;

    return 0;

}

static void decode_profile_tier_level(GetBitContext *gb, AVCodecContext *avctx,

                                      PTLCommon *ptl)

{

    int i;



    ptl->profile_space = get_bits(gb, 2);

    ptl->tier_flag     = get_bits1(gb);

    ptl->profile_idc   = get_bits(gb, 5);

    if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN)

        av_log(avctx, AV_LOG_DEBUG, "Main profile bitstream\n");

    else if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN_10)

        av_log(avctx, AV_LOG_DEBUG, "Main 10 profile bitstream\n");

    else if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN_STILL_PICTURE)

        av_log(avctx, AV_LOG_DEBUG, "Main Still Picture profile bitstream\n");

    else

        av_log(avctx, AV_LOG_WARNING, "Unknown HEVC profile: %d\n", ptl->profile_idc);



    for (i = 0; i < 32; i++)

        ptl->profile_compatibility_flag[i] = get_bits1(gb);

    ptl->progressive_source_flag    = get_bits1(gb);

    ptl->interlaced_source_flag     = get_bits1(gb);

    ptl->non_packed_constraint_flag = get_bits1(gb);

    ptl->frame_only_constraint_flag = get_bits1(gb);



    skip_bits(gb, 16); // XXX_reserved_zero_44bits[0..15]

    skip_bits(gb, 16); // XXX_reserved_zero_44bits[16..31]

    skip_bits(gb, 12); // XXX_reserved_zero_44bits[32..43]

}

static void predictor_decompress_fir_adapt(int32_t *error_buffer,

                                           int32_t *buffer_out,

                                           int output_size,

                                           int readsamplesize,

                                           int16_t *predictor_coef_table,

                                           int predictor_coef_num,

                                           int predictor_quantitization)

{

    int i;



    /* first sample always copies */

    *buffer_out = *error_buffer;



    if (!predictor_coef_num) {

        if (output_size <= 1)

            return;



        memcpy(&buffer_out[1], &error_buffer[1],

               (output_size - 1) * sizeof(*buffer_out));

        return;

    }



    if (predictor_coef_num == 31) {

        /* simple 1st-order prediction */

        if (output_size <= 1)

            return;

        for (i = 1; i < output_size; i++) {

            buffer_out[i] = sign_extend(buffer_out[i - 1] + error_buffer[i],

                                        readsamplesize);

        }

        return;

    }



    /* read warm-up samples */

    for (i = 0; i < predictor_coef_num; i++) {

        buffer_out[i + 1] = sign_extend(buffer_out[i] + error_buffer[i + 1],

                                        readsamplesize);

    }



    /* NOTE: 4 and 8 are very common cases that could be optimized. */



    /* general case */

    for (i = predictor_coef_num; i < output_size - 1; i++) {

        int j;

        int val = 0;

        int error_val = error_buffer[i + 1];

        int error_sign;

        int d = buffer_out[i - predictor_coef_num];



        for (j = 0; j < predictor_coef_num; j++) {

            val += (buffer_out[i - j] - d) *

                   predictor_coef_table[j];

        }



        val = (val + (1 << (predictor_quantitization - 1))) >>

              predictor_quantitization;

        val += d + error_val;



        buffer_out[i + 1] = sign_extend(val, readsamplesize);



        /* adapt LPC coefficients */

        error_sign = sign_only(error_val);

        if (error_sign) {

            for (j = predictor_coef_num - 1; j >= 0 && error_val * error_sign > 0; j--) {

                int sign;

                val  = d - buffer_out[i - j];

                sign = sign_only(val) * error_sign;

                predictor_coef_table[j] -= sign;

                val *= sign;

                error_val -= ((val >> predictor_quantitization) *

                              (predictor_coef_num - j));

            }

        }

    }

}

static ssize_t nic_receive(VLANClientState *nc, const uint8_t * buf, size_t size)

{

    /* TODO:

     * - Magic packets should set bit 30 in power management driver register.

     * - Interesting packets should set bit 29 in power management driver register.

     */

    EEPRO100State *s = DO_UPCAST(NICState, nc, nc)->opaque;

    uint16_t rfd_status = 0xa000;

    static const uint8_t broadcast_macaddr[6] =

        { 0xff, 0xff, 0xff, 0xff, 0xff, 0xff };



    /* TODO: check multiple IA bit. */

    if (s->configuration[20] & BIT(6)) {

        missing("Multiple IA bit");

        return -1;

    }



    if (s->configuration[8] & 0x80) {

        /* CSMA is disabled. */

        logout("%p received while CSMA is disabled\n", s);

        return -1;

    } else if (size < 64 && (s->configuration[7] & BIT(0))) {

        /* Short frame and configuration byte 7/0 (discard short receive) set:

         * Short frame is discarded */

        logout("%p received short frame (%zu byte)\n", s, size);

        s->statistics.rx_short_frame_errors++;

#if 0

        return -1;

#endif

    } else if ((size > MAX_ETH_FRAME_SIZE + 4) && !(s->configuration[18] & BIT(3))) {

        /* Long frame and configuration byte 18/3 (long receive ok) not set:

         * Long frames are discarded. */

        logout("%p received long frame (%zu byte), ignored\n", s, size);

        return -1;

    } else if (memcmp(buf, s->conf.macaddr.a, 6) == 0) {       /* !!! */

        /* Frame matches individual address. */

        /* TODO: check configuration byte 15/4 (ignore U/L). */

        TRACE(RXTX, logout("%p received frame for me, len=%zu\n", s, size));

    } else if (memcmp(buf, broadcast_macaddr, 6) == 0) {

        /* Broadcast frame. */

        TRACE(RXTX, logout("%p received broadcast, len=%zu\n", s, size));

        rfd_status |= 0x0002;

    } else if (buf[0] & 0x01) {

        /* Multicast frame. */

        TRACE(RXTX, logout("%p received multicast, len=%zu,%s\n", s, size, nic_dump(buf, size)));

        if (s->configuration[21] & BIT(3)) {

          /* Multicast all bit is set, receive all multicast frames. */

        } else {

          unsigned mcast_idx = compute_mcast_idx(buf);

          assert(mcast_idx < 64);

          if (s->mult[mcast_idx >> 3] & (1 << (mcast_idx & 7))) {

            /* Multicast frame is allowed in hash table. */

          } else if (s->configuration[15] & BIT(0)) {

              /* Promiscuous: receive all. */

              rfd_status |= 0x0004;

          } else {

              TRACE(RXTX, logout("%p multicast ignored\n", s));

              return -1;

          }

        }

        /* TODO: Next not for promiscuous mode? */

        rfd_status |= 0x0002;

    } else if (s->configuration[15] & BIT(0)) {

        /* Promiscuous: receive all. */

        TRACE(RXTX, logout("%p received frame in promiscuous mode, len=%zu\n", s, size));

        rfd_status |= 0x0004;

    } else {

        TRACE(RXTX, logout("%p received frame, ignored, len=%zu,%s\n", s, size,

              nic_dump(buf, size)));

        return size;

    }



    if (get_ru_state(s) != ru_ready) {

        /* No resources available. */

        logout("no resources, state=%u\n", get_ru_state(s));

        /* TODO: RNR interrupt only at first failed frame? */

        eepro100_rnr_interrupt(s);

        s->statistics.rx_resource_errors++;

#if 0

        assert(!"no resources");

#endif

        return -1;

    }

    /* !!! */

    eepro100_rx_t rx;

    cpu_physical_memory_read(s->ru_base + s->ru_offset, (uint8_t *) & rx,

                             offsetof(eepro100_rx_t, packet));

    uint16_t rfd_command = le16_to_cpu(rx.command);

    uint16_t rfd_size = le16_to_cpu(rx.size);



    if (size > rfd_size) {

        logout("Receive buffer (%" PRId16 " bytes) too small for data "

            "(%zu bytes); data truncated\n", rfd_size, size);

        size = rfd_size;

    }

    if (size < 64) {

        rfd_status |= 0x0080;

    }

    TRACE(OTHER, logout("command 0x%04x, link 0x%08x, addr 0x%08x, size %u\n",

          rfd_command, rx.link, rx.rx_buf_addr, rfd_size));

    stw_phys(s->ru_base + s->ru_offset + offsetof(eepro100_rx_t, status),

             rfd_status);

    stw_phys(s->ru_base + s->ru_offset + offsetof(eepro100_rx_t, count), size);

    /* Early receive interrupt not supported. */

#if 0

    eepro100_er_interrupt(s);

#endif

    /* Receive CRC Transfer not supported. */

    if (s->configuration[18] & BIT(2)) {

        missing("Receive CRC Transfer");

        return -1;

    }

    /* TODO: check stripping enable bit. */

#if 0

    assert(!(s->configuration[17] & BIT(0)));

#endif

    cpu_physical_memory_write(s->ru_base + s->ru_offset +

                              offsetof(eepro100_rx_t, packet), buf, size);

    s->statistics.rx_good_frames++;

    eepro100_fr_interrupt(s);

    s->ru_offset = le32_to_cpu(rx.link);

    if (rfd_command & COMMAND_EL) {

        /* EL bit is set, so this was the last frame. */

        logout("receive: Running out of frames\n");

        set_ru_state(s, ru_suspended);

    }

    if (rfd_command & COMMAND_S) {

        /* S bit is set. */

        set_ru_state(s, ru_suspended);

    }

    return size;

}

static void do_video_out(AVFormatContext *s, OutputStream *ost,

                         InputStream *ist, AVFrame *in_picture)

{

    int nb_frames, i, ret, format_video_sync;

    AVFrame *final_picture;

    AVCodecContext *enc;

    double sync_ipts;

    double duration = 0;

    int frame_size = 0;

    float quality = same_quant ? in_picture->quality

                               : ost->st->codec->global_quality;



    enc = ost->st->codec;



    if (ist->st->start_time != AV_NOPTS_VALUE && ist->st->first_dts != AV_NOPTS_VALUE) {

        duration = FFMAX(av_q2d(ist->st->time_base), av_q2d(ist->st->codec->time_base));

        if(ist->st->avg_frame_rate.num)

            duration= FFMAX(duration, 1/av_q2d(ist->st->avg_frame_rate));



        duration /= av_q2d(enc->time_base);

    }



    sync_ipts = get_sync_ipts(ost, in_picture->pts) / av_q2d(enc->time_base);



    /* by default, we output a single frame */

    nb_frames = 1;



    format_video_sync = video_sync_method;

    if (format_video_sync == VSYNC_AUTO)

        format_video_sync = (s->oformat->flags & AVFMT_VARIABLE_FPS) ? ((s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH : VSYNC_VFR) : 1;



    if (format_video_sync != VSYNC_PASSTHROUGH && format_video_sync != VSYNC_DROP) {

        double vdelta = sync_ipts - ost->sync_opts + duration;

        // FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

        if (vdelta < -1.1)

            nb_frames = 0;

        else if (format_video_sync == VSYNC_VFR) {

            if (vdelta <= -0.6) {

                nb_frames = 0;

            } else if (vdelta > 0.6)

                ost->sync_opts = lrintf(sync_ipts);

        } else if (vdelta > 1.1)

            nb_frames = lrintf(vdelta);

        if (nb_frames == 0) {

            ++nb_frames_drop;

            av_log(NULL, AV_LOG_VERBOSE, "*** drop!\n");

        } else if (nb_frames > 1) {

            nb_frames_dup += nb_frames - 1;

            av_log(NULL, AV_LOG_VERBOSE, "*** %d dup!\n", nb_frames - 1);

        }

    } else

        ost->sync_opts = lrintf(sync_ipts);



    nb_frames = FFMIN(nb_frames, ost->max_frames - ost->frame_number);

    if (nb_frames <= 0)

        return;



    do_video_resample(ost, ist, in_picture, &final_picture);



    /* duplicates frame if needed */

    for (i = 0; i < nb_frames; i++) {

        AVPacket pkt;

        av_init_packet(&pkt);

        pkt.data = NULL;

        pkt.size = 0;



        if (s->oformat->flags & AVFMT_RAWPICTURE &&

            enc->codec->id == CODEC_ID_RAWVIDEO) {

            /* raw pictures are written as AVPicture structure to

               avoid any copies. We support temporarily the older

               method. */

            enc->coded_frame->interlaced_frame = in_picture->interlaced_frame;

            enc->coded_frame->top_field_first  = in_picture->top_field_first;

            pkt.data   = (uint8_t *)final_picture;

            pkt.size   =  sizeof(AVPicture);

            pkt.pts    = av_rescale_q(ost->sync_opts, enc->time_base, ost->st->time_base);

            pkt.flags |= AV_PKT_FLAG_KEY;



            write_frame(s, &pkt, ost);

        } else {

            int got_packet;

            AVFrame big_picture;



            big_picture = *final_picture;

            /* better than nothing: use input picture interlaced

               settings */

            big_picture.interlaced_frame = in_picture->interlaced_frame;

            if (ost->st->codec->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME)) {

                if (ost->top_field_first == -1)

                    big_picture.top_field_first = in_picture->top_field_first;

                else

                    big_picture.top_field_first = !!ost->top_field_first;

            }



            /* handles same_quant here. This is not correct because it may

               not be a global option */

            big_picture.quality = quality;

            if (!enc->me_threshold)

                big_picture.pict_type = 0;

            big_picture.pts = ost->sync_opts;

            if (ost->forced_kf_index < ost->forced_kf_count &&

                big_picture.pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

                big_picture.pict_type = AV_PICTURE_TYPE_I;

                ost->forced_kf_index++;

            }

            ret = avcodec_encode_video2(enc, &pkt, &big_picture, &got_packet);

            if (ret < 0) {

                av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

                exit_program(1);

            }



            if (got_packet) {

                if (pkt.pts == AV_NOPTS_VALUE && !(enc->codec->capabilities & CODEC_CAP_DELAY))

                    pkt.pts = ost->sync_opts;



                if (pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts = av_rescale_q(pkt.pts, enc->time_base, ost->st->time_base);

                if (pkt.dts != AV_NOPTS_VALUE)

                    pkt.dts = av_rescale_q(pkt.dts, enc->time_base, ost->st->time_base);



                if (debug_ts) {

                    av_log(NULL, AV_LOG_INFO, "encoder -> type:video "

                           "pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s\n",

                           av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &ost->st->time_base),

                           av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &ost->st->time_base));

                }



                if (format_video_sync == VSYNC_DROP)

                    pkt.pts = pkt.dts = AV_NOPTS_VALUE;



                write_frame(s, &pkt, ost);

                frame_size = pkt.size;

                video_size += pkt.size;




                /* if two pass, output log */

                if (ost->logfile && enc->stats_out) {

                    fprintf(ost->logfile, "%s", enc->stats_out);

                }

            }

        }

        ost->sync_opts++;

        /*

         * For video, number of frames in == number of packets out.

         * But there may be reordering, so we can't throw away frames on encoder

         * flush, we need to limit them here, before they go into encoder.

         */

        ost->frame_number++;

    }

    if (vstats_filename && frame_size)

        do_video_stats(output_files[ost->file_index].ctx, ost, frame_size);

}

static int hls_start(AVFormatContext *s, VariantStream *vs)

{

    HLSContext *c = s->priv_data;

    AVFormatContext *oc = vs->avf;

    AVFormatContext *vtt_oc = vs->vtt_avf;

    AVDictionary *options = NULL;

    char *filename, iv_string[KEYSIZE*2 + 1];

    int err = 0;



    if (c->flags & HLS_SINGLE_FILE) {

        av_strlcpy(oc->filename, vs->basename,

                   sizeof(oc->filename));

        if (vs->vtt_basename)

            av_strlcpy(vtt_oc->filename, vs->vtt_basename,

                  sizeof(vtt_oc->filename));

    } else if (c->max_seg_size > 0) {

        if (replace_int_data_in_filename(oc->filename, sizeof(oc->filename),

#if FF_API_HLS_WRAP

            vs->basename, 'd', c->wrap ? vs->sequence % c->wrap : vs->sequence) < 1) {

#else

            vs->basename, 'd', vs->sequence) < 1) {

#endif

                av_log(oc, AV_LOG_ERROR, "Invalid segment filename template '%s', you can try to use -use_localtime 1 with it\n", vs->basename);

                return AVERROR(EINVAL);

        }

    } else {

        if (c->use_localtime) {

            time_t now0;

            struct tm *tm, tmpbuf;

            time(&now0);

            tm = localtime_r(&now0, &tmpbuf);

            if (!strftime(oc->filename, sizeof(oc->filename), vs->basename, tm)) {

                av_log(oc, AV_LOG_ERROR, "Could not get segment filename with use_localtime\n");

                return AVERROR(EINVAL);

            }



            err = sls_flag_use_localtime_filename(oc, c, vs);

            if (err < 0) {

                return AVERROR(ENOMEM);

            }



            if (c->use_localtime_mkdir) {

                const char *dir;

                char *fn_copy = av_strdup(oc->filename);

                if (!fn_copy) {

                    return AVERROR(ENOMEM);

                }

                dir = av_dirname(fn_copy);

                if (mkdir_p(dir) == -1 && errno != EEXIST) {

                    av_log(oc, AV_LOG_ERROR, "Could not create directory %s with use_localtime_mkdir\n", dir);

                    av_free(fn_copy);

                    return AVERROR(errno);

                }

                av_free(fn_copy);

            }

        } else if (replace_int_data_in_filename(oc->filename, sizeof(oc->filename),

#if FF_API_HLS_WRAP

                   vs->basename, 'd', c->wrap ? vs->sequence % c->wrap : vs->sequence) < 1) {

#else

                   vs->basename, 'd', vs->sequence) < 1) {

#endif

            av_log(oc, AV_LOG_ERROR, "Invalid segment filename template '%s' you can try to use -use_localtime 1 with it\n", vs->basename);

            return AVERROR(EINVAL);

        }

        if( vs->vtt_basename) {

            if (replace_int_data_in_filename(vtt_oc->filename, sizeof(vtt_oc->filename),

#if FF_API_HLS_WRAP

                vs->vtt_basename, 'd', c->wrap ? vs->sequence % c->wrap : vs->sequence) < 1) {

#else

                vs->vtt_basename, 'd', vs->sequence) < 1) {

#endif

                av_log(vtt_oc, AV_LOG_ERROR, "Invalid segment filename template '%s'\n", vs->vtt_basename);

                return AVERROR(EINVAL);

            }

       }

    }

    vs->number++;



    set_http_options(s, &options, c);



    if (c->flags & HLS_TEMP_FILE) {

        av_strlcat(oc->filename, ".tmp", sizeof(oc->filename));

    }



    if (c->key_info_file || c->encrypt) {

        if (c->key_info_file && c->encrypt) {

            av_log(s, AV_LOG_WARNING, "Cannot use both -hls_key_info_file and -hls_enc,"

                  " will use -hls_key_info_file priority\n");

        }



        if (!c->encrypt_started || (c->flags & HLS_PERIODIC_REKEY)) {

            if (c->key_info_file) {

                if ((err = hls_encryption_start(s)) < 0)

                    goto fail;

            } else {

                if ((err = do_encrypt(s, vs)) < 0)

                    goto fail;

            }

            c->encrypt_started = 1;

        }

        if ((err = av_dict_set(&options, "encryption_key", c->key_string, 0))

                < 0)

            goto fail;

        err = av_strlcpy(iv_string, c->iv_string, sizeof(iv_string));

        if (!err)

            snprintf(iv_string, sizeof(iv_string), "%032"PRIx64, vs->sequence);

        if ((err = av_dict_set(&options, "encryption_iv", iv_string, 0)) < 0)

           goto fail;



        filename = av_asprintf("crypto:%s", oc->filename);

        if (!filename) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        err = hlsenc_io_open(s, &oc->pb, filename, &options);

        av_free(filename);

        av_dict_free(&options);

        if (err < 0)

            return err;

    } else if (c->segment_type != SEGMENT_TYPE_FMP4) {

        if ((err = hlsenc_io_open(s, &oc->pb, oc->filename, &options)) < 0)

            goto fail;

    }

    if (vs->vtt_basename) {

        set_http_options(s, &options, c);

        if ((err = hlsenc_io_open(s, &vtt_oc->pb, vtt_oc->filename, &options)) < 0)

            goto fail;

    }

    av_dict_free(&options);



    if (c->segment_type != SEGMENT_TYPE_FMP4) {

        /* We only require one PAT/PMT per segment. */

        if (oc->oformat->priv_class && oc->priv_data) {

            char period[21];



            snprintf(period, sizeof(period), "%d", (INT_MAX / 2) - 1);



            av_opt_set(oc->priv_data, "mpegts_flags", "resend_headers", 0);

            av_opt_set(oc->priv_data, "sdt_period", period, 0);

            av_opt_set(oc->priv_data, "pat_period", period, 0);

        }

    }



    if (vs->vtt_basename) {

        err = avformat_write_header(vtt_oc,NULL);

        if (err < 0)

            return err;

    }



    return 0;

fail:

    av_dict_free(&options);



    return err;

}

_eth_get_rss_ex_src_addr(const struct iovec *pkt, int pkt_frags,

                        size_t dsthdr_offset,

                        struct ip6_ext_hdr *ext_hdr,

                        struct in6_address *src_addr)

{

    size_t bytes_left = (ext_hdr->ip6r_len + 1) * 8 - sizeof(*ext_hdr);

    struct ip6_option_hdr opthdr;

    size_t opt_offset = dsthdr_offset + sizeof(*ext_hdr);



    while (bytes_left > sizeof(opthdr)) {

        size_t input_size = iov_size(pkt, pkt_frags);

        size_t bytes_read, optlen;



        if (input_size < opt_offset) {

            return false;

        }



        bytes_read = iov_to_buf(pkt, pkt_frags, opt_offset,

                                &opthdr, sizeof(opthdr));



        if (bytes_read != sizeof(opthdr)) {

            return false;

        }



        optlen = (opthdr.type == IP6_OPT_PAD1) ? 1

                                               : (opthdr.len + sizeof(opthdr));



        if (optlen > bytes_left) {

            return false;

        }



        if (opthdr.type == IP6_OPT_HOME) {

            size_t input_size = iov_size(pkt, pkt_frags);



            if (input_size < opt_offset + sizeof(opthdr)) {

                return false;

            }



            bytes_read = iov_to_buf(pkt, pkt_frags,

                                    opt_offset + sizeof(opthdr),

                                    src_addr, sizeof(*src_addr));



            return bytes_read == sizeof(src_addr);

        }



        opt_offset += optlen;

        bytes_left -= optlen;

    }



    return false;

}

static bool send_gradient_rect(VncState *vs, int w, int h)

{

    int stream = 3;

    int level = tight_conf[vs->tight_compression].gradient_zlib_level;

    size_t bytes;



    if (vs->clientds.pf.bytes_per_pixel == 1)

        return send_full_color_rect(vs, w, h);



    vnc_write_u8(vs, (stream | VNC_TIGHT_EXPLICIT_FILTER) << 4);

    vnc_write_u8(vs, VNC_TIGHT_FILTER_GRADIENT);



    buffer_reserve(&vs->tight_gradient, w * 3 * sizeof (int));



    if (vs->tight_pixel24) {

        tight_filter_gradient24(vs, vs->tight.buffer, w, h);

        bytes = 3;

    } else if (vs->clientds.pf.bytes_per_pixel == 4) {

        tight_filter_gradient32(vs, (uint32_t *)vs->tight.buffer, w, h);

        bytes = 4;

    } else {

        tight_filter_gradient16(vs, (uint16_t *)vs->tight.buffer, w, h);

        bytes = 2;

    }



    buffer_reset(&vs->tight_gradient);



    bytes = w * h * bytes;

    vs->tight.offset = bytes;



    bytes = tight_compress_data(vs, stream, bytes,

                                level, Z_FILTERED);

    return (bytes >= 0);

}

int64_t av_gettime_relative(void)

{

#if HAVE_CLOCK_GETTIME && defined(CLOCK_MONOTONIC)

    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);

    return (int64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

#else

    return av_gettime() + 42 * 60 * 60 * INT64_C(1000000);

#endif

}

void ppc_tlb_invalidate_all (CPUPPCState *env)

{

    switch (env->mmu_model) {

    case POWERPC_MMU_SOFT_6xx:

    case POWERPC_MMU_SOFT_74xx:

        ppc6xx_tlb_invalidate_all(env);

        break;

    case POWERPC_MMU_SOFT_4xx:

    case POWERPC_MMU_SOFT_4xx_Z:

        ppc4xx_tlb_invalidate_all(env);

        break;

    case POWERPC_MMU_REAL_4xx:

        cpu_abort(env, "No TLB for PowerPC 4xx in real mode\n");

        break;

    case POWERPC_MMU_BOOKE:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_BOOKE_FSL:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_601:

        /* XXX: TODO */

        cpu_abort(env, "MMU model not implemented\n");

        break;

    case POWERPC_MMU_32B:

#if defined(TARGET_PPC64)

    case POWERPC_MMU_64B:

    case POWERPC_MMU_64BRIDGE:

#endif /* defined(TARGET_PPC64) */

        tlb_flush(env, 1);

        break;

    default:

        /* XXX: TODO */

        cpu_abort(env, "Unknown MMU model %d\n", env->mmu_model);

        break;

    }

}

start_list(Visitor *v, const char *name, GenericList **list, size_t size,

           Error **errp)

{

    StringInputVisitor *siv = to_siv(v);



    /* We don't support visits without a list */

    assert(list);



    if (parse_str(siv, name, errp) < 0) {

        *list = NULL;

        return;

    }



    siv->cur_range = g_list_first(siv->ranges);

    if (siv->cur_range) {

        Range *r = siv->cur_range->data;

        if (r) {

            siv->cur = r->begin;

        }

        *list = g_malloc0(size);

    } else {

        *list = NULL;

    }

}

static int vpc_create(const char *filename, QEMUOptionParameter *options)

{

    uint8_t buf[1024];

    struct vhd_footer *footer = (struct vhd_footer *) buf;

    QEMUOptionParameter *disk_type_param;

    int fd, i;

    uint16_t cyls = 0;

    uint8_t heads = 0;

    uint8_t secs_per_cyl = 0;

    int64_t total_sectors;

    int64_t total_size;

    int disk_type;

    int ret = -EIO;



    /* Read out options */

    total_size = get_option_parameter(options, BLOCK_OPT_SIZE)->value.n;



    disk_type_param = get_option_parameter(options, BLOCK_OPT_SUBFMT);

    if (disk_type_param && disk_type_param->value.s) {

        if (!strcmp(disk_type_param->value.s, "dynamic")) {

            disk_type = VHD_DYNAMIC;

        } else if (!strcmp(disk_type_param->value.s, "fixed")) {

            disk_type = VHD_FIXED;

        } else {

            return -EINVAL;

        }

    } else {

        disk_type = VHD_DYNAMIC;

    }



    /* Create the file */

    fd = qemu_open(filename, O_WRONLY | O_CREAT | O_TRUNC | O_BINARY, 0644);

    if (fd < 0) {

        return -EIO;

    }



    /*

     * Calculate matching total_size and geometry. Increase the number of

     * sectors requested until we get enough (or fail). This ensures that

     * qemu-img convert doesn't truncate images, but rather rounds up.

     */

    total_sectors = total_size / BDRV_SECTOR_SIZE;

    for (i = 0; total_sectors > (int64_t)cyls * heads * secs_per_cyl; i++) {

        if (calculate_geometry(total_sectors + i, &cyls, &heads,

                               &secs_per_cyl))

        {

            ret = -EFBIG;

            goto fail;

        }

    }



    total_sectors = (int64_t) cyls * heads * secs_per_cyl;



    /* Prepare the Hard Disk Footer */

    memset(buf, 0, 1024);



    memcpy(footer->creator, "conectix", 8);

    /* TODO Check if "qemu" creator_app is ok for VPC */

    memcpy(footer->creator_app, "qemu", 4);

    memcpy(footer->creator_os, "Wi2k", 4);



    footer->features = be32_to_cpu(0x02);

    footer->version = be32_to_cpu(0x00010000);

    if (disk_type == VHD_DYNAMIC) {

        footer->data_offset = be64_to_cpu(HEADER_SIZE);

    } else {

        footer->data_offset = be64_to_cpu(0xFFFFFFFFFFFFFFFFULL);

    }

    footer->timestamp = be32_to_cpu(time(NULL) - VHD_TIMESTAMP_BASE);



    /* Version of Virtual PC 2007 */

    footer->major = be16_to_cpu(0x0005);

    footer->minor = be16_to_cpu(0x0003);

    if (disk_type == VHD_DYNAMIC) {

        footer->orig_size = be64_to_cpu(total_sectors * 512);

        footer->size = be64_to_cpu(total_sectors * 512);

    } else {

        footer->orig_size = be64_to_cpu(total_size);

        footer->size = be64_to_cpu(total_size);

    }

    footer->cyls = be16_to_cpu(cyls);

    footer->heads = heads;

    footer->secs_per_cyl = secs_per_cyl;



    footer->type = be32_to_cpu(disk_type);



    /* TODO uuid is missing */



    footer->checksum = be32_to_cpu(vpc_checksum(buf, HEADER_SIZE));



    if (disk_type == VHD_DYNAMIC) {

        ret = create_dynamic_disk(fd, buf, total_sectors);

    } else {

        ret = create_fixed_disk(fd, buf, total_size);

    }



 fail:

    qemu_close(fd);

    return ret;

}

void main_loop_wait(int nonblocking)

{

    fd_set rfds, wfds, xfds;

    int ret, nfds;

    struct timeval tv;

    int timeout;



    if (nonblocking)

        timeout = 0;

    else {

        timeout = qemu_calculate_timeout();

        qemu_bh_update_timeout(&timeout);

    }



    os_host_main_loop_wait(&timeout);



    tv.tv_sec = timeout / 1000;

    tv.tv_usec = (timeout % 1000) * 1000;



    /* poll any events */

    /* XXX: separate device handlers from system ones */

    nfds = -1;

    FD_ZERO(&rfds);

    FD_ZERO(&wfds);

    FD_ZERO(&xfds);

    qemu_iohandler_fill(&nfds, &rfds, &wfds, &xfds);

    slirp_select_fill(&nfds, &rfds, &wfds, &xfds);



    qemu_mutex_unlock_iothread();

    ret = select(nfds + 1, &rfds, &wfds, &xfds, &tv);

    qemu_mutex_lock_iothread();



    qemu_iohandler_poll(&rfds, &wfds, &xfds, ret);

    slirp_select_poll(&rfds, &wfds, &xfds, (ret < 0));



    qemu_run_all_timers();



    /* Check bottom-halves last in case any of the earlier events triggered

       them.  */

    qemu_bh_poll();



}

static int curl_aio_flush(void *opaque)

{

    BDRVCURLState *s = opaque;

    int i, j;



    for (i=0; i < CURL_NUM_STATES; i++) {

        for(j=0; j < CURL_NUM_ACB; j++) {

            if (s->states[i].acb[j]) {

                return 1;

            }

        }

    }

    return 0;

}

static const mon_cmd_t *monitor_parse_command(Monitor *mon,

                                              const char *cmdline,

                                              int start,

                                              mon_cmd_t *table,

                                              QDict *qdict)

{

    const char *p, *typestr;

    int c;

    const mon_cmd_t *cmd;

    char cmdname[256];

    char buf[1024];

    char *key;



    /* extract the command name */

    p = get_command_name(cmdline + start, cmdname, sizeof(cmdname));

    if (!p)

        return NULL;



    cmd = search_dispatch_table(table, cmdname);

    if (!cmd) {

        monitor_printf(mon, "unknown command: '%.*s'\n",

                       (int)(p - cmdline), cmdline);

        return NULL;

    }



    /* filter out following useless space */

    while (qemu_isspace(*p)) {

        p++;

    }

    /* search sub command */

    if (cmd->sub_table != NULL) {

        /* check if user set additional command */

        if (*p == '\0') {

            return cmd;

        }

        return monitor_parse_command(mon, cmdline, p - cmdline,

                                     cmd->sub_table, qdict);

    }



    /* parse the parameters */

    typestr = cmd->args_type;

    for(;;) {

        typestr = key_get_info(typestr, &key);

        if (!typestr)

            break;

        c = *typestr;

        typestr++;

        switch(c) {

        case 'F':

        case 'B':

        case 's':

            {

                int ret;



                while (qemu_isspace(*p))

                    p++;

                if (*typestr == '?') {

                    typestr++;

                    if (*p == '\0') {

                        /* no optional string: NULL argument */

                        break;

                    }

                }

                ret = get_str(buf, sizeof(buf), &p);

                if (ret < 0) {

                    switch(c) {

                    case 'F':

                        monitor_printf(mon, "%s: filename expected\n",

                                       cmdname);

                        break;

                    case 'B':

                        monitor_printf(mon, "%s: block device name expected\n",

                                       cmdname);

                        break;

                    default:

                        monitor_printf(mon, "%s: string expected\n", cmdname);

                        break;

                    }

                    goto fail;

                }

                qdict_put(qdict, key, qstring_from_str(buf));

            }

            break;

        case 'O':

            {

                QemuOptsList *opts_list;

                QemuOpts *opts;



                opts_list = qemu_find_opts(key);

                if (!opts_list || opts_list->desc->name) {

                    goto bad_type;

                }

                while (qemu_isspace(*p)) {

                    p++;

                }

                if (!*p)

                    break;

                if (get_str(buf, sizeof(buf), &p) < 0) {

                    goto fail;

                }

                opts = qemu_opts_parse(opts_list, buf, 1);

                if (!opts) {

                    goto fail;

                }

                qemu_opts_to_qdict(opts, qdict);

                qemu_opts_del(opts);

            }

            break;

        case '/':

            {

                int count, format, size;



                while (qemu_isspace(*p))

                    p++;

                if (*p == '/') {

                    /* format found */

                    p++;

                    count = 1;

                    if (qemu_isdigit(*p)) {

                        count = 0;

                        while (qemu_isdigit(*p)) {

                            count = count * 10 + (*p - '0');

                            p++;

                        }

                    }

                    size = -1;

                    format = -1;

                    for(;;) {

                        switch(*p) {

                        case 'o':

                        case 'd':

                        case 'u':

                        case 'x':

                        case 'i':

                        case 'c':

                            format = *p++;

                            break;

                        case 'b':

                            size = 1;

                            p++;

                            break;

                        case 'h':

                            size = 2;

                            p++;

                            break;

                        case 'w':

                            size = 4;

                            p++;

                            break;

                        case 'g':

                        case 'L':

                            size = 8;

                            p++;

                            break;

                        default:

                            goto next;

                        }

                    }

                next:

                    if (*p != '\0' && !qemu_isspace(*p)) {

                        monitor_printf(mon, "invalid char in format: '%c'\n",

                                       *p);

                        goto fail;

                    }

                    if (format < 0)

                        format = default_fmt_format;

                    if (format != 'i') {

                        /* for 'i', not specifying a size gives -1 as size */

                        if (size < 0)

                            size = default_fmt_size;

                        default_fmt_size = size;

                    }

                    default_fmt_format = format;

                } else {

                    count = 1;

                    format = default_fmt_format;

                    if (format != 'i') {

                        size = default_fmt_size;

                    } else {

                        size = -1;

                    }

                }

                qdict_put(qdict, "count", qint_from_int(count));

                qdict_put(qdict, "format", qint_from_int(format));

                qdict_put(qdict, "size", qint_from_int(size));

            }

            break;

        case 'i':

        case 'l':

        case 'M':

            {

                int64_t val;



                while (qemu_isspace(*p))

                    p++;

                if (*typestr == '?' || *typestr == '.') {

                    if (*typestr == '?') {

                        if (*p == '\0') {

                            typestr++;

                            break;

                        }

                    } else {

                        if (*p == '.') {

                            p++;

                            while (qemu_isspace(*p))

                                p++;

                        } else {

                            typestr++;

                            break;

                        }

                    }

                    typestr++;

                }

                if (get_expr(mon, &val, &p))

                    goto fail;

                /* Check if 'i' is greater than 32-bit */

                if ((c == 'i') && ((val >> 32) & 0xffffffff)) {

                    monitor_printf(mon, "\'%s\' has failed: ", cmdname);

                    monitor_printf(mon, "integer is for 32-bit values\n");

                    goto fail;

                } else if (c == 'M') {

                    if (val < 0) {

                        monitor_printf(mon, "enter a positive value\n");

                        goto fail;

                    }

                    val <<= 20;

                }

                qdict_put(qdict, key, qint_from_int(val));

            }

            break;

        case 'o':

            {

                int64_t val;

                char *end;



                while (qemu_isspace(*p)) {

                    p++;

                }

                if (*typestr == '?') {

                    typestr++;

                    if (*p == '\0') {

                        break;

                    }

                }

                val = strtosz(p, &end);

                if (val < 0) {

                    monitor_printf(mon, "invalid size\n");

                    goto fail;

                }

                qdict_put(qdict, key, qint_from_int(val));

                p = end;

            }

            break;

        case 'T':

            {

                double val;



                while (qemu_isspace(*p))

                    p++;

                if (*typestr == '?') {

                    typestr++;

                    if (*p == '\0') {

                        break;

                    }

                }

                if (get_double(mon, &val, &p) < 0) {

                    goto fail;

                }

                if (p[0] && p[1] == 's') {

                    switch (*p) {

                    case 'm':

                        val /= 1e3; p += 2; break;

                    case 'u':

                        val /= 1e6; p += 2; break;

                    case 'n':

                        val /= 1e9; p += 2; break;

                    }

                }

                if (*p && !qemu_isspace(*p)) {

                    monitor_printf(mon, "Unknown unit suffix\n");

                    goto fail;

                }

                qdict_put(qdict, key, qfloat_from_double(val));

            }

            break;

        case 'b':

            {

                const char *beg;

                bool val;



                while (qemu_isspace(*p)) {

                    p++;

                }

                beg = p;

                while (qemu_isgraph(*p)) {

                    p++;

                }

                if (p - beg == 2 && !memcmp(beg, "on", p - beg)) {

                    val = true;

                } else if (p - beg == 3 && !memcmp(beg, "off", p - beg)) {

                    val = false;

                } else {

                    monitor_printf(mon, "Expected 'on' or 'off'\n");

                    goto fail;

                }

                qdict_put(qdict, key, qbool_from_bool(val));

            }

            break;

        case '-':

            {

                const char *tmp = p;

                int skip_key = 0;

                /* option */



                c = *typestr++;

                if (c == '\0')

                    goto bad_type;

                while (qemu_isspace(*p))

                    p++;

                if (*p == '-') {

                    p++;

                    if(c != *p) {

                        if(!is_valid_option(p, typestr)) {



                            monitor_printf(mon, "%s: unsupported option -%c\n",

                                           cmdname, *p);

                            goto fail;

                        } else {

                            skip_key = 1;

                        }

                    }

                    if(skip_key) {

                        p = tmp;

                    } else {

                        /* has option */

                        p++;

                        qdict_put(qdict, key, qbool_from_bool(true));

                    }

                }

            }

            break;

        case 'S':

            {

                /* package all remaining string */

                int len;



                while (qemu_isspace(*p)) {

                    p++;

                }

                if (*typestr == '?') {

                    typestr++;

                    if (*p == '\0') {

                        /* no remaining string: NULL argument */

                        break;

                    }

                }

                len = strlen(p);

                if (len <= 0) {

                    monitor_printf(mon, "%s: string expected\n",

                                   cmdname);

                    break;

                }

                qdict_put(qdict, key, qstring_from_str(p));

                p += len;

            }

            break;

        default:

        bad_type:

            monitor_printf(mon, "%s: unknown type '%c'\n", cmdname, c);

            goto fail;

        }

        g_free(key);

        key = NULL;

    }

    /* check that all arguments were parsed */

    while (qemu_isspace(*p))

        p++;

    if (*p != '\0') {

        monitor_printf(mon, "%s: extraneous characters at the end of line\n",

                       cmdname);

        goto fail;

    }



    return cmd;



fail:

    g_free(key);

    return NULL;

}

void gen_intermediate_code(CPUPPCState *env, struct TranslationBlock *tb)

{

    PowerPCCPU *cpu = ppc_env_get_cpu(env);

    CPUState *cs = CPU(cpu);

    DisasContext ctx, *ctxp = &ctx;

    opc_handler_t **table, *handler;

    target_ulong pc_start;

    int num_insns;

    int max_insns;



    pc_start = tb->pc;

    ctx.nip = pc_start;

    ctx.tb = tb;

    ctx.exception = POWERPC_EXCP_NONE;

    ctx.spr_cb = env->spr_cb;

    ctx.pr = msr_pr;

    ctx.mem_idx = env->dmmu_idx;

    ctx.dr = msr_dr;

#if !defined(CONFIG_USER_ONLY)

    ctx.hv = msr_hv || !env->has_hv_mode;

#endif

    ctx.insns_flags = env->insns_flags;

    ctx.insns_flags2 = env->insns_flags2;

    ctx.access_type = -1;

    ctx.le_mode = !!(env->hflags & (1 << MSR_LE));

    ctx.default_tcg_memop_mask = ctx.le_mode ? MO_LE : MO_BE;

#if defined(TARGET_PPC64)

    ctx.sf_mode = msr_is_64bit(env, env->msr);

    ctx.has_cfar = !!(env->flags & POWERPC_FLAG_CFAR);

#endif

    if (env->mmu_model == POWERPC_MMU_32B ||

        env->mmu_model == POWERPC_MMU_601 ||

        (env->mmu_model & POWERPC_MMU_64B))

            ctx.lazy_tlb_flush = true;



    ctx.fpu_enabled = !!msr_fp;

    if ((env->flags & POWERPC_FLAG_SPE) && msr_spe)

        ctx.spe_enabled = !!msr_spe;

    else

        ctx.spe_enabled = false;

    if ((env->flags & POWERPC_FLAG_VRE) && msr_vr)

        ctx.altivec_enabled = !!msr_vr;

    else

        ctx.altivec_enabled = false;

    if ((env->flags & POWERPC_FLAG_VSX) && msr_vsx) {

        ctx.vsx_enabled = !!msr_vsx;

    } else {

        ctx.vsx_enabled = false;

    }

#if defined(TARGET_PPC64)

    if ((env->flags & POWERPC_FLAG_TM) && msr_tm) {

        ctx.tm_enabled = !!msr_tm;

    } else {

        ctx.tm_enabled = false;

    }

#endif

    if ((env->flags & POWERPC_FLAG_SE) && msr_se)

        ctx.singlestep_enabled = CPU_SINGLE_STEP;

    else

        ctx.singlestep_enabled = 0;

    if ((env->flags & POWERPC_FLAG_BE) && msr_be)

        ctx.singlestep_enabled |= CPU_BRANCH_STEP;

    if (unlikely(cs->singlestep_enabled)) {

        ctx.singlestep_enabled |= GDBSTUB_SINGLE_STEP;

    }

#if defined (DO_SINGLE_STEP) && 0

    /* Single step trace mode */

    msr_se = 1;

#endif

    num_insns = 0;

    max_insns = tb->cflags & CF_COUNT_MASK;

    if (max_insns == 0) {

        max_insns = CF_COUNT_MASK;

    }

    if (max_insns > TCG_MAX_INSNS) {

        max_insns = TCG_MAX_INSNS;

    }



    gen_tb_start(tb);

    tcg_clear_temp_count();

    /* Set env in case of segfault during code fetch */

    while (ctx.exception == POWERPC_EXCP_NONE && !tcg_op_buf_full()) {

        tcg_gen_insn_start(ctx.nip);

        num_insns++;



        if (unlikely(cpu_breakpoint_test(cs, ctx.nip, BP_ANY))) {

            gen_debug_exception(ctxp);

            /* The address covered by the breakpoint must be included in

               [tb->pc, tb->pc + tb->size) in order to for it to be

               properly cleared -- thus we increment the PC here so that

               the logic setting tb->size below does the right thing.  */

            ctx.nip += 4;

            break;

        }



        LOG_DISAS("----------------\n");

        LOG_DISAS("nip=" TARGET_FMT_lx " super=%d ir=%d\n",

                  ctx.nip, ctx.mem_idx, (int)msr_ir);

        if (num_insns == max_insns && (tb->cflags & CF_LAST_IO))

            gen_io_start();

        if (unlikely(need_byteswap(&ctx))) {

            ctx.opcode = bswap32(cpu_ldl_code(env, ctx.nip));

        } else {

            ctx.opcode = cpu_ldl_code(env, ctx.nip);

        }

        LOG_DISAS("translate opcode %08x (%02x %02x %02x) (%s)\n",

                    ctx.opcode, opc1(ctx.opcode), opc2(ctx.opcode),

                    opc3(ctx.opcode), ctx.le_mode ? "little" : "big");

        ctx.nip += 4;

        table = env->opcodes;

        handler = table[opc1(ctx.opcode)];

        if (is_indirect_opcode(handler)) {

            table = ind_table(handler);

            handler = table[opc2(ctx.opcode)];

            if (is_indirect_opcode(handler)) {

                table = ind_table(handler);

                handler = table[opc3(ctx.opcode)];

            }

        }

        /* Is opcode *REALLY* valid ? */

        if (unlikely(handler->handler == &gen_invalid)) {

            qemu_log_mask(LOG_GUEST_ERROR, "invalid/unsupported opcode: "

                          "%02x - %02x - %02x (%08x) " TARGET_FMT_lx " %d\n",

                          opc1(ctx.opcode), opc2(ctx.opcode),

                          opc3(ctx.opcode), ctx.opcode, ctx.nip - 4, (int)msr_ir);

        } else {

            uint32_t inval;



            if (unlikely(handler->type & (PPC_SPE | PPC_SPE_SINGLE | PPC_SPE_DOUBLE) && Rc(ctx.opcode))) {

                inval = handler->inval2;

            } else {

                inval = handler->inval1;

            }



            if (unlikely((ctx.opcode & inval) != 0)) {

                qemu_log_mask(LOG_GUEST_ERROR, "invalid bits: %08x for opcode: "

                              "%02x - %02x - %02x (%08x) " TARGET_FMT_lx "\n",

                              ctx.opcode & inval, opc1(ctx.opcode),

                              opc2(ctx.opcode), opc3(ctx.opcode),

                              ctx.opcode, ctx.nip - 4);

                gen_inval_exception(ctxp, POWERPC_EXCP_INVAL_INVAL);

                break;

            }

        }

        (*(handler->handler))(&ctx);

#if defined(DO_PPC_STATISTICS)

        handler->count++;

#endif

        /* Check trace mode exceptions */

        if (unlikely(ctx.singlestep_enabled & CPU_SINGLE_STEP &&

                     (ctx.nip <= 0x100 || ctx.nip > 0xF00) &&

                     ctx.exception != POWERPC_SYSCALL &&

                     ctx.exception != POWERPC_EXCP_TRAP &&

                     ctx.exception != POWERPC_EXCP_BRANCH)) {

            gen_exception(ctxp, POWERPC_EXCP_TRACE);

        } else if (unlikely(((ctx.nip & (TARGET_PAGE_SIZE - 1)) == 0) ||

                            (cs->singlestep_enabled) ||

                            singlestep ||

                            num_insns >= max_insns)) {

            /* if we reach a page boundary or are single stepping, stop

             * generation

             */

            break;

        }

        if (tcg_check_temp_count()) {

            fprintf(stderr, "Opcode %02x %02x %02x (%08x) leaked temporaries\n",

                    opc1(ctx.opcode), opc2(ctx.opcode), opc3(ctx.opcode),

                    ctx.opcode);

            exit(1);

        }

    }

    if (tb->cflags & CF_LAST_IO)

        gen_io_end();

    if (ctx.exception == POWERPC_EXCP_NONE) {

        gen_goto_tb(&ctx, 0, ctx.nip);

    } else if (ctx.exception != POWERPC_EXCP_BRANCH) {

        if (unlikely(cs->singlestep_enabled)) {

            gen_debug_exception(ctxp);

        }

        /* Generate the return instruction */

        tcg_gen_exit_tb(0);

    }

    gen_tb_end(tb, num_insns);



    tb->size = ctx.nip - pc_start;

    tb->icount = num_insns;



#if defined(DEBUG_DISAS)

    if (qemu_loglevel_mask(CPU_LOG_TB_IN_ASM)

        && qemu_log_in_addr_range(pc_start)) {

        int flags;

        flags = env->bfd_mach;

        flags |= ctx.le_mode << 16;

        qemu_log("IN: %s\n", lookup_symbol(pc_start));

        log_target_disas(cs, pc_start, ctx.nip - pc_start, flags);

        qemu_log("\n");

    }

#endif

}

static void vbe_update_vgaregs(VGACommonState *s)

{

    int h, shift_control;



    if (!vbe_enabled(s)) {

        /* vbe is turned off -- nothing to do */

        return;

    }



    /* graphic mode + memory map 1 */

    s->gr[VGA_GFX_MISC] = (s->gr[VGA_GFX_MISC] & ~0x0c) | 0x04 |

        VGA_GR06_GRAPHICS_MODE;

    s->cr[VGA_CRTC_MODE] |= 3; /* no CGA modes */

    s->cr[VGA_CRTC_OFFSET] = s->vbe_line_offset >> 3;

    /* width */

    s->cr[VGA_CRTC_H_DISP] =

        (s->vbe_regs[VBE_DISPI_INDEX_XRES] >> 3) - 1;

    /* height (only meaningful if < 1024) */

    h = s->vbe_regs[VBE_DISPI_INDEX_YRES] - 1;

    s->cr[VGA_CRTC_V_DISP_END] = h;

    s->cr[VGA_CRTC_OVERFLOW] = (s->cr[VGA_CRTC_OVERFLOW] & ~0x42) |

        ((h >> 7) & 0x02) | ((h >> 3) & 0x40);

    /* line compare to 1023 */

    s->cr[VGA_CRTC_LINE_COMPARE] = 0xff;

    s->cr[VGA_CRTC_OVERFLOW] |= 0x10;

    s->cr[VGA_CRTC_MAX_SCAN] |= 0x40;



    if (s->vbe_regs[VBE_DISPI_INDEX_BPP] == 4) {

        shift_control = 0;

        s->sr[VGA_SEQ_CLOCK_MODE] &= ~8; /* no double line */

    } else {

        shift_control = 2;

        /* set chain 4 mode */

        s->sr[VGA_SEQ_MEMORY_MODE] |= VGA_SR04_CHN_4M;

        /* activate all planes */

        s->sr[VGA_SEQ_PLANE_WRITE] |= VGA_SR02_ALL_PLANES;

    }

    s->gr[VGA_GFX_MODE] = (s->gr[VGA_GFX_MODE] & ~0x60) |

        (shift_control << 5);

    s->cr[VGA_CRTC_MAX_SCAN] &= ~0x9f; /* no double scan */

}

static void term_insert_char(int ch)

{

    if (term_cmd_buf_index < TERM_CMD_BUF_SIZE) {

        memmove(term_cmd_buf + term_cmd_buf_index + 1,

                term_cmd_buf + term_cmd_buf_index,

                term_cmd_buf_size - term_cmd_buf_index);

        term_cmd_buf[term_cmd_buf_index] = ch;

        term_cmd_buf_size++;

        term_cmd_buf_index++;

    }

}

static void e1000e_pci_realize(PCIDevice *pci_dev, Error **errp)

{

    static const uint16_t e1000e_pmrb_offset = 0x0C8;

    static const uint16_t e1000e_pcie_offset = 0x0E0;

    static const uint16_t e1000e_aer_offset =  0x100;

    static const uint16_t e1000e_dsn_offset =  0x140;

    E1000EState *s = E1000E(pci_dev);

    uint8_t *macaddr;

    int ret;



    trace_e1000e_cb_pci_realize();



    pci_dev->config_write = e1000e_write_config;



    pci_dev->config[PCI_CACHE_LINE_SIZE] = 0x10;

    pci_dev->config[PCI_INTERRUPT_PIN] = 1;



    pci_set_word(pci_dev->config + PCI_SUBSYSTEM_VENDOR_ID, s->subsys_ven);

    pci_set_word(pci_dev->config + PCI_SUBSYSTEM_ID, s->subsys);



    s->subsys_ven_used = s->subsys_ven;

    s->subsys_used = s->subsys;



    /* Define IO/MMIO regions */

    memory_region_init_io(&s->mmio, OBJECT(s), &mmio_ops, s,

                          "e1000e-mmio", E1000E_MMIO_SIZE);

    pci_register_bar(pci_dev, E1000E_MMIO_IDX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &s->mmio);



    /*

     * We provide a dummy implementation for the flash BAR

     * for drivers that may theoretically probe for its presence.

     */

    memory_region_init(&s->flash, OBJECT(s),

                       "e1000e-flash", E1000E_FLASH_SIZE);

    pci_register_bar(pci_dev, E1000E_FLASH_IDX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &s->flash);



    memory_region_init_io(&s->io, OBJECT(s), &io_ops, s,

                          "e1000e-io", E1000E_IO_SIZE);

    pci_register_bar(pci_dev, E1000E_IO_IDX,

                     PCI_BASE_ADDRESS_SPACE_IO, &s->io);



    memory_region_init(&s->msix, OBJECT(s), "e1000e-msix",

                       E1000E_MSIX_SIZE);

    pci_register_bar(pci_dev, E1000E_MSIX_IDX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &s->msix);



    /* Create networking backend */

    qemu_macaddr_default_if_unset(&s->conf.macaddr);

    macaddr = s->conf.macaddr.a;



    e1000e_init_msix(s);



    if (pcie_endpoint_cap_v1_init(pci_dev, e1000e_pcie_offset) < 0) {

        hw_error("Failed to initialize PCIe capability");

    }



    ret = msi_init(PCI_DEVICE(s), 0xD0, 1, true, false, NULL);

    if (ret) {

        trace_e1000e_msi_init_fail(ret);

    }



    if (e1000e_add_pm_capability(pci_dev, e1000e_pmrb_offset,

                                  PCI_PM_CAP_DSI) < 0) {

        hw_error("Failed to initialize PM capability");

    }



    if (pcie_aer_init(pci_dev, e1000e_aer_offset, PCI_ERR_SIZEOF) < 0) {

        hw_error("Failed to initialize AER capability");

    }



    pcie_dev_ser_num_init(pci_dev, e1000e_dsn_offset,

                          e1000e_gen_dsn(macaddr));



    e1000e_init_net_peer(s, pci_dev, macaddr);



    /* Initialize core */

    e1000e_core_realize(s);



    e1000e_core_pci_realize(&s->core,

                            e1000e_eeprom_template,

                            sizeof(e1000e_eeprom_template),

                            macaddr);

}

int avpriv_exif_decode_ifd(void *logctx, GetByteContext *gbytes, int le,

                           int depth, AVDictionary **metadata)

{

    int i, ret;

    int entries;



    entries = ff_tget_short(gbytes, le);



    if (bytestream2_get_bytes_left(gbytes) < entries * 12) {

        return AVERROR_INVALIDDATA;

    }



    for (i = 0; i < entries; i++) {

        if ((ret = exif_decode_tag(logctx, gbytes, le, depth, metadata)) < 0) {

            return ret;

        }

    }



    // return next IDF offset or 0x000000000 or a value < 0 for failure

    return ff_tget_long(gbytes, le);

}

