static inline void RENAME(rgb32tobgr15)(const uint8_t *src, uint8_t *dst, long src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

#if COMPILE_TEMPLATE_MMX

    const uint8_t *mm_end;

#endif

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_15mask),"m"(green_15mask));

    mm_end = end - 15;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         4%1, %%mm3    \n\t"

            "punpckldq    8%1, %%mm0    \n\t"

            "punpckldq   12%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psllq         $7, %%mm0    \n\t"

            "psllq         $7, %%mm3    \n\t"

            "pand       %%mm7, %%mm0    \n\t"

            "pand       %%mm7, %%mm3    \n\t"

            "psrlq         $6, %%mm1    \n\t"

            "psrlq         $6, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq        $19, %%mm2    \n\t"

            "psrlq        $19, %%mm5    \n\t"

            "pand          %2, %%mm2    \n\t"

            "pand          %2, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

        d += 4;

        s += 16;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

#endif

    while (s < end) {

        register int rgb = *(const uint32_t*)s; s += 4;

        *d++ = ((rgb&0xF8)<<7) + ((rgb&0xF800)>>6) + ((rgb&0xF80000)>>19);

    }

}

static inline void tcg_out_ld(TCGContext *s, TCGType type, TCGReg ret,

                              TCGReg arg1, intptr_t arg2)

{

    int opi, opx;



    assert(TCG_TARGET_REG_BITS == 64 || type == TCG_TYPE_I32);

    if (type == TCG_TYPE_I32) {

        opi = LWZ, opx = LWZX;

    } else {

        opi = LD, opx = LDX;

    }

    tcg_out_mem_long(s, opi, opx, ret, arg1, arg2);

}

void decode_mb_mode(VP8Context *s, VP8Macroblock *mb, int mb_x, int mb_y,

                    uint8_t *segment, uint8_t *ref, int layout, int is_vp7)

{

    VP56RangeCoder *c = &s->c;

    static const char *vp7_feature_name[] = { "q-index",

                                              "lf-delta",

                                              "partial-golden-update",

                                              "blit-pitch" };

    if (is_vp7) {

        int i;

        *segment = 0;

        for (i = 0; i < 4; i++) {

            if (s->feature_enabled[i]) {

                if (vp56_rac_get_prob_branchy(c, s->feature_present_prob[i])) {

                      int index = vp8_rac_get_tree(c, vp7_feature_index_tree,

                                                   s->feature_index_prob[i]);

                      av_log(s->avctx, AV_LOG_WARNING,

                             "Feature %s present in macroblock (value 0x%x)\n",

                             vp7_feature_name[i], s->feature_value[i][index]);

                }

           }

        }

    } else if (s->segmentation.update_map) {

        int bit  = vp56_rac_get_prob(c, s->prob->segmentid[0]);

        *segment = vp56_rac_get_prob(c, s->prob->segmentid[1+bit]) + 2*bit;

    } else if (s->segmentation.enabled)

        *segment = ref ? *ref : *segment;

    mb->segment = *segment;



    mb->skip = s->mbskip_enabled ? vp56_rac_get_prob(c, s->prob->mbskip) : 0;



    if (s->keyframe) {

        mb->mode = vp8_rac_get_tree(c, vp8_pred16x16_tree_intra,

                                    vp8_pred16x16_prob_intra);



        if (mb->mode == MODE_I4x4) {

            decode_intra4x4_modes(s, c, mb, mb_x, 1, layout);

        } else {

            const uint32_t modes = (is_vp7 ? vp7_pred4x4_mode

                                           : vp8_pred4x4_mode)[mb->mode] * 0x01010101u;

            if (s->mb_layout)

                AV_WN32A(mb->intra4x4_pred_mode_top, modes);

            else

                AV_WN32A(s->intra4x4_pred_mode_top + 4 * mb_x, modes);

            AV_WN32A(s->intra4x4_pred_mode_left, modes);

        }



        mb->chroma_pred_mode = vp8_rac_get_tree(c, vp8_pred8x8c_tree,

                                                vp8_pred8x8c_prob_intra);

        mb->ref_frame        = VP56_FRAME_CURRENT;

    } else if (vp56_rac_get_prob_branchy(c, s->prob->intra)) {

        // inter MB, 16.2

        if (vp56_rac_get_prob_branchy(c, s->prob->last))

            mb->ref_frame =

                (!is_vp7 && vp56_rac_get_prob(c, s->prob->golden)) ? VP56_FRAME_GOLDEN2 /* altref */

                                                                   : VP56_FRAME_GOLDEN;

        else

            mb->ref_frame = VP56_FRAME_PREVIOUS;

        s->ref_count[mb->ref_frame - 1]++;



        // motion vectors, 16.3

        if (is_vp7)

            vp7_decode_mvs(s, mb, mb_x, mb_y, layout);

        else

            vp8_decode_mvs(s, mb, mb_x, mb_y, layout);

    } else {

        // intra MB, 16.1

        mb->mode = vp8_rac_get_tree(c, vp8_pred16x16_tree_inter, s->prob->pred16x16);



        if (mb->mode == MODE_I4x4)

            decode_intra4x4_modes(s, c, mb, mb_x, 0, layout);



        mb->chroma_pred_mode = vp8_rac_get_tree(c, vp8_pred8x8c_tree,

                                                s->prob->pred8x8c);

        mb->ref_frame        = VP56_FRAME_CURRENT;

        mb->partitioning     = VP8_SPLITMVMODE_NONE;

        AV_ZERO32(&mb->bmv[0]);

    }

}

static void gen_branch(DisasContext *ctx, int insn_bytes)

{

    if (ctx->hflags & MIPS_HFLAG_BMASK) {

        int proc_hflags = ctx->hflags & MIPS_HFLAG_BMASK;

        /* Branches completion */

        ctx->hflags &= ~MIPS_HFLAG_BMASK;

        ctx->bstate = BS_BRANCH;

        save_cpu_state(ctx, 0);

        /* FIXME: Need to clear can_do_io.  */

        switch (proc_hflags & MIPS_HFLAG_BMASK_BASE) {

        case MIPS_HFLAG_FBNSLOT:

            MIPS_DEBUG("forbidden slot");

            gen_goto_tb(ctx, 0, ctx->pc + insn_bytes);

            break;

        case MIPS_HFLAG_B:

            /* unconditional branch */

            MIPS_DEBUG("unconditional branch");

            if (proc_hflags & MIPS_HFLAG_BX) {

                tcg_gen_xori_i32(hflags, hflags, MIPS_HFLAG_M16);

            }

            gen_goto_tb(ctx, 0, ctx->btarget);

            break;

        case MIPS_HFLAG_BL:

            /* blikely taken case */

            MIPS_DEBUG("blikely branch taken");

            gen_goto_tb(ctx, 0, ctx->btarget);

            break;

        case MIPS_HFLAG_BC:

            /* Conditional branch */

            MIPS_DEBUG("conditional branch");

            {

                int l1 = gen_new_label();



                tcg_gen_brcondi_tl(TCG_COND_NE, bcond, 0, l1);

                gen_goto_tb(ctx, 1, ctx->pc + insn_bytes);

                gen_set_label(l1);

                gen_goto_tb(ctx, 0, ctx->btarget);

            }

            break;

        case MIPS_HFLAG_BR:

            /* unconditional branch to register */

            MIPS_DEBUG("branch to register");

            if (ctx->insn_flags & (ASE_MIPS16 | ASE_MICROMIPS)) {

                TCGv t0 = tcg_temp_new();

                TCGv_i32 t1 = tcg_temp_new_i32();



                tcg_gen_andi_tl(t0, btarget, 0x1);

                tcg_gen_trunc_tl_i32(t1, t0);

                tcg_temp_free(t0);

                tcg_gen_andi_i32(hflags, hflags, ~(uint32_t)MIPS_HFLAG_M16);

                tcg_gen_shli_i32(t1, t1, MIPS_HFLAG_M16_SHIFT);

                tcg_gen_or_i32(hflags, hflags, t1);

                tcg_temp_free_i32(t1);



                tcg_gen_andi_tl(cpu_PC, btarget, ~(target_ulong)0x1);

            } else {

                tcg_gen_mov_tl(cpu_PC, btarget);

            }

            if (ctx->singlestep_enabled) {

                save_cpu_state(ctx, 0);

                gen_helper_0e0i(raise_exception, EXCP_DEBUG);

            }

            tcg_gen_exit_tb(0);

            break;

        default:

            MIPS_DEBUG("unknown branch");

            break;

        }

    }

}

static uint64_t get_cluster_offset(BlockDriverState *bs,
                                   uint64_t offset, int *num)
{
    BDRVQcowState *s = bs->opaque;
    int l1_index, l2_index;
    uint64_t l2_offset, *l2_table, cluster_offset;
    int l1_bits, c;
    int index_in_cluster, nb_available, nb_needed, nb_clusters;
    index_in_cluster = (offset >> 9) & (s->cluster_sectors - 1);
    nb_needed = *num + index_in_cluster;
    l1_bits = s->l2_bits + s->cluster_bits;
    /* compute how many bytes there are between the offset and
     * the end of the l1 entry
     */
    nb_available = (1 << l1_bits) - (offset & ((1 << l1_bits) - 1));
    /* compute the number of available sectors */
    nb_available = (nb_available >> 9) + index_in_cluster;
    cluster_offset = 0;
    /* seek the the l2 offset in the l1 table */
    l1_index = offset >> l1_bits;
    if (l1_index >= s->l1_size)
        goto out;
    l2_offset = s->l1_table[l1_index];
    /* seek the l2 table of the given l2 offset */
    if (!l2_offset)
        goto out;
    /* load the l2 table in memory */
    l2_offset &= ~QCOW_OFLAG_COPIED;
    l2_table = l2_load(bs, l2_offset);
    if (l2_table == NULL)
        return 0;
    /* find the cluster offset for the given disk offset */
    l2_index = (offset >> s->cluster_bits) & (s->l2_size - 1);
    cluster_offset = be64_to_cpu(l2_table[l2_index]);
    nb_clusters = size_to_clusters(s, nb_needed << 9);
    if (!cluster_offset) {
        /* how many empty clusters ? */
        c = count_contiguous_free_clusters(nb_clusters, &l2_table[l2_index]);
    } else {
        /* how many allocated clusters ? */
        c = count_contiguous_clusters(nb_clusters, s->cluster_size,
                &l2_table[l2_index], 0, QCOW_OFLAG_COPIED);
   nb_available = (c * s->cluster_sectors);
out:
    if (nb_available > nb_needed)
        nb_available = nb_needed;
    *num = nb_available - index_in_cluster;
    return cluster_offset & ~QCOW_OFLAG_COPIED;

static int colo_packet_compare_udp(Packet *spkt, Packet *ppkt)

{

    int ret;

    int network_header_length = ppkt->ip->ip_hl * 4;



    trace_colo_compare_main("compare udp");



    /*

     * Because of ppkt and spkt are both in the same connection,

     * The ppkt's src ip, dst ip, src port, dst port, ip_proto all are

     * same with spkt. In addition, IP header's Identification is a random

     * field, we can handle it in IP fragmentation function later.

     * COLO just concern the response net packet payload from primary guest

     * and secondary guest are same or not, So we ignored all IP header include

     * other field like TOS,TTL,IP Checksum. we only need to compare

     * the ip payload here.

     */

    ret = colo_packet_compare_common(ppkt, spkt,

                                     network_header_length + ETH_HLEN);



    if (ret) {

        trace_colo_compare_udp_miscompare("primary pkt size", ppkt->size);

        trace_colo_compare_udp_miscompare("Secondary pkt size", spkt->size);

        if (trace_event_get_state(TRACE_COLO_COMPARE_MISCOMPARE)) {

            qemu_hexdump((char *)ppkt->data, stderr, "colo-compare pri pkt",

                         ppkt->size);

            qemu_hexdump((char *)spkt->data, stderr, "colo-compare sec pkt",

                         spkt->size);

        }

    }



    return ret;

}

static int vc1_decode_p_mb(VC1Context *v, DCTELEM block[6][64])

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i, j;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int cbp; /* cbp decoding stuff */

    int mqdiff, mquant; /* MB quantization */

    int ttmb = v->ttfrm; /* MB Transform type */

    int status;



    static const int size_table[6] = { 0, 2, 3, 4, 5, 8 },

      offset_table[6] = { 0, 1, 3, 7, 15, 31 };

    int mb_has_coeffs = 1; /* last_flag */

    int dmv_x, dmv_y; /* Differential MV components */

    int index, index1; /* LUT indices */

    int val, sign; /* temp values */

    int first_block = 1;

    int dst_idx, off;

    int skipped, fourmv;



    mquant = v->pq; /* Loosy initialization */



    if (v->mv_type_is_raw)

        fourmv = get_bits1(gb);

    else

        fourmv = v->mv_type_mb_plane[mb_pos];

    if (v->skip_is_raw)

        skipped = get_bits1(gb);

    else

        skipped = v->s.mbskip_table[mb_pos];



    s->dsp.clear_blocks(s->block[0]);



    if (!fourmv) /* 1MV mode */

    {

        if (!skipped)

        {

            GET_MVDATA(dmv_x, dmv_y);



            s->current_picture.mb_type[mb_pos] = s->mb_intra ? MB_TYPE_INTRA : MB_TYPE_16x16;

            vc1_pred_mv(s, 0, dmv_x, dmv_y, 1, v->range_x, v->range_y, v->mb_type[0]);



            /* FIXME Set DC val for inter block ? */

            if (s->mb_intra && !mb_has_coeffs)

            {

                GET_MQUANT();

                s->ac_pred = get_bits(gb, 1);

                cbp = 0;

            }

            else if (mb_has_coeffs)

            {

                if (s->mb_intra) s->ac_pred = get_bits(gb, 1);

                cbp = get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

                GET_MQUANT();

            }

            else

            {

                mquant = v->pq;

                cbp = 0;

            }

            s->current_picture.qscale_table[mb_pos] = mquant;



            if (!v->ttmbf && !s->mb_intra && mb_has_coeffs)

                ttmb = get_vlc2(gb, vc1_ttmb_vlc[v->tt_index].table,

                                VC1_TTMB_VLC_BITS, 2);

            if(!s->mb_intra) vc1_mc_1mv(v);

            dst_idx = 0;

            for (i=0; i<6; i++)

            {

                s->dc_val[0][s->block_index[i]] = 0;

                dst_idx += i >> 2;

                val = ((cbp >> (5 - i)) & 1);

                off = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

                v->mb_type[0][s->block_index[i]] = s->mb_intra;

                if(s->mb_intra) {

                    /* check if prediction blocks A and C are available */

                    v->a_avail = v->c_avail = 0;

                    if(i == 2 || i == 3 || s->mb_y)

                        v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

                    if(i == 1 || i == 3 || s->mb_x)

                        v->c_avail = v->mb_type[0][s->block_index[i] - 1];



                    vc1_decode_intra_block(v, block[i], i, val, mquant, (i&4)?v->codingset2:v->codingset);

                    vc1_inv_trans(block[i], 8, 8);

                    for(j = 0; j < 64; j++) block[i][j] += 128;

                    s->dsp.put_pixels_clamped(block[i], s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2));

                    /* TODO: proper loop filtering */

                    if(v->pq >= 9 && v->overlap) {

                        if(v->a_avail)

                            s->dsp.h263_v_loop_filter(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2), s->y_dc_scale);

                        if(v->c_avail)

                            s->dsp.h263_h_loop_filter(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2), s->y_dc_scale);

                    }

                } else if(val) {

                    vc1_decode_p_block(v, block[i], i, mquant, ttmb, first_block);

                    if(!v->ttmbf && ttmb < 8) ttmb = -1;

                    first_block = 0;

                    s->dsp.add_pixels_clamped(block[i], s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize);

                }

            }

        }

        else //Skipped

        {

            s->mb_intra = 0;

            for(i = 0; i < 6; i++) v->mb_type[0][s->block_index[i]] = 0;

            s->current_picture.mb_type[mb_pos] = MB_TYPE_SKIP;

            s->current_picture.qscale_table[mb_pos] = 0;

            vc1_pred_mv(s, 0, 0, 0, 1, v->range_x, v->range_y, v->mb_type[0]);

            vc1_mc_1mv(v);

            return 0;

        }

    } //1MV mode

    else //4MV mode

    {

        if (!skipped /* unskipped MB */)

        {

            int intra_count = 0, coded_inter = 0;

            int is_intra[6], is_coded[6];

            /* Get CBPCY */

            cbp = get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

            for (i=0; i<6; i++)

            {

                val = ((cbp >> (5 - i)) & 1);

                s->dc_val[0][s->block_index[i]] = 0;

                s->mb_intra = 0;

                if(i < 4) {

                    dmv_x = dmv_y = 0;

                    s->mb_intra = 0;

                    mb_has_coeffs = 0;

                    if(val) {

                        GET_MVDATA(dmv_x, dmv_y);

                    }

                    vc1_pred_mv(s, i, dmv_x, dmv_y, 0, v->range_x, v->range_y, v->mb_type[0]);

                    if(!s->mb_intra) vc1_mc_4mv_luma(v, i);

                    intra_count += s->mb_intra;

                    is_intra[i] = s->mb_intra;

                    is_coded[i] = mb_has_coeffs;

                }

                if(i&4){

                    is_intra[i] = (intra_count >= 3);

                    is_coded[i] = val;

                }

                if(i == 4) vc1_mc_4mv_chroma(v);

                v->mb_type[0][s->block_index[i]] = is_intra[i];

                if(!coded_inter) coded_inter = !is_intra[i] & is_coded[i];

            }

            dst_idx = 0;

            GET_MQUANT();

            s->current_picture.qscale_table[mb_pos] = mquant;

            /* test if block is intra and has pred */

            {

                int intrapred = 0;

                for(i=0; i<6; i++)

                    if(is_intra[i]) {

                        if(v->mb_type[0][s->block_index[i] - s->block_wrap[i]] || v->mb_type[0][s->block_index[i] - 1]) {

                            intrapred = 1;

                            break;

                        }

                    }

                if(intrapred)s->ac_pred = get_bits(gb, 1);

                else s->ac_pred = 0;

            }

            if (!v->ttmbf && coded_inter)

                ttmb = get_vlc2(gb, vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 12);

            for (i=0; i<6; i++)

            {

                dst_idx += i >> 2;

                off = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

                s->mb_intra = is_intra[i];

                if (is_intra[i]) {

                    /* check if prediction blocks A and C are available */

                    v->a_avail = v->c_avail = 0;

                    if(i == 2 || i == 3 || s->mb_y)

                        v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

                    if(i == 1 || i == 3 || s->mb_x)

                        v->c_avail = v->mb_type[0][s->block_index[i] - 1];



                    vc1_decode_intra_block(v, s->block[i], i, is_coded[i], mquant, (i&4)?v->codingset2:v->codingset);

                    vc1_inv_trans(block[i], 8, 8);

                    for(j = 0; j < 64; j++) block[i][j] += 128;

                    s->dsp.put_pixels_clamped(s->block[i], s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize);

                    /* TODO: proper loop filtering */

                    if(v->pq >= 9 && v->overlap) {

                        if(v->a_avail)

                            s->dsp.h263_v_loop_filter(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2), s->y_dc_scale);

                        if(v->c_avail)

                            s->dsp.h263_h_loop_filter(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2), s->y_dc_scale);

                    }

                } else if(is_coded[i]) {

                    status = vc1_decode_p_block(v, s->block[i], i, mquant, ttmb, first_block);

                    if(!v->ttmbf && ttmb < 8) ttmb = -1;

                    first_block = 0;

                    s->dsp.add_pixels_clamped(s->block[i], s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize);

                }

            }

            return status;

        }

        else //Skipped MB

        {

            s->mb_intra = 0;

            for (i=0; i<6; i++) v->mb_type[0][s->block_index[i]] = 0;

            for (i=0; i<4; i++)

            {

                vc1_pred_mv(s, i, 0, 0, 0, v->range_x, v->range_y, v->mb_type[0]);

                vc1_mc_4mv_luma(v, i);

            }

            vc1_mc_4mv_chroma(v);

            s->current_picture.qscale_table[mb_pos] = 0;

            return 0;

        }

    }



    /* Should never happen */

    return -1;

}

void qmp_blockdev_snapshot_internal_sync(const char *device,

                                         const char *name,

                                         Error **errp)

{

    BlockdevSnapshotInternal snapshot = {

        .device = (char *) device,

        .name = (char *) name

    };

    TransactionAction action = {

        .type = TRANSACTION_ACTION_KIND_BLOCKDEV_SNAPSHOT_INTERNAL_SYNC,

        .u.blockdev_snapshot_internal_sync = &snapshot,

    };

    blockdev_do_action(&action, errp);

}

static void phys_sections_free(PhysPageMap *map)

{

    while (map->sections_nb > 0) {

        MemoryRegionSection *section = &map->sections[--map->sections_nb];

        phys_section_destroy(section->mr);

    }

    g_free(map->sections);

    g_free(map->nodes);

    g_free(map);

}

print_with_operands (const struct cris_opcode *opcodep,

		     unsigned int insn,

		     unsigned char *buffer,

		     bfd_vma addr,

		     disassemble_info *info,

		     /* If a prefix insn was before this insn (and is supposed

			to be output as an address), here is a description of

			it.  */

		     const struct cris_opcode *prefix_opcodep,

		     unsigned int prefix_insn,

		     unsigned char *prefix_buffer,

		     bfd_boolean with_reg_prefix)

{

  /* Get a buffer of somewhat reasonable size where we store

     intermediate parts of the insn.  */

  char temp[sizeof (".d [$r13=$r12-2147483648],$r10") * 2];

  char *tp = temp;

  static const char mode_char[] = "bwd?";

  const char *s;

  const char *cs;

  struct cris_disasm_data *disdata

    = (struct cris_disasm_data *) info->private_data;



  /* Print out the name first thing we do.  */

  (*info->fprintf_func) (info->stream, "%s", opcodep->name);



  cs = opcodep->args;

  s = cs;



  /* Ignore any prefix indicator.  */

  if (*s == 'p')

    s++;



  if (*s == 'm' || *s == 'M' || *s == 'z')

    {

      *tp++ = '.';



      /* Get the size-letter.  */

      *tp++ = *s == 'M'

	? (insn & 0x8000 ? 'd'

	   : insn & 0x4000 ? 'w' : 'b')

	: mode_char[(insn >> 4) & (*s == 'z' ? 1 : 3)];



      /* Ignore the size and the space character that follows.  */

      s += 2;

    }



  /* Add a space if this isn't a long-branch, because for those will add

     the condition part of the name later.  */

  if (opcodep->match != (BRANCH_PC_LOW + BRANCH_INCR_HIGH * 256))

    *tp++ = ' ';



  /* Fill in the insn-type if deducible from the name (and there's no

     better way).  */

  if (opcodep->name[0] == 'j')

    {

      if (CONST_STRNEQ (opcodep->name, "jsr"))

	/* It's "jsr" or "jsrc".  */

	info->insn_type = dis_jsr;

      else

	/* Any other jump-type insn is considered a branch.  */

	info->insn_type = dis_branch;

    }



  /* We might know some more fields right now.  */

  info->branch_delay_insns = opcodep->delayed;



  /* Handle operands.  */

  for (; *s; s++)

    {

    switch (*s)

      {

      case 'T':

	tp = format_sup_reg ((insn >> 12) & 15, tp, with_reg_prefix);

	break;



      case 'A':

	if (with_reg_prefix)

	  *tp++ = REGISTER_PREFIX_CHAR;

	*tp++ = 'a';

	*tp++ = 'c';

	*tp++ = 'r';

	break;



      case '[':

      case ']':

      case ',':

	*tp++ = *s;

	break;



      case '!':

	/* Ignore at this point; used at earlier stages to avoid

	   recognition if there's a prefix at something that in other

	   ways looks like a "pop".  */

	break;



      case 'd':

	/* Ignore.  This is an optional ".d " on the large one of

	   relaxable insns.  */

	break;



      case 'B':

	/* This was the prefix that made this a "push".  We've already

	   handled it by recognizing it, so signal that the prefix is

	   handled by setting it to NULL.  */

	prefix_opcodep = NULL;

	break;



      case 'D':

      case 'r':

	tp = format_reg (disdata, insn & 15, tp, with_reg_prefix);

	break;



      case 'R':

	tp = format_reg (disdata, (insn >> 12) & 15, tp, with_reg_prefix);

	break;



      case 'n':

	{

	  /* Like N but pc-relative to the start of the insn.  */

	  unsigned long number

	    = (buffer[2] + buffer[3] * 256 + buffer[4] * 65536

	       + buffer[5] * 0x1000000 + addr);



	  /* Finish off and output previous formatted bytes.  */

	  *tp = 0;

	  if (temp[0])

	    (*info->fprintf_func) (info->stream, "%s", temp);

	  tp = temp;



	  (*info->print_address_func) ((bfd_vma) number, info);

	}

	break;



      case 'u':

	{

	  /* Like n but the offset is bits <3:0> in the instruction.  */

	  unsigned long number = (buffer[0] & 0xf) * 2 + addr;



	  /* Finish off and output previous formatted bytes.  */

	  *tp = 0;

	  if (temp[0])

	    (*info->fprintf_func) (info->stream, "%s", temp);

	  tp = temp;



	  (*info->print_address_func) ((bfd_vma) number, info);

	}

	break;



      case 'N':

      case 'y':

      case 'Y':

      case 'S':

      case 's':

	/* Any "normal" memory operand.  */

	if ((insn & 0x400) && (insn & 15) == 15 && prefix_opcodep == NULL)

	  {

	    /* We're looking at [pc+], i.e. we need to output an immediate

	       number, where the size can depend on different things.  */

	    long number;

	    int signedp

	      = ((*cs == 'z' && (insn & 0x20))

		 || opcodep->match == BDAP_QUICK_OPCODE);

	    int nbytes;



	    if (opcodep->imm_oprnd_size == SIZE_FIX_32)

	      nbytes = 4;

	    else if (opcodep->imm_oprnd_size == SIZE_SPEC_REG)

	      {

		const struct cris_spec_reg *sregp

		  = spec_reg_info ((insn >> 12) & 15, disdata->distype);



		/* A NULL return should have been as a non-match earlier,

		   so catch it as an internal error in the error-case

		   below.  */

		if (sregp == NULL)

		  /* Whatever non-valid size.  */

		  nbytes = 42;

		else

		  /* PC is always incremented by a multiple of two.

		     For CRISv32, immediates are always 4 bytes for

		     special registers.  */

		  nbytes = disdata->distype == cris_dis_v32

		    ? 4 : (sregp->reg_size + 1) & ~1;

	      }

	    else

	      {

		int mode_size = 1 << ((insn >> 4) & (*cs == 'z' ? 1 : 3));



		if (mode_size == 1)

		  nbytes = 2;

		else

		  nbytes = mode_size;

	      }



	    switch (nbytes)

	      {

	      case 1:

		number = buffer[2];

		if (signedp && number > 127)

		  number -= 256;

		break;



	      case 2:

		number = buffer[2] + buffer[3] * 256;

		if (signedp && number > 32767)

		  number -= 65536;

		break;



	      case 4:

		number

		  = buffer[2] + buffer[3] * 256 + buffer[4] * 65536

		  + buffer[5] * 0x1000000;

		break;



	      default:

		strcpy (tp, "bug");

		tp += 3;

		number = 42;

	      }



	    if ((*cs == 'z' && (insn & 0x20))

		|| (opcodep->match == BDAP_QUICK_OPCODE

		    && (nbytes <= 2 || buffer[1 + nbytes] == 0)))

	      tp = format_dec (number, tp, signedp);

	    else

	      {

		unsigned int highbyte = (number >> 24) & 0xff;



		/* Either output this as an address or as a number.  If it's

		   a dword with the same high-byte as the address of the

		   insn, assume it's an address, and also if it's a non-zero

		   non-0xff high-byte.  If this is a jsr or a jump, then

		   it's definitely an address.  */

		if (nbytes == 4

		    && (highbyte == ((addr >> 24) & 0xff)

			|| (highbyte != 0 && highbyte != 0xff)

			|| info->insn_type == dis_branch

			|| info->insn_type == dis_jsr))

		  {

		    /* Finish off and output previous formatted bytes.  */

		    *tp = 0;

		    tp = temp;

		    if (temp[0])

		      (*info->fprintf_func) (info->stream, "%s", temp);



		    (*info->print_address_func) ((bfd_vma) number, info);



		    info->target = number;

		  }

		else

		  tp = format_hex (number, tp, disdata);

	      }

	  }

	else

	  {

	    /* Not an immediate number.  Then this is a (possibly

	       prefixed) memory operand.  */

	    if (info->insn_type != dis_nonbranch)

	      {

		int mode_size

		  = 1 << ((insn >> 4)

			  & (opcodep->args[0] == 'z' ? 1 : 3));

		int size;

		info->insn_type = dis_dref;

		info->flags |= CRIS_DIS_FLAG_MEMREF;



		if (opcodep->imm_oprnd_size == SIZE_FIX_32)

		  size = 4;

		else if (opcodep->imm_oprnd_size == SIZE_SPEC_REG)

		  {

		    const struct cris_spec_reg *sregp

		      = spec_reg_info ((insn >> 12) & 15, disdata->distype);



		    /* FIXME: Improve error handling; should have been caught

		       earlier.  */

		    if (sregp == NULL)

		      size = 4;

		    else

		      size = sregp->reg_size;

		  }

		else

		  size = mode_size;



		info->data_size = size;

	      }



	    *tp++ = '[';



	    if (prefix_opcodep

		/* We don't match dip with a postincremented field

		   as a side-effect address mode.  */

		&& ((insn & 0x400) == 0

		    || prefix_opcodep->match != DIP_OPCODE))

	      {

		if (insn & 0x400)

		  {

		    tp = format_reg (disdata, insn & 15, tp, with_reg_prefix);

		    *tp++ = '=';

		  }





		/* We mainly ignore the prefix format string when the

		   address-mode syntax is output.  */

		switch (prefix_opcodep->match)

		  {

		  case DIP_OPCODE:

		    /* It's [r], [r+] or [pc+].  */

		    if ((prefix_insn & 0x400) && (prefix_insn & 15) == 15)

		      {

			/* It's [pc+].  This cannot possibly be anything

			   but an address.  */

			unsigned long number

			  = prefix_buffer[2] + prefix_buffer[3] * 256

			  + prefix_buffer[4] * 65536

			  + prefix_buffer[5] * 0x1000000;



			info->target = (bfd_vma) number;



			/* Finish off and output previous formatted

			   data.  */

			*tp = 0;

			tp = temp;

			if (temp[0])

			  (*info->fprintf_func) (info->stream, "%s", temp);



			(*info->print_address_func) ((bfd_vma) number, info);

		      }

		    else

		      {

			/* For a memref in an address, we use target2.

			   In this case, target is zero.  */

			info->flags

			  |= (CRIS_DIS_FLAG_MEM_TARGET2_IS_REG

			      | CRIS_DIS_FLAG_MEM_TARGET2_MEM);



			info->target2 = prefix_insn & 15;



			*tp++ = '[';

			tp = format_reg (disdata, prefix_insn & 15, tp,

					 with_reg_prefix);

			if (prefix_insn & 0x400)

			  *tp++ = '+';

			*tp++ = ']';

		      }

		    break;



		  case BDAP_QUICK_OPCODE:

		    {

		      int number;



		      number = prefix_buffer[0];

		      if (number > 127)

			number -= 256;



		      /* Output "reg+num" or, if num < 0, "reg-num".  */

		      tp = format_reg (disdata, (prefix_insn >> 12) & 15, tp,

				       with_reg_prefix);

		      if (number >= 0)

			*tp++ = '+';

		      tp = format_dec (number, tp, 1);



		      info->flags |= CRIS_DIS_FLAG_MEM_TARGET_IS_REG;

		      info->target = (prefix_insn >> 12) & 15;

		      info->target2 = (bfd_vma) number;

		      break;

		    }



		  case BIAP_OPCODE:

		    /* Output "r+R.m".  */

		    tp = format_reg (disdata, prefix_insn & 15, tp,

				     with_reg_prefix);

		    *tp++ = '+';

		    tp = format_reg (disdata, (prefix_insn >> 12) & 15, tp,

				     with_reg_prefix);

		    *tp++ = '.';

		    *tp++ = mode_char[(prefix_insn >> 4) & 3];



		    info->flags

		      |= (CRIS_DIS_FLAG_MEM_TARGET2_IS_REG

			  | CRIS_DIS_FLAG_MEM_TARGET_IS_REG



			  | ((prefix_insn & 0x8000)

			     ? CRIS_DIS_FLAG_MEM_TARGET2_MULT4

			     : ((prefix_insn & 0x8000)

				? CRIS_DIS_FLAG_MEM_TARGET2_MULT2 : 0)));



		    /* Is it the casejump?  It's a "adds.w [pc+r%d.w],pc".  */

		    if (insn == 0xf83f && (prefix_insn & ~0xf000) == 0x55f)

		      /* Then start interpreting data as offsets.  */

		      case_offset_counter = no_of_case_offsets;

		    break;



		  case BDAP_INDIR_OPCODE:

		    /* Output "r+s.m", or, if "s" is [pc+], "r+s" or

		       "r-s".  */

		    tp = format_reg (disdata, (prefix_insn >> 12) & 15, tp,

				     with_reg_prefix);



		    if ((prefix_insn & 0x400) && (prefix_insn & 15) == 15)

		      {

			long number;

			unsigned int nbytes;



			/* It's a value.  Get its size.  */

			int mode_size = 1 << ((prefix_insn >> 4) & 3);



			if (mode_size == 1)

			  nbytes = 2;

			else

			  nbytes = mode_size;



			switch (nbytes)

			  {

			  case 1:

			    number = prefix_buffer[2];

			    if (number > 127)

			      number -= 256;

			    break;



			  case 2:

			    number = prefix_buffer[2] + prefix_buffer[3] * 256;

			    if (number > 32767)

			      number -= 65536;

			    break;



			  case 4:

			    number

			      = prefix_buffer[2] + prefix_buffer[3] * 256

			      + prefix_buffer[4] * 65536

			      + prefix_buffer[5] * 0x1000000;

			    break;



			  default:

			    strcpy (tp, "bug");

			    tp += 3;

			    number = 42;

			  }



			info->flags |= CRIS_DIS_FLAG_MEM_TARGET_IS_REG;

			info->target2 = (bfd_vma) number;



			/* If the size is dword, then assume it's an

			   address.  */

			if (nbytes == 4)

			  {

			    /* Finish off and output previous formatted

			       bytes.  */

			    *tp++ = '+';

			    *tp = 0;

			    tp = temp;

			    (*info->fprintf_func) (info->stream, "%s", temp);



			    (*info->print_address_func) ((bfd_vma) number, info);

			  }

			else

			  {

			    if (number >= 0)

			      *tp++ = '+';

			    tp = format_dec (number, tp, 1);

			  }

		      }

		    else

		      {

			/* Output "r+[R].m" or "r+[R+].m".  */

			*tp++ = '+';

			*tp++ = '[';

			tp = format_reg (disdata, prefix_insn & 15, tp,

					 with_reg_prefix);

			if (prefix_insn & 0x400)

			  *tp++ = '+';

			*tp++ = ']';

			*tp++ = '.';

			*tp++ = mode_char[(prefix_insn >> 4) & 3];



			info->flags

			  |= (CRIS_DIS_FLAG_MEM_TARGET2_IS_REG

			      | CRIS_DIS_FLAG_MEM_TARGET2_MEM

			      | CRIS_DIS_FLAG_MEM_TARGET_IS_REG



			      | (((prefix_insn >> 4) == 2)

				 ? 0

				 : (((prefix_insn >> 4) & 3) == 1

				    ? CRIS_DIS_FLAG_MEM_TARGET2_MEM_WORD

				    : CRIS_DIS_FLAG_MEM_TARGET2_MEM_BYTE)));

		      }

		    break;



		  default:

		    (*info->fprintf_func) (info->stream, "?prefix-bug");

		  }



		/* To mark that the prefix is used, reset it.  */

		prefix_opcodep = NULL;

	      }

	    else

	      {

		tp = format_reg (disdata, insn & 15, tp, with_reg_prefix);



		info->flags |= CRIS_DIS_FLAG_MEM_TARGET_IS_REG;

		info->target = insn & 15;



		if (insn & 0x400)

		  *tp++ = '+';

	      }

	    *tp++ = ']';

	  }

	break;



      case 'x':

	tp = format_reg (disdata, (insn >> 12) & 15, tp, with_reg_prefix);

	*tp++ = '.';

	*tp++ = mode_char[(insn >> 4) & 3];

	break;



      case 'I':

	tp = format_dec (insn & 63, tp, 0);

	break;



      case 'b':

	{

	  int where = buffer[2] + buffer[3] * 256;



	  if (where > 32767)

	    where -= 65536;



	  where += addr + ((disdata->distype == cris_dis_v32) ? 0 : 4);



	  if (insn == BA_PC_INCR_OPCODE)

	    info->insn_type = dis_branch;

	  else

	    info->insn_type = dis_condbranch;



	  info->target = (bfd_vma) where;



	  *tp = 0;

	  tp = temp;

	  (*info->fprintf_func) (info->stream, "%s%s ",

				 temp, cris_cc_strings[insn >> 12]);



	  (*info->print_address_func) ((bfd_vma) where, info);

	}

      break;



    case 'c':

      tp = format_dec (insn & 31, tp, 0);

      break;



    case 'C':

      tp = format_dec (insn & 15, tp, 0);

      break;



    case 'o':

      {

	long offset = insn & 0xfe;

	bfd_vma target;



	if (insn & 1)

	  offset |= ~0xff;



	if (opcodep->match == BA_QUICK_OPCODE)

	  info->insn_type = dis_branch;

	else

	  info->insn_type = dis_condbranch;



	target = addr + ((disdata->distype == cris_dis_v32) ? 0 : 2) + offset;

	info->target = target;

	*tp = 0;

	tp = temp;

	(*info->fprintf_func) (info->stream, "%s", temp);

	(*info->print_address_func) (target, info);

      }

      break;



    case 'Q':

    case 'O':

      {

	long number = buffer[0];



	if (number > 127)

	  number = number - 256;



	tp = format_dec (number, tp, 1);

	*tp++ = ',';

	tp = format_reg (disdata, (insn >> 12) & 15, tp, with_reg_prefix);

      }

      break;



    case 'f':

      tp = print_flags (disdata, insn, tp);

      break;



    case 'i':

      tp = format_dec ((insn & 32) ? (insn & 31) | ~31L : insn & 31, tp, 1);

      break;



    case 'P':

      {

	const struct cris_spec_reg *sregp

	  = spec_reg_info ((insn >> 12) & 15, disdata->distype);



	if (sregp->name == NULL)

	  /* Should have been caught as a non-match earlier.  */

	  *tp++ = '?';

	else

	  {

	    if (with_reg_prefix)

	      *tp++ = REGISTER_PREFIX_CHAR;

	    strcpy (tp, sregp->name);

	    tp += strlen (tp);

	  }

      }

      break;



    default:

      strcpy (tp, "???");

      tp += 3;

    }

  }



  *tp = 0;



  if (prefix_opcodep)

    (*info->fprintf_func) (info->stream, " (OOPS unused prefix \"%s: %s\")",

			   prefix_opcodep->name, prefix_opcodep->args);



  (*info->fprintf_func) (info->stream, "%s", temp);



  /* Get info for matching case-tables, if we don't have any active.

     We assume that the last constant seen is used; either in the insn

     itself or in a "move.d const,rN, sub.d rN,rM"-like sequence.  */

  if (TRACE_CASE && case_offset_counter == 0)

    {

      if (CONST_STRNEQ (opcodep->name, "sub"))

	case_offset = last_immediate;



      /* It could also be an "add", if there are negative case-values.  */

      else if (CONST_STRNEQ (opcodep->name, "add"))

	/* The first case is the negated operand to the add.  */

	case_offset = -last_immediate;



      /* A bound insn will tell us the number of cases.  */

      else if (CONST_STRNEQ (opcodep->name, "bound"))

	no_of_case_offsets = last_immediate + 1;



      /* A jump or jsr or branch breaks the chain of insns for a

	 case-table, so assume default first-case again.  */

      else if (info->insn_type == dis_jsr

	       || info->insn_type == dis_branch

	       || info->insn_type == dis_condbranch)

	case_offset = 0;

    }

}

