static void update_error_limit(WavpackFrameContext *ctx)

{

    int i, br[2], sl[2];



    for (i = 0; i <= ctx->stereo_in; i++) {

        ctx->ch[i].bitrate_acc += ctx->ch[i].bitrate_delta;

        br[i]                   = ctx->ch[i].bitrate_acc >> 16;

        sl[i]                   = LEVEL_DECAY(ctx->ch[i].slow_level);

    }

    if (ctx->stereo_in && ctx->hybrid_bitrate) {

        int balance = (sl[1] - sl[0] + br[1] + 1) >> 1;

        if (balance > br[0]) {

            br[1] = br[0] << 1;

            br[0] = 0;

        } else if (-balance > br[0]) {

            br[0] <<= 1;

            br[1]   = 0;

        } else {

            br[1] = br[0] + balance;

            br[0] = br[0] - balance;

        }

    }

    for (i = 0; i <= ctx->stereo_in; i++) {

        if (ctx->hybrid_bitrate) {

            if (sl[i] - br[i] > -0x100)

                ctx->ch[i].error_limit = wp_exp2(sl[i] - br[i] + 0x100);

            else

                ctx->ch[i].error_limit = 0;

        } else {

            ctx->ch[i].error_limit = wp_exp2(br[i]);

        }

    }

}

static int dv_read_timecode(AVFormatContext *s) {

    int ret;

    char timecode[AV_TIMECODE_STR_SIZE];

    int64_t pos = avio_tell(s->pb);



    // Read 3 DIF blocks: Header block and 2 Subcode blocks.

    int partial_frame_size = 3 * 80;

    uint8_t *partial_frame = av_mallocz(sizeof(*partial_frame) *

                                        partial_frame_size);



    RawDVContext *c = s->priv_data;

    ret = avio_read(s->pb, partial_frame, partial_frame_size);

    if (ret < 0)

        goto finish;



    if (ret < partial_frame_size) {

        ret = -1;

        goto finish;

    }



    ret = dv_extract_timecode(c->dv_demux, partial_frame, timecode);

    if (ret)

        av_dict_set(&s->metadata, "timecode", timecode, 0);

    else if (ret < 0)

        av_log(s, AV_LOG_ERROR, "Detected timecode is invalid\n");



finish:

    av_free(partial_frame);

    avio_seek(s->pb, pos, SEEK_SET);

    return ret;

}

static int mov_write_avcc_tag(ByteIOContext *pb, MOVTrack *track)

{

    offset_t pos = url_ftell(pb);



    put_be32(pb, 0);

    put_tag(pb, "avcC");

    if (track->vosLen > 6) {

        /* check for h264 start code */

        if (AV_RB32(track->vosData) == 0x00000001) {

            uint8_t *buf, *end;

            uint32_t sps_size=0, pps_size=0;

            uint8_t *sps=0, *pps=0;



            avc_parse_nal_units(&track->vosData, &track->vosLen);

            buf = track->vosData;

            end = track->vosData + track->vosLen;



            /* look for sps and pps */

            while (buf < end) {

                unsigned int size;

                uint8_t nal_type;

                size = AV_RB32(buf);

                nal_type = buf[4] & 0x1f;

                if (nal_type == 7) { /* SPS */

                    sps = buf + 4;

                    sps_size = size;

                } else if (nal_type == 8) { /* PPS */

                    pps = buf + 4;

                    pps_size = size;

                }

                buf += size + 4;

            }

            assert(sps);

            assert(pps);



            put_byte(pb, 1); /* version */

            put_byte(pb, sps[1]); /* profile */

            put_byte(pb, sps[2]); /* profile compat */

            put_byte(pb, sps[3]); /* level */

            put_byte(pb, 0xff); /* 6 bits reserved (111111) + 2 bits nal size length - 1 (11) */

            put_byte(pb, 0xe1); /* 3 bits reserved (111) + 5 bits number of sps (00001) */



            put_be16(pb, sps_size);

            put_buffer(pb, sps, sps_size);

            put_byte(pb, 1); /* number of pps */

            put_be16(pb, pps_size);

            put_buffer(pb, pps, pps_size);

        } else {

            put_buffer(pb, track->vosData, track->vosLen);

        }

    }

    return updateSize(pb, pos);

}

static void tcg_out_opc(TCGContext *s, int opc, int r, int rm, int x)

{

    int rex;



    if (opc & P_GS) {

        tcg_out8(s, 0x65);

    }

    if (opc & P_DATA16) {

        /* We should never be asking for both 16 and 64-bit operation.  */

        assert((opc & P_REXW) == 0);

        tcg_out8(s, 0x66);

    }

    if (opc & P_ADDR32) {

        tcg_out8(s, 0x67);

    }



    rex = 0;

    rex |= (opc & P_REXW) ? 0x8 : 0x0;  /* REX.W */

    rex |= (r & 8) >> 1;                /* REX.R */

    rex |= (x & 8) >> 2;                /* REX.X */

    rex |= (rm & 8) >> 3;               /* REX.B */



    /* P_REXB_{R,RM} indicates that the given register is the low byte.

       For %[abcd]l we need no REX prefix, but for %{si,di,bp,sp}l we do,

       as otherwise the encoding indicates %[abcd]h.  Note that the values

       that are ORed in merely indicate that the REX byte must be present;

       those bits get discarded in output.  */

    rex |= opc & (r >= 4 ? P_REXB_R : 0);

    rex |= opc & (rm >= 4 ? P_REXB_RM : 0);



    if (rex) {

        tcg_out8(s, (uint8_t)(rex | 0x40));

    }



    if (opc & (P_EXT | P_EXT38)) {

        tcg_out8(s, 0x0f);

        if (opc & P_EXT38) {

            tcg_out8(s, 0x38);

        }

    }



    tcg_out8(s, opc);

}

static void vfio_realize(PCIDevice *pdev, Error **errp)

{

    VFIOPCIDevice *vdev = DO_UPCAST(VFIOPCIDevice, pdev, pdev);

    VFIODevice *vbasedev_iter;

    VFIOGroup *group;

    char *tmp, group_path[PATH_MAX], *group_name;

    Error *err = NULL;

    ssize_t len;

    struct stat st;

    int groupid;

    int i, ret;



    if (!vdev->vbasedev.sysfsdev) {

        if (!(~vdev->host.domain || ~vdev->host.bus ||

              ~vdev->host.slot || ~vdev->host.function)) {

            error_setg(errp, "No provided host device");

            error_append_hint(errp, "Use -vfio-pci,host=DDDD:BB:DD.F "

                              "or -vfio-pci,sysfsdev=PATH_TO_DEVICE\n");

            return;

        }

        vdev->vbasedev.sysfsdev =

            g_strdup_printf("/sys/bus/pci/devices/%04x:%02x:%02x.%01x",

                            vdev->host.domain, vdev->host.bus,

                            vdev->host.slot, vdev->host.function);

    }



    if (stat(vdev->vbasedev.sysfsdev, &st) < 0) {

        error_setg_errno(errp, errno, "no such host device");

        error_prepend(errp, ERR_PREFIX, vdev->vbasedev.sysfsdev);

        return;

    }



    vdev->vbasedev.name = g_strdup(basename(vdev->vbasedev.sysfsdev));

    vdev->vbasedev.ops = &vfio_pci_ops;

    vdev->vbasedev.type = VFIO_DEVICE_TYPE_PCI;



    tmp = g_strdup_printf("%s/iommu_group", vdev->vbasedev.sysfsdev);

    len = readlink(tmp, group_path, sizeof(group_path));

    g_free(tmp);



    if (len <= 0 || len >= sizeof(group_path)) {

        error_setg_errno(errp, len < 0 ? errno : ENAMETOOLONG,

                         "no iommu_group found");

        goto error;

    }



    group_path[len] = 0;



    group_name = basename(group_path);

    if (sscanf(group_name, "%d", &groupid) != 1) {

        error_setg_errno(errp, errno, "failed to read %s", group_path);

        goto error;

    }



    trace_vfio_realize(vdev->vbasedev.name, groupid);



    group = vfio_get_group(groupid, pci_device_iommu_address_space(pdev), errp);

    if (!group) {

        goto error;

    }



    QLIST_FOREACH(vbasedev_iter, &group->device_list, next) {

        if (strcmp(vbasedev_iter->name, vdev->vbasedev.name) == 0) {

            error_setg(errp, "device is already attached");

            vfio_put_group(group);

            goto error;

        }

    }



    ret = vfio_get_device(group, vdev->vbasedev.name, &vdev->vbasedev, errp);

    if (ret) {

        vfio_put_group(group);

        goto error;

    }



    vfio_populate_device(vdev, &err);

    if (err) {

        error_propagate(errp, err);

        goto error;

    }



    /* Get a copy of config space */

    ret = pread(vdev->vbasedev.fd, vdev->pdev.config,

                MIN(pci_config_size(&vdev->pdev), vdev->config_size),

                vdev->config_offset);

    if (ret < (int)MIN(pci_config_size(&vdev->pdev), vdev->config_size)) {

        ret = ret < 0 ? -errno : -EFAULT;

        error_setg_errno(errp, -ret, "failed to read device config space");

        goto error;

    }



    /* vfio emulates a lot for us, but some bits need extra love */

    vdev->emulated_config_bits = g_malloc0(vdev->config_size);



    /* QEMU can choose to expose the ROM or not */

    memset(vdev->emulated_config_bits + PCI_ROM_ADDRESS, 0xff, 4);



    /*

     * The PCI spec reserves vendor ID 0xffff as an invalid value.  The

     * device ID is managed by the vendor and need only be a 16-bit value.

     * Allow any 16-bit value for subsystem so they can be hidden or changed.

     */

    if (vdev->vendor_id != PCI_ANY_ID) {

        if (vdev->vendor_id >= 0xffff) {

            error_setg(errp, "invalid PCI vendor ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_VENDOR_ID, vdev->vendor_id, ~0);

        trace_vfio_pci_emulated_vendor_id(vdev->vbasedev.name, vdev->vendor_id);

    } else {

        vdev->vendor_id = pci_get_word(pdev->config + PCI_VENDOR_ID);

    }



    if (vdev->device_id != PCI_ANY_ID) {

        if (vdev->device_id > 0xffff) {

            error_setg(errp, "invalid PCI device ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_DEVICE_ID, vdev->device_id, ~0);

        trace_vfio_pci_emulated_device_id(vdev->vbasedev.name, vdev->device_id);

    } else {

        vdev->device_id = pci_get_word(pdev->config + PCI_DEVICE_ID);

    }



    if (vdev->sub_vendor_id != PCI_ANY_ID) {

        if (vdev->sub_vendor_id > 0xffff) {

            error_setg(errp, "invalid PCI subsystem vendor ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_SUBSYSTEM_VENDOR_ID,

                               vdev->sub_vendor_id, ~0);

        trace_vfio_pci_emulated_sub_vendor_id(vdev->vbasedev.name,

                                              vdev->sub_vendor_id);

    }



    if (vdev->sub_device_id != PCI_ANY_ID) {

        if (vdev->sub_device_id > 0xffff) {

            error_setg(errp, "invalid PCI subsystem device ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_SUBSYSTEM_ID, vdev->sub_device_id, ~0);

        trace_vfio_pci_emulated_sub_device_id(vdev->vbasedev.name,

                                              vdev->sub_device_id);

    }



    /* QEMU can change multi-function devices to single function, or reverse */

    vdev->emulated_config_bits[PCI_HEADER_TYPE] =

                                              PCI_HEADER_TYPE_MULTI_FUNCTION;



    /* Restore or clear multifunction, this is always controlled by QEMU */

    if (vdev->pdev.cap_present & QEMU_PCI_CAP_MULTIFUNCTION) {

        vdev->pdev.config[PCI_HEADER_TYPE] |= PCI_HEADER_TYPE_MULTI_FUNCTION;

    } else {

        vdev->pdev.config[PCI_HEADER_TYPE] &= ~PCI_HEADER_TYPE_MULTI_FUNCTION;

    }



    /*

     * Clear host resource mapping info.  If we choose not to register a

     * BAR, such as might be the case with the option ROM, we can get

     * confusing, unwritable, residual addresses from the host here.

     */

    memset(&vdev->pdev.config[PCI_BASE_ADDRESS_0], 0, 24);

    memset(&vdev->pdev.config[PCI_ROM_ADDRESS], 0, 4);



    vfio_pci_size_rom(vdev);



    vfio_msix_early_setup(vdev, &err);

    if (err) {

        error_propagate(errp, err);

        goto error;

    }



    vfio_bars_setup(vdev);



    ret = vfio_add_capabilities(vdev, errp);

    if (ret) {

        goto out_teardown;

    }



    if (vdev->vga) {

        vfio_vga_quirk_setup(vdev);

    }



    for (i = 0; i < PCI_ROM_SLOT; i++) {

        vfio_bar_quirk_setup(vdev, i);

    }



    if (!vdev->igd_opregion &&

        vdev->features & VFIO_FEATURE_ENABLE_IGD_OPREGION) {

        struct vfio_region_info *opregion;



        if (vdev->pdev.qdev.hotplugged) {

            error_setg(errp,

                       "cannot support IGD OpRegion feature on hotplugged "

                       "device");

            goto out_teardown;

        }



        ret = vfio_get_dev_region_info(&vdev->vbasedev,

                        VFIO_REGION_TYPE_PCI_VENDOR_TYPE | PCI_VENDOR_ID_INTEL,

                        VFIO_REGION_SUBTYPE_INTEL_IGD_OPREGION, &opregion);

        if (ret) {

            error_setg_errno(errp, -ret,

                             "does not support requested IGD OpRegion feature");

            goto out_teardown;

        }



        ret = vfio_pci_igd_opregion_init(vdev, opregion, errp);

        g_free(opregion);

        if (ret) {

            goto out_teardown;

        }

    }



    /* QEMU emulates all of MSI & MSIX */

    if (pdev->cap_present & QEMU_PCI_CAP_MSIX) {

        memset(vdev->emulated_config_bits + pdev->msix_cap, 0xff,

               MSIX_CAP_LENGTH);

    }



    if (pdev->cap_present & QEMU_PCI_CAP_MSI) {

        memset(vdev->emulated_config_bits + pdev->msi_cap, 0xff,

               vdev->msi_cap_size);

    }



    if (vfio_pci_read_config(&vdev->pdev, PCI_INTERRUPT_PIN, 1)) {

        vdev->intx.mmap_timer = timer_new_ms(QEMU_CLOCK_VIRTUAL,

                                                  vfio_intx_mmap_enable, vdev);

        pci_device_set_intx_routing_notifier(&vdev->pdev, vfio_intx_update);

        ret = vfio_intx_enable(vdev, errp);

        if (ret) {

            goto out_teardown;

        }

    }



    vfio_register_err_notifier(vdev);

    vfio_register_req_notifier(vdev);

    vfio_setup_resetfn_quirk(vdev);



    return;



out_teardown:

    pci_device_set_intx_routing_notifier(&vdev->pdev, NULL);

    vfio_teardown_msi(vdev);

    vfio_bars_exit(vdev);

error:

    error_prepend(errp, ERR_PREFIX, vdev->vbasedev.name);

}

static int mux_proc_byte(CharDriverState *chr, MuxDriver *d, int ch)

{

    if (d->term_got_escape) {

        d->term_got_escape = 0;

        if (ch == term_escape_char)

            goto send_char;

        switch(ch) {

        case '?':

        case 'h':

            mux_print_help(chr);

            break;

        case 'x':

            {

                 const char *term =  "QEMU: Terminated\n\r";

                 qemu_chr_fe_write(chr, (uint8_t *)term, strlen(term));

                 exit(0);

                 break;

            }

        case 's':

            blk_commit_all();

            break;

        case 'b':

            qemu_chr_be_event(chr, CHR_EVENT_BREAK);

            break;

        case 'c':

            /* Switch to the next registered device */

            mux_chr_send_event(d, d->focus, CHR_EVENT_MUX_OUT);

            d->focus++;

            if (d->focus >= d->mux_cnt)

                d->focus = 0;

            mux_chr_send_event(d, d->focus, CHR_EVENT_MUX_IN);

            break;

        case 't':

            d->timestamps = !d->timestamps;

            d->timestamps_start = -1;

            d->linestart = 0;

            break;

        }

    } else if (ch == term_escape_char) {

        d->term_got_escape = 1;

    } else {

    send_char:

        return 1;

    }

    return 0;

}

void do_migrate_set_speed(Monitor *mon, const QDict *qdict)

{

    double d;

    char *ptr;

    FdMigrationState *s;

    const char *value = qdict_get_str(qdict, "value");



    d = strtod(value, &ptr);

    switch (*ptr) {

    case 'G': case 'g':

        d *= 1024;

    case 'M': case 'm':

        d *= 1024;

    case 'K': case 'k':

        d *= 1024;

    default:

        break;

    }



    max_throttle = (uint32_t)d;



    s = migrate_to_fms(current_migration);

    if (s && s->file) {

        qemu_file_set_rate_limit(s->file, max_throttle);

    }

}

static int mov_write_ftyp_tag(AVIOContext *pb, AVFormatContext *s)

{

    MOVMuxContext *mov = s->priv_data;

    int64_t pos = avio_tell(pb);

    int has_h264 = 0, has_video = 0;

    int minor = 0x200;

    int i;



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

            has_video = 1;

        if (st->codec->codec_id == AV_CODEC_ID_H264)

            has_h264 = 1;

    }



    avio_wb32(pb, 0); /* size */

    ffio_wfourcc(pb, "ftyp");



    if (mov->mode == MODE_3GP) {

        ffio_wfourcc(pb, has_h264 ? "3gp6"  : "3gp4");

        minor =     has_h264 ?   0x100 :   0x200;

    } else if (mov->mode & MODE_3G2) {

        ffio_wfourcc(pb, has_h264 ? "3g2b"  : "3g2a");

        minor =     has_h264 ? 0x20000 : 0x10000;

    } else if (mov->mode == MODE_PSP)

        ffio_wfourcc(pb, "MSNV");

    else if (mov->mode == MODE_MP4)

        ffio_wfourcc(pb, "isom");

    else if (mov->mode == MODE_IPOD)

        ffio_wfourcc(pb, has_video ? "M4V ":"M4A ");

    else if (mov->mode == MODE_ISM)

        ffio_wfourcc(pb, "isml");

    else if (mov->mode == MODE_F4V)

        ffio_wfourcc(pb, "f4v ");

    else

        ffio_wfourcc(pb, "qt  ");



    avio_wb32(pb, minor);



    if (mov->mode == MODE_MOV)

        ffio_wfourcc(pb, "qt  ");

    else if (mov->mode == MODE_ISM) {

        ffio_wfourcc(pb, "piff");

        ffio_wfourcc(pb, "iso2");

    } else {

        ffio_wfourcc(pb, "isom");

        ffio_wfourcc(pb, "iso2");

        if (has_h264)

            ffio_wfourcc(pb, "avc1");

    }



    if (mov->mode == MODE_3GP)

        ffio_wfourcc(pb, has_h264 ? "3gp6":"3gp4");

    else if (mov->mode & MODE_3G2)

        ffio_wfourcc(pb, has_h264 ? "3g2b":"3g2a");

    else if (mov->mode == MODE_PSP)

        ffio_wfourcc(pb, "MSNV");

    else if (mov->mode == MODE_MP4)

        ffio_wfourcc(pb, "mp41");

    return update_size(pb, pos);

}

static void read_ttag(AVFormatContext *s, int taglen, const char *key)

{

    char *q, dst[512];

    int len, dstlen = sizeof(dst) - 1;

    unsigned genre;



    dst[0] = 0;

    if (taglen < 1)

        return;



    taglen--; /* account for encoding type byte */



    switch (get_byte(s->pb)) { /* encoding type */



    case 0:  /* ISO-8859-1 (0 - 255 maps directly into unicode) */

        q = dst;

        while (taglen--) {

            uint8_t tmp;

            PUT_UTF8(get_byte(s->pb), tmp, if (q - dst < dstlen - 1) *q++ = tmp;)

        }

        *q = '\0';

        break;



    case 3:  /* UTF-8 */

        len = FFMIN(taglen, dstlen - 1);

        get_buffer(s->pb, dst, len);

        dst[len] = 0;

        break;

    }



    if (!strcmp(key, "genre")

        && (sscanf(dst, "(%d)", &genre) == 1 || sscanf(dst, "%d", &genre) == 1)

        && genre <= ID3v1_GENRE_MAX)

        av_strlcpy(dst, ff_id3v1_genre_str[genre], sizeof(dst));



    if (*dst)

        av_metadata_set(&s->metadata, key, dst);

}

static int vnc_update_client(VncState *vs, int has_dirty)

{

    if (vs->need_update && vs->csock != -1) {

        VncDisplay *vd = vs->vd;

        VncJob *job;

        int y;

        int width, height;

        int n = 0;





        if (vs->output.offset && !vs->audio_cap && !vs->force_update)

            /* kernel send buffers are full -> drop frames to throttle */

            return 0;



        if (!has_dirty && !vs->audio_cap && !vs->force_update)

            return 0;



        /*

         * Send screen updates to the vnc client using the server

         * surface and server dirty map.  guest surface updates

         * happening in parallel don't disturb us, the next pass will

         * send them to the client.

         */

        job = vnc_job_new(vs);



        width = MIN(pixman_image_get_width(vd->server), vs->client_width);

        height = MIN(pixman_image_get_height(vd->server), vs->client_height);



        for (y = 0; y < height; y++) {

            int x;

            int last_x = -1;

            for (x = 0; x < width / 16; x++) {

                if (test_and_clear_bit(x, vs->dirty[y])) {

                    if (last_x == -1) {

                        last_x = x;

                    }

                } else {

                    if (last_x != -1) {

                        int h = find_and_clear_dirty_height(vs, y, last_x, x,

                                                            height);



                        n += vnc_job_add_rect(job, last_x * 16, y,

                                              (x - last_x) * 16, h);

                    }

                    last_x = -1;

                }

            }

            if (last_x != -1) {

                int h = find_and_clear_dirty_height(vs, y, last_x, x, height);

                n += vnc_job_add_rect(job, last_x * 16, y,

                                      (x - last_x) * 16, h);

            }

        }



        vnc_job_push(job);

        vs->force_update = 0;

        return n;

    }



    if (vs->csock == -1)

        vnc_disconnect_finish(vs);



    return 0;

}

void aio_bh_schedule_oneshot(AioContext *ctx, QEMUBHFunc *cb, void *opaque)

{

    QEMUBH *bh;

    bh = g_new(QEMUBH, 1);

    *bh = (QEMUBH){

        .ctx = ctx,

        .cb = cb,

        .opaque = opaque,

    };

    qemu_lockcnt_lock(&ctx->list_lock);

    bh->next = ctx->first_bh;

    bh->scheduled = 1;

    bh->deleted = 1;

    /* Make sure that the members are ready before putting bh into list */

    smp_wmb();

    ctx->first_bh = bh;

    qemu_lockcnt_unlock(&ctx->list_lock);

    aio_notify(ctx);

}

static void do_apply_filter(APEContext *ctx, int version, APEFilter *f,

                            int32_t *data, int count, int order, int fracbits)

{

    int res;

    int absres;



    while (count--) {

        /* round fixedpoint scalar product */

        res = ctx->adsp.scalarproduct_and_madd_int16(f->coeffs,

                                                     f->delay - order,

                                                     f->adaptcoeffs - order,

                                                     order, APESIGN(*data));

        res = (res + (1 << (fracbits - 1))) >> fracbits;

        res += *data;

        *data++ = res;



        /* Update the output history */

        *f->delay++ = av_clip_int16(res);



        if (version < 3980) {

            /* Version ??? to < 3.98 files (untested) */

            f->adaptcoeffs[0]  = (res == 0) ? 0 : ((res >> 28) & 8) - 4;

            f->adaptcoeffs[-4] >>= 1;

            f->adaptcoeffs[-8] >>= 1;

        } else {

            /* Version 3.98 and later files */



            /* Update the adaption coefficients */

            absres = FFABS(res);

            if (absres)

                *f->adaptcoeffs = ((res & (-1<<31)) ^ (-1<<30)) >>

                                  (25 + (absres <= f->avg*3) + (absres <= f->avg*4/3));

            else

                *f->adaptcoeffs = 0;



            f->avg += (absres - f->avg) / 16;



            f->adaptcoeffs[-1] >>= 1;

            f->adaptcoeffs[-2] >>= 1;

            f->adaptcoeffs[-8] >>= 1;

        }



        f->adaptcoeffs++;



        /* Have we filled the history buffer? */

        if (f->delay == f->historybuffer + HISTORY_SIZE + (order * 2)) {

            memmove(f->historybuffer, f->delay - (order * 2),

                    (order * 2) * sizeof(*f->historybuffer));

            f->delay = f->historybuffer + order * 2;

            f->adaptcoeffs = f->historybuffer + order;

        }

    }

}

static int writev_f(BlockBackend *blk, int argc, char **argv)

{

    struct timeval t1, t2;

    bool Cflag = false, qflag = false;

    int flags = 0;

    int c, cnt;

    char *buf;

    int64_t offset;

    /* Some compilers get confused and warn if this is not initialized.  */

    int total = 0;

    int nr_iov;

    int pattern = 0xcd;

    QEMUIOVector qiov;



    while ((c = getopt(argc, argv, "CqP:")) != -1) {

        switch (c) {

        case 'C':

            Cflag = true;

            break;

        case 'f':

            flags |= BDRV_REQ_FUA;

            break;

        case 'q':

            qflag = true;

            break;

        case 'P':

            pattern = parse_pattern(optarg);

            if (pattern < 0) {

                return 0;

            }

            break;

        default:

            return qemuio_command_usage(&writev_cmd);

        }

    }



    if (optind > argc - 2) {

        return qemuio_command_usage(&writev_cmd);

    }



    offset = cvtnum(argv[optind]);

    if (offset < 0) {

        print_cvtnum_err(offset, argv[optind]);

        return 0;

    }

    optind++;



    nr_iov = argc - optind;

    buf = create_iovec(blk, &qiov, &argv[optind], nr_iov, pattern);

    if (buf == NULL) {

        return 0;

    }



    gettimeofday(&t1, NULL);

    cnt = do_aio_writev(blk, &qiov, offset, flags, &total);

    gettimeofday(&t2, NULL);



    if (cnt < 0) {

        printf("writev failed: %s\n", strerror(-cnt));

        goto out;

    }



    if (qflag) {

        goto out;

    }



    /* Finally, report back -- -C gives a parsable format */

    t2 = tsub(t2, t1);

    print_report("wrote", &t2, offset, qiov.size, total, cnt, Cflag);

out:

    qemu_iovec_destroy(&qiov);

    qemu_io_free(buf);

    return 0;

}

