            }

#endif

        }

    }

#endif

}

static int verify_md5(HEVCContext *s, AVFrame *frame)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(frame->format);

    int pixel_shift = desc->comp[0].depth_minus1 > 7;

    int i, j;



    if (!desc)

        return AVERROR(EINVAL);



    av_log(s->avctx, AV_LOG_DEBUG, "Verifying checksum for frame with POC %d: ",

           s->poc);



    /* the checksums are LE, so we have to byteswap for >8bpp formats

     * on BE arches */

#if HAVE_BIGENDIAN

    if (pixel_shift && !s->checksum_buf) {

        av_fast_malloc(&s->checksum_buf, &s->checksum_buf_size,

                       FFMAX3(frame->linesize[0], frame->linesize[1],

                              frame->linesize[2]));

        if (!s->checksum_buf)

            return AVERROR(ENOMEM);

    }

#endif



    for (i = 0; frame->data[i]; i++) {

        int width  = s->avctx->coded_width;

        int height = s->avctx->coded_height;

        int w = (i == 1 || i == 2) ? (width  >> desc->log2_chroma_w) : width;

        int h = (i == 1 || i == 2) ? (height >> desc->log2_chroma_h) : height;

        uint8_t md5[16];



        av_md5_init(s->md5_ctx);

        for (j = 0; j < h; j++) {

            const uint8_t *src = frame->data[i] + j * frame->linesize[i];

#if HAVE_BIGENDIAN

            if (pixel_shift) {

                s->dsp.bswap16_buf((uint16_t*)s->checksum_buf,

                                   (const uint16_t*)src, w);

                src = s->checksum_buf;

            }

#endif

            av_md5_update(s->md5_ctx, src, w << pixel_shift);

        }

        av_md5_final(s->md5_ctx, md5);



        if (!memcmp(md5, s->md5[i], 16)) {

            av_log   (s->avctx, AV_LOG_DEBUG, "plane %d - correct ", i);

            print_md5(s->avctx, AV_LOG_DEBUG, md5);

            av_log   (s->avctx, AV_LOG_DEBUG, "; ");

        } else {

            av_log   (s->avctx, AV_LOG_ERROR, "mismatching checksum of plane %d - ", i);

            print_md5(s->avctx, AV_LOG_ERROR, md5);

            av_log   (s->avctx, AV_LOG_ERROR, " != ");

            print_md5(s->avctx, AV_LOG_ERROR, s->md5[i]);

            av_log   (s->avctx, AV_LOG_ERROR, "\n");

            return AVERROR_INVALIDDATA;

        }

    }



    av_log(s->avctx, AV_LOG_DEBUG, "\n");



    return 0;

}

static int decode_subpacket(COOKContext *q, uint8_t *inbuffer,

                            int sub_packet_size, int16_t *outbuffer) {

    int i,j;

    int value;

    float* tmp_ptr;



    /* packet dump */

//    for (i=0 ; i<sub_packet_size ; i++) {

//        av_log(NULL, AV_LOG_ERROR, "%02x", inbuffer[i]);

//    }

//    av_log(NULL, AV_LOG_ERROR, "\n");



    decode_bytes(inbuffer, q->decoded_bytes_buffer, sub_packet_size);

    init_get_bits(&q->gb, q->decoded_bytes_buffer, sub_packet_size*8);

    decode_gain_info(&q->gb, &q->gain_current);

    memcpy(&q->gain_copy, &q->gain_current ,sizeof(COOKgain));  //This copy does not seem to be used. FIXME



    if(q->nb_channels==2 && q->joint_stereo==1){

        joint_decode(q, q->decode_buf_ptr[0], q->decode_buf_ptr[2]);



        /* Swap buffer pointers. */

        tmp_ptr = q->decode_buf_ptr[1];

        q->decode_buf_ptr[1] = q->decode_buf_ptr[0];

        q->decode_buf_ptr[0] = tmp_ptr;

        tmp_ptr = q->decode_buf_ptr[3];

        q->decode_buf_ptr[3] = q->decode_buf_ptr[2];

        q->decode_buf_ptr[2] = tmp_ptr;



        /* FIXME: Rethink the gainbuffer handling, maybe a rename?

           now/previous swap */

        q->gain_now_ptr = &q->gain_now;

        q->gain_previous_ptr = &q->gain_previous;

        for (i=0 ; i<q->nb_channels ; i++){



            cook_imlt(q, q->decode_buf_ptr[i*2], q->mono_mdct_output, q->mlt_tmp);

            gain_compensate(q, q->mono_mdct_output, q->gain_now_ptr,

                            q->gain_previous_ptr, q->previous_buffer_ptr[0]);



            /* Swap out the previous buffer. */

            tmp_ptr = q->previous_buffer_ptr[0];

            q->previous_buffer_ptr[0] = q->previous_buffer_ptr[1];

            q->previous_buffer_ptr[1] = tmp_ptr;



            /* Clip and convert the floats to 16 bits. */

            for (j=0 ; j<q->samples_per_frame ; j++){

                value = lrintf(q->mono_mdct_output[j]);

                if(value < -32768) value = -32768;

                else if(value > 32767) value = 32767;

                outbuffer[2*j+i] = value;

            }

        }



        memcpy(&q->gain_now, &q->gain_previous, sizeof(COOKgain));

        memcpy(&q->gain_previous, &q->gain_current, sizeof(COOKgain));



    } else if (q->nb_channels==2 && q->joint_stereo==0) {

            /* channel 0 */

            mono_decode(q, q->decode_buf_ptr[0]);



            tmp_ptr = q->decode_buf_ptr[0];

            q->decode_buf_ptr[0] = q->decode_buf_ptr[1];

            q->decode_buf_ptr[1] = q->decode_buf_ptr[2];

            q->decode_buf_ptr[2] = q->decode_buf_ptr[3];

            q->decode_buf_ptr[3] = tmp_ptr;



            q->gain_now_ptr = &q->gain_now;

            q->gain_previous_ptr = &q->gain_previous;



            cook_imlt(q, q->decode_buf_ptr[0], q->mono_mdct_output,q->mlt_tmp);

            gain_compensate(q, q->mono_mdct_output, q->gain_now_ptr,

                            q->gain_previous_ptr, q->previous_buffer_ptr[0]);

            /* Swap out the previous buffer. */

            tmp_ptr = q->previous_buffer_ptr[0];

            q->previous_buffer_ptr[0] = q->previous_buffer_ptr[1];

            q->previous_buffer_ptr[1] = tmp_ptr;



            for (j=0 ; j<q->samples_per_frame ; j++){

                value = lrintf(q->mono_mdct_output[j]);

                if(value < -32768) value = -32768;

                else if(value > 32767) value = 32767;

                outbuffer[2*j+1] = value;

            }



            /* channel 1 */

            //av_log(NULL,AV_LOG_ERROR,"bits = %d\n",get_bits_count(&q->gb));

            init_get_bits(&q->gb, q->decoded_bytes_buffer, sub_packet_size*8+q->bits_per_subpacket);

            decode_gain_info(&q->gb, &q->gain_current);

            //memcpy(&q->gain_copy, &q->gain_current ,sizeof(COOKgain));

            mono_decode(q, q->decode_buf_ptr[0]);

            tmp_ptr = q->decode_buf_ptr[0];

            q->decode_buf_ptr[1] = q->decode_buf_ptr[2];

            q->decode_buf_ptr[2] = q->decode_buf_ptr[3];

            q->decode_buf_ptr[3] = tmp_ptr;



            q->gain_now_ptr = &q->gain_now;

            q->gain_previous_ptr = &q->gain_previous;



            cook_imlt(q, q->decode_buf_ptr[0], q->mono_mdct_output,q->mlt_tmp);

            gain_compensate(q, q->mono_mdct_output, q->gain_now_ptr, q->gain_previous_ptr, q->previous_buffer_ptr[0]);



            /* Swap out the previous buffer. */

            tmp_ptr = q->previous_buffer_ptr[0];

            q->previous_buffer_ptr[0] = q->previous_buffer_ptr[1];

            q->previous_buffer_ptr[1] = tmp_ptr;



            for (j=0 ; j<q->samples_per_frame ; j++){

                value = lrintf(q->mono_mdct_output[j]);

                if(value < -32768) value = -32768;

                else if(value > 32767) value = 32767;

                outbuffer[2*j] = value;

            }





            /* Swap out the previous buffer. */

            memcpy(&q->gain_now, &q->gain_previous, sizeof(COOKgain));

            memcpy(&q->gain_previous, &q->gain_current, sizeof(COOKgain));



    } else {

        mono_decode(q, q->decode_buf_ptr[0]);



        /* Swap buffer pointers. */

        tmp_ptr = q->decode_buf_ptr[1];

        q->decode_buf_ptr[1] = q->decode_buf_ptr[0];

        q->decode_buf_ptr[0] = tmp_ptr;



        /* FIXME: Rethink the gainbuffer handling, maybe a rename?

           now/previous swap */

        q->gain_now_ptr = &q->gain_now;

        q->gain_previous_ptr = &q->gain_previous;



        cook_imlt(q, q->decode_buf_ptr[0], q->mono_mdct_output,q->mlt_tmp);

        gain_compensate(q, q->mono_mdct_output, q->gain_now_ptr,

                        q->gain_previous_ptr, q->mono_previous_buffer1);



        /* Clip and convert the floats to 16 bits */

        for (j=0 ; j<q->samples_per_frame ; j++){

            value = lrintf(q->mono_mdct_output[j]);

            if(value < -32768) value = -32768;

            else if(value > 32767) value = 32767;

            outbuffer[j] = value;

        }

        memcpy(&q->gain_now, &q->gain_previous, sizeof(COOKgain));

        memcpy(&q->gain_previous, &q->gain_current, sizeof(COOKgain));

    }

    return q->samples_per_frame * sizeof(int16_t);

}

static int virtio_scsi_parse_req(VirtIOSCSIReq *req,

                                 unsigned req_size, unsigned resp_size)

{

    VirtIODevice *vdev = (VirtIODevice *) req->dev;

    size_t in_size, out_size;



    if (iov_to_buf(req->elem.out_sg, req->elem.out_num, 0,

                   &req->req, req_size) < req_size) {

        return -EINVAL;

    }



    if (qemu_iovec_concat_iov(&req->resp_iov,

                              req->elem.in_sg, req->elem.in_num, 0,

                              resp_size) < resp_size) {

        return -EINVAL;

    }



    req->resp_size = resp_size;



    /* Old BIOSes left some padding by mistake after the req_size/resp_size.

     * As a workaround, always consider the first buffer as the virtio-scsi

     * request/response, making the payload start at the second element

     * of the iovec.

     *

     * The actual length of the response header, stored in req->resp_size,

     * does not change.

     *

     * TODO: always disable this workaround for virtio 1.0 devices.

     */

    if (!virtio_has_feature(vdev, VIRTIO_F_ANY_LAYOUT)) {

        req_size = req->elem.out_sg[0].iov_len;

        resp_size = req->elem.in_sg[0].iov_len;

    }



    out_size = qemu_sgl_concat(req, req->elem.out_sg,

                               &req->elem.out_addr[0], req->elem.out_num,

                               req_size);

    in_size = qemu_sgl_concat(req, req->elem.in_sg,

                              &req->elem.in_addr[0], req->elem.in_num,

                              resp_size);



    if (out_size && in_size) {

        return -ENOTSUP;

    }



    if (out_size) {

        req->mode = SCSI_XFER_TO_DEV;

    } else if (in_size) {

        req->mode = SCSI_XFER_FROM_DEV;

    }



    return 0;

}

VncInfo *qmp_query_vnc(Error **errp)

{

    VncInfo *info = g_malloc0(sizeof(*info));

    VncDisplay *vd = vnc_display_find(NULL);

    SocketAddressLegacy *addr = NULL;



    if (vd == NULL || !vd->nlsock) {

        info->enabled = false;

    } else {

        info->enabled = true;



        /* for compatibility with the original command */

        info->has_clients = true;

        info->clients = qmp_query_client_list(vd);



        if (vd->lsock == NULL) {

            return info;

        }



        addr = qio_channel_socket_get_local_address(vd->lsock[0], errp);

        if (!addr) {

            goto out_error;

        }



        switch (addr->type) {

        case SOCKET_ADDRESS_LEGACY_KIND_INET:

            info->host = g_strdup(addr->u.inet.data->host);

            info->service = g_strdup(addr->u.inet.data->port);

            if (addr->u.inet.data->ipv6) {

                info->family = NETWORK_ADDRESS_FAMILY_IPV6;

            } else {

                info->family = NETWORK_ADDRESS_FAMILY_IPV4;

            }

            break;



        case SOCKET_ADDRESS_LEGACY_KIND_UNIX:

            info->host = g_strdup("");

            info->service = g_strdup(addr->u.q_unix.data->path);

            info->family = NETWORK_ADDRESS_FAMILY_UNIX;

            break;



        case SOCKET_ADDRESS_LEGACY_KIND_VSOCK:

        case SOCKET_ADDRESS_LEGACY_KIND_FD:

            error_setg(errp, "Unsupported socket address type %s",

                       SocketAddressLegacyKind_lookup[addr->type]);

            goto out_error;

        default:

            abort();

        }



        info->has_host = true;

        info->has_service = true;

        info->has_family = true;



        info->has_auth = true;

        info->auth = g_strdup(vnc_auth_name(vd));

    }



    qapi_free_SocketAddressLegacy(addr);

    return info;



out_error:

    qapi_free_SocketAddressLegacy(addr);

    qapi_free_VncInfo(info);

    return NULL;

}

int redir_open(AVFormatContext **ic_ptr, ByteIOContext *f)

{

    char buf[4096], *q;

    int c;

    AVFormatContext *ic = NULL;



    /* parse each URL and try to open it */

    c = url_fgetc(f);

    while (c != URL_EOF) {

        /* skip spaces */

        for(;;) {

            if (!redir_isspace(c))

                break;

            c = url_fgetc(f);

        }

        if (c == URL_EOF)

            break;

        /* record url */

        q = buf;

        for(;;) {

            if (c == URL_EOF || redir_isspace(c))

                break;

            if ((q - buf) < sizeof(buf) - 1)

                *q++ = c;

            c = url_fgetc(f);

        }

        *q = '\0';

        //printf("URL='%s'\n", buf);

        /* try to open the media file */

        if (av_open_input_file(&ic, buf, NULL, 0, NULL) == 0)

            break;

    }

    *ic_ptr = ic;

    if (!ic)

        return AVERROR(EIO);

    else

        return 0;

}

static int translate_pages(S390CPU *cpu, vaddr addr, int nr_pages,

                           target_ulong *pages, bool is_write)

{

    bool lowprot = is_write && lowprot_enabled(&cpu->env);

    uint64_t asc = cpu->env.psw.mask & PSW_MASK_ASC;

    CPUS390XState *env = &cpu->env;

    int ret, i, pflags;



    for (i = 0; i < nr_pages; i++) {

        /* Low-address protection? */

        if (lowprot && (addr < 512 || (addr >= 4096 && addr < 4096 + 512))) {

            trigger_access_exception(env, PGM_PROTECTION, ILEN_AUTO, 0);

            return -EACCES;

        }

        ret = mmu_translate(env, addr, is_write, asc, &pages[i], &pflags, true);

        if (ret) {

            return ret;

        }

        if (!address_space_access_valid(&address_space_memory, pages[i],

                                        TARGET_PAGE_SIZE, is_write)) {

            program_interrupt(env, PGM_ADDRESSING, ILEN_AUTO);

            return -EFAULT;

        }

        addr += TARGET_PAGE_SIZE;

    }



    return 0;

}

static void blend_frame(AVFilterContext *ctx,

                        AVFrame *top_buf,

                        AVFrame *bottom_buf,

                        AVFrame *dst_buf)

{

    BlendContext *b = ctx->priv;

    AVFilterLink *inlink = ctx->inputs[0];

    FilterParams *param;

    int plane;



    for (plane = 0; dst_buf->data[plane]; plane++) {

        int hsub = plane == 1 || plane == 2 ? b->hsub : 0;

        int vsub = plane == 1 || plane == 2 ? b->vsub : 0;

        int outw = dst_buf->width  >> hsub;

        int outh = dst_buf->height >> vsub;

        uint8_t *dst    = dst_buf->data[plane];

        uint8_t *top    = top_buf->data[plane];

        uint8_t *bottom = bottom_buf->data[plane];



        param = &b->params[plane];

        param->values[VAR_N]  = inlink->frame_count;

        param->values[VAR_T]  = dst_buf->pts == AV_NOPTS_VALUE ? NAN : dst_buf->pts * av_q2d(inlink->time_base);

        param->values[VAR_W]  = outw;

        param->values[VAR_H]  = outh;

        param->values[VAR_SW] = outw / dst_buf->width;

        param->values[VAR_SH] = outh / dst_buf->height;

        param->blend(top, top_buf->linesize[plane],

                     bottom, bottom_buf->linesize[plane],

                     dst, dst_buf->linesize[plane], outw, outh, param);

    }

}

