static int64_t mkv_write_seekhead(AVIOContext *pb, mkv_seekhead *seekhead)

{

    ebml_master metaseek, seekentry;

    int64_t currentpos;

    int i;



    currentpos = avio_tell(pb);



    if (seekhead->reserved_size > 0)

        if (avio_seek(pb, seekhead->filepos, SEEK_SET) < 0)

            return -1;



    metaseek = start_ebml_master(pb, MATROSKA_ID_SEEKHEAD, seekhead->reserved_size);

    for (i = 0; i < seekhead->num_entries; i++) {

        mkv_seekhead_entry *entry = &seekhead->entries[i];



        seekentry = start_ebml_master(pb, MATROSKA_ID_SEEKENTRY, MAX_SEEKENTRY_SIZE);



        put_ebml_id(pb, MATROSKA_ID_SEEKID);

        put_ebml_num(pb, ebml_id_size(entry->elementid), 0);

        put_ebml_id(pb, entry->elementid);



        put_ebml_uint(pb, MATROSKA_ID_SEEKPOSITION, entry->segmentpos);

        end_ebml_master(pb, seekentry);

    }

    end_ebml_master(pb, metaseek);



    if (seekhead->reserved_size > 0) {

        uint64_t remaining = seekhead->filepos + seekhead->reserved_size - avio_tell(pb);

        put_ebml_void(pb, remaining);

        avio_seek(pb, currentpos, SEEK_SET);



        currentpos = seekhead->filepos;

    }

    av_free(seekhead->entries);

    av_free(seekhead);



    return currentpos;

}

static void vp8_filter_mb_row(AVCodecContext *avctx, void *tdata,

                              int jobnr, int threadnr)

{

    VP8Context *s = avctx->priv_data;

    VP8ThreadData *td = &s->thread_data[threadnr];

    int mb_x, mb_y = td->thread_mb_pos >> 16, num_jobs = s->num_jobs;

    AVFrame *curframe = s->curframe->tf.f;

    VP8Macroblock *mb;

    VP8ThreadData *prev_td, *next_td;

    uint8_t *dst[3] = {

        curframe->data[0] + 16 * mb_y * s->linesize,

        curframe->data[1] +  8 * mb_y * s->uvlinesize,

        curframe->data[2] +  8 * mb_y * s->uvlinesize

    };



    if (s->mb_layout == 1)

        mb = s->macroblocks_base + ((s->mb_width + 1) * (mb_y + 1) + 1);

    else

        mb = s->macroblocks + (s->mb_height - mb_y - 1) * 2;



    if (mb_y == 0)

        prev_td = td;

    else

        prev_td = &s->thread_data[(jobnr + num_jobs - 1) % num_jobs];

    if (mb_y == s->mb_height - 1)

        next_td = td;

    else

        next_td = &s->thread_data[(jobnr + 1) % num_jobs];



    for (mb_x = 0; mb_x < s->mb_width; mb_x++, mb++) {

        VP8FilterStrength *f = &td->filter_strength[mb_x];

        if (prev_td != td)

            check_thread_pos(td, prev_td,

                             (mb_x + 1) + (s->mb_width + 3), mb_y - 1);

        if (next_td != td)

            if (next_td != &s->thread_data[0])

                check_thread_pos(td, next_td, mb_x + 1, mb_y + 1);



        if (num_jobs == 1) {

            if (s->filter.simple)

                backup_mb_border(s->top_border[mb_x + 1], dst[0],

                                 NULL, NULL, s->linesize, 0, 1);

            else

                backup_mb_border(s->top_border[mb_x + 1], dst[0],

                                 dst[1], dst[2], s->linesize, s->uvlinesize, 0);

        }



        if (s->filter.simple)

            filter_mb_simple(s, dst[0], f, mb_x, mb_y);

        else

            filter_mb(s, dst, f, mb_x, mb_y);

        dst[0] += 16;

        dst[1] += 8;

        dst[2] += 8;



        update_pos(td, mb_y, (s->mb_width + 3) + mb_x);

    }

}

static void *buffered_file_thread(void *opaque)

{

    MigrationState *s = opaque;

    int64_t initial_time = qemu_get_clock_ms(rt_clock);

    int64_t sleep_time = 0;

    int64_t max_size = 0;

    bool last_round = false;

    int ret;



    qemu_mutex_lock_iothread();

    DPRINTF("beginning savevm\n");

    ret = qemu_savevm_state_begin(s->file, &s->params);

    qemu_mutex_unlock_iothread();



    while (ret >= 0) {

        int64_t current_time;

        uint64_t pending_size;



        qemu_mutex_lock_iothread();

        if (s->state != MIG_STATE_ACTIVE) {

            DPRINTF("put_ready returning because of non-active state\n");

            qemu_mutex_unlock_iothread();

            break;

        }

        if (s->complete) {

            qemu_mutex_unlock_iothread();

            break;

        }

        if (s->bytes_xfer < s->xfer_limit) {

            DPRINTF("iterate\n");

            pending_size = qemu_savevm_state_pending(s->file, max_size);

            DPRINTF("pending size %lu max %lu\n", pending_size, max_size);

            if (pending_size && pending_size >= max_size) {

                ret = qemu_savevm_state_iterate(s->file);

                if (ret < 0) {

                    qemu_mutex_unlock_iothread();

                    break;

                }

            } else {

                int old_vm_running = runstate_is_running();

                int64_t start_time, end_time;



                DPRINTF("done iterating\n");

                start_time = qemu_get_clock_ms(rt_clock);

                qemu_system_wakeup_request(QEMU_WAKEUP_REASON_OTHER);

                vm_stop_force_state(RUN_STATE_FINISH_MIGRATE);

                ret = qemu_savevm_state_complete(s->file);

                if (ret < 0) {

                    qemu_mutex_unlock_iothread();

                    break;

                } else {

                    migrate_fd_completed(s);

                }

                end_time = qemu_get_clock_ms(rt_clock);

                s->total_time = end_time - s->total_time;

                s->downtime = end_time - start_time;

                if (s->state != MIG_STATE_COMPLETED) {

                    if (old_vm_running) {

                        vm_start();

                    }

                }

                last_round = true;

            }

        }

        qemu_mutex_unlock_iothread();

        current_time = qemu_get_clock_ms(rt_clock);

        if (current_time >= initial_time + BUFFER_DELAY) {

            uint64_t transferred_bytes = s->bytes_xfer;

            uint64_t time_spent = current_time - initial_time - sleep_time;

            double bandwidth = transferred_bytes / time_spent;

            max_size = bandwidth * migrate_max_downtime() / 1000000;



            DPRINTF("transferred %" PRIu64 " time_spent %" PRIu64

                    " bandwidth %g max_size %" PRId64 "\n",

                    transferred_bytes, time_spent, bandwidth, max_size);

            /* if we haven't sent anything, we don't want to recalculate

               10000 is a small enough number for our purposes */

            if (s->dirty_bytes_rate && transferred_bytes > 10000) {

                s->expected_downtime = s->dirty_bytes_rate / bandwidth;

            }



            s->bytes_xfer = 0;

            sleep_time = 0;

            initial_time = current_time;

        }

        if (!last_round && (s->bytes_xfer >= s->xfer_limit)) {

            /* usleep expects microseconds */

            g_usleep((initial_time + BUFFER_DELAY - current_time)*1000);

            sleep_time += qemu_get_clock_ms(rt_clock) - current_time;

        }

        buffered_flush(s);

        ret = qemu_file_get_error(s->file);

    }



    if (ret < 0) {

        migrate_fd_error(s);

    }

    g_free(s->buffer);

    return NULL;

}

static int ccid_handle_bulk_out(USBCCIDState *s, USBPacket *p)

{

    CCID_Header *ccid_header;



    if (p->len + s->bulk_out_pos > BULK_OUT_DATA_SIZE) {

        return USB_RET_STALL;

    }

    ccid_header = (CCID_Header *)s->bulk_out_data;

    memcpy(s->bulk_out_data + s->bulk_out_pos, p->data, p->len);

    s->bulk_out_pos += p->len;

    if (p->len == CCID_MAX_PACKET_SIZE) {

        DPRINTF(s, D_VERBOSE,

            "usb-ccid: bulk_in: expecting more packets (%d/%d)\n",

            p->len, ccid_header->dwLength);

        return 0;

    }

    if (s->bulk_out_pos < 10) {

        DPRINTF(s, 1,

                "%s: bad USB_TOKEN_OUT length, should be at least 10 bytes\n",

                __func__);

    } else {

        DPRINTF(s, D_MORE_INFO, "%s %x\n", __func__, ccid_header->bMessageType);

        switch (ccid_header->bMessageType) {

        case CCID_MESSAGE_TYPE_PC_to_RDR_GetSlotStatus:

            ccid_write_slot_status(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_IccPowerOn:

            DPRINTF(s, 1, "PowerOn: %d\n",

                ((CCID_IccPowerOn *)(ccid_header))->bPowerSelect);

            s->powered = true;

            if (!ccid_card_inserted(s)) {

                ccid_report_error_failed(s, ERROR_ICC_MUTE);

            }

            /* atr is written regardless of error. */

            ccid_write_data_block_atr(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_IccPowerOff:

            DPRINTF(s, 1, "PowerOff\n");

            ccid_reset_error_status(s);

            s->powered = false;

            ccid_write_slot_status(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_XfrBlock:

            ccid_on_apdu_from_guest(s, (CCID_XferBlock *)s->bulk_out_data);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_SetParameters:

            ccid_reset_error_status(s);

            ccid_set_parameters(s, ccid_header);

            ccid_write_parameters(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_ResetParameters:

            ccid_reset_error_status(s);

            ccid_reset_parameters(s);

            ccid_write_parameters(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_GetParameters:

            ccid_reset_error_status(s);

            ccid_write_parameters(s, ccid_header);

            break;

        default:

            DPRINTF(s, 1,

                "handle_data: ERROR: unhandled message type %Xh\n",

                ccid_header->bMessageType);

            /*

             * The caller is expecting the device to respond, tell it we

             * don't support the operation.

             */

            ccid_report_error_failed(s, ERROR_CMD_NOT_SUPPORTED);

            ccid_write_slot_status(s, ccid_header);

            break;

        }

    }

    s->bulk_out_pos = 0;

    return 0;

}

static void vga_draw_text(VGAState *s, int full_update)

{

    int cx, cy, cheight, cw, ch, cattr, height, width, ch_attr;

    int cx_min, cx_max, linesize, x_incr;

    uint32_t offset, fgcol, bgcol, v, cursor_offset;

    uint8_t *d1, *d, *src, *s1, *dest, *cursor_ptr;

    const uint8_t *font_ptr, *font_base[2];

    int dup9, line_offset, depth_index;

    uint32_t *palette;

    uint32_t *ch_attr_ptr;

    vga_draw_glyph8_func *vga_draw_glyph8;

    vga_draw_glyph9_func *vga_draw_glyph9;



    vga_dirty_log_stop(s);



    /* compute font data address (in plane 2) */

    v = s->sr[3];

    offset = (((v >> 4) & 1) | ((v << 1) & 6)) * 8192 * 4 + 2;

    if (offset != s->font_offsets[0]) {

        s->font_offsets[0] = offset;

        full_update = 1;

    }

    font_base[0] = s->vram_ptr + offset;



    offset = (((v >> 5) & 1) | ((v >> 1) & 6)) * 8192 * 4 + 2;

    font_base[1] = s->vram_ptr + offset;

    if (offset != s->font_offsets[1]) {

        s->font_offsets[1] = offset;

        full_update = 1;

    }

    if (s->plane_updated & (1 << 2)) {

        /* if the plane 2 was modified since the last display, it

           indicates the font may have been modified */

        s->plane_updated = 0;

        full_update = 1;

    }

    full_update |= update_basic_params(s);



    line_offset = s->line_offset;

    s1 = s->vram_ptr + (s->start_addr * 4);



    vga_get_text_resolution(s, &width, &height, &cw, &cheight);

    x_incr = cw * ((ds_get_bits_per_pixel(s->ds) + 7) >> 3);

    if ((height * width) > CH_ATTR_SIZE) {

        /* better than nothing: exit if transient size is too big */

        return;

    }



    if (width != s->last_width || height != s->last_height ||

        cw != s->last_cw || cheight != s->last_ch || s->last_depth) {

        s->last_scr_width = width * cw;

        s->last_scr_height = height * cheight;

        qemu_console_resize(s->ds, s->last_scr_width, s->last_scr_height);

        s->last_depth = 0;

        s->last_width = width;

        s->last_height = height;

        s->last_ch = cheight;

        s->last_cw = cw;

        full_update = 1;

    }

    s->rgb_to_pixel =

        rgb_to_pixel_dup_table[get_depth_index(s->ds)];

    full_update |= update_palette16(s);

    palette = s->last_palette;

    x_incr = cw * ((ds_get_bits_per_pixel(s->ds) + 7) >> 3);



    cursor_offset = ((s->cr[0x0e] << 8) | s->cr[0x0f]) - s->start_addr;

    if (cursor_offset != s->cursor_offset ||

        s->cr[0xa] != s->cursor_start ||

        s->cr[0xb] != s->cursor_end) {

      /* if the cursor position changed, we update the old and new

         chars */

        if (s->cursor_offset < CH_ATTR_SIZE)

            s->last_ch_attr[s->cursor_offset] = -1;

        if (cursor_offset < CH_ATTR_SIZE)

            s->last_ch_attr[cursor_offset] = -1;

        s->cursor_offset = cursor_offset;

        s->cursor_start = s->cr[0xa];

        s->cursor_end = s->cr[0xb];

    }

    cursor_ptr = s->vram_ptr + (s->start_addr + cursor_offset) * 4;



    depth_index = get_depth_index(s->ds);

    if (cw == 16)

        vga_draw_glyph8 = vga_draw_glyph16_table[depth_index];

    else

        vga_draw_glyph8 = vga_draw_glyph8_table[depth_index];

    vga_draw_glyph9 = vga_draw_glyph9_table[depth_index];



    dest = ds_get_data(s->ds);

    linesize = ds_get_linesize(s->ds);

    ch_attr_ptr = s->last_ch_attr;

    for(cy = 0; cy < height; cy++) {

        d1 = dest;

        src = s1;

        cx_min = width;

        cx_max = -1;

        for(cx = 0; cx < width; cx++) {

            ch_attr = *(uint16_t *)src;

            if (full_update || ch_attr != *ch_attr_ptr) {

                if (cx < cx_min)

                    cx_min = cx;

                if (cx > cx_max)

                    cx_max = cx;

                *ch_attr_ptr = ch_attr;

#ifdef WORDS_BIGENDIAN

                ch = ch_attr >> 8;

                cattr = ch_attr & 0xff;

#else

                ch = ch_attr & 0xff;

                cattr = ch_attr >> 8;

#endif

                font_ptr = font_base[(cattr >> 3) & 1];

                font_ptr += 32 * 4 * ch;

                bgcol = palette[cattr >> 4];

                fgcol = palette[cattr & 0x0f];

                if (cw != 9) {

                    vga_draw_glyph8(d1, linesize,

                                    font_ptr, cheight, fgcol, bgcol);

                } else {

                    dup9 = 0;

                    if (ch >= 0xb0 && ch <= 0xdf && (s->ar[0x10] & 0x04))

                        dup9 = 1;

                    vga_draw_glyph9(d1, linesize,

                                    font_ptr, cheight, fgcol, bgcol, dup9);

                }

                if (src == cursor_ptr &&

                    !(s->cr[0x0a] & 0x20)) {

                    int line_start, line_last, h;

                    /* draw the cursor */

                    line_start = s->cr[0x0a] & 0x1f;

                    line_last = s->cr[0x0b] & 0x1f;

                    /* XXX: check that */

                    if (line_last > cheight - 1)

                        line_last = cheight - 1;

                    if (line_last >= line_start && line_start < cheight) {

                        h = line_last - line_start + 1;

                        d = d1 + linesize * line_start;

                        if (cw != 9) {

                            vga_draw_glyph8(d, linesize,

                                            cursor_glyph, h, fgcol, bgcol);

                        } else {

                            vga_draw_glyph9(d, linesize,

                                            cursor_glyph, h, fgcol, bgcol, 1);

                        }

                    }

                }

            }

            d1 += x_incr;

            src += 4;

            ch_attr_ptr++;

        }

        if (cx_max != -1) {

            dpy_update(s->ds, cx_min * cw, cy * cheight,

                       (cx_max - cx_min + 1) * cw, cheight);

        }

        dest += linesize * cheight;

        s1 += line_offset;

    }

}

