static void new_video_stream(AVFormatContext *oc)

{

    AVStream *st;

    AVCodecContext *video_enc;

    enum CodecID codec_id;



    st = av_new_stream(oc, oc->nb_streams);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        av_exit(1);

    }

    avcodec_get_context_defaults2(st->codec, AVMEDIA_TYPE_VIDEO);

    bitstream_filters[nb_output_files][oc->nb_streams - 1]= video_bitstream_filters;

    video_bitstream_filters= NULL;



    avcodec_thread_init(st->codec, thread_count);



    video_enc = st->codec;



    if(video_codec_tag)

        video_enc->codec_tag= video_codec_tag;



    if(   (video_global_header&1)

       || (video_global_header==0 && (oc->oformat->flags & AVFMT_GLOBALHEADER))){

        video_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_VIDEO]->flags|= CODEC_FLAG_GLOBAL_HEADER;

    }

    if(video_global_header&2){

        video_enc->flags2 |= CODEC_FLAG2_LOCAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_VIDEO]->flags2|= CODEC_FLAG2_LOCAL_HEADER;

    }



    if (video_stream_copy) {

        st->stream_copy = 1;

        video_enc->codec_type = AVMEDIA_TYPE_VIDEO;

        video_enc->sample_aspect_ratio =

        st->sample_aspect_ratio = av_d2q(frame_aspect_ratio*frame_height/frame_width, 255);

    } else {

        const char *p;

        int i;

        AVCodec *codec;

        AVRational fps= frame_rate.num ? frame_rate : (AVRational){25,1};



        if (video_codec_name) {

            codec_id = find_codec_or_die(video_codec_name, AVMEDIA_TYPE_VIDEO, 1);

            codec = avcodec_find_encoder_by_name(video_codec_name);

            output_codecs[nb_ocodecs] = codec;

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_VIDEO);

            codec = avcodec_find_encoder(codec_id);

        }



        video_enc->codec_id = codec_id;



        set_context_opts(video_enc, avcodec_opts[AVMEDIA_TYPE_VIDEO], AV_OPT_FLAG_VIDEO_PARAM | AV_OPT_FLAG_ENCODING_PARAM);



        if (codec && codec->supported_framerates && !force_fps)

            fps = codec->supported_framerates[av_find_nearest_q_idx(fps, codec->supported_framerates)];

        video_enc->time_base.den = fps.num;

        video_enc->time_base.num = fps.den;



        video_enc->width = frame_width + frame_padright + frame_padleft;

        video_enc->height = frame_height + frame_padtop + frame_padbottom;

        video_enc->sample_aspect_ratio = av_d2q(frame_aspect_ratio*video_enc->height/video_enc->width, 255);

        video_enc->pix_fmt = frame_pix_fmt;

        st->sample_aspect_ratio = video_enc->sample_aspect_ratio;



        choose_pixel_fmt(st, codec);



        if (intra_only)

            video_enc->gop_size = 0;

        if (video_qscale || same_quality) {

            video_enc->flags |= CODEC_FLAG_QSCALE;

            video_enc->global_quality=

                st->quality = FF_QP2LAMBDA * video_qscale;

        }



        if(intra_matrix)

            video_enc->intra_matrix = intra_matrix;

        if(inter_matrix)

            video_enc->inter_matrix = inter_matrix;



        p= video_rc_override_string;

        for(i=0; p; i++){

            int start, end, q;

            int e=sscanf(p, "%d,%d,%d", &start, &end, &q);

            if(e!=3){

                fprintf(stderr, "error parsing rc_override\n");

                av_exit(1);

            }

            video_enc->rc_override=

                av_realloc(video_enc->rc_override,

                           sizeof(RcOverride)*(i+1));

            video_enc->rc_override[i].start_frame= start;

            video_enc->rc_override[i].end_frame  = end;

            if(q>0){

                video_enc->rc_override[i].qscale= q;

                video_enc->rc_override[i].quality_factor= 1.0;

            }

            else{

                video_enc->rc_override[i].qscale= 0;

                video_enc->rc_override[i].quality_factor= -q/100.0;

            }

            p= strchr(p, '/');

            if(p) p++;

        }

        video_enc->rc_override_count=i;

        if (!video_enc->rc_initial_buffer_occupancy)

            video_enc->rc_initial_buffer_occupancy = video_enc->rc_buffer_size*3/4;

        video_enc->me_threshold= me_threshold;

        video_enc->intra_dc_precision= intra_dc_precision - 8;



        if (do_psnr)

            video_enc->flags|= CODEC_FLAG_PSNR;



        /* two pass mode */

        if (do_pass) {

            if (do_pass == 1) {

                video_enc->flags |= CODEC_FLAG_PASS1;

            } else {

                video_enc->flags |= CODEC_FLAG_PASS2;

            }

        }

    }

    nb_ocodecs++;

    if (video_language) {

        av_metadata_set2(&st->metadata, "language", video_language, 0);

        av_freep(&video_language);

    }



    /* reset some key parameters */

    video_disable = 0;

    av_freep(&video_codec_name);

    video_stream_copy = 0;

    frame_pix_fmt = PIX_FMT_NONE;

}

static av_cold int encode_init(AVCodecContext *avctx)

{

    FFV1Context *s = avctx->priv_data;

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(avctx->pix_fmt);

    int i, j, k, m, ret;



    if ((ret = ff_ffv1_common_init(avctx)) < 0)

        return ret;



    s->version = 0;



    if ((avctx->flags & (AV_CODEC_FLAG_PASS1 | AV_CODEC_FLAG_PASS2)) ||

        avctx->slices > 1)

        s->version = FFMAX(s->version, 2);



    // Unspecified level & slices, we choose version 1.2+ to ensure multithreaded decodability

    if (avctx->slices == 0 && avctx->level < 0 && avctx->width * avctx->height > 720*576)

        s->version = FFMAX(s->version, 2);



    if (avctx->level <= 0 && s->version == 2) {

        s->version = 3;

    }

    if (avctx->level >= 0 && avctx->level <= 4) {

        if (avctx->level < s->version) {

            av_log(avctx, AV_LOG_ERROR, "Version %d needed for requested features but %d requested\n", s->version, avctx->level);

            return AVERROR(EINVAL);

        }

        s->version = avctx->level;

    }



    if (s->ec < 0) {

        s->ec = (s->version >= 3);

    }



    if ((s->version == 2 || s->version>3) && avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL) {

        av_log(avctx, AV_LOG_ERROR, "Version 2 needed for requested features but version 2 is experimental and not enabled\n");

        return AVERROR_INVALIDDATA;

    }



#if FF_API_CODER_TYPE

FF_DISABLE_DEPRECATION_WARNINGS

    if (avctx->coder_type != -1)

        s->ac = avctx->coder_type > 0 ? AC_RANGE_CUSTOM_TAB : AC_GOLOMB_RICE;

    else

FF_ENABLE_DEPRECATION_WARNINGS

#endif

    if (s->ac == 1) // Compatbility with common command line usage

        s->ac = AC_RANGE_CUSTOM_TAB;

    else if (s->ac == AC_RANGE_DEFAULT_TAB_FORCE)

        s->ac = AC_RANGE_DEFAULT_TAB;



    s->plane_count = 3;

    switch(avctx->pix_fmt) {

    case AV_PIX_FMT_YUV444P9:

    case AV_PIX_FMT_YUV422P9:

    case AV_PIX_FMT_YUV420P9:

    case AV_PIX_FMT_YUVA444P9:

    case AV_PIX_FMT_YUVA422P9:

    case AV_PIX_FMT_YUVA420P9:

        if (!avctx->bits_per_raw_sample)

            s->bits_per_raw_sample = 9;

    case AV_PIX_FMT_GRAY10:

    case AV_PIX_FMT_YUV444P10:

    case AV_PIX_FMT_YUV420P10:

    case AV_PIX_FMT_YUV422P10:

    case AV_PIX_FMT_YUVA444P10:

    case AV_PIX_FMT_YUVA422P10:

    case AV_PIX_FMT_YUVA420P10:

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 10;

    case AV_PIX_FMT_GRAY12:

    case AV_PIX_FMT_YUV444P12:

    case AV_PIX_FMT_YUV420P12:

    case AV_PIX_FMT_YUV422P12:

        s->packed_at_lsb = 1;

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 12;

    case AV_PIX_FMT_GRAY16:

    case AV_PIX_FMT_YUV444P16:

    case AV_PIX_FMT_YUV422P16:

    case AV_PIX_FMT_YUV420P16:

    case AV_PIX_FMT_YUVA444P16:

    case AV_PIX_FMT_YUVA422P16:

    case AV_PIX_FMT_YUVA420P16:

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample) {

            s->bits_per_raw_sample = 16;

        } else if (!s->bits_per_raw_sample) {

            s->bits_per_raw_sample = avctx->bits_per_raw_sample;

        }

        if (s->bits_per_raw_sample <= 8) {

            av_log(avctx, AV_LOG_ERROR, "bits_per_raw_sample invalid\n");

            return AVERROR_INVALIDDATA;

        }

        s->version = FFMAX(s->version, 1);

    case AV_PIX_FMT_GRAY8:

    case AV_PIX_FMT_YA8:

    case AV_PIX_FMT_YUV444P:

    case AV_PIX_FMT_YUV440P:

    case AV_PIX_FMT_YUV422P:

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV411P:

    case AV_PIX_FMT_YUV410P:

    case AV_PIX_FMT_YUVA444P:

    case AV_PIX_FMT_YUVA422P:

    case AV_PIX_FMT_YUVA420P:

        s->chroma_planes = desc->nb_components < 3 ? 0 : 1;

        s->colorspace = 0;

        s->transparency = desc->nb_components == 4 || desc->nb_components == 2;

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 8;

        else if (!s->bits_per_raw_sample)

            s->bits_per_raw_sample = 8;

        break;

    case AV_PIX_FMT_RGB32:

        s->colorspace = 1;

        s->transparency = 1;

        s->chroma_planes = 1;

        s->bits_per_raw_sample = 8;

        break;

    case AV_PIX_FMT_RGB48:

        s->colorspace = 1;

        s->chroma_planes = 1;

        s->bits_per_raw_sample = 16;

        s->use32bit = 1;

        s->version = FFMAX(s->version, 1);

        if (avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL) {

            av_log(avctx, AV_LOG_ERROR, "16bit RGB is experimental and under development, only use it for experiments\n");

            return AVERROR_INVALIDDATA;

        }

        break;

    case AV_PIX_FMT_0RGB32:

        s->colorspace = 1;

        s->chroma_planes = 1;

        s->bits_per_raw_sample = 8;

        break;

    case AV_PIX_FMT_GBRP9:

        if (!avctx->bits_per_raw_sample)

            s->bits_per_raw_sample = 9;

    case AV_PIX_FMT_GBRP10:

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 10;

    case AV_PIX_FMT_GBRP12:

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 12;

    case AV_PIX_FMT_GBRP14:

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 14;

    case AV_PIX_FMT_GBRP16:

        if (!avctx->bits_per_raw_sample && !s->bits_per_raw_sample)

            s->bits_per_raw_sample = 16;

        else if (!s->bits_per_raw_sample)

            s->bits_per_raw_sample = avctx->bits_per_raw_sample;

        s->colorspace = 1;

        s->chroma_planes = 1;

        if (s->bits_per_raw_sample >= 16) {

            s->use32bit = 1;

            if (avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL) {

                av_log(avctx, AV_LOG_ERROR, "16bit RGB is experimental and under development, only use it for experiments\n");

                return AVERROR_INVALIDDATA;

            }

        }

        s->version = FFMAX(s->version, 1);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "format not supported\n");

        return AVERROR(ENOSYS);

    }

    av_assert0(s->bits_per_raw_sample >= 8);



    if (s->bits_per_raw_sample > 8) {

        if (s->ac == AC_GOLOMB_RICE) {

            av_log(avctx, AV_LOG_INFO,

                    "bits_per_raw_sample > 8, forcing range coder\n");

            s->ac = AC_RANGE_CUSTOM_TAB;

        }

    }

    if (s->transparency) {

        av_log(avctx, AV_LOG_WARNING, "Storing alpha plane, this will require a recent FFV1 decoder to playback!\n");

    }

#if FF_API_PRIVATE_OPT

FF_DISABLE_DEPRECATION_WARNINGS

    if (avctx->context_model)

        s->context_model = avctx->context_model;

    if (avctx->context_model > 1U) {

        av_log(avctx, AV_LOG_ERROR, "Invalid context model %d, valid values are 0 and 1\n", avctx->context_model);

        return AVERROR(EINVAL);

    }

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    if (s->ac == AC_RANGE_CUSTOM_TAB) {

        for (i = 1; i < 256; i++)

            s->state_transition[i] = ver2_state[i];

    } else {

        RangeCoder c;

        ff_build_rac_states(&c, 0.05 * (1LL << 32), 256 - 8);

        for (i = 1; i < 256; i++)

            s->state_transition[i] = c.one_state[i];

    }



    for (i = 0; i < 256; i++) {

        s->quant_table_count = 2;

        if (s->bits_per_raw_sample <= 8) {

            s->quant_tables[0][0][i]=           quant11[i];

            s->quant_tables[0][1][i]=        11*quant11[i];

            s->quant_tables[0][2][i]=     11*11*quant11[i];

            s->quant_tables[1][0][i]=           quant11[i];

            s->quant_tables[1][1][i]=        11*quant11[i];

            s->quant_tables[1][2][i]=     11*11*quant5 [i];

            s->quant_tables[1][3][i]=   5*11*11*quant5 [i];

            s->quant_tables[1][4][i]= 5*5*11*11*quant5 [i];

        } else {

            s->quant_tables[0][0][i]=           quant9_10bit[i];

            s->quant_tables[0][1][i]=        11*quant9_10bit[i];

            s->quant_tables[0][2][i]=     11*11*quant9_10bit[i];

            s->quant_tables[1][0][i]=           quant9_10bit[i];

            s->quant_tables[1][1][i]=        11*quant9_10bit[i];

            s->quant_tables[1][2][i]=     11*11*quant5_10bit[i];

            s->quant_tables[1][3][i]=   5*11*11*quant5_10bit[i];

            s->quant_tables[1][4][i]= 5*5*11*11*quant5_10bit[i];

        }

    }

    s->context_count[0] = (11 * 11 * 11        + 1) / 2;

    s->context_count[1] = (11 * 11 * 5 * 5 * 5 + 1) / 2;

    memcpy(s->quant_table, s->quant_tables[s->context_model],

           sizeof(s->quant_table));



    for (i = 0; i < s->plane_count; i++) {

        PlaneContext *const p = &s->plane[i];



        memcpy(p->quant_table, s->quant_table, sizeof(p->quant_table));

        p->quant_table_index = s->context_model;

        p->context_count     = s->context_count[p->quant_table_index];

    }



    if ((ret = ff_ffv1_allocate_initial_states(s)) < 0)

        return ret;



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    if (!s->transparency)

        s->plane_count = 2;

    if (!s->chroma_planes && s->version > 3)

        s->plane_count--;



    avcodec_get_chroma_sub_sample(avctx->pix_fmt, &s->chroma_h_shift, &s->chroma_v_shift);

    s->picture_number = 0;



    if (avctx->flags & (AV_CODEC_FLAG_PASS1 | AV_CODEC_FLAG_PASS2)) {

        for (i = 0; i < s->quant_table_count; i++) {

            s->rc_stat2[i] = av_mallocz(s->context_count[i] *

                                        sizeof(*s->rc_stat2[i]));

            if (!s->rc_stat2[i])

                return AVERROR(ENOMEM);

        }

    }

    if (avctx->stats_in) {

        char *p = avctx->stats_in;

        uint8_t (*best_state)[256] = av_malloc_array(256, 256);

        int gob_count = 0;

        char *next;

        if (!best_state)

            return AVERROR(ENOMEM);



        av_assert0(s->version >= 2);



        for (;;) {

            for (j = 0; j < 256; j++)

                for (i = 0; i < 2; i++) {

                    s->rc_stat[j][i] = strtol(p, &next, 0);

                    if (next == p) {

                        av_log(avctx, AV_LOG_ERROR,

                               "2Pass file invalid at %d %d [%s]\n", j, i, p);

                        av_freep(&best_state);

                        return AVERROR_INVALIDDATA;

                    }

                    p = next;

                }

            for (i = 0; i < s->quant_table_count; i++)

                for (j = 0; j < s->context_count[i]; j++) {

                    for (k = 0; k < 32; k++)

                        for (m = 0; m < 2; m++) {

                            s->rc_stat2[i][j][k][m] = strtol(p, &next, 0);

                            if (next == p) {

                                av_log(avctx, AV_LOG_ERROR,

                                       "2Pass file invalid at %d %d %d %d [%s]\n",

                                       i, j, k, m, p);

                                av_freep(&best_state);

                                return AVERROR_INVALIDDATA;

                            }

                            p = next;

                        }

                }

            gob_count = strtol(p, &next, 0);

            if (next == p || gob_count <= 0) {

                av_log(avctx, AV_LOG_ERROR, "2Pass file invalid\n");

                av_freep(&best_state);

                return AVERROR_INVALIDDATA;

            }

            p = next;

            while (*p == '\n' || *p == ' ')

                p++;

            if (p[0] == 0)

                break;

        }

        if (s->ac == AC_RANGE_CUSTOM_TAB)

            sort_stt(s, s->state_transition);



        find_best_state(best_state, s->state_transition);



        for (i = 0; i < s->quant_table_count; i++) {

            for (k = 0; k < 32; k++) {

                double a=0, b=0;

                int jp = 0;

                for (j = 0; j < s->context_count[i]; j++) {

                    double p = 128;

                    if (s->rc_stat2[i][j][k][0] + s->rc_stat2[i][j][k][1] > 200 && j || a+b > 200) {

                        if (a+b)

                            p = 256.0 * b / (a + b);

                        s->initial_states[i][jp][k] =

                            best_state[av_clip(round(p), 1, 255)][av_clip_uint8((a + b) / gob_count)];

                        for(jp++; jp<j; jp++)

                            s->initial_states[i][jp][k] = s->initial_states[i][jp-1][k];

                        a=b=0;

                    }

                    a += s->rc_stat2[i][j][k][0];

                    b += s->rc_stat2[i][j][k][1];

                    if (a+b) {

                        p = 256.0 * b / (a + b);

                    }

                    s->initial_states[i][j][k] =

                        best_state[av_clip(round(p), 1, 255)][av_clip_uint8((a + b) / gob_count)];

                }

            }

        }

        av_freep(&best_state);

    }



    if (s->version > 1) {

        int plane_count = 1 + 2*s->chroma_planes + s->transparency;

        s->num_v_slices = (avctx->width > 352 || avctx->height > 288 || !avctx->slices) ? 2 : 1;



        if (avctx->height < 5)

            s->num_v_slices = 1;



        for (; s->num_v_slices < 32; s->num_v_slices++) {

            for (s->num_h_slices = s->num_v_slices; s->num_h_slices < 2*s->num_v_slices; s->num_h_slices++) {

                int maxw = (avctx->width  + s->num_h_slices - 1) / s->num_h_slices;

                int maxh = (avctx->height + s->num_v_slices - 1) / s->num_v_slices;

                if (s->num_h_slices > avctx->width || s->num_v_slices > avctx->height)

                    continue;

                if (maxw * maxh * (int64_t)(s->bits_per_raw_sample+1) * plane_count > 8<<24)

                    continue;

                if (avctx->slices == s->num_h_slices * s->num_v_slices && avctx->slices <= MAX_SLICES || !avctx->slices)

                    goto slices_ok;

            }

        }

        av_log(avctx, AV_LOG_ERROR,

               "Unsupported number %d of slices requested, please specify a "

               "supported number with -slices (ex:4,6,9,12,16, ...)\n",

               avctx->slices);

        return AVERROR(ENOSYS);

slices_ok:

        if ((ret = write_extradata(s)) < 0)

            return ret;

    }



    if ((ret = ff_ffv1_init_slice_contexts(s)) < 0)

        return ret;

    s->slice_count = s->max_slice_count;

    if ((ret = ff_ffv1_init_slices_state(s)) < 0)

        return ret;



#define STATS_OUT_SIZE 1024 * 1024 * 6

    if (avctx->flags & AV_CODEC_FLAG_PASS1) {

        avctx->stats_out = av_mallocz(STATS_OUT_SIZE);

        if (!avctx->stats_out)

            return AVERROR(ENOMEM);

        for (i = 0; i < s->quant_table_count; i++)

            for (j = 0; j < s->max_slice_count; j++) {

                FFV1Context *sf = s->slice_context[j];

                av_assert0(!sf->rc_stat2[i]);

                sf->rc_stat2[i] = av_mallocz(s->context_count[i] *

                                             sizeof(*sf->rc_stat2[i]));

                if (!sf->rc_stat2[i])

                    return AVERROR(ENOMEM);

            }

    }



    return 0;

}

static void test_qemu_strtol_full_empty(void)

{

    const char *str = "";

    long res = 999L;

    int err;



    err =  qemu_strtol(str, NULL, 0, &res);



    g_assert_cmpint(err, ==, 0);

    g_assert_cmpint(res, ==, 0);

}

void ff_ac3_bit_alloc_calc_bap(int16_t *mask, int16_t *psd, int start, int end,

                               int snr_offset, int floor,

                               const uint8_t *bap_tab, uint8_t *bap)

{

    int i, j, end1, v, address;



    /* special case, if snr offset is -960, set all bap's to zero */

    if (snr_offset == -960) {

        memset(bap, 0, 256);

        return;

    }



    i = start;

    j = bin_to_band_tab[start];

    do {

        v = (FFMAX(mask[j] - snr_offset - floor, 0) & 0x1FE0) + floor;

        end1 = FFMIN(band_start_tab[j] + ff_ac3_critical_band_size_tab[j], end);

        for (; i < end1; i++) {

            address = av_clip((psd[i] - v) >> 5, 0, 63);

            bap[i] = bap_tab[address];

        }

    } while (end > band_start_tab[j++]);

}

static void rtas_ibm_get_config_addr_info2(PowerPCCPU *cpu,

                                           sPAPREnvironment *spapr,

                                           uint32_t token, uint32_t nargs,

                                           target_ulong args, uint32_t nret,

                                           target_ulong rets)

{

    sPAPRPHBState *sphb;

    sPAPRPHBClass *spc;

    PCIDevice *pdev;

    uint32_t addr, option;

    uint64_t buid;



    if ((nargs != 4) || (nret != 2)) {

        goto param_error_exit;

    }



    buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    sphb = find_phb(spapr, buid);

    if (!sphb) {

        goto param_error_exit;

    }



    spc = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(sphb);

    if (!spc->eeh_set_option) {

        goto param_error_exit;

    }



    /*

     * We always have PE address of form "00BB0001". "BB"

     * represents the bus number of PE's primary bus.

     */

    option = rtas_ld(args, 3);

    switch (option) {

    case RTAS_GET_PE_ADDR:

        addr = rtas_ld(args, 0);

        pdev = find_dev(spapr, buid, addr);

        if (!pdev) {

            goto param_error_exit;

        }



        rtas_st(rets, 1, (pci_bus_num(pdev->bus) << 16) + 1);

        break;

    case RTAS_GET_PE_MODE:

        rtas_st(rets, 1, RTAS_PE_MODE_SHARED);

        break;

    default:

        goto param_error_exit;

    }



    rtas_st(rets, 0, RTAS_OUT_SUCCESS);

    return;



param_error_exit:

    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

}

static void decode_pulses(Pulse * pulse, GetBitContext * gb, const uint16_t * swb_offset) {

    int i;

    pulse->num_pulse = get_bits(gb, 2) + 1;

    pulse->pos[0]    = swb_offset[get_bits(gb, 6)];

    pulse->pos[0]   += get_bits(gb, 5);

    pulse->amp[0]    = get_bits(gb, 4);

    for (i = 1; i < pulse->num_pulse; i++) {

        pulse->pos[i] = get_bits(gb, 5) + pulse->pos[i-1];

        pulse->amp[i] = get_bits(gb, 4);

    }

}

static void rtas_ibm_change_msi(PowerPCCPU *cpu, sPAPREnvironment *spapr,

                                uint32_t token, uint32_t nargs,

                                target_ulong args, uint32_t nret,

                                target_ulong rets)

{

    uint32_t config_addr = rtas_ld(args, 0);

    uint64_t buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    unsigned int func = rtas_ld(args, 3);

    unsigned int req_num = rtas_ld(args, 4); /* 0 == remove all */

    unsigned int seq_num = rtas_ld(args, 5);

    unsigned int ret_intr_type;

    unsigned int irq, max_irqs = 0, num = 0;

    sPAPRPHBState *phb = NULL;

    PCIDevice *pdev = NULL;

    spapr_pci_msi *msi;

    int *config_addr_key;



    switch (func) {

    case RTAS_CHANGE_MSI_FN:

    case RTAS_CHANGE_FN:

        ret_intr_type = RTAS_TYPE_MSI;

        break;

    case RTAS_CHANGE_MSIX_FN:

        ret_intr_type = RTAS_TYPE_MSIX;

        break;

    default:

        error_report("rtas_ibm_change_msi(%u) is not implemented", func);

        rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

        return;

    }



    /* Fins sPAPRPHBState */

    phb = find_phb(spapr, buid);

    if (phb) {

        pdev = find_dev(spapr, buid, config_addr);

    }

    if (!phb || !pdev) {

        rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

        return;

    }



    /* Releasing MSIs */

    if (!req_num) {

        msi = (spapr_pci_msi *) g_hash_table_lookup(phb->msi, &config_addr);

        if (!msi) {

            trace_spapr_pci_msi("Releasing wrong config", config_addr);

            rtas_st(rets, 0, RTAS_OUT_HW_ERROR);

            return;

        }



        xics_free(spapr->icp, msi->first_irq, msi->num);

        if (msi_present(pdev)) {

            spapr_msi_setmsg(pdev, 0, false, 0, num);

        }

        if (msix_present(pdev)) {

            spapr_msi_setmsg(pdev, 0, true, 0, num);

        }

        g_hash_table_remove(phb->msi, &config_addr);



        trace_spapr_pci_msi("Released MSIs", config_addr);

        rtas_st(rets, 0, RTAS_OUT_SUCCESS);

        rtas_st(rets, 1, 0);

        return;

    }



    /* Enabling MSI */



    /* Check if the device supports as many IRQs as requested */

    if (ret_intr_type == RTAS_TYPE_MSI) {

        max_irqs = msi_nr_vectors_allocated(pdev);

    } else if (ret_intr_type == RTAS_TYPE_MSIX) {

        max_irqs = pdev->msix_entries_nr;

    }

    if (!max_irqs) {

        error_report("Requested interrupt type %d is not enabled for device %x",

                     ret_intr_type, config_addr);

        rtas_st(rets, 0, -1); /* Hardware error */

        return;

    }

    /* Correct the number if the guest asked for too many */

    if (req_num > max_irqs) {

        trace_spapr_pci_msi_retry(config_addr, req_num, max_irqs);

        req_num = max_irqs;

        irq = 0; /* to avoid misleading trace */

        goto out;

    }



    /* Allocate MSIs */

    irq = xics_alloc_block(spapr->icp, 0, req_num, false,

                           ret_intr_type == RTAS_TYPE_MSI);

    if (!irq) {

        error_report("Cannot allocate MSIs for device %x", config_addr);

        rtas_st(rets, 0, RTAS_OUT_HW_ERROR);

        return;

    }



    /* Setup MSI/MSIX vectors in the device (via cfgspace or MSIX BAR) */

    spapr_msi_setmsg(pdev, SPAPR_PCI_MSI_WINDOW, ret_intr_type == RTAS_TYPE_MSIX,

                     irq, req_num);



    /* Add MSI device to cache */

    msi = g_new(spapr_pci_msi, 1);

    msi->first_irq = irq;

    msi->num = req_num;

    config_addr_key = g_new(int, 1);

    *config_addr_key = config_addr;

    g_hash_table_insert(phb->msi, config_addr_key, msi);



out:

    rtas_st(rets, 0, RTAS_OUT_SUCCESS);

    rtas_st(rets, 1, req_num);

    rtas_st(rets, 2, ++seq_num);

    rtas_st(rets, 3, ret_intr_type);



    trace_spapr_pci_rtas_ibm_change_msi(config_addr, func, req_num, irq);

}

static abi_long do_connect(int sockfd, abi_ulong target_addr,

                           socklen_t addrlen)

{

    void *addr;



    if (addrlen < 0)

        return -TARGET_EINVAL;



    addr = alloca(addrlen);



    target_to_host_sockaddr(addr, target_addr, addrlen);

    return get_errno(connect(sockfd, addr, addrlen));

}

static bool vfio_prereg_listener_skipped_section(MemoryRegionSection *section)

{

    if (memory_region_is_iommu(section->mr)) {

        hw_error("Cannot possibly preregister IOMMU memory");

    }



    return !memory_region_is_ram(section->mr) ||

            memory_region_is_skip_dump(section->mr);

}

static void qpi_mem_writel(void *opaque, target_phys_addr_t addr, uint32_t val)

{

    CPUState *env;



    env = cpu_single_env;

    if (!env)

        return;

    env->eflags = (env->eflags & ~(IF_MASK | IOPL_MASK)) | 

        (val & (IF_MASK | IOPL_MASK));

}

int av_opt_set(void *obj, const char *name, const char *val, int search_flags)

{

    int ret = 0;

    void *dst, *target_obj;

    const AVOption *o = av_opt_find2(obj, name, NULL, 0, search_flags, &target_obj);

    if (!o || !target_obj)

        return AVERROR_OPTION_NOT_FOUND;

    if (!val && (o->type != AV_OPT_TYPE_STRING &&

                 o->type != AV_OPT_TYPE_PIXEL_FMT && o->type != AV_OPT_TYPE_SAMPLE_FMT &&

                 o->type != AV_OPT_TYPE_IMAGE_SIZE && o->type != AV_OPT_TYPE_VIDEO_RATE &&

                 o->type != AV_OPT_TYPE_DURATION && o->type != AV_OPT_TYPE_COLOR &&

                 o->type != AV_OPT_TYPE_CHANNEL_LAYOUT && o->type != AV_OPT_TYPE_BOOL))

        return AVERROR(EINVAL);



    if (o->flags & AV_OPT_FLAG_READONLY)

        return AVERROR(EINVAL);



    dst = ((uint8_t *)target_obj) + o->offset;

    switch (o->type) {

    case AV_OPT_TYPE_BOOL:

        return set_string_bool(obj, o, val, dst);

    case AV_OPT_TYPE_STRING:

        return set_string(obj, o, val, dst);

    case AV_OPT_TYPE_BINARY:

        return set_string_binary(obj, o, val, dst);

    case AV_OPT_TYPE_FLAGS:

    case AV_OPT_TYPE_INT:

    case AV_OPT_TYPE_INT64:

    case AV_OPT_TYPE_FLOAT:

    case AV_OPT_TYPE_DOUBLE:

    case AV_OPT_TYPE_RATIONAL:

        return set_string_number(obj, target_obj, o, val, dst);

    case AV_OPT_TYPE_IMAGE_SIZE:

        return set_string_image_size(obj, o, val, dst);

    case AV_OPT_TYPE_VIDEO_RATE:

        return set_string_video_rate(obj, o, val, dst);

    case AV_OPT_TYPE_PIXEL_FMT:

        return set_string_pixel_fmt(obj, o, val, dst);

    case AV_OPT_TYPE_SAMPLE_FMT:

        return set_string_sample_fmt(obj, o, val, dst);

    case AV_OPT_TYPE_DURATION:

        if (!val) {

            *(int64_t *)dst = 0;

            return 0;

        } else {

            if ((ret = av_parse_time(dst, val, 1)) < 0)

                av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\" as duration\n", val);

            return ret;

        }

        break;

    case AV_OPT_TYPE_COLOR:

        return set_string_color(obj, o, val, dst);

    case AV_OPT_TYPE_CHANNEL_LAYOUT:

        if (!val || !strcmp(val, "none")) {

            *(int64_t *)dst = 0;

        } else {

            int64_t cl = av_get_channel_layout(val);

            if (!cl) {

                av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\" as channel layout\n", val);

                ret = AVERROR(EINVAL);

            }

            *(int64_t *)dst = cl;

            return ret;

        }

        break;

    }



    av_log(obj, AV_LOG_ERROR, "Invalid option type.\n");

    return AVERROR(EINVAL);

}

static RxFilterInfo *virtio_net_query_rxfilter(NetClientState *nc)

{

    VirtIONet *n = qemu_get_nic_opaque(nc);

    VirtIODevice *vdev = VIRTIO_DEVICE(n);

    RxFilterInfo *info;

    strList *str_list, *entry;

    int i;



    info = g_malloc0(sizeof(*info));

    info->name = g_strdup(nc->name);

    info->promiscuous = n->promisc;



    if (n->nouni) {

        info->unicast = RX_STATE_NONE;

    } else if (n->alluni) {

        info->unicast = RX_STATE_ALL;

    } else {

        info->unicast = RX_STATE_NORMAL;

    }



    if (n->nomulti) {

        info->multicast = RX_STATE_NONE;

    } else if (n->allmulti) {

        info->multicast = RX_STATE_ALL;

    } else {

        info->multicast = RX_STATE_NORMAL;

    }



    info->broadcast_allowed = n->nobcast;

    info->multicast_overflow = n->mac_table.multi_overflow;

    info->unicast_overflow = n->mac_table.uni_overflow;



    info->main_mac = mac_strdup_printf(n->mac);



    str_list = NULL;

    for (i = 0; i < n->mac_table.first_multi; i++) {

        entry = g_malloc0(sizeof(*entry));

        entry->value = mac_strdup_printf(n->mac_table.macs + i * ETH_ALEN);

        entry->next = str_list;

        str_list = entry;

    }

    info->unicast_table = str_list;



    str_list = NULL;

    for (i = n->mac_table.first_multi; i < n->mac_table.in_use; i++) {

        entry = g_malloc0(sizeof(*entry));

        entry->value = mac_strdup_printf(n->mac_table.macs + i * ETH_ALEN);

        entry->next = str_list;

        str_list = entry;

    }

    info->multicast_table = str_list;

    info->vlan_table = get_vlan_table(n);



    if (!((1 << VIRTIO_NET_F_CTRL_VLAN) & vdev->guest_features)) {

        info->vlan = RX_STATE_ALL;

    } else if (!info->vlan_table) {

        info->vlan = RX_STATE_NONE;

    } else {

        info->vlan = RX_STATE_NORMAL;

    }



    /* enable event notification after query */

    nc->rxfilter_notify_enabled = 1;



    return info;

}

static void config_parse(GAConfig *config, int argc, char **argv)

{

    const char *sopt = "hVvdm:p:l:f:F::b:s:t:D";

    int opt_ind = 0, ch;

    const struct option lopt[] = {

        { "help", 0, NULL, 'h' },

        { "version", 0, NULL, 'V' },

        { "dump-conf", 0, NULL, 'D' },

        { "logfile", 1, NULL, 'l' },

        { "pidfile", 1, NULL, 'f' },

#ifdef CONFIG_FSFREEZE

        { "fsfreeze-hook", 2, NULL, 'F' },

#endif

        { "verbose", 0, NULL, 'v' },

        { "method", 1, NULL, 'm' },

        { "path", 1, NULL, 'p' },

        { "daemonize", 0, NULL, 'd' },

        { "blacklist", 1, NULL, 'b' },

#ifdef _WIN32

        { "service", 1, NULL, 's' },

#endif

        { "statedir", 1, NULL, 't' },

        { NULL, 0, NULL, 0 }

    };



    config->log_level = G_LOG_LEVEL_ERROR | G_LOG_LEVEL_CRITICAL;



    while ((ch = getopt_long(argc, argv, sopt, lopt, &opt_ind)) != -1) {

        switch (ch) {

        case 'm':

            g_free(config->method);

            config->method = g_strdup(optarg);

            break;

        case 'p':

            g_free(config->channel_path);

            config->channel_path = g_strdup(optarg);

            break;

        case 'l':

            g_free(config->log_filepath);

            config->log_filepath = g_strdup(optarg);

            break;

        case 'f':

            g_free(config->pid_filepath);

            config->pid_filepath = g_strdup(optarg);

            break;

#ifdef CONFIG_FSFREEZE

        case 'F':

            g_free(config->fsfreeze_hook);

            config->fsfreeze_hook = g_strdup(optarg ?: QGA_FSFREEZE_HOOK_DEFAULT);

            break;

#endif

        case 't':

            g_free(config->state_dir);

            config->state_dir = g_strdup(optarg);

            break;

        case 'v':

            /* enable all log levels */

            config->log_level = G_LOG_LEVEL_MASK;

            break;

        case 'V':

            printf("QEMU Guest Agent %s\n", QEMU_VERSION);

            exit(EXIT_SUCCESS);

        case 'd':

            config->daemonize = 1;

            break;

        case 'D':

            config->dumpconf = 1;

            break;

        case 'b': {

            if (is_help_option(optarg)) {

                qmp_for_each_command(ga_print_cmd, NULL);

                exit(EXIT_SUCCESS);

            }

            config->blacklist = g_list_concat(config->blacklist,

                                             split_list(optarg, ","));

            break;

        }

#ifdef _WIN32

        case 's':

            config->service = optarg;

            if (strcmp(config->service, "install") == 0) {

                if (ga_install_vss_provider()) {

                    exit(EXIT_FAILURE);

                }

                if (ga_install_service(config->channel_path,

                                       config->log_filepath, config->state_dir)) {

                    exit(EXIT_FAILURE);

                }

                exit(EXIT_SUCCESS);

            } else if (strcmp(config->service, "uninstall") == 0) {

                ga_uninstall_vss_provider();

                exit(ga_uninstall_service());

            } else if (strcmp(config->service, "vss-install") == 0) {

                if (ga_install_vss_provider()) {

                    exit(EXIT_FAILURE);

                }

                exit(EXIT_SUCCESS);

            } else if (strcmp(config->service, "vss-uninstall") == 0) {

                ga_uninstall_vss_provider();

                exit(EXIT_SUCCESS);

            } else {

                printf("Unknown service command.\n");

                exit(EXIT_FAILURE);

            }

            break;

#endif

        case 'h':

            usage(argv[0]);

            exit(EXIT_SUCCESS);

        case '?':

            g_print("Unknown option, try '%s --help' for more information.\n",

                    argv[0]);

            exit(EXIT_FAILURE);

        }

    }

}

static void sd_reset(SDState *sd, BlockBackend *blk)

{

    uint64_t size;

    uint64_t sect;



    if (blk) {

        blk_get_geometry(blk, &sect);

    } else {

        sect = 0;

    }

    size = sect << 9;



    sect = sd_addr_to_wpnum(size) + 1;



    sd->state = sd_idle_state;

    sd->rca = 0x0000;

    sd_set_ocr(sd);

    sd_set_scr(sd);

    sd_set_cid(sd);

    sd_set_csd(sd, size);

    sd_set_cardstatus(sd);

    sd_set_sdstatus(sd);



    sd->blk = blk;



    if (sd->wp_groups)

        g_free(sd->wp_groups);

    sd->wp_switch = blk ? blk_is_read_only(blk) : false;

    sd->wpgrps_size = sect;

    sd->wp_groups = bitmap_new(sd->wpgrps_size);

    memset(sd->function_group, 0, sizeof(sd->function_group));

    sd->erase_start = 0;

    sd->erase_end = 0;

    sd->size = size;

    sd->blk_len = 0x200;

    sd->pwd_len = 0;

    sd->expecting_acmd = false;

}

