static int vdi_co_read(BlockDriverState *bs,

        int64_t sector_num, uint8_t *buf, int nb_sectors)

{

    BDRVVdiState *s = bs->opaque;

    uint32_t bmap_entry;

    uint32_t block_index;

    uint32_t sector_in_block;

    uint32_t n_sectors;

    int ret;



    logout("\n");



restart:

    block_index = sector_num / s->block_sectors;

    sector_in_block = sector_num % s->block_sectors;

    n_sectors = s->block_sectors - sector_in_block;

    if (n_sectors > nb_sectors) {

        n_sectors = nb_sectors;

    }



    logout("will read %u sectors starting at sector %" PRIu64 "\n",

           n_sectors, sector_num);



    /* prepare next AIO request */

    bmap_entry = le32_to_cpu(s->bmap[block_index]);

    if (!VDI_IS_ALLOCATED(bmap_entry)) {

        /* Block not allocated, return zeros, no need to wait. */

        memset(buf, 0, n_sectors * SECTOR_SIZE);

        ret = 0;

    } else {

        uint64_t offset = s->header.offset_data / SECTOR_SIZE +

                          (uint64_t)bmap_entry * s->block_sectors +

                          sector_in_block;

        ret = bdrv_read(bs->file, offset, buf, n_sectors);

    }

    logout("%u sectors read\n", n_sectors);



    nb_sectors -= n_sectors;

    sector_num += n_sectors;

    buf += n_sectors * SECTOR_SIZE;



    if (ret >= 0 && nb_sectors > 0) {

        goto restart;

    }



    return ret;

}

static int usb_audio_handle_data(USBDevice *dev, USBPacket *p)

{

    USBAudioState *s = (USBAudioState *) dev;

    int ret = 0;



    switch (p->pid) {

    case USB_TOKEN_OUT:

        switch (p->devep) {

        case 1:

            ret = usb_audio_handle_dataout(s, p);

            break;

        default:

            goto fail;

        }

        break;



    default:

fail:

        ret = USB_RET_STALL;

        break;

    }

    if (ret == USB_RET_STALL && s->debug) {

        fprintf(stderr, "usb-audio: failed data transaction: "

                        "pid 0x%x ep 0x%x len 0x%zx\n",

                        p->pid, p->devep, p->iov.size);

    }

    return ret;

}

static int fetch_active_ports_list(QEMUFile *f,

                                   VirtIOSerial *s, uint32_t nr_active_ports)

{

    uint32_t i;



    s->post_load = g_malloc0(sizeof(*s->post_load));

    s->post_load->nr_active_ports = nr_active_ports;

    s->post_load->connected =

        g_malloc0(sizeof(*s->post_load->connected) * nr_active_ports);



    s->post_load->timer = timer_new_ns(QEMU_CLOCK_VIRTUAL,

                                            virtio_serial_post_load_timer_cb,

                                            s);



    /* Items in struct VirtIOSerialPort */

    for (i = 0; i < nr_active_ports; i++) {

        VirtIOSerialPort *port;

        uint32_t elem_popped;

        uint32_t id;



        id = qemu_get_be32(f);

        port = find_port_by_id(s, id);

        if (!port) {

            return -EINVAL;

        }



        port->guest_connected = qemu_get_byte(f);

        s->post_load->connected[i].port = port;

        s->post_load->connected[i].host_connected = qemu_get_byte(f);



        qemu_get_be32s(f, &elem_popped);

        if (elem_popped) {

            qemu_get_be32s(f, &port->iov_idx);

            qemu_get_be64s(f, &port->iov_offset);



            port->elem =

                qemu_get_virtqueue_element(f, sizeof(VirtQueueElement));



            /*

             *  Port was throttled on source machine.  Let's

             *  unthrottle it here so data starts flowing again.

             */

            virtio_serial_throttle_port(port, false);

        }

    }

    timer_mod(s->post_load->timer, 1);

    return 0;

}

static void vt82c686b_pm_realize(PCIDevice *dev, Error **errp)

{

    VT686PMState *s = DO_UPCAST(VT686PMState, dev, dev);

    uint8_t *pci_conf;



    pci_conf = s->dev.config;

    pci_set_word(pci_conf + PCI_COMMAND, 0);

    pci_set_word(pci_conf + PCI_STATUS, PCI_STATUS_FAST_BACK |

                 PCI_STATUS_DEVSEL_MEDIUM);



    /* 0x48-0x4B is Power Management I/O Base */

    pci_set_long(pci_conf + 0x48, 0x00000001);



    /* SMB ports:0xeee0~0xeeef */

    s->smb_io_base =((s->smb_io_base & 0xfff0) + 0x0);

    pci_conf[0x90] = s->smb_io_base | 1;

    pci_conf[0x91] = s->smb_io_base >> 8;

    pci_conf[0xd2] = 0x90;

    pm_smbus_init(&s->dev.qdev, &s->smb);

    memory_region_add_subregion(get_system_io(), s->smb_io_base, &s->smb.io);



    apm_init(dev, &s->apm, NULL, s);



    memory_region_init(&s->io, OBJECT(dev), "vt82c686-pm", 64);

    memory_region_set_enabled(&s->io, false);

    memory_region_add_subregion(get_system_io(), 0, &s->io);



    acpi_pm_tmr_init(&s->ar, pm_tmr_timer, &s->io);

    acpi_pm1_evt_init(&s->ar, pm_tmr_timer, &s->io);

    acpi_pm1_cnt_init(&s->ar, &s->io, 2);

}

int ff_srtp_decrypt(struct SRTPContext *s, uint8_t *buf, int *lenptr)

{

    uint8_t iv[16] = { 0 }, hmac[20];

    int len = *lenptr;

    int ext, seq_largest;

    uint32_t ssrc, roc;

    uint64_t index;

    int rtcp;



    // TODO: Missing replay protection



    if (len < s->hmac_size)

        return AVERROR_INVALIDDATA;



    rtcp = RTP_PT_IS_RTCP(buf[1]);



    // Authentication HMAC

    av_hmac_init(s->hmac, rtcp ? s->rtcp_auth : s->rtp_auth, sizeof(s->rtp_auth));

    // If MKI is used, this should exclude the MKI as well

    av_hmac_update(s->hmac, buf, len - s->hmac_size);



    if (!rtcp) {

        int seq = AV_RB16(buf + 2);

        uint32_t v;

        uint8_t rocbuf[4];



        // RFC 3711 section 3.3.1, appendix A

        seq_largest = s->seq_initialized ? s->seq_largest : seq;

        v = roc = s->roc;

        if (seq_largest < 32768) {

            if (seq - seq_largest > 32768)

                v = roc - 1;

        } else {

            if (seq_largest - 32768 > seq)

                v = roc + 1;

        }

        if (v == roc) {

            seq_largest = FFMAX(seq_largest, seq);

        } else if (v == roc + 1) {

            seq_largest = seq;

            roc = v;

        }

        index = seq + (((uint64_t)v) << 16);



        AV_WB32(rocbuf, roc);

        av_hmac_update(s->hmac, rocbuf, 4);

    }



    av_hmac_final(s->hmac, hmac, sizeof(hmac));

    if (memcmp(hmac, buf + len - s->hmac_size, s->hmac_size)) {

        av_log(NULL, AV_LOG_WARNING, "HMAC mismatch\n");

        return AVERROR_INVALIDDATA;

    }



    len -= s->hmac_size;

    *lenptr = len;



    if (len < 12)

        return AVERROR_INVALIDDATA;



    if (rtcp) {

        uint32_t srtcp_index = AV_RB32(buf + len - 4);

        len -= 4;

        *lenptr = len;



        ssrc = AV_RB32(buf + 4);

        index = srtcp_index & 0x7fffffff;



        buf += 8;

        len -= 8;

        if (!(srtcp_index & 0x80000000))

            return 0;

    } else {

        s->seq_initialized = 1;

        s->seq_largest     = seq_largest;

        s->roc             = roc;



        ext  = buf[0] & 0x10;

        ssrc = AV_RB32(buf + 8);



        buf += 12;

        len -= 12;



        if (ext) {

            if (len < 4)

                return AVERROR_INVALIDDATA;

            ext = (AV_RB16(buf + 2) + 1) * 4;

            if (len < ext)

                return AVERROR_INVALIDDATA;

            len -= ext;

            buf += ext;

        }

    }



    create_iv(iv, rtcp ? s->rtcp_salt : s->rtp_salt, index, ssrc);

    av_aes_init(s->aes, rtcp ? s->rtcp_key : s->rtp_key, 128, 0);

    encrypt_counter(s->aes, iv, buf, len);



    return 0;

}

static int virtio_balloon_load(QEMUFile *f, void *opaque, int version_id)

{

    VirtIOBalloon *s = opaque;



