int ff_msmpeg4_pred_dc(MpegEncContext *s, int n,

                       int16_t **dc_val_ptr, int *dir_ptr)

{

    int a, b, c, wrap, pred, scale;

    int16_t *dc_val;



    /* find prediction */

    if (n < 4) {

        scale = s->y_dc_scale;

    } else {

        scale = s->c_dc_scale;

    }



    wrap = s->block_wrap[n];

    dc_val= s->dc_val[0] + s->block_index[n];



    /* B C

     * A X

     */

    a = dc_val[ - 1];

    b = dc_val[ - 1 - wrap];

    c = dc_val[ - wrap];



    if(s->first_slice_line && (n&2)==0 && s->msmpeg4_version<4){

        b=c=1024;

    }



    /* XXX: the following solution consumes divisions, but it does not

       necessitate to modify mpegvideo.c. The problem comes from the

       fact they decided to store the quantized DC (which would lead

       to problems if Q could vary !) */

#if ARCH_X86 && HAVE_7REGS && HAVE_EBX_AVAILABLE

    __asm__ volatile(

        "movl %3, %%eax         \n\t"

        "shrl $1, %%eax         \n\t"

        "addl %%eax, %2         \n\t"

        "addl %%eax, %1         \n\t"

        "addl %0, %%eax         \n\t"

        "mull %4                \n\t"

        "movl %%edx, %0         \n\t"

        "movl %1, %%eax         \n\t"

        "mull %4                \n\t"

        "movl %%edx, %1         \n\t"

        "movl %2, %%eax         \n\t"

        "mull %4                \n\t"

        "movl %%edx, %2         \n\t"

        : "+b" (a), "+c" (b), "+D" (c)

        : "g" (scale), "S" (ff_inverse[scale])

        : "%eax", "%edx"

    );

#else

    /* Divisions are costly everywhere; optimize the most common case. */

    if (scale == 8) {

        a = (a + (8 >> 1)) / 8;

        b = (b + (8 >> 1)) / 8;

        c = (c + (8 >> 1)) / 8;

    } else {

        a = FASTDIV((a + (scale >> 1)), scale);

        b = FASTDIV((b + (scale >> 1)), scale);

        c = FASTDIV((c + (scale >> 1)), scale);

    }

#endif

    /* XXX: WARNING: they did not choose the same test as MPEG4. This

       is very important ! */

    if(s->msmpeg4_version>3){

        if(s->inter_intra_pred){

            uint8_t *dest;

            int wrap;



            if(n==1){

                pred=a;

                *dir_ptr = 0;

            }else if(n==2){

                pred=c;

                *dir_ptr = 1;

            }else if(n==3){

                if (abs(a - b) < abs(b - c)) {

                    pred = c;

                    *dir_ptr = 1;

                } else {

                    pred = a;

                    *dir_ptr = 0;

                }

            }else{

                if(n<4){

                    wrap= s->linesize;

                    dest= s->current_picture.f.data[0] + (((n >> 1) + 2*s->mb_y) * 8*  wrap ) + ((n & 1) + 2*s->mb_x) * 8;

                }else{

                    wrap= s->uvlinesize;

                    dest= s->current_picture.f.data[n - 3] + (s->mb_y * 8 * wrap) + s->mb_x * 8;

                }

                if(s->mb_x==0) a= (1024 + (scale>>1))/scale;

                else           a= get_dc(dest-8, wrap, scale*8);

                if(s->mb_y==0) c= (1024 + (scale>>1))/scale;

                else           c= get_dc(dest-8*wrap, wrap, scale*8);



                if (s->h263_aic_dir==0) {

                    pred= a;

                    *dir_ptr = 0;

                }else if (s->h263_aic_dir==1) {

                    if(n==0){

                        pred= c;

                        *dir_ptr = 1;

                    }else{

                        pred= a;

                        *dir_ptr = 0;

                    }

                }else if (s->h263_aic_dir==2) {

                    if(n==0){

                        pred= a;

                        *dir_ptr = 0;

                    }else{

                        pred= c;

                        *dir_ptr = 1;

                    }

                } else {

                    pred= c;

                    *dir_ptr = 1;

                }

            }

        }else{

            if (abs(a - b) < abs(b - c)) {

                pred = c;

                *dir_ptr = 1;

            } else {

                pred = a;

                *dir_ptr = 0;

            }

        }

    }else{

        if (abs(a - b) <= abs(b - c)) {

            pred = c;

            *dir_ptr = 1;

        } else {

            pred = a;

            *dir_ptr = 0;

        }

    }



    /* update predictor */

    *dc_val_ptr = &dc_val[0];

    return pred;

}

static NetSocketState *net_socket_fd_init_dgram(VLANState *vlan,

                                                const char *model,

                                                const char *name,

                                                int fd, int is_connected)

{

    struct sockaddr_in saddr;

    int newfd;

    socklen_t saddr_len;

    VLANClientState *nc;

    NetSocketState *s;



    /* fd passed: multicast: "learn" dgram_dst address from bound address and save it

     * Because this may be "shared" socket from a "master" process, datagrams would be recv()

     * by ONLY ONE process: we must "clone" this dgram socket --jjo

     */



    if (is_connected) {

        if (getsockname(fd, (struct sockaddr *) &saddr, &saddr_len) == 0) {

            /* must be bound */

            if (saddr.sin_addr.s_addr == 0) {

                fprintf(stderr, "qemu: error: init_dgram: fd=%d unbound, "

                        "cannot setup multicast dst addr\n", fd);

                return NULL;

            }

            /* clone dgram socket */

            newfd = net_socket_mcast_create(&saddr, NULL);

            if (newfd < 0) {

                /* error already reported by net_socket_mcast_create() */

                close(fd);

                return NULL;

            }

            /* clone newfd to fd, close newfd */

            dup2(newfd, fd);

            close(newfd);



        } else {

            fprintf(stderr,

                    "qemu: error: init_dgram: fd=%d failed getsockname(): %s\n",

                    fd, strerror(errno));

            return NULL;

        }

    }



    nc = qemu_new_net_client(&net_dgram_socket_info, vlan, NULL, model, name);



    snprintf(nc->info_str, sizeof(nc->info_str),

            "socket: fd=%d (%s mcast=%s:%d)",

            fd, is_connected ? "cloned" : "",

            inet_ntoa(saddr.sin_addr), ntohs(saddr.sin_port));



    s = DO_UPCAST(NetSocketState, nc, nc);



    s->fd = fd;



    qemu_set_fd_handler(s->fd, net_socket_send_dgram, NULL, s);



    /* mcast: save bound address as dst */

    if (is_connected) s->dgram_dst=saddr;



    return s;

}

