static int css_interpret_ccw(SubchDev *sch, hwaddr ccw_addr,

                             bool suspend_allowed)

{

    int ret;

    bool check_len;

    int len;

    CCW1 ccw;



    if (!ccw_addr) {

        return -EIO;

    }

    /* Check doubleword aligned and 31 or 24 (fmt 0) bit addressable. */

    if (ccw_addr & (sch->ccw_fmt_1 ? 0x80000007 : 0xff000007)) {

        return -EINVAL;

    }



    /* Translate everything to format-1 ccws - the information is the same. */

    ccw = copy_ccw_from_guest(ccw_addr, sch->ccw_fmt_1);



    /* Check for invalid command codes. */

    if ((ccw.cmd_code & 0x0f) == 0) {

        return -EINVAL;

    }

    if (((ccw.cmd_code & 0x0f) == CCW_CMD_TIC) &&

        ((ccw.cmd_code & 0xf0) != 0)) {

        return -EINVAL;

    }

    if (!sch->ccw_fmt_1 && (ccw.count == 0) &&

        (ccw.cmd_code != CCW_CMD_TIC)) {

        return -EINVAL;

    }



    /* We don't support MIDA. */

    if (ccw.flags & CCW_FLAG_MIDA) {

        return -EINVAL;

    }



    if (ccw.flags & CCW_FLAG_SUSPEND) {

        return suspend_allowed ? -EINPROGRESS : -EINVAL;

    }



    check_len = !((ccw.flags & CCW_FLAG_SLI) && !(ccw.flags & CCW_FLAG_DC));



    if (!ccw.cda) {

        if (sch->ccw_no_data_cnt == 255) {

            return -EINVAL;

        }

        sch->ccw_no_data_cnt++;

    }



    /* Look at the command. */

    switch (ccw.cmd_code) {

    case CCW_CMD_NOOP:

        /* Nothing to do. */

        ret = 0;

        break;

    case CCW_CMD_BASIC_SENSE:

        if (check_len) {

            if (ccw.count != sizeof(sch->sense_data)) {

                ret = -EINVAL;

                break;

            }

        }

        len = MIN(ccw.count, sizeof(sch->sense_data));

        cpu_physical_memory_write(ccw.cda, sch->sense_data, len);

        sch->curr_status.scsw.count = ccw.count - len;

        memset(sch->sense_data, 0, sizeof(sch->sense_data));

        ret = 0;

        break;

    case CCW_CMD_SENSE_ID:

    {

        SenseId sense_id;



        copy_sense_id_to_guest(&sense_id, &sch->id);

        /* Sense ID information is device specific. */

        if (check_len) {

            if (ccw.count != sizeof(sense_id)) {

                ret = -EINVAL;

                break;

            }

        }

        len = MIN(ccw.count, sizeof(sense_id));

        /*

         * Only indicate 0xff in the first sense byte if we actually

         * have enough place to store at least bytes 0-3.

         */

        if (len >= 4) {

            sense_id.reserved = 0xff;

        } else {

            sense_id.reserved = 0;

        }

        cpu_physical_memory_write(ccw.cda, &sense_id, len);

        sch->curr_status.scsw.count = ccw.count - len;

        ret = 0;

        break;

    }

    case CCW_CMD_TIC:

        if (sch->last_cmd_valid && (sch->last_cmd.cmd_code == CCW_CMD_TIC)) {

            ret = -EINVAL;

            break;

        }

        if (ccw.flags & (CCW_FLAG_CC | CCW_FLAG_DC)) {

            ret = -EINVAL;

            break;

        }

        sch->channel_prog = ccw.cda;

        ret = -EAGAIN;

        break;

    default:

        if (sch->ccw_cb) {

            /* Handle device specific commands. */

            ret = sch->ccw_cb(sch, ccw);

        } else {

            ret = -ENOSYS;

        }

        break;

    }

    sch->last_cmd = ccw;

    sch->last_cmd_valid = true;

    if (ret == 0) {

        if (ccw.flags & CCW_FLAG_CC) {

            sch->channel_prog += 8;

            ret = -EAGAIN;

        }

    }



    return ret;

}

static bool get_phys_addr(CPUARMState *env, target_ulong address,

                          int access_type, ARMMMUIdx mmu_idx,

                          hwaddr *phys_ptr, MemTxAttrs *attrs, int *prot,

                          target_ulong *page_size, uint32_t *fsr,

                          ARMMMUFaultInfo *fi)

{

    if (mmu_idx == ARMMMUIdx_S12NSE0 || mmu_idx == ARMMMUIdx_S12NSE1) {

        /* Call ourselves recursively to do the stage 1 and then stage 2

         * translations.

         */

        if (arm_feature(env, ARM_FEATURE_EL2)) {

            hwaddr ipa;

            int s2_prot;

            int ret;



            ret = get_phys_addr(env, address, access_type,

                                stage_1_mmu_idx(mmu_idx), &ipa, attrs,

                                prot, page_size, fsr, fi);



            /* If S1 fails or S2 is disabled, return early.  */

            if (ret || regime_translation_disabled(env, ARMMMUIdx_S2NS)) {

                *phys_ptr = ipa;

                return ret;

            }



            /* S1 is done. Now do S2 translation.  */

            ret = get_phys_addr_lpae(env, ipa, access_type, ARMMMUIdx_S2NS,

                                     phys_ptr, attrs, &s2_prot,

                                     page_size, fsr, fi);

            fi->s2addr = ipa;

            /* Combine the S1 and S2 perms.  */

            *prot &= s2_prot;

            return ret;

        } else {

            /*

             * For non-EL2 CPUs a stage1+stage2 translation is just stage 1.

             */

            mmu_idx = stage_1_mmu_idx(mmu_idx);

        }

    }



    /* The page table entries may downgrade secure to non-secure, but

     * cannot upgrade an non-secure translation regime's attributes

     * to secure.

     */

    attrs->secure = regime_is_secure(env, mmu_idx);

    attrs->user = regime_is_user(env, mmu_idx);



    /* Fast Context Switch Extension. This doesn't exist at all in v8.

     * In v7 and earlier it affects all stage 1 translations.

     */

    if (address < 0x02000000 && mmu_idx != ARMMMUIdx_S2NS

        && !arm_feature(env, ARM_FEATURE_V8)) {

        if (regime_el(env, mmu_idx) == 3) {

            address += env->cp15.fcseidr_s;

        } else {

            address += env->cp15.fcseidr_ns;

        }

    }



    /* pmsav7 has special handling for when MPU is disabled so call it before

     * the common MMU/MPU disabled check below.

     */

    if (arm_feature(env, ARM_FEATURE_PMSA) &&

        arm_feature(env, ARM_FEATURE_V7)) {

        bool ret;

        *page_size = TARGET_PAGE_SIZE;

        ret = get_phys_addr_pmsav7(env, address, access_type, mmu_idx,

                                   phys_ptr, prot, fsr);

        qemu_log_mask(CPU_LOG_MMU, "PMSAv7 MPU lookup for %s at 0x%08" PRIx32

                      " mmu_idx %u -> %s (prot %c%c%c)\n",

                      access_type == 1 ? "reading" :

                      (access_type == 2 ? "writing" : "execute"),

                      (uint32_t)address, mmu_idx,

                      ret ? "Miss" : "Hit",

                      *prot & PAGE_READ ? 'r' : '-',

                      *prot & PAGE_WRITE ? 'w' : '-',

                      *prot & PAGE_EXEC ? 'x' : '-');



        return ret;

    }



    if (regime_translation_disabled(env, mmu_idx)) {

        /* MMU/MPU disabled.  */

        *phys_ptr = address;

        *prot = PAGE_READ | PAGE_WRITE | PAGE_EXEC;

        *page_size = TARGET_PAGE_SIZE;

        return 0;

    }



    if (arm_feature(env, ARM_FEATURE_PMSA)) {

        /* Pre-v7 MPU */

        *page_size = TARGET_PAGE_SIZE;

        return get_phys_addr_pmsav5(env, address, access_type, mmu_idx,

                                    phys_ptr, prot, fsr);

    }



    if (regime_using_lpae_format(env, mmu_idx)) {

        return get_phys_addr_lpae(env, address, access_type, mmu_idx, phys_ptr,

                                  attrs, prot, page_size, fsr, fi);

    } else if (regime_sctlr(env, mmu_idx) & SCTLR_XP) {

        return get_phys_addr_v6(env, address, access_type, mmu_idx, phys_ptr,

                                attrs, prot, page_size, fsr, fi);

    } else {

        return get_phys_addr_v5(env, address, access_type, mmu_idx, phys_ptr,

                                prot, page_size, fsr, fi);

    }

}

static void set_sensor_evt_enable(IPMIBmcSim *ibs,

                                  uint8_t *cmd, unsigned int cmd_len,

                                  uint8_t *rsp, unsigned int *rsp_len,

                                  unsigned int max_rsp_len)

{

    IPMISensor *sens;



    IPMI_CHECK_CMD_LEN(4);

    if ((cmd[2] > MAX_SENSORS) ||

            !IPMI_SENSOR_GET_PRESENT(ibs->sensors + cmd[2])) {

        rsp[2] = IPMI_CC_REQ_ENTRY_NOT_PRESENT;

        return;

    }

    sens = ibs->sensors + cmd[2];

    switch ((cmd[3] >> 4) & 0x3) {

    case 0: /* Do not change */

        break;

    case 1: /* Enable bits */

        if (cmd_len > 4) {

            sens->assert_enable |= cmd[4];

        }

        if (cmd_len > 5) {

            sens->assert_enable |= cmd[5] << 8;

        }

        if (cmd_len > 6) {

            sens->deassert_enable |= cmd[6];

        }

        if (cmd_len > 7) {

            sens->deassert_enable |= cmd[7] << 8;

        }

        break;

    case 2: /* Disable bits */

        if (cmd_len > 4) {

            sens->assert_enable &= ~cmd[4];

        }

        if (cmd_len > 5) {

            sens->assert_enable &= ~(cmd[5] << 8);

        }

        if (cmd_len > 6) {

            sens->deassert_enable &= ~cmd[6];

        }

        if (cmd_len > 7) {

            sens->deassert_enable &= ~(cmd[7] << 8);

        }

        break;

    case 3:

        rsp[2] = IPMI_CC_INVALID_DATA_FIELD;

        return;

    }

    IPMI_SENSOR_SET_RET_STATUS(sens, cmd[3]);

}

static void get_default_channel_layouts(OutputStream *ost, InputStream *ist)

{

    char layout_name[256];

    AVCodecContext *enc = ost->st->codec;

    AVCodecContext *dec = ist->st->codec;



    if (!dec->channel_layout) {

        if (enc->channel_layout && dec->channels == enc->channels) {

            dec->channel_layout = enc->channel_layout;

        } else {

            dec->channel_layout = av_get_default_channel_layout(dec->channels);



            if (!dec->channel_layout) {

                av_log(NULL, AV_LOG_FATAL, "Unable to find default channel "

                       "layout for Input Stream #%d.%d\n", ist->file_index,

                       ist->st->index);

                exit_program(1);

            }

        }

        av_get_channel_layout_string(layout_name, sizeof(layout_name),

                                     dec->channels, dec->channel_layout);

        av_log(NULL, AV_LOG_WARNING, "Guessed Channel Layout for  Input Stream "

               "#%d.%d : %s\n", ist->file_index, ist->st->index, layout_name);

    }

    if (!enc->channel_layout) {

        if (dec->channels == enc->channels) {

            enc->channel_layout = dec->channel_layout;

            return;

        } else {

            enc->channel_layout = av_get_default_channel_layout(enc->channels);

        }

        if (!enc->channel_layout) {

            av_log(NULL, AV_LOG_FATAL, "Unable to find default channel layout "

                   "for Output Stream #%d.%d\n", ost->file_index,

                   ost->st->index);

            exit_program(1);

        }

        av_get_channel_layout_string(layout_name, sizeof(layout_name),

                                     enc->channels, enc->channel_layout);

        av_log(NULL, AV_LOG_WARNING, "Guessed Channel Layout for Output Stream "

               "#%d.%d : %s\n", ost->file_index, ost->st->index, layout_name);

    }

}

static void realview_init(ram_addr_t ram_size, int vga_ram_size,

                     const char *boot_device, DisplayState *ds,

                     const char *kernel_filename, const char *kernel_cmdline,

                     const char *initrd_filename, const char *cpu_model)

{

    CPUState *env;

    qemu_irq *pic;

    void *scsi_hba;

    PCIBus *pci_bus;

    NICInfo *nd;

    int n;

    int done_smc = 0;

    qemu_irq cpu_irq[4];

    int ncpu;

    int index;



    if (!cpu_model)

        cpu_model = "arm926";

    /* FIXME: obey smp_cpus.  */

    if (strcmp(cpu_model, "arm11mpcore") == 0) {

        ncpu = 4;

    } else {

        ncpu = 1;

    }



    for (n = 0; n < ncpu; n++) {

        env = cpu_init(cpu_model);

        if (!env) {

            fprintf(stderr, "Unable to find CPU definition\n");

            exit(1);

        }

        pic = arm_pic_init_cpu(env);

        cpu_irq[n] = pic[ARM_PIC_CPU_IRQ];

        if (n > 0) {

            /* Set entry point for secondary CPUs.  This assumes we're using

               the init code from arm_boot.c.  Real hardware resets all CPUs

               the same.  */

            env->regs[15] = 0x80000000;

        }

    }



    /* ??? RAM should repeat to fill physical memory space.  */

    /* SDRAM at address zero.  */

    cpu_register_physical_memory(0, ram_size, IO_MEM_RAM);



    arm_sysctl_init(0x10000000, 0xc1400400);



    if (ncpu == 1) {

        /* ??? The documentation says GIC1 is nFIQ and either GIC2 or GIC3

           is nIRQ (there are inconsistencies).  However Linux 2.6.17 expects

           GIC1 to be nIRQ and ignores all the others, so do that for now.  */

        pic = realview_gic_init(0x10040000, cpu_irq[0]);

    } else {

        pic = mpcore_irq_init(cpu_irq);

    }



    pl050_init(0x10006000, pic[20], 0);

    pl050_init(0x10007000, pic[21], 1);



    pl011_init(0x10009000, pic[12], serial_hds[0], PL011_ARM);

    pl011_init(0x1000a000, pic[13], serial_hds[1], PL011_ARM);

    pl011_init(0x1000b000, pic[14], serial_hds[2], PL011_ARM);

    pl011_init(0x1000c000, pic[15], serial_hds[3], PL011_ARM);



    /* DMA controller is optional, apparently.  */

    pl080_init(0x10030000, pic[24], 2);



    sp804_init(0x10011000, pic[4]);

    sp804_init(0x10012000, pic[5]);



    pl110_init(ds, 0x10020000, pic[23], 1);



    index = drive_get_index(IF_SD, 0, 0);

    if (index == -1) {

        fprintf(stderr, "qemu: missing SecureDigital card\n");

        exit(1);

    }

    pl181_init(0x10005000, drives_table[index].bdrv, pic[17], pic[18]);



    pl031_init(0x10017000, pic[10]);



    pci_bus = pci_vpb_init(pic, 48, 1);

    if (usb_enabled) {

        usb_ohci_init_pci(pci_bus, 3, -1);

    }

    if (drive_get_max_bus(IF_SCSI) > 0) {

        fprintf(stderr, "qemu: too many SCSI bus\n");

        exit(1);

    }

    scsi_hba = lsi_scsi_init(pci_bus, -1);

    for (n = 0; n < LSI_MAX_DEVS; n++) {

        index = drive_get_index(IF_SCSI, 0, n);

        if (index == -1)

            continue;

        lsi_scsi_attach(scsi_hba, drives_table[index].bdrv, n);

    }

    for(n = 0; n < nb_nics; n++) {

        nd = &nd_table[n];

        if (!nd->model)

            nd->model = done_smc ? "rtl8139" : "smc91c111";

        if (strcmp(nd->model, "smc91c111") == 0) {

            smc91c111_init(nd, 0x4e000000, pic[28]);

        } else {

            pci_nic_init(pci_bus, nd, -1);

        }

    }



    /* Memory map for RealView Emulation Baseboard:  */

    /* 0x10000000 System registers.  */

    /*  0x10001000 System controller.  */

    /*  0x10002000 Two-Wire Serial Bus.  */

    /* 0x10003000 Reserved.  */

    /*  0x10004000 AACI.  */

    /*  0x10005000 MCI.  */

    /* 0x10006000 KMI0.  */

    /* 0x10007000 KMI1.  */

    /*  0x10008000 Character LCD.  */

    /* 0x10009000 UART0.  */

    /* 0x1000a000 UART1.  */

    /* 0x1000b000 UART2.  */

    /* 0x1000c000 UART3.  */

    /*  0x1000d000 SSPI.  */

    /*  0x1000e000 SCI.  */

    /* 0x1000f000 Reserved.  */

    /*  0x10010000 Watchdog.  */

    /* 0x10011000 Timer 0+1.  */

    /* 0x10012000 Timer 2+3.  */

    /*  0x10013000 GPIO 0.  */

    /*  0x10014000 GPIO 1.  */

    /*  0x10015000 GPIO 2.  */

    /* 0x10016000 Reserved.  */

    /* 0x10017000 RTC.  */

    /*  0x10018000 DMC.  */

    /*  0x10019000 PCI controller config.  */

    /*  0x10020000 CLCD.  */

    /* 0x10030000 DMA Controller.  */

    /* 0x10040000 GIC1.  */

    /* 0x10050000 GIC2.  */

    /* 0x10060000 GIC3.  */

    /* 0x10070000 GIC4.  */

    /*  0x10080000 SMC.  */

    /*  0x40000000 NOR flash.  */

    /*  0x44000000 DoC flash.  */

    /*  0x48000000 SRAM.  */

    /*  0x4c000000 Configuration flash.  */

    /* 0x4e000000 Ethernet.  */

    /*  0x4f000000 USB.  */

    /*  0x50000000 PISMO.  */

    /*  0x54000000 PISMO.  */

    /*  0x58000000 PISMO.  */

    /*  0x5c000000 PISMO.  */

    /* 0x60000000 PCI.  */

    /* 0x61000000 PCI Self Config.  */

    /* 0x62000000 PCI Config.  */

    /* 0x63000000 PCI IO.  */

    /* 0x64000000 PCI mem 0.  */

    /* 0x68000000 PCI mem 1.  */

    /* 0x6c000000 PCI mem 2.  */



    realview_binfo.ram_size = ram_size;

    realview_binfo.kernel_filename = kernel_filename;

    realview_binfo.kernel_cmdline = kernel_cmdline;

    realview_binfo.initrd_filename = initrd_filename;

    realview_binfo.nb_cpus = ncpu;

    arm_load_kernel(first_cpu, &realview_binfo);



    /* ??? Hack to map an additional page of ram for the secondary CPU

       startup code.  I guess this works on real hardware because the

       BootROM happens to be in ROM/flash or in memory that isn't clobbered

       until after Linux boots the secondary CPUs.  */

    cpu_register_physical_memory(0x80000000, 0x1000, IO_MEM_RAM + ram_size);

}

static int asf_write_header1(AVFormatContext *s, int64_t file_size, int64_t data_chunk_size)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVDictionaryEntry *tags[5];

    int header_size, n, extra_size, extra_size2, wav_extra_size, file_time;

    int has_title;

    int metadata_count;

    AVCodecContext *enc;

    int64_t header_offset, cur_pos, hpos;

    int bit_rate;

    int64_t duration;



    ff_metadata_conv(&s->metadata, ff_asf_metadata_conv, NULL);



    tags[0] = av_dict_get(s->metadata, "title"    , NULL, 0);

    tags[1] = av_dict_get(s->metadata, "author"   , NULL, 0);

    tags[2] = av_dict_get(s->metadata, "copyright", NULL, 0);

    tags[3] = av_dict_get(s->metadata, "comment"  , NULL, 0);

    tags[4] = av_dict_get(s->metadata, "rating"   , NULL, 0);



    duration = asf->duration + PREROLL_TIME * 10000;

    has_title = tags[0] || tags[1] || tags[2] || tags[3] || tags[4];

    metadata_count = s->metadata ? s->metadata->count : 0;



    bit_rate = 0;

    for(n=0;n<s->nb_streams;n++) {

        enc = s->streams[n]->codec;



        av_set_pts_info(s->streams[n], 32, 1, 1000); /* 32 bit pts in ms */



        bit_rate += enc->bit_rate;

    }



    if (asf->is_streamed) {

        put_chunk(s, 0x4824, 0, 0xc00); /* start of stream (length will be patched later) */

    }



    put_guid(pb, &ff_asf_header);

    avio_wl64(pb, -1); /* header length, will be patched after */

    avio_wl32(pb, 3 + has_title + !!metadata_count + s->nb_streams); /* number of chunks in header */

    avio_w8(pb, 1); /* ??? */

    avio_w8(pb, 2); /* ??? */



    /* file header */

    header_offset = avio_tell(pb);

    hpos = put_header(pb, &ff_asf_file_header);

    put_guid(pb, &ff_asf_my_guid);

    avio_wl64(pb, file_size);

    file_time = 0;

    avio_wl64(pb, unix_to_file_time(file_time));

    avio_wl64(pb, asf->nb_packets); /* number of packets */

    avio_wl64(pb, duration); /* end time stamp (in 100ns units) */

    avio_wl64(pb, asf->duration); /* duration (in 100ns units) */

    avio_wl64(pb, PREROLL_TIME); /* start time stamp */

    avio_wl32(pb, (asf->is_streamed || !pb->seekable ) ? 3 : 2); /* ??? */

    avio_wl32(pb, s->packet_size); /* packet size */

    avio_wl32(pb, s->packet_size); /* packet size */

    avio_wl32(pb, bit_rate); /* Nominal data rate in bps */

    end_header(pb, hpos);



    /* unknown headers */

    hpos = put_header(pb, &ff_asf_head1_guid);

    put_guid(pb, &ff_asf_head2_guid);

    avio_wl32(pb, 6);

    avio_wl16(pb, 0);

    end_header(pb, hpos);



    /* title and other infos */

    if (has_title) {

        int len;

        uint8_t *buf;

        AVIOContext *dyn_buf;



        if (avio_open_dyn_buf(&dyn_buf) < 0)

            return AVERROR(ENOMEM);



        hpos = put_header(pb, &ff_asf_comment_header);



        for (n = 0; n < FF_ARRAY_ELEMS(tags); n++) {

            len = tags[n] ? avio_put_str16le(dyn_buf, tags[n]->value) : 0;

            avio_wl16(pb, len);

        }

        len = avio_close_dyn_buf(dyn_buf, &buf);

        avio_write(pb, buf, len);

        av_freep(&buf);

        end_header(pb, hpos);

    }

    if (metadata_count) {

        AVDictionaryEntry *tag = NULL;

        hpos = put_header(pb, &ff_asf_extended_content_header);

        avio_wl16(pb, metadata_count);

        while ((tag = av_dict_get(s->metadata, "", tag, AV_DICT_IGNORE_SUFFIX))) {

            put_str16(pb, tag->key);

            avio_wl16(pb, 0);

            put_str16(pb, tag->value);

        }

        end_header(pb, hpos);

    }



    /* stream headers */

    for(n=0;n<s->nb_streams;n++) {

        int64_t es_pos;

        //        ASFStream *stream = &asf->streams[n];



        enc = s->streams[n]->codec;

        asf->streams[n].num = n + 1;

        asf->streams[n].seq = 0;





        switch(enc->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            wav_extra_size = 0;

            extra_size = 18 + wav_extra_size;

            extra_size2 = 8;

            break;

        default:

        case AVMEDIA_TYPE_VIDEO:

            wav_extra_size = enc->extradata_size;

            extra_size = 0x33 + wav_extra_size;

            extra_size2 = 0;

            break;

        }



        hpos = put_header(pb, &ff_asf_stream_header);

        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            put_guid(pb, &ff_asf_audio_stream);

            put_guid(pb, &ff_asf_audio_conceal_spread);

        } else {

            put_guid(pb, &ff_asf_video_stream);

            put_guid(pb, &ff_asf_video_conceal_none);

        }

        avio_wl64(pb, 0); /* ??? */

        es_pos = avio_tell(pb);

        avio_wl32(pb, extra_size); /* wav header len */

        avio_wl32(pb, extra_size2); /* additional data len */

        avio_wl16(pb, n + 1); /* stream number */

        avio_wl32(pb, 0); /* ??? */



        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            /* WAVEFORMATEX header */

            int wavsize = ff_put_wav_header(pb, enc);

            if ((enc->codec_id != CODEC_ID_MP3) && (enc->codec_id != CODEC_ID_MP2) && (enc->codec_id != CODEC_ID_ADPCM_IMA_WAV) && (enc->extradata_size==0)) {

                wavsize += 2;

                avio_wl16(pb, 0);

            }



            if (wavsize < 0)

                return -1;

            if (wavsize != extra_size) {

                cur_pos = avio_tell(pb);

                avio_seek(pb, es_pos, SEEK_SET);

                avio_wl32(pb, wavsize); /* wav header len */

                avio_seek(pb, cur_pos, SEEK_SET);

            }

            /* ERROR Correction */

            avio_w8(pb, 0x01);

            if(enc->codec_id == CODEC_ID_ADPCM_G726 || !enc->block_align){

                avio_wl16(pb, 0x0190);

                avio_wl16(pb, 0x0190);

            }else{

                avio_wl16(pb, enc->block_align);

                avio_wl16(pb, enc->block_align);

            }

            avio_wl16(pb, 0x01);

            avio_w8(pb, 0x00);

        } else {

            avio_wl32(pb, enc->width);

            avio_wl32(pb, enc->height);

            avio_w8(pb, 2); /* ??? */

            avio_wl16(pb, 40 + enc->extradata_size); /* size */



            /* BITMAPINFOHEADER header */

            ff_put_bmp_header(pb, enc, ff_codec_bmp_tags, 1);

        }

        end_header(pb, hpos);

    }



    /* media comments */



    hpos = put_header(pb, &ff_asf_codec_comment_header);

    put_guid(pb, &ff_asf_codec_comment1_header);

    avio_wl32(pb, s->nb_streams);

    for(n=0;n<s->nb_streams;n++) {

        AVCodec *p;

        const char *desc;

        int len;

        uint8_t *buf;

        AVIOContext *dyn_buf;



        enc = s->streams[n]->codec;

        p = avcodec_find_encoder(enc->codec_id);



        if(enc->codec_type == AVMEDIA_TYPE_AUDIO)

            avio_wl16(pb, 2);

        else if(enc->codec_type == AVMEDIA_TYPE_VIDEO)

            avio_wl16(pb, 1);

        else

            avio_wl16(pb, -1);



        if(enc->codec_id == CODEC_ID_WMAV2)

            desc = "Windows Media Audio V8";

        else

            desc = p ? p->name : enc->codec_name;



        if ( avio_open_dyn_buf(&dyn_buf) < 0)

            return AVERROR(ENOMEM);



        avio_put_str16le(dyn_buf, desc);

        len = avio_close_dyn_buf(dyn_buf, &buf);

        avio_wl16(pb, len / 2); // "number of characters" = length in bytes / 2



        avio_write(pb, buf, len);

        av_freep(&buf);



        avio_wl16(pb, 0); /* no parameters */





        /* id */

        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            avio_wl16(pb, 2);

            avio_wl16(pb, enc->codec_tag);

        } else {

            avio_wl16(pb, 4);

            avio_wl32(pb, enc->codec_tag);

        }

        if(!enc->codec_tag)

            return -1;

    }

    end_header(pb, hpos);



    /* patch the header size fields */



    cur_pos = avio_tell(pb);

    header_size = cur_pos - header_offset;

    if (asf->is_streamed) {

        header_size += 8 + 30 + 50;



        avio_seek(pb, header_offset - 10 - 30, SEEK_SET);

        avio_wl16(pb, header_size);

        avio_seek(pb, header_offset - 2 - 30, SEEK_SET);

        avio_wl16(pb, header_size);



        header_size -= 8 + 30 + 50;

    }

    header_size += 24 + 6;

    avio_seek(pb, header_offset - 14, SEEK_SET);

    avio_wl64(pb, header_size);

    avio_seek(pb, cur_pos, SEEK_SET);



    /* movie chunk, followed by packets of packet_size */

    asf->data_offset = cur_pos;

    put_guid(pb, &ff_asf_data_header);

    avio_wl64(pb, data_chunk_size);

    put_guid(pb, &ff_asf_my_guid);

    avio_wl64(pb, asf->nb_packets); /* nb packets */

    avio_w8(pb, 1); /* ??? */

    avio_w8(pb, 1); /* ??? */

    return 0;

}

