        p_name += cid_str_size;

        sscanf(p_name, "%x", &cid);

    }



    return cid;

}

static int dc1394_read_header(AVFormatContext *c, AVFormatParameters * ap)

{

    dc1394_data* dc1394 = c->priv_data;

    AVStream* vst;

    nodeid_t* camera_nodes;

    int res;

    struct dc1394_frame_format *fmt;

    struct dc1394_frame_rate *fps;



    for (fmt = dc1394_frame_formats; fmt->width; fmt++)

         if (fmt->pix_fmt == ap->pix_fmt && fmt->width == ap->width && fmt->height == ap->height)

             break;



    for (fps = dc1394_frame_rates; fps->frame_rate; fps++)

         if (fps->frame_rate == av_rescale(1000, ap->time_base.den, ap->time_base.num))

             break;



    /* create a video stream */

    vst = av_new_stream(c, 0);

    if (!vst)

        return -1;

    av_set_pts_info(vst, 64, 1, 1000);

    vst->codec->codec_type = CODEC_TYPE_VIDEO;

    vst->codec->codec_id = CODEC_ID_RAWVIDEO;

    vst->codec->time_base.den = fps->frame_rate;

    vst->codec->time_base.num = 1000;

    vst->codec->width = fmt->width;

    vst->codec->height = fmt->height;

    vst->codec->pix_fmt = fmt->pix_fmt;



    /* packet init */

    av_init_packet(&dc1394->packet);

    dc1394->packet.size = avpicture_get_size(fmt->pix_fmt, fmt->width, fmt->height);

    dc1394->packet.stream_index = vst->index;

    dc1394->packet.flags |= PKT_FLAG_KEY;



    dc1394->current_frame = 0;

    dc1394->fps = fps->frame_rate;



    vst->codec->bit_rate = av_rescale(dc1394->packet.size * 8, fps->frame_rate, 1000);



    /* Now lets prep the hardware */

    dc1394->handle = dc1394_create_handle(0); /* FIXME: gotta have ap->port */

    if (!dc1394->handle) {

        av_log(c, AV_LOG_ERROR, "Can't acquire dc1394 handle on port %d\n", 0 /* ap->port */);

        goto out;

    }

    camera_nodes = dc1394_get_camera_nodes(dc1394->handle, &res, 1);

    if (!camera_nodes || camera_nodes[ap->channel] == DC1394_NO_CAMERA) {

        av_log(c, AV_LOG_ERROR, "There's no IIDC camera on the channel %d\n", ap->channel);

        goto out_handle;

    }

    res = dc1394_dma_setup_capture(dc1394->handle, camera_nodes[ap->channel],

                                   0,

                                   FORMAT_VGA_NONCOMPRESSED,

                                   fmt->frame_size_id,

                                   SPEED_400,

                                   fps->frame_rate_id, 8, 1,

                                   c->filename,

                                   &dc1394->camera);

    dc1394_free_camera_nodes(camera_nodes);

    if (res != DC1394_SUCCESS) {

        av_log(c, AV_LOG_ERROR, "Can't prepare camera for the DMA capture\n");

        goto out_handle;

    }



    res = dc1394_start_iso_transmission(dc1394->handle, dc1394->camera.node);

    if (res != DC1394_SUCCESS) {

        av_log(c, AV_LOG_ERROR, "Can't start isochronous transmission\n");

        goto out_handle_dma;

    }



    return 0;



out_handle_dma:

    dc1394_dma_unlisten(dc1394->handle, &dc1394->camera);

    dc1394_dma_release_camera(dc1394->handle, &dc1394->camera);

out_handle:

    dc1394_destroy_handle(dc1394->handle);

out:

    return -1;

}

int vc1_decode_entry_point(AVCodecContext *avctx, VC1Context *v, GetBitContext *gb)

{

    int i;



    av_log(avctx, AV_LOG_DEBUG, "Entry point: %08X\n", show_bits_long(gb, 32));

    v->broken_link = get_bits1(gb);

    v->closed_entry = get_bits1(gb);

    v->panscanflag = get_bits1(gb);

    v->refdist_flag = get_bits1(gb);

    v->s.loop_filter = get_bits1(gb);

    v->fastuvmc = get_bits1(gb);

    v->extended_mv = get_bits1(gb);

    v->dquant = get_bits(gb, 2);

    v->vstransform = get_bits1(gb);

    v->overlap = get_bits1(gb);

    v->quantizer_mode = get_bits(gb, 2);



    if(v->hrd_param_flag){

        for(i = 0; i < v->hrd_num_leaky_buckets; i++) {

            skip_bits(gb, 8); //hrd_full[n]

        }

    }



    if(get_bits1(gb)){

        avctx->coded_width = (get_bits(gb, 12)+1)<<1;

        avctx->coded_height = (get_bits(gb, 12)+1)<<1;

    }

    if(v->extended_mv)

        v->extended_dmv = get_bits1(gb);

    if((v->range_mapy_flag = get_bits1(gb))) {

        av_log(avctx, AV_LOG_ERROR, "Luma scaling is not supported, expect wrong picture\n");

        v->range_mapy = get_bits(gb, 3);

    }

    if((v->range_mapuv_flag = get_bits1(gb))) {

        av_log(avctx, AV_LOG_ERROR, "Chroma scaling is not supported, expect wrong picture\n");

        v->range_mapuv = get_bits(gb, 3);

    }



    av_log(avctx, AV_LOG_DEBUG, "Entry point info:\n"

        "BrokenLink=%i, ClosedEntry=%i, PanscanFlag=%i\n"

        "RefDist=%i, Postproc=%i, FastUVMC=%i, ExtMV=%i\n"

        "DQuant=%i, VSTransform=%i, Overlap=%i, Qmode=%i\n",

        v->broken_link, v->closed_entry, v->panscanflag, v->refdist_flag, v->s.loop_filter,

        v->fastuvmc, v->extended_mv, v->dquant, v->vstransform, v->overlap, v->quantizer_mode);



    return 0;

}

static inline void ls_decode_line(JLSState *state, MJpegDecodeContext *s,
                                  void *last, void *dst, int last2, int w,
                                  int stride, int comp, int bits)
{
    int i, x = 0;
    int Ra, Rb, Rc, Rd;
    int D0, D1, D2;
    while (x < w) {
        int err, pred;
        /* compute gradients */
        Ra = x ? R(dst, x - stride) : R(last, x);
        Rb = R(last, x);
        Rc = x ? R(last, x - stride) : last2;
        Rd = (x >= w - stride) ? R(last, x) : R(last, x + stride);
        D0 = Rd - Rb;
        D1 = Rb - Rc;
        D2 = Rc - Ra;
        /* run mode */
        if ((FFABS(D0) <= state->near) &&
            (FFABS(D1) <= state->near) &&
            (FFABS(D2) <= state->near)) {
            int r;
            int RItype;
            /* decode full runs while available */
            while (get_bits1(&s->gb)) {
                int r;
                r = 1 << ff_log2_run[state->run_index[comp]];
                if (x + r * stride > w)
                    r = (w - x) / stride;
                for (i = 0; i < r; i++) {
                    W(dst, x, Ra);
                    x += stride;
                }
                /* if EOL reached, we stop decoding */
                if (r != 1 << ff_log2_run[state->run_index[comp]])
                if (state->run_index[comp] < 31)
                    state->run_index[comp]++;
                if (x + stride > w)
            }
            /* decode aborted run */
            r = ff_log2_run[state->run_index[comp]];
            if (r)
                r = get_bits_long(&s->gb, r);
            if (x + r * stride > w) {
                r = (w - x) / stride;
            }
            for (i = 0; i < r; i++) {
                W(dst, x, Ra);
                x += stride;
            }
            if (x >= w) {
                av_log(NULL, AV_LOG_ERROR, "run overflow\n");
                av_assert0(x <= w);
            }
            /* decode run termination value */
            Rb     = R(last, x);
            RItype = (FFABS(Ra - Rb) <= state->near) ? 1 : 0;
            err    = ls_get_code_runterm(&s->gb, state, RItype,
                                         ff_log2_run[state->run_index[comp]]);
            if (state->run_index[comp])
                state->run_index[comp]--;
            if (state->near && RItype) {
                pred = Ra + err;
            } else {
                if (Rb < Ra)
                    pred = Rb - err;
                else
                    pred = Rb + err;
            }
        } else { /* regular mode */
            int context, sign;
            context = ff_jpegls_quantize(state, D0) * 81 +
                      ff_jpegls_quantize(state, D1) *  9 +
                      ff_jpegls_quantize(state, D2);
            pred    = mid_pred(Ra, Ra + Rb - Rc, Rb);
            if (context < 0) {
                context = -context;
                sign    = 1;
            } else {
                sign = 0;
            }
            if (sign) {
                pred = av_clip(pred - state->C[context], 0, state->maxval);
                err  = -ls_get_code_regular(&s->gb, state, context);
            } else {
                pred = av_clip(pred + state->C[context], 0, state->maxval);
                err  = ls_get_code_regular(&s->gb, state, context);
            }
            /* we have to do something more for near-lossless coding */
            pred += err;
        }
        if (state->near) {
            if (pred < -state->near)
                pred += state->range * state->twonear;
            else if (pred > state->maxval + state->near)
                pred -= state->range * state->twonear;
            pred = av_clip(pred, 0, state->maxval);
        }
        pred &= state->maxval;
        W(dst, x, pred);
        x += stride;
    }
}

static ram_addr_t get_current_ram_size(void)

{

    GSList *list = NULL, *item;

    ram_addr_t size = ram_size;



    pc_dimm_build_list(qdev_get_machine(), &list);

    for (item = list; item; item = g_slist_next(item)) {

        Object *obj = OBJECT(item->data);

        size += object_property_get_int(obj, PC_DIMM_SIZE_PROP, &error_abort);

    }

    g_slist_free(list);



    return size;

}

BlockDriverAIOCB *bdrv_aio_write(BlockDriverState *bs, int64_t sector_num,

                                 const uint8_t *buf, int nb_sectors,

                                 BlockDriverCompletionFunc *cb, void *opaque)

{

    BlockDriver *drv = bs->drv;

    BlockDriverAIOCB *ret;



    if (!drv)

        return NULL;

    if (bs->read_only)

        return NULL;

    if (sector_num == 0 && bs->boot_sector_enabled && nb_sectors > 0) {

        memcpy(bs->boot_sector_data, buf, 512);

    }



    ret = drv->bdrv_aio_write(bs, sector_num, buf, nb_sectors, cb, opaque);



    if (ret) {

	/* Update stats even though technically transfer has not happened. */

	bs->wr_bytes += (unsigned) nb_sectors * SECTOR_SIZE;

	bs->wr_ops ++;

    }



    return ret;

}

static void scsi_write_data(SCSIRequest *req)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    SCSIDiskClass *sdc = (SCSIDiskClass *) object_get_class(OBJECT(s));



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    /* The request is used as the AIO opaque value, so add a ref.  */

    scsi_req_ref(&r->req);

    if (r->req.cmd.mode != SCSI_XFER_TO_DEV) {

        DPRINTF("Data transfer direction invalid\n");

        scsi_write_complete_noio(r, -EINVAL);

        return;

    }



    if (!r->req.sg && !r->qiov.size) {

        /* Called for the first time.  Ask the driver to send us more data.  */

        r->started = true;

        scsi_write_complete_noio(r, 0);

        return;

    }

    if (s->tray_open) {

        scsi_write_complete_noio(r, -ENOMEDIUM);

        return;

    }



    if (r->req.cmd.buf[0] == VERIFY_10 || r->req.cmd.buf[0] == VERIFY_12 ||

        r->req.cmd.buf[0] == VERIFY_16) {

        if (r->req.sg) {

            scsi_dma_complete_noio(r, 0);

        } else {

            scsi_write_complete_noio(r, 0);

        }

        return;

    }



    if (r->req.sg) {

        dma_acct_start(s->qdev.conf.blk, &r->acct, r->req.sg, BLOCK_ACCT_WRITE);

        r->req.resid -= r->req.sg->size;

        r->req.aiocb = dma_blk_io(blk_get_aio_context(s->qdev.conf.blk),

                                  r->req.sg, r->sector << BDRV_SECTOR_BITS,

                                  sdc->dma_writev, r, scsi_dma_complete, r,

                                  DMA_DIRECTION_TO_DEVICE);

    } else {

        block_acct_start(blk_get_stats(s->qdev.conf.blk), &r->acct,

                         r->qiov.size, BLOCK_ACCT_WRITE);

        r->req.aiocb = sdc->dma_writev(r->sector << BDRV_SECTOR_BITS, &r->qiov,

                                       scsi_write_complete, r, r);

    }

}

