static SoftFloat sbr_sum_square_c(int (*x)[2], int n)

{

    SoftFloat ret;

    uint64_t accu = 0, round;

    int i, nz;

    unsigned u;



    for (i = 0; i < n; i += 2) {

        // Larger values are inavlid and could cause overflows of accu.

        av_assert2(FFABS(x[i + 0][0]) >> 29 == 0);

        accu += (int64_t)x[i + 0][0] * x[i + 0][0];

        av_assert2(FFABS(x[i + 0][1]) >> 29 == 0);

        accu += (int64_t)x[i + 0][1] * x[i + 0][1];

        av_assert2(FFABS(x[i + 1][0]) >> 29 == 0);

        accu += (int64_t)x[i + 1][0] * x[i + 1][0];

        av_assert2(FFABS(x[i + 1][1]) >> 29 == 0);

        accu += (int64_t)x[i + 1][1] * x[i + 1][1];

    }



    u = accu >> 32;

    if (u == 0) {

        nz = 1;

    } else {

        nz = -1;

        while (u < 0x80000000U) {

            u <<= 1;

            nz++;

        }

        nz = 32 - nz;

    }



    round = 1ULL << (nz-1);

    u = ((accu + round) >> nz);

    u >>= 1;

    ret = av_int2sf(u, 15 - nz);



    return ret;

}

static void test_mirror(void)

{

    int send_sock[2], recv_sock;

    char *cmdline;

    uint32_t ret = 0, len = 0;

    char send_buf[] = "Hello! filter-mirror~";

    char sock_path[] = "filter-mirror.XXXXXX";

    char *recv_buf;

    uint32_t size = sizeof(send_buf);

    size = htonl(size);



    ret = socketpair(PF_UNIX, SOCK_STREAM, 0, send_sock);

    g_assert_cmpint(ret, !=, -1);



    ret = mkstemp(sock_path);

    g_assert_cmpint(ret, !=, -1);



    cmdline = g_strdup_printf("-netdev socket,id=qtest-bn0,fd=%d "

                 "-device e1000,netdev=qtest-bn0,id=qtest-e0 "

                 "-chardev socket,id=mirror0,path=%s,server,nowait "

                 "-object filter-mirror,id=qtest-f0,netdev=qtest-bn0,queue=tx,outdev=mirror0 "

                 , send_sock[1], sock_path);

    qtest_start(cmdline);

    g_free(cmdline);



    recv_sock = unix_connect(sock_path, NULL);

    g_assert_cmpint(recv_sock, !=, -1);



    struct iovec iov[] = {

        {

            .iov_base = &size,

            .iov_len = sizeof(size),

        }, {

            .iov_base = send_buf,

            .iov_len = sizeof(send_buf),

        },

    };



    /* send a qmp command to guarantee that 'connected' is setting to true. */

    qmp_discard_response("{ 'execute' : 'query-status'}");

    ret = iov_send(send_sock[0], iov, 2, 0, sizeof(size) + sizeof(send_buf));

    g_assert_cmpint(ret, ==, sizeof(send_buf) + sizeof(size));

    close(send_sock[0]);



    ret = qemu_recv(recv_sock, &len, sizeof(len), 0);

    g_assert_cmpint(ret, ==, sizeof(len));

    len = ntohl(len);



    g_assert_cmpint(len, ==, sizeof(send_buf));

    recv_buf = g_malloc(len);

    ret = qemu_recv(recv_sock, recv_buf, len, 0);

    g_assert_cmpstr(recv_buf, ==, send_buf);



    g_free(recv_buf);

    close(recv_sock);

    unlink(sock_path);

}

static int decode_tile(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile)

{

    int compno, reslevelno, bandno;

    int x, y;

    uint8_t *line;

    Jpeg2000T1Context t1;



    /* Loop on tile components */

    for (compno = 0; compno < s->ncomponents; compno++) {

        Jpeg2000Component *comp     = tile->comp + compno;

        Jpeg2000CodingStyle *codsty = tile->codsty + compno;



        /* Loop on resolution levels */

        for (reslevelno = 0; reslevelno < codsty->nreslevels2decode; reslevelno++) {

            Jpeg2000ResLevel *rlevel = comp->reslevel + reslevelno;

            /* Loop on bands */

            for (bandno = 0; bandno < rlevel->nbands; bandno++) {

                int nb_precincts, precno;

                Jpeg2000Band *band = rlevel->band + bandno;

                int cblkno=0, bandpos;



                bandpos = bandno + (reslevelno > 0);



                if (band->coord[0][0] == band->coord[0][1] || band->coord[1][0] == band->coord[1][1])

                    continue;



                nb_precincts = rlevel->num_precincts_x * rlevel->num_precincts_y;

                /* Loop on precincts */

                for (precno = 0; precno < nb_precincts; precno++) {

                    Jpeg2000Prec *prec = band->prec + precno;



                    /* Loop on codeblocks */

                    for (cblkno = 0; cblkno < prec->nb_codeblocks_width * prec->nb_codeblocks_height; cblkno++) {

                        int x, y;

                        Jpeg2000Cblk *cblk = prec->cblk + cblkno;

                        decode_cblk(s, codsty, &t1, cblk,

                                    cblk->coord[0][1] - cblk->coord[0][0],

                                    cblk->coord[1][1] - cblk->coord[1][0],

                                    bandpos);



                        /* Manage band offsets */

                        x = cblk->coord[0][0];

                        y = cblk->coord[1][0];



                        if (codsty->transform == FF_DWT97)

                            dequantization_float(x, y, cblk, comp, &t1, band);

                        else

                            dequantization_int(x, y, cblk, comp, &t1, band);

                   } /* end cblk */

                } /*end prec */

            } /* end band */

        } /* end reslevel */



        ff_dwt_decode(&comp->dwt, comp->data);

    } /*end comp */



    /* inverse MCT transformation */

    if (tile->codsty[0].mct)

        mct_decode(s, tile);



    if (s->precision <= 8) {

        for (compno = 0; compno < s->ncomponents; compno++) {

            Jpeg2000Component *comp = tile->comp + compno;

            float *datap = (float*)comp->data;

            int32_t *i_datap = (int32_t *) comp->data;



            y = tile->comp[compno].coord[1][0] - s->image_offset_y;

            line = s->picture->data[0] + y * s->picture->linesize[0];

            for (; y < tile->comp[compno].coord[1][1] - s->image_offset_y; y += s->cdy[compno]) {

                uint8_t *dst;



                x   = tile->comp[compno].coord[0][0] - s->image_offset_x;

                dst = line + x * s->ncomponents + compno;



                for (; x < tile->comp[compno].coord[0][1] - s->image_offset_x; x += s->cdx[compno]) {

                     int val;

                    /* DC level shift and clip see ISO 15444-1:2002 G.1.2 */

                    if (tile->codsty->transform == FF_DWT97)

                        val = lrintf(*datap) + (1 << (s->cbps[compno] - 1));

                    else

                        val = *i_datap + (1 << (s->cbps[compno] - 1));

                    val = av_clip(val, 0, (1 << s->cbps[compno]) - 1);

                    *dst = val << (8 - s->cbps[compno]);

                    datap++;

                    i_datap++;

                    dst += s->ncomponents;

                }

                line += s->picture->linesize[0];

            }

        }

    } else {

        for (compno = 0; compno < s->ncomponents; compno++) {

            Jpeg2000Component *comp = tile->comp + compno;

            float *datap = (float*)comp->data;

            int32_t *i_datap = (int32_t *) comp->data;

            uint16_t *linel;



            y     = tile->comp[compno].coord[1][0] - s->image_offset_y;

            linel = (uint16_t*)s->picture->data[0] + y * (s->picture->linesize[0] >> 1);

            for (; y < tile->comp[compno].coord[1][1] - s->image_offset_y; y += s->cdy[compno]) {

                uint16_t *dst;



                x = tile->comp[compno].coord[0][0] - s->image_offset_x;

                dst = linel + (x * s->ncomponents + compno);

                for (; x < tile->comp[compno].coord[0][1] - s->image_offset_x; x += s-> cdx[compno]) {

                     int val;

                    /* DC level shift and clip see ISO 15444-1:2002 G.1.2 */

                    if (tile->codsty->transform == FF_DWT97)

                        val = lrintf(*datap) + (1 << (s->cbps[compno] - 1));

                    else

                        val = *i_datap + (1 << (s->cbps[compno] - 1));

                    val = av_clip(val, 0, (1 << s->cbps[compno]) - 1);

                    /* align 12 bit values in little-endian mode */

                    *dst = val << (16 - s->cbps[compno]);

                    datap++;

                    i_datap++;

                    dst += s->ncomponents;

                }

                linel += s->picture->linesize[0]>>1;

            }

        }

    }

    return 0;

}

void virtqueue_get_avail_bytes(VirtQueue *vq, unsigned int *in_bytes,

                               unsigned int *out_bytes,

                               unsigned max_in_bytes, unsigned max_out_bytes)

{

    unsigned int idx;

    unsigned int total_bufs, in_total, out_total;



    idx = vq->last_avail_idx;



    total_bufs = in_total = out_total = 0;

    while (virtqueue_num_heads(vq, idx)) {

        unsigned int max, num_bufs, indirect = 0;

        hwaddr desc_pa;

        int i;



        max = vq->vring.num;

        num_bufs = total_bufs;

        i = virtqueue_get_head(vq, idx++);

        desc_pa = vq->vring.desc;



        if (vring_desc_flags(desc_pa, i) & VRING_DESC_F_INDIRECT) {

            if (vring_desc_len(desc_pa, i) % sizeof(VRingDesc)) {

                error_report("Invalid size for indirect buffer table");

                exit(1);

            }



            /* If we've got too many, that implies a descriptor loop. */

            if (num_bufs >= max) {

                error_report("Looped descriptor");

                exit(1);

            }



            /* loop over the indirect descriptor table */

            indirect = 1;

            max = vring_desc_len(desc_pa, i) / sizeof(VRingDesc);

            num_bufs = i = 0;

            desc_pa = vring_desc_addr(desc_pa, i);

        }



        do {

            /* If we've got too many, that implies a descriptor loop. */

            if (++num_bufs > max) {

                error_report("Looped descriptor");

                exit(1);

            }



            if (vring_desc_flags(desc_pa, i) & VRING_DESC_F_WRITE) {

                in_total += vring_desc_len(desc_pa, i);

            } else {

                out_total += vring_desc_len(desc_pa, i);

            }

            if (in_total >= max_in_bytes && out_total >= max_out_bytes) {

                goto done;

            }

        } while ((i = virtqueue_next_desc(desc_pa, i, max)) != max);



        if (!indirect)

            total_bufs = num_bufs;

        else

            total_bufs++;

    }

done:

    if (in_bytes) {

        *in_bytes = in_total;

    }

    if (out_bytes) {

        *out_bytes = out_total;

    }

}

