    return fpscr;

}

static int rtp_read_header(AVFormatContext *s)

{

    uint8_t recvbuf[RTP_MAX_PACKET_LENGTH];

    char host[500], sdp[500];

    int ret, port;

    URLContext* in = NULL;

    int payload_type;

    AVCodecContext codec = { 0 };

    struct sockaddr_storage addr;

    AVIOContext pb;

    socklen_t addrlen = sizeof(addr);

    RTSPState *rt = s->priv_data;



    if (!ff_network_init())

        return AVERROR(EIO);



    if (!rt->protocols) {

        rt->protocols = ffurl_get_protocols(NULL, NULL);

        if (!rt->protocols)

            return AVERROR(ENOMEM);

    }



    ret = ffurl_open(&in, s->filename, AVIO_FLAG_READ,

                     &s->interrupt_callback, NULL, rt->protocols);

    if (ret)

        goto fail;



    while (1) {

        ret = ffurl_read(in, recvbuf, sizeof(recvbuf));

        if (ret == AVERROR(EAGAIN))

            continue;

        if (ret < 0)

            goto fail;

        if (ret < 12) {

            av_log(s, AV_LOG_WARNING, "Received too short packet\n");

            continue;

        }



        if ((recvbuf[0] & 0xc0) != 0x80) {

            av_log(s, AV_LOG_WARNING, "Unsupported RTP version packet "

                                      "received\n");

            continue;

        }



        if (RTP_PT_IS_RTCP(recvbuf[1]))

            continue;



        payload_type = recvbuf[1] & 0x7f;

        break;

    }

    getsockname(ffurl_get_file_handle(in), (struct sockaddr*) &addr, &addrlen);

    ffurl_close(in);

    in = NULL;



    if (ff_rtp_get_codec_info(&codec, payload_type)) {

        av_log(s, AV_LOG_ERROR, "Unable to receive RTP payload type %d "

                                "without an SDP file describing it\n",

                                 payload_type);

        goto fail;

    }

    if (codec.codec_type != AVMEDIA_TYPE_DATA) {

        av_log(s, AV_LOG_WARNING, "Guessing on RTP content - if not received "

                                  "properly you need an SDP file "

                                  "describing it\n");

    }



    av_url_split(NULL, 0, NULL, 0, host, sizeof(host), &port,

                 NULL, 0, s->filename);



    snprintf(sdp, sizeof(sdp),

             "v=0\r\nc=IN IP%d %s\r\nm=%s %d RTP/AVP %d\r\n",

             addr.ss_family == AF_INET ? 4 : 6, host,

             codec.codec_type == AVMEDIA_TYPE_DATA  ? "application" :

             codec.codec_type == AVMEDIA_TYPE_VIDEO ? "video" : "audio",

             port, payload_type);

    av_log(s, AV_LOG_VERBOSE, "SDP:\n%s\n", sdp);



    ffio_init_context(&pb, sdp, strlen(sdp), 0, NULL, NULL, NULL, NULL);

    s->pb = &pb;



    /* sdp_read_header initializes this again */

    ff_network_close();



    rt->media_type_mask = (1 << (AVMEDIA_TYPE_DATA+1)) - 1;



    ret = sdp_read_header(s);

    s->pb = NULL;

    return ret;



fail:

    if (in)

        ffurl_close(in);

    ff_network_close();

    return ret;

}

static void xhci_kick_epctx(XHCIEPContext *epctx, unsigned int streamid)

{

    XHCIState *xhci = epctx->xhci;

    XHCIStreamContext *stctx;

    XHCITransfer *xfer;

    XHCIRing *ring;

    USBEndpoint *ep = NULL;

    uint64_t mfindex;

    int length;

    int i;



    trace_usb_xhci_ep_kick(epctx->slotid, epctx->epid, streamid);



    /* If the device has been detached, but the guest has not noticed this

       yet the 2 above checks will succeed, but we must NOT continue */

    if (!xhci->slots[epctx->slotid - 1].uport ||

        !xhci->slots[epctx->slotid - 1].uport->dev ||

        !xhci->slots[epctx->slotid - 1].uport->dev->attached) {

        return;

    }



    if (epctx->retry) {

        XHCITransfer *xfer = epctx->retry;



        trace_usb_xhci_xfer_retry(xfer);

        assert(xfer->running_retry);

        if (xfer->timed_xfer) {

            /* time to kick the transfer? */

            mfindex = xhci_mfindex_get(xhci);

            xhci_check_intr_iso_kick(xhci, xfer, epctx, mfindex);

            if (xfer->running_retry) {

                return;

            }

            xfer->timed_xfer = 0;

            xfer->running_retry = 1;

        }

        if (xfer->iso_xfer) {

            /* retry iso transfer */

            if (xhci_setup_packet(xfer) < 0) {

                return;

            }

            usb_handle_packet(xfer->packet.ep->dev, &xfer->packet);

            assert(xfer->packet.status != USB_RET_NAK);

            xhci_complete_packet(xfer);

        } else {

            /* retry nak'ed transfer */

            if (xhci_setup_packet(xfer) < 0) {

                return;

            }

            usb_handle_packet(xfer->packet.ep->dev, &xfer->packet);

            if (xfer->packet.status == USB_RET_NAK) {

                return;

            }

            xhci_complete_packet(xfer);

        }

        assert(!xfer->running_retry);

        xhci_ep_free_xfer(epctx->retry);

        epctx->retry = NULL;

    }



    if (epctx->state == EP_HALTED) {

        DPRINTF("xhci: ep halted, not running schedule\n");

        return;

    }





    if (epctx->nr_pstreams) {

        uint32_t err;

        stctx = xhci_find_stream(epctx, streamid, &err);

        if (stctx == NULL) {

            return;

        }

        ring = &stctx->ring;

        xhci_set_ep_state(xhci, epctx, stctx, EP_RUNNING);

    } else {

        ring = &epctx->ring;

        streamid = 0;

        xhci_set_ep_state(xhci, epctx, NULL, EP_RUNNING);

    }

    assert(ring->dequeue != 0);



    while (1) {

        length = xhci_ring_chain_length(xhci, ring);

        if (length <= 0) {

            break;

        }

        xfer = xhci_ep_alloc_xfer(epctx, length);

        if (xfer == NULL) {

            break;

        }



        for (i = 0; i < length; i++) {

            TRBType type;

            type = xhci_ring_fetch(xhci, ring, &xfer->trbs[i], NULL);

            assert(type);

        }

        xfer->streamid = streamid;



        if (epctx->epid == 1) {

            xhci_fire_ctl_transfer(xhci, xfer);

        } else {

            xhci_fire_transfer(xhci, xfer, epctx);

        }

        if (xfer->complete) {

            xhci_ep_free_xfer(xfer);

            xfer = NULL;

        }



        if (epctx->state == EP_HALTED) {

            break;

        }

        if (xfer != NULL && xfer->running_retry) {

            DPRINTF("xhci: xfer nacked, stopping schedule\n");

            epctx->retry = xfer;

            break;

        }

    }



    ep = xhci_epid_to_usbep(epctx);

    if (ep) {

        usb_device_flush_ep_queue(ep->dev, ep);

    }

}

