static int send_response(GAState *s, QObject *payload)

{

    const char *buf;

    QString *payload_qstr;

    GIOStatus status;



    g_assert(payload && s->channel);



    payload_qstr = qobject_to_json(payload);

    if (!payload_qstr) {

        return -EINVAL;

    }



