{

	return a + b;

}

static void scsi_device_class_init(ObjectClass *klass, void *data)

{

    DeviceClass *k = DEVICE_CLASS(klass);

    set_bit(DEVICE_CATEGORY_STORAGE, k->categories);

    k->bus_type = TYPE_SCSI_BUS;

    k->init     = scsi_qdev_init;

    k->unplug   = scsi_qdev_unplug;

    k->exit     = scsi_qdev_exit;

    k->props    = scsi_props;

}

static int dvvideo_decode_frame(AVCodecContext *avctx, 

                                 void *data, int *data_size,

                                 uint8_t *buf, int buf_size)

{

    DVVideoContext *s = avctx->priv_data;



    /* special case for last picture */

    if(buf_size==0)

        return 0;



    s->sys = dv_frame_profile(buf);

    if (!s->sys || buf_size < s->sys->frame_size)

        return -1; /* NOTE: we only accept several full frames */



    if(s->picture.data[0])

        avctx->release_buffer(avctx, &s->picture);



    s->picture.reference = 0;

    avctx->pix_fmt = s->sys->pix_fmt;

    avctx->width = s->sys->width;

    avctx->height = s->sys->height;

    if(avctx->get_buffer(avctx, &s->picture) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    s->picture.interlaced_frame = 1;

    s->picture.top_field_first = 0;



    s->buf = buf;

    avctx->execute(avctx, dv_decode_mt, (void**)&dv_anchor[0], NULL, 

	           s->sys->difseg_size * 27);



    emms_c();



    /* return image */

    *data_size = sizeof(AVFrame);

    *(AVFrame*)data= s->picture;



    return s->sys->frame_size;

}

static void quantize_and_encode_band_cost_UPAIR7_mips(struct AACEncContext *s,

                                                      PutBitContext *pb, const float *in, float *out,

                                                      const float *scaled, int size, int scale_idx,

                                                      int cb, const float lambda, const float uplim,

                                                      int *bits, const float ROUNDING)

{

    const float Q34 = ff_aac_pow34sf_tab[POW_SF2_ZERO - scale_idx + SCALE_ONE_POS - SCALE_DIV_512];

    const float IQ  = ff_aac_pow2sf_tab [POW_SF2_ZERO + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    int i;

    int qc1, qc2, qc3, qc4;



    uint8_t  *p_bits  = (uint8_t*) ff_aac_spectral_bits[cb-1];

    uint16_t *p_codes = (uint16_t*)ff_aac_spectral_codes[cb-1];

    float    *p_vec   = (float    *)ff_aac_codebook_vectors[cb-1];



    abs_pow34_v(s->scoefs, in, size);

    scaled = s->scoefs;

    for (i = 0; i < size; i += 4) {

        int curidx1, curidx2, sign1, count1, sign2, count2;

        int *in_int = (int *)&in[i];

        uint8_t v_bits;

        unsigned int v_codes;

        int t0, t1, t2, t3, t4;

        const float *vec1, *vec2;



        qc1 = scaled[i  ] * Q34 + ROUND_STANDARD;

        qc2 = scaled[i+1] * Q34 + ROUND_STANDARD;

        qc3 = scaled[i+2] * Q34 + ROUND_STANDARD;

        qc4 = scaled[i+3] * Q34 + ROUND_STANDARD;



        __asm__ volatile (

            ".set push                              \n\t"

            ".set noreorder                         \n\t"



            "ori    %[t4],      $zero,      7       \n\t"

            "ori    %[sign1],   $zero,      0       \n\t"

            "ori    %[sign2],   $zero,      0       \n\t"

            "slt    %[t0],      %[t4],      %[qc1]  \n\t"

            "slt    %[t1],      %[t4],      %[qc2]  \n\t"

            "slt    %[t2],      %[t4],      %[qc3]  \n\t"

            "slt    %[t3],      %[t4],      %[qc4]  \n\t"

            "movn   %[qc1],     %[t4],      %[t0]   \n\t"

            "movn   %[qc2],     %[t4],      %[t1]   \n\t"

            "movn   %[qc3],     %[t4],      %[t2]   \n\t"

            "movn   %[qc4],     %[t4],      %[t3]   \n\t"

            "lw     %[t0],      0(%[in_int])        \n\t"

            "lw     %[t1],      4(%[in_int])        \n\t"

            "lw     %[t2],      8(%[in_int])        \n\t"

            "lw     %[t3],      12(%[in_int])       \n\t"

            "slt    %[t0],      %[t0],      $zero   \n\t"

            "movn   %[sign1],   %[t0],      %[qc1]  \n\t"

            "slt    %[t2],      %[t2],      $zero   \n\t"

            "movn   %[sign2],   %[t2],      %[qc3]  \n\t"

            "slt    %[t1],      %[t1],      $zero   \n\t"

            "sll    %[t0],      %[sign1],   1       \n\t"

            "or     %[t0],      %[t0],      %[t1]   \n\t"

            "movn   %[sign1],   %[t0],      %[qc2]  \n\t"

            "slt    %[t3],      %[t3],      $zero   \n\t"

            "sll    %[t0],      %[sign2],   1       \n\t"

            "or     %[t0],      %[t0],      %[t3]   \n\t"

            "movn   %[sign2],   %[t0],      %[qc4]  \n\t"

            "slt    %[count1],  $zero,      %[qc1]  \n\t"

            "slt    %[t1],      $zero,      %[qc2]  \n\t"

            "slt    %[count2],  $zero,      %[qc3]  \n\t"

            "slt    %[t2],      $zero,      %[qc4]  \n\t"

            "addu   %[count1],  %[count1],  %[t1]   \n\t"

            "addu   %[count2],  %[count2],  %[t2]   \n\t"



            ".set pop                               \n\t"



            : [qc1]"+r"(qc1), [qc2]"+r"(qc2),

              [qc3]"+r"(qc3), [qc4]"+r"(qc4),

              [sign1]"=&r"(sign1), [count1]"=&r"(count1),

              [sign2]"=&r"(sign2), [count2]"=&r"(count2),

              [t0]"=&r"(t0), [t1]"=&r"(t1), [t2]"=&r"(t2), [t3]"=&r"(t3),

              [t4]"=&r"(t4)

            : [in_int]"r"(in_int)

            : "t0", "t1", "t2", "t3", "t4",

              "memory"

        );



        curidx1  = 8 * qc1;

        curidx1 += qc2;



        v_codes = (p_codes[curidx1] << count1) | sign1;

        v_bits  = p_bits[curidx1] + count1;

        put_bits(pb, v_bits, v_codes);



        curidx2  = 8 * qc3;

        curidx2 += qc4;



        v_codes = (p_codes[curidx2] << count2) | sign2;

        v_bits  = p_bits[curidx2] + count2;

        put_bits(pb, v_bits, v_codes);



        if (out) {

           vec1 = &p_vec[curidx1*2];

           vec2 = &p_vec[curidx2*2];

           out[i+0] = copysignf(vec1[0] * IQ, in[i+0]);

           out[i+1] = copysignf(vec1[1] * IQ, in[i+1]);

           out[i+2] = copysignf(vec2[0] * IQ, in[i+2]);

           out[i+3] = copysignf(vec2[1] * IQ, in[i+3]);

        }

    }

}

static int vp8_lossless_decode_frame(AVCodecContext *avctx, AVFrame *p,

                                     int *got_frame, uint8_t *data_start,

                                     unsigned int data_size, int is_alpha_chunk)

{

    WebPContext *s = avctx->priv_data;

    int w, h, ret, i;



    if (!is_alpha_chunk) {

        s->lossless = 1;

        avctx->pix_fmt = AV_PIX_FMT_ARGB;

    }



    ret = init_get_bits8(&s->gb, data_start, data_size);

    if (ret < 0)

        return ret;



    if (!is_alpha_chunk) {

        if (get_bits(&s->gb, 8) != 0x2F) {

            av_log(avctx, AV_LOG_ERROR, "Invalid WebP Lossless signature\n");

            return AVERROR_INVALIDDATA;

        }



        w = get_bits(&s->gb, 14) + 1;

        h = get_bits(&s->gb, 14) + 1;

        if (s->width && s->width != w) {

            av_log(avctx, AV_LOG_WARNING, "Width mismatch. %d != %d\n",

                   s->width, w);

        }

        s->width = w;

        if (s->height && s->height != h) {

            av_log(avctx, AV_LOG_WARNING, "Height mismatch. %d != %d\n",

                   s->width, w);

        }

        s->height = h;



        ret = ff_set_dimensions(avctx, s->width, s->height);

        if (ret < 0)

            return ret;



        s->has_alpha = get_bits1(&s->gb);



        if (get_bits(&s->gb, 3) != 0x0) {

            av_log(avctx, AV_LOG_ERROR, "Invalid WebP Lossless version\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        if (!s->width || !s->height)

            return AVERROR_BUG;

        w = s->width;

        h = s->height;

    }



    /* parse transformations */

    s->nb_transforms = 0;

    s->reduced_width = 0;

    while (get_bits1(&s->gb)) {

        enum TransformType transform = get_bits(&s->gb, 2);

        s->transforms[s->nb_transforms++] = transform;

        switch (transform) {

        case PREDICTOR_TRANSFORM:

            ret = parse_transform_predictor(s);

            break;

        case COLOR_TRANSFORM:

            ret = parse_transform_color(s);

            break;

        case COLOR_INDEXING_TRANSFORM:

            ret = parse_transform_color_indexing(s);

            break;

        }

        if (ret < 0)

            goto free_and_return;

    }



    /* decode primary image */

    s->image[IMAGE_ROLE_ARGB].frame = p;

    if (is_alpha_chunk)

        s->image[IMAGE_ROLE_ARGB].is_alpha_primary = 1;

    ret = decode_entropy_coded_image(s, IMAGE_ROLE_ARGB, w, h);

    if (ret < 0)

        goto free_and_return;



    /* apply transformations */

    for (i = s->nb_transforms - 1; i >= 0; i--) {

        switch (s->transforms[i]) {

        case PREDICTOR_TRANSFORM:

            ret = apply_predictor_transform(s);

            break;

        case COLOR_TRANSFORM:

            ret = apply_color_transform(s);

            break;

        case SUBTRACT_GREEN:

            ret = apply_subtract_green_transform(s);

            break;

        case COLOR_INDEXING_TRANSFORM:

            ret = apply_color_indexing_transform(s);

            break;

        }

        if (ret < 0)

            goto free_and_return;

    }



    *got_frame   = 1;

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;

    ret          = data_size;



free_and_return:

    for (i = 0; i < IMAGE_ROLE_NB; i++)

        image_ctx_free(&s->image[i]);



    return ret;

}

int ff_raw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVStream *st;

    enum CodecID id;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



        id = s->iformat->value;

        if (id == CODEC_ID_RAWVIDEO) {

            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        } else {

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        }

        st->codec->codec_id = id;



        switch(st->codec->codec_type) {

        case AVMEDIA_TYPE_AUDIO: {

            RawAudioDemuxerContext *s1 = s->priv_data;



#if FF_API_FORMAT_PARAMETERS

            if (ap->sample_rate)

                st->codec->sample_rate = ap->sample_rate;

            if (ap->channels)

                st->codec->channels    = ap->channels;

            else st->codec->channels   = 1;

#endif



            if (s1->sample_rate)

                st->codec->sample_rate = s1->sample_rate;

            if (s1->channels)

                st->codec->channels    = s1->channels;



            st->codec->bits_per_coded_sample = av_get_bits_per_sample(st->codec->codec_id);

            assert(st->codec->bits_per_coded_sample > 0);

            st->codec->block_align = st->codec->bits_per_coded_sample*st->codec->channels/8;

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

            break;

            }

        case AVMEDIA_TYPE_VIDEO: {

            FFRawVideoDemuxerContext *s1 = s->priv_data;

            int width = 0, height = 0, ret;

            enum PixelFormat pix_fmt;



            if(ap->time_base.num)

                av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

            else

                av_set_pts_info(st, 64, 1, 25);

            if (s1->video_size && (ret = av_parse_video_size(&width, &height, s1->video_size)) < 0) {

                av_log(s, AV_LOG_ERROR, "Couldn't parse video size.\n");

                goto fail;

            }

            if ((pix_fmt = av_get_pix_fmt(s1->pixel_format)) == PIX_FMT_NONE) {

                av_log(s, AV_LOG_ERROR, "No such pixel format: %s.\n", s1->pixel_format);

                ret = AVERROR(EINVAL);

                goto fail;

            }

#if FF_API_FORMAT_PARAMETERS

            if (ap->width > 0)

                width = ap->width;

            if (ap->height > 0)

                height = ap->height;

            if (ap->pix_fmt)

                pix_fmt = ap->pix_fmt;

#endif

            st->codec->width  = width;

            st->codec->height = height;

            st->codec->pix_fmt = pix_fmt;

fail:

            av_freep(&s1->video_size);

            av_freep(&s1->pixel_format);

            return ret;

            }

        default:

            return -1;

        }

    return 0;

}

