int h263_decode_picture_header(MpegEncContext *s)

{

    int format, width, height;



    /* picture header */

    if (get_bits(&s->gb, 22) != 0x20)

        return -1;

    skip_bits(&s->gb, 8); /* picture timestamp */



    if (get_bits1(&s->gb) != 1)

        return -1;	/* marker */

    if (get_bits1(&s->gb) != 0)

        return -1;	/* h263 id */

    skip_bits1(&s->gb);	/* split screen off */

    skip_bits1(&s->gb);	/* camera  off */

    skip_bits1(&s->gb);	/* freeze picture release off */



    format = get_bits(&s->gb, 3);



    if (format != 7) {

        s->h263_plus = 0;

        /* H.263v1 */

        width = h263_format[format][0];

        height = h263_format[format][1];

        if (!width)

            return -1;



        s->pict_type = I_TYPE + get_bits1(&s->gb);



        s->unrestricted_mv = get_bits1(&s->gb); 

        s->h263_long_vectors = s->unrestricted_mv;



        if (get_bits1(&s->gb) != 0)

            return -1;	/* SAC: off */

        if (get_bits1(&s->gb) != 0)

            return -1;	/* advanced prediction mode: off */

        if (get_bits1(&s->gb) != 0)

            return -1;	/* not PB frame */



        s->qscale = get_bits(&s->gb, 5);

        skip_bits1(&s->gb);	/* Continuous Presence Multipoint mode: off */

    } else {

        s->h263_plus = 1;

        /* H.263v2 */

        /* OPPTYPE */



        if (get_bits(&s->gb, 3) != 1) /* Update Full Extended PTYPE */

            return -1;

        format = get_bits(&s->gb, 3);



        skip_bits(&s->gb,1); /* Custom PCF */

        umvplus_dec = get_bits(&s->gb, 1); /* Unrestricted Motion Vector */

        skip_bits(&s->gb, 10);

        skip_bits(&s->gb, 3); /* Reserved */



        /* MPPTYPE */

        s->pict_type = get_bits(&s->gb, 3) + 1;

        if (s->pict_type != I_TYPE &&

            s->pict_type != P_TYPE)

            return -1;

        skip_bits(&s->gb, 7);



        /* Get the picture dimensions */

        if (format == 6) {

            /* Custom Picture Format (CPFMT) */

            skip_bits(&s->gb, 4); /* aspect ratio */

            width = (get_bits(&s->gb, 9) + 1) * 4;

            skip_bits1(&s->gb);

            height = get_bits(&s->gb, 9) * 4;

#ifdef DEBUG 

            fprintf(stderr,"\nH.263+ Custom picture: %dx%d\n",width,height);

#endif            

        }

        else {

            width = h263_format[format][0];

            height = h263_format[format][1];

        }



        if ((width == 0) || (height == 0))

            return -1;



        if (umvplus_dec) {

            skip_bits1(&s->gb); /* Unlimited Unrestricted Motion Vectors Indicator (UUI) */

        }



        s->qscale = get_bits(&s->gb, 5);

    }

    /* PEI */

    while (get_bits1(&s->gb) != 0) {

        skip_bits(&s->gb, 8);

    }

    s->f_code = 1;

    s->width = width;

    s->height = height;

    return 0;

}

static void get_fcb_param(FCBParam *optim, int16_t *impulse_resp,

                          int16_t *buf, int pulse_cnt, int pitch_lag)

{

    FCBParam param;

    int16_t impulse_r[SUBFRAME_LEN];

    int16_t temp_corr[SUBFRAME_LEN];

    int16_t impulse_corr[SUBFRAME_LEN];



    int ccr1[SUBFRAME_LEN];

    int ccr2[SUBFRAME_LEN];

    int amp, err, max, max_amp_index, min, scale, i, j, k, l;



    int64_t temp;



    /* Update impulse response */

    memcpy(impulse_r, impulse_resp, sizeof(int16_t) * SUBFRAME_LEN);

    param.dirac_train = 0;

    if (pitch_lag < SUBFRAME_LEN - 2) {

        param.dirac_train = 1;

        gen_dirac_train(impulse_r, pitch_lag);

    }



    for (i = 0; i < SUBFRAME_LEN; i++)

        temp_corr[i] = impulse_r[i] >> 1;



    /* Compute impulse response autocorrelation */

    temp = dot_product(temp_corr, temp_corr, SUBFRAME_LEN);



    scale = normalize_bits_int32(temp);

    impulse_corr[0] = av_clipl_int32((temp << scale) + (1 << 15)) >> 16;



    for (i = 1; i < SUBFRAME_LEN; i++) {

        temp = dot_product(temp_corr + i, temp_corr, SUBFRAME_LEN - i);

        impulse_corr[i] = av_clipl_int32((temp << scale) + (1 << 15)) >> 16;

    }



    /* Compute crosscorrelation of impulse response with residual signal */

    scale -= 4;

    for (i = 0; i < SUBFRAME_LEN; i++){

        temp = dot_product(buf + i, impulse_r, SUBFRAME_LEN - i);

        if (scale < 0)

            ccr1[i] = temp >> -scale;

        else

            ccr1[i] = av_clipl_int32(temp << scale);

    }



    /* Search loop */

    for (i = 0; i < GRID_SIZE; i++) {

        /* Maximize the crosscorrelation */

        max = 0;

        for (j = i; j < SUBFRAME_LEN; j += GRID_SIZE) {

            temp = FFABS(ccr1[j]);

            if (temp >= max) {

                max = temp;

                param.pulse_pos[0] = j;

            }

        }



        /* Quantize the gain (max crosscorrelation/impulse_corr[0]) */

        amp = max;

        min = 1 << 30;

        max_amp_index = GAIN_LEVELS - 2;

        for (j = max_amp_index; j >= 2; j--) {

            temp = av_clipl_int32((int64_t)fixed_cb_gain[j] *

                                  impulse_corr[0] << 1);

            temp = FFABS(temp - amp);

            if (temp < min) {

                min = temp;

                max_amp_index = j;

            }

        }



        max_amp_index--;

        /* Select additional gain values */

        for (j = 1; j < 5; j++) {

            for (k = i; k < SUBFRAME_LEN; k += GRID_SIZE) {

                temp_corr[k] = 0;

                ccr2[k]      = ccr1[k];

            }

            param.amp_index = max_amp_index + j - 2;

            amp = fixed_cb_gain[param.amp_index];



            param.pulse_sign[0] = (ccr2[param.pulse_pos[0]] < 0) ? -amp : amp;

            temp_corr[param.pulse_pos[0]] = 1;



            for (k = 1; k < pulse_cnt; k++) {

                max = -1 << 30;

                for (l = i; l < SUBFRAME_LEN; l += GRID_SIZE) {

                    if (temp_corr[l])

                        continue;

                    temp = impulse_corr[FFABS(l - param.pulse_pos[k - 1])];

                    temp = av_clipl_int32((int64_t)temp *

                                          param.pulse_sign[k - 1] << 1);

                    ccr2[l] -= temp;

                    temp = FFABS(ccr2[l]);

                    if (temp > max) {

                        max = temp;

                        param.pulse_pos[k] = l;

                    }

                }



                param.pulse_sign[k] = (ccr2[param.pulse_pos[k]] < 0) ?

                                      -amp : amp;

                temp_corr[param.pulse_pos[k]] = 1;

            }



            /* Create the error vector */

            memset(temp_corr, 0, sizeof(int16_t) * SUBFRAME_LEN);



            for (k = 0; k < pulse_cnt; k++)

                temp_corr[param.pulse_pos[k]] = param.pulse_sign[k];



            for (k = SUBFRAME_LEN - 1; k >= 0; k--) {

                temp = 0;

                for (l = 0; l <= k; l++) {

                    int prod = av_clipl_int32((int64_t)temp_corr[l] *

                                              impulse_r[k - l] << 1);

                    temp     = av_clipl_int32(temp + prod);

                }

                temp_corr[k] = temp << 2 >> 16;

            }



            /* Compute square of error */

            err = 0;

            for (k = 0; k < SUBFRAME_LEN; k++) {

                int64_t prod;

                prod = av_clipl_int32((int64_t)buf[k] * temp_corr[k] << 1);

                err  = av_clipl_int32(err - prod);

                prod = av_clipl_int32((int64_t)temp_corr[k] * temp_corr[k]);

                err  = av_clipl_int32(err + prod);

            }



            /* Minimize */

            if (err < optim->min_err) {

                optim->min_err     = err;

                optim->grid_index  = i;

                optim->amp_index   = param.amp_index;

                optim->dirac_train = param.dirac_train;



                for (k = 0; k < pulse_cnt; k++) {

                    optim->pulse_sign[k] = param.pulse_sign[k];

                    optim->pulse_pos[k]  = param.pulse_pos[k];

                }

            }

        }

    }

}

void drive_hot_add(Monitor *mon, const QDict *qdict)

{

    int dom, pci_bus;

    unsigned slot;

    int type, bus;

    PCIDevice *dev;

    DriveInfo *dinfo = NULL;

    const char *pci_addr = qdict_get_str(qdict, "pci_addr");

    const char *opts = qdict_get_str(qdict, "opts");

    BusState *scsibus;



    dinfo = add_init_drive(opts);

    if (!dinfo)

        goto err;

    if (dinfo->devaddr) {

        monitor_printf(mon, "Parameter addr not supported\n");

        goto err;

    }

    type = dinfo->type;

    bus = drive_get_max_bus (type);



    switch (type) {

    case IF_SCSI:

        if (pci_read_devaddr(mon, pci_addr, &dom, &pci_bus, &slot)) {

            goto err;

        }

        dev = pci_find_device(pci_bus, slot, 0);

        if (!dev) {

            monitor_printf(mon, "no pci device with address %s\n", pci_addr);

            goto err;

        }

        scsibus = QLIST_FIRST(&dev->qdev.child_bus);

        scsi_bus_legacy_add_drive(DO_UPCAST(SCSIBus, qbus, scsibus),

                                  dinfo, dinfo->unit);

        monitor_printf(mon, "OK bus %d, unit %d\n",

                       dinfo->bus,

                       dinfo->unit);

        break;

    case IF_NONE:

        monitor_printf(mon, "OK\n");

        break;

    default:

        monitor_printf(mon, "Can't hot-add drive to type %d\n", type);

        goto err;

    }

    return;



err:

    if (dinfo)

        drive_uninit(dinfo);

    return;

}

int load_elf_binary(struct linux_binprm * bprm, struct target_pt_regs * regs,

                    struct image_info * info)

{

    struct elfhdr elf_ex;

    struct elfhdr interp_elf_ex;

    struct exec interp_ex;

    int interpreter_fd = -1; /* avoid warning */

    abi_ulong load_addr, load_bias;

    int load_addr_set = 0;

    unsigned int interpreter_type = INTERPRETER_NONE;

    unsigned char ibcs2_interpreter;

    int i;

    abi_ulong mapped_addr;

    struct elf_phdr * elf_ppnt;

    struct elf_phdr *elf_phdata;

    abi_ulong elf_bss, k, elf_brk;

    int retval;

    char * elf_interpreter;

    abi_ulong elf_entry, interp_load_addr = 0;

    int status;

    abi_ulong start_code, end_code, start_data, end_data;

    abi_ulong reloc_func_desc = 0;

    abi_ulong elf_stack;

    char passed_fileno[6];



    ibcs2_interpreter = 0;

    status = 0;

    load_addr = 0;

    load_bias = 0;

    elf_ex = *((struct elfhdr *) bprm->buf);          /* exec-header */

#ifdef BSWAP_NEEDED

    bswap_ehdr(&elf_ex);

#endif



    /* First of all, some simple consistency checks */

    if ((elf_ex.e_type != ET_EXEC && elf_ex.e_type != ET_DYN) ||

       				(! elf_check_arch(elf_ex.e_machine))) {

	    return -ENOEXEC;

    }



    bprm->p = copy_elf_strings(1, &bprm->filename, bprm->page, bprm->p);

    bprm->p = copy_elf_strings(bprm->envc,bprm->envp,bprm->page,bprm->p);

    bprm->p = copy_elf_strings(bprm->argc,bprm->argv,bprm->page,bprm->p);

    if (!bprm->p) {

        retval = -E2BIG;

    }



    /* Now read in all of the header information */

    elf_phdata = (struct elf_phdr *)malloc(elf_ex.e_phentsize*elf_ex.e_phnum);

    if (elf_phdata == NULL) {

	return -ENOMEM;

    }



    retval = lseek(bprm->fd, elf_ex.e_phoff, SEEK_SET);

    if(retval > 0) {

	retval = read(bprm->fd, (char *) elf_phdata,

				elf_ex.e_phentsize * elf_ex.e_phnum);

    }



    if (retval < 0) {

	perror("load_elf_binary");

	exit(-1);

	free (elf_phdata);

	return -errno;

    }



#ifdef BSWAP_NEEDED

    elf_ppnt = elf_phdata;

    for (i=0; i<elf_ex.e_phnum; i++, elf_ppnt++) {

        bswap_phdr(elf_ppnt);

    }

#endif

    elf_ppnt = elf_phdata;



    elf_bss = 0;

    elf_brk = 0;





    elf_stack = ~((abi_ulong)0UL);

    elf_interpreter = NULL;

    start_code = ~((abi_ulong)0UL);

    end_code = 0;

    start_data = 0;

    end_data = 0;




    for(i=0;i < elf_ex.e_phnum; i++) {

	if (elf_ppnt->p_type == PT_INTERP) {

	    if ( elf_interpreter != NULL )

	    {

		free (elf_phdata);

		free(elf_interpreter);

		close(bprm->fd);

		return -EINVAL;

	    }



	    /* This is the program interpreter used for

	     * shared libraries - for now assume that this

	     * is an a.out format binary

	     */



	    elf_interpreter = (char *)malloc(elf_ppnt->p_filesz);



	    if (elf_interpreter == NULL) {

		free (elf_phdata);

		close(bprm->fd);

		return -ENOMEM;

	    }



	    retval = lseek(bprm->fd, elf_ppnt->p_offset, SEEK_SET);

	    if(retval >= 0) {

		retval = read(bprm->fd, elf_interpreter, elf_ppnt->p_filesz);

	    }

	    if(retval < 0) {

	 	perror("load_elf_binary2");

		exit(-1);

	    }



	    /* If the program interpreter is one of these two,

	       then assume an iBCS2 image. Otherwise assume

	       a native linux image. */



	    /* JRP - Need to add X86 lib dir stuff here... */



	    if (strcmp(elf_interpreter,"/usr/lib/libc.so.1") == 0 ||

		strcmp(elf_interpreter,"/usr/lib/ld.so.1") == 0) {

	      ibcs2_interpreter = 1;

	    }



#if 0

	    printf("Using ELF interpreter %s\n", elf_interpreter);

#endif

	    if (retval >= 0) {

		retval = open(path(elf_interpreter), O_RDONLY);

		if(retval >= 0) {

		    interpreter_fd = retval;

		}

		else {

		    perror(elf_interpreter);

		    exit(-1);

		    /* retval = -errno; */

		}

	    }



	    if (retval >= 0) {

		retval = lseek(interpreter_fd, 0, SEEK_SET);

		if(retval >= 0) {

		    retval = read(interpreter_fd,bprm->buf,128);

		}

	    }

	    if (retval >= 0) {

		interp_ex = *((struct exec *) bprm->buf); /* aout exec-header */

		interp_elf_ex=*((struct elfhdr *) bprm->buf); /* elf exec-header */

	    }

	    if (retval < 0) {

		perror("load_elf_binary3");

		exit(-1);

		free (elf_phdata);

		free(elf_interpreter);

		close(bprm->fd);

		return retval;

	    }

	}

	elf_ppnt++;

    }



    /* Some simple consistency checks for the interpreter */

    if (elf_interpreter){

	interpreter_type = INTERPRETER_ELF | INTERPRETER_AOUT;



	/* Now figure out which format our binary is */

	if ((N_MAGIC(interp_ex) != OMAGIC) && (N_MAGIC(interp_ex) != ZMAGIC) &&

	    	(N_MAGIC(interp_ex) != QMAGIC)) {

	  interpreter_type = INTERPRETER_ELF;

	}



	if (interp_elf_ex.e_ident[0] != 0x7f ||

            strncmp((char *)&interp_elf_ex.e_ident[1], "ELF",3) != 0) {

	    interpreter_type &= ~INTERPRETER_ELF;

	}



	if (!interpreter_type) {

	    free(elf_interpreter);

	    free(elf_phdata);

	    close(bprm->fd);

	    return -ELIBBAD;

	}

    }



    /* OK, we are done with that, now set up the arg stuff,

       and then start this sucker up */



    {

	char * passed_p;



	if (interpreter_type == INTERPRETER_AOUT) {

	    snprintf(passed_fileno, sizeof(passed_fileno), "%d", bprm->fd);

	    passed_p = passed_fileno;



	    if (elf_interpreter) {

		bprm->p = copy_elf_strings(1,&passed_p,bprm->page,bprm->p);

		bprm->argc++;

	    }

	}

	if (!bprm->p) {

	    if (elf_interpreter) {

	        free(elf_interpreter);

	    }

	    free (elf_phdata);

	    close(bprm->fd);

	    return -E2BIG;

	}

    }



    /* OK, This is the point of no return */

    info->end_data = 0;

    info->end_code = 0;

    info->start_mmap = (abi_ulong)ELF_START_MMAP;

    info->mmap = 0;

    elf_entry = (abi_ulong) elf_ex.e_entry;



    /* Do this so that we can load the interpreter, if need be.  We will

       change some of these later */

    info->rss = 0;

    bprm->p = setup_arg_pages(bprm->p, bprm, info);

    info->start_stack = bprm->p;



    /* Now we do a little grungy work by mmaping the ELF image into

     * the correct location in memory.  At this point, we assume that

     * the image should be loaded at fixed address, not at a variable

     * address.

     */



    for(i = 0, elf_ppnt = elf_phdata; i < elf_ex.e_phnum; i++, elf_ppnt++) {

        int elf_prot = 0;

        int elf_flags = 0;

        abi_ulong error;



	if (elf_ppnt->p_type != PT_LOAD)

            continue;



        if (elf_ppnt->p_flags & PF_R) elf_prot |= PROT_READ;

        if (elf_ppnt->p_flags & PF_W) elf_prot |= PROT_WRITE;

        if (elf_ppnt->p_flags & PF_X) elf_prot |= PROT_EXEC;

        elf_flags = MAP_PRIVATE | MAP_DENYWRITE;

        if (elf_ex.e_type == ET_EXEC || load_addr_set) {

            elf_flags |= MAP_FIXED;

        } else if (elf_ex.e_type == ET_DYN) {

            /* Try and get dynamic programs out of the way of the default mmap

               base, as well as whatever program they might try to exec.  This

               is because the brk will follow the loader, and is not movable.  */

            /* NOTE: for qemu, we do a big mmap to get enough space

               without hardcoding any address */

            error = target_mmap(0, ET_DYN_MAP_SIZE,

                                PROT_NONE, MAP_PRIVATE | MAP_ANON,

                                -1, 0);

            if (error == -1) {

                perror("mmap");

                exit(-1);

            }

            load_bias = TARGET_ELF_PAGESTART(error - elf_ppnt->p_vaddr);

        }



        error = target_mmap(TARGET_ELF_PAGESTART(load_bias + elf_ppnt->p_vaddr),

                            (elf_ppnt->p_filesz +

                             TARGET_ELF_PAGEOFFSET(elf_ppnt->p_vaddr)),

                            elf_prot,

                            (MAP_FIXED | MAP_PRIVATE | MAP_DENYWRITE),

                            bprm->fd,

                            (elf_ppnt->p_offset -

                             TARGET_ELF_PAGEOFFSET(elf_ppnt->p_vaddr)));

        if (error == -1) {

            perror("mmap");

            exit(-1);

        }



#ifdef LOW_ELF_STACK

        if (TARGET_ELF_PAGESTART(elf_ppnt->p_vaddr) < elf_stack)

            elf_stack = TARGET_ELF_PAGESTART(elf_ppnt->p_vaddr);

#endif



        if (!load_addr_set) {

            load_addr_set = 1;

            load_addr = elf_ppnt->p_vaddr - elf_ppnt->p_offset;

            if (elf_ex.e_type == ET_DYN) {

                load_bias += error -

                    TARGET_ELF_PAGESTART(load_bias + elf_ppnt->p_vaddr);

                load_addr += load_bias;

                reloc_func_desc = load_bias;

            }

        }

        k = elf_ppnt->p_vaddr;

        if (k < start_code)

            start_code = k;

        if (start_data < k)

            start_data = k;

        k = elf_ppnt->p_vaddr + elf_ppnt->p_filesz;

        if (k > elf_bss)

            elf_bss = k;

        if ((elf_ppnt->p_flags & PF_X) && end_code <  k)

            end_code = k;

        if (end_data < k)

            end_data = k;

        k = elf_ppnt->p_vaddr + elf_ppnt->p_memsz;

        if (k > elf_brk) elf_brk = k;

    }



    elf_entry += load_bias;

    elf_bss += load_bias;

    elf_brk += load_bias;

    start_code += load_bias;

    end_code += load_bias;

    start_data += load_bias;

    end_data += load_bias;



    if (elf_interpreter) {

	if (interpreter_type & 1) {

	    elf_entry = load_aout_interp(&interp_ex, interpreter_fd);

	}

	else if (interpreter_type & 2) {

	    elf_entry = load_elf_interp(&interp_elf_ex, interpreter_fd,

					    &interp_load_addr);

	}

        reloc_func_desc = interp_load_addr;



	close(interpreter_fd);

	free(elf_interpreter);



	if (elf_entry == ~((abi_ulong)0UL)) {

	    printf("Unable to load interpreter\n");

	    free(elf_phdata);

	    exit(-1);

	    return 0;

	}

    }



    free(elf_phdata);



    if (loglevel)

	load_symbols(&elf_ex, bprm->fd);



    if (interpreter_type != INTERPRETER_AOUT) close(bprm->fd);

    info->personality = (ibcs2_interpreter ? PER_SVR4 : PER_LINUX);



#ifdef LOW_ELF_STACK

    info->start_stack = bprm->p = elf_stack - 4;

#endif

    bprm->p = create_elf_tables(bprm->p,

		    bprm->argc,

		    bprm->envc,

                    &elf_ex,

                    load_addr, load_bias,

		    interp_load_addr,

		    (interpreter_type == INTERPRETER_AOUT ? 0 : 1),

		    info);

    info->load_addr = reloc_func_desc;

    info->start_brk = info->brk = elf_brk;

    info->end_code = end_code;

    info->start_code = start_code;

    info->start_data = start_data;

    info->end_data = end_data;

    info->start_stack = bprm->p;



    /* Calling set_brk effectively mmaps the pages that we need for the bss and break

       sections */

    set_brk(elf_bss, elf_brk);



    padzero(elf_bss, elf_brk);



#if 0

    printf("(start_brk) %x\n" , info->start_brk);

    printf("(end_code) %x\n" , info->end_code);

    printf("(start_code) %x\n" , info->start_code);

    printf("(end_data) %x\n" , info->end_data);

    printf("(start_stack) %x\n" , info->start_stack);

    printf("(brk) %x\n" , info->brk);

#endif



    if ( info->personality == PER_SVR4 )

    {

	    /* Why this, you ask???  Well SVr4 maps page 0 as read-only,

	       and some applications "depend" upon this behavior.

	       Since we do not have the power to recompile these, we

	       emulate the SVr4 behavior.  Sigh.  */

	    mapped_addr = target_mmap(0, qemu_host_page_size, PROT_READ | PROT_EXEC,

                                      MAP_FIXED | MAP_PRIVATE, -1, 0);

    }



    info->entry = elf_entry;



    return 0;

}

static int sctp_write(URLContext *h, const uint8_t *buf, int size)

{

    SCTPContext *s = h->priv_data;

    int ret;



    if (!(h->flags & AVIO_FLAG_NONBLOCK)) {

        ret = sctp_wait_fd(s->fd, 1);

        if (ret < 0)

            return ret;

    }



    if (s->max_streams) {

        /*StreamId is introduced as a 2byte code into the stream*/

        struct sctp_sndrcvinfo info = { 0 };

        info.sinfo_stream           = AV_RB16(buf);

        if (info.sinfo_stream > s->max_streams)

            abort();

        ret = ff_sctp_send(s->fd, buf + 2, size - 2, &info, MSG_EOR);

    } else

        ret = send(s->fd, buf, size, 0);



    return ret < 0 ? ff_neterrno() : ret;

}

