static void qemu_laio_process_completion(struct qemu_laiocb *laiocb)

{

    int ret;



    ret = laiocb->ret;

    if (ret != -ECANCELED) {

        if (ret == laiocb->nbytes) {

            ret = 0;

        } else if (ret >= 0) {

            /* Short reads mean EOF, pad with zeros. */

            if (laiocb->is_read) {

                qemu_iovec_memset(laiocb->qiov, ret, 0,

                    laiocb->qiov->size - ret);

            } else {

                ret = -ENOSPC;

            }

        }

    }



    laiocb->ret = ret;

    if (laiocb->co) {

        /* Jump and continue completion for foreign requests, don't do

         * anything for current request, it will be completed shortly. */

        if (laiocb->co != qemu_coroutine_self()) {

            qemu_coroutine_enter(laiocb->co);

        }

    } else {

        laiocb->common.cb(laiocb->common.opaque, ret);

        qemu_aio_unref(laiocb);

    }

}

static int configure_input_video_filter(FilterGraph *fg, InputFilter *ifilter,

                                        AVFilterInOut *in)

{

    AVFilterContext *last_filter;

    const AVFilter *buffer_filt = avfilter_get_by_name("buffer");

    InputStream *ist = ifilter->ist;

    InputFile     *f = input_files[ist->file_index];

    AVRational tb = ist->framerate.num ? av_inv_q(ist->framerate) :

                                         ist->st->time_base;

    AVRational fr = ist->framerate;

    AVRational sar;

    AVBPrint args;

    char name[255];

    int ret, pad_idx = 0;

    int64_t tsoffset = 0;

    AVBufferSrcParameters *par = av_buffersrc_parameters_alloc();



    if (!par)

        return AVERROR(ENOMEM);

    memset(par, 0, sizeof(*par));

    par->format = AV_PIX_FMT_NONE;



    if (ist->dec_ctx->codec_type == AVMEDIA_TYPE_AUDIO) {

        av_log(NULL, AV_LOG_ERROR, "Cannot connect video filter to audio input\n");

        return AVERROR(EINVAL);

    }



    if (!fr.num)

        fr = av_guess_frame_rate(input_files[ist->file_index]->ctx, ist->st, NULL);



    if (ist->dec_ctx->codec_type == AVMEDIA_TYPE_SUBTITLE) {

        ret = sub2video_prepare(ist);

        if (ret < 0)

            return ret;

    }



    sar = ist->st->sample_aspect_ratio.num ?

          ist->st->sample_aspect_ratio :

          ist->dec_ctx->sample_aspect_ratio;

    if(!sar.den)

        sar = (AVRational){0,1};

    av_bprint_init(&args, 0, 1);

    av_bprintf(&args,

             "video_size=%dx%d:pix_fmt=%d:time_base=%d/%d:"

             "pixel_aspect=%d/%d:sws_param=flags=%d", ist->resample_width,

             ist->resample_height,

             ist->hwaccel_retrieve_data ? ist->hwaccel_retrieved_pix_fmt : ist->resample_pix_fmt,

             tb.num, tb.den, sar.num, sar.den,

             SWS_BILINEAR + ((ist->dec_ctx->flags&AV_CODEC_FLAG_BITEXACT) ? SWS_BITEXACT:0));

    if (fr.num && fr.den)

        av_bprintf(&args, ":frame_rate=%d/%d", fr.num, fr.den);

    snprintf(name, sizeof(name), "graph %d input from stream %d:%d", fg->index,

             ist->file_index, ist->st->index);





    if ((ret = avfilter_graph_create_filter(&ifilter->filter, buffer_filt, name,

                                            args.str, NULL, fg->graph)) < 0)

        return ret;

    par->hw_frames_ctx = ist->hw_frames_ctx;

    ret = av_buffersrc_parameters_set(ifilter->filter, par);

    if (ret < 0)

        return ret;

    av_freep(&par);

    last_filter = ifilter->filter;



    if (ist->autorotate) {

        double theta = get_rotation(ist->st);



        if (fabs(theta - 90) < 1.0) {

            ret = insert_filter(&last_filter, &pad_idx, "transpose", "clock");

        } else if (fabs(theta - 180) < 1.0) {

            ret = insert_filter(&last_filter, &pad_idx, "hflip", NULL);

            if (ret < 0)

                return ret;

            ret = insert_filter(&last_filter, &pad_idx, "vflip", NULL);

        } else if (fabs(theta - 270) < 1.0) {

            ret = insert_filter(&last_filter, &pad_idx, "transpose", "cclock");

        } else if (fabs(theta) > 1.0) {

            char rotate_buf[64];

            snprintf(rotate_buf, sizeof(rotate_buf), "%f*PI/180", theta);

            ret = insert_filter(&last_filter, &pad_idx, "rotate", rotate_buf);

        }

        if (ret < 0)

            return ret;

    }



    if (ist->framerate.num) {

        AVFilterContext *setpts;



        snprintf(name, sizeof(name), "force CFR for input from stream %d:%d",

                 ist->file_index, ist->st->index);

        if ((ret = avfilter_graph_create_filter(&setpts,

                                                avfilter_get_by_name("setpts"),

                                                name, "N", NULL,

                                                fg->graph)) < 0)

            return ret;



        if ((ret = avfilter_link(last_filter, 0, setpts, 0)) < 0)

            return ret;



        last_filter = setpts;

    }



    if (do_deinterlace) {

        AVFilterContext *yadif;



        snprintf(name, sizeof(name), "deinterlace input from stream %d:%d",

                 ist->file_index, ist->st->index);

        if ((ret = avfilter_graph_create_filter(&yadif,

                                                avfilter_get_by_name("yadif"),

                                                name, "", NULL,

                                                fg->graph)) < 0)

            return ret;



        if ((ret = avfilter_link(last_filter, 0, yadif, 0)) < 0)

            return ret;



        last_filter = yadif;

    }



    snprintf(name, sizeof(name), "trim for input stream %d:%d",

             ist->file_index, ist->st->index);

    if (copy_ts) {

        tsoffset = f->start_time == AV_NOPTS_VALUE ? 0 : f->start_time;

        if (!start_at_zero && f->ctx->start_time != AV_NOPTS_VALUE)

            tsoffset += f->ctx->start_time;

    }

    ret = insert_trim(((f->start_time == AV_NOPTS_VALUE) || !f->accurate_seek) ?

                      AV_NOPTS_VALUE : tsoffset, f->recording_time,

                      &last_filter, &pad_idx, name);

    if (ret < 0)

        return ret;



    if ((ret = avfilter_link(last_filter, 0, in->filter_ctx, in->pad_idx)) < 0)

        return ret;

    return 0;

}

static coroutine_fn void reconnect_to_sdog(void *opaque)

{

    Error *local_err = NULL;

    BDRVSheepdogState *s = opaque;

    AIOReq *aio_req, *next;



    aio_set_fd_handler(s->aio_context, s->fd, NULL, NULL, NULL);

    close(s->fd);

    s->fd = -1;



    /* Wait for outstanding write requests to be completed. */

    while (s->co_send != NULL) {

        co_write_request(opaque);

    }



    /* Try to reconnect the sheepdog server every one second. */

    while (s->fd < 0) {

        s->fd = get_sheep_fd(s, &local_err);

        if (s->fd < 0) {

            DPRINTF("Wait for connection to be established\n");

            error_report("%s", error_get_pretty(local_err));

            error_free(local_err);

            co_aio_sleep_ns(bdrv_get_aio_context(s->bs), QEMU_CLOCK_REALTIME,

                            1000000000ULL);

        }

    };



    /*

     * Now we have to resend all the request in the inflight queue.  However,

     * resend_aioreq() can yield and newly created requests can be added to the

     * inflight queue before the coroutine is resumed.  To avoid mixing them, we

     * have to move all the inflight requests to the failed queue before

     * resend_aioreq() is called.

     */

    QLIST_FOREACH_SAFE(aio_req, &s->inflight_aio_head, aio_siblings, next) {

        QLIST_REMOVE(aio_req, aio_siblings);

        QLIST_INSERT_HEAD(&s->failed_aio_head, aio_req, aio_siblings);

    }



    /* Resend all the failed aio requests. */

    while (!QLIST_EMPTY(&s->failed_aio_head)) {

        aio_req = QLIST_FIRST(&s->failed_aio_head);

        QLIST_REMOVE(aio_req, aio_siblings);

        QLIST_INSERT_HEAD(&s->inflight_aio_head, aio_req, aio_siblings);

        resend_aioreq(s, aio_req);

    }

}

ram_addr_t ppc4xx_sdram_adjust(ram_addr_t ram_size, int nr_banks,

                               MemoryRegion ram_memories[],

                               hwaddr ram_bases[],

                               hwaddr ram_sizes[],

                               const unsigned int sdram_bank_sizes[])

{

    ram_addr_t size_left = ram_size;

    ram_addr_t base = 0;

    int i;

    int j;



    for (i = 0; i < nr_banks; i++) {

        for (j = 0; sdram_bank_sizes[j] != 0; j++) {

            unsigned int bank_size = sdram_bank_sizes[j];



            if (bank_size <= size_left) {

                char name[32];

                snprintf(name, sizeof(name), "ppc4xx.sdram%d", i);

                memory_region_allocate_system_memory(&ram_memories[i], NULL,

                                                     name, bank_size);

                ram_bases[i] = base;

                ram_sizes[i] = bank_size;

                base += bank_size;

                size_left -= bank_size;

                break;

            }

        }



        if (!size_left) {

            /* No need to use the remaining banks. */

            break;

        }

    }



    ram_size -= size_left;

    if (size_left)

        printf("Truncating memory to %d MiB to fit SDRAM controller limits.\n",

               (int)(ram_size >> 20));



    return ram_size;

}

static void setup_frame(int sig, struct target_sigaction *ka,

                        target_sigset_t *set, CPUCRISState *env)

{

	struct target_signal_frame *frame;

	abi_ulong frame_addr;

	int err = 0;

	int i;



	frame_addr = get_sigframe(env, sizeof *frame);

	if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0))

		goto badframe;



	/*

	 * The CRIS signal return trampoline. A real linux/CRIS kernel doesn't

	 * use this trampoline anymore but it sets it up for GDB.

	 * In QEMU, using the trampoline simplifies things a bit so we use it.

	 *

	 * This is movu.w __NR_sigreturn, r9; break 13;

	 */

    __put_user(0x9c5f, frame->retcode+0);

    __put_user(TARGET_NR_sigreturn,

               frame->retcode + 1);

    __put_user(0xe93d, frame->retcode + 2);



	/* Save the mask.  */

    __put_user(set->sig[0], &frame->sc.oldmask);

	if (err)

		goto badframe;



	for(i = 1; i < TARGET_NSIG_WORDS; i++) {

		if (__put_user(set->sig[i], &frame->extramask[i - 1]))

			goto badframe;

	}



	setup_sigcontext(&frame->sc, env);



	/* Move the stack and setup the arguments for the handler.  */

	env->regs[R_SP] = frame_addr;

	env->regs[10] = sig;

	env->pc = (unsigned long) ka->_sa_handler;

	/* Link SRP so the guest returns through the trampoline.  */

	env->pregs[PR_SRP] = frame_addr + offsetof(typeof(*frame), retcode);



	unlock_user_struct(frame, frame_addr, 1);

	return;

  badframe:

	unlock_user_struct(frame, frame_addr, 1);

	force_sig(TARGET_SIGSEGV);

}

static void vfio_pci_size_rom(VFIODevice *vdev)

{

    uint32_t orig, size = cpu_to_le32((uint32_t)PCI_ROM_ADDRESS_MASK);

    off_t offset = vdev->config_offset + PCI_ROM_ADDRESS;

    char name[32];



    if (vdev->pdev.romfile || !vdev->pdev.rom_bar) {

        return;

    }



    /*

     * Use the same size ROM BAR as the physical device.  The contents

     * will get filled in later when the guest tries to read it.

     */

    if (pread(vdev->fd, &orig, 4, offset) != 4 ||

        pwrite(vdev->fd, &size, 4, offset) != 4 ||

        pread(vdev->fd, &size, 4, offset) != 4 ||

        pwrite(vdev->fd, &orig, 4, offset) != 4) {

        error_report("%s(%04x:%02x:%02x.%x) failed: %m",

                     __func__, vdev->host.domain, vdev->host.bus,

                     vdev->host.slot, vdev->host.function);

        return;

    }



    size = ~(le32_to_cpu(size) & PCI_ROM_ADDRESS_MASK) + 1;



    if (!size) {

        return;

    }



    DPRINTF("%04x:%02x:%02x.%x ROM size 0x%x\n", vdev->host.domain,

            vdev->host.bus, vdev->host.slot, vdev->host.function, size);



    snprintf(name, sizeof(name), "vfio[%04x:%02x:%02x.%x].rom",

             vdev->host.domain, vdev->host.bus, vdev->host.slot,

             vdev->host.function);



    memory_region_init_io(&vdev->pdev.rom, OBJECT(vdev),

                          &vfio_rom_ops, vdev, name, size);



    pci_register_bar(&vdev->pdev, PCI_ROM_SLOT,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &vdev->pdev.rom);



    vdev->pdev.has_rom = true;


}

static int decode_frame(AVCodecContext *avctx,

                        void *data, int *data_size,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    TM2Context * const l = avctx->priv_data;

    AVFrame * const p= (AVFrame*)&l->pic;

    int i, skip, t;

    uint8_t *swbuf;



    swbuf = av_malloc(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

    if(!swbuf){

        av_log(avctx, AV_LOG_ERROR, "Cannot allocate temporary buffer\n");

        return -1;

    }

    p->reference = 1;

    p->buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;

    if(avctx->reget_buffer(avctx, p) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        av_free(swbuf);

        return -1;

    }



    l->dsp.bswap_buf((uint32_t*)swbuf, (const uint32_t*)buf, buf_size >> 2);

    skip = tm2_read_header(l, swbuf);



    if(skip == -1){

        av_free(swbuf);

        return -1;

    }



    for(i = 0; i < TM2_NUM_STREAMS; i++){

        t = tm2_read_stream(l, swbuf + skip, tm2_stream_order[i]);

        if(t == -1){

            av_free(swbuf);

            return -1;

        }

        skip += t;

    }

    p->key_frame = tm2_decode_blocks(l, p);

    if(p->key_frame)

        p->pict_type = FF_I_TYPE;

    else

        p->pict_type = FF_P_TYPE;



    l->cur = !l->cur;

    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = l->pic;

    av_free(swbuf);



    return buf_size;

}

static int decode_frame_mp3on4(AVCodecContext *avctx, void *data,

                               int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf     = avpkt->data;

    int buf_size           = avpkt->size;

    MP3On4DecodeContext *s = avctx->priv_data;

    MPADecodeContext *m;

    int fsize, len = buf_size, out_size = 0;

    uint32_t header;

    OUT_INT *out_samples;

    OUT_INT *outptr, *bp;

    int fr, j, n, ch, ret;



    /* get output buffer */

    s->frame->nb_samples = MPA_FRAME_SIZE;

    if ((ret = avctx->get_buffer(avctx, s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;


    out_samples = (OUT_INT *)s->frame->data[0];



    // Discard too short frames

    if (buf_size < HEADER_SIZE)




    // If only one decoder interleave is not needed

    outptr = s->frames == 1 ? out_samples : s->decoded_buf;



    avctx->bit_rate = 0;



    ch = 0;

    for (fr = 0; fr < s->frames; fr++) {

        fsize = AV_RB16(buf) >> 4;

        fsize = FFMIN3(fsize, len, MPA_MAX_CODED_FRAME_SIZE);

        m     = s->mp3decctx[fr];

        assert(m != NULL);







        header = (AV_RB32(buf) & 0x000fffff) | s->syncword; // patch header



        if (ff_mpa_check_header(header) < 0) // Bad header, discard block

            break;



        avpriv_mpegaudio_decode_header((MPADecodeHeader *)m, header);



        if (ch + m->nb_channels > avctx->channels) {

            av_log(avctx, AV_LOG_ERROR, "frame channel count exceeds codec "

                                        "channel count\n");



        ch += m->nb_channels;



        out_size += mp_decode_frame(m, outptr, buf, fsize);

        buf      += fsize;

        len      -= fsize;



        if (s->frames > 1) {

            n = m->avctx->frame_size*m->nb_channels;

            /* interleave output data */

            bp = out_samples + s->coff[fr];

            if (m->nb_channels == 1) {

                for (j = 0; j < n; j++) {

                    *bp = s->decoded_buf[j];

                    bp += avctx->channels;


            } else {

                for (j = 0; j < n; j++) {

                    bp[0] = s->decoded_buf[j++];

                    bp[1] = s->decoded_buf[j];

                    bp   += avctx->channels;




        avctx->bit_rate += m->bit_rate;




    /* update codec info */

    avctx->sample_rate = s->mp3decctx[0]->sample_rate;



    s->frame->nb_samples = out_size / (avctx->channels * sizeof(OUT_INT));

    *got_frame_ptr   = 1;

    *(AVFrame *)data = *s->frame;



    return buf_size;

static int get_dimension(GetBitContext *gb, const int *dim)

{

    int t   = get_bits(gb, 3);

    int val = dim[t];

    if(val < 0)

        val = dim[get_bits1(gb) - val];

    if(!val){

        do{



            t = get_bits(gb, 8);

            val += t << 2;

        }while(t == 0xFF);

    }

    return val;

}

static int loadvm_postcopy_handle_run(MigrationIncomingState *mis)

{

    PostcopyState ps = postcopy_state_set(POSTCOPY_INCOMING_RUNNING);



    trace_loadvm_postcopy_handle_run();

    if (ps != POSTCOPY_INCOMING_LISTENING) {

        error_report("CMD_POSTCOPY_RUN in wrong postcopy state (%d)", ps);

        return -1;

    }



    mis->bh = qemu_bh_new(loadvm_postcopy_handle_run_bh, NULL);

    qemu_bh_schedule(mis->bh);



    /* We need to finish reading the stream from the package

     * and also stop reading anything more from the stream that loaded the

     * package (since it's now being read by the listener thread).

     * LOADVM_QUIT will quit all the layers of nested loadvm loops.

     */

    return LOADVM_QUIT;

}

static int protocol_version(VncState *vs, uint8_t *version, size_t len)

{

    char local[13];



    memcpy(local, version, 12);

    local[12] = 0;



    if (sscanf(local, "RFB %03d.%03d\n", &vs->major, &vs->minor) != 2) {

	VNC_DEBUG("Malformed protocol version %s\n", local);

	vnc_client_error(vs);

	return 0;

    }

    VNC_DEBUG("Client request protocol version %d.%d\n", vs->major, vs->minor);

    if (vs->major != 3 ||

	(vs->minor != 3 &&

	 vs->minor != 4 &&

	 vs->minor != 5 &&

	 vs->minor != 7 &&

	 vs->minor != 8)) {

	VNC_DEBUG("Unsupported client version\n");

	vnc_write_u32(vs, VNC_AUTH_INVALID);

	vnc_flush(vs);

	vnc_client_error(vs);

	return 0;

    }

    /* Some broken clients report v3.4 or v3.5, which spec requires to be treated

     * as equivalent to v3.3 by servers

     */

    if (vs->minor == 4 || vs->minor == 5)

	vs->minor = 3;



    if (vs->minor == 3) {

	if (vs->vd->auth == VNC_AUTH_NONE) {

            VNC_DEBUG("Tell client auth none\n");

            vnc_write_u32(vs, vs->vd->auth);

            vnc_flush(vs);

            vnc_read_when(vs, protocol_client_init, 1);

       } else if (vs->vd->auth == VNC_AUTH_VNC) {

            VNC_DEBUG("Tell client VNC auth\n");

            vnc_write_u32(vs, vs->vd->auth);

            vnc_flush(vs);

            start_auth_vnc(vs);

       } else {

            VNC_DEBUG("Unsupported auth %d for protocol 3.3\n", vs->vd->auth);

            vnc_write_u32(vs, VNC_AUTH_INVALID);

            vnc_flush(vs);

            vnc_client_error(vs);

       }

    } else {

	VNC_DEBUG("Telling client we support auth %d\n", vs->vd->auth);

	vnc_write_u8(vs, 1); /* num auth */

	vnc_write_u8(vs, vs->vd->auth);

	vnc_read_when(vs, protocol_client_auth, 1);

	vnc_flush(vs);

    }



    return 0;

}

DriveInfo *drive_init(QemuOpts *opts, int default_to_scsi, int *fatal_error)

{

    const char *buf;

    const char *file = NULL;

    char devname[128];

    const char *serial;

    const char *mediastr = "";

    BlockInterfaceType type;

    enum { MEDIA_DISK, MEDIA_CDROM } media;

    int bus_id, unit_id;

    int cyls, heads, secs, translation;

    BlockDriver *drv = NULL;

    int max_devs;

    int index;

    int ro = 0;

    int bdrv_flags = 0;

    int on_read_error, on_write_error;

    const char *devaddr;

    DriveInfo *dinfo;

    int snapshot = 0;

    int ret;



    *fatal_error = 1;



    translation = BIOS_ATA_TRANSLATION_AUTO;



    if (default_to_scsi) {

        type = IF_SCSI;

        max_devs = MAX_SCSI_DEVS;

        pstrcpy(devname, sizeof(devname), "scsi");

    } else {

        type = IF_IDE;

        max_devs = MAX_IDE_DEVS;

        pstrcpy(devname, sizeof(devname), "ide");

    }

    media = MEDIA_DISK;



    /* extract parameters */

    bus_id  = qemu_opt_get_number(opts, "bus", 0);

    unit_id = qemu_opt_get_number(opts, "unit", -1);

    index   = qemu_opt_get_number(opts, "index", -1);



    cyls  = qemu_opt_get_number(opts, "cyls", 0);

    heads = qemu_opt_get_number(opts, "heads", 0);

    secs  = qemu_opt_get_number(opts, "secs", 0);



    snapshot = qemu_opt_get_bool(opts, "snapshot", 0);

    ro = qemu_opt_get_bool(opts, "readonly", 0);



    file = qemu_opt_get(opts, "file");

    serial = qemu_opt_get(opts, "serial");



    if ((buf = qemu_opt_get(opts, "if")) != NULL) {

        pstrcpy(devname, sizeof(devname), buf);

        if (!strcmp(buf, "ide")) {

	    type = IF_IDE;

            max_devs = MAX_IDE_DEVS;

        } else if (!strcmp(buf, "scsi")) {

	    type = IF_SCSI;

            max_devs = MAX_SCSI_DEVS;

        } else if (!strcmp(buf, "floppy")) {

	    type = IF_FLOPPY;

            max_devs = 0;

        } else if (!strcmp(buf, "pflash")) {

	    type = IF_PFLASH;

            max_devs = 0;

	} else if (!strcmp(buf, "mtd")) {

	    type = IF_MTD;

            max_devs = 0;

	} else if (!strcmp(buf, "sd")) {

	    type = IF_SD;

            max_devs = 0;

        } else if (!strcmp(buf, "virtio")) {

            type = IF_VIRTIO;

            max_devs = 0;

	} else if (!strcmp(buf, "xen")) {

	    type = IF_XEN;

            max_devs = 0;

	} else if (!strcmp(buf, "none")) {

	    type = IF_NONE;

            max_devs = 0;

	} else {

            fprintf(stderr, "qemu: unsupported bus type '%s'\n", buf);

            return NULL;

	}

    }



    if (cyls || heads || secs) {

        if (cyls < 1 || (type == IF_IDE && cyls > 16383)) {

            fprintf(stderr, "qemu: '%s' invalid physical cyls number\n", buf);

	    return NULL;

	}

        if (heads < 1 || (type == IF_IDE && heads > 16)) {

            fprintf(stderr, "qemu: '%s' invalid physical heads number\n", buf);

	    return NULL;

	}

        if (secs < 1 || (type == IF_IDE && secs > 63)) {

            fprintf(stderr, "qemu: '%s' invalid physical secs number\n", buf);

	    return NULL;

	}

    }



    if ((buf = qemu_opt_get(opts, "trans")) != NULL) {

        if (!cyls) {

            fprintf(stderr,

                    "qemu: '%s' trans must be used with cyls,heads and secs\n",

                    buf);

            return NULL;

        }

        if (!strcmp(buf, "none"))

            translation = BIOS_ATA_TRANSLATION_NONE;

        else if (!strcmp(buf, "lba"))

            translation = BIOS_ATA_TRANSLATION_LBA;

        else if (!strcmp(buf, "auto"))

            translation = BIOS_ATA_TRANSLATION_AUTO;

	else {

            fprintf(stderr, "qemu: '%s' invalid translation type\n", buf);

	    return NULL;

	}

    }



    if ((buf = qemu_opt_get(opts, "media")) != NULL) {

        if (!strcmp(buf, "disk")) {

	    media = MEDIA_DISK;

	} else if (!strcmp(buf, "cdrom")) {

            if (cyls || secs || heads) {

                fprintf(stderr,

                        "qemu: '%s' invalid physical CHS format\n", buf);

	        return NULL;

            }

	    media = MEDIA_CDROM;

	} else {

	    fprintf(stderr, "qemu: '%s' invalid media\n", buf);

	    return NULL;

	}

    }



    if ((buf = qemu_opt_get(opts, "cache")) != NULL) {

        if (!strcmp(buf, "off") || !strcmp(buf, "none")) {

            bdrv_flags |= BDRV_O_NOCACHE;

        } else if (!strcmp(buf, "writeback")) {

            bdrv_flags |= BDRV_O_CACHE_WB;

        } else if (!strcmp(buf, "unsafe")) {

            bdrv_flags |= BDRV_O_CACHE_WB;

            bdrv_flags |= BDRV_O_NO_FLUSH;

        } else if (!strcmp(buf, "writethrough")) {

            /* this is the default */

        } else {

           fprintf(stderr, "qemu: invalid cache option\n");

           return NULL;

        }

    }



#ifdef CONFIG_LINUX_AIO

    if ((buf = qemu_opt_get(opts, "aio")) != NULL) {

        if (!strcmp(buf, "native")) {

            bdrv_flags |= BDRV_O_NATIVE_AIO;

        } else if (!strcmp(buf, "threads")) {

            /* this is the default */

        } else {

           fprintf(stderr, "qemu: invalid aio option\n");

           return NULL;

        }

    }

#endif



    if ((buf = qemu_opt_get(opts, "format")) != NULL) {

       if (strcmp(buf, "?") == 0) {

            fprintf(stderr, "qemu: Supported formats:");

            bdrv_iterate_format(bdrv_format_print, NULL);

            fprintf(stderr, "\n");

	    return NULL;

        }

        drv = bdrv_find_whitelisted_format(buf);

        if (!drv) {

            fprintf(stderr, "qemu: '%s' invalid format\n", buf);

            return NULL;

        }

    }



    on_write_error = BLOCK_ERR_STOP_ENOSPC;

    if ((buf = qemu_opt_get(opts, "werror")) != NULL) {

        if (type != IF_IDE && type != IF_SCSI && type != IF_VIRTIO && type != IF_NONE) {

            fprintf(stderr, "werror is no supported by this format\n");

            return NULL;

        }



        on_write_error = parse_block_error_action(buf, 0);

        if (on_write_error < 0) {

            return NULL;

        }

    }



    on_read_error = BLOCK_ERR_REPORT;

    if ((buf = qemu_opt_get(opts, "rerror")) != NULL) {

        if (type != IF_IDE && type != IF_VIRTIO && type != IF_NONE) {

            fprintf(stderr, "rerror is no supported by this format\n");

            return NULL;

        }



        on_read_error = parse_block_error_action(buf, 1);

        if (on_read_error < 0) {

            return NULL;

        }

    }



    if ((devaddr = qemu_opt_get(opts, "addr")) != NULL) {

        if (type != IF_VIRTIO) {

            fprintf(stderr, "addr is not supported\n");

            return NULL;

        }

    }



    /* compute bus and unit according index */



    if (index != -1) {

        if (bus_id != 0 || unit_id != -1) {

            fprintf(stderr,

                    "qemu: index cannot be used with bus and unit\n");

            return NULL;

        }

        if (max_devs == 0)

        {

            unit_id = index;

            bus_id = 0;

        } else {

            unit_id = index % max_devs;

            bus_id = index / max_devs;

        }

    }



    /* if user doesn't specify a unit_id,

     * try to find the first free

     */



    if (unit_id == -1) {

       unit_id = 0;

       while (drive_get(type, bus_id, unit_id) != NULL) {

           unit_id++;

           if (max_devs && unit_id >= max_devs) {

               unit_id -= max_devs;

               bus_id++;

           }

       }

    }



    /* check unit id */



    if (max_devs && unit_id >= max_devs) {

        fprintf(stderr, "qemu: unit %d too big (max is %d)\n",

                unit_id, max_devs - 1);

        return NULL;

    }



    /*

     * ignore multiple definitions

     */



    if (drive_get(type, bus_id, unit_id) != NULL) {

        *fatal_error = 0;

        return NULL;

    }



    /* init */



    dinfo = qemu_mallocz(sizeof(*dinfo));

    if ((buf = qemu_opts_id(opts)) != NULL) {

        dinfo->id = qemu_strdup(buf);

    } else {

        /* no id supplied -> create one */

        dinfo->id = qemu_mallocz(32);

        if (type == IF_IDE || type == IF_SCSI)

            mediastr = (media == MEDIA_CDROM) ? "-cd" : "-hd";

        if (max_devs)

            snprintf(dinfo->id, 32, "%s%i%s%i",

                     devname, bus_id, mediastr, unit_id);

        else

            snprintf(dinfo->id, 32, "%s%s%i",

                     devname, mediastr, unit_id);

    }

    dinfo->bdrv = bdrv_new(dinfo->id);

    dinfo->devaddr = devaddr;

    dinfo->type = type;

    dinfo->bus = bus_id;

    dinfo->unit = unit_id;

    dinfo->on_read_error = on_read_error;

    dinfo->on_write_error = on_write_error;

    dinfo->opts = opts;

    if (serial)

        strncpy(dinfo->serial, serial, sizeof(serial));

    QTAILQ_INSERT_TAIL(&drives, dinfo, next);



    switch(type) {

    case IF_IDE:

    case IF_SCSI:

    case IF_XEN:

    case IF_NONE:

        switch(media) {

	case MEDIA_DISK:

            if (cyls != 0) {

                bdrv_set_geometry_hint(dinfo->bdrv, cyls, heads, secs);

                bdrv_set_translation_hint(dinfo->bdrv, translation);

            }

	    break;

	case MEDIA_CDROM:

            bdrv_set_type_hint(dinfo->bdrv, BDRV_TYPE_CDROM);

	    break;

	}

        break;

    case IF_SD:

        /* FIXME: This isn't really a floppy, but it's a reasonable

           approximation.  */

    case IF_FLOPPY:

        bdrv_set_type_hint(dinfo->bdrv, BDRV_TYPE_FLOPPY);

        break;

    case IF_PFLASH:

    case IF_MTD:

        break;

    case IF_VIRTIO:

        /* add virtio block device */

        opts = qemu_opts_create(&qemu_device_opts, NULL, 0);

        qemu_opt_set(opts, "driver", "virtio-blk-pci");

        qemu_opt_set(opts, "drive", dinfo->id);

        if (devaddr)

            qemu_opt_set(opts, "addr", devaddr);

        break;

    case IF_COUNT:

        abort();

    }

    if (!file) {

        *fatal_error = 0;

        return NULL;

    }

    if (snapshot) {

        /* always use cache=unsafe with snapshot */

        bdrv_flags &= ~BDRV_O_CACHE_MASK;

        bdrv_flags |= (BDRV_O_SNAPSHOT|BDRV_O_CACHE_WB|BDRV_O_NO_FLUSH);

    }



    if (media == MEDIA_CDROM) {

        /* CDROM is fine for any interface, don't check.  */

        ro = 1;

    } else if (ro == 1) {

        if (type != IF_SCSI && type != IF_VIRTIO && type != IF_FLOPPY && type != IF_NONE) {

            fprintf(stderr, "qemu: readonly flag not supported for drive with this interface\n");

            return NULL;

        }

    }



    bdrv_flags |= ro ? 0 : BDRV_O_RDWR;



    ret = bdrv_open(dinfo->bdrv, file, bdrv_flags, drv);

    if (ret < 0) {

        fprintf(stderr, "qemu: could not open disk image %s: %s\n",

                        file, strerror(-ret));

        return NULL;

    }



    if (bdrv_key_required(dinfo->bdrv))

        autostart = 0;

    *fatal_error = 0;

    return dinfo;

}

static av_always_inline void encode_mb_internal(MpegEncContext *s, int motion_x, int motion_y, int mb_block_height, int mb_block_count)

{

    int16_t weight[8][64];

    DCTELEM orig[8][64];

    const int mb_x= s->mb_x;

    const int mb_y= s->mb_y;

    int i;

    int skip_dct[8];

    int dct_offset   = s->linesize*8; //default for progressive frames

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    int wrap_y, wrap_c;



    for(i=0; i<mb_block_count; i++) skip_dct[i]=s->skipdct;



    if(s->adaptive_quant){

        const int last_qp= s->qscale;

        const int mb_xy= mb_x + mb_y*s->mb_stride;



        s->lambda= s->lambda_table[mb_xy];

        update_qscale(s);



        if(!(s->flags&CODEC_FLAG_QP_RD)){

            s->qscale= s->current_picture_ptr->qscale_table[mb_xy];

            s->dquant= s->qscale - last_qp;



            if(s->out_format==FMT_H263){

                s->dquant= av_clip(s->dquant, -2, 2);



                if(s->codec_id==CODEC_ID_MPEG4){

                    if(!s->mb_intra){

                        if(s->pict_type == FF_B_TYPE){

                            if(s->dquant&1 || s->mv_dir&MV_DIRECT)

                                s->dquant= 0;

                        }

                        if(s->mv_type==MV_TYPE_8X8)

                            s->dquant=0;

                    }

                }

            }

        }

        ff_set_qscale(s, last_qp + s->dquant);

    }else if(s->flags&CODEC_FLAG_QP_RD)

        ff_set_qscale(s, s->qscale + s->dquant);



    wrap_y = s->linesize;

    wrap_c = s->uvlinesize;

    ptr_y = s->new_picture.data[0] + (mb_y * 16 * wrap_y) + mb_x * 16;

    ptr_cb = s->new_picture.data[1] + (mb_y * mb_block_height * wrap_c) + mb_x * 8;

    ptr_cr = s->new_picture.data[2] + (mb_y * mb_block_height * wrap_c) + mb_x * 8;



    if(mb_x*16+16 > s->width || mb_y*16+16 > s->height){

        uint8_t *ebuf= s->edge_emu_buffer + 32;

        ff_emulated_edge_mc(ebuf            , ptr_y , wrap_y,16,16,mb_x*16,mb_y*16, s->width   , s->height);

        ptr_y= ebuf;

        ff_emulated_edge_mc(ebuf+18*wrap_y  , ptr_cb, wrap_c, 8, mb_block_height, mb_x*8, mb_y*8, s->width>>1, s->height>>1);

        ptr_cb= ebuf+18*wrap_y;

        ff_emulated_edge_mc(ebuf+18*wrap_y+8, ptr_cr, wrap_c, 8, mb_block_height, mb_x*8, mb_y*8, s->width>>1, s->height>>1);

        ptr_cr= ebuf+18*wrap_y+8;

    }



    if (s->mb_intra) {

        if(s->flags&CODEC_FLAG_INTERLACED_DCT){

            int progressive_score, interlaced_score;



            s->interlaced_dct=0;

            progressive_score= s->dsp.ildct_cmp[4](s, ptr_y           , NULL, wrap_y, 8)

                              +s->dsp.ildct_cmp[4](s, ptr_y + wrap_y*8, NULL, wrap_y, 8) - 400;



            if(progressive_score > 0){

                interlaced_score = s->dsp.ildct_cmp[4](s, ptr_y           , NULL, wrap_y*2, 8)

                                  +s->dsp.ildct_cmp[4](s, ptr_y + wrap_y  , NULL, wrap_y*2, 8);

                if(progressive_score > interlaced_score){

                    s->interlaced_dct=1;



                    dct_offset= wrap_y;

                    wrap_y<<=1;

                    if (s->chroma_format == CHROMA_422)

                        wrap_c<<=1;

                }

            }

        }



        s->dsp.get_pixels(s->block[0], ptr_y                 , wrap_y);

        s->dsp.get_pixels(s->block[1], ptr_y              + 8, wrap_y);

        s->dsp.get_pixels(s->block[2], ptr_y + dct_offset    , wrap_y);

        s->dsp.get_pixels(s->block[3], ptr_y + dct_offset + 8, wrap_y);



        if(s->flags&CODEC_FLAG_GRAY){

            skip_dct[4]= 1;

            skip_dct[5]= 1;

        }else{

            s->dsp.get_pixels(s->block[4], ptr_cb, wrap_c);

            s->dsp.get_pixels(s->block[5], ptr_cr, wrap_c);

            if(!s->chroma_y_shift){ /* 422 */

                s->dsp.get_pixels(s->block[6], ptr_cb + (dct_offset>>1), wrap_c);

                s->dsp.get_pixels(s->block[7], ptr_cr + (dct_offset>>1), wrap_c);

            }

        }

    }else{

        op_pixels_func (*op_pix)[4];

        qpel_mc_func (*op_qpix)[16];

        uint8_t *dest_y, *dest_cb, *dest_cr;



        dest_y  = s->dest[0];

        dest_cb = s->dest[1];

        dest_cr = s->dest[2];



        if ((!s->no_rounding) || s->pict_type==FF_B_TYPE){

            op_pix = s->dsp.put_pixels_tab;

            op_qpix= s->dsp.put_qpel_pixels_tab;

        }else{

            op_pix = s->dsp.put_no_rnd_pixels_tab;

            op_qpix= s->dsp.put_no_rnd_qpel_pixels_tab;

        }



        if (s->mv_dir & MV_DIR_FORWARD) {

            MPV_motion(s, dest_y, dest_cb, dest_cr, 0, s->last_picture.data, op_pix, op_qpix);

            op_pix = s->dsp.avg_pixels_tab;

            op_qpix= s->dsp.avg_qpel_pixels_tab;

        }

        if (s->mv_dir & MV_DIR_BACKWARD) {

            MPV_motion(s, dest_y, dest_cb, dest_cr, 1, s->next_picture.data, op_pix, op_qpix);

        }



        if(s->flags&CODEC_FLAG_INTERLACED_DCT){

            int progressive_score, interlaced_score;



            s->interlaced_dct=0;

            progressive_score= s->dsp.ildct_cmp[0](s, dest_y           , ptr_y           , wrap_y, 8)

                              +s->dsp.ildct_cmp[0](s, dest_y + wrap_y*8, ptr_y + wrap_y*8, wrap_y, 8) - 400;



            if(s->avctx->ildct_cmp == FF_CMP_VSSE) progressive_score -= 400;



            if(progressive_score>0){

                interlaced_score = s->dsp.ildct_cmp[0](s, dest_y           , ptr_y           , wrap_y*2, 8)

                                  +s->dsp.ildct_cmp[0](s, dest_y + wrap_y  , ptr_y + wrap_y  , wrap_y*2, 8);



                if(progressive_score > interlaced_score){

                    s->interlaced_dct=1;



                    dct_offset= wrap_y;

                    wrap_y<<=1;

                    if (s->chroma_format == CHROMA_422)

                        wrap_c<<=1;

                }

            }

        }



        s->dsp.diff_pixels(s->block[0], ptr_y                 , dest_y                 , wrap_y);

        s->dsp.diff_pixels(s->block[1], ptr_y              + 8, dest_y              + 8, wrap_y);

        s->dsp.diff_pixels(s->block[2], ptr_y + dct_offset    , dest_y + dct_offset    , wrap_y);

        s->dsp.diff_pixels(s->block[3], ptr_y + dct_offset + 8, dest_y + dct_offset + 8, wrap_y);



        if(s->flags&CODEC_FLAG_GRAY){

            skip_dct[4]= 1;

            skip_dct[5]= 1;

        }else{

            s->dsp.diff_pixels(s->block[4], ptr_cb, dest_cb, wrap_c);

            s->dsp.diff_pixels(s->block[5], ptr_cr, dest_cr, wrap_c);

            if(!s->chroma_y_shift){ /* 422 */

                s->dsp.diff_pixels(s->block[6], ptr_cb + (dct_offset>>1), dest_cb + (dct_offset>>1), wrap_c);

                s->dsp.diff_pixels(s->block[7], ptr_cr + (dct_offset>>1), dest_cr + (dct_offset>>1), wrap_c);

            }

        }

        /* pre quantization */

        if(s->current_picture.mc_mb_var[s->mb_stride*mb_y+ mb_x]<2*s->qscale*s->qscale){

            //FIXME optimize

            if(s->dsp.sad[1](NULL, ptr_y               , dest_y               , wrap_y, 8) < 20*s->qscale) skip_dct[0]= 1;

            if(s->dsp.sad[1](NULL, ptr_y            + 8, dest_y            + 8, wrap_y, 8) < 20*s->qscale) skip_dct[1]= 1;

            if(s->dsp.sad[1](NULL, ptr_y +dct_offset   , dest_y +dct_offset   , wrap_y, 8) < 20*s->qscale) skip_dct[2]= 1;

            if(s->dsp.sad[1](NULL, ptr_y +dct_offset+ 8, dest_y +dct_offset+ 8, wrap_y, 8) < 20*s->qscale) skip_dct[3]= 1;

            if(s->dsp.sad[1](NULL, ptr_cb              , dest_cb              , wrap_c, 8) < 20*s->qscale) skip_dct[4]= 1;

            if(s->dsp.sad[1](NULL, ptr_cr              , dest_cr              , wrap_c, 8) < 20*s->qscale) skip_dct[5]= 1;

            if(!s->chroma_y_shift){ /* 422 */

                if(s->dsp.sad[1](NULL, ptr_cb +(dct_offset>>1), dest_cb +(dct_offset>>1), wrap_c, 8) < 20*s->qscale) skip_dct[6]= 1;

                if(s->dsp.sad[1](NULL, ptr_cr +(dct_offset>>1), dest_cr +(dct_offset>>1), wrap_c, 8) < 20*s->qscale) skip_dct[7]= 1;

            }

        }

    }



    if(s->avctx->quantizer_noise_shaping){

        if(!skip_dct[0]) get_visual_weight(weight[0], ptr_y                 , wrap_y);

        if(!skip_dct[1]) get_visual_weight(weight[1], ptr_y              + 8, wrap_y);

        if(!skip_dct[2]) get_visual_weight(weight[2], ptr_y + dct_offset    , wrap_y);

        if(!skip_dct[3]) get_visual_weight(weight[3], ptr_y + dct_offset + 8, wrap_y);

        if(!skip_dct[4]) get_visual_weight(weight[4], ptr_cb                , wrap_c);

        if(!skip_dct[5]) get_visual_weight(weight[5], ptr_cr                , wrap_c);

        if(!s->chroma_y_shift){ /* 422 */

            if(!skip_dct[6]) get_visual_weight(weight[6], ptr_cb + (dct_offset>>1), wrap_c);

            if(!skip_dct[7]) get_visual_weight(weight[7], ptr_cr + (dct_offset>>1), wrap_c);

        }

        memcpy(orig[0], s->block[0], sizeof(DCTELEM)*64*mb_block_count);

    }



    /* DCT & quantize */

    assert(s->out_format!=FMT_MJPEG || s->qscale==8);

    {

        for(i=0;i<mb_block_count;i++) {

            if(!skip_dct[i]){

                int overflow;

                s->block_last_index[i] = s->dct_quantize(s, s->block[i], i, s->qscale, &overflow);

            // FIXME we could decide to change to quantizer instead of clipping

            // JS: I don't think that would be a good idea it could lower quality instead

            //     of improve it. Just INTRADC clipping deserves changes in quantizer

                if (overflow) clip_coeffs(s, s->block[i], s->block_last_index[i]);

            }else

                s->block_last_index[i]= -1;

        }

        if(s->avctx->quantizer_noise_shaping){

            for(i=0;i<mb_block_count;i++) {

                if(!skip_dct[i]){

                    s->block_last_index[i] = dct_quantize_refine(s, s->block[i], weight[i], orig[i], i, s->qscale);

                }

            }

        }



        if(s->luma_elim_threshold && !s->mb_intra)

            for(i=0; i<4; i++)

                dct_single_coeff_elimination(s, i, s->luma_elim_threshold);

        if(s->chroma_elim_threshold && !s->mb_intra)

            for(i=4; i<mb_block_count; i++)

                dct_single_coeff_elimination(s, i, s->chroma_elim_threshold);



        if(s->flags & CODEC_FLAG_CBP_RD){

            for(i=0;i<mb_block_count;i++) {

                if(s->block_last_index[i] == -1)

                    s->coded_score[i]= INT_MAX/256;

            }

        }

    }



    if((s->flags&CODEC_FLAG_GRAY) && s->mb_intra){

        s->block_last_index[4]=

        s->block_last_index[5]= 0;

        s->block[4][0]=

        s->block[5][0]= (1024 + s->c_dc_scale/2)/ s->c_dc_scale;

    }



    //non c quantize code returns incorrect block_last_index FIXME

    if(s->alternate_scan && s->dct_quantize != dct_quantize_c){

        for(i=0; i<mb_block_count; i++){

            int j;

            if(s->block_last_index[i]>0){

                for(j=63; j>0; j--){

                    if(s->block[i][ s->intra_scantable.permutated[j] ]) break;

                }

                s->block_last_index[i]= j;

            }

        }

    }



    /* huffman encode */

    switch(s->codec_id){ //FIXME funct ptr could be slightly faster

    case CODEC_ID_MPEG1VIDEO:

    case CODEC_ID_MPEG2VIDEO:

        if (CONFIG_MPEG1VIDEO_ENCODER || CONFIG_MPEG2VIDEO_ENCODER)

            mpeg1_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_MPEG4:

        if (CONFIG_MPEG4_ENCODER)

            mpeg4_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_MSMPEG4V2:

    case CODEC_ID_MSMPEG4V3:

    case CODEC_ID_WMV1:

        if (CONFIG_MSMPEG4_ENCODER)

            msmpeg4_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_WMV2:

        if (CONFIG_WMV2_ENCODER)

            ff_wmv2_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_H261:

        if (CONFIG_H261_ENCODER)

            ff_h261_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_H263:

    case CODEC_ID_H263P:

    case CODEC_ID_FLV1:

    case CODEC_ID_RV10:

    case CODEC_ID_RV20:

        if (CONFIG_H263_ENCODER || CONFIG_H263P_ENCODER ||

            CONFIG_FLV_ENCODER  || CONFIG_RV10_ENCODER  || CONFIG_RV20_ENCODER)

            h263_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_MJPEG:

        if (CONFIG_MJPEG_ENCODER)

            ff_mjpeg_encode_mb(s, s->block);

        break;

    default:

        assert(0);

    }

}

static int dirac_unpack_idwt_params(DiracContext *s)

{

    GetBitContext *gb = &s->gb;

    int i, level;

    unsigned tmp;



#define CHECKEDREAD(dst, cond, errmsg) \

    tmp = svq3_get_ue_golomb(gb); \

    if (cond) { \

        av_log(s->avctx, AV_LOG_ERROR, errmsg); \

        return -1; \

    }\

    dst = tmp;



    align_get_bits(gb);



    s->zero_res = s->num_refs ? get_bits1(gb) : 0;

    if (s->zero_res)

        return 0;



    /*[DIRAC_STD] 11.3.1 Transform parameters. transform_parameters() */

    CHECKEDREAD(s->wavelet_idx, tmp > 6, "wavelet_idx is too big\n")



    CHECKEDREAD(s->wavelet_depth, tmp > MAX_DWT_LEVELS || tmp < 1, "invalid number of DWT decompositions\n")



    if (!s->low_delay) {

        /* Codeblock parameters (core syntax only) */

        if (get_bits1(gb)) {

            for (i = 0; i <= s->wavelet_depth; i++) {

                CHECKEDREAD(s->codeblock[i].width , tmp < 1, "codeblock width invalid\n")

                CHECKEDREAD(s->codeblock[i].height, tmp < 1, "codeblock height invalid\n")

            }



            CHECKEDREAD(s->codeblock_mode, tmp > 1, "unknown codeblock mode\n")

        } else

            for (i = 0; i <= s->wavelet_depth; i++)

                s->codeblock[i].width = s->codeblock[i].height = 1;

    } else {

        /* Slice parameters + quantization matrix*/

        /*[DIRAC_STD] 11.3.4 Slice coding Parameters (low delay syntax only). slice_parameters() */

        s->lowdelay.num_x     = svq3_get_ue_golomb(gb);

        s->lowdelay.num_y     = svq3_get_ue_golomb(gb);

        s->lowdelay.bytes.num = svq3_get_ue_golomb(gb);

        s->lowdelay.bytes.den = svq3_get_ue_golomb(gb);



        if (s->lowdelay.bytes.den <= 0) {

            av_log(s->avctx,AV_LOG_ERROR,"Invalid lowdelay.bytes.den\n");

            return AVERROR_INVALIDDATA;

        }



        /* [DIRAC_STD] 11.3.5 Quantisation matrices (low-delay syntax). quant_matrix() */

        if (get_bits1(gb)) {

            av_log(s->avctx,AV_LOG_DEBUG,"Low Delay: Has Custom Quantization Matrix!\n");

            /* custom quantization matrix */

            s->lowdelay.quant[0][0] = svq3_get_ue_golomb(gb);

            for (level = 0; level < s->wavelet_depth; level++) {

                s->lowdelay.quant[level][1] = svq3_get_ue_golomb(gb);

                s->lowdelay.quant[level][2] = svq3_get_ue_golomb(gb);

                s->lowdelay.quant[level][3] = svq3_get_ue_golomb(gb);

            }

        } else {

            if (s->wavelet_depth > 4) {

                av_log(s->avctx,AV_LOG_ERROR,"Mandatory custom low delay matrix missing for depth %d\n", s->wavelet_depth);

                return AVERROR_INVALIDDATA;

            }

            /* default quantization matrix */

            for (level = 0; level < s->wavelet_depth; level++)

                for (i = 0; i < 4; i++) {

                    s->lowdelay.quant[level][i] = default_qmat[s->wavelet_idx][level][i];

                    /* haar with no shift differs for different depths */

                    if (s->wavelet_idx == 3)

                        s->lowdelay.quant[level][i] += 4*(s->wavelet_depth-1 - level);

                }

        }

    }

    return 0;

}

