av_cold void swri_rematrix_init_x86(struct SwrContext *s){

    int mm_flags = av_get_cpu_flags();

    int nb_in  = av_get_channel_layout_nb_channels(s->in_ch_layout);

    int nb_out = av_get_channel_layout_nb_channels(s->out_ch_layout);

    int num    = nb_in * nb_out;

    int i,j;



    s->mix_1_1_simd = NULL;

    s->mix_2_1_simd = NULL;



    if (s->midbuf.fmt == AV_SAMPLE_FMT_S16P){

        if(mm_flags & AV_CPU_FLAG_MMX) {

            s->mix_1_1_simd = ff_mix_1_1_a_int16_mmx;

            s->mix_2_1_simd = ff_mix_2_1_a_int16_mmx;

        }

        if(mm_flags & AV_CPU_FLAG_SSE2) {

            s->mix_1_1_simd = ff_mix_1_1_a_int16_sse2;

            s->mix_2_1_simd = ff_mix_2_1_a_int16_sse2;

        }

        s->native_simd_matrix = av_mallocz(2 * num * sizeof(int16_t));

        s->native_simd_one    = av_mallocz(2 * sizeof(int16_t));

        for(i=0; i<nb_out; i++){

            int sh = 0;

            for(j=0; j<nb_in; j++)

                sh = FFMAX(sh, FFABS(((int*)s->native_matrix)[i * nb_in + j]));

            sh = FFMAX(av_log2(sh) - 14, 0);

            for(j=0; j<nb_in; j++) {

                ((int16_t*)s->native_simd_matrix)[2*(i * nb_in + j)+1] = 15 - sh;

                ((int16_t*)s->native_simd_matrix)[2*(i * nb_in + j)] =

                    ((((int*)s->native_matrix)[i * nb_in + j]) + (1<<sh>>1)) >> sh;

            }

        }

        ((int16_t*)s->native_simd_one)[1] = 14;

        ((int16_t*)s->native_simd_one)[0] = 16384;

    } else if(s->midbuf.fmt == AV_SAMPLE_FMT_FLTP){

        if(mm_flags & AV_CPU_FLAG_SSE) {

            s->mix_1_1_simd = ff_mix_1_1_a_float_sse;

            s->mix_2_1_simd = ff_mix_2_1_a_float_sse;

        }

        if(HAVE_AVX_EXTERNAL && mm_flags & AV_CPU_FLAG_AVX) {

            s->mix_1_1_simd = ff_mix_1_1_a_float_avx;

            s->mix_2_1_simd = ff_mix_2_1_a_float_avx;

        }

        s->native_simd_matrix = av_mallocz(num * sizeof(float));

        memcpy(s->native_simd_matrix, s->native_matrix, num * sizeof(float));

        s->native_simd_one = av_mallocz(sizeof(float));

        memcpy(s->native_simd_one, s->native_one, sizeof(float));

    }

}

static int check_jni_invocation(void *log_ctx)

{

    int ret = AVERROR_EXTERNAL;

    void *handle = NULL;

    void **jni_invocation = NULL;



    handle = dlopen(NULL, RTLD_LOCAL);

    if (!handle) {

        goto done;

    }



    jni_invocation = (void **)dlsym(handle, "_ZN13JniInvocation15jni_invocation_E");

    if (!jni_invocation) {

        av_log(log_ctx, AV_LOG_ERROR, "Could not find JniInvocation::jni_invocation_ symbol\n");

        goto done;

    }



    ret = !(jni_invocation != NULL && *jni_invocation != NULL);



done:

    if (handle) {

        dlclose(handle);

    }



    return ret;

}

static uint64_t pchip_read(void *opaque, hwaddr addr, unsigned size)

{

    TyphoonState *s = opaque;

    uint64_t ret = 0;



    if (addr & 4) {

        return s->latch_tmp;

    }



    switch (addr) {

    case 0x0000:

        /* WSBA0: Window Space Base Address Register.  */

        ret = s->pchip.win[0].base_addr;

        break;

    case 0x0040:

        /* WSBA1 */

        ret = s->pchip.win[1].base_addr;

        break;

    case 0x0080:

        /* WSBA2 */

        ret = s->pchip.win[2].base_addr;

        break;

    case 0x00c0:

        /* WSBA3 */

        ret = s->pchip.win[3].base_addr;

        break;



    case 0x0100:

        /* WSM0: Window Space Mask Register.  */

        ret = s->pchip.win[0].mask;

        break;

    case 0x0140:

        /* WSM1 */

        ret = s->pchip.win[1].mask;

        break;

    case 0x0180:

        /* WSM2 */

        ret = s->pchip.win[2].mask;

        break;

    case 0x01c0:

        /* WSM3 */

        ret = s->pchip.win[3].mask;

        break;



    case 0x0200:

        /* TBA0: Translated Base Address Register.  */

        ret = (uint64_t)s->pchip.win[0].translated_base_pfn << 10;

        break;

    case 0x0240:

        /* TBA1 */

        ret = (uint64_t)s->pchip.win[1].translated_base_pfn << 10;

        break;

    case 0x0280:

        /* TBA2 */

        ret = (uint64_t)s->pchip.win[2].translated_base_pfn << 10;

        break;

    case 0x02c0:

        /* TBA3 */

        ret = (uint64_t)s->pchip.win[3].translated_base_pfn << 10;

        break;



    case 0x0300:

        /* PCTL: Pchip Control Register.  */

        ret = s->pchip.ctl;

        break;

    case 0x0340:

        /* PLAT: Pchip Master Latency Register.  */

        break;

    case 0x03c0:

        /* PERROR: Pchip Error Register.  */

        break;

    case 0x0400:

        /* PERRMASK: Pchip Error Mask Register.  */

        break;

    case 0x0440:

        /* PERRSET: Pchip Error Set Register.  */

        break;

    case 0x0480:

        /* TLBIV: Translation Buffer Invalidate Virtual Register (WO).  */

        break;

    case 0x04c0:

        /* TLBIA: Translation Buffer Invalidate All Register (WO).  */

        break;

    case 0x0500: /* PMONCTL */

    case 0x0540: /* PMONCNT */

    case 0x0800: /* SPRST */

        break;



    default:

        cpu_unassigned_access(current_cpu, addr, false, false, 0, size);

        return -1;

    }



    s->latch_tmp = ret >> 32;

    return ret;

}

