static int get_cookies(HTTPContext *s, char **cookies, const char *path,

                       const char *domain)

{

    // cookie strings will look like Set-Cookie header field values.  Multiple

    // Set-Cookie fields will result in multiple values delimited by a newline

    int ret = 0;

    char *next, *cookie, *set_cookies = av_strdup(s->cookies), *cset_cookies = set_cookies;



    if (!set_cookies) return AVERROR(EINVAL);



    *cookies = NULL;

    while ((cookie = av_strtok(set_cookies, "\n", &next))) {

        int domain_offset = 0;

        char *param, *next_param, *cdomain = NULL, *cpath = NULL, *cvalue = NULL;

        set_cookies = NULL;



        while ((param = av_strtok(cookie, "; ", &next_param))) {

            cookie = NULL;

            if        (!av_strncasecmp("path=",   param, 5)) {


                cpath = av_strdup(&param[5]);

            } else if (!av_strncasecmp("domain=", param, 7)) {


                cdomain = av_strdup(&param[7]);

            } else if (!av_strncasecmp("secure",  param, 6) ||

                       !av_strncasecmp("comment", param, 7) ||

                       !av_strncasecmp("max-age", param, 7) ||

                       !av_strncasecmp("version", param, 7)) {

                // ignore Comment, Max-Age, Secure and Version

            } else {

                av_free(cvalue);

                cvalue = av_strdup(param);

            }

        }



        // ensure all of the necessary values are valid

        if (!cdomain || !cpath || !cvalue) {

            av_log(s, AV_LOG_WARNING,

                   "Invalid cookie found, no value, path or domain specified\n");

            goto done_cookie;

        }



        // check if the request path matches the cookie path

        if (av_strncasecmp(path, cpath, strlen(cpath)))

            goto done_cookie;



        // the domain should be at least the size of our cookie domain

        domain_offset = strlen(domain) - strlen(cdomain);

        if (domain_offset < 0)

            goto done_cookie;



        // match the cookie domain

        if (av_strcasecmp(&domain[domain_offset], cdomain))

            goto done_cookie;



        // cookie parameters match, so copy the value

        if (!*cookies) {

            if (!(*cookies = av_strdup(cvalue))) {

                ret = AVERROR(ENOMEM);

                goto done_cookie;

            }

        } else {

            char *tmp = *cookies;

            size_t str_size = strlen(cvalue) + strlen(*cookies) + 3;

            if (!(*cookies = av_malloc(str_size))) {

                ret = AVERROR(ENOMEM);

                goto done_cookie;

            }

            snprintf(*cookies, str_size, "%s; %s", tmp, cvalue);

            av_free(tmp);

        }



        done_cookie:



        av_free(cvalue);

        if (ret < 0) {

            if (*cookies) av_freep(cookies);

            av_free(cset_cookies);

            return ret;

        }

    }



    av_free(cset_cookies);



    return 0;

}

static void decode_mb(MadContext *t, int inter)

{

    MpegEncContext *s = &t->s;

    int mv_map = 0;

    int mv_x, mv_y;

    int j;



    if (inter) {

        int v = decode210(&s->gb);

        if (v < 2) {

            mv_map = v ? get_bits(&s->gb, 6) : 63;

            mv_x = decode_motion(&s->gb);

            mv_y = decode_motion(&s->gb);

        } else {

            mv_map = 0;

        }

    }



    for (j=0; j<6; j++) {

        if (mv_map & (1<<j)) {  // mv_x and mv_y are guarded by mv_map

            int add = 2*decode_motion(&s->gb);

            comp_block(t, s->mb_x, s->mb_y, j, mv_x, mv_y, add);

        } else {

            s->dsp.clear_block(t->block);

            decode_block_intra(t, t->block);

            idct_put(t, t->block, s->mb_x, s->mb_y, j);

        }

    }

}

void swr_compensate(struct SwrContext *s, int sample_delta, int compensation_distance){

    ResampleContext *c= s->resample;

//    sample_delta += (c->ideal_dst_incr - c->dst_incr)*(int64_t)c->compensation_distance / c->ideal_dst_incr;

    c->compensation_distance= compensation_distance;

    c->dst_incr = c->ideal_dst_incr - c->ideal_dst_incr * (int64_t)sample_delta / compensation_distance;

}

static int mov_write_moov_tag(ByteIOContext *pb, MOVContext *mov)

{

    int pos, i;

    pos = url_ftell(pb);

    put_be32(pb, 0); /* size placeholder*/

    put_tag(pb, "moov");

    mov->timescale = globalTimescale;



    for (i=0; i<MAX_STREAMS; i++) {

        if(mov->tracks[i].entry <= 0) continue;



        if(mov->tracks[i].enc->codec_type == CODEC_TYPE_VIDEO) {

            mov->tracks[i].timescale = mov->tracks[i].enc->frame_rate;

            mov->tracks[i].sampleDuration = mov->tracks[i].enc->frame_rate_base;

        }

        else if(mov->tracks[i].enc->codec_type == CODEC_TYPE_AUDIO) {

            /* If AMR, track timescale = 8000, AMR_WB = 16000 */

            if(mov->tracks[i].enc->codec_id == CODEC_ID_AMR_NB) {

                mov->tracks[i].sampleDuration = 160;  // Bytes per chunk

                mov->tracks[i].timescale = 8000;

            }

            else {

                mov->tracks[i].timescale = mov->tracks[i].enc->sample_rate;

                mov->tracks[i].sampleDuration = mov->tracks[i].enc->frame_size;

            }

        }



        mov->tracks[i].trackDuration = 

            mov->tracks[i].sampleCount * mov->tracks[i].sampleDuration;

        mov->tracks[i].time = mov->time;

        mov->tracks[i].trackID = i+1;

    }



    mov_write_mvhd_tag(pb, mov);

    //mov_write_iods_tag(pb, mov);

    for (i=0; i<MAX_STREAMS; i++) {

        if(mov->tracks[i].entry > 0) {

            mov_write_trak_tag(pb, &(mov->tracks[i]));

        }

    }



    return updateSize(pb, pos);

}

PCIBus *typhoon_init(ram_addr_t ram_size, ISABus **isa_bus,

                     qemu_irq *p_rtc_irq,

                     AlphaCPU *cpus[4], pci_map_irq_fn sys_map_irq)

{

    const uint64_t MB = 1024 * 1024;

    const uint64_t GB = 1024 * MB;

    MemoryRegion *addr_space = get_system_memory();

    DeviceState *dev;

    TyphoonState *s;

    PCIHostState *phb;

    PCIBus *b;

    int i;



    dev = qdev_create(NULL, TYPE_TYPHOON_PCI_HOST_BRIDGE);

    qdev_init_nofail(dev);



    s = TYPHOON_PCI_HOST_BRIDGE(dev);

    phb = PCI_HOST_BRIDGE(dev);



    /* Remember the CPUs so that we can deliver interrupts to them.  */

    for (i = 0; i < 4; i++) {

        AlphaCPU *cpu = cpus[i];

        s->cchip.cpu[i] = cpu;

        if (cpu != NULL) {

            cpu->alarm_timer = qemu_new_timer_ns(rtc_clock,

                                                 typhoon_alarm_timer,

                                                 (void *)((uintptr_t)s + i));

        }

    }



    *p_rtc_irq = *qemu_allocate_irqs(typhoon_set_timer_irq, s, 1);



    /* Main memory region, 0x00.0000.0000.  Real hardware supports 32GB,

       but the address space hole reserved at this point is 8TB.  */

    memory_region_init_ram(&s->ram_region, OBJECT(s), "ram", ram_size);

    vmstate_register_ram_global(&s->ram_region);

    memory_region_add_subregion(addr_space, 0, &s->ram_region);



    /* TIGbus, 0x801.0000.0000, 1GB.  */

    /* ??? The TIGbus is used for delivering interrupts, and access to

       the flash ROM.  I'm not sure that we need to implement it at all.  */



    /* Pchip0 CSRs, 0x801.8000.0000, 256MB.  */

    memory_region_init_io(&s->pchip.region, OBJECT(s), &pchip_ops, s, "pchip0",

                          256*MB);

    memory_region_add_subregion(addr_space, 0x80180000000ULL,

                                &s->pchip.region);



    /* Cchip CSRs, 0x801.A000.0000, 256MB.  */

    memory_region_init_io(&s->cchip.region, OBJECT(s), &cchip_ops, s, "cchip0",

                          256*MB);

    memory_region_add_subregion(addr_space, 0x801a0000000ULL,

                                &s->cchip.region);



    /* Dchip CSRs, 0x801.B000.0000, 256MB.  */

    memory_region_init_io(&s->dchip_region, OBJECT(s), &dchip_ops, s, "dchip0",

                          256*MB);

    memory_region_add_subregion(addr_space, 0x801b0000000ULL,

                                &s->dchip_region);



    /* Pchip0 PCI memory, 0x800.0000.0000, 4GB.  */

    memory_region_init(&s->pchip.reg_mem, OBJECT(s), "pci0-mem", 4*GB);

    memory_region_add_subregion(addr_space, 0x80000000000ULL,

                                &s->pchip.reg_mem);



    /* Pchip0 PCI I/O, 0x801.FC00.0000, 32MB.  */

    memory_region_init(&s->pchip.reg_io, OBJECT(s), "pci0-io", 32*MB);

    memory_region_add_subregion(addr_space, 0x801fc000000ULL,

                                &s->pchip.reg_io);



    b = pci_register_bus(dev, "pci",

                         typhoon_set_irq, sys_map_irq, s,

                         &s->pchip.reg_mem, &s->pchip.reg_io,

                         0, 64, TYPE_PCI_BUS);

    phb->bus = b;



    /* Pchip0 PCI special/interrupt acknowledge, 0x801.F800.0000, 64MB.  */

    memory_region_init_io(&s->pchip.reg_iack, OBJECT(s), &alpha_pci_iack_ops,

                          b, "pci0-iack", 64*MB);

    memory_region_add_subregion(addr_space, 0x801f8000000ULL,

                                &s->pchip.reg_iack);



    /* Pchip0 PCI configuration, 0x801.FE00.0000, 16MB.  */

    memory_region_init_io(&s->pchip.reg_conf, OBJECT(s), &alpha_pci_conf1_ops,

                          b, "pci0-conf", 16*MB);

    memory_region_add_subregion(addr_space, 0x801fe000000ULL,

                                &s->pchip.reg_conf);



    /* For the record, these are the mappings for the second PCI bus.

       We can get away with not implementing them because we indicate

       via the Cchip.CSC<PIP> bit that Pchip1 is not present.  */

    /* Pchip1 PCI memory, 0x802.0000.0000, 4GB.  */

    /* Pchip1 CSRs, 0x802.8000.0000, 256MB.  */

    /* Pchip1 PCI special/interrupt acknowledge, 0x802.F800.0000, 64MB.  */

    /* Pchip1 PCI I/O, 0x802.FC00.0000, 32MB.  */

    /* Pchip1 PCI configuration, 0x802.FE00.0000, 16MB.  */



    /* Init the ISA bus.  */

    /* ??? Technically there should be a cy82c693ub pci-isa bridge.  */

    {

        qemu_irq isa_pci_irq, *isa_irqs;



        *isa_bus = isa_bus_new(NULL, &s->pchip.reg_io);

        isa_pci_irq = *qemu_allocate_irqs(typhoon_set_isa_irq, s, 1);

        isa_irqs = i8259_init(*isa_bus, isa_pci_irq);

        isa_bus_irqs(*isa_bus, isa_irqs);

    }



    return b;

}

static int find_large_solid_color_rect(VncState *vs, int x, int y,

                                       int w, int h, int max_rows)

{

    int dx, dy, dw, dh;

    int n = 0;



    /* Try to find large solid-color areas and send them separately. */



    for (dy = y; dy < y + h; dy += VNC_TIGHT_MAX_SPLIT_TILE_SIZE) {



        /* If a rectangle becomes too large, send its upper part now. */



        if (dy - y >= max_rows) {

            n += send_rect_simple(vs, x, y, w, max_rows);

            y += max_rows;

            h -= max_rows;

        }



        dh = MIN(VNC_TIGHT_MAX_SPLIT_TILE_SIZE, (y + h - dy));



        for (dx = x; dx < x + w; dx += VNC_TIGHT_MAX_SPLIT_TILE_SIZE) {

            uint32_t color_value;

            int x_best, y_best, w_best, h_best;



            dw = MIN(VNC_TIGHT_MAX_SPLIT_TILE_SIZE, (x + w - dx));



            if (!check_solid_tile(vs, dx, dy, dw, dh, &color_value, false)) {

                continue ;

            }



            /* Get dimensions of solid-color area. */



            find_best_solid_area(vs, dx, dy, w - (dx - x), h - (dy - y),

                                 color_value, &w_best, &h_best);



            /* Make sure a solid rectangle is large enough

               (or the whole rectangle is of the same color). */



            if (w_best * h_best != w * h &&

                w_best * h_best < VNC_TIGHT_MIN_SOLID_SUBRECT_SIZE) {

                continue;

            }



            /* Try to extend solid rectangle to maximum size. */



            x_best = dx; y_best = dy;

            extend_solid_area(vs, x, y, w, h, color_value,

                              &x_best, &y_best, &w_best, &h_best);



            /* Send rectangles at top and left to solid-color area. */



            if (y_best != y) {

                n += send_rect_simple(vs, x, y, w, y_best-y);

            }

            if (x_best != x) {

                n += vnc_tight_send_framebuffer_update(vs, x, y_best,

                                                       x_best-x, h_best);

            }



            /* Send solid-color rectangle. */

            n += send_sub_rect_solid(vs, x_best, y_best, w_best, h_best);



            /* Send remaining rectangles (at right and bottom). */



            if (x_best + w_best != x + w) {

                n += vnc_tight_send_framebuffer_update(vs, x_best+w_best,

                                                       y_best,

                                                       w-(x_best-x)-w_best,

                                                       h_best);

            }

            if (y_best + h_best != y + h) {

                n += vnc_tight_send_framebuffer_update(vs, x, y_best+h_best,

                                                       w, h-(y_best-y)-h_best);

            }



            /* Return after all recursive calls are done. */

            return n;

        }

    }

    return n + send_rect_simple(vs, x, y, w, h);

}

static int decode_frame_header(NUTContext *nut, int64_t *pts, int *stream_id,

                               uint8_t *header_idx, int frame_code)

{

    AVFormatContext *s = nut->avf;

    AVIOContext *bc    = s->pb;

    StreamContext *stc;

    int size, flags, size_mul, pts_delta, i, reserved_count;

    uint64_t tmp;



    if (avio_tell(bc) > nut->last_syncpoint_pos + nut->max_distance) {

        av_log(s, AV_LOG_ERROR,

               "Last frame must have been damaged %"PRId64" > %"PRId64" + %d\n",

               avio_tell(bc), nut->last_syncpoint_pos, nut->max_distance);

        return AVERROR_INVALIDDATA;

    }



    flags          = nut->frame_code[frame_code].flags;

    size_mul       = nut->frame_code[frame_code].size_mul;

    size           = nut->frame_code[frame_code].size_lsb;

    *stream_id     = nut->frame_code[frame_code].stream_id;

    pts_delta      = nut->frame_code[frame_code].pts_delta;

    reserved_count = nut->frame_code[frame_code].reserved_count;

    *header_idx    = nut->frame_code[frame_code].header_idx;



    if (flags & FLAG_INVALID)

        return AVERROR_INVALIDDATA;

    if (flags & FLAG_CODED)

        flags ^= ffio_read_varlen(bc);

    if (flags & FLAG_STREAM_ID) {

        GET_V(*stream_id, tmp < s->nb_streams);

    }

    stc = &nut->stream[*stream_id];

    if (flags & FLAG_CODED_PTS) {

        int coded_pts = ffio_read_varlen(bc);

        // FIXME check last_pts validity?

        if (coded_pts < (1 << stc->msb_pts_shift)) {

            *pts = ff_lsb2full(stc, coded_pts);

        } else

            *pts = coded_pts - (1 << stc->msb_pts_shift);

    } else

        *pts = stc->last_pts + pts_delta;

    if (flags & FLAG_SIZE_MSB)

        size += size_mul * ffio_read_varlen(bc);

    if (flags & FLAG_MATCH_TIME)

        get_s(bc);

    if (flags & FLAG_HEADER_IDX)

        *header_idx = ffio_read_varlen(bc);

    if (flags & FLAG_RESERVED)

        reserved_count = ffio_read_varlen(bc);

    for (i = 0; i < reserved_count; i++)

        ffio_read_varlen(bc);



    if (*header_idx >= (unsigned)nut->header_count) {

        av_log(s, AV_LOG_ERROR, "header_idx invalid\n");

        return AVERROR_INVALIDDATA;

    }

    if (size > 4096)

        *header_idx = 0;

    size -= nut->header_len[*header_idx];



    if (flags & FLAG_CHECKSUM) {

        avio_rb32(bc); // FIXME check this

    } else if (size > 2 * nut->max_distance || FFABS(stc->last_pts - *pts) >

               stc->max_pts_distance) {

        av_log(s, AV_LOG_ERROR, "frame size > 2max_distance and no checksum\n");

        return AVERROR_INVALIDDATA;

    }



    stc->last_pts   = *pts;

    stc->last_flags = flags;



    return size;

}

static int nfs_parse_uri(const char *filename, QDict *options, Error **errp)

{

    URI *uri = NULL;

    QueryParams *qp = NULL;

    int ret = -EINVAL, i;



    uri = uri_parse(filename);

    if (!uri) {

        error_setg(errp, "Invalid URI specified");

        goto out;

    }

    if (strcmp(uri->scheme, "nfs") != 0) {

        error_setg(errp, "URI scheme must be 'nfs'");

        goto out;

    }



    if (!uri->server) {

        error_setg(errp, "missing hostname in URI");

        goto out;

    }



    if (!uri->path) {

        error_setg(errp, "missing file path in URI");

        goto out;

    }



    qp = query_params_parse(uri->query);

    if (!qp) {

        error_setg(errp, "could not parse query parameters");

        goto out;

    }



    qdict_put(options, "server.host", qstring_from_str(uri->server));

    qdict_put(options, "server.type", qstring_from_str("inet"));

    qdict_put(options, "path", qstring_from_str(uri->path));



    for (i = 0; i < qp->n; i++) {

        if (!qp->p[i].value) {

            error_setg(errp, "Value for NFS parameter expected: %s",

                       qp->p[i].name);

            goto out;

        }

        if (parse_uint_full(qp->p[i].value, NULL, 0)) {

            error_setg(errp, "Illegal value for NFS parameter: %s",

                       qp->p[i].name);

            goto out;

        }

        if (!strcmp(qp->p[i].name, "uid")) {

            qdict_put(options, "user",

                      qstring_from_str(qp->p[i].value));

        } else if (!strcmp(qp->p[i].name, "gid")) {

            qdict_put(options, "group",

                      qstring_from_str(qp->p[i].value));

        } else if (!strcmp(qp->p[i].name, "tcp-syncnt")) {

            qdict_put(options, "tcp-syn-count",

                      qstring_from_str(qp->p[i].value));

        } else if (!strcmp(qp->p[i].name, "readahead")) {

            qdict_put(options, "readahead-size",

                      qstring_from_str(qp->p[i].value));

        } else if (!strcmp(qp->p[i].name, "pagecache")) {

            qdict_put(options, "page-cache-size",

                      qstring_from_str(qp->p[i].value));

        } else if (!strcmp(qp->p[i].name, "debug")) {

            qdict_put(options, "debug",

                      qstring_from_str(qp->p[i].value));

        } else {

            error_setg(errp, "Unknown NFS parameter name: %s",

                       qp->p[i].name);

            goto out;

        }

    }

    ret = 0;

out:

    if (qp) {

        query_params_free(qp);

    }

    if (uri) {

        uri_free(uri);

    }

    return ret;

}

static int format_name(char *buf, int buf_len, int index)

{

    const char *proto, *dir;

    char *orig_buf_dup = NULL, *mod_buf_dup = NULL;

    int ret = 0;



    if (!av_stristr(buf, "%v"))

        return ret;



    orig_buf_dup = av_strdup(buf);

    if (!orig_buf_dup) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    if (replace_int_data_in_filename(buf, buf_len, orig_buf_dup, 'v', index) < 1) {

        ret = AVERROR(EINVAL);

        goto fail;

    }



    proto = avio_find_protocol_name(orig_buf_dup);

    dir = av_dirname(orig_buf_dup);



    /* if %v is present in the file's directory, create sub-directory */

    if (av_stristr(dir, "%v") && proto && !strcmp(proto, "file")) {

        mod_buf_dup = av_strdup(buf);

        if (!mod_buf_dup) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        dir = av_dirname(mod_buf_dup);

        if (mkdir_p(dir) == -1 && errno != EEXIST) {

            ret = AVERROR(errno);

            goto fail;

        }

    }



fail:

    av_freep(&orig_buf_dup);

    av_freep(&mod_buf_dup);

    return ret;

}

static void new_audio_stream(AVFormatContext *oc, int file_idx)

{

    AVStream *st;

    OutputStream *ost;

    AVCodec *codec= NULL;

    AVCodecContext *audio_enc;

    enum CodecID codec_id = CODEC_ID_NONE;



    if(!audio_stream_copy){

        if (audio_codec_name) {

            codec_id = find_codec_or_die(audio_codec_name, AVMEDIA_TYPE_AUDIO, 1,

                                         avcodec_opts[AVMEDIA_TYPE_AUDIO]->strict_std_compliance);

            codec = avcodec_find_encoder_by_name(audio_codec_name);

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_AUDIO);

            codec = avcodec_find_encoder(codec_id);

        }

    }

    ost = new_output_stream(oc, file_idx, codec);

    st  = ost->st;



    ost->bitstream_filters = audio_bitstream_filters;

    audio_bitstream_filters= NULL;



    st->codec->thread_count= thread_count;



    audio_enc = st->codec;

    audio_enc->codec_type = AVMEDIA_TYPE_AUDIO;



    if(audio_codec_tag)

        audio_enc->codec_tag= audio_codec_tag;



    if (oc->oformat->flags & AVFMT_GLOBALHEADER) {

        audio_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

    }

    if (audio_stream_copy) {

        st->stream_copy = 1;

    } else {

        audio_enc->codec_id = codec_id;

        set_context_opts(audio_enc, avcodec_opts[AVMEDIA_TYPE_AUDIO], AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);



        if (audio_qscale > QSCALE_NONE) {

            audio_enc->flags |= CODEC_FLAG_QSCALE;

            audio_enc->global_quality = FF_QP2LAMBDA * audio_qscale;

        }

        if (audio_channels)

            audio_enc->channels = audio_channels;

        if (audio_sample_fmt != AV_SAMPLE_FMT_NONE)

            audio_enc->sample_fmt = audio_sample_fmt;

        if (audio_sample_rate)

            audio_enc->sample_rate = audio_sample_rate;

    }

    if (audio_language) {

        av_dict_set(&st->metadata, "language", audio_language, 0);

        av_freep(&audio_language);

    }



    /* reset some key parameters */

    audio_disable = 0;

    av_freep(&audio_codec_name);

    audio_stream_copy = 0;

}

static int vfio_container_do_ioctl(AddressSpace *as, int32_t groupid,

                                   int req, void *param)

{

    VFIOGroup *group;

    VFIOContainer *container;

    int ret = -1;



    group = vfio_get_group(groupid, as);

    if (!group) {

        error_report("vfio: group %d not registered", groupid);

        return ret;

    }



    container = group->container;

    if (group->container) {

        ret = ioctl(container->fd, req, param);

        if (ret < 0) {

            error_report("vfio: failed to ioctl %d to container: ret=%d, %s",

                         _IOC_NR(req) - VFIO_BASE, ret, strerror(errno));

        }

    }



    vfio_put_group(group);



    return ret;

}

