static ssize_t socket_read(int sockfd, void *buff, size_t size)

{

    ssize_t retval, total = 0;



    while (size) {

        retval = read(sockfd, buff, size);

        if (retval == 0) {

            return -EIO;

        }

        if (retval < 0) {

            if (errno == EINTR) {

                continue;

            }

            return -errno;

        }

        size -= retval;

        buff += retval;

        total += retval;

    }

    return total;

}

static int recover(WtvContext *wtv, uint64_t broken_pos)

{

    AVIOContext *pb = wtv->pb;

    int i;

    for (i = 0; i < wtv->nb_index_entries; i++) {

        if (wtv->index_entries[i].pos > broken_pos) {

            int ret = avio_seek(pb, wtv->index_entries[i].pos, SEEK_SET);

            if (ret < 0)

                return ret;

            wtv->pts = wtv->index_entries[i].timestamp;

            return 0;

         }

     }

     return AVERROR(EIO);

}

int qemu_savevm_state_complete(QEMUFile *f)

{

    SaveStateEntry *se;



    TAILQ_FOREACH(se, &savevm_handlers, entry) {

        if (se->save_live_state == NULL)

            continue;



        /* Section type */

        qemu_put_byte(f, QEMU_VM_SECTION_END);

        qemu_put_be32(f, se->section_id);



        se->save_live_state(f, QEMU_VM_SECTION_END, se->opaque);

    }



    TAILQ_FOREACH(se, &savevm_handlers, entry) {

        int len;



	if (se->save_state == NULL && se->vmsd == NULL)

	    continue;



        /* Section type */

        qemu_put_byte(f, QEMU_VM_SECTION_FULL);

        qemu_put_be32(f, se->section_id);



        /* ID string */

        len = strlen(se->idstr);

        qemu_put_byte(f, len);

        qemu_put_buffer(f, (uint8_t *)se->idstr, len);



        qemu_put_be32(f, se->instance_id);

        qemu_put_be32(f, se->version_id);



        vmstate_save(f, se);

    }



    qemu_put_byte(f, QEMU_VM_EOF);



    if (qemu_file_has_error(f))

        return -EIO;



    return 0;

}

