void parse_numa_opts(MachineState *ms)

{

    int i;

    const CPUArchIdList *possible_cpus;

    MachineClass *mc = MACHINE_GET_CLASS(ms);



    for (i = 0; i < MAX_NODES; i++) {

        numa_info[i].node_cpu = bitmap_new(max_cpus);

    }



    if (qemu_opts_foreach(qemu_find_opts("numa"), parse_numa, ms, NULL)) {

        exit(1);

    }



    assert(max_numa_nodeid <= MAX_NODES);



    /* No support for sparse NUMA node IDs yet: */

    for (i = max_numa_nodeid - 1; i >= 0; i--) {

        /* Report large node IDs first, to make mistakes easier to spot */

        if (!numa_info[i].present) {

            error_report("numa: Node ID missing: %d", i);

            exit(1);

        }

    }



    /* This must be always true if all nodes are present: */

    assert(nb_numa_nodes == max_numa_nodeid);



    if (nb_numa_nodes > 0) {

        uint64_t numa_total;



        if (nb_numa_nodes > MAX_NODES) {

            nb_numa_nodes = MAX_NODES;

        }



        /* If no memory size is given for any node, assume the default case

         * and distribute the available memory equally across all nodes

         */

        for (i = 0; i < nb_numa_nodes; i++) {

            if (numa_info[i].node_mem != 0) {

                break;

            }

        }

        if (i == nb_numa_nodes) {

            assert(mc->numa_auto_assign_ram);

            mc->numa_auto_assign_ram(mc, numa_info, nb_numa_nodes, ram_size);

        }



        numa_total = 0;

        for (i = 0; i < nb_numa_nodes; i++) {

            numa_total += numa_info[i].node_mem;

        }

        if (numa_total != ram_size) {

            error_report("total memory for NUMA nodes (0x%" PRIx64 ")"

                         " should equal RAM size (0x" RAM_ADDR_FMT ")",

                         numa_total, ram_size);

            exit(1);

        }



        for (i = 0; i < nb_numa_nodes; i++) {

            QLIST_INIT(&numa_info[i].addr);

        }



        numa_set_mem_ranges();



        /* assign CPUs to nodes using board provided default mapping */

        if (!mc->cpu_index_to_instance_props || !mc->possible_cpu_arch_ids) {

            error_report("default CPUs to NUMA node mapping isn't supported");

            exit(1);

        }



        possible_cpus = mc->possible_cpu_arch_ids(ms);

        for (i = 0; i < possible_cpus->len; i++) {

            if (possible_cpus->cpus[i].props.has_node_id) {

                break;

            }

        }



        /* no CPUs are assigned to NUMA nodes */

        if (i == possible_cpus->len) {

            for (i = 0; i < max_cpus; i++) {

                CpuInstanceProperties props;

                /* fetch default mapping from board and enable it */

                props = mc->cpu_index_to_instance_props(ms, i);

                props.has_node_id = true;



                set_bit(i, numa_info[props.node_id].node_cpu);

                machine_set_cpu_numa_node(ms, &props, &error_fatal);

            }

        }



        validate_numa_cpus();



        /* QEMU needs at least all unique node pair distances to build

         * the whole NUMA distance table. QEMU treats the distance table

         * as symmetric by default, i.e. distance A->B == distance B->A.

         * Thus, QEMU is able to complete the distance table

         * initialization even though only distance A->B is provided and

         * distance B->A is not. QEMU knows the distance of a node to

         * itself is always 10, so A->A distances may be omitted. When

         * the distances of two nodes of a pair differ, i.e. distance

         * A->B != distance B->A, then that means the distance table is

         * asymmetric. In this case, the distances for both directions

         * of all node pairs are required.

         */

        if (have_numa_distance) {

            /* Validate enough NUMA distance information was provided. */

            validate_numa_distance();



            /* Validation succeeded, now fill in any missing distances. */

            complete_init_numa_distance();

        }

    } else {

        numa_set_mem_node_id(0, ram_size, 0);

    }

}

static void vp3_draw_horiz_band(Vp3DecodeContext *s, int y)

{

    int h, cy, i;

    int offset[AV_NUM_DATA_POINTERS];



    if (HAVE_THREADS && s->avctx->active_thread_type & FF_THREAD_FRAME) {

        int y_flipped = s->flipped_image ? s->avctx->height - y : y;



        /* At the end of the frame, report INT_MAX instead of the height of

         * the frame. This makes the other threads' ff_thread_await_progress()

         * calls cheaper, because they don't have to clip their values. */

        ff_thread_report_progress(&s->current_frame,

                                  y_flipped == s->avctx->height ? INT_MAX

                                                                : y_flipped - 1,

                                  0);

    }



    if (s->avctx->draw_horiz_band == NULL)

        return;



    h = y - s->last_slice_end;

    s->last_slice_end = y;

    y -= h;



    if (!s->flipped_image)

        y = s->avctx->height - y - h;



    cy        = y >> s->chroma_y_shift;

    offset[0] = s->current_frame.f->linesize[0] * y;

    offset[1] = s->current_frame.f->linesize[1] * cy;

    offset[2] = s->current_frame.f->linesize[2] * cy;

    for (i = 3; i < AV_NUM_DATA_POINTERS; i++)

        offset[i] = 0;



    emms_c();

    s->avctx->draw_horiz_band(s->avctx, s->current_frame.f, offset, y, 3, h);

}

