static inline void RENAME(rgb24tobgr15)(const uint8_t *src, uint8_t *dst, int src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

    const uint8_t *mm_end;

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_15mask),"m"(green_15mask));

    mm_end = end - 11;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         3%1, %%mm3    \n\t"

            "punpckldq    6%1, %%mm0    \n\t"

            "punpckldq    9%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psrlq         $3, %%mm0    \n\t"

            "psrlq         $3, %%mm3    \n\t"

            "pand          %2, %%mm0    \n\t"

            "pand          %2, %%mm3    \n\t"

            "psrlq         $6, %%mm1    \n\t"

            "psrlq         $6, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq         $9, %%mm2    \n\t"

            "psrlq         $9, %%mm5    \n\t"

            "pand       %%mm7, %%mm2    \n\t"

            "pand       %%mm7, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

        d += 4;

        s += 12;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

    while (s < end) {

        const int b = *s++;

        const int g = *s++;

        const int r = *s++;

        *d++ = (b>>3) | ((g&0xF8)<<2) | ((r&0xF8)<<7);

    }

}

static int ir2_decode_plane_inter(Ir2Context *ctx, int width, int height, uint8_t *dst,

                                  int pitch, const uint8_t *table)

{

    int j;

    int out = 0;

    int c;

    int t;



    if (width & 1)




    for (j = 0; j < height; j++) {

        out = 0;



        while (out < width) {

            c = ir2_get_code(&ctx->gb);

            if (c >= 0x80) { /* we have a skip */

                c   -= 0x7F;

                out += c * 2;

            } else { /* add two deltas from table */

                t        = dst[out] + (((table[c * 2] - 128)*3) >> 2);

                t        = av_clip_uint8(t);

                dst[out] = t;

                out++;

                t        = dst[out] + (((table[(c * 2) + 1] - 128)*3) >> 2);

                t        = av_clip_uint8(t);

                dst[out] = t;

                out++;

            }

        }

        dst += pitch;

    }

    return 0;

}

int cpu_watchpoint_remove(CPUState *env, target_ulong addr, target_ulong len,

                          int flags)

{

    target_ulong len_mask = ~(len - 1);

    CPUWatchpoint *wp;



    TAILQ_FOREACH(wp, &env->watchpoints, entry) {

        if (addr == wp->vaddr && len_mask == wp->len_mask

                && flags == (wp->flags & ~BP_WATCHPOINT_HIT)) {

            cpu_watchpoint_remove_by_ref(env, wp);

            return 0;

        }

    }

    return -ENOENT;

}

static int fill_note_info(struct elf_note_info *info,

    long signr, const CPUState *env)

{

#define NUMNOTES 3

    CPUState *cpu = NULL;

    TaskState *ts = (TaskState *)env->opaque;

    int i;



    (void) memset(info, 0, sizeof (*info));



    TAILQ_INIT(&info->thread_list);



    info->notes = qemu_mallocz(NUMNOTES * sizeof (struct memelfnote));

    if (info->notes == NULL)

        return (-ENOMEM);

    info->prstatus = qemu_mallocz(sizeof (*info->prstatus));

    if (info->prstatus == NULL)

        return (-ENOMEM);

    info->psinfo = qemu_mallocz(sizeof (*info->psinfo));

    if (info->prstatus == NULL)

        return (-ENOMEM);



    /*

     * First fill in status (and registers) of current thread

     * including process info & aux vector.

     */

    fill_prstatus(info->prstatus, ts, signr);

    elf_core_copy_regs(&info->prstatus->pr_reg, env);

    fill_note(&info->notes[0], "CORE", NT_PRSTATUS,

        sizeof (*info->prstatus), info->prstatus);

    fill_psinfo(info->psinfo, ts);

    fill_note(&info->notes[1], "CORE", NT_PRPSINFO,

        sizeof (*info->psinfo), info->psinfo);

    fill_auxv_note(&info->notes[2], ts);

    info->numnote = 3;



    info->notes_size = 0;

    for (i = 0; i < info->numnote; i++)

        info->notes_size += note_size(&info->notes[i]);



    /* read and fill status of all threads */

    cpu_list_lock();

    for (cpu = first_cpu; cpu != NULL; cpu = cpu->next_cpu) {

        if (cpu == thread_env)

            continue;

        fill_thread_info(info, cpu);

    }

    cpu_list_unlock();



    return (0);

}

theora_header (AVFormatContext * s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    AVStream *st = s->streams[idx];

    struct theora_params *thp = os->private;

    int cds = st->codec->extradata_size + os->psize + 2;

    uint8_t *cdp;



    if(!(os->buf[os->pstart] & 0x80))

        return 0;



    if(!thp){

        thp = av_mallocz(sizeof(*thp));

        os->private = thp;




    if (os->buf[os->pstart] == 0x80) {

        GetBitContext gb;

        int width, height;



        init_get_bits(&gb, os->buf + os->pstart, os->psize*8);



        skip_bits_long(&gb, 7*8); /* 0x80"theora" */



        thp->version = get_bits_long(&gb, 24);

        if (thp->version < 0x030100)

        {

            av_log(s, AV_LOG_ERROR,

                "Too old or unsupported Theora (%x)\n", thp->version);

            return -1;




        width  = get_bits(&gb, 16) << 4;

        height = get_bits(&gb, 16) << 4;

        avcodec_set_dimensions(st->codec, width, height);



        if (thp->version >= 0x030400)

            skip_bits(&gb, 100);



        if (thp->version >= 0x030200) {

            width  = get_bits_long(&gb, 24);

            height = get_bits_long(&gb, 24);

            if (   width  <= st->codec->width  && width  > st->codec->width-16

                && height <= st->codec->height && height > st->codec->height-16)

                avcodec_set_dimensions(st->codec, width, height);



            skip_bits(&gb, 16);


        st->codec->time_base.den = get_bits_long(&gb, 32);

        st->codec->time_base.num = get_bits_long(&gb, 32);






        st->time_base = st->codec->time_base;



        st->sample_aspect_ratio.num = get_bits_long(&gb, 24);

        st->sample_aspect_ratio.den = get_bits_long(&gb, 24);



        if (thp->version >= 0x030200)

            skip_bits_long(&gb, 38);

        if (thp->version >= 0x304000)

            skip_bits(&gb, 2);



        thp->gpshift = get_bits(&gb, 5);

        thp->gpmask = (1 << thp->gpshift) - 1;



        st->codec->codec_type = CODEC_TYPE_VIDEO;

        st->codec->codec_id = CODEC_ID_THEORA;



    } else if (os->buf[os->pstart] == 0x83) {

        vorbis_comment (s, os->buf + os->pstart + 7, os->psize - 8);




    st->codec->extradata = av_realloc (st->codec->extradata,

                                       cds + FF_INPUT_BUFFER_PADDING_SIZE);

    cdp = st->codec->extradata + st->codec->extradata_size;

    *cdp++ = os->psize >> 8;

    *cdp++ = os->psize & 0xff;

    memcpy (cdp, os->buf + os->pstart, os->psize);

    st->codec->extradata_size = cds;



    return 1;

int target_munmap(target_ulong start, target_ulong len)

{

    target_ulong end, real_start, real_end, addr;

    int prot, ret;



#ifdef DEBUG_MMAP

    printf("munmap: start=0x%lx len=0x%lx\n", start, len);

#endif

    if (start & ~TARGET_PAGE_MASK)

        return -EINVAL;

    len = TARGET_PAGE_ALIGN(len);

    if (len == 0)

        return -EINVAL;

    end = start + len;

    real_start = start & qemu_host_page_mask;

    real_end = HOST_PAGE_ALIGN(end);



    if (start > real_start) {

        /* handle host page containing start */

        prot = 0;

        for(addr = real_start; addr < start; addr += TARGET_PAGE_SIZE) {

            prot |= page_get_flags(addr);

        }

        if (real_end == real_start + qemu_host_page_size) {

            for(addr = end; addr < real_end; addr += TARGET_PAGE_SIZE) {

                prot |= page_get_flags(addr);

            }

            end = real_end;

        }

        if (prot != 0)

            real_start += qemu_host_page_size;

    }

    if (end < real_end) {

        prot = 0;

        for(addr = end; addr < real_end; addr += TARGET_PAGE_SIZE) {

            prot |= page_get_flags(addr);

        }

        if (prot != 0)

            real_end -= qemu_host_page_size;

    }



    /* unmap what we can */

    if (real_start < real_end) {

        ret = munmap((void *)real_start, real_end - real_start);

        if (ret != 0)

            return ret;

    }



    page_set_flags(start, start + len, 0);

    return 0;

}

static int thp_read_packet(AVFormatContext *s,

                            AVPacket *pkt)

{

    ThpDemuxContext *thp = s->priv_data;

    AVIOContext *pb = s->pb;

    unsigned int size;

    int ret;



    if (thp->audiosize == 0) {

        /* Terminate when last frame is reached.  */

        if (thp->frame >= thp->framecnt)

            return AVERROR_EOF;



        avio_seek(pb, thp->next_frame, SEEK_SET);



        /* Locate the next frame and read out its size.  */

        thp->next_frame += FFMAX(thp->next_framesz, 1);

        thp->next_framesz = avio_rb32(pb);



                        avio_rb32(pb); /* Previous total size.  */

        size          = avio_rb32(pb); /* Total size of this frame.  */



        /* Store the audiosize so the next time this function is called,

           the audio can be read.  */

        if (thp->has_audio)

            thp->audiosize = avio_rb32(pb); /* Audio size.  */

        else

            thp->frame++;



        ret = av_get_packet(pb, pkt, size);



        if (ret != size) {

            av_free_packet(pkt);

            return AVERROR(EIO);

        }



        pkt->stream_index = thp->video_stream_index;

    } else {

        ret = av_get_packet(pb, pkt, thp->audiosize);



        if (ret != thp->audiosize) {

            av_free_packet(pkt);

            return AVERROR(EIO);

        }



        pkt->stream_index = thp->audio_stream_index;

        if (thp->audiosize >= 8)

            pkt->duration = AV_RB32(&pkt->data[4]);



        thp->audiosize = 0;

        thp->frame++;

    }



    return 0;

}

static void guess_mv(ERContext *s)

{

    uint8_t *fixed = s->er_temp_buffer;

#define MV_FROZEN    3

#define MV_CHANGED   2

#define MV_UNCHANGED 1

    const int mb_stride = s->mb_stride;

    const int mb_width  = s->mb_width;

    const int mb_height = s->mb_height;

    int i, depth, num_avail;

    int mb_x, mb_y, mot_step, mot_stride;



    set_mv_strides(s, &mot_step, &mot_stride);



    num_avail = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int f = 0;

        int error = s->error_status_table[mb_xy];



        if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

            f = MV_FROZEN; // intra // FIXME check

        if (!(error & ER_MV_ERROR))

            f = MV_FROZEN; // inter with undamaged MV



        fixed[mb_xy] = f;

        if (f == MV_FROZEN)

            num_avail++;

    }



    if ((!(s->avctx->error_concealment&FF_EC_GUESS_MVS)) ||

        num_avail <= mb_width / 2) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                const int mb_xy = mb_x + mb_y * s->mb_stride;

                int mv_dir = (s->last_pic.f && s->last_pic.f->data[0]) ? MV_DIR_FORWARD : MV_DIR_BACKWARD;



                if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

                    continue;

                if (!(s->error_status_table[mb_xy] & ER_MV_ERROR))

                    continue;



                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->decode_mb(s->opaque, 0, mv_dir, MV_TYPE_16X16, &s->mv,

                             mb_x, mb_y, 0, 0);

            }

        }

        return;

    }



    for (depth = 0; ; depth++) {

        int changed, pass, none_left;



        none_left = 1;

        changed   = 1;

        for (pass = 0; (changed || pass < 2) && pass < 10; pass++) {

            int mb_x, mb_y;

            int score_sum = 0;



            changed = 0;

            for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

                for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                    const int mb_xy        = mb_x + mb_y * s->mb_stride;

                    int mv_predictor[8][2] = { { 0 } };

                    int ref[8]             = { 0 };

                    int pred_count         = 0;

                    int j;

                    int best_score         = 256 * 256 * 256 * 64;

                    int best_pred          = 0;

                    const int mot_index    = (mb_x + mb_y * mot_stride) * mot_step;

                    int prev_x, prev_y, prev_ref;



                    if ((mb_x ^ mb_y ^ pass) & 1)

                        continue;



                    if (fixed[mb_xy] == MV_FROZEN)

                        continue;

                    assert(!IS_INTRA(s->cur_pic.mb_type[mb_xy]));

                    assert(s->last_pic && s->last_pic.f->data[0]);



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_FROZEN)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_FROZEN)

                        j = 1;

                    if (j == 0)

                        continue;



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_CHANGED)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_CHANGED)

                        j = 1;

                    if (j == 0 && pass > 1)

                        continue;



                    none_left = 0;



                    if (mb_x > 0 && fixed[mb_xy - 1]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index - mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index - mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy - 1)];

                        pred_count++;

                    }

                    if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index + mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index + mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy + 1)];

                        pred_count++;

                    }

                    if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index - mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index - mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy - s->mb_stride)];

                        pred_count++;

                    }

                    if (mb_y + 1<mb_height && fixed[mb_xy + mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index + mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index + mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy + s->mb_stride)];

                        pred_count++;

                    }

                    if (pred_count == 0)

                        continue;



                    if (pred_count > 1) {

                        int sum_x = 0, sum_y = 0, sum_r = 0;

                        int max_x, max_y, min_x, min_y, max_r, min_r;



                        for (j = 0; j < pred_count; j++) {

                            sum_x += mv_predictor[j][0];

                            sum_y += mv_predictor[j][1];

                            sum_r += ref[j];

                            if (j && ref[j] != ref[j - 1])

                                goto skip_mean_and_median;

                        }



                        /* mean */

                        mv_predictor[pred_count][0] = sum_x / j;

                        mv_predictor[pred_count][1] = sum_y / j;

                                 ref[pred_count]    = sum_r / j;



                        /* median */

                        if (pred_count >= 3) {

                            min_y = min_x = min_r =  99999;

                            max_y = max_x = max_r = -99999;

                        } else {

                            min_x = min_y = max_x = max_y = min_r = max_r = 0;

                        }

                        for (j = 0; j < pred_count; j++) {

                            max_x = FFMAX(max_x, mv_predictor[j][0]);

                            max_y = FFMAX(max_y, mv_predictor[j][1]);

                            max_r = FFMAX(max_r, ref[j]);

                            min_x = FFMIN(min_x, mv_predictor[j][0]);

                            min_y = FFMIN(min_y, mv_predictor[j][1]);

                            min_r = FFMIN(min_r, ref[j]);

                        }

                        mv_predictor[pred_count + 1][0] = sum_x - max_x - min_x;

                        mv_predictor[pred_count + 1][1] = sum_y - max_y - min_y;

                                 ref[pred_count + 1]    = sum_r - max_r - min_r;



                        if (pred_count == 4) {

                            mv_predictor[pred_count + 1][0] /= 2;

                            mv_predictor[pred_count + 1][1] /= 2;

                                     ref[pred_count + 1]    /= 2;

                        }

                        pred_count += 2;

                    }



skip_mean_and_median:

                    /* zero MV */

                    pred_count++;



                    if (!fixed[mb_xy]) {

                        if (s->avctx->codec_id == AV_CODEC_ID_H264) {

                            // FIXME

                        } else {

                            ff_thread_await_progress(s->last_pic.tf,

                                                     mb_y, 0);

                        }

                        if (!s->last_pic.motion_val[0] ||

                            !s->last_pic.ref_index[0])

                            goto skip_last_mv;

                        prev_x   = s->last_pic.motion_val[0][mot_index][0];

                        prev_y   = s->last_pic.motion_val[0][mot_index][1];

                        prev_ref = s->last_pic.ref_index[0][4 * mb_xy];

                    } else {

                        prev_x   = s->cur_pic.motion_val[0][mot_index][0];

                        prev_y   = s->cur_pic.motion_val[0][mot_index][1];

                        prev_ref = s->cur_pic.ref_index[0][4 * mb_xy];

                    }



                    /* last MV */

                    mv_predictor[pred_count][0] = prev_x;

                    mv_predictor[pred_count][1] = prev_y;

                             ref[pred_count]    = prev_ref;

                    pred_count++;



skip_last_mv:



                    for (j = 0; j < pred_count; j++) {

                        int *linesize = s->cur_pic.f->linesize;

                        int score = 0;

                        uint8_t *src = s->cur_pic.f->data[0] +

                                       mb_x * 16 + mb_y * 16 * linesize[0];



                        s->cur_pic.motion_val[0][mot_index][0] =

                            s->mv[0][0][0] = mv_predictor[j][0];

                        s->cur_pic.motion_val[0][mot_index][1] =

                            s->mv[0][0][1] = mv_predictor[j][1];



                        // predictor intra or otherwise not available

                        if (ref[j] < 0)

                            continue;



                        s->decode_mb(s->opaque, ref[j], MV_DIR_FORWARD,

                                     MV_TYPE_16X16, &s->mv, mb_x, mb_y, 0, 0);



                        if (mb_x > 0 && fixed[mb_xy - 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * linesize[0] - 1] -

                                               src[k * linesize[0]]);

                        }

                        if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * linesize[0] + 15] -

                                               src[k * linesize[0] + 16]);

                        }

                        if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k - linesize[0]] - src[k]);

                        }

                        if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k + linesize[0] * 15] -

                                               src[k + linesize[0] * 16]);

                        }



                        if (score <= best_score) { // <= will favor the last MV

                            best_score = score;

                            best_pred  = j;

                        }

                    }

                    score_sum += best_score;

                    s->mv[0][0][0] = mv_predictor[best_pred][0];

                    s->mv[0][0][1] = mv_predictor[best_pred][1];



                    for (i = 0; i < mot_step; i++)

                        for (j = 0; j < mot_step; j++) {

                            s->cur_pic.motion_val[0][mot_index + i + j * mot_stride][0] = s->mv[0][0][0];

                            s->cur_pic.motion_val[0][mot_index + i + j * mot_stride][1] = s->mv[0][0][1];

                        }



                    s->decode_mb(s->opaque, ref[best_pred], MV_DIR_FORWARD,

                                 MV_TYPE_16X16, &s->mv, mb_x, mb_y, 0, 0);





                    if (s->mv[0][0][0] != prev_x || s->mv[0][0][1] != prev_y) {

                        fixed[mb_xy] = MV_CHANGED;

                        changed++;

                    } else

                        fixed[mb_xy] = MV_UNCHANGED;

                }

            }

        }



        if (none_left)

            return;



        for (i = 0; i < s->mb_num; i++) {

            int mb_xy = s->mb_index2xy[i];

            if (fixed[mb_xy])

                fixed[mb_xy] = MV_FROZEN;

        }

    }

}

struct omap_intr_handler_s *omap_inth_init(target_phys_addr_t base,

                unsigned long size, unsigned char nbanks, qemu_irq **pins,

                qemu_irq parent_irq, qemu_irq parent_fiq, omap_clk clk)

{

    struct omap_intr_handler_s *s = (struct omap_intr_handler_s *)

            g_malloc0(sizeof(struct omap_intr_handler_s) +

                            sizeof(struct omap_intr_handler_bank_s) * nbanks);



    s->parent_intr[0] = parent_irq;

    s->parent_intr[1] = parent_fiq;

    s->nbanks = nbanks;

    s->pins = qemu_allocate_irqs(omap_set_intr, s, nbanks * 32);

    if (pins)

        *pins = s->pins;



    memory_region_init_io(&s->mmio, &omap_inth_mem_ops, s, "omap-intc", size);

    memory_region_add_subregion(get_system_memory(), base, &s->mmio);



    omap_inth_reset(s);



    return s;

}

static int filter_samples(AVFilterLink *inlink, AVFilterBufferRef *buf)

{

    AVFilterContext  *ctx = inlink->dst;

    ASyncContext       *s = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    int nb_channels = av_get_channel_layout_nb_channels(buf->audio->channel_layout);

    int64_t pts = (buf->pts == AV_NOPTS_VALUE) ? buf->pts :

                  av_rescale_q(buf->pts, inlink->time_base, outlink->time_base);

    int out_size, ret;

    int64_t delta;



    /* buffer data until we get the first timestamp */

    if (s->pts == AV_NOPTS_VALUE) {

        if (pts != AV_NOPTS_VALUE) {

            s->pts = pts - get_delay(s);

        }

        return write_to_fifo(s, buf);

    }



    /* now wait for the next timestamp */

    if (pts == AV_NOPTS_VALUE) {

        return write_to_fifo(s, buf);

    }



    /* when we have two timestamps, compute how many samples would we have

     * to add/remove to get proper sync between data and timestamps */

    delta    = pts - s->pts - get_delay(s);

    out_size = avresample_available(s->avr);



    if (labs(delta) > s->min_delta) {

        av_log(ctx, AV_LOG_VERBOSE, "Discontinuity - %"PRId64" samples.\n", delta);

        out_size += delta;

    } else {

        if (s->resample) {

            int comp = av_clip(delta, -s->max_comp, s->max_comp);

            av_log(ctx, AV_LOG_VERBOSE, "Compensating %d samples per second.\n", comp);

            avresample_set_compensation(s->avr, delta, inlink->sample_rate);

        }

        delta = 0;

    }



    if (out_size > 0) {

        AVFilterBufferRef *buf_out = ff_get_audio_buffer(outlink, AV_PERM_WRITE,

                                                         out_size);

        if (!buf_out) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        avresample_read(s->avr, (void**)buf_out->extended_data, out_size);

        buf_out->pts = s->pts;



        if (delta > 0) {

            av_samples_set_silence(buf_out->extended_data, out_size - delta,

                                   delta, nb_channels, buf->format);

        }

        ret = ff_filter_samples(outlink, buf_out);

        if (ret < 0)

            goto fail;

        s->got_output = 1;

    } else {

        av_log(ctx, AV_LOG_WARNING, "Non-monotonous timestamps, dropping "

               "whole buffer.\n");

    }



    /* drain any remaining buffered data */

    avresample_read(s->avr, NULL, avresample_available(s->avr));



    s->pts = pts - avresample_get_delay(s->avr);

    ret = avresample_convert(s->avr, NULL, 0, 0, (void**)buf->extended_data,

                             buf->linesize[0], buf->audio->nb_samples);



fail:

    avfilter_unref_buffer(buf);



    return ret;

}

static void *do_touch_pages(void *arg)

{

    MemsetThread *memset_args = (MemsetThread *)arg;

    char *addr = memset_args->addr;

    uint64_t numpages = memset_args->numpages;

    uint64_t hpagesize = memset_args->hpagesize;

    sigset_t set, oldset;

    int i = 0;



    /* unblock SIGBUS */

    sigemptyset(&set);

    sigaddset(&set, SIGBUS);

    pthread_sigmask(SIG_UNBLOCK, &set, &oldset);



    if (sigsetjmp(memset_args->env, 1)) {

        memset_thread_failed = true;

    } else {

        for (i = 0; i < numpages; i++) {

            memset(addr, 0, 1);

            addr += hpagesize;

        }

    }

    pthread_sigmask(SIG_SETMASK, &oldset, NULL);

    return NULL;

}

static int opt_recording_timestamp(void *optctx, const char *opt, const char *arg)

{

    OptionsContext *o = optctx;

    char buf[128];

    int64_t recording_timestamp = parse_time_or_die(opt, arg, 0) / 1E6;

    struct tm time = *gmtime((time_t*)&recording_timestamp);

    strftime(buf, sizeof(buf), "creation_time=%FT%T%z", &time);

    parse_option(o, "metadata", buf, options);



    av_log(NULL, AV_LOG_WARNING, "%s is deprecated, set the 'creation_time' metadata "

                                 "tag instead.\n", opt);

    return 0;

}

