static int mxf_read_partition_pack(void *arg, AVIOContext *pb, int tag, int size, UID uid, int64_t klv_offset)

{

    MXFContext *mxf = arg;

    MXFPartition *partition;

    UID op;

    uint64_t footer_partition;

    uint32_t nb_essence_containers;

    int err;



    if (mxf->partitions_count+1 >= UINT_MAX / sizeof(*mxf->partitions))

        return AVERROR(ENOMEM);



    if ((err = av_reallocp_array(&mxf->partitions, mxf->partitions_count + 1,

                                 sizeof(*mxf->partitions))) < 0) {

        mxf->partitions_count = 0;

        return err;

    }



    if (mxf->parsing_backward) {

        /* insert the new partition pack in the middle

         * this makes the entries in mxf->partitions sorted by offset */

        memmove(&mxf->partitions[mxf->last_forward_partition+1],

                &mxf->partitions[mxf->last_forward_partition],

                (mxf->partitions_count - mxf->last_forward_partition)*sizeof(*mxf->partitions));

        partition = mxf->current_partition = &mxf->partitions[mxf->last_forward_partition];

    } else {

        mxf->last_forward_partition++;

        partition = mxf->current_partition = &mxf->partitions[mxf->partitions_count];

    }



    memset(partition, 0, sizeof(*partition));

    mxf->partitions_count++;

    partition->pack_length = avio_tell(pb) - klv_offset + size;



    switch(uid[13]) {

    case 2:

        partition->type = Header;

        break;

    case 3:

        partition->type = BodyPartition;

        break;

    case 4:

        partition->type = Footer;

        break;

    default:

        av_log(mxf->fc, AV_LOG_ERROR, "unknown partition type %i\n", uid[13]);

        return AVERROR_INVALIDDATA;

    }



    /* consider both footers to be closed (there is only Footer and CompleteFooter) */

    partition->closed = partition->type == Footer || !(uid[14] & 1);

    partition->complete = uid[14] > 2;

    avio_skip(pb, 4);

    partition->kag_size = avio_rb32(pb);

    partition->this_partition = avio_rb64(pb);

    partition->previous_partition = avio_rb64(pb);

    footer_partition = avio_rb64(pb);

    partition->header_byte_count = avio_rb64(pb);

    partition->index_byte_count = avio_rb64(pb);

    partition->index_sid = avio_rb32(pb);

    avio_skip(pb, 8);

    partition->body_sid = avio_rb32(pb);

    avio_read(pb, op, sizeof(UID));

    nb_essence_containers = avio_rb32(pb);



    /* some files don'thave FooterPartition set in every partition */

    if (footer_partition) {

        if (mxf->footer_partition && mxf->footer_partition != footer_partition) {

            av_log(mxf->fc, AV_LOG_ERROR,

                   "inconsistent FooterPartition value: %"PRIu64" != %"PRIu64"\n",

                   mxf->footer_partition, footer_partition);

        } else {

            mxf->footer_partition = footer_partition;

        }

    }



    av_dlog(mxf->fc,

            "PartitionPack: ThisPartition = 0x%"PRIX64

            ", PreviousPartition = 0x%"PRIX64", "

            "FooterPartition = 0x%"PRIX64", IndexSID = %i, BodySID = %i\n",

            partition->this_partition,

            partition->previous_partition, footer_partition,

            partition->index_sid, partition->body_sid);



    /* sanity check PreviousPartition if set */

    if (partition->previous_partition &&

        mxf->run_in + partition->previous_partition >= klv_offset) {

        av_log(mxf->fc, AV_LOG_ERROR,

               "PreviousPartition points to this partition or forward\n");

        return AVERROR_INVALIDDATA;

    }



    if      (op[12] == 1 && op[13] == 1) mxf->op = OP1a;

    else if (op[12] == 1 && op[13] == 2) mxf->op = OP1b;

    else if (op[12] == 1 && op[13] == 3) mxf->op = OP1c;

    else if (op[12] == 2 && op[13] == 1) mxf->op = OP2a;

    else if (op[12] == 2 && op[13] == 2) mxf->op = OP2b;

    else if (op[12] == 2 && op[13] == 3) mxf->op = OP2c;

    else if (op[12] == 3 && op[13] == 1) mxf->op = OP3a;

    else if (op[12] == 3 && op[13] == 2) mxf->op = OP3b;

    else if (op[12] == 3 && op[13] == 3) mxf->op = OP3c;

    else if (op[12] == 64&& op[13] == 1) mxf->op = OPSonyOpt;

    else if (op[12] == 0x10) {

        /* SMPTE 390m: "There shall be exactly one essence container"

         * The following block deals with files that violate this, namely:

         * 2011_DCPTEST_24FPS.V.mxf - two ECs, OP1a

         * abcdefghiv016f56415e.mxf - zero ECs, OPAtom, output by Avid AirSpeed */

        if (nb_essence_containers != 1) {

            MXFOP op = nb_essence_containers ? OP1a : OPAtom;



            /* only nag once */

            if (!mxf->op)

                av_log(mxf->fc, AV_LOG_WARNING,

                       "\"OPAtom\" with %u ECs - assuming %s\n",

                       nb_essence_containers,

                       op == OP1a ? "OP1a" : "OPAtom");



            mxf->op = op;

        } else

            mxf->op = OPAtom;

    } else {

        av_log(mxf->fc, AV_LOG_ERROR, "unknown operational pattern: %02xh %02xh - guessing OP1a\n", op[12], op[13]);

        mxf->op = OP1a;

    }



    if (partition->kag_size <= 0 || partition->kag_size > (1 << 20)) {

        av_log(mxf->fc, AV_LOG_WARNING, "invalid KAGSize %i - guessing ", partition->kag_size);



        if (mxf->op == OPSonyOpt)

            partition->kag_size = 512;

        else

            partition->kag_size = 1;



        av_log(mxf->fc, AV_LOG_WARNING, "%i\n", partition->kag_size);

    }



    return 0;

}

SwsContext *getSwsContext(int srcW, int srcH, int srcFormat, int dstW, int dstH, int dstFormat, int flags,

                         SwsFilter *srcFilter, SwsFilter *dstFilter){



	SwsContext *c;

	int i;

	int usesFilter;

	SwsFilter dummyFilter= {NULL, NULL, NULL, NULL};



#ifdef ARCH_X86

	if(gCpuCaps.hasMMX)

		asm volatile("emms\n\t"::: "memory");

#endif



	if(swScale==NULL) globalInit();



	/* avoid dupplicate Formats, so we dont need to check to much */

	if(srcFormat==IMGFMT_IYUV) srcFormat=IMGFMT_I420;

	if(srcFormat==IMGFMT_Y8)   srcFormat=IMGFMT_Y800;

	if(dstFormat==IMGFMT_Y8)   dstFormat=IMGFMT_Y800;



	if(!isSupportedIn(srcFormat)) 

	{

		fprintf(stderr, "swScaler: %s is not supported as input format\n", vo_format_name(srcFormat));

		return NULL;

	}

	if(!isSupportedOut(dstFormat))

	{

		fprintf(stderr, "swScaler: %s is not supported as output format\n", vo_format_name(dstFormat));

		return NULL;

	}



	/* sanity check */

	if(srcW<4 || srcH<1 || dstW<8 || dstH<1) //FIXME check if these are enough and try to lowwer them after fixing the relevant parts of the code

	{

		fprintf(stderr, "swScaler: %dx%d -> %dx%d is invalid scaling dimension\n", 

			srcW, srcH, dstW, dstH);

		return NULL;

	}



	if(!dstFilter) dstFilter= &dummyFilter;

	if(!srcFilter) srcFilter= &dummyFilter;



	c= memalign(64, sizeof(SwsContext));

	memset(c, 0, sizeof(SwsContext));



	c->srcW= srcW;

	c->srcH= srcH;

	c->dstW= dstW;

	c->dstH= dstH;

	c->lumXInc= ((srcW<<16) + (dstW>>1))/dstW;

	c->lumYInc= ((srcH<<16) + (dstH>>1))/dstH;

	c->flags= flags;

	c->dstFormat= dstFormat;

	c->srcFormat= srcFormat;



	usesFilter=0;

	if(dstFilter->lumV!=NULL && dstFilter->lumV->length>1) usesFilter=1;

	if(dstFilter->lumH!=NULL && dstFilter->lumH->length>1) usesFilter=1;

	if(dstFilter->chrV!=NULL && dstFilter->chrV->length>1) usesFilter=1;

	if(dstFilter->chrH!=NULL && dstFilter->chrH->length>1) usesFilter=1;

	if(srcFilter->lumV!=NULL && srcFilter->lumV->length>1) usesFilter=1;

	if(srcFilter->lumH!=NULL && srcFilter->lumH->length>1) usesFilter=1;

	if(srcFilter->chrV!=NULL && srcFilter->chrV->length>1) usesFilter=1;

	if(srcFilter->chrH!=NULL && srcFilter->chrH->length>1) usesFilter=1;



	/* unscaled special Cases */

	if(srcW==dstW && srcH==dstH && !usesFilter)

	{

		/* yuv2bgr */

		if(isPlanarYUV(srcFormat) && isBGR(dstFormat))

		{

			// FIXME multiple yuv2rgb converters wont work that way cuz that thing is full of globals&statics

#ifdef WORDS_BIGENDIAN

			if(dstFormat==IMGFMT_BGR32)

				yuv2rgb_init( dstFormat&0xFF /* =bpp */, MODE_BGR);

			else

				yuv2rgb_init( dstFormat&0xFF /* =bpp */, MODE_RGB);

#else

			yuv2rgb_init( dstFormat&0xFF /* =bpp */, MODE_RGB);

#endif

			c->swScale= planarYuvToBgr;



			if(flags&SWS_PRINT_INFO)

				printf("SwScaler: using unscaled %s -> %s special converter\n", 

					vo_format_name(srcFormat), vo_format_name(dstFormat));

			return c;

		}



		/* simple copy */

		if(srcFormat == dstFormat || (isPlanarYUV(srcFormat) && isPlanarYUV(dstFormat)))

		{

			c->swScale= simpleCopy;



			if(flags&SWS_PRINT_INFO)

				printf("SwScaler: using unscaled %s -> %s special converter\n", 

					vo_format_name(srcFormat), vo_format_name(dstFormat));

			return c;

		}



		/* bgr32to24 & rgb32to24*/

		if((srcFormat==IMGFMT_BGR32 && dstFormat==IMGFMT_BGR24)

		 ||(srcFormat==IMGFMT_RGB32 && dstFormat==IMGFMT_RGB24))

		{

			c->swScale= bgr32to24Wrapper;



			if(flags&SWS_PRINT_INFO)

				printf("SwScaler: using unscaled %s -> %s special converter\n", 

					vo_format_name(srcFormat), vo_format_name(dstFormat));

			return c;

		}



		/* bgr24to32 & rgb24to32*/

		if((srcFormat==IMGFMT_BGR24 && dstFormat==IMGFMT_BGR32)

		 ||(srcFormat==IMGFMT_RGB24 && dstFormat==IMGFMT_RGB32))

		{

			c->swScale= bgr24to32Wrapper;



			if(flags&SWS_PRINT_INFO)

				printf("SwScaler: using unscaled %s -> %s special converter\n", 

					vo_format_name(srcFormat), vo_format_name(dstFormat));

			return c;

		}



		/* bgr15to16 */

		if(srcFormat==IMGFMT_BGR15 && dstFormat==IMGFMT_BGR16)

		{

			c->swScale= bgr15to16Wrapper;



			if(flags&SWS_PRINT_INFO)

				printf("SwScaler: using unscaled %s -> %s special converter\n", 

					vo_format_name(srcFormat), vo_format_name(dstFormat));

			return c;

		}



		/* bgr24toYV12 */

		if(srcFormat==IMGFMT_BGR24 && dstFormat==IMGFMT_YV12)

		{

			c->swScale= bgr24toyv12Wrapper;



			if(flags&SWS_PRINT_INFO)

				printf("SwScaler: using unscaled %s -> %s special converter\n", 

					vo_format_name(srcFormat), vo_format_name(dstFormat));

			return c;

		}

	}



	if(cpuCaps.hasMMX2)

	{

		c->canMMX2BeUsed= (dstW >=srcW && (dstW&31)==0 && (srcW&15)==0) ? 1 : 0;

		if(!c->canMMX2BeUsed && dstW >=srcW && (srcW&15)==0 && (flags&SWS_FAST_BILINEAR))

		{

			if(flags&SWS_PRINT_INFO)

				fprintf(stderr, "SwScaler: output Width is not a multiple of 32 -> no MMX2 scaler\n");

		}

	}

	else

		c->canMMX2BeUsed=0;





	/* dont use full vertical UV input/internaly if the source doesnt even have it */

	if(isHalfChrV(srcFormat)) c->flags= flags= flags&(~SWS_FULL_CHR_V);

	/* dont use full horizontal UV input if the source doesnt even have it */

	if(isHalfChrH(srcFormat)) c->flags= flags= flags&(~SWS_FULL_CHR_H_INP);

	/* dont use full horizontal UV internally if the destination doesnt even have it */

	if(isHalfChrH(dstFormat)) c->flags= flags= flags&(~SWS_FULL_CHR_H_INT);



	if(flags&SWS_FULL_CHR_H_INP)	c->chrSrcW= srcW;

	else				c->chrSrcW= (srcW+1)>>1;



	if(flags&SWS_FULL_CHR_H_INT)	c->chrDstW= dstW;

	else				c->chrDstW= (dstW+1)>>1;



	if(flags&SWS_FULL_CHR_V)	c->chrSrcH= srcH;

	else				c->chrSrcH= (srcH+1)>>1;



	if(isHalfChrV(dstFormat))	c->chrDstH= (dstH+1)>>1;

	else				c->chrDstH= dstH;



	c->chrXInc= ((c->chrSrcW<<16) + (c->chrDstW>>1))/c->chrDstW;

	c->chrYInc= ((c->chrSrcH<<16) + (c->chrDstH>>1))/c->chrDstH;





	// match pixel 0 of the src to pixel 0 of dst and match pixel n-2 of src to pixel n-2 of dst

	// but only for the FAST_BILINEAR mode otherwise do correct scaling

	// n-2 is the last chrominance sample available

	// this is not perfect, but noone shuld notice the difference, the more correct variant

	// would be like the vertical one, but that would require some special code for the

	// first and last pixel

	if(flags&SWS_FAST_BILINEAR)

	{

		if(c->canMMX2BeUsed)

		{

			c->lumXInc+= 20;

			c->chrXInc+= 20;

		}

		//we dont use the x86asm scaler if mmx is available

		else if(cpuCaps.hasMMX)

		{

			c->lumXInc = ((srcW-2)<<16)/(dstW-2) - 20;

			c->chrXInc = ((c->chrSrcW-2)<<16)/(c->chrDstW-2) - 20;

		}

	}



	/* precalculate horizontal scaler filter coefficients */

	{

		const int filterAlign= cpuCaps.hasMMX ? 4 : 1;



		initFilter(&c->hLumFilter, &c->hLumFilterPos, &c->hLumFilterSize, c->lumXInc,

				 srcW      ,       dstW, filterAlign, 1<<14, flags,

				 srcFilter->lumH, dstFilter->lumH);

		initFilter(&c->hChrFilter, &c->hChrFilterPos, &c->hChrFilterSize, c->chrXInc,

				(srcW+1)>>1, c->chrDstW, filterAlign, 1<<14, flags,

				 srcFilter->chrH, dstFilter->chrH);



#ifdef ARCH_X86

// cant downscale !!!

		if(c->canMMX2BeUsed && (flags & SWS_FAST_BILINEAR))

		{

			initMMX2HScaler(      dstW, c->lumXInc, c->funnyYCode);

			initMMX2HScaler(c->chrDstW, c->chrXInc, c->funnyUVCode);

		}

#endif

	} // Init Horizontal stuff







	/* precalculate vertical scaler filter coefficients */

	initFilter(&c->vLumFilter, &c->vLumFilterPos, &c->vLumFilterSize, c->lumYInc,

			srcH      ,        dstH, 1, (1<<12)-4, flags,

			srcFilter->lumV, dstFilter->lumV);

	initFilter(&c->vChrFilter, &c->vChrFilterPos, &c->vChrFilterSize, c->chrYInc,

			(srcH+1)>>1, c->chrDstH, 1, (1<<12)-4, flags,

			 srcFilter->chrV, dstFilter->chrV);



	// Calculate Buffer Sizes so that they wont run out while handling these damn slices

	c->vLumBufSize= c->vLumFilterSize;

	c->vChrBufSize= c->vChrFilterSize;

	for(i=0; i<dstH; i++)

	{

		int chrI= i*c->chrDstH / dstH;

		int nextSlice= MAX(c->vLumFilterPos[i   ] + c->vLumFilterSize - 1,

				 ((c->vChrFilterPos[chrI] + c->vChrFilterSize - 1)<<1));

		nextSlice&= ~1; // Slices start at even boundaries

		if(c->vLumFilterPos[i   ] + c->vLumBufSize < nextSlice)

			c->vLumBufSize= nextSlice - c->vLumFilterPos[i   ];

		if(c->vChrFilterPos[chrI] + c->vChrBufSize < (nextSlice>>1))

			c->vChrBufSize= (nextSlice>>1) - c->vChrFilterPos[chrI];

	}



	// allocate pixbufs (we use dynamic allocation because otherwise we would need to

	c->lumPixBuf= (int16_t**)memalign(4, c->vLumBufSize*2*sizeof(int16_t*));

	c->chrPixBuf= (int16_t**)memalign(4, c->vChrBufSize*2*sizeof(int16_t*));

	//Note we need at least one pixel more at the end because of the mmx code (just in case someone wanna replace the 4000/8000)

	for(i=0; i<c->vLumBufSize; i++)

		c->lumPixBuf[i]= c->lumPixBuf[i+c->vLumBufSize]= (uint16_t*)memalign(8, 4000);

	for(i=0; i<c->vChrBufSize; i++)

		c->chrPixBuf[i]= c->chrPixBuf[i+c->vChrBufSize]= (uint16_t*)memalign(8, 8000);



	//try to avoid drawing green stuff between the right end and the stride end

	for(i=0; i<c->vLumBufSize; i++) memset(c->lumPixBuf[i], 0, 4000);

	for(i=0; i<c->vChrBufSize; i++) memset(c->chrPixBuf[i], 64, 8000);



	ASSERT(c->chrDstH <= dstH)



	// pack filter data for mmx code

	if(cpuCaps.hasMMX)

	{

		c->lumMmxFilter= (int16_t*)memalign(8, c->vLumFilterSize*      dstH*4*sizeof(int16_t));

		c->chrMmxFilter= (int16_t*)memalign(8, c->vChrFilterSize*c->chrDstH*4*sizeof(int16_t));

		for(i=0; i<c->vLumFilterSize*dstH; i++)

			c->lumMmxFilter[4*i]=c->lumMmxFilter[4*i+1]=c->lumMmxFilter[4*i+2]=c->lumMmxFilter[4*i+3]=

				c->vLumFilter[i];

		for(i=0; i<c->vChrFilterSize*c->chrDstH; i++)

			c->chrMmxFilter[4*i]=c->chrMmxFilter[4*i+1]=c->chrMmxFilter[4*i+2]=c->chrMmxFilter[4*i+3]=

				c->vChrFilter[i];

	}



	if(flags&SWS_PRINT_INFO)

	{

#ifdef DITHER1XBPP

		char *dither= " dithered";

#else

		char *dither= "";

#endif

		if(flags&SWS_FAST_BILINEAR)

			fprintf(stderr, "\nSwScaler: FAST_BILINEAR scaler, ");

		else if(flags&SWS_BILINEAR)

			fprintf(stderr, "\nSwScaler: BILINEAR scaler, ");

		else if(flags&SWS_BICUBIC)

			fprintf(stderr, "\nSwScaler: BICUBIC scaler, ");

		else if(flags&SWS_X)

			fprintf(stderr, "\nSwScaler: Experimental scaler, ");

		else if(flags&SWS_POINT)

			fprintf(stderr, "\nSwScaler: Nearest Neighbor / POINT scaler, ");

		else if(flags&SWS_AREA)

			fprintf(stderr, "\nSwScaler: Area Averageing scaler, ");

		else

			fprintf(stderr, "\nSwScaler: ehh flags invalid?! ");



		if(dstFormat==IMGFMT_BGR15 || dstFormat==IMGFMT_BGR16)

			fprintf(stderr, "from %s to%s %s ", 

				vo_format_name(srcFormat), dither, vo_format_name(dstFormat));

		else

			fprintf(stderr, "from %s to %s ", 

				vo_format_name(srcFormat), vo_format_name(dstFormat));



		if(cpuCaps.hasMMX2)

			fprintf(stderr, "using MMX2\n");

		else if(cpuCaps.has3DNow)

			fprintf(stderr, "using 3DNOW\n");

		else if(cpuCaps.hasMMX)

			fprintf(stderr, "using MMX\n");

		else

			fprintf(stderr, "using C\n");

	}



	if((flags & SWS_PRINT_INFO) && verbose)

	{

		if(cpuCaps.hasMMX)

		{

			if(c->canMMX2BeUsed && (flags&SWS_FAST_BILINEAR))

				printf("SwScaler: using FAST_BILINEAR MMX2 scaler for horizontal scaling\n");

			else

			{

				if(c->hLumFilterSize==4)

					printf("SwScaler: using 4-tap MMX scaler for horizontal luminance scaling\n");

				else if(c->hLumFilterSize==8)

					printf("SwScaler: using 8-tap MMX scaler for horizontal luminance scaling\n");

				else

					printf("SwScaler: using n-tap MMX scaler for horizontal luminance scaling\n");



				if(c->hChrFilterSize==4)

					printf("SwScaler: using 4-tap MMX scaler for horizontal chrominance scaling\n");

				else if(c->hChrFilterSize==8)

					printf("SwScaler: using 8-tap MMX scaler for horizontal chrominance scaling\n");

				else

					printf("SwScaler: using n-tap MMX scaler for horizontal chrominance scaling\n");

			}

		}

		else

		{

#ifdef ARCH_X86

			printf("SwScaler: using X86-Asm scaler for horizontal scaling\n");

#else

			if(flags & SWS_FAST_BILINEAR)

				printf("SwScaler: using FAST_BILINEAR C scaler for horizontal scaling\n");

			else

				printf("SwScaler: using C scaler for horizontal scaling\n");

#endif

		}

		if(isPlanarYUV(dstFormat))

		{

			if(c->vLumFilterSize==1)

				printf("SwScaler: using 1-tap %s \"scaler\" for vertical scaling (YV12 like)\n", cpuCaps.hasMMX ? "MMX" : "C");

			else

				printf("SwScaler: using n-tap %s scaler for vertical scaling (YV12 like)\n", cpuCaps.hasMMX ? "MMX" : "C");

		}

		else

		{

			if(c->vLumFilterSize==1 && c->vChrFilterSize==2)

				printf("SwScaler: using 1-tap %s \"scaler\" for vertical luminance scaling (BGR)\n"

				       "SwScaler:       2-tap scaler for vertical chrominance scaling (BGR)\n",cpuCaps.hasMMX ? "MMX" : "C");

			else if(c->vLumFilterSize==2 && c->vChrFilterSize==2)

				printf("SwScaler: using 2-tap linear %s scaler for vertical scaling (BGR)\n", cpuCaps.hasMMX ? "MMX" : "C");

			else

				printf("SwScaler: using n-tap %s scaler for vertical scaling (BGR)\n", cpuCaps.hasMMX ? "MMX" : "C");

		}



		if(dstFormat==IMGFMT_BGR24)

			printf("SwScaler: using %s YV12->BGR24 Converter\n",

				cpuCaps.hasMMX2 ? "MMX2" : (cpuCaps.hasMMX ? "MMX" : "C"));

		else if(dstFormat==IMGFMT_BGR32)

			printf("SwScaler: using %s YV12->BGR32 Converter\n", cpuCaps.hasMMX ? "MMX" : "C");

		else if(dstFormat==IMGFMT_BGR16)

			printf("SwScaler: using %s YV12->BGR16 Converter\n", cpuCaps.hasMMX ? "MMX" : "C");

		else if(dstFormat==IMGFMT_BGR15)

			printf("SwScaler: using %s YV12->BGR15 Converter\n", cpuCaps.hasMMX ? "MMX" : "C");



		printf("SwScaler: %dx%d -> %dx%d\n", srcW, srcH, dstW, dstH);

	}

	if((flags & SWS_PRINT_INFO) && verbose>1)

	{

		printf("SwScaler:Lum srcW=%d srcH=%d dstW=%d dstH=%d xInc=%d yInc=%d\n",

			c->srcW, c->srcH, c->dstW, c->dstH, c->lumXInc, c->lumYInc);

		printf("SwScaler:Chr srcW=%d srcH=%d dstW=%d dstH=%d xInc=%d yInc=%d\n",

			c->chrSrcW, c->chrSrcH, c->chrDstW, c->chrDstH, c->chrXInc, c->chrYInc);

	}



	c->swScale= swScale;

	return c;

}

static int decode_user_data(MpegEncContext *s, GetBitContext *gb){

    char buf[256];

    int i;

    int e;

    int ver, build, ver2, ver3;

    char last;



    for(i=0; i<255; i++){

        if(show_bits(gb, 23) == 0) break;

        buf[i]= get_bits(gb, 8);

    }

    buf[i]=0;



    /* divx detection */

    e=sscanf(buf, "DivX%dBuild%d%c", &ver, &build, &last);

    if(e<2)

        e=sscanf(buf, "DivX%db%d%c", &ver, &build, &last);

    if(e>=2){

        s->divx_version= ver;

        s->divx_build= build;

        s->divx_packed= e==3 && last=='p';

    }



    /* ffmpeg detection */

    e=sscanf(buf, "FFmpe%*[^b]b%d", &build)+3;

    if(e!=4)

        e=sscanf(buf, "FFmpeg v%d.%d.%d / libavcodec build: %d", &ver, &ver2, &ver3, &build); 

    if(e!=4){

        e=sscanf(buf, "Lavc%d.%d.%d", &ver, &ver2, &ver3)+1;

        build= (ver<<16) + (ver2<<8) + ver3;

    }

    if(e!=4){

        if(strcmp(buf, "ffmpeg")==0){

            s->lavc_build= 4600;

        }

    }

    if(e==4){

        s->lavc_build= build;

    }



    /* xvid detection */

    e=sscanf(buf, "XviD%d", &build);

    if(e==1){

        s->xvid_build= build;

    }



//printf("User Data: %s\n", buf);

    return 0;

}

static void av_noinline qpeg_decode_inter(QpegContext *qctx, uint8_t *dst,

                              int stride, int width, int height,

                              int delta, const uint8_t *ctable,

                              uint8_t *refdata)

{

    int i, j;

    int code;

    int filled = 0;

    int orig_height;



    if(!refdata)

        refdata= dst;



    /* copy prev frame */

    for(i = 0; i < height; i++)

        memcpy(dst + (i * stride), refdata + (i * stride), width);



    orig_height = height;

    height--;

    dst = dst + height * stride;



    while ((bytestream2_get_bytes_left(&qctx->buffer) > 0) && (height >= 0)) {

        code = bytestream2_get_byte(&qctx->buffer);



        if(delta) {

            /* motion compensation */

            while(bytestream2_get_bytes_left(&qctx->buffer) > 0 && (code & 0xF0) == 0xF0) {

                if(delta == 1) {

                    int me_idx;

                    int me_w, me_h, me_x, me_y;

                    uint8_t *me_plane;

                    int corr, val;



                    /* get block size by index */

                    me_idx = code & 0xF;

                    me_w = qpeg_table_w[me_idx];

                    me_h = qpeg_table_h[me_idx];



                    /* extract motion vector */

                    corr = bytestream2_get_byte(&qctx->buffer);



                    val = corr >> 4;

                    if(val > 7)

                        val -= 16;

                    me_x = val;



                    val = corr & 0xF;

                    if(val > 7)

                        val -= 16;

                    me_y = val;



                    /* check motion vector */

                    if ((me_x + filled < 0) || (me_x + me_w + filled > width) ||

                       (height - me_y - me_h < 0) || (height - me_y >= orig_height) ||

                       (filled + me_w > width) || (height - me_h < 0))

                        av_log(NULL, AV_LOG_ERROR, "Bogus motion vector (%i,%i), block size %ix%i at %i,%i\n",

                               me_x, me_y, me_w, me_h, filled, height);

                    else {

                        /* do motion compensation */

                        me_plane = refdata + (filled + me_x) + (height - me_y) * stride;

                        for(j = 0; j < me_h; j++) {

                            for(i = 0; i < me_w; i++)

                                dst[filled + i - (j * stride)] = me_plane[i - (j * stride)];

                        }

                    }

                }

                code = bytestream2_get_byte(&qctx->buffer);

            }

        }



        if(code == 0xE0) /* end-of-picture code */

            break;

        if(code > 0xE0) { /* run code: 0xE1..0xFF */

            int p;



            code &= 0x1F;

            p = bytestream2_get_byte(&qctx->buffer);

            for(i = 0; i <= code; i++) {

                dst[filled++] = p;

                if(filled >= width) {

                    filled = 0;

                    dst -= stride;

                    height--;

                    if (height < 0)

                        break;

                }

            }

        } else if(code >= 0xC0) { /* copy code: 0xC0..0xDF */

            code &= 0x1F;



            if(code + 1 > bytestream2_get_bytes_left(&qctx->buffer))

                break;



            for(i = 0; i <= code; i++) {

                dst[filled++] = bytestream2_get_byte(&qctx->buffer);

                if(filled >= width) {

                    filled = 0;

                    dst -= stride;

                    height--;

                    if (height < 0)

                        break;

                }

            }

        } else if(code >= 0x80) { /* skip code: 0x80..0xBF */

            int skip;



            code &= 0x3F;

            /* codes 0x80 and 0x81 are actually escape codes,

               skip value minus constant is in the next byte */

            if(!code)

                skip = bytestream2_get_byte(&qctx->buffer) +  64;

            else if(code == 1)

                skip = bytestream2_get_byte(&qctx->buffer) + 320;

            else

                skip = code;

            filled += skip;

            while( filled >= width) {

                filled -= width;

                dst -= stride;

                height--;

                if(height < 0)

                    break;

            }

        } else {

            /* zero code treated as one-pixel skip */

            if(code) {

                dst[filled++] = ctable[code & 0x7F];

            }

            else

                filled++;

            if(filled >= width) {

                filled = 0;

                dst -= stride;

                height--;

            }

        }

    }

}

static void parse_type_number(Visitor *v, const char *name, double *obj,

                              Error **errp)

{

    StringInputVisitor *siv = to_siv(v);

    char *endp = (char *) siv->string;

    double val;



    errno = 0;

    if (siv->string) {

        val = strtod(siv->string, &endp);

    }

    if (!siv->string || errno || endp == siv->string || *endp) {

        error_setg(errp, QERR_INVALID_PARAMETER_TYPE, name ? name : "null",

                   "number");

        return;

    }



    *obj = val;

}

static int vhdx_create_bat(BlockDriverState *bs, BDRVVHDXState *s,

                           uint64_t image_size, VHDXImageType type,

                           bool use_zero_blocks, uint64_t file_offset,

                           uint32_t length)

{

    int ret = 0;

    uint64_t data_file_offset;

    uint64_t total_sectors = 0;

    uint64_t sector_num = 0;

    uint64_t unused;

    int block_state;

    VHDXSectorInfo sinfo;



    assert(s->bat == NULL);



    /* this gives a data start after BAT/bitmap entries, and well

     * past any metadata entries (with a 4 MB buffer for future

     * expansion */

    data_file_offset = file_offset + length + 5 * MiB;

    total_sectors = image_size >> s->logical_sector_size_bits;



    if (type == VHDX_TYPE_DYNAMIC) {

        /* All zeroes, so we can just extend the file - the end of the BAT

         * is the furthest thing we have written yet */

        ret = bdrv_truncate(bs, data_file_offset);

        if (ret < 0) {

            goto exit;

        }

    } else if (type == VHDX_TYPE_FIXED) {

        ret = bdrv_truncate(bs, data_file_offset + image_size);

        if (ret < 0) {

            goto exit;

        }

    } else {

        ret = -ENOTSUP;

        goto exit;

    }



    if (type == VHDX_TYPE_FIXED ||

                use_zero_blocks ||

                bdrv_has_zero_init(bs) == 0) {

        /* for a fixed file, the default BAT entry is not zero */

        s->bat = g_malloc0(length);

        block_state = type == VHDX_TYPE_FIXED ? PAYLOAD_BLOCK_FULLY_PRESENT :

                                                PAYLOAD_BLOCK_NOT_PRESENT;

        block_state = use_zero_blocks ? PAYLOAD_BLOCK_ZERO : block_state;

        /* fill the BAT by emulating sector writes of sectors_per_block size */

        while (sector_num < total_sectors) {

            vhdx_block_translate(s, sector_num, s->sectors_per_block, &sinfo);

            sinfo.file_offset = data_file_offset +

                                (sector_num << s->logical_sector_size_bits);

            sinfo.file_offset = ROUND_UP(sinfo.file_offset, MiB);

            vhdx_update_bat_table_entry(bs, s, &sinfo, &unused, &unused,

                                        block_state);

            cpu_to_le64s(&s->bat[sinfo.bat_idx]);

            sector_num += s->sectors_per_block;

        }

        ret = bdrv_pwrite(bs, file_offset, s->bat, length);

        if (ret < 0) {

            goto exit;

        }

    }







exit:

    g_free(s->bat);

    return ret;

}

static void net_slirp_cleanup(NetClientState *nc)

{

    SlirpState *s = DO_UPCAST(SlirpState, nc, nc);



    slirp_cleanup(s->slirp);

    qemu_remove_exit_notifier(&s->exit_notifier);

    slirp_smb_cleanup(s);

    QTAILQ_REMOVE(&slirp_stacks, s, entry);

}

int ff_h264_decode_mb_cavlc(H264Context *h){

    MpegEncContext * const s = &h->s;

    int mb_xy;

    int partition_count;

    unsigned int mb_type, cbp;

    int dct8x8_allowed= h->pps.transform_8x8_mode;



    mb_xy = h->mb_xy = s->mb_x + s->mb_y*s->mb_stride;



    tprintf(s->avctx, "pic:%d mb:%d/%d\n", h->frame_num, s->mb_x, s->mb_y);

    cbp = 0; /* avoid warning. FIXME: find a solution without slowing

                down the code */

    if(h->slice_type_nos != FF_I_TYPE){

        if(s->mb_skip_run==-1)

            s->mb_skip_run= get_ue_golomb(&s->gb);



        if (s->mb_skip_run--) {

            if(FRAME_MBAFF && (s->mb_y&1) == 0){

                if(s->mb_skip_run==0)

                    h->mb_mbaff = h->mb_field_decoding_flag = get_bits1(&s->gb);

                else

                    predict_field_decoding_flag(h);

            }

            decode_mb_skip(h);

            return 0;

        }

    }

    if(FRAME_MBAFF){

        if( (s->mb_y&1) == 0 )

            h->mb_mbaff = h->mb_field_decoding_flag = get_bits1(&s->gb);

    }



    h->prev_mb_skipped= 0;



    mb_type= get_ue_golomb(&s->gb);

    if(h->slice_type_nos == FF_B_TYPE){

        if(mb_type < 23){

            partition_count= b_mb_type_info[mb_type].partition_count;

            mb_type=         b_mb_type_info[mb_type].type;

        }else{

            mb_type -= 23;

            goto decode_intra_mb;

        }

    }else if(h->slice_type_nos == FF_P_TYPE){

        if(mb_type < 5){

            partition_count= p_mb_type_info[mb_type].partition_count;

            mb_type=         p_mb_type_info[mb_type].type;

        }else{

            mb_type -= 5;

            goto decode_intra_mb;

        }

    }else{

       assert(h->slice_type_nos == FF_I_TYPE);

        if(h->slice_type == FF_SI_TYPE && mb_type)

            mb_type--;

decode_intra_mb:

        if(mb_type > 25){

            av_log(h->s.avctx, AV_LOG_ERROR, "mb_type %d in %c slice too large at %d %d\n", mb_type, av_get_pict_type_char(h->slice_type), s->mb_x, s->mb_y);

            return -1;

        }

        partition_count=0;

        cbp= i_mb_type_info[mb_type].cbp;

        h->intra16x16_pred_mode= i_mb_type_info[mb_type].pred_mode;

        mb_type= i_mb_type_info[mb_type].type;

    }



    if(MB_FIELD)

        mb_type |= MB_TYPE_INTERLACED;



    h->slice_table[ mb_xy ]= h->slice_num;



    if(IS_INTRA_PCM(mb_type)){

        unsigned int x;



        // We assume these blocks are very rare so we do not optimize it.

        align_get_bits(&s->gb);



        // The pixels are stored in the same order as levels in h->mb array.

        for(x=0; x < (CHROMA ? 384 : 256); x++){

            ((uint8_t*)h->mb)[x]= get_bits(&s->gb, 8);

        }



        // In deblocking, the quantizer is 0

        s->current_picture.qscale_table[mb_xy]= 0;

        // All coeffs are present

        memset(h->non_zero_count[mb_xy], 16, 16);



        s->current_picture.mb_type[mb_xy]= mb_type;

        return 0;

    }



    if(MB_MBAFF){

        h->ref_count[0] <<= 1;

        h->ref_count[1] <<= 1;

    }



    fill_caches(h, mb_type, 0);



    //mb_pred

    if(IS_INTRA(mb_type)){

        int pred_mode;

//            init_top_left_availability(h);

        if(IS_INTRA4x4(mb_type)){

            int i;

            int di = 1;

            if(dct8x8_allowed && get_bits1(&s->gb)){

                mb_type |= MB_TYPE_8x8DCT;

                di = 4;

            }



//                fill_intra4x4_pred_table(h);

            for(i=0; i<16; i+=di){

                int mode= pred_intra_mode(h, i);



                if(!get_bits1(&s->gb)){

                    const int rem_mode= get_bits(&s->gb, 3);

                    mode = rem_mode + (rem_mode >= mode);

                }



                if(di==4)

                    fill_rectangle( &h->intra4x4_pred_mode_cache[ scan8[i] ], 2, 2, 8, mode, 1 );

                else

                    h->intra4x4_pred_mode_cache[ scan8[i] ] = mode;

            }

            ff_h264_write_back_intra_pred_mode(h);

            if( ff_h264_check_intra4x4_pred_mode(h) < 0)

                return -1;

        }else{

            h->intra16x16_pred_mode= ff_h264_check_intra_pred_mode(h, h->intra16x16_pred_mode);

            if(h->intra16x16_pred_mode < 0)

                return -1;

        }

        if(CHROMA){

            pred_mode= ff_h264_check_intra_pred_mode(h, get_ue_golomb_31(&s->gb));

            if(pred_mode < 0)

                return -1;

            h->chroma_pred_mode= pred_mode;

        }

    }else if(partition_count==4){

        int i, j, sub_partition_count[4], list, ref[2][4];



        if(h->slice_type_nos == FF_B_TYPE){

            for(i=0; i<4; i++){

                h->sub_mb_type[i]= get_ue_golomb_31(&s->gb);

                if(h->sub_mb_type[i] >=13){

                    av_log(h->s.avctx, AV_LOG_ERROR, "B sub_mb_type %u out of range at %d %d\n", h->sub_mb_type[i], s->mb_x, s->mb_y);

                    return -1;

                }

                sub_partition_count[i]= b_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      b_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

            if(   IS_DIRECT(h->sub_mb_type[0]) || IS_DIRECT(h->sub_mb_type[1])

               || IS_DIRECT(h->sub_mb_type[2]) || IS_DIRECT(h->sub_mb_type[3])) {

                ff_h264_pred_direct_motion(h, &mb_type);

                h->ref_cache[0][scan8[4]] =

                h->ref_cache[1][scan8[4]] =

                h->ref_cache[0][scan8[12]] =

                h->ref_cache[1][scan8[12]] = PART_NOT_AVAILABLE;

            }

        }else{

            assert(h->slice_type_nos == FF_P_TYPE); //FIXME SP correct ?

            for(i=0; i<4; i++){

                h->sub_mb_type[i]= get_ue_golomb_31(&s->gb);

                if(h->sub_mb_type[i] >=4){

                    av_log(h->s.avctx, AV_LOG_ERROR, "P sub_mb_type %u out of range at %d %d\n", h->sub_mb_type[i], s->mb_x, s->mb_y);

                    return -1;

                }

                sub_partition_count[i]= p_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      p_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

        }



        for(list=0; list<h->list_count; list++){

            int ref_count= IS_REF0(mb_type) ? 1 : h->ref_count[list];

            for(i=0; i<4; i++){

                if(IS_DIRECT(h->sub_mb_type[i])) continue;

                if(IS_DIR(h->sub_mb_type[i], 0, list)){

                    unsigned int tmp;

                    if(ref_count == 1){

                        tmp= 0;

                    }else if(ref_count == 2){

                        tmp= get_bits1(&s->gb)^1;

                    }else{

                        tmp= get_ue_golomb_31(&s->gb);

                        if(tmp>=ref_count){

                            av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", tmp);

                            return -1;

                        }

                    }

                    ref[list][i]= tmp;

                }else{

                 //FIXME

                    ref[list][i] = -1;

                }

            }

        }



        if(dct8x8_allowed)

            dct8x8_allowed = get_dct8x8_allowed(h);



        for(list=0; list<h->list_count; list++){

            for(i=0; i<4; i++){

                if(IS_DIRECT(h->sub_mb_type[i])) {

                    h->ref_cache[list][ scan8[4*i] ] = h->ref_cache[list][ scan8[4*i]+1 ];

                    continue;

                }

                h->ref_cache[list][ scan8[4*i]   ]=h->ref_cache[list][ scan8[4*i]+1 ]=

                h->ref_cache[list][ scan8[4*i]+8 ]=h->ref_cache[list][ scan8[4*i]+9 ]= ref[list][i];



                if(IS_DIR(h->sub_mb_type[i], 0, list)){

                    const int sub_mb_type= h->sub_mb_type[i];

                    const int block_width= (sub_mb_type & (MB_TYPE_16x16|MB_TYPE_16x8)) ? 2 : 1;

                    for(j=0; j<sub_partition_count[i]; j++){

                        int mx, my;

                        const int index= 4*i + block_width*j;

                        int16_t (* mv_cache)[2]= &h->mv_cache[list][ scan8[index] ];

                        pred_motion(h, index, block_width, list, h->ref_cache[list][ scan8[index] ], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        if(IS_SUB_8X8(sub_mb_type)){

                            mv_cache[ 1 ][0]=

                            mv_cache[ 8 ][0]= mv_cache[ 9 ][0]= mx;

                            mv_cache[ 1 ][1]=

                            mv_cache[ 8 ][1]= mv_cache[ 9 ][1]= my;

                        }else if(IS_SUB_8X4(sub_mb_type)){

                            mv_cache[ 1 ][0]= mx;

                            mv_cache[ 1 ][1]= my;

                        }else if(IS_SUB_4X8(sub_mb_type)){

                            mv_cache[ 8 ][0]= mx;

                            mv_cache[ 8 ][1]= my;

                        }

                        mv_cache[ 0 ][0]= mx;

                        mv_cache[ 0 ][1]= my;

                    }

                }else{

                    uint32_t *p= (uint32_t *)&h->mv_cache[list][ scan8[4*i] ][0];

                    p[0] = p[1]=

                    p[8] = p[9]= 0;

                }

            }

        }

    }else if(IS_DIRECT(mb_type)){

        ff_h264_pred_direct_motion(h, &mb_type);

        dct8x8_allowed &= h->sps.direct_8x8_inference_flag;

    }else{

        int list, mx, my, i;

         //FIXME we should set ref_idx_l? to 0 if we use that later ...

        if(IS_16X16(mb_type)){

            for(list=0; list<h->list_count; list++){

                    unsigned int val;

                    if(IS_DIR(mb_type, 0, list)){

                        if(h->ref_count[list]==1){

                            val= 0;

                        }else if(h->ref_count[list]==2){

                            val= get_bits1(&s->gb)^1;

                        }else{

                            val= get_ue_golomb_31(&s->gb);

                            if(val >= h->ref_count[list]){

                                av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", val);

                                return -1;

                            }

                        }

                    }else

                        val= LIST_NOT_USED&0xFF;

                    fill_rectangle(&h->ref_cache[list][ scan8[0] ], 4, 4, 8, val, 1);

            }

            for(list=0; list<h->list_count; list++){

                unsigned int val;

                if(IS_DIR(mb_type, 0, list)){

                    pred_motion(h, 0, 4, list, h->ref_cache[list][ scan8[0] ], &mx, &my);

                    mx += get_se_golomb(&s->gb);

                    my += get_se_golomb(&s->gb);

                    tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                    val= pack16to32(mx,my);

                }else

                    val=0;

                fill_rectangle(h->mv_cache[list][ scan8[0] ], 4, 4, 8, val, 4);

            }

        }

        else if(IS_16X8(mb_type)){

            for(list=0; list<h->list_count; list++){

                    for(i=0; i<2; i++){

                        unsigned int val;

                        if(IS_DIR(mb_type, i, list)){

                            if(h->ref_count[list] == 1){

                                val= 0;

                            }else if(h->ref_count[list] == 2){

                                val= get_bits1(&s->gb)^1;

                            }else{

                                val= get_ue_golomb_31(&s->gb);

                                if(val >= h->ref_count[list]){

                                    av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", val);

                                    return -1;

                                }

                            }

                        }else

                            val= LIST_NOT_USED&0xFF;

                        fill_rectangle(&h->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, val, 1);

                    }

            }

            for(list=0; list<h->list_count; list++){

                for(i=0; i<2; i++){

                    unsigned int val;

                    if(IS_DIR(mb_type, i, list)){

                        pred_16x8_motion(h, 8*i, list, h->ref_cache[list][scan8[0] + 16*i], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        val= pack16to32(mx,my);

                    }else

                        val=0;

                    fill_rectangle(h->mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, val, 4);

                }

            }

        }else{

            assert(IS_8X16(mb_type));

            for(list=0; list<h->list_count; list++){

                    for(i=0; i<2; i++){

                        unsigned int val;

                        if(IS_DIR(mb_type, i, list)){ //FIXME optimize

                            if(h->ref_count[list]==1){

                                val= 0;

                            }else if(h->ref_count[list]==2){

                                val= get_bits1(&s->gb)^1;

                            }else{

                                val= get_ue_golomb_31(&s->gb);

                                if(val >= h->ref_count[list]){

                                    av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", val);

                                    return -1;

                                }

                            }

                        }else

                            val= LIST_NOT_USED&0xFF;

                        fill_rectangle(&h->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, val, 1);

                    }

            }

            for(list=0; list<h->list_count; list++){

                for(i=0; i<2; i++){

                    unsigned int val;

                    if(IS_DIR(mb_type, i, list)){

                        pred_8x16_motion(h, i*4, list, h->ref_cache[list][ scan8[0] + 2*i ], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        val= pack16to32(mx,my);

                    }else

                        val=0;

                    fill_rectangle(h->mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, val, 4);

                }

            }

        }

    }



    if(IS_INTER(mb_type))

        write_back_motion(h, mb_type);



    if(!IS_INTRA16x16(mb_type)){

        cbp= get_ue_golomb(&s->gb);

        if(cbp > 47){

            av_log(h->s.avctx, AV_LOG_ERROR, "cbp too large (%u) at %d %d\n", cbp, s->mb_x, s->mb_y);

            return -1;

        }



        if(CHROMA){

            if(IS_INTRA4x4(mb_type)) cbp= golomb_to_intra4x4_cbp[cbp];

            else                     cbp= golomb_to_inter_cbp   [cbp];

        }else{

            if(IS_INTRA4x4(mb_type)) cbp= golomb_to_intra4x4_cbp_gray[cbp];

            else                     cbp= golomb_to_inter_cbp_gray[cbp];

        }

    }

    h->cbp = cbp;



    if(dct8x8_allowed && (cbp&15) && !IS_INTRA(mb_type)){

        if(get_bits1(&s->gb)){

            mb_type |= MB_TYPE_8x8DCT;

            h->cbp_table[mb_xy]= cbp;

        }

    }

    s->current_picture.mb_type[mb_xy]= mb_type;



    if(cbp || IS_INTRA16x16(mb_type)){

        int i8x8, i4x4, chroma_idx;

        int dquant;

        GetBitContext *gb= IS_INTRA(mb_type) ? h->intra_gb_ptr : h->inter_gb_ptr;

        const uint8_t *scan, *scan8x8, *dc_scan;



//        fill_non_zero_count_cache(h);



        if(IS_INTERLACED(mb_type)){

            scan8x8= s->qscale ? h->field_scan8x8_cavlc : h->field_scan8x8_cavlc_q0;

            scan= s->qscale ? h->field_scan : h->field_scan_q0;

            dc_scan= luma_dc_field_scan;

        }else{

            scan8x8= s->qscale ? h->zigzag_scan8x8_cavlc : h->zigzag_scan8x8_cavlc_q0;

            scan= s->qscale ? h->zigzag_scan : h->zigzag_scan_q0;

            dc_scan= luma_dc_zigzag_scan;

        }



        dquant= get_se_golomb(&s->gb);



        if( dquant > 25 || dquant < -26 ){

            av_log(h->s.avctx, AV_LOG_ERROR, "dquant out of range (%d) at %d %d\n", dquant, s->mb_x, s->mb_y);

            return -1;

        }



        s->qscale += dquant;

        if(((unsigned)s->qscale) > 51){

            if(s->qscale<0) s->qscale+= 52;

            else            s->qscale-= 52;

        }



        h->chroma_qp[0]= get_chroma_qp(h, 0, s->qscale);

        h->chroma_qp[1]= get_chroma_qp(h, 1, s->qscale);

        if(IS_INTRA16x16(mb_type)){

            if( decode_residual(h, h->intra_gb_ptr, h->mb, LUMA_DC_BLOCK_INDEX, dc_scan, h->dequant4_coeff[0][s->qscale], 16) < 0){

                return -1; //FIXME continue if partitioned and other return -1 too

            }



            assert((cbp&15) == 0 || (cbp&15) == 15);



            if(cbp&15){

                for(i8x8=0; i8x8<4; i8x8++){

                    for(i4x4=0; i4x4<4; i4x4++){

                        const int index= i4x4 + 4*i8x8;

                        if( decode_residual(h, h->intra_gb_ptr, h->mb + 16*index, index, scan + 1, h->dequant4_coeff[0][s->qscale], 15) < 0 ){

                            return -1;

                        }

                    }

                }

            }else{

                fill_rectangle(&h->non_zero_count_cache[scan8[0]], 4, 4, 8, 0, 1);

            }

        }else{

            for(i8x8=0; i8x8<4; i8x8++){

                if(cbp & (1<<i8x8)){

                    if(IS_8x8DCT(mb_type)){

                        DCTELEM *buf = &h->mb[64*i8x8];

                        uint8_t *nnz;

                        for(i4x4=0; i4x4<4; i4x4++){

                            if( decode_residual(h, gb, buf, i4x4+4*i8x8, scan8x8+16*i4x4,

                                                h->dequant8_coeff[IS_INTRA( mb_type ) ? 0:1][s->qscale], 16) <0 )

                                return -1;

                        }

                        nnz= &h->non_zero_count_cache[ scan8[4*i8x8] ];

                        nnz[0] += nnz[1] + nnz[8] + nnz[9];

                    }else{

                        for(i4x4=0; i4x4<4; i4x4++){

                            const int index= i4x4 + 4*i8x8;



                            if( decode_residual(h, gb, h->mb + 16*index, index, scan, h->dequant4_coeff[IS_INTRA( mb_type ) ? 0:3][s->qscale], 16) <0 ){

                                return -1;

                            }

                        }

                    }

                }else{

                    uint8_t * const nnz= &h->non_zero_count_cache[ scan8[4*i8x8] ];

                    nnz[0] = nnz[1] = nnz[8] = nnz[9] = 0;

                }

            }

        }



        if(cbp&0x30){

            for(chroma_idx=0; chroma_idx<2; chroma_idx++)

                if( decode_residual(h, gb, h->mb + 256 + 16*4*chroma_idx, CHROMA_DC_BLOCK_INDEX, chroma_dc_scan, NULL, 4) < 0){

                    return -1;

                }

        }



        if(cbp&0x20){

            for(chroma_idx=0; chroma_idx<2; chroma_idx++){

                const uint32_t *qmul = h->dequant4_coeff[chroma_idx+1+(IS_INTRA( mb_type ) ? 0:3)][h->chroma_qp[chroma_idx]];

                for(i4x4=0; i4x4<4; i4x4++){

                    const int index= 16 + 4*chroma_idx + i4x4;

                    if( decode_residual(h, gb, h->mb + 16*index, index, scan + 1, qmul, 15) < 0){

                        return -1;

                    }

                }

            }

        }else{

            uint8_t * const nnz= &h->non_zero_count_cache[0];

            nnz[ scan8[16]+0 ] = nnz[ scan8[16]+1 ] =nnz[ scan8[16]+8 ] =nnz[ scan8[16]+9 ] =

            nnz[ scan8[20]+0 ] = nnz[ scan8[20]+1 ] =nnz[ scan8[20]+8 ] =nnz[ scan8[20]+9 ] = 0;

        }

    }else{

        uint8_t * const nnz= &h->non_zero_count_cache[0];

        fill_rectangle(&nnz[scan8[0]], 4, 4, 8, 0, 1);

        nnz[ scan8[16]+0 ] = nnz[ scan8[16]+1 ] =nnz[ scan8[16]+8 ] =nnz[ scan8[16]+9 ] =

        nnz[ scan8[20]+0 ] = nnz[ scan8[20]+1 ] =nnz[ scan8[20]+8 ] =nnz[ scan8[20]+9 ] = 0;

    }

    s->current_picture.qscale_table[mb_xy]= s->qscale;

    write_back_non_zero_count(h);



    if(MB_MBAFF){

        h->ref_count[0] >>= 1;

        h->ref_count[1] >>= 1;

    }



    return 0;

}

static void vnc_display_close(VncDisplay *vs)

{

    if (!vs)

        return;

    g_free(vs->display);

    vs->display = NULL;

    if (vs->lsock != -1) {

        qemu_set_fd_handler2(vs->lsock, NULL, NULL, NULL, NULL);

        close(vs->lsock);

        vs->lsock = -1;

    }

#ifdef CONFIG_VNC_WS

    g_free(vs->ws_display);

    vs->ws_display = NULL;

    if (vs->lwebsock != -1) {

        qemu_set_fd_handler2(vs->lwebsock, NULL, NULL, NULL, NULL);

        close(vs->lwebsock);

        vs->lwebsock = -1;

    }

#endif /* CONFIG_VNC_WS */

    vs->auth = VNC_AUTH_INVALID;

#ifdef CONFIG_VNC_TLS

    vs->subauth = VNC_AUTH_INVALID;

    vs->tls.x509verify = 0;

#endif

}

static int ram_load_postcopy(QEMUFile *f)

{

    int flags = 0, ret = 0;

    bool place_needed = false;

    bool matching_page_sizes = qemu_host_page_size == TARGET_PAGE_SIZE;

    MigrationIncomingState *mis = migration_incoming_get_current();

    /* Temporary page that is later 'placed' */

    void *postcopy_host_page = postcopy_get_tmp_page(mis);

    void *last_host = NULL;



    while (!ret && !(flags & RAM_SAVE_FLAG_EOS)) {

        ram_addr_t addr;

        void *host = NULL;

        void *page_buffer = NULL;

        void *place_source = NULL;

        uint8_t ch;

        bool all_zero = false;



        addr = qemu_get_be64(f);

        flags = addr & ~TARGET_PAGE_MASK;

        addr &= TARGET_PAGE_MASK;



        trace_ram_load_postcopy_loop((uint64_t)addr, flags);

        place_needed = false;

        if (flags & (RAM_SAVE_FLAG_COMPRESS | RAM_SAVE_FLAG_PAGE)) {

            host = host_from_stream_offset(f, addr, flags);

            if (!host) {

                error_report("Illegal RAM offset " RAM_ADDR_FMT, addr);

                ret = -EINVAL;

                break;

            }

            page_buffer = host;

            /*

             * Postcopy requires that we place whole host pages atomically.

             * To make it atomic, the data is read into a temporary page

             * that's moved into place later.

             * The migration protocol uses,  possibly smaller, target-pages

             * however the source ensures it always sends all the components

             * of a host page in order.

             */

            page_buffer = postcopy_host_page +

                          ((uintptr_t)host & ~qemu_host_page_mask);

            /* If all TP are zero then we can optimise the place */

            if (!((uintptr_t)host & ~qemu_host_page_mask)) {

                all_zero = true;

            } else {

                /* not the 1st TP within the HP */

                if (host != (last_host + TARGET_PAGE_SIZE)) {

                    error_report("Non-sequential target page %p/%p\n",

                                  host, last_host);

                    ret = -EINVAL;

                    break;

                }

            }





            /*

             * If it's the last part of a host page then we place the host

             * page

             */

            place_needed = (((uintptr_t)host + TARGET_PAGE_SIZE) &

                                     ~qemu_host_page_mask) == 0;

            place_source = postcopy_host_page;

        }




        switch (flags & ~RAM_SAVE_FLAG_CONTINUE) {

        case RAM_SAVE_FLAG_COMPRESS:

            ch = qemu_get_byte(f);

            memset(page_buffer, ch, TARGET_PAGE_SIZE);

            if (ch) {

                all_zero = false;

            }

            break;



        case RAM_SAVE_FLAG_PAGE:

            all_zero = false;

            if (!place_needed || !matching_page_sizes) {

                qemu_get_buffer(f, page_buffer, TARGET_PAGE_SIZE);

            } else {

                /* Avoids the qemu_file copy during postcopy, which is

                 * going to do a copy later; can only do it when we

                 * do this read in one go (matching page sizes)

                 */

                qemu_get_buffer_in_place(f, (uint8_t **)&place_source,

                                         TARGET_PAGE_SIZE);

            }

            break;

        case RAM_SAVE_FLAG_EOS:

            /* normal exit */

            break;

        default:

            error_report("Unknown combination of migration flags: %#x"

                         " (postcopy mode)", flags);

            ret = -EINVAL;

        }



        if (place_needed) {

            /* This gets called at the last target page in the host page */

            if (all_zero) {

                ret = postcopy_place_page_zero(mis,

                                               host + TARGET_PAGE_SIZE -

                                               qemu_host_page_size);

            } else {

                ret = postcopy_place_page(mis, host + TARGET_PAGE_SIZE -

                                               qemu_host_page_size,

                                               place_source);

            }

        }

        if (!ret) {

            ret = qemu_file_get_error(f);

        }

    }



    return ret;

}

