static int bdrv_inherited_flags(int flags)

{

    /* Enable protocol handling, disable format probing for bs->file */

    flags |= BDRV_O_PROTOCOL;



    /* Our block drivers take care to send flushes and respect unmap policy,

     * so we can enable both unconditionally on lower layers. */

    flags |= BDRV_O_CACHE_WB | BDRV_O_UNMAP;



    /* The backing file of a temporary snapshot is read-only */

    if (flags & BDRV_O_SNAPSHOT) {

        flags &= ~BDRV_O_RDWR;

    }



    /* Clear flags that only apply to the top layer */

    flags &= ~(BDRV_O_SNAPSHOT | BDRV_O_NO_BACKING);



    return flags;

}

void load_seg(int seg_reg, int selector, unsigned int cur_eip)

{

    uint32_t e1, e2;

    int cpl, dpl, rpl;

    SegmentCache *dt;

    int index;

    uint8_t *ptr;



    if ((selector & 0xfffc) == 0) {

        /* null selector case */

        if (seg_reg == R_SS) {

            EIP = cur_eip;

            raise_exception_err(EXCP0D_GPF, 0);

        } else {

            cpu_x86_load_seg_cache(env, seg_reg, selector, NULL, 0, 0);

        }

    } else {



        if (selector & 0x4)

            dt = &env->ldt;

        else

            dt = &env->gdt;

        index = selector & ~7;

        if ((index + 7) > dt->limit) {

            EIP = cur_eip;

            raise_exception_err(EXCP0D_GPF, selector & 0xfffc);

        }

        ptr = dt->base + index;

        e1 = ldl_kernel(ptr);

        e2 = ldl_kernel(ptr + 4);



        if (!(e2 & DESC_S_MASK)) {

            EIP = cur_eip;

            raise_exception_err(EXCP0D_GPF, selector & 0xfffc);

        }

        rpl = selector & 3;

        dpl = (e2 >> DESC_DPL_SHIFT) & 3;

        cpl = env->hflags & HF_CPL_MASK;

        if (seg_reg == R_SS) {

            /* must be writable segment */

            if ((e2 & DESC_CS_MASK) || !(e2 & DESC_W_MASK)) {

                EIP = cur_eip;

                raise_exception_err(EXCP0D_GPF, selector & 0xfffc);

            }

            if (rpl != cpl || dpl != cpl) {

                EIP = cur_eip;

                raise_exception_err(EXCP0D_GPF, selector & 0xfffc);

            }

        } else {

            /* must be readable segment */

            if ((e2 & (DESC_CS_MASK | DESC_R_MASK)) == DESC_CS_MASK) {

                EIP = cur_eip;

                raise_exception_err(EXCP0D_GPF, selector & 0xfffc);

            }



            if (!(e2 & DESC_CS_MASK) || !(e2 & DESC_C_MASK)) {

                /* if not conforming code, test rights */

                if (dpl < cpl || dpl < rpl) {

                    EIP = cur_eip;

                    raise_exception_err(EXCP0D_GPF, selector & 0xfffc);

                }

            }

        }



        if (!(e2 & DESC_P_MASK)) {

            EIP = cur_eip;

            if (seg_reg == R_SS)

                raise_exception_err(EXCP0C_STACK, selector & 0xfffc);

            else

                raise_exception_err(EXCP0B_NOSEG, selector & 0xfffc);

        }



        /* set the access bit if not already set */

        if (!(e2 & DESC_A_MASK)) {

            e2 |= DESC_A_MASK;

            stl_kernel(ptr + 4, e2);

        }



        cpu_x86_load_seg_cache(env, seg_reg, selector, 

                       get_seg_base(e1, e2),

                       get_seg_limit(e1, e2),

                       e2);

#if 0

        fprintf(logfile, "load_seg: sel=0x%04x base=0x%08lx limit=0x%08lx flags=%08x\n", 

                selector, (unsigned long)sc->base, sc->limit, sc->flags);

#endif

    }

}

static void tcg_out_insn_3401(TCGContext *s, AArch64Insn insn, TCGType ext,

                              TCGReg rd, TCGReg rn, uint64_t aimm)

{

    if (aimm > 0xfff) {

        assert((aimm & 0xfff) == 0);

        aimm >>= 12;

        assert(aimm <= 0xfff);

        aimm |= 1 << 12;  /* apply LSL 12 */

    }

    tcg_out32(s, insn | ext << 31 | aimm << 10 | rn << 5 | rd);

}

static int output_frame(AVFilterLink *outlink, int nb_samples)

{

    AVFilterContext *ctx = outlink->src;

    MixContext      *s = ctx->priv;

    AVFilterBufferRef *out_buf, *in_buf;

    int i;



    calculate_scales(s, nb_samples);



    out_buf = ff_get_audio_buffer(outlink, AV_PERM_WRITE, nb_samples);

    if (!out_buf)

        return AVERROR(ENOMEM);



    in_buf = ff_get_audio_buffer(outlink, AV_PERM_WRITE, nb_samples);

    if (!in_buf)

        return AVERROR(ENOMEM);



    for (i = 0; i < s->nb_inputs; i++) {

        if (s->input_state[i] == INPUT_ON) {

            int planes, plane_size, p;



            av_audio_fifo_read(s->fifos[i], (void **)in_buf->extended_data,

                               nb_samples);



            planes     = s->planar ? s->nb_channels : 1;

            plane_size = nb_samples * (s->planar ? 1 : s->nb_channels);

            plane_size = FFALIGN(plane_size, 16);



            for (p = 0; p < planes; p++) {

                s->fdsp.vector_fmac_scalar((float *)out_buf->extended_data[p],

                                           (float *) in_buf->extended_data[p],

                                           s->input_scale[i], plane_size);

            }

        }

    }

    avfilter_unref_buffer(in_buf);



    out_buf->pts = s->next_pts;

    if (s->next_pts != AV_NOPTS_VALUE)

        s->next_pts += nb_samples;



    return ff_filter_samples(outlink, out_buf);

}

static QObject *qmp_output_pop(QmpOutputVisitor *qov, void *qapi)

{

    QStackEntry *e = QSLIST_FIRST(&qov->stack);

    QObject *value;



    assert(e);

    assert(e->qapi == qapi);

    QSLIST_REMOVE_HEAD(&qov->stack, node);

    value = e->value;

    assert(value);

    g_free(e);

    return value;

}

static int add_tonal_components(float *spectrum, int num_components,

                                TonalComponent *components)

{

    int i, j, last_pos = -1;

    float *input, *output;



    for (i = 0; i < num_components; i++) {

        last_pos = FFMAX(components[i].pos + components[i].num_coefs, last_pos);

        input    = components[i].coef;

        output   = &spectrum[components[i].pos];



        for (j = 0; j < components[i].num_coefs; j++)

            output[i] += input[i];

    }



    return last_pos;

}

