static int ipvideo_decode_block_opcode_0x9(IpvideoContext *s, AVFrame *frame)
{
    int x, y;
    unsigned char P[4];
    /* 4-color encoding */
    bytestream2_get_buffer(&s->stream_ptr, P, 4);
    if (P[0] <= P[1]) {
        if (P[2] <= P[3]) {
            /* 1 of 4 colors for each pixel, need 16 more bytes */
            for (y = 0; y < 8; y++) {
                /* get the next set of 8 2-bit flags */
                int flags = bytestream2_get_le16(&s->stream_ptr);
                for (x = 0; x < 8; x++, flags >>= 2)
                    *s->pixel_ptr++ = P[flags & 0x03];
                s->pixel_ptr += s->line_inc;
        } else {
            uint32_t flags;
            /* 1 of 4 colors for each 2x2 block, need 4 more bytes */
            flags = bytestream2_get_le32(&s->stream_ptr);
            for (y = 0; y < 8; y += 2) {
                for (x = 0; x < 8; x += 2, flags >>= 2) {
                    s->pixel_ptr[x                ] =
                    s->pixel_ptr[x + 1            ] =
                    s->pixel_ptr[x +     s->stride] =
                    s->pixel_ptr[x + 1 + s->stride] = P[flags & 0x03];
                s->pixel_ptr += s->stride * 2;
    } else {
        uint64_t flags;
        /* 1 of 4 colors for each 2x1 or 1x2 block, need 8 more bytes */
        flags = bytestream2_get_le64(&s->stream_ptr);
        if (P[2] <= P[3]) {
            for (y = 0; y < 8; y++) {
                for (x = 0; x < 8; x += 2, flags >>= 2) {
                    s->pixel_ptr[x    ] =
                    s->pixel_ptr[x + 1] = P[flags & 0x03];
                s->pixel_ptr += s->stride;
        } else {
            for (y = 0; y < 8; y += 2) {
                for (x = 0; x < 8; x++, flags >>= 2) {
                    s->pixel_ptr[x            ] =
                    s->pixel_ptr[x + s->stride] = P[flags & 0x03];
                s->pixel_ptr += s->stride * 2;
    /* report success */
    return 0;

static int get_refcount(BlockDriverState *bs, int64_t cluster_index)

{

    BDRVQcowState *s = bs->opaque;

    int refcount_table_index, block_index;

    int64_t refcount_block_offset;

    int ret;

    uint16_t *refcount_block;

    uint16_t refcount;



    refcount_table_index = cluster_index >> (s->cluster_bits - REFCOUNT_SHIFT);

    if (refcount_table_index >= s->refcount_table_size)

        return 0;

    refcount_block_offset =

        s->refcount_table[refcount_table_index] & REFT_OFFSET_MASK;

    if (!refcount_block_offset)

        return 0;



    ret = qcow2_cache_get(bs, s->refcount_block_cache, refcount_block_offset,

        (void**) &refcount_block);

    if (ret < 0) {

        return ret;

    }



    block_index = cluster_index &

        ((1 << (s->cluster_bits - REFCOUNT_SHIFT)) - 1);

    refcount = be16_to_cpu(refcount_block[block_index]);



    ret = qcow2_cache_put(bs, s->refcount_block_cache,

        (void**) &refcount_block);

    if (ret < 0) {

        return ret;

    }



    return refcount;

}

static void vnc_desktop_resize(VncState *vs)

{

    DisplaySurface *ds = vs->vd->ds;



    if (vs->csock == -1 || !vnc_has_feature(vs, VNC_FEATURE_RESIZE)) {

        return;

    }

    if (vs->client_width == surface_width(ds) &&

        vs->client_height == surface_height(ds)) {

        return;

    }

    vs->client_width = surface_width(ds);

    vs->client_height = surface_height(ds);

    vnc_lock_output(vs);

    vnc_write_u8(vs, VNC_MSG_SERVER_FRAMEBUFFER_UPDATE);

    vnc_write_u8(vs, 0);

    vnc_write_u16(vs, 1); /* number of rects */

    vnc_framebuffer_update(vs, 0, 0, vs->client_width, vs->client_height,

                           VNC_ENCODING_DESKTOPRESIZE);

    vnc_unlock_output(vs);

    vnc_flush(vs);

}

static int usb_wacom_handle_data(USBDevice *dev, USBPacket *p)

{

    USBWacomState *s = (USBWacomState *) dev;

    uint8_t buf[p->iov.size];

    int ret = 0;



    switch (p->pid) {

    case USB_TOKEN_IN:

        if (p->devep == 1) {

            if (!(s->changed || s->idle))

                return USB_RET_NAK;

            s->changed = 0;

            if (s->mode == WACOM_MODE_HID)

                ret = usb_mouse_poll(s, buf, p->iov.size);

            else if (s->mode == WACOM_MODE_WACOM)

                ret = usb_wacom_poll(s, buf, p->iov.size);

            usb_packet_copy(p, buf, ret);

            break;

        }

        /* Fall through.  */

    case USB_TOKEN_OUT:

    default:

        ret = USB_RET_STALL;

        break;

    }

    return ret;

}

static int webp_decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                             AVPacket *avpkt)

{

    AVFrame * const p = data;

    WebPContext *s = avctx->priv_data;

    GetByteContext gb;

    int ret;

    uint32_t chunk_type, chunk_size;

    int vp8x_flags = 0;



    s->avctx     = avctx;

    s->width     = 0;

    s->height    = 0;

    *got_frame   = 0;

    s->has_alpha = 0;

    bytestream2_init(&gb, avpkt->data, avpkt->size);



    if (bytestream2_get_bytes_left(&gb) < 12)

        return AVERROR_INVALIDDATA;



    if (bytestream2_get_le32(&gb) != MKTAG('R', 'I', 'F', 'F')) {

        av_log(avctx, AV_LOG_ERROR, "missing RIFF tag\n");

        return AVERROR_INVALIDDATA;

    }



    chunk_size = bytestream2_get_le32(&gb);

    if (bytestream2_get_bytes_left(&gb) < chunk_size)

        return AVERROR_INVALIDDATA;



    if (bytestream2_get_le32(&gb) != MKTAG('W', 'E', 'B', 'P')) {

        av_log(avctx, AV_LOG_ERROR, "missing WEBP tag\n");

        return AVERROR_INVALIDDATA;

    }



    while (bytestream2_get_bytes_left(&gb) > 0) {

        char chunk_str[5] = { 0 };



        chunk_type = bytestream2_get_le32(&gb);

        chunk_size = bytestream2_get_le32(&gb);

        if (chunk_size == UINT32_MAX)

            return AVERROR_INVALIDDATA;

        chunk_size += chunk_size & 1;



        if (bytestream2_get_bytes_left(&gb) < chunk_size)

            return AVERROR_INVALIDDATA;



        switch (chunk_type) {

        case MKTAG('V', 'P', '8', ' '):

            if (!*got_frame) {

                ret = vp8_lossy_decode_frame(avctx, p, got_frame,

                                             avpkt->data + bytestream2_tell(&gb),

                                             chunk_size);

                if (ret < 0)

                    return ret;

            }

            bytestream2_skip(&gb, chunk_size);

            break;

        case MKTAG('V', 'P', '8', 'L'):

            if (!*got_frame) {

                ret = vp8_lossless_decode_frame(avctx, p, got_frame,

                                                avpkt->data + bytestream2_tell(&gb),

                                                chunk_size, 0);

                if (ret < 0)

                    return ret;

            }

            bytestream2_skip(&gb, chunk_size);

            break;

        case MKTAG('V', 'P', '8', 'X'):

            vp8x_flags = bytestream2_get_byte(&gb);

            bytestream2_skip(&gb, 3);

            s->width  = bytestream2_get_le24(&gb) + 1;

            s->height = bytestream2_get_le24(&gb) + 1;

            ret = av_image_check_size(s->width, s->height, 0, avctx);

            if (ret < 0)

                return ret;

            break;

        case MKTAG('A', 'L', 'P', 'H'): {

            int alpha_header, filter_m, compression;



            if (!(vp8x_flags & VP8X_FLAG_ALPHA)) {

                av_log(avctx, AV_LOG_WARNING,

                       "ALPHA chunk present, but alpha bit not set in the "

                       "VP8X header\n");

            }

            if (chunk_size == 0) {

                av_log(avctx, AV_LOG_ERROR, "invalid ALPHA chunk size\n");

                return AVERROR_INVALIDDATA;

            }

            alpha_header       = bytestream2_get_byte(&gb);

            s->alpha_data      = avpkt->data + bytestream2_tell(&gb);

            s->alpha_data_size = chunk_size - 1;

            bytestream2_skip(&gb, s->alpha_data_size);



            filter_m    = (alpha_header >> 2) & 0x03;

            compression =  alpha_header       & 0x03;



            if (compression > ALPHA_COMPRESSION_VP8L) {

                av_log(avctx, AV_LOG_VERBOSE,

                       "skipping unsupported ALPHA chunk\n");

            } else {

                s->has_alpha         = 1;

                s->alpha_compression = compression;

                s->alpha_filter      = filter_m;

            }



            break;

        }

        case MKTAG('I', 'C', 'C', 'P'):

        case MKTAG('A', 'N', 'I', 'M'):

        case MKTAG('A', 'N', 'M', 'F'):

        case MKTAG('E', 'X', 'I', 'F'):

        case MKTAG('X', 'M', 'P', ' '):

            AV_WL32(chunk_str, chunk_type);

            av_log(avctx, AV_LOG_VERBOSE, "skipping unsupported chunk: %s\n",

                   chunk_str);

            bytestream2_skip(&gb, chunk_size);

            break;

        default:

            AV_WL32(chunk_str, chunk_type);

            av_log(avctx, AV_LOG_VERBOSE, "skipping unknown chunk: %s\n",

                   chunk_str);

            bytestream2_skip(&gb, chunk_size);

            break;

        }

    }



    if (!*got_frame) {

        av_log(avctx, AV_LOG_ERROR, "image data not found\n");

        return AVERROR_INVALIDDATA;

    }



    return avpkt->size;

}

static int parse_keyframes_index(AVFormatContext *s, AVIOContext *ioc, AVStream *vstream, int64_t max_pos) {

    unsigned int arraylen = 0, timeslen = 0, fileposlen = 0, i;

    double num_val;

    char str_val[256];

    int64_t *times = NULL;

    int64_t *filepositions = NULL;

    int ret = AVERROR(ENOSYS);

    int64_t initial_pos = avio_tell(ioc);

    AVDictionaryEntry *creator = av_dict_get(s->metadata, "metadatacreator",

                                             NULL, 0);



    if (creator && !strcmp(creator->value, "MEGA")) {

        /* Files with this metadatacreator tag seem to have filepositions

         * pointing at the 4 trailer bytes of the previous packet,

         * which isn't the norm (nor what we expect here, nor what

         * jwplayer + lighttpd expect, nor what flvtool2 produces).

         * Just ignore the index in this case, instead of risking trying

         * to adjust it to something that might or might not work. */

        return 0;

    }



    while (avio_tell(ioc) < max_pos - 2 && amf_get_string(ioc, str_val, sizeof(str_val)) > 0) {

        int64_t* current_array;



        // Expect array object in context

        if (avio_r8(ioc) != AMF_DATA_TYPE_ARRAY)

            break;



        arraylen = avio_rb32(ioc);

        /*

         * Expect only 'times' or 'filepositions' sub-arrays in other case refuse to use such metadata

         * for indexing

         */

        if (!strcmp(KEYFRAMES_TIMESTAMP_TAG, str_val) && !times) {

            if (!(times = av_mallocz(sizeof(*times) * arraylen))) {

                ret = AVERROR(ENOMEM);

                goto finish;

            }

            timeslen = arraylen;

            current_array = times;

        } else if (!strcmp(KEYFRAMES_BYTEOFFSET_TAG, str_val) && !filepositions) {

            if (!(filepositions = av_mallocz(sizeof(*filepositions) * arraylen))) {

                ret = AVERROR(ENOMEM);

                goto finish;

            }

            fileposlen = arraylen;

            current_array = filepositions;

        } else // unexpected metatag inside keyframes, will not use such metadata for indexing

            break;



        for (i = 0; i < arraylen && avio_tell(ioc) < max_pos - 1; i++) {

            if (avio_r8(ioc) != AMF_DATA_TYPE_NUMBER)

                goto finish;

            num_val = av_int2dbl(avio_rb64(ioc));

            current_array[i] = num_val;

        }

        if (times && filepositions) {

            // All done, exiting at a position allowing amf_parse_object

            // to finish parsing the object

            ret = 0;

            break;

        }

    }



    if (timeslen == fileposlen)

         for(i = 0; i < arraylen; i++)

             av_add_index_entry(vstream, filepositions[i], times[i]*1000, 0, 0, AVINDEX_KEYFRAME);

    else

        av_log(s, AV_LOG_WARNING, "Invalid keyframes object, skipping.\n");



finish:

    av_freep(&times);

    av_freep(&filepositions);

    // If we got unexpected data, but successfully reset back to

    // the start pos, the caller can continue parsing

    if (ret < 0 && avio_seek(ioc, initial_pos, SEEK_SET) > 0)

        return 0;

    return ret;

}

static int add_metadata_from_side_data(AVCodecContext *avctx, AVFrame *frame)

{

    int size, ret = 0;

    const uint8_t *side_metadata;

    const uint8_t *end;



    side_metadata = av_packet_get_side_data(avctx->pkt,

                                            AV_PKT_DATA_STRINGS_METADATA, &size);

    if (!side_metadata)

        goto end;

    end = side_metadata + size;

    while (side_metadata < end) {

        const uint8_t *key = side_metadata;

        const uint8_t *val = side_metadata + strlen(key) + 1;

        int ret = av_dict_set(avpriv_frame_get_metadatap(frame), key, val, 0);

        if (ret < 0)

            break;

        side_metadata = val + strlen(val) + 1;

    }

end:

    return ret;

}

static int build_table(VLC *vlc, int table_nb_bits, int nb_codes,

                       VLCcode *codes, int flags)

{

    int table_size, table_index, index, code_prefix, symbol, subtable_bits;

    int i, j, k, n, nb, inc;

    uint32_t code;

    VLC_TYPE (*table)[2];



    table_size = 1 << table_nb_bits;

    if (table_nb_bits > 30)

       return -1;

    table_index = alloc_table(vlc, table_size, flags & INIT_VLC_USE_NEW_STATIC);

    av_dlog(NULL, "new table index=%d size=%d\n", table_index, table_size);

    if (table_index < 0)

        return table_index;

    table = &vlc->table[table_index];



    for (i = 0; i < table_size; i++) {

        table[i][1] = 0; //bits

        table[i][0] = -1; //codes

    }



    /* first pass: map codes and compute auxiliary table sizes */

    for (i = 0; i < nb_codes; i++) {

        n      = codes[i].bits;

        code   = codes[i].code;

        symbol = codes[i].symbol;

        av_dlog(NULL, "i=%d n=%d code=0x%x\n", i, n, code);

        if (n <= table_nb_bits) {

            /* no need to add another table */

            j = code >> (32 - table_nb_bits);

            nb = 1 << (table_nb_bits - n);

            inc = 1;

            if (flags & INIT_VLC_LE) {

                j = bitswap_32(code);

                inc = 1 << n;

            }

            for (k = 0; k < nb; k++) {

                av_dlog(NULL, "%4x: code=%d n=%d\n", j, i, n);

                if (table[j][1] /*bits*/ != 0) {

                    av_log(NULL, AV_LOG_ERROR, "incorrect codes\n");

                    return AVERROR_INVALIDDATA;

                }

                table[j][1] = n; //bits

                table[j][0] = symbol;

                j += inc;

            }

        } else {

            /* fill auxiliary table recursively */

            n -= table_nb_bits;

            code_prefix = code >> (32 - table_nb_bits);

            subtable_bits = n;

            codes[i].bits = n;

            codes[i].code = code << table_nb_bits;

            for (k = i+1; k < nb_codes; k++) {

                n = codes[k].bits - table_nb_bits;

                if (n <= 0)

                    break;

                code = codes[k].code;

                if (code >> (32 - table_nb_bits) != code_prefix)

                    break;

                codes[k].bits = n;

                codes[k].code = code << table_nb_bits;

                subtable_bits = FFMAX(subtable_bits, n);

            }

            subtable_bits = FFMIN(subtable_bits, table_nb_bits);

            j = (flags & INIT_VLC_LE) ? bitswap_32(code_prefix) >> (32 - table_nb_bits) : code_prefix;

            table[j][1] = -subtable_bits;

            av_dlog(NULL, "%4x: n=%d (subtable)\n",

                    j, codes[i].bits + table_nb_bits);

            index = build_table(vlc, subtable_bits, k-i, codes+i, flags);

            if (index < 0)

                return index;

            /* note: realloc has been done, so reload tables */

            table = &vlc->table[table_index];

            table[j][0] = index; //code

            av_assert0(table[j][0] == index);

            i = k-1;

        }

    }

    return table_index;

}

static void encode_exponents_blk_ch(uint8_t *exp,

                                    int nb_exps, int exp_strategy,

                                    uint8_t *num_exp_groups)

{

    int group_size, nb_groups, i, j, k, exp_min;



    group_size = exp_strategy + (exp_strategy == EXP_D45);

    *num_exp_groups = (nb_exps + (group_size * 3) - 4) / (3 * group_size);

    nb_groups = *num_exp_groups * 3;



    /* for each group, compute the minimum exponent */

    if (exp_strategy > EXP_D15) {

    k = 1;

    for (i = 1; i <= nb_groups; i++) {

        exp_min = exp[k];

        assert(exp_min >= 0 && exp_min <= 24);

        for (j = 1; j < group_size; j++) {

            if (exp[k+j] < exp_min)

                exp_min = exp[k+j];

        }

        exp[i] = exp_min;

        k += group_size;

    }

    }



    /* constraint for DC exponent */

    if (exp[0] > 15)

        exp[0] = 15;



    /* decrease the delta between each groups to within 2 so that they can be

       differentially encoded */

    for (i = 1; i <= nb_groups; i++)

        exp[i] = FFMIN(exp[i], exp[i-1] + 2);

    for (i = nb_groups-1; i >= 0; i--)

        exp[i] = FFMIN(exp[i], exp[i+1] + 2);



    /* now we have the exponent values the decoder will see */

    if (exp_strategy > EXP_D15) {

    k = nb_groups * group_size;

    for (i = nb_groups; i > 0; i--) {

        for (j = 0; j < group_size; j++)

            exp[k-j] = exp[i];

        k -= group_size;

    }

    }

}

