static int color_request_frame(AVFilterLink *link)

{

    ColorContext *color = link->src->priv;

    AVFilterBufferRef *picref = ff_get_video_buffer(link, AV_PERM_WRITE, color->w, color->h);

    int ret;



    picref->video->pixel_aspect = (AVRational) {1, 1};

