static int poll_filter(OutputStream *ost)

{

    OutputFile    *of = output_files[ost->file_index];

    AVFrame *filtered_frame = NULL;

    int frame_size, ret;



    if (!ost->filtered_frame && !(ost->filtered_frame = avcodec_alloc_frame())) {

        return AVERROR(ENOMEM);

    } else

        avcodec_get_frame_defaults(ost->filtered_frame);

    filtered_frame = ost->filtered_frame;



    if (ost->enc->type == AVMEDIA_TYPE_AUDIO &&

        !(ost->enc->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE))

        ret = av_buffersink_get_samples(ost->filter->filter, filtered_frame,

                                         ost->st->codec->frame_size);

    else

        ret = av_buffersink_get_frame(ost->filter->filter, filtered_frame);



    if (ret < 0)

        return ret;



    if (filtered_frame->pts != AV_NOPTS_VALUE) {

        filtered_frame->pts = av_rescale_q(filtered_frame->pts,

                                           ost->filter->filter->inputs[0]->time_base,

                                           ost->st->codec->time_base) -

                              av_rescale_q(of->start_time,

                                           AV_TIME_BASE_Q,

                                           ost->st->codec->time_base);

    }



    switch (ost->filter->filter->inputs[0]->type) {

    case AVMEDIA_TYPE_VIDEO:

        if (!ost->frame_aspect_ratio)

            ost->st->codec->sample_aspect_ratio = filtered_frame->sample_aspect_ratio;



        do_video_out(of->ctx, ost, filtered_frame, &frame_size);

        if (vstats_filename && frame_size)

            do_video_stats(ost, frame_size);

        break;

    case AVMEDIA_TYPE_AUDIO:

        do_audio_out(of->ctx, ost, filtered_frame);

        break;

    default:

        // TODO support subtitle filters

        av_assert0(0);

    }



    av_frame_unref(filtered_frame);



    return 0;

}

static void qapi_clone_type_str(Visitor *v, const char *name, char **obj,

                                 Error **errp)

{

    QapiCloneVisitor *qcv = to_qcv(v);



    assert(qcv->depth);

    /*

     * Pointer was already cloned by g_memdup; create fresh copy.

     * Note that as long as qmp-output-visitor accepts NULL instead of

     * "", then we must do likewise. However, we want to obey the

     * input visitor semantics of never producing NULL when the empty

     * string is intended.

     */

    *obj = g_strdup(*obj ?: "");

}

static int parse_presentation_segment(AVCodecContext *avctx,

                                      const uint8_t *buf, int buf_size,

                                      int64_t pts)

{

    PGSSubContext *ctx = avctx->priv_data;



    int x, y, ret;



    int w = bytestream_get_be16(&buf);

    int h = bytestream_get_be16(&buf);



    ctx->presentation.pts = pts;



    av_dlog(avctx, "Video Dimensions %dx%d\n",

            w, h);

    ret = ff_set_dimensions(avctx, w, h);

    if (ret < 0)

        return ret;



    /* Skip 1 bytes of unknown, frame rate? */

    buf++;



    ctx->presentation.id_number = bytestream_get_be16(&buf);



    /*

     * Skip 3 bytes of unknown:

     *     state

     *     palette_update_flag (0x80),

     *     palette_id_to_use,

     */

    buf += 3;



    ctx->presentation.object_number = bytestream_get_byte(&buf);

    ctx->presentation.composition_flag = 0;

    if (!ctx->presentation.object_number)

        return 0;



    /*

     * Skip 3 bytes of unknown:

     *     object_id_ref (2 bytes),

     *     window_id_ref,

     */

    buf += 3;

    ctx->presentation.composition_flag = bytestream_get_byte(&buf);



    x = bytestream_get_be16(&buf);

    y = bytestream_get_be16(&buf);



    /* TODO If cropping, cropping_x, cropping_y, cropping_width, cropping_height (all 2 bytes).*/



    av_dlog(avctx, "Subtitle Placement x=%d, y=%d\n", x, y);



    if (x > avctx->width || y > avctx->height) {

        av_log(avctx, AV_LOG_ERROR, "Subtitle out of video bounds. x = %d, y = %d, video width = %d, video height = %d.\n",

               x, y, avctx->width, avctx->height);

        x = 0; y = 0;

    }



    /* Fill in dimensions */

    ctx->presentation.x = x;

    ctx->presentation.y = y;



    return 0;

}

static void do_video_stats(AVOutputStream *ost, 

                         AVInputStream *ist,

                         int frame_size)

{

    static FILE *fvstats=NULL;

    static INT64 total_size = 0;

    struct tm *today;

    time_t today2;

    char filename[40];

    AVCodecContext *enc;

    int frame_number;

    INT64 ti;

    double ti1, bitrate, avg_bitrate;



    if (!fvstats) {

        today2 = time(NULL);

        today = localtime(&today2);

        sprintf(filename, "vstats_%02d%02d%02d.log", today->tm_hour,

                                               today->tm_min,

                                               today->tm_sec);

        fvstats = fopen(filename,"w");

        if (!fvstats) {

            perror("fopen");

            exit(1);

        }

    }



    ti = MAXINT64;

    enc = &ost->st->codec;

    total_size += frame_size;

    if (enc->codec_type == CODEC_TYPE_VIDEO) {

        frame_number = ist->frame_number;

        fprintf(fvstats, "frame= %5d q= %2d ", frame_number, enc->quality);

        if (do_psnr)

            fprintf(fvstats, "PSNR= %6.2f ", enc->psnr_y);



        fprintf(fvstats,"f_size= %6d ", frame_size);

        /* compute min pts value */

        if (!ist->discard && ist->pts < ti) {

            ti = ist->pts;

        }

        ti1 = (double)ti / 1000000.0;

        if (ti1 < 0.01)

            ti1 = 0.01;



        bitrate = (double)(frame_size * 8) * enc->frame_rate / FRAME_RATE_BASE / 1000.0;

        avg_bitrate = (double)(total_size * 8) / ti1 / 1000.0;

        fprintf(fvstats, "s_size= %8.0fkB time= %0.3f br= %7.1fkbits/s avg_br= %7.1fkbits/s ",

            (double)total_size / 1024, ti1, bitrate, avg_bitrate);

        fprintf(fvstats,"type= %s\n", enc->key_frame == 1 ? "I" : "P");        

    }







}

