                   (cond & wsource->condition),

                   user_data);

}

int rtjpeg_decode_frame_yuv420(RTJpegContext *c, AVFrame *f,

                               const uint8_t *buf, int buf_size) {

    GetBitContext gb;

    int w = c->w / 16, h = c->h / 16;

    int x, y;

    uint8_t *y1 = f->data[0], *y2 = f->data[0] + 8 * f->linesize[0];

    uint8_t *u = f->data[1], *v = f->data[2];

    init_get_bits(&gb, buf, buf_size * 8);

    for (y = 0; y < h; y++) {

        for (x = 0; x < w; x++) {

            DCTELEM *block = c->block;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y1, f->linesize[0], block);

            y1 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y1, f->linesize[0], block);

            y1 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y2, f->linesize[0], block);

            y2 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y2, f->linesize[0], block);

            y2 += 8;

            if (get_block(&gb, block, c->scan, c->cquant) > 0)

                c->dsp->idct_put(u, f->linesize[1], block);

            u += 8;

            if (get_block(&gb, block, c->scan, c->cquant) > 0)

                c->dsp->idct_put(v, f->linesize[2], block);

            v += 8;

        }

        y1 += 2 * 8 * (f->linesize[0] - w);

        y2 += 2 * 8 * (f->linesize[0] - w);

        u += 8 * (f->linesize[1] - w);

        v += 8 * (f->linesize[2] - w);

    }

    return get_bits_count(&gb) / 8;

}

static void do_branch(DisasContext *dc, int32_t offset, uint32_t insn, int cc,

                      TCGv r_cond)

{

    unsigned int cond = GET_FIELD(insn, 3, 6), a = (insn & (1 << 29));

    target_ulong target = dc->pc + offset;



    if (cond == 0x0) {

        /* unconditional not taken */

        if (a) {

            dc->pc = dc->npc + 4;

            dc->npc = dc->pc + 4;

        } else {

            dc->pc = dc->npc;

            dc->npc = dc->pc + 4;

        }

    } else if (cond == 0x8) {

        /* unconditional taken */

        if (a) {

            dc->pc = target;

            dc->npc = dc->pc + 4;

        } else {

            dc->pc = dc->npc;

            dc->npc = target;

            tcg_gen_mov_tl(cpu_pc, cpu_npc);

        }

    } else {

        flush_cond(dc, r_cond);

        gen_cond(r_cond, cc, cond, dc);

        if (a) {

            gen_branch_a(dc, target, dc->npc, r_cond);

            dc->is_br = 1;

        } else {

            dc->pc = dc->npc;

            dc->jump_pc[0] = target;

            dc->jump_pc[1] = dc->npc + 4;

            dc->npc = JUMP_PC;

        }

    }

}

static void dxva_adjust_hwframes(AVCodecContext *avctx, AVHWFramesContext *frames_ctx)

{

    FFDXVASharedContext *sctx = DXVA_SHARED_CONTEXT(avctx);

    int surface_alignment, num_surfaces;



    frames_ctx->format = sctx->pix_fmt;



    /* decoding MPEG-2 requires additional alignment on some Intel GPUs,

    but it causes issues for H.264 on certain AMD GPUs..... */

    if (avctx->codec_id == AV_CODEC_ID_MPEG2VIDEO)

        surface_alignment = 32;

    /* the HEVC DXVA2 spec asks for 128 pixel aligned surfaces to ensure

    all coding features have enough room to work with */

    else if (avctx->codec_id == AV_CODEC_ID_HEVC)

        surface_alignment = 128;

    else

        surface_alignment = 16;



    /* 4 base work surfaces */

    num_surfaces = 4;



    /* add surfaces based on number of possible refs */

    if (avctx->codec_id == AV_CODEC_ID_H264 || avctx->codec_id == AV_CODEC_ID_HEVC)

        num_surfaces += 16;

    else

        num_surfaces += 2;



    /* add extra surfaces for frame threading */

    if (avctx->active_thread_type & FF_THREAD_FRAME)

        num_surfaces += avctx->thread_count;



    frames_ctx->sw_format = avctx->sw_pix_fmt == AV_PIX_FMT_YUV420P10 ?

                            AV_PIX_FMT_P010 : AV_PIX_FMT_NV12;

    frames_ctx->width = FFALIGN(avctx->coded_width, surface_alignment);

    frames_ctx->height = FFALIGN(avctx->coded_height, surface_alignment);

    frames_ctx->initial_pool_size = num_surfaces;





#if CONFIG_DXVA2

    if (frames_ctx->format == AV_PIX_FMT_DXVA2_VLD) {

        AVDXVA2FramesContext *frames_hwctx = frames_ctx->hwctx;



        frames_hwctx->surface_type = DXVA2_VideoDecoderRenderTarget;

    }

#endif



#if CONFIG_D3D11VA

    if (frames_ctx->format == AV_PIX_FMT_D3D11) {

        AVD3D11VAFramesContext *frames_hwctx = frames_ctx->hwctx;



        frames_hwctx->BindFlags |= D3D11_BIND_DECODER;

    }

#endif

}

static void qobject_input_start_list(Visitor *v, const char *name,

