        break;

    case 0x1c8 ... 0x1cf: /* bswap reg */

        reg = (b & 7) | REX_B(s);

#ifdef TARGET_X86_64

        if (dflag == 2) {

            gen_op_mov_TN_reg(OT_QUAD, 0, reg);

