    dev->bus->memread(dev->bus, addr, buf, len);

}

static int cow_open(BlockDriverState *bs, QDict *options, int flags,

                    Error **errp)

{

    BDRVCowState *s = bs->opaque;

    struct cow_header_v2 cow_header;

    int bitmap_size;

    int64_t size;

    int ret;



    /* see if it is a cow image */

    ret = bdrv_pread(bs->file, 0, &cow_header, sizeof(cow_header));

    if (ret < 0) {

        goto fail;

    }



    if (be32_to_cpu(cow_header.magic) != COW_MAGIC) {

        error_setg(errp, "Image not in COW format");

        ret = -EINVAL;

        goto fail;

    }



    if (be32_to_cpu(cow_header.version) != COW_VERSION) {

        char version[64];

        snprintf(version, sizeof(version),

               "COW version %" PRIu32, cow_header.version);

        error_set(errp, QERR_UNKNOWN_BLOCK_FORMAT_FEATURE,

            bs->device_name, "cow", version);

        ret = -ENOTSUP;

        goto fail;

    }



    /* cow image found */

    size = be64_to_cpu(cow_header.size);

    bs->total_sectors = size / 512;



    pstrcpy(bs->backing_file, sizeof(bs->backing_file),

            cow_header.backing_file);



    bitmap_size = ((bs->total_sectors + 7) >> 3) + sizeof(cow_header);

    s->cow_sectors_offset = (bitmap_size + 511) & ~511;

    qemu_co_mutex_init(&s->lock);

    return 0;

 fail:

    return ret;

}

static void test_visitor_in_native_list_bool(TestInputVisitorData *data,

                                            const void *unused)

{

    UserDefNativeListUnion *cvalue = NULL;

    boolList *elem = NULL;

    Visitor *v;

    GString *gstr_list = g_string_new("");

    GString *gstr_union = g_string_new("");

    int i;



    for (i = 0; i < 32; i++) {

        g_string_append_printf(gstr_list, "%s",

                               (i % 3 == 0) ? "true" : "false");

        if (i != 31) {

            g_string_append(gstr_list, ", ");

        }

    }

    g_string_append_printf(gstr_union,  "{ 'type': 'boolean', 'data': [ %s ] }",

                           gstr_list->str);

    v = visitor_input_test_init_raw(data,  gstr_union->str);



    visit_type_UserDefNativeListUnion(v, NULL, &cvalue, &error_abort);

    g_assert(cvalue != NULL);

    g_assert_cmpint(cvalue->type, ==, USER_DEF_NATIVE_LIST_UNION_KIND_BOOLEAN);



    for (i = 0, elem = cvalue->u.boolean.data; elem; elem = elem->next, i++) {

        g_assert_cmpint(elem->value, ==, (i % 3 == 0) ? 1 : 0);

    }



    g_string_free(gstr_union, true);

    g_string_free(gstr_list, true);

    qapi_free_UserDefNativeListUnion(cvalue);

}

static void qdict_array_split_test(void)

{

    QDict *test_dict = qdict_new();

    QDict *dict1, *dict2;

    QList *test_list;



    /*

     * Test the split of

     *

     * {

     *     "1.x": 0,

     *     "3.y": 1,

     *     "0.a": 42,

     *     "o.o": 7,

     *     "0.b": 23

     * }

     *

     * to

     *

     * [

     *     {

     *         "a": 42,

     *         "b": 23

     *     },

     *     {

     *         "x": 0

     *     }

     * ]

     *

     * and

     *

     * {

     *     "3.y": 1,

     *     "o.o": 7

     * }

     *

     * (remaining in the old QDict)

     *

     * This example is given in the comment of qdict_array_split().

     */



    qdict_put(test_dict, "1.x", qint_from_int(0));

    qdict_put(test_dict, "3.y", qint_from_int(1));

    qdict_put(test_dict, "0.a", qint_from_int(42));

    qdict_put(test_dict, "o.o", qint_from_int(7));

    qdict_put(test_dict, "0.b", qint_from_int(23));



    qdict_array_split(test_dict, &test_list);



    dict1 = qobject_to_qdict(qlist_pop(test_list));

    dict2 = qobject_to_qdict(qlist_pop(test_list));



    g_assert(dict1);

    g_assert(dict2);

    g_assert(qlist_empty(test_list));



    QDECREF(test_list);



    g_assert(qdict_get_int(dict1, "a") == 42);

    g_assert(qdict_get_int(dict1, "b") == 23);



    g_assert(qdict_size(dict1) == 2);



    QDECREF(dict1);



    g_assert(qdict_get_int(dict2, "x") == 0);



    g_assert(qdict_size(dict2) == 1);



    QDECREF(dict2);



    g_assert(qdict_get_int(test_dict, "3.y") == 1);

    g_assert(qdict_get_int(test_dict, "o.o") == 7);



    g_assert(qdict_size(test_dict) == 2);



    QDECREF(test_dict);

}

static int amovie_request_frame(AVFilterLink *outlink)

{

    MovieContext *movie = outlink->src->priv;

    int ret;



    if (movie->is_done)

        return AVERROR_EOF;

    do {

        if ((ret = amovie_get_samples(outlink)) < 0)

            return ret;

    } while (!movie->samplesref);



    ff_filter_samples(outlink, avfilter_ref_buffer(movie->samplesref, ~0));

    avfilter_unref_buffer(movie->samplesref);

    movie->samplesref = NULL;



    return 0;

}

void qmp_guest_fstrim(bool has_minimum, int64_t minimum, Error **errp)

{

    int ret = 0;

    FsMountList mounts;

    struct FsMount *mount;

    int fd;

    Error *local_err = NULL;

    struct fstrim_range r = {

        .start = 0,

        .len = -1,

        .minlen = has_minimum ? minimum : 0,

    };



    slog("guest-fstrim called");



    QTAILQ_INIT(&mounts);

    build_fs_mount_list(&mounts, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    QTAILQ_FOREACH(mount, &mounts, next) {

        fd = qemu_open(mount->dirname, O_RDONLY);

        if (fd == -1) {

            error_setg_errno(errp, errno, "failed to open %s", mount->dirname);

            goto error;

        }



        /* We try to cull filesytems we know won't work in advance, but other

         * filesytems may not implement fstrim for less obvious reasons.  These

         * will report EOPNOTSUPP; we simply ignore these errors.  Any other

         * error means an unexpected error, so return it in those cases.  In

         * some other cases ENOTTY will be reported (e.g. CD-ROMs).

         */

        ret = ioctl(fd, FITRIM, &r);

        if (ret == -1) {

            if (errno != ENOTTY && errno != EOPNOTSUPP) {

                error_setg_errno(errp, errno, "failed to trim %s",

                                 mount->dirname);

                close(fd);

                goto error;

            }

        }

        close(fd);

    }



error:

    free_fs_mount_list(&mounts);

}

