static void thread_pool_cancel(BlockDriverAIOCB *acb)

{

    ThreadPoolElement *elem = (ThreadPoolElement *)acb;

    ThreadPool *pool = elem->pool;



    trace_thread_pool_cancel(elem, elem->common.opaque);



    qemu_mutex_lock(&pool->lock);

    if (elem->state == THREAD_QUEUED &&

        /* No thread has yet started working on elem. we can try to "steal"

         * the item from the worker if we can get a signal from the

         * semaphore.  Because this is non-blocking, we can do it with

         * the lock taken and ensure that elem will remain THREAD_QUEUED.

         */

        qemu_sem_timedwait(&pool->sem, 0) == 0) {

        QTAILQ_REMOVE(&pool->request_list, elem, reqs);

        elem->state = THREAD_CANCELED;

        event_notifier_set(&pool->notifier);

    } else {

        pool->pending_cancellations++;

        while (elem->state != THREAD_CANCELED && elem->state != THREAD_DONE) {

            qemu_cond_wait(&pool->check_cancel, &pool->lock);

        }

        pool->pending_cancellations--;

    }

    qemu_mutex_unlock(&pool->lock);


}

static void *aio_thread(void *unused)

{

    sigset_t set;



    /* block all signals */

    sigfillset(&set);

    sigprocmask(SIG_BLOCK, &set, NULL);



    while (1) {

        struct qemu_paiocb *aiocb;

        size_t offset;

        int ret = 0;



        pthread_mutex_lock(&lock);



        while (TAILQ_EMPTY(&request_list) &&

               !(ret == ETIMEDOUT)) {

            struct timespec ts = { 0 };

            qemu_timeval tv;



            qemu_gettimeofday(&tv);

            ts.tv_sec = tv.tv_sec + 10;

            ret = pthread_cond_timedwait(&cond, &lock, &ts);

        }



        if (ret == ETIMEDOUT)

            break;



        aiocb = TAILQ_FIRST(&request_list);

        TAILQ_REMOVE(&request_list, aiocb, node);



        offset = 0;

        aiocb->active = 1;



        idle_threads--;

        pthread_mutex_unlock(&lock);



        while (offset < aiocb->aio_nbytes) {

            ssize_t len;



            if (aiocb->is_write)

                len = pwrite(aiocb->aio_fildes,

                             (const char *)aiocb->aio_buf + offset,

                             aiocb->aio_nbytes - offset,

                             aiocb->aio_offset + offset);

            else

                len = pread(aiocb->aio_fildes,

                            (char *)aiocb->aio_buf + offset,

                            aiocb->aio_nbytes - offset,

                            aiocb->aio_offset + offset);



            if (len == -1 && errno == EINTR)

                continue;

            else if (len == -1) {

                pthread_mutex_lock(&lock);

                aiocb->ret = -errno;

                pthread_mutex_unlock(&lock);

                break;

            } else if (len == 0)

                break;



            offset += len;



            pthread_mutex_lock(&lock);

            aiocb->ret = offset;

            pthread_mutex_unlock(&lock);

        }



        pthread_mutex_lock(&lock);

        idle_threads++;

        pthread_mutex_unlock(&lock);



        sigqueue(getpid(),

                 aiocb->aio_sigevent.sigev_signo,

                 aiocb->aio_sigevent.sigev_value);

    }



    idle_threads--;

    cur_threads--;

    pthread_mutex_unlock(&lock);



    return NULL;

}

static int qio_channel_websock_handshake_send_response(QIOChannelWebsock *ioc,

                                                       const char *key,

                                                       Error **errp)

{

    char combined_key[QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

                      QIO_CHANNEL_WEBSOCK_GUID_LEN + 1];

    char *accept = NULL, *response = NULL;

    size_t responselen;



    g_strlcpy(combined_key, key, QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN + 1);

    g_strlcat(combined_key, QIO_CHANNEL_WEBSOCK_GUID,

              QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

              QIO_CHANNEL_WEBSOCK_GUID_LEN + 1);



    /* hash and encode it */

    if (qcrypto_hash_base64(QCRYPTO_HASH_ALG_SHA1,

                            combined_key,

                            QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

                            QIO_CHANNEL_WEBSOCK_GUID_LEN,

                            &accept,

                            errp) < 0) {

        return -1;

    }



    response = g_strdup_printf(QIO_CHANNEL_WEBSOCK_HANDSHAKE_RESPONSE, accept);

    responselen = strlen(response);

    buffer_reserve(&ioc->encoutput, responselen);

    buffer_append(&ioc->encoutput, response, responselen);



    g_free(accept);

    g_free(response);



    return 0;

}

static uint32_t mipid_txrx(void *opaque, uint32_t cmd, int len)

{

    struct mipid_s *s = (struct mipid_s *) opaque;

    uint8_t ret;



    if (len > 9) {

        hw_error("%s: FIXME: bad SPI word width %i\n", __FUNCTION__, len);

    }



    if (s->p >= ARRAY_SIZE(s->resp)) {

        ret = 0;

    } else {

        ret = s->resp[s->p++];

    }

    if (s->pm-- > 0) {

        s->param[s->pm] = cmd;

    } else {

        s->cmd = cmd;

    }



    switch (s->cmd) {

    case 0x00:	/* NOP */

        break;



    case 0x01:	/* SWRESET */

        mipid_reset(s);

        break;



    case 0x02:	/* BSTROFF */

        s->booster = 0;

        break;

    case 0x03:	/* BSTRON */

        s->booster = 1;

        break;



    case 0x04:	/* RDDID */

        s->p = 0;

        s->resp[0] = (s->id >> 16) & 0xff;

        s->resp[1] = (s->id >>  8) & 0xff;

        s->resp[2] = (s->id >>  0) & 0xff;

        break;



    case 0x06:	/* RD_RED */

    case 0x07:	/* RD_GREEN */

        /* XXX the bootloader sometimes issues RD_BLUE meaning RDDID so

         * for the bootloader one needs to change this.  */

    case 0x08:	/* RD_BLUE */

        s->p = 0;

        /* TODO: return first pixel components */

        s->resp[0] = 0x01;

        break;



    case 0x09:	/* RDDST */

        s->p = 0;

        s->resp[0] = s->booster << 7;

        s->resp[1] = (5 << 4) | (s->partial << 2) |

                (s->sleep << 1) | s->normal;

        s->resp[2] = (s->vscr << 7) | (s->invert << 5) |

                (s->onoff << 2) | (s->te << 1) | (s->gamma >> 2);

        s->resp[3] = s->gamma << 6;

        break;



    case 0x0a:	/* RDDPM */

        s->p = 0;

        s->resp[0] = (s->onoff << 2) | (s->normal << 3) | (s->sleep << 4) |

                (s->partial << 5) | (s->sleep << 6) | (s->booster << 7);

        break;

    case 0x0b:	/* RDDMADCTR */

        s->p = 0;

        s->resp[0] = 0;

        break;

    case 0x0c:	/* RDDCOLMOD */

        s->p = 0;

        s->resp[0] = 5;	/* 65K colours */

        break;

    case 0x0d:	/* RDDIM */

        s->p = 0;

        s->resp[0] = (s->invert << 5) | (s->vscr << 7) | s->gamma;

        break;

    case 0x0e:	/* RDDSM */

        s->p = 0;

        s->resp[0] = s->te << 7;

        break;

    case 0x0f:	/* RDDSDR */

        s->p = 0;

        s->resp[0] = s->selfcheck;

        break;



    case 0x10:	/* SLPIN */

        s->sleep = 1;

        break;

    case 0x11:	/* SLPOUT */

        s->sleep = 0;

        s->selfcheck ^= 1 << 6;	/* POFF self-diagnosis Ok */

        break;



    case 0x12:	/* PTLON */

        s->partial = 1;

        s->normal = 0;

        s->vscr = 0;

        break;

    case 0x13:	/* NORON */

        s->partial = 0;

        s->normal = 1;

        s->vscr = 0;

        break;



    case 0x20:	/* INVOFF */

        s->invert = 0;

        break;

    case 0x21:	/* INVON */

        s->invert = 1;

        break;



    case 0x22:	/* APOFF */

    case 0x23:	/* APON */

        goto bad_cmd;



    case 0x25:	/* WRCNTR */

        if (s->pm < 0) {

            s->pm = 1;

        }

        goto bad_cmd;



    case 0x26:	/* GAMSET */

        if (!s->pm) {

            s->gamma = ctz32(s->param[0] & 0xf);

            if (s->gamma == 32) {

                s->gamma = -1; /* XXX: should this be 0? */

            }

        } else if (s->pm < 0) {

            s->pm = 1;

        }

        break;



    case 0x28:	/* DISPOFF */

        s->onoff = 0;

        break;

    case 0x29:	/* DISPON */

        s->onoff = 1;

        break;



    case 0x2a:	/* CASET */

    case 0x2b:	/* RASET */

    case 0x2c:	/* RAMWR */

    case 0x2d:	/* RGBSET */

    case 0x2e:	/* RAMRD */

    case 0x30:	/* PTLAR */

    case 0x33:	/* SCRLAR */

        goto bad_cmd;



    case 0x34:	/* TEOFF */

        s->te = 0;

        break;

    case 0x35:	/* TEON */

        if (!s->pm) {

            s->te = 1;

        } else if (s->pm < 0) {

            s->pm = 1;

        }

        break;



    case 0x36:	/* MADCTR */

        goto bad_cmd;



    case 0x37:	/* VSCSAD */

        s->partial = 0;

        s->normal = 0;

        s->vscr = 1;

        break;



    case 0x38:	/* IDMOFF */

    case 0x39:	/* IDMON */

    case 0x3a:	/* COLMOD */

        goto bad_cmd;



    case 0xb0:	/* CLKINT / DISCTL */

    case 0xb1:	/* CLKEXT */

        if (s->pm < 0) {

            s->pm = 2;

        }

        break;



    case 0xb4:	/* FRMSEL */

        break;



    case 0xb5:	/* FRM8SEL */

    case 0xb6:	/* TMPRNG / INIESC */

    case 0xb7:	/* TMPHIS / NOP2 */

    case 0xb8:	/* TMPREAD / MADCTL */

    case 0xba:	/* DISTCTR */

    case 0xbb:	/* EPVOL */

        goto bad_cmd;



    case 0xbd:	/* Unknown */

        s->p = 0;

        s->resp[0] = 0;

        s->resp[1] = 1;

        break;



    case 0xc2:	/* IFMOD */

        if (s->pm < 0) {

            s->pm = 2;

        }

        break;



    case 0xc6:	/* PWRCTL */

    case 0xc7:	/* PPWRCTL */

    case 0xd0:	/* EPWROUT */

    case 0xd1:	/* EPWRIN */

    case 0xd4:	/* RDEV */

    case 0xd5:	/* RDRR */

        goto bad_cmd;



    case 0xda:	/* RDID1 */

        s->p = 0;

        s->resp[0] = (s->id >> 16) & 0xff;

        break;

    case 0xdb:	/* RDID2 */

        s->p = 0;

        s->resp[0] = (s->id >>  8) & 0xff;

        break;

    case 0xdc:	/* RDID3 */

        s->p = 0;

        s->resp[0] = (s->id >>  0) & 0xff;

        break;



    default:

    bad_cmd:

        qemu_log_mask(LOG_GUEST_ERROR,

                      "%s: unknown command %02x\n", __func__, s->cmd);

        break;

    }



    return ret;

}

static inline int get_phys_addr(CPUARMState *env, target_ulong address,

                                int access_type, int is_user,

                                hwaddr *phys_ptr, int *prot,

                                target_ulong *page_size)

{

    /* This is not entirely correct as get_phys_addr() can also be called

     * from ats_write() for an address translation of a specific regime.

     */

    uint32_t sctlr = A32_BANKED_CURRENT_REG_GET(env, sctlr);



    /* Fast Context Switch Extension.  */

    if (address < 0x02000000)

        address += env->cp15.c13_fcse;



    if ((sctlr & SCTLR_M) == 0) {

        /* MMU/MPU disabled.  */

        *phys_ptr = address;

        *prot = PAGE_READ | PAGE_WRITE | PAGE_EXEC;

        *page_size = TARGET_PAGE_SIZE;

        return 0;

    } else if (arm_feature(env, ARM_FEATURE_MPU)) {

        *page_size = TARGET_PAGE_SIZE;

	return get_phys_addr_mpu(env, address, access_type, is_user, phys_ptr,

				 prot);

    } else if (extended_addresses_enabled(env)) {

        return get_phys_addr_lpae(env, address, access_type, is_user, phys_ptr,

                                  prot, page_size);

    } else if (sctlr & SCTLR_XP) {

        return get_phys_addr_v6(env, address, access_type, is_user, phys_ptr,

                                prot, page_size);

    } else {

        return get_phys_addr_v5(env, address, access_type, is_user, phys_ptr,

                                prot, page_size);

    }

}

int avfilter_graph_send_command(AVFilterGraph *graph, const char *target, const char *cmd, const char *arg, char *res, int res_len, int flags)

{

    int i, r = AVERROR(ENOSYS);



    if(!graph)

        return r;



    if((flags & AVFILTER_CMD_FLAG_ONE) && !(flags & AVFILTER_CMD_FLAG_FAST)) {

        r=avfilter_graph_send_command(graph, target, cmd, arg, res, res_len, flags | AVFILTER_CMD_FLAG_FAST);

        if(r != AVERROR(ENOSYS))

            return r;

    }



    if(res_len && res)

        res[0]= 0;



    for (i = 0; i < graph->filter_count; i++) {

        AVFilterContext *filter = graph->filters[i];

        if(!strcmp(target, "all") || !strcmp(target, filter->name) || !strcmp(target, filter->filter->name)){

            r = avfilter_process_command(filter, cmd, arg, res, res_len, flags);

            if(r != AVERROR(ENOSYS)) {

                if((flags & AVFILTER_CMD_FLAG_ONE) || r<0)

                    return r;

            }

        }

    }



    return r;

}

static void unplug_disks(PCIBus *b, PCIDevice *d, void *o)

{

    /* We have to ignore passthrough devices */

    if (!strcmp(d->name, "xen-pci-passthrough")) {

        return;

    }



    switch (pci_get_word(d->config + PCI_CLASS_DEVICE)) {

    case PCI_CLASS_STORAGE_IDE:

        pci_piix3_xen_ide_unplug(DEVICE(d));

        break;



    case PCI_CLASS_STORAGE_SCSI:

    case PCI_CLASS_STORAGE_EXPRESS:

        object_unparent(OBJECT(d));

        break;



    default:

        break;

    }

}

int ff_rtsp_fetch_packet(AVFormatContext *s, AVPacket *pkt)

{

    RTSPState *rt = s->priv_data;

    int ret, len;

    RTSPStream *rtsp_st, *first_queue_st = NULL;

    int64_t wait_end = 0;



    if (rt->nb_byes == rt->nb_rtsp_streams)

        return AVERROR_EOF;



    /* get next frames from the same RTP packet */

    if (rt->cur_transport_priv) {

        if (rt->transport == RTSP_TRANSPORT_RDT) {

            ret = ff_rdt_parse_packet(rt->cur_transport_priv, pkt, NULL, 0);

        } else if (rt->transport == RTSP_TRANSPORT_RTP) {

            ret = ff_rtp_parse_packet(rt->cur_transport_priv, pkt, NULL, 0);

        } else if (rt->ts && CONFIG_RTPDEC) {

            ret = ff_mpegts_parse_packet(rt->ts, pkt, rt->recvbuf + rt->recvbuf_pos, rt->recvbuf_len - rt->recvbuf_pos);

            if (ret >= 0) {

                rt->recvbuf_pos += ret;

                ret = rt->recvbuf_pos < rt->recvbuf_len;

            }

        } else

            ret = -1;

        if (ret == 0) {

            rt->cur_transport_priv = NULL;

            return 0;

        } else if (ret == 1) {

            return 0;

        } else

            rt->cur_transport_priv = NULL;

    }



redo:

    if (rt->transport == RTSP_TRANSPORT_RTP) {

        int i;

        int64_t first_queue_time = 0;

        for (i = 0; i < rt->nb_rtsp_streams; i++) {

            RTPDemuxContext *rtpctx = rt->rtsp_streams[i]->transport_priv;

            int64_t queue_time;

            if (!rtpctx)

                continue;

            queue_time = ff_rtp_queued_packet_time(rtpctx);

            if (queue_time && (queue_time - first_queue_time < 0 ||

                               !first_queue_time)) {

                first_queue_time = queue_time;

                first_queue_st   = rt->rtsp_streams[i];

            }

        }

        if (first_queue_time) {

            wait_end = first_queue_time + s->max_delay;

        } else {

            wait_end = 0;

            first_queue_st = NULL;

        }

    }



    /* read next RTP packet */

    if (!rt->recvbuf) {

        rt->recvbuf = av_malloc(RECVBUF_SIZE);

        if (!rt->recvbuf)

            return AVERROR(ENOMEM);

    }



    switch(rt->lower_transport) {

    default:

#if CONFIG_RTSP_DEMUXER

    case RTSP_LOWER_TRANSPORT_TCP:

        len = ff_rtsp_tcp_read_packet(s, &rtsp_st, rt->recvbuf, RECVBUF_SIZE);

        break;

#endif

    case RTSP_LOWER_TRANSPORT_UDP:

    case RTSP_LOWER_TRANSPORT_UDP_MULTICAST:

        len = udp_read_packet(s, &rtsp_st, rt->recvbuf, RECVBUF_SIZE, wait_end);

        if (len > 0 && rtsp_st->transport_priv && rt->transport == RTSP_TRANSPORT_RTP)

            ff_rtp_check_and_send_back_rr(rtsp_st->transport_priv, rtsp_st->rtp_handle, NULL, len);

        break;

    case RTSP_LOWER_TRANSPORT_CUSTOM:

        if (first_queue_st && rt->transport == RTSP_TRANSPORT_RTP &&

            wait_end && wait_end < av_gettime_relative())

            len = AVERROR(EAGAIN);

        else

            len = ffio_read_partial(s->pb, rt->recvbuf, RECVBUF_SIZE);

        len = pick_stream(s, &rtsp_st, rt->recvbuf, len);

        if (len > 0 && rtsp_st->transport_priv && rt->transport == RTSP_TRANSPORT_RTP)

            ff_rtp_check_and_send_back_rr(rtsp_st->transport_priv, NULL, s->pb, len);

        break;

    }

    if (len == AVERROR(EAGAIN) && first_queue_st &&

        rt->transport == RTSP_TRANSPORT_RTP) {

        rtsp_st = first_queue_st;

        ret = ff_rtp_parse_packet(rtsp_st->transport_priv, pkt, NULL, 0);

        goto end;

    }

    if (len < 0)

        return len;

    if (len == 0)

        return AVERROR_EOF;

    if (rt->transport == RTSP_TRANSPORT_RDT) {

        ret = ff_rdt_parse_packet(rtsp_st->transport_priv, pkt, &rt->recvbuf, len);

    } else if (rt->transport == RTSP_TRANSPORT_RTP) {

        ret = ff_rtp_parse_packet(rtsp_st->transport_priv, pkt, &rt->recvbuf, len);

        if (rtsp_st->feedback) {

            AVIOContext *pb = NULL;

            if (rt->lower_transport == RTSP_LOWER_TRANSPORT_CUSTOM)

                pb = s->pb;

            ff_rtp_send_rtcp_feedback(rtsp_st->transport_priv, rtsp_st->rtp_handle, pb);

        }

        if (ret < 0) {

            /* Either bad packet, or a RTCP packet. Check if the

             * first_rtcp_ntp_time field was initialized. */

            RTPDemuxContext *rtpctx = rtsp_st->transport_priv;

            if (rtpctx->first_rtcp_ntp_time != AV_NOPTS_VALUE) {

                /* first_rtcp_ntp_time has been initialized for this stream,

                 * copy the same value to all other uninitialized streams,

                 * in order to map their timestamp origin to the same ntp time

                 * as this one. */

                int i;

                AVStream *st = NULL;

                if (rtsp_st->stream_index >= 0)

                    st = s->streams[rtsp_st->stream_index];

                for (i = 0; i < rt->nb_rtsp_streams; i++) {

                    RTPDemuxContext *rtpctx2 = rt->rtsp_streams[i]->transport_priv;

                    AVStream *st2 = NULL;

                    if (rt->rtsp_streams[i]->stream_index >= 0)

                        st2 = s->streams[rt->rtsp_streams[i]->stream_index];

                    if (rtpctx2 && st && st2 &&

                        rtpctx2->first_rtcp_ntp_time == AV_NOPTS_VALUE) {

                        rtpctx2->first_rtcp_ntp_time = rtpctx->first_rtcp_ntp_time;

                        rtpctx2->rtcp_ts_offset = av_rescale_q(

                            rtpctx->rtcp_ts_offset, st->time_base,

                            st2->time_base);

                    }

                }

            }

            if (ret == -RTCP_BYE) {

                rt->nb_byes++;



                av_log(s, AV_LOG_DEBUG, "Received BYE for stream %d (%d/%d)\n",

                       rtsp_st->stream_index, rt->nb_byes, rt->nb_rtsp_streams);



                if (rt->nb_byes == rt->nb_rtsp_streams)

                    return AVERROR_EOF;

            }

        }

    } else if (rt->ts && CONFIG_RTPDEC) {

        ret = ff_mpegts_parse_packet(rt->ts, pkt, rt->recvbuf, len);

        if (ret >= 0) {

            if (ret < len) {

                rt->recvbuf_len = len;

                rt->recvbuf_pos = ret;

                rt->cur_transport_priv = rt->ts;

                return 1;

            } else {

                ret = 0;

            }

        }

    } else {

        return AVERROR_INVALIDDATA;

    }

end:

    if (ret < 0)

        goto redo;

    if (ret == 1)

        /* more packets may follow, so we save the RTP context */

        rt->cur_transport_priv = rtsp_st->transport_priv;



    return ret;

}

static void vnc_dpy_switch(DisplayChangeListener *dcl,

                           DisplaySurface *surface)

{

    VncDisplay *vd = container_of(dcl, VncDisplay, dcl);

    VncState *vs;



    vnc_abort_display_jobs(vd);



    /* server surface */

    qemu_pixman_image_unref(vd->server);

    vd->ds = surface;

    vd->server = pixman_image_create_bits(VNC_SERVER_FB_FORMAT,

                                          surface_width(vd->ds),

                                          surface_height(vd->ds),

                                          NULL, 0);



    /* guest surface */

#if 0 /* FIXME */

    if (ds_get_bytes_per_pixel(ds) != vd->guest.ds->pf.bytes_per_pixel)

        console_color_init(ds);

#endif

    qemu_pixman_image_unref(vd->guest.fb);

    vd->guest.fb = pixman_image_ref(surface->image);

    vd->guest.format = surface->format;

    VNC_SET_VISIBLE_PIXELS_DIRTY(vd->guest.dirty,

                                 surface_width(vd->ds),

                                 surface_height(vd->ds));



    QTAILQ_FOREACH(vs, &vd->clients, next) {

        vnc_colordepth(vs);

        vnc_desktop_resize(vs);

        if (vs->vd->cursor) {

            vnc_cursor_define(vs);

        }

        VNC_SET_VISIBLE_PIXELS_DIRTY(vs->dirty,

                                     surface_width(vd->ds),

                                     surface_height(vd->ds));

    }

}

static void set_pixel_format(VncState *vs,

			     int bits_per_pixel, int depth,

			     int big_endian_flag, int true_color_flag,

			     int red_max, int green_max, int blue_max,

			     int red_shift, int green_shift, int blue_shift)

{

    int host_big_endian_flag;



#ifdef WORDS_BIGENDIAN

    host_big_endian_flag = 1;

#else

    host_big_endian_flag = 0;

#endif

    if (!true_color_flag) {

    fail:

	vnc_client_error(vs);

        return;

    }

    if (bits_per_pixel == 32 &&

        host_big_endian_flag == big_endian_flag &&

        red_max == 0xff && green_max == 0xff && blue_max == 0xff &&

        red_shift == 16 && green_shift == 8 && blue_shift == 0) {

        vs->depth = 4;

        vs->write_pixels = vnc_write_pixels_copy;

        vs->send_hextile_tile = send_hextile_tile_32;

    } else

    if (bits_per_pixel == 16 &&

        host_big_endian_flag == big_endian_flag &&

        red_max == 31 && green_max == 63 && blue_max == 31 &&

        red_shift == 11 && green_shift == 5 && blue_shift == 0) {

        vs->depth = 2;

        vs->write_pixels = vnc_write_pixels_copy;

        vs->send_hextile_tile = send_hextile_tile_16;

    } else

    if (bits_per_pixel == 8 &&

        red_max == 7 && green_max == 7 && blue_max == 3 &&

        red_shift == 5 && green_shift == 2 && blue_shift == 0) {

        vs->depth = 1;

        vs->write_pixels = vnc_write_pixels_copy;

        vs->send_hextile_tile = send_hextile_tile_8;

    } else

    {

        /* generic and slower case */

        if (bits_per_pixel != 8 &&

            bits_per_pixel != 16 &&

            bits_per_pixel != 32)

            goto fail;

        vs->depth = 4;

        vs->red_shift = red_shift;

        vs->red_max = red_max;

        vs->red_shift1 = 24 - compute_nbits(red_max);

        vs->green_shift = green_shift;

        vs->green_max = green_max;

        vs->green_shift1 = 16 - compute_nbits(green_max);

        vs->blue_shift = blue_shift;

        vs->blue_max = blue_max;

        vs->blue_shift1 = 8 - compute_nbits(blue_max);

        vs->pix_bpp = bits_per_pixel / 8;

        vs->pix_big_endian = big_endian_flag;

        vs->write_pixels = vnc_write_pixels_generic;

        vs->send_hextile_tile = send_hextile_tile_generic;

    }



    vnc_dpy_resize(vs->ds, vs->ds->width, vs->ds->height);

    memset(vs->dirty_row, 0xFF, sizeof(vs->dirty_row));

    memset(vs->old_data, 42, vs->ds->linesize * vs->ds->height);



    vga_hw_invalidate();

    vga_hw_update();

}

static int decode_pce(AVCodecContext *avctx, MPEG4AudioConfig *m4ac,

                      uint8_t (*layout_map)[3],

                      GetBitContext *gb)

{

    int num_front, num_side, num_back, num_lfe, num_assoc_data, num_cc, sampling_index;

    int comment_len;

    int tags;



    skip_bits(gb, 2);  // object_type



    sampling_index = get_bits(gb, 4);

    if (m4ac->sampling_index != sampling_index)

        av_log(avctx, AV_LOG_WARNING, "Sample rate index in program config element does not match the sample rate index configured by the container.\n");



    num_front       = get_bits(gb, 4);

    num_side        = get_bits(gb, 4);

    num_back        = get_bits(gb, 4);

    num_lfe         = get_bits(gb, 2);

    num_assoc_data  = get_bits(gb, 3);

    num_cc          = get_bits(gb, 4);



    if (get_bits1(gb))

        skip_bits(gb, 4); // mono_mixdown_tag

    if (get_bits1(gb))

        skip_bits(gb, 4); // stereo_mixdown_tag



    if (get_bits1(gb))

        skip_bits(gb, 3); // mixdown_coeff_index and pseudo_surround



    if (get_bits_left(gb) < 4 * (num_front + num_side + num_back + num_lfe + num_assoc_data + num_cc)) {

        av_log(avctx, AV_LOG_ERROR, overread_err);

        return -1;

    }

    decode_channel_map(layout_map       , AAC_CHANNEL_FRONT, gb, num_front);

    tags = num_front;

    decode_channel_map(layout_map + tags, AAC_CHANNEL_SIDE,  gb, num_side);

    tags += num_side;

    decode_channel_map(layout_map + tags, AAC_CHANNEL_BACK,  gb, num_back);

    tags += num_back;

    decode_channel_map(layout_map + tags, AAC_CHANNEL_LFE,   gb, num_lfe);

    tags += num_lfe;



    skip_bits_long(gb, 4 * num_assoc_data);



    decode_channel_map(layout_map + tags, AAC_CHANNEL_CC,    gb, num_cc);

    tags += num_cc;



    align_get_bits(gb);



    /* comment field, first byte is length */

    comment_len = get_bits(gb, 8) * 8;

    if (get_bits_left(gb) < comment_len) {

        av_log(avctx, AV_LOG_ERROR, overread_err);

        return -1;

    }

    skip_bits_long(gb, comment_len);

    return tags;

}

