    w = (x + w) / VNC_STAT_RECT;

    h = (y + h) / VNC_STAT_RECT;

    x /= VNC_STAT_RECT;

    y /= VNC_STAT_RECT;



    for (j = y; j <= y + h; j++) {

        for (i = x; i <= x + w; i++) {

            vs->lossy_rect[j][i] = 1;

        }

    }

}

void helper_lsl(void)

{

    unsigned int selector, limit;

    uint32_t e1, e2;



    CC_SRC = cc_table[CC_OP].compute_all() & ~CC_Z;

    selector = T0 & 0xffff;

    if (load_segment(&e1, &e2, selector) != 0)

        return;

    limit = (e1 & 0xffff) | (e2 & 0x000f0000);

    if (e2 & (1 << 23))

        limit = (limit << 12) | 0xfff;

    T1 = limit;

    CC_SRC |= CC_Z;

}

static int mxf_read_local_tags(MXFContext *mxf, KLVPacket *klv, int (*read_child)(), int ctx_size, enum MXFMetadataSetType type)

{

    ByteIOContext *pb = mxf->fc->pb;

    MXFMetadataSet *ctx = ctx_size ? av_mallocz(ctx_size) : mxf;

    uint64_t klv_end = url_ftell(pb) + klv->length;



    if (!ctx)

        return -1;

    while (url_ftell(pb) + 4 < klv_end) {

        int tag = get_be16(pb);

        int size = get_be16(pb); /* KLV specified by 0x53 */

        uint64_t next = url_ftell(pb) + size;

        UID uid;



        if (!size) { /* ignore empty tag, needed for some files with empty UMID tag */

            av_log(mxf->fc, AV_LOG_ERROR, "local tag 0x%04X with 0 size\n", tag);

            continue;

        }

        if (tag > 0x7FFF) { /* dynamic tag */

            int i;

            for (i = 0; i < mxf->local_tags_count; i++) {

                int local_tag = AV_RB16(mxf->local_tags+i*18);

                if (local_tag == tag) {

                    memcpy(uid, mxf->local_tags+i*18+2, 16);

                    dprintf(mxf->fc, "local tag 0x%04X\n", local_tag);

#ifdef DEBUG

                    PRINT_KEY(mxf->fc, "uid", uid);

#endif

                }

            }

        }

        if (ctx_size && tag == 0x3C0A)

            get_buffer(pb, ctx->uid, 16);

        else

            read_child(ctx, pb, tag, size, uid);



        url_fseek(pb, next, SEEK_SET);

    }

    if (ctx_size) ctx->type = type;

    return ctx_size ? mxf_add_metadata_set(mxf, ctx) : 0;

}

vpc_co_pwritev(BlockDriverState *bs, uint64_t offset, uint64_t bytes,

               QEMUIOVector *qiov, int flags)

{

    BDRVVPCState *s = bs->opaque;

    int64_t image_offset;

    int64_t n_bytes;

    int64_t bytes_done = 0;

    int ret;

    VHDFooter *footer =  (VHDFooter *) s->footer_buf;

    QEMUIOVector local_qiov;



    if (be32_to_cpu(footer->type) == VHD_FIXED) {

        return bdrv_co_pwritev(bs->file, offset, bytes, qiov, 0);

    }



    qemu_co_mutex_lock(&s->lock);

    qemu_iovec_init(&local_qiov, qiov->niov);



    while (bytes > 0) {

        image_offset = get_image_offset(bs, offset, true);

        n_bytes = MIN(bytes, s->block_size - (offset % s->block_size));



        if (image_offset == -1) {

            image_offset = alloc_block(bs, offset);

            if (image_offset < 0) {

                ret = image_offset;

                goto fail;

            }

        }



        qemu_iovec_reset(&local_qiov);

        qemu_iovec_concat(&local_qiov, qiov, bytes_done, n_bytes);



        ret = bdrv_co_pwritev(bs->file, image_offset, n_bytes,

                              &local_qiov, 0);

        if (ret < 0) {

            goto fail;

        }



        bytes -= n_bytes;

        offset += n_bytes;

        bytes_done += n_bytes;

    }



    ret = 0;

fail:

    qemu_iovec_destroy(&local_qiov);

    qemu_co_mutex_unlock(&s->lock);



    return ret;

}

static PullupField *make_field_queue(PullupContext *s, int len)

{

    PullupField *head, *f;



    f = head = av_mallocz(sizeof(*head));

    if (!f)

        return NULL;



    if (alloc_metrics(s, f) < 0) {

        av_free(f);

        return NULL;

    }



    for (; len > 0; len--) {

        f->next = av_mallocz(sizeof(*f->next));

        if (!f->next) {

            free_field_queue(head, &f);

            return NULL;

        }



        f->next->prev = f;

        f = f->next;

        if (alloc_metrics(s, f) < 0) {

            free_field_queue(head, &f);

            return NULL;

        }

    }



    f->next = head;

    head->prev = f;



    return head;

}

static void create_gic(VirtBoardInfo *vbi, qemu_irq *pic, bool secure)

{

    /* We create a standalone GIC v2 */

    DeviceState *gicdev;

    SysBusDevice *gicbusdev;

    const char *gictype;

    int i;



    gictype = gic_class_name();



    gicdev = qdev_create(NULL, gictype);

    qdev_prop_set_uint32(gicdev, "revision", 2);

    qdev_prop_set_uint32(gicdev, "num-cpu", smp_cpus);

    /* Note that the num-irq property counts both internal and external

     * interrupts; there are always 32 of the former (mandated by GIC spec).

     */

    qdev_prop_set_uint32(gicdev, "num-irq", NUM_IRQS + 32);

    if (!kvm_irqchip_in_kernel()) {

        qdev_prop_set_bit(gicdev, "has-security-extensions", secure);

    }

    qdev_init_nofail(gicdev);

    gicbusdev = SYS_BUS_DEVICE(gicdev);

    sysbus_mmio_map(gicbusdev, 0, vbi->memmap[VIRT_GIC_DIST].base);

    sysbus_mmio_map(gicbusdev, 1, vbi->memmap[VIRT_GIC_CPU].base);



    /* Wire the outputs from each CPU's generic timer to the

     * appropriate GIC PPI inputs, and the GIC's IRQ output to

     * the CPU's IRQ input.

     */

    for (i = 0; i < smp_cpus; i++) {

        DeviceState *cpudev = DEVICE(qemu_get_cpu(i));

        int ppibase = NUM_IRQS + i * GIC_INTERNAL + GIC_NR_SGIS;

        int irq;

        /* Mapping from the output timer irq lines from the CPU to the

         * GIC PPI inputs we use for the virt board.

         */

        const int timer_irq[] = {

            [GTIMER_PHYS] = ARCH_TIMER_NS_EL1_IRQ,

            [GTIMER_VIRT] = ARCH_TIMER_VIRT_IRQ,

            [GTIMER_HYP]  = ARCH_TIMER_NS_EL2_IRQ,

            [GTIMER_SEC]  = ARCH_TIMER_S_EL1_IRQ,

        };



        for (irq = 0; irq < ARRAY_SIZE(timer_irq); irq++) {

            qdev_connect_gpio_out(cpudev, irq,

                                  qdev_get_gpio_in(gicdev,

                                                   ppibase + timer_irq[irq]));

        }



        sysbus_connect_irq(gicbusdev, i, qdev_get_gpio_in(cpudev, ARM_CPU_IRQ));

        sysbus_connect_irq(gicbusdev, i + smp_cpus,

                           qdev_get_gpio_in(cpudev, ARM_CPU_FIQ));

    }



    for (i = 0; i < NUM_IRQS; i++) {

        pic[i] = qdev_get_gpio_in(gicdev, i);

    }



    fdt_add_gic_node(vbi);



    create_v2m(vbi, pic);

}

static int mpegps_read_pes_header(AVFormatContext *s,

                                  int64_t *ppos, int *pstart_code,

                                  int64_t *ppts, int64_t *pdts)

{

    MpegDemuxContext *m = s->priv_data;

    int len, size, startcode, c, flags, header_len;

    int64_t pts, dts, last_pos;



    last_pos = -1;

 redo:

        /* next start code (should be immediately after) */

        m->header_state = 0xff;

        size = MAX_SYNC_SIZE;

        startcode = find_next_start_code(&s->pb, &size, &m->header_state);

    //printf("startcode=%x pos=0x%"PRIx64"\n", startcode, url_ftell(&s->pb));

    if (startcode < 0)

        return AVERROR_IO;

    if (startcode == PACK_START_CODE)

        goto redo;

    if (startcode == SYSTEM_HEADER_START_CODE)

        goto redo;

    if (startcode == PADDING_STREAM ||

        startcode == PRIVATE_STREAM_2) {

        /* skip them */

        len = get_be16(&s->pb);

        url_fskip(&s->pb, len);

        goto redo;

    }

    if (startcode == PROGRAM_STREAM_MAP) {

        mpegps_psm_parse(m, &s->pb);

        goto redo;

    }



    /* find matching stream */

    if (!((startcode >= 0x1c0 && startcode <= 0x1df) ||

          (startcode >= 0x1e0 && startcode <= 0x1ef) ||

          (startcode == 0x1bd)))

        goto redo;

    if (ppos) {

        *ppos = url_ftell(&s->pb) - 4;

    }

    len = get_be16(&s->pb);

    pts = AV_NOPTS_VALUE;

    dts = AV_NOPTS_VALUE;

    /* stuffing */

    for(;;) {

        if (len < 1)

            goto redo;

        c = get_byte(&s->pb);

        len--;

        /* XXX: for mpeg1, should test only bit 7 */

        if (c != 0xff)

            break;

    }

    if ((c & 0xc0) == 0x40) {

        /* buffer scale & size */

        if (len < 2)

            goto redo;

        get_byte(&s->pb);

        c = get_byte(&s->pb);

        len -= 2;

    }

    if ((c & 0xf0) == 0x20) {

        if (len < 4)

            goto redo;

        dts = pts = get_pts(&s->pb, c);

        len -= 4;

    } else if ((c & 0xf0) == 0x30) {

        if (len < 9)

            goto redo;

        pts = get_pts(&s->pb, c);

        dts = get_pts(&s->pb, -1);

        len -= 9;

    } else if ((c & 0xc0) == 0x80) {

        /* mpeg 2 PES */

#if 0 /* some streams have this field set for no apparent reason */

        if ((c & 0x30) != 0) {

            /* Encrypted multiplex not handled */

            goto redo;

        }

#endif

        flags = get_byte(&s->pb);

        header_len = get_byte(&s->pb);

        len -= 2;

        if (header_len > len)

            goto redo;

        if ((flags & 0xc0) == 0x80) {

            dts = pts = get_pts(&s->pb, -1);

            if (header_len < 5)

                goto redo;

            header_len -= 5;

            len -= 5;

        } if ((flags & 0xc0) == 0xc0) {

            pts = get_pts(&s->pb, -1);

            dts = get_pts(&s->pb, -1);

            if (header_len < 10)

                goto redo;

            header_len -= 10;

            len -= 10;

        }

        len -= header_len;

        while (header_len > 0) {

            get_byte(&s->pb);

            header_len--;

        }

    }

    else if( c!= 0xf )

        goto redo;



    if (startcode == PRIVATE_STREAM_1 && !m->psm_es_type[startcode & 0xff]) {

        if (len < 1)

            goto redo;

        startcode = get_byte(&s->pb);

        len--;

        if (startcode >= 0x80 && startcode <= 0xbf) {

            /* audio: skip header */

            if (len < 3)

                goto redo;

            get_byte(&s->pb);

            get_byte(&s->pb);

            get_byte(&s->pb);

            len -= 3;

        }

    }

    if(dts != AV_NOPTS_VALUE && ppos){

        int i;

        for(i=0; i<s->nb_streams; i++){

            if(startcode == s->streams[i]->id) {

                av_add_index_entry(s->streams[i], *ppos, dts, 0, 0, AVINDEX_KEYFRAME /* FIXME keyframe? */);

            }

        }

    }



    *pstart_code = startcode;

    *ppts = pts;

    *pdts = dts;

    return len;

}

