static inline int gen_intermediate_code_internal(CPUState *env, 

                                                 TranslationBlock *tb, 

                                                 int search_pc)

{

    DisasContext dc1, *dc = &dc1;

    uint16_t *gen_opc_end;

    int j, lj;

    target_ulong pc_start;

    uint32_t next_page_start;



    /* generate intermediate code */

    pc_start = tb->pc;



    dc->tb = tb;



    gen_opc_ptr = gen_opc_buf;

    gen_opc_end = gen_opc_buf + OPC_MAX_SIZE;

    gen_opparam_ptr = gen_opparam_buf;



    dc->is_jmp = DISAS_NEXT;

    dc->pc = pc_start;

    dc->singlestep_enabled = env->singlestep_enabled;

    dc->condjmp = 0;

    dc->thumb = env->thumb;


#if !defined(CONFIG_USER_ONLY)

    dc->user = (env->uncached_cpsr & 0x1f) == ARM_CPU_MODE_USR;

#endif

    next_page_start = (pc_start & TARGET_PAGE_MASK) + TARGET_PAGE_SIZE;

    nb_gen_labels = 0;

    lj = -1;

    do {

        if (env->nb_breakpoints > 0) {

            for(j = 0; j < env->nb_breakpoints; j++) {

                if (env->breakpoints[j] == dc->pc) {

                    gen_op_movl_T0_im((long)dc->pc);

                    gen_op_movl_reg_TN[0][15]();

                    gen_op_debug();

                    dc->is_jmp = DISAS_JUMP;

                    break;

                }

            }

        }

        if (search_pc) {

            j = gen_opc_ptr - gen_opc_buf;

            if (lj < j) {

                lj++;

                while (lj < j)

                    gen_opc_instr_start[lj++] = 0;

            }

            gen_opc_pc[lj] = dc->pc;

            gen_opc_instr_start[lj] = 1;

        }



        if (env->thumb)

          disas_thumb_insn(dc);

        else

          disas_arm_insn(env, dc);



        if (dc->condjmp && !dc->is_jmp) {

            gen_set_label(dc->condlabel);

            dc->condjmp = 0;

        }

        /* Terminate the TB on memory ops if watchpoints are present.  */

        /* FIXME: This should be replacd by the deterministic execution

         * IRQ raising bits.  */

        if (dc->is_mem && env->nb_watchpoints)

            break;



        /* Translation stops when a conditional branch is enoutered.

         * Otherwise the subsequent code could get translated several times.

         * Also stop translation when a page boundary is reached.  This

         * ensures prefech aborts occur at the right place.  */

    } while (!dc->is_jmp && gen_opc_ptr < gen_opc_end &&

             !env->singlestep_enabled &&

             dc->pc < next_page_start);

    /* At this stage dc->condjmp will only be set when the skipped

     * instruction was a conditional branch, and the PC has already been

     * written.  */

    if (__builtin_expect(env->singlestep_enabled, 0)) {

        /* Make sure the pc is updated, and raise a debug exception.  */

        if (dc->condjmp) {

            gen_op_debug();

            gen_set_label(dc->condlabel);

        }

        if (dc->condjmp || !dc->is_jmp) {

            gen_op_movl_T0_im((long)dc->pc);

            gen_op_movl_reg_TN[0][15]();

            dc->condjmp = 0;

        }

        gen_op_debug();

    } else {

        switch(dc->is_jmp) {

        case DISAS_NEXT:

            gen_goto_tb(dc, 1, dc->pc);

            break;

        default:

        case DISAS_JUMP:

        case DISAS_UPDATE:

            /* indicate that the hash table must be used to find the next TB */

            gen_op_movl_T0_0();

            gen_op_exit_tb();

            break;

        case DISAS_TB_JUMP:

            /* nothing more to generate */

            break;

        }

        if (dc->condjmp) {

            gen_set_label(dc->condlabel);

            gen_goto_tb(dc, 1, dc->pc);

            dc->condjmp = 0;

        }

    }

    *gen_opc_ptr = INDEX_op_end;



#ifdef DEBUG_DISAS

    if (loglevel & CPU_LOG_TB_IN_ASM) {

        fprintf(logfile, "----------------\n");

        fprintf(logfile, "IN: %s\n", lookup_symbol(pc_start));

        target_disas(logfile, pc_start, dc->pc - pc_start, env->thumb);

        fprintf(logfile, "\n");

        if (loglevel & (CPU_LOG_TB_OP)) {

            fprintf(logfile, "OP:\n");

            dump_ops(gen_opc_buf, gen_opparam_buf);

            fprintf(logfile, "\n");

        }

    }

#endif

    if (search_pc) {

        j = gen_opc_ptr - gen_opc_buf;

        lj++;

        while (lj <= j)

            gen_opc_instr_start[lj++] = 0;

        tb->size = 0;

    } else {

        tb->size = dc->pc - pc_start;

    }

    return 0;

}

void decode_mb_coeffs(VP8Context *s, VP8ThreadData *td, VP56RangeCoder *c,

                      VP8Macroblock *mb, uint8_t t_nnz[9], uint8_t l_nnz[9])

{

    int i, x, y, luma_start = 0, luma_ctx = 3;

    int nnz_pred, nnz, nnz_total = 0;

    int segment = mb->segment;

    int block_dc = 0;



    if (mb->mode != MODE_I4x4 && mb->mode != VP8_MVMODE_SPLIT) {

        nnz_pred = t_nnz[8] + l_nnz[8];



        // decode DC values and do hadamard

        nnz = decode_block_coeffs(c, td->block_dc, s->prob->token[1], 0,

                                  nnz_pred, s->qmat[segment].luma_dc_qmul);

        l_nnz[8] = t_nnz[8] = !!nnz;

        if (nnz) {

            nnz_total += nnz;

            block_dc   = 1;

            if (nnz == 1)

                s->vp8dsp.vp8_luma_dc_wht_dc(td->block, td->block_dc);

            else

                s->vp8dsp.vp8_luma_dc_wht(td->block, td->block_dc);

        }

        luma_start = 1;

        luma_ctx   = 0;

    }



    // luma blocks

    for (y = 0; y < 4; y++)

        for (x = 0; x < 4; x++) {

            nnz_pred = l_nnz[y] + t_nnz[x];

            nnz = decode_block_coeffs(c, td->block[y][x],

                                      s->prob->token[luma_ctx],

                                      luma_start, nnz_pred,

                                      s->qmat[segment].luma_qmul);

            /* nnz+block_dc may be one more than the actual last index,

             * but we don't care */

            td->non_zero_count_cache[y][x] = nnz + block_dc;

            t_nnz[x] = l_nnz[y] = !!nnz;

            nnz_total += nnz;

        }



    // chroma blocks

    // TODO: what to do about dimensions? 2nd dim for luma is x,

    // but for chroma it's (y<<1)|x

    for (i = 4; i < 6; i++)

        for (y = 0; y < 2; y++)

            for (x = 0; x < 2; x++) {

                nnz_pred = l_nnz[i + 2 * y] + t_nnz[i + 2 * x];

                nnz      = decode_block_coeffs(c, td->block[i][(y << 1) + x],

                                               s->prob->token[2],

                                               0, nnz_pred,

                                               s->qmat[segment].chroma_qmul);

                td->non_zero_count_cache[i][(y << 1) + x] = nnz;

                t_nnz[i + 2 * x] = l_nnz[i + 2 * y] = !!nnz;

                nnz_total       += nnz;

            }



    // if there were no coded coeffs despite the macroblock not being marked skip,

    // we MUST not do the inner loop filter and should not do IDCT

    // Since skip isn't used for bitstream prediction, just manually set it.

    if (!nnz_total)

        mb->skip = 1;

}

uint64_t qcow2_alloc_cluster_offset(BlockDriverState *bs,

                                    uint64_t offset,

                                    int n_start, int n_end,

                                    int *num, QCowL2Meta *m)

{

    BDRVQcowState *s = bs->opaque;

    int l2_index, ret;

    uint64_t l2_offset, *l2_table, cluster_offset;

    int nb_clusters, i = 0;

    QCowL2Meta *old_alloc;



    ret = get_cluster_table(bs, offset, &l2_table, &l2_offset, &l2_index);

    if (ret == 0)

        return 0;



    nb_clusters = size_to_clusters(s, n_end << 9);



    nb_clusters = MIN(nb_clusters, s->l2_size - l2_index);



    cluster_offset = be64_to_cpu(l2_table[l2_index]);



    /* We keep all QCOW_OFLAG_COPIED clusters */



    if (cluster_offset & QCOW_OFLAG_COPIED) {

        nb_clusters = count_contiguous_clusters(nb_clusters, s->cluster_size,

                &l2_table[l2_index], 0, 0);



        cluster_offset &= ~QCOW_OFLAG_COPIED;

        m->nb_clusters = 0;



        goto out;

    }



    /* for the moment, multiple compressed clusters are not managed */



    if (cluster_offset & QCOW_OFLAG_COMPRESSED)

        nb_clusters = 1;



    /* how many available clusters ? */



    while (i < nb_clusters) {

        i += count_contiguous_clusters(nb_clusters - i, s->cluster_size,

                &l2_table[l2_index], i, 0);



        if(be64_to_cpu(l2_table[l2_index + i]))

            break;



        i += count_contiguous_free_clusters(nb_clusters - i,

                &l2_table[l2_index + i]);



        cluster_offset = be64_to_cpu(l2_table[l2_index + i]);



        if ((cluster_offset & QCOW_OFLAG_COPIED) ||

                (cluster_offset & QCOW_OFLAG_COMPRESSED))

            break;

    }

    nb_clusters = i;



    /*

     * Check if there already is an AIO write request in flight which allocates

     * the same cluster. In this case we need to wait until the previous

     * request has completed and updated the L2 table accordingly.

     */

    QLIST_FOREACH(old_alloc, &s->cluster_allocs, next_in_flight) {



        uint64_t end_offset = offset + nb_clusters * s->cluster_size;

        uint64_t old_offset = old_alloc->offset;

        uint64_t old_end_offset = old_alloc->offset +

            old_alloc->nb_clusters * s->cluster_size;



        if (end_offset < old_offset || offset > old_end_offset) {

            /* No intersection */

        } else {

            if (offset < old_offset) {

                /* Stop at the start of a running allocation */

                nb_clusters = (old_offset - offset) >> s->cluster_bits;

            } else {

                nb_clusters = 0;

            }



            if (nb_clusters == 0) {

                /* Set dependency and wait for a callback */

                m->depends_on = old_alloc;

                m->nb_clusters = 0;

                *num = 0;

                return 0;

            }

        }

    }



    if (!nb_clusters) {

        abort();

    }



    QLIST_INSERT_HEAD(&s->cluster_allocs, m, next_in_flight);



    /* allocate a new cluster */



    cluster_offset = qcow2_alloc_clusters(bs, nb_clusters * s->cluster_size);



    /* save info needed for meta data update */

    m->offset = offset;

    m->n_start = n_start;

    m->nb_clusters = nb_clusters;



out:

    m->nb_available = MIN(nb_clusters << (s->cluster_bits - 9), n_end);



    *num = m->nb_available - n_start;



    return cluster_offset;

}

static int kempf_decode_tile(G2MContext *c, int tile_x, int tile_y,

                             const uint8_t *src, int src_size)

{

    int width, height;

    int hdr, zsize, npal, tidx = -1, ret;

    int i, j;

    const uint8_t *src_end = src + src_size;

    uint8_t pal[768], transp[3];

    uLongf dlen = (c->tile_width + 1) * c->tile_height;

    int sub_type;

    int nblocks, cblocks, bstride;

    int bits, bitbuf, coded;

    uint8_t *dst = c->framebuf + tile_x * c->tile_width * 3 +

                   tile_y * c->tile_height * c->framebuf_stride;



    if (src_size < 2)

        return AVERROR_INVALIDDATA;



    width  = FFMIN(c->width  - tile_x * c->tile_width,  c->tile_width);

    height = FFMIN(c->height - tile_y * c->tile_height, c->tile_height);



    hdr = *src++;

    sub_type = hdr >> 5;

    if (sub_type == 0) {

        int j;

        memcpy(transp, src, 3);

        src += 3;

        for (j = 0; j < height; j++, dst += c->framebuf_stride)

            for (i = 0; i < width; i++)

                memcpy(dst + i * 3, transp, 3);

        return 0;

    } else if (sub_type == 1) {

        return jpg_decode_data(&c->jc, width, height, src, src_end - src,

                               dst, c->framebuf_stride, NULL, 0, 0, 0);

    }



    if (sub_type != 2) {

        memcpy(transp, src, 3);

        src += 3;

    }

    npal = *src++ + 1;

    memcpy(pal, src, npal * 3); src += npal * 3;

    if (sub_type != 2) {

        for (i = 0; i < npal; i++) {

            if (!memcmp(pal + i * 3, transp, 3)) {

               tidx = i;

               break;

            }

        }

    }



    if (src_end - src < 2)

        return 0;

    zsize = (src[0] << 8) | src[1]; src += 2;



    if (src_end - src < zsize)

        return AVERROR_INVALIDDATA;



    ret = uncompress(c->kempf_buf, &dlen, src, zsize);

    if (ret)

        return AVERROR_INVALIDDATA;

    src += zsize;



    if (sub_type == 2) {

        kempf_restore_buf(c->kempf_buf, dlen, dst, c->framebuf_stride,

                          NULL, 0, width, height, pal, npal, tidx);

        return 0;

    }



    nblocks = *src++ + 1;

    cblocks = 0;

    bstride = FFALIGN(width, 16) >> 4;

    // blocks are coded LSB and we need normal bitreader for JPEG data

    bits = 0;

    for (i = 0; i < (FFALIGN(height, 16) >> 4); i++) {

        for (j = 0; j < (FFALIGN(width, 16) >> 4); j++) {

            if (!bits) {

                bitbuf = *src++;

                bits   = 8;

            }

            coded = bitbuf & 1;

            bits--;

            bitbuf >>= 1;

            cblocks += coded;

            if (cblocks > nblocks)

                return AVERROR_INVALIDDATA;

            c->kempf_flags[j + i * bstride] = coded;

        }

    }



    memset(c->jpeg_tile, 0, c->tile_stride * height);

    jpg_decode_data(&c->jc, width, height, src, src_end - src,

                    c->jpeg_tile, c->tile_stride,

                    c->kempf_flags, bstride, nblocks, 0);



    kempf_restore_buf(c->kempf_buf, dlen, dst, c->framebuf_stride,

                      c->jpeg_tile, c->tile_stride,

                      width, height, pal, npal, tidx);



    return 0;

}

