static void final(Real144_internal *glob, short *i1, short *i2, void *out,

                  int *statbuf, int len)

{

    int x, sum;

    int buffer[10];

    short *ptr;

    short *ptr2;



    memcpy(glob->work, statbuf,20);

    memcpy(glob->work + 10, i2, len * 2);



    buffer[9] = i1[0];

    buffer[8] = i1[1];

    buffer[7] = i1[2];

    buffer[6] = i1[3];

    buffer[5] = i1[4];

    buffer[4] = i1[5];

    buffer[3] = i1[6];

    buffer[2] = i1[7];

    buffer[1] = i1[8];

    buffer[0] = i1[9];



    ptr2 = (ptr = glob->work) + len;



    while (ptr < ptr2) {

        for(sum=0, x=0; x<=9; x++)

            sum += buffer[x] * (ptr[x]);



        sum = sum >> 12;

        x = ptr[10] - sum;



        if (x<-32768 || x>32767) {

            memset(out, 0, len * 2);

            memset(statbuf, 0, 20);

            return;

        }



        ptr[10] = x;

        ptr++;

    }

    memcpy(out, ptr+10 - len, len * 2);

    memcpy(statbuf, ptr, 20);

}

static void filter_mb_edgecv( H264Context *h, uint8_t *pix, int stride, int bS[4], int qp ) {

    int i, d;

    const int index_a = clip( qp + h->slice_alpha_c0_offset, 0, 51 );

    const int alpha = alpha_table[index_a];

    const int beta  = beta_table[clip( qp + h->slice_beta_offset, 0, 51 )];



    for( i = 0; i < 4; i++ ) {

        if( bS[i] == 0 ) {

            pix += 2 * stride;

            continue;

        }



        /* 2px edge length (because we use same bS than the one for luma) */

        for( d = 0; d < 2; d++ )

        {

            const uint8_t p0 = pix[-1];

            const uint8_t p1 = pix[-2];

            const uint8_t q0 = pix[0];

            const uint8_t q1 = pix[1];



            if( abs( p0 - q0 ) >= alpha ||

                abs( p1 - p0 ) >= beta ||

                abs( q1 - q0 ) >= beta ) {

                pix += stride;

                continue;

            }



            if( bS[i] < 4 ) {

                const int tc = tc0_table[index_a][bS[i] - 1] + 1;

                const int i_delta = clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );



                pix[-1] = clip( p0 + i_delta, 0, 255 );    /* p0' */

                pix[0]  = clip( q0 - i_delta, 0, 255 );    /* q0' */

            } else {

                pix[-1] = ( 2*p1 + p0 + q1 + 2 ) >> 2;   /* p0' */

                pix[0]  = ( 2*q1 + q0 + p1 + 2 ) >> 2;   /* q0' */

            }

            pix += stride;

        }

    }

}

long do_rt_sigreturn(CPUX86State *env)

{

        abi_ulong frame_addr;

	struct rt_sigframe *frame;

        sigset_t set;

	int eax;



        frame_addr = env->regs[R_ESP] - 4;

        if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1))

                goto badframe;

        target_to_host_sigset(&set, &frame->uc.tuc_sigmask);

        sigprocmask(SIG_SETMASK, &set, NULL);



	if (restore_sigcontext(env, &frame->uc.tuc_mcontext, &eax))

		goto badframe;



	if (do_sigaltstack(frame_addr + offsetof(struct rt_sigframe, uc.tuc_stack), 0, 

                           get_sp_from_cpustate(env)) == -EFAULT)

		goto badframe;



        unlock_user_struct(frame, frame_addr, 0);

	return eax;



badframe:

        unlock_user_struct(frame, frame_addr, 0);

        force_sig(TARGET_SIGSEGV);

	return 0;

}

