static void virtio_serial_device_realize(DeviceState *dev, Error **errp)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(dev);

    VirtIOSerial *vser = VIRTIO_SERIAL(dev);

    uint32_t i, max_supported_ports;



    if (!vser->serial.max_virtserial_ports) {

        error_setg(errp, "Maximum number of serial ports not specified");

        return;

    }



    /* Each port takes 2 queues, and one pair is for the control queue */

    max_supported_ports = VIRTIO_QUEUE_MAX / 2 - 1;



    if (vser->serial.max_virtserial_ports > max_supported_ports) {

        error_setg(errp, "maximum ports supported: %u", max_supported_ports);

        return;

    }



    /* We don't support emergency write, skip it for now. */

    /* TODO: cleaner fix, depending on host features. */

    virtio_init(vdev, "virtio-serial", VIRTIO_ID_CONSOLE,

                offsetof(struct virtio_console_config, emerg_wr));



    /* Spawn a new virtio-serial bus on which the ports will ride as devices */

    qbus_create_inplace(&vser->bus, sizeof(vser->bus), TYPE_VIRTIO_SERIAL_BUS,

                        dev, vdev->bus_name);

    qbus_set_hotplug_handler(BUS(&vser->bus), DEVICE(vser), errp);

    vser->bus.vser = vser;

    QTAILQ_INIT(&vser->ports);



    vser->bus.max_nr_ports = vser->serial.max_virtserial_ports;

    vser->ivqs = g_malloc(vser->serial.max_virtserial_ports

                          * sizeof(VirtQueue *));

    vser->ovqs = g_malloc(vser->serial.max_virtserial_ports

                          * sizeof(VirtQueue *));



    /* Add a queue for host to guest transfers for port 0 (backward compat) */

    vser->ivqs[0] = virtio_add_queue(vdev, 128, handle_input);

    /* Add a queue for guest to host transfers for port 0 (backward compat) */

    vser->ovqs[0] = virtio_add_queue(vdev, 128, handle_output);



    /* TODO: host to guest notifications can get dropped

     * if the queue fills up. Implement queueing in host,

     * this might also make it possible to reduce the control

     * queue size: as guest preposts buffers there,

     * this will save 4Kbyte of guest memory per entry. */



    /* control queue: host to guest */

    vser->c_ivq = virtio_add_queue(vdev, 32, control_in);

    /* control queue: guest to host */

    vser->c_ovq = virtio_add_queue(vdev, 32, control_out);



    for (i = 1; i < vser->bus.max_nr_ports; i++) {

        /* Add a per-port queue for host to guest transfers */

        vser->ivqs[i] = virtio_add_queue(vdev, 128, handle_input);

        /* Add a per-per queue for guest to host transfers */

        vser->ovqs[i] = virtio_add_queue(vdev, 128, handle_output);

    }



    vser->ports_map = g_malloc0(((vser->serial.max_virtserial_ports + 31) / 32)

        * sizeof(vser->ports_map[0]));

    /*

     * Reserve location 0 for a console port for backward compat

     * (old kernel, new qemu)

     */

    mark_port_added(vser, 0);



    vser->post_load = NULL;



    QLIST_INSERT_HEAD(&vserdevices.devices, vser, next);

}

static void qbus_list_bus(DeviceState *dev, char *dest, int len)

{

    BusState *child;

    const char *sep = " ";

    int pos = 0;



    pos += snprintf(dest+pos, len-pos,"child busses at \"%s\":",

                    dev->id ? dev->id : dev->info->name);

    LIST_FOREACH(child, &dev->child_bus, sibling) {

        pos += snprintf(dest+pos, len-pos, "%s\"%s\"", sep, child->name);

        sep = ", ";

    }

}

static int execute_ref_pic_marking(H264Context *h, MMCO *mmco, int mmco_count){

    MpegEncContext * const s = &h->s;

    int i, j;

    int current_ref_assigned=0;

    Picture *pic;



    if((s->avctx->debug&FF_DEBUG_MMCO) && mmco_count==0)

        av_log(h->s.avctx, AV_LOG_DEBUG, "no mmco here\n");



    for(i=0; i<mmco_count; i++){

        int structure, frame_num, unref_pic;

        if(s->avctx->debug&FF_DEBUG_MMCO)

            av_log(h->s.avctx, AV_LOG_DEBUG, "mmco:%d %d %d\n", h->mmco[i].opcode, h->mmco[i].short_pic_num, h->mmco[i].long_arg);



        switch(mmco[i].opcode){

        case MMCO_SHORT2UNUSED:

            if(s->avctx->debug&FF_DEBUG_MMCO)

                av_log(h->s.avctx, AV_LOG_DEBUG, "mmco: unref short %d count %d\n", h->mmco[i].short_pic_num, h->short_ref_count);

            frame_num = pic_num_extract(h, mmco[i].short_pic_num, &structure);

            pic = find_short(h, frame_num, &j);

            if (pic) {

                if (unreference_pic(h, pic, structure ^ PICT_FRAME))

                    remove_short_at_index(h, j);

            } else if(s->avctx->debug&FF_DEBUG_MMCO)

                av_log(h->s.avctx, AV_LOG_DEBUG, "mmco: unref short failure\n");

            break;

        case MMCO_SHORT2LONG:

            if (FIELD_PICTURE && mmco[i].long_arg < h->long_ref_count &&

                    h->long_ref[mmco[i].long_arg]->frame_num ==

                                              mmco[i].short_pic_num / 2) {

                /* do nothing, we've already moved this field pair. */

            } else {

                int frame_num = mmco[i].short_pic_num >> FIELD_PICTURE;



                pic= remove_long(h, mmco[i].long_arg);

                if(pic) unreference_pic(h, pic, 0);



                h->long_ref[ mmco[i].long_arg ]= remove_short(h, frame_num);

                if (h->long_ref[ mmco[i].long_arg ]){

                    h->long_ref[ mmco[i].long_arg ]->long_ref=1;

                    h->long_ref_count++;

                }

            }

            break;

        case MMCO_LONG2UNUSED:

            j = pic_num_extract(h, mmco[i].long_arg, &structure);

            pic = h->long_ref[j];

            if (pic) {

                if (unreference_pic(h, pic, structure ^ PICT_FRAME))

                    remove_long_at_index(h, j);

            } else if(s->avctx->debug&FF_DEBUG_MMCO)

                av_log(h->s.avctx, AV_LOG_DEBUG, "mmco: unref long failure\n");

            break;

        case MMCO_LONG:

            unref_pic = 1;

            if (FIELD_PICTURE && !s->first_field) {

                if (h->long_ref[mmco[i].long_arg] == s->current_picture_ptr) {

                    /* Just mark second field as referenced */

                    unref_pic = 0;

                } else if (s->current_picture_ptr->reference) {

                    /* First field in pair is in short term list or

                     * at a different long term index.

                     * This is not allowed; see 7.4.3, notes 2 and 3.

                     * Report the problem and keep the pair where it is,

                     * and mark this field valid.

                     */

                    av_log(h->s.avctx, AV_LOG_ERROR,

                        "illegal long term reference assignment for second "

                        "field in complementary field pair (first field is "

                        "short term or has non-matching long index)\n");

                    unref_pic = 0;

                }

            }



            if (unref_pic) {

                pic= remove_long(h, mmco[i].long_arg);

                if(pic) unreference_pic(h, pic, 0);



                h->long_ref[ mmco[i].long_arg ]= s->current_picture_ptr;

                h->long_ref[ mmco[i].long_arg ]->long_ref=1;

                h->long_ref_count++;

            }



            s->current_picture_ptr->reference |= s->picture_structure;

            current_ref_assigned=1;

            break;

        case MMCO_SET_MAX_LONG:

            assert(mmco[i].long_arg <= 16);

            // just remove the long term which index is greater than new max

            for(j = mmco[i].long_arg; j<16; j++){

                pic = remove_long(h, j);

                if (pic) unreference_pic(h, pic, 0);

            }

            break;

        case MMCO_RESET:

            while(h->short_ref_count){

                pic= remove_short(h, h->short_ref[0]->frame_num);

                if(pic) unreference_pic(h, pic, 0);

            }

            for(j = 0; j < 16; j++) {

                pic= remove_long(h, j);

                if(pic) unreference_pic(h, pic, 0);

            }

            s->current_picture_ptr->poc=

            s->current_picture_ptr->field_poc[0]=

            s->current_picture_ptr->field_poc[1]=

            h->poc_lsb=

            h->poc_msb=

            h->frame_num=

            s->current_picture_ptr->frame_num= 0;

            break;

        default: assert(0);

        }

    }



    if (!current_ref_assigned && FIELD_PICTURE &&

            !s->first_field && s->current_picture_ptr->reference) {



        /* Second field of complementary field pair; the first field of

         * which is already referenced. If short referenced, it

         * should be first entry in short_ref. If not, it must exist

         * in long_ref; trying to put it on the short list here is an

         * error in the encoded bit stream (ref: 7.4.3, NOTE 2 and 3).

         */

        if (h->short_ref_count && h->short_ref[0] == s->current_picture_ptr) {

            /* Just mark the second field valid */

            s->current_picture_ptr->reference = PICT_FRAME;

        } else if (s->current_picture_ptr->long_ref) {

            av_log(h->s.avctx, AV_LOG_ERROR, "illegal short term reference "

                                             "assignment for second field "

                                             "in complementary field pair "

                                             "(first field is long term)\n");

        } else {

            /*

             * First field in reference, but not in any sensible place on our

             * reference lists. This shouldn't happen unless reference

             * handling somewhere else is wrong.

             */

            assert(0);

        }

        current_ref_assigned = 1;

    }



    if(!current_ref_assigned){

        pic= remove_short(h, s->current_picture_ptr->frame_num);

        if(pic){

            unreference_pic(h, pic, 0);

            av_log(h->s.avctx, AV_LOG_ERROR, "illegal short term buffer state detected\n");

        }



        if(h->short_ref_count)

            memmove(&h->short_ref[1], &h->short_ref[0], h->short_ref_count*sizeof(Picture*));



        h->short_ref[0]= s->current_picture_ptr;

        h->short_ref[0]->long_ref=0;

        h->short_ref_count++;

        s->current_picture_ptr->reference |= s->picture_structure;

    }



    if (h->long_ref_count + h->short_ref_count > h->sps.ref_frame_count){



        /* We have too many reference frames, probably due to corrupted

         * stream. Need to discard one frame. Prevents overrun of the

         * short_ref and long_ref buffers.

         */

        av_log(h->s.avctx, AV_LOG_ERROR,

               "number of reference frames exceeds max (probably "

               "corrupt input), discarding one\n");



        if (h->long_ref_count && !h->short_ref_count) {

            for (i = 0; i < 16; ++i)

                if (h->long_ref[i])

                    break;



            assert(i < 16);

            pic = h->long_ref[i];

            remove_long_at_index(h, i);

        } else {

            pic = h->short_ref[h->short_ref_count - 1];

            remove_short_at_index(h, h->short_ref_count - 1);

        }

        unreference_pic(h, pic, 0);

    }



    print_short_term(h);

    print_long_term(h);

    return 0;

}

static int vhost_verify_ring_mappings(struct vhost_dev *dev,

                                      uint64_t start_addr,

                                      uint64_t size)

{

    int i, j;

    int r = 0;

    const char *part_name[] = {

        "descriptor table",

        "available ring",

        "used ring"

    };



    for (i = 0; i < dev->nvqs; ++i) {

        struct vhost_virtqueue *vq = dev->vqs + i;



        j = 0;

        r = vhost_verify_ring_part_mapping(vq->desc, vq->desc_phys,

                                           vq->desc_size, start_addr, size);

        if (!r) {

            break;

        }



        j++;

        r = vhost_verify_ring_part_mapping(vq->avail, vq->avail_phys,

                                           vq->avail_size, start_addr, size);

        if (!r) {

            break;

        }



        j++;

        r = vhost_verify_ring_part_mapping(vq->used, vq->used_phys,

                                           vq->used_size, start_addr, size);

        if (!r) {

            break;

        }

    }



    if (r == -ENOMEM) {

        error_report("Unable to map %s for ring %d", part_name[j], i);

    } else if (r == -EBUSY) {

        error_report("%s relocated for ring %d", part_name[j], i);

    }

    return r;

}

int qcow2_discard_clusters(BlockDriverState *bs, uint64_t offset,

    int nb_sectors, enum qcow2_discard_type type, bool full_discard)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t end_offset;

    unsigned int nb_clusters;

    int ret;



    end_offset = offset + (nb_sectors << BDRV_SECTOR_BITS);



    /* Round start up and end down */

    offset = align_offset(offset, s->cluster_size);

    end_offset = start_of_cluster(s, end_offset);



    if (offset > end_offset) {

        return 0;

    }



    nb_clusters = size_to_clusters(s, end_offset - offset);



    s->cache_discards = true;



    /* Each L2 table is handled by its own loop iteration */

    while (nb_clusters > 0) {

        ret = discard_single_l2(bs, offset, nb_clusters, type, full_discard);

        if (ret < 0) {

            goto fail;

        }



        nb_clusters -= ret;

        offset += (ret * s->cluster_size);

    }



    ret = 0;

fail:

    s->cache_discards = false;

    qcow2_process_discards(bs, ret);



    return ret;

}

static int yop_read_header(AVFormatContext *s)

{

    YopDecContext *yop = s->priv_data;

    AVIOContext *pb  = s->pb;



    AVCodecContext *audio_dec, *video_dec;

    AVStream *audio_stream, *video_stream;



    int frame_rate, ret;



    audio_stream = avformat_new_stream(s, NULL);

    video_stream = avformat_new_stream(s, NULL);





    // Extra data that will be passed to the decoder

    video_stream->codec->extradata_size = 8;



    video_stream->codec->extradata = av_mallocz(video_stream->codec->extradata_size +

                                                FF_INPUT_BUFFER_PADDING_SIZE);



    if (!video_stream->codec->extradata)




    // Audio

    audio_dec               = audio_stream->codec;

    audio_dec->codec_type   = AVMEDIA_TYPE_AUDIO;

    audio_dec->codec_id     = AV_CODEC_ID_ADPCM_IMA_APC;

    audio_dec->channels     = 1;

    audio_dec->sample_rate  = 22050;



    // Video

    video_dec               = video_stream->codec;

    video_dec->codec_type   = AVMEDIA_TYPE_VIDEO;

    video_dec->codec_id     = AV_CODEC_ID_YOP;



    avio_skip(pb, 6);



    frame_rate              = avio_r8(pb);

    yop->frame_size         = avio_r8(pb) * 2048;

    video_dec->width        = avio_rl16(pb);

    video_dec->height       = avio_rl16(pb);



    video_stream->sample_aspect_ratio = (AVRational){1, 2};



    ret = avio_read(pb, video_dec->extradata, 8);

    if (ret < 8)

        return ret < 0 ? ret : AVERROR_EOF;



    yop->palette_size       = video_dec->extradata[0] * 3 + 4;

    yop->audio_block_length = AV_RL16(video_dec->extradata + 6);



    // 1840 samples per frame, 1 nibble per sample; hence 1840/2 = 920

    if (yop->audio_block_length < 920 ||

        yop->audio_block_length + yop->palette_size >= yop->frame_size) {

        av_log(s, AV_LOG_ERROR, "YOP has invalid header\n");

        return AVERROR_INVALIDDATA;

    }



    avio_seek(pb, 2048, SEEK_SET);



    avpriv_set_pts_info(video_stream, 32, 1, frame_rate);



    return 0;

}

static av_cold int vqa_decode_end(AVCodecContext *avctx)

{

