    s->qcow_filename = NULL;

    return ret;

}

static int qcow_snapshot_create(BlockDriverState *bs,

                                QEMUSnapshotInfo *sn_info)

{

    BDRVQcowState *s = bs->opaque;

    QCowSnapshot *snapshots1, sn1, *sn = &sn1;

    int i, ret;

    uint64_t *l1_table = NULL;



    memset(sn, 0, sizeof(*sn));



    if (sn_info->id_str[0] == '\0') {

        /* compute a new id */

        find_new_snapshot_id(bs, sn_info->id_str, sizeof(sn_info->id_str));

    }



    /* check that the ID is unique */

    if (find_snapshot_by_id(bs, sn_info->id_str) >= 0)

        return -ENOENT;



    sn->id_str = qemu_strdup(sn_info->id_str);

    if (!sn->id_str)

        goto fail;

    sn->name = qemu_strdup(sn_info->name);

    if (!sn->name)

        goto fail;

    sn->vm_state_size = sn_info->vm_state_size;

    sn->date_sec = sn_info->date_sec;

    sn->date_nsec = sn_info->date_nsec;

    sn->vm_clock_nsec = sn_info->vm_clock_nsec;



    ret = update_snapshot_refcount(bs, s->l1_table_offset, s->l1_size, 1);

    if (ret < 0)

        goto fail;



    /* create the L1 table of the snapshot */

    sn->l1_table_offset = alloc_clusters(bs, s->l1_size * sizeof(uint64_t));

    sn->l1_size = s->l1_size;



    l1_table = qemu_malloc(s->l1_size * sizeof(uint64_t));

    if (!l1_table)

        goto fail;

    for(i = 0; i < s->l1_size; i++) {

        l1_table[i] = cpu_to_be64(s->l1_table[i]);

    }

    if (bdrv_pwrite(s->hd, sn->l1_table_offset,

                    l1_table, s->l1_size * sizeof(uint64_t)) !=

        (s->l1_size * sizeof(uint64_t)))

        goto fail;

    qemu_free(l1_table);

    l1_table = NULL;



    snapshots1 = qemu_malloc((s->nb_snapshots + 1) * sizeof(QCowSnapshot));

    if (!snapshots1)

        goto fail;

    memcpy(snapshots1, s->snapshots, s->nb_snapshots * sizeof(QCowSnapshot));


    s->snapshots = snapshots1;

    s->snapshots[s->nb_snapshots++] = *sn;



    if (qcow_write_snapshots(bs) < 0)

        goto fail;

#ifdef DEBUG_ALLOC

    check_refcounts(bs);

#endif

    return 0;

 fail:

    qemu_free(sn->name);

    qemu_free(l1_table);

    return -1;

}

static int scsi_write_data(SCSIDevice *d, uint32_t tag)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, d);

    SCSIDiskReq *r;



    DPRINTF("Write data tag=0x%x\n", tag);

    r = scsi_find_request(s, tag);

    if (!r) {

        BADF("Bad write tag 0x%x\n", tag);

        scsi_command_complete(r, CHECK_CONDITION, HARDWARE_ERROR);

        return 1;

    }



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    scsi_write_request(r);



    return 0;

}

static ram_addr_t kqemu_ram_alloc(ram_addr_t size)

{

    ram_addr_t addr;

    if ((last_ram_offset + size) > kqemu_phys_ram_size) {

        fprintf(stderr, "Not enough memory (requested_size = %" PRIu64 ", max memory = %" PRIu64 ")\n",

                (uint64_t)size, (uint64_t)kqemu_phys_ram_size);

        abort();

    }

    addr = last_ram_offset;

    last_ram_offset = TARGET_PAGE_ALIGN(last_ram_offset + size);

    return addr;

}

static void synthfilt_build_sb_samples(QDM2Context *q, GetBitContext *gb,

                                       int length, int sb_min, int sb_max)

{

    int sb, j, k, n, ch, run, channels;

    int joined_stereo, zero_encoding, chs;

    int type34_first;

    float type34_div = 0;

    float type34_predictor;

    float samples[10], sign_bits[16];



    if (length == 0) {

        // If no data use noise

        for (sb=sb_min; sb < sb_max; sb++)

            build_sb_samples_from_noise (q, sb);



        return;

    }



    for (sb = sb_min; sb < sb_max; sb++) {

        FIX_NOISE_IDX(q->noise_idx);



        channels = q->nb_channels;



        if (q->nb_channels <= 1 || sb < 12)

            joined_stereo = 0;

        else if (sb >= 24)

            joined_stereo = 1;

        else

            joined_stereo = (get_bits_left(gb) >= 1) ? get_bits1 (gb) : 0;



        if (joined_stereo) {

            if (get_bits_left(gb) >= 16)

                for (j = 0; j < 16; j++)

                    sign_bits[j] = get_bits1 (gb);



            for (j = 0; j < 64; j++)

                if (q->coding_method[1][sb][j] > q->coding_method[0][sb][j])

                    q->coding_method[0][sb][j] = q->coding_method[1][sb][j];



            fix_coding_method_array(sb, q->nb_channels, q->coding_method);

            channels = 1;

        }



        for (ch = 0; ch < channels; ch++) {

            zero_encoding = (get_bits_left(gb) >= 1) ? get_bits1(gb) : 0;

            type34_predictor = 0.0;

            type34_first = 1;



            for (j = 0; j < 128; ) {

                switch (q->coding_method[ch][sb][j / 2]) {

                    case 8:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + 2 * k) >= 128)

                                        break;

                                    samples[2 * k] = get_bits1(gb) ? dequant_1bit[joined_stereo][2 * get_bits1(gb)] : 0;

                                }

                            } else {

                                n = get_bits(gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[2 * k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                            for (k = 0; k < 5; k++)

                                samples[2 * k + 1] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else {

                            for (k = 0; k < 10; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 10;

                        break;



                    case 10:

                        if (get_bits_left(gb) >= 1) {

                            float f = 0.81;



                            if (get_bits1(gb))

                                f = -f;

                            f -= noise_samples[((sb + 1) * (j +5 * ch + 1)) & 127] * 9.0 / 40.0;

                            samples[0] = f;

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    case 16:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + k) >= 128)

                                        break;

                                    samples[k] = (get_bits1(gb) == 0) ? 0 : dequant_1bit[joined_stereo][2 * get_bits1(gb)];

                                }

                            } else {

                                n = get_bits (gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                        } else {

                            for (k = 0; k < 5; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 5;

                        break;



                    case 24:

                        if (get_bits_left(gb) >= 7) {

                            n = get_bits(gb, 7);

                            for (k = 0; k < 3; k++)

                                samples[k] = (random_dequant_type24[n][k] - 2.0) * 0.5;

                        } else {

                            for (k = 0; k < 3; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 3;

                        break;



                    case 30:

                        if (get_bits_left(gb) >= 4) {

                            unsigned index = qdm2_get_vlc(gb, &vlc_tab_type30, 0, 1);

                            if (index < FF_ARRAY_ELEMS(type30_dequant)) {

                                samples[0] = type30_dequant[index];

                            } else

                                samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);



                        run = 1;

                        break;



                    case 34:

                        if (get_bits_left(gb) >= 7) {

                            if (type34_first) {

                                type34_div = (float)(1 << get_bits(gb, 2));

                                samples[0] = ((float)get_bits(gb, 5) - 16.0) / 15.0;

                                type34_predictor = samples[0];

                                type34_first = 0;

                            } else {

                                unsigned index = qdm2_get_vlc(gb, &vlc_tab_type34, 0, 1);

                                if (index < FF_ARRAY_ELEMS(type34_delta)) {

                                    samples[0] = type34_delta[index] / type34_div + type34_predictor;

                                    type34_predictor = samples[0];

                                } else

                                    samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                            }

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    default:

                        samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        run = 1;

                        break;

                }



                if (joined_stereo) {

                    float tmp[10][MPA_MAX_CHANNELS];



                    for (k = 0; k < run; k++) {

                        tmp[k][0] = samples[k];

                        tmp[k][1] = (sign_bits[(j + k) / 8]) ? -samples[k] : samples[k];

                    }

                    for (chs = 0; chs < q->nb_channels; chs++)

                        for (k = 0; k < run; k++)

                            if ((j + k) < 128)

                                q->sb_samples[chs][j + k][sb] = q->tone_level[chs][sb][((j + k)/2)] * tmp[k][chs];

                } else {

                    for (k = 0; k < run; k++)

                        if ((j + k) < 128)

                            q->sb_samples[ch][j + k][sb] = q->tone_level[ch][sb][(j + k)/2] * samples[k];

                }



                j += run;

            } // j loop

        } // channel loop

    } // subband loop

}

static void gic_complete_irq(gic_state * s, int cpu, int irq)

{

    int update = 0;

    int cm = 1 << cpu;

    DPRINTF("EOI %d\n", irq);

    if (s->running_irq[cpu] == 1023)

        return; /* No active IRQ.  */

    if (irq != 1023) {

        /* Mark level triggered interrupts as pending if they are still

           raised.  */

        if (!GIC_TEST_TRIGGER(irq) && GIC_TEST_ENABLED(irq)

                && GIC_TEST_LEVEL(irq, cm) && (GIC_TARGET(irq) & cm) != 0) {

            DPRINTF("Set %d pending mask %x\n", irq, cm);

            GIC_SET_PENDING(irq, cm);

            update = 1;

        }

    }

    if (irq != s->running_irq[cpu]) {

        /* Complete an IRQ that is not currently running.  */

        int tmp = s->running_irq[cpu];

        while (s->last_active[tmp][cpu] != 1023) {

            if (s->last_active[tmp][cpu] == irq) {

                s->last_active[tmp][cpu] = s->last_active[irq][cpu];

                break;

            }

            tmp = s->last_active[tmp][cpu];

        }

        if (update) {

            gic_update(s);

        }

    } else {

        /* Complete the current running IRQ.  */

        gic_set_running_irq(s, cpu, s->last_active[s->running_irq[cpu]][cpu]);

    }

}

static void hpet_timer(void *opaque)

{

    HPETTimer *t = (HPETTimer*)opaque;

    uint64_t diff;



    uint64_t period = t->period;

    uint64_t cur_tick = hpet_get_ticks();



    if (timer_is_periodic(t) && period != 0) {

        if (t->config & HPET_TN_32BIT) {

            while (hpet_time_after(cur_tick, t->cmp))

                t->cmp = (uint32_t)(t->cmp + t->period);

        } else

            while (hpet_time_after64(cur_tick, t->cmp))

                t->cmp += period;



        diff = hpet_calculate_diff(t, cur_tick);

        qemu_mod_timer(t->qemu_timer, qemu_get_clock(vm_clock)

                       + (int64_t)ticks_to_ns(diff));

    } else if (t->config & HPET_TN_32BIT && !timer_is_periodic(t)) {

        if (t->wrap_flag) {

            diff = hpet_calculate_diff(t, cur_tick);

            qemu_mod_timer(t->qemu_timer, qemu_get_clock(vm_clock)

                           + (int64_t)ticks_to_ns(diff));

            t->wrap_flag = 0;

        }

    }

    update_irq(t);

}

static int decode_channel_sound_unit(ATRAC3Context *q, GetBitContext *gb,

                                     ChannelUnit *snd, float *output,

                                     int channel_num, int coding_mode)

{

    int band, ret, num_subbands, last_tonal, num_bands;

    GainBlock *gain1 = &snd->gain_block[    snd->gc_blk_switch];

    GainBlock *gain2 = &snd->gain_block[1 - snd->gc_blk_switch];



    if (coding_mode == JOINT_STEREO && channel_num == 1) {

        if (get_bits(gb, 2) != 3) {

            av_log(NULL,AV_LOG_ERROR,"JS mono Sound Unit id != 3.\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        if (get_bits(gb, 6) != 0x28) {

            av_log(NULL,AV_LOG_ERROR,"Sound Unit id != 0x28.\n");

            return AVERROR_INVALIDDATA;

        }

    }



    /* number of coded QMF bands */

    snd->bands_coded = get_bits(gb, 2);



    ret = decode_gain_control(gb, gain2, snd->bands_coded);

    if (ret)

        return ret;



    snd->num_components = decode_tonal_components(gb, snd->components,

                                                  snd->bands_coded);

    if (snd->num_components < 0)

        return snd->num_components;



    num_subbands = decode_spectrum(gb, snd->spectrum);



    /* Merge the decoded spectrum and tonal components. */

    last_tonal = add_tonal_components(snd->spectrum, snd->num_components,

                                      snd->components);





    /* calculate number of used MLT/QMF bands according to the amount of coded

       spectral lines */

    num_bands = (subband_tab[num_subbands] - 1) >> 8;

    if (last_tonal >= 0)

        num_bands = FFMAX((last_tonal + 256) >> 8, num_bands);





    /* Reconstruct time domain samples. */

    for (band = 0; band < 4; band++) {

        /* Perform the IMDCT step without overlapping. */

        if (band <= num_bands)

            imlt(q, &snd->spectrum[band * 256], snd->imdct_buf, band & 1);

        else

            memset(snd->imdct_buf, 0, 512 * sizeof(*snd->imdct_buf));



        /* gain compensation and overlapping */

        ff_atrac_gain_compensation(&q->gainc_ctx, snd->imdct_buf,

                                   &snd->prev_frame[band * 256],

                                   &gain1->g_block[band], &gain2->g_block[band],

                                   256, &output[band * 256]);

    }



    /* Swap the gain control buffers for the next frame. */

    snd->gc_blk_switch ^= 1;



    return 0;

}

void replay_read_events(int checkpoint)

{

    while (replay_data_kind == EVENT_ASYNC) {

        Event *event = replay_read_event(checkpoint);

        if (!event) {

            break;

        }

        replay_mutex_unlock();

        replay_run_event(event);

        replay_mutex_lock();



        g_free(event);

        replay_finish_event();

        read_event_kind = -1;

    }

}

