void FUNCC(ff_h264_chroma422_dc_dequant_idct)(int16_t *_block, int qmul){

    const int stride= 16*2;

    const int xStride= 16;

    int i;

    int temp[8];

    static const uint8_t x_offset[2]={0, 16};

    dctcoef *block = (dctcoef*)_block;



    for(i=0; i<4; i++){

        temp[2*i+0] = block[stride*i + xStride*0] + block[stride*i + xStride*1];

        temp[2*i+1] = block[stride*i + xStride*0] - block[stride*i + xStride*1];

    }



    for(i=0; i<2; i++){

        const int offset= x_offset[i];

        const int z0= temp[2*0+i] + temp[2*2+i];

        const int z1= temp[2*0+i] - temp[2*2+i];

        const int z2= temp[2*1+i] - temp[2*3+i];

        const int z3= temp[2*1+i] + temp[2*3+i];



        block[stride*0+offset]= ((z0 + z3)*qmul + 128) >> 8;

        block[stride*1+offset]= ((z1 + z2)*qmul + 128) >> 8;

        block[stride*2+offset]= ((z1 - z2)*qmul + 128) >> 8;

        block[stride*3+offset]= ((z0 - z3)*qmul + 128) >> 8;

    }

}

static int parse_video_var(AVFormatContext *avctx, AVStream *st, const char *name, int size)

{

    AVIOContext *pb = avctx->pb;

    if (!strcmp(name, "__DIR_COUNT")) {

        st->nb_frames = st->duration = var_read_int(pb, size);

    } else if (!strcmp(name, "COMPRESSION")) {

        char * str = var_read_string(pb, size);

        if (!strcmp(str, "1")) {

            st->codec->codec_id = AV_CODEC_ID_MVC1;

        } else if (!strcmp(str, "2")) {

            st->codec->pix_fmt  = AV_PIX_FMT_ABGR;

            st->codec->codec_id = AV_CODEC_ID_RAWVIDEO;

        } else if (!strcmp(str, "3")) {

            st->codec->codec_id = AV_CODEC_ID_SGIRLE;

        } else if (!strcmp(str, "10")) {

            st->codec->codec_id = AV_CODEC_ID_MJPEG;

        } else if (!strcmp(str, "MVC2")) {

            st->codec->codec_id = AV_CODEC_ID_MVC2;

        } else {

            av_log_ask_for_sample(avctx, "unknown video compression %s\n", str);

        }

        av_free(str);

    } else if (!strcmp(name, "FPS")) {

        st->time_base = av_inv_q(var_read_float(pb, size));

    } else if (!strcmp(name, "HEIGHT")) {

        st->codec->height = var_read_int(pb, size);

    } else if (!strcmp(name, "PIXEL_ASPECT")) {

        st->sample_aspect_ratio = var_read_float(pb, size);

        av_reduce(&st->sample_aspect_ratio.num, &st->sample_aspect_ratio.den,

                  st->sample_aspect_ratio.num, st->sample_aspect_ratio.den, INT_MAX);

    } else if (!strcmp(name, "WIDTH")) {

        st->codec->width = var_read_int(pb, size);

    } else if (!strcmp(name, "ORIENTATION")) {

        if (var_read_int(pb, size) == 1101) {

            st->codec->extradata       = av_strdup("BottomUp");

            st->codec->extradata_size  = 9;

        }

    } else if (!strcmp(name, "Q_SPATIAL") || !strcmp(name, "Q_TEMPORAL")) {

        var_read_metadata(avctx, name, size);

    } else if (!strcmp(name, "INTERLACING") || !strcmp(name, "PACKING")) {

        avio_skip(pb, size); // ignore

    } else

        return -1;

    return 0;

}

void ff_acelp_weighted_filter(

        int16_t *out,

        const int16_t* in,

        const int16_t *weight_pow,

        int filter_length)

{

    int n;

    for(n=0; n<filter_length; n++)

        out[n] = (in[n] * weight_pow[n] + 0x4000) >> 15; /* (3.12) = (0.15) * (3.12) with rounding */

}

static int decode_tile(J2kDecoderContext *s, J2kTile *tile)

{

    int compno, reslevelno, bandno;

    int x, y, *src[4];

    uint8_t *line;

    J2kT1Context t1;



    for (compno = 0; compno < s->ncomponents; compno++){

        J2kComponent *comp = tile->comp + compno;

        J2kCodingStyle *codsty = tile->codsty + compno;



        for (reslevelno = 0; reslevelno < codsty->nreslevels; reslevelno++){

            J2kResLevel *rlevel = comp->reslevel + reslevelno;

            for (bandno = 0; bandno < rlevel->nbands; bandno++){

                J2kBand *band = rlevel->band + bandno;

                int cblkx, cblky, cblkno=0, xx0, x0, xx1, y0, yy0, yy1, bandpos;



                bandpos = bandno + (reslevelno > 0);



                yy0 = bandno == 0 ? 0 : comp->reslevel[reslevelno-1].coord[1][1] - comp->reslevel[reslevelno-1].coord[1][0];

                y0 = yy0;

                yy1 = FFMIN(ff_j2k_ceildiv(band->coord[1][0] + 1, band->codeblock_height) * band->codeblock_height,

                            band->coord[1][1]) - band->coord[1][0] + yy0;



                if (band->coord[0][0] == band->coord[0][1] || band->coord[1][0] == band->coord[1][1])

                    continue;



                for (cblky = 0; cblky < band->cblkny; cblky++){

                    if (reslevelno == 0 || bandno == 1)

                        xx0 = 0;

                    else

                        xx0 = comp->reslevel[reslevelno-1].coord[0][1] - comp->reslevel[reslevelno-1].coord[0][0];

                    x0 = xx0;

                    xx1 = FFMIN(ff_j2k_ceildiv(band->coord[0][0] + 1, band->codeblock_width) * band->codeblock_width,

                                band->coord[0][1]) - band->coord[0][0] + xx0;



                    for (cblkx = 0; cblkx < band->cblknx; cblkx++, cblkno++){

                        int y, x;

                        decode_cblk(s, codsty, &t1, band->cblk + cblkno, xx1 - xx0, yy1 - yy0, bandpos);

                        if (codsty->transform == FF_DWT53){

                            for (y = yy0; y < yy1; y+=s->cdy[compno]){

                                int *ptr = t1.data[y-yy0];

                                for (x = xx0; x < xx1; x+=s->cdx[compno]){

                                    comp->data[(comp->coord[0][1] - comp->coord[0][0]) * y + x] = *ptr++ >> 1;

                                }

                            }

                        } else{

                            for (y = yy0; y < yy1; y+=s->cdy[compno]){

                                int *ptr = t1.data[y-yy0];

                                for (x = xx0; x < xx1; x+=s->cdx[compno]){

                                    int tmp = ((int64_t)*ptr++) * ((int64_t)band->stepsize) >> 13, tmp2;

                                    tmp2 = FFABS(tmp>>1) + FFABS(tmp&1);

                                    comp->data[(comp->coord[0][1] - comp->coord[0][0]) * y + x] = tmp < 0 ? -tmp2 : tmp2;

                                }

                            }

                        }

                        xx0 = xx1;

                        xx1 = FFMIN(xx1 + band->codeblock_width, band->coord[0][1] - band->coord[0][0] + x0);

                    }

                    yy0 = yy1;

                    yy1 = FFMIN(yy1 + band->codeblock_height, band->coord[1][1] - band->coord[1][0] + y0);

                }

            }

        }

        ff_j2k_dwt_decode(&comp->dwt, comp->data);

        src[compno] = comp->data;

    }

    if (tile->codsty[0].mct)

        mct_decode(s, tile);



    if (s->avctx->pix_fmt == PIX_FMT_BGRA) // RGBA -> BGRA

        FFSWAP(int *, src[0], src[2]);



    if (s->precision <= 8) {

        for (compno = 0; compno < s->ncomponents; compno++){

            y = tile->comp[compno].coord[1][0] - s->image_offset_y;

            line = s->picture.data[0] + y * s->picture.linesize[0];

            for (; y < tile->comp[compno].coord[1][1] - s->image_offset_y; y += s->cdy[compno]){

                uint8_t *dst;



                x = tile->comp[compno].coord[0][0] - s->image_offset_x;

                dst = line + x * s->ncomponents + compno;



                for (; x < tile->comp[compno].coord[0][1] - s->image_offset_x; x += s->cdx[compno]) {

                    *src[compno] += 1 << (s->cbps[compno]-1);

                    if (*src[compno] < 0)

                        *src[compno] = 0;

                    else if (*src[compno] >= (1 << s->cbps[compno]))

                        *src[compno] = (1 << s->cbps[compno]) - 1;

                    *dst = *src[compno]++;

                    dst += s->ncomponents;

                }

                line += s->picture.linesize[0];

            }

        }

    } else {

        for (compno = 0; compno < s->ncomponents; compno++) {

            y = tile->comp[compno].coord[1][0] - s->image_offset_y;

            line = s->picture.data[0] + y * s->picture.linesize[0];

            for (; y < tile->comp[compno].coord[1][1] - s->image_offset_y; y += s->cdy[compno]) {

                uint16_t *dst;

                x = tile->comp[compno].coord[0][0] - s->image_offset_x;

                dst = line + (x * s->ncomponents + compno) * 2;

                for (; x < tile->comp[compno].coord[0][1] - s->image_offset_x; x += s-> cdx[compno]) {

                    int32_t val;

                    val = *src[compno]++ << (16 - s->cbps[compno]);

                    val += 1 << 15;

                    val = av_clip(val, 0, (1 << 16) - 1);

                    *dst = val;

                    dst += s->ncomponents;

                }

                line += s->picture.linesize[0];

            }

        }

    }

    return 0;

}

static int amv_encode_picture(AVCodecContext *avctx, AVPacket *pkt,

                              const AVFrame *pic_arg, int *got_packet)



{

    MpegEncContext *s = avctx->priv_data;

    AVFrame *pic;

    int i, ret;

    int chroma_h_shift, chroma_v_shift;



    av_pix_fmt_get_chroma_sub_sample(avctx->pix_fmt, &chroma_h_shift, &chroma_v_shift);



    //CODEC_FLAG_EMU_EDGE have to be cleared

    if(s->avctx->flags & CODEC_FLAG_EMU_EDGE)

        return AVERROR(EINVAL);



    pic = av_frame_alloc();

    if (!pic)

        return AVERROR(ENOMEM);

    av_frame_ref(pic, pic_arg);

    //picture should be flipped upside-down

    for(i=0; i < 3; i++) {

        int vsample = i ? 2 >> chroma_v_shift : 2;

        pic->data[i] += (pic->linesize[i] * (vsample * (8 * s->mb_height -((s->height/V_MAX)&7)) - 1 ));

        pic->linesize[i] *= -1;

    }

    ret = ff_MPV_encode_picture(avctx, pkt, pic, got_packet);

    av_frame_free(&pic);

    return ret;

}

