static void s390_init(ram_addr_t ram_size,

                      const char *boot_device,

                      const char *kernel_filename,

                      const char *kernel_cmdline,

                      const char *initrd_filename,

                      const char *cpu_model)

{

    CPUState *env = NULL;

    ram_addr_t ram_addr;

    ram_addr_t kernel_size = 0;

    ram_addr_t initrd_offset;

    ram_addr_t initrd_size = 0;

    int i;



    /* XXX we only work on KVM for now */



    if (!kvm_enabled()) {

        fprintf(stderr, "The S390 target only works with KVM enabled\n");

        exit(1);

    }



    /* get a BUS */

    s390_bus = s390_virtio_bus_init(&ram_size);



    /* allocate RAM */

    ram_addr = qemu_ram_alloc(NULL, "s390.ram", ram_size);

    cpu_register_physical_memory(0, ram_size, ram_addr);



    /* init CPUs */

    if (cpu_model == NULL) {

        cpu_model = "host";

    }



    ipi_states = qemu_malloc(sizeof(CPUState *) * smp_cpus);



    for (i = 0; i < smp_cpus; i++) {

        CPUState *tmp_env;



        tmp_env = cpu_init(cpu_model);

        if (!env) {

            env = tmp_env;

        }

        ipi_states[i] = tmp_env;

        tmp_env->halted = 1;

        tmp_env->exception_index = EXCP_HLT;

    }



    env->halted = 0;

    env->exception_index = 0;



    if (kernel_filename) {

        kernel_size = load_image(kernel_filename, qemu_get_ram_ptr(0));



        if (lduw_phys(KERN_IMAGE_START) != 0x0dd0) {

            fprintf(stderr, "Specified image is not an s390 boot image\n");

            exit(1);

        }



        env->psw.addr = KERN_IMAGE_START;

        env->psw.mask = 0x0000000180000000ULL;

    } else {

        ram_addr_t bios_size = 0;

        char *bios_filename;



        /* Load zipl bootloader */

        if (bios_name == NULL) {

            bios_name = ZIPL_FILENAME;

        }



        bios_filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

        bios_size = load_image(bios_filename, qemu_get_ram_ptr(ZIPL_LOAD_ADDR));




        if ((long)bios_size < 0) {

            hw_error("could not load bootloader '%s'\n", bios_name);

        }



        if (bios_size > 4096) {

            hw_error("stage1 bootloader is > 4k\n");

        }



        env->psw.addr = ZIPL_START;

        env->psw.mask = 0x0000000180000000ULL;

    }



    if (initrd_filename) {

        initrd_offset = INITRD_START;

        while (kernel_size + 0x100000 > initrd_offset) {

            initrd_offset += 0x100000;

        }

        initrd_size = load_image(initrd_filename, qemu_get_ram_ptr(initrd_offset));



        stq_phys(INITRD_PARM_START, initrd_offset);

        stq_phys(INITRD_PARM_SIZE, initrd_size);

    }



    if (kernel_cmdline) {

        cpu_physical_memory_rw(KERN_PARM_AREA, (uint8_t *)kernel_cmdline,

                               strlen(kernel_cmdline), 1);

    }



    /* Create VirtIO network adapters */

    for(i = 0; i < nb_nics; i++) {

        NICInfo *nd = &nd_table[i];

        DeviceState *dev;



        if (!nd->model) {

            nd->model = qemu_strdup("virtio");

        }



        if (strcmp(nd->model, "virtio")) {

            fprintf(stderr, "S390 only supports VirtIO nics\n");

            exit(1);

        }



        dev = qdev_create((BusState *)s390_bus, "virtio-net-s390");

        qdev_set_nic_properties(dev, nd);

        qdev_init_nofail(dev);

    }



    /* Create VirtIO disk drives */

    for(i = 0; i < MAX_BLK_DEVS; i++) {

        DriveInfo *dinfo;

        DeviceState *dev;



        dinfo = drive_get(IF_IDE, 0, i);

        if (!dinfo) {

            continue;

        }



        dev = qdev_create((BusState *)s390_bus, "virtio-blk-s390");

        qdev_prop_set_drive_nofail(dev, "drive", dinfo->bdrv);

        qdev_init_nofail(dev);

    }

}

int qcow2_snapshot_load_tmp(BlockDriverState *bs,

                            const char *snapshot_id,

                            const char *name,

                            Error **errp)

{

    int i, snapshot_index;

    BDRVQcowState *s = bs->opaque;

    QCowSnapshot *sn;

    uint64_t *new_l1_table;

    int new_l1_bytes;

    int ret;



    assert(bs->read_only);



    /* Search the snapshot */

    snapshot_index = find_snapshot_by_id_and_name(bs, snapshot_id, name);

    if (snapshot_index < 0) {

        error_setg(errp,

                   "Can't find snapshot");

        return -ENOENT;

    }

    sn = &s->snapshots[snapshot_index];



    /* Allocate and read in the snapshot's L1 table */

    if (sn->l1_size > QCOW_MAX_L1_SIZE) {

        error_setg(errp, "Snapshot L1 table too large");

        return -EFBIG;

    }

    new_l1_bytes = sn->l1_size * sizeof(uint64_t);

    new_l1_table = g_malloc0(align_offset(new_l1_bytes, 512));



    ret = bdrv_pread(bs->file, sn->l1_table_offset, new_l1_table, new_l1_bytes);

    if (ret < 0) {

        error_setg(errp, "Failed to read l1 table for snapshot");

        g_free(new_l1_table);

        return ret;

    }



    /* Switch the L1 table */

    g_free(s->l1_table);



    s->l1_size = sn->l1_size;

    s->l1_table_offset = sn->l1_table_offset;

    s->l1_table = new_l1_table;



    for(i = 0;i < s->l1_size; i++) {

        be64_to_cpus(&s->l1_table[i]);

    }



    return 0;

}

int av_bsf_list_parse_str(const char *str, AVBSFContext **bsf_lst)

{

    AVBSFList *lst;

    char *bsf_str, *buf, *dup, *saveptr;

    int ret;



    if (!str)

        return av_bsf_get_null_filter(bsf_lst);



    lst = av_bsf_list_alloc();

    if (!lst)

        return AVERROR(ENOMEM);



    if (!(dup = buf = av_strdup(str)))

        return AVERROR(ENOMEM);



    while (1) {

        bsf_str = av_strtok(buf, ",", &saveptr);

        if (!bsf_str)

            break;



        ret = bsf_parse_single(bsf_str, lst);

        if (ret < 0)

            goto end;



        buf = NULL;

    }



    ret = av_bsf_list_finalize(&lst, bsf_lst);

end:

    if (ret < 0)

        av_bsf_list_free(&lst);

    av_free(dup);

    return ret;

}

