static void icp_set_cppr(struct icp_state *icp, int server, uint8_t cppr)

{

    struct icp_server_state *ss = icp->ss + server;

    uint8_t old_cppr;

    uint32_t old_xisr;



    old_cppr = CPPR(ss);

    ss->xirr = (ss->xirr & ~CPPR_MASK) | (cppr << 24);



    if (cppr < old_cppr) {

        if (XISR(ss) && (cppr <= ss->pending_priority)) {

            old_xisr = XISR(ss);

            ss->xirr &= ~XISR_MASK; /* Clear XISR */


            qemu_irq_lower(ss->output);

            ics_reject(icp->ics, old_xisr);

        }

    } else {

        if (!XISR(ss)) {

            icp_resend(icp, server);

        }

    }

}

static int ra288_decode_frame(AVCodecContext * avctx, void *data,

                              int *data_size, const uint8_t * buf,

                              int buf_size)

{

    int16_t *out = data;

    int i, j;

    RA288Context *ractx = avctx->priv_data;

    GetBitContext gb;



    if (buf_size < avctx->block_align) {

        av_log(avctx, AV_LOG_ERROR,

               "Error! Input buffer is too small [%d<%d]\n",

               buf_size, avctx->block_align);

        return 0;

    }



    init_get_bits(&gb, buf, avctx->block_align * 8);



    for (i=0; i < 32; i++) {

        float gain = amptable[get_bits(&gb, 3)];

        int cb_coef = get_bits(&gb, 6 + (i&1));



        decode(ractx, gain, cb_coef);



        for (j=0; j < 5; j++)

            *(out++) = 8 * ractx->sp_block[4 - j];



        if ((i & 7) == 3)

            backward_filter(ractx);

    }



    *data_size = (char *)out - (char *)data;

    return avctx->block_align;

}

static int read_ir(AVFilterLink *inlink, AVFrame *frame)

{

    AVFilterContext *ctx = inlink->dst;

    HeadphoneContext *s = ctx->priv;

    int ir_len, max_ir_len, input_number;



    for (input_number = 0; input_number < s->nb_inputs; input_number++)

        if (inlink == ctx->inputs[input_number])

            break;



    av_audio_fifo_write(s->in[input_number].fifo, (void **)frame->extended_data,

                        frame->nb_samples);

    av_frame_free(&frame);



    ir_len = av_audio_fifo_size(s->in[input_number].fifo);

    max_ir_len = 65536;

    if (ir_len > max_ir_len) {

        av_log(ctx, AV_LOG_ERROR, "Too big length of IRs: %d > %d.\n", ir_len, max_ir_len);

        return AVERROR(EINVAL);

    }

    s->in[input_number].ir_len = ir_len;

    s->ir_len = FFMAX(ir_len, s->ir_len);



    return 0;

}

static av_cold int aac_decode_init(AVCodecContext *avctx)

{

    AACContext *ac = avctx->priv_data;

    float output_scale_factor;



    ac->avctx = avctx;

    ac->oc[1].m4ac.sample_rate = avctx->sample_rate;



    if (avctx->extradata_size > 0) {

        if (decode_audio_specific_config(ac, ac->avctx, &ac->oc[1].m4ac,

                                         avctx->extradata,

                                         avctx->extradata_size*8, 1) < 0)

            return -1;

    } else {

        int sr, i;

        uint8_t layout_map[MAX_ELEM_ID*4][3];

        int layout_map_tags;



        sr = sample_rate_idx(avctx->sample_rate);

        ac->oc[1].m4ac.sampling_index = sr;

        ac->oc[1].m4ac.channels = avctx->channels;

        ac->oc[1].m4ac.sbr = -1;

        ac->oc[1].m4ac.ps = -1;



        for (i = 0; i < FF_ARRAY_ELEMS(ff_mpeg4audio_channels); i++)

            if (ff_mpeg4audio_channels[i] == avctx->channels)

                break;

        if (i == FF_ARRAY_ELEMS(ff_mpeg4audio_channels)) {

            i = 0;

        }

        ac->oc[1].m4ac.chan_config = i;



        if (ac->oc[1].m4ac.chan_config) {

            int ret = set_default_channel_config(avctx, layout_map,

                &layout_map_tags, ac->oc[1].m4ac.chan_config);

            if (!ret)

                output_configure(ac, layout_map, layout_map_tags,

                                 ac->oc[1].m4ac.chan_config, OC_GLOBAL_HDR);

            else if (avctx->err_recognition & AV_EF_EXPLODE)

                return AVERROR_INVALIDDATA;

        }

    }



    if (avctx->request_sample_fmt == AV_SAMPLE_FMT_FLT) {

        avctx->sample_fmt = AV_SAMPLE_FMT_FLT;

        output_scale_factor = 1.0 / 32768.0;

    } else {

        avctx->sample_fmt = AV_SAMPLE_FMT_S16;

        output_scale_factor = 1.0;

    }



    AAC_INIT_VLC_STATIC( 0, 304);

    AAC_INIT_VLC_STATIC( 1, 270);

    AAC_INIT_VLC_STATIC( 2, 550);

    AAC_INIT_VLC_STATIC( 3, 300);

    AAC_INIT_VLC_STATIC( 4, 328);

    AAC_INIT_VLC_STATIC( 5, 294);

    AAC_INIT_VLC_STATIC( 6, 306);

    AAC_INIT_VLC_STATIC( 7, 268);

    AAC_INIT_VLC_STATIC( 8, 510);

    AAC_INIT_VLC_STATIC( 9, 366);

    AAC_INIT_VLC_STATIC(10, 462);



    ff_aac_sbr_init();



    ff_dsputil_init(&ac->dsp, avctx);

    ff_fmt_convert_init(&ac->fmt_conv, avctx);

    avpriv_float_dsp_init(&ac->fdsp, avctx->flags & CODEC_FLAG_BITEXACT);



    ac->random_state = 0x1f2e3d4c;



    ff_aac_tableinit();



    INIT_VLC_STATIC(&vlc_scalefactors,7,FF_ARRAY_ELEMS(ff_aac_scalefactor_code),

                    ff_aac_scalefactor_bits, sizeof(ff_aac_scalefactor_bits[0]), sizeof(ff_aac_scalefactor_bits[0]),

                    ff_aac_scalefactor_code, sizeof(ff_aac_scalefactor_code[0]), sizeof(ff_aac_scalefactor_code[0]),

                    352);



    ff_mdct_init(&ac->mdct,       11, 1, output_scale_factor/1024.0);

    ff_mdct_init(&ac->mdct_small,  8, 1, output_scale_factor/128.0);

    ff_mdct_init(&ac->mdct_ltp,   11, 0, -2.0/output_scale_factor);

    // window initialization

    ff_kbd_window_init(ff_aac_kbd_long_1024, 4.0, 1024);

    ff_kbd_window_init(ff_aac_kbd_short_128, 6.0, 128);

    ff_init_ff_sine_windows(10);

    ff_init_ff_sine_windows( 7);



    cbrt_tableinit();



    avcodec_get_frame_defaults(&ac->frame);

    avctx->coded_frame = &ac->frame;



    return 0;

}

static int roq_encode_video(RoqContext *enc)

{

    RoqTempdata *tempData = enc->tmpData;

    int i, ret;



    memset(tempData, 0, sizeof(*tempData));



    ret = create_cel_evals(enc, tempData);

    if (ret < 0)

        return ret;



    ret = generate_new_codebooks(enc, tempData);

    if (ret < 0)

        return ret;



    if (enc->framesSinceKeyframe >= 1) {

        motion_search(enc, 8);

        motion_search(enc, 4);

    }



 retry_encode:

    for (i=0; i<enc->width*enc->height/64; i++)

        gather_data_for_cel(tempData->cel_evals + i, enc, tempData);



    /* Quake 3 can't handle chunks bigger than 65535 bytes */

    if (tempData->mainChunkSize/8 > 65535) {

        av_log(enc->avctx, AV_LOG_ERROR,

               "Warning, generated a frame too big (%d > 65535), "

               "try using a smaller qscale value.\n",

               tempData->mainChunkSize/8);

        enc->lambda *= 1.5;

        tempData->mainChunkSize = 0;

        memset(tempData->used_option, 0, sizeof(tempData->used_option));

        memset(tempData->codebooks.usedCB4, 0,

               sizeof(tempData->codebooks.usedCB4));

        memset(tempData->codebooks.usedCB2, 0,

               sizeof(tempData->codebooks.usedCB2));



        goto retry_encode;

    }



    remap_codebooks(enc, tempData);



    write_codebooks(enc, tempData);



    reconstruct_and_encode_image(enc, tempData, enc->width, enc->height,

                                 enc->width*enc->height/64);



    enc->avctx->coded_frame = enc->current_frame;



    /* Rotate frame history */

    FFSWAP(AVFrame *, enc->current_frame, enc->last_frame);

    FFSWAP(motion_vect *, enc->last_motion4, enc->this_motion4);

    FFSWAP(motion_vect *, enc->last_motion8, enc->this_motion8);



    av_free(tempData->cel_evals);

    av_free(tempData->closest_cb2);



    enc->framesSinceKeyframe++;



    return 0;

}

void do_sraw (void)

{

    int32_t ret;



    if (likely(!(T1 & 0x20UL))) {

        if (likely((uint32_t)T1 != 0)) {

            ret = (int32_t)T0 >> (T1 & 0x1fUL);

            if (likely(ret >= 0 || ((int32_t)T0 & ((1 << T1) - 1)) == 0)) {

                xer_ca = 0;

            } else {

                xer_ca = 1;

            }

        } else {

            ret = T0;

            xer_ca = 0;

        }

    } else {

        ret = (-1) * ((uint32_t)T0 >> 31);

        if (likely(ret >= 0 || ((uint32_t)T0 & ~0x80000000UL) == 0)) {

            xer_ca = 0;

        } else {

            xer_ca = 1;

        }

    }

    T0 = ret;

}

