int av_parse_color(uint8_t *rgba_color, const char *color_string, void *log_ctx)

{

    if (!strcasecmp(color_string, "random") || !strcasecmp(color_string, "bikeshed")) {

        int rgba = ff_random_get_seed();

        rgba_color[0] = rgba >> 24;

        rgba_color[1] = rgba >> 16;

        rgba_color[2] = rgba >> 8;

        rgba_color[3] = rgba;

    } else

    if (!strncmp(color_string, "0x", 2)) {

        char *tail;

        int len = strlen(color_string);

        int rgba = strtol(color_string, &tail, 16);



        if (*tail || (len != 8 && len != 10)) {

            av_log(log_ctx, AV_LOG_ERROR, "Invalid 0xRRGGBB[AA] color string: '%s'\n", color_string);

            return -1;

        }

        if (len == 10) {

            rgba_color[3] = rgba;

            rgba >>= 8;

        }

        rgba_color[0] = rgba >> 16;

        rgba_color[1] = rgba >> 8;

        rgba_color[2] = rgba;

    } else {

        const ColorEntry *entry = bsearch(color_string,

                                          color_table,

                                          FF_ARRAY_ELEMS(color_table),

                                          sizeof(ColorEntry),

                                          color_table_compare);

        if (!entry) {

            av_log(log_ctx, AV_LOG_ERROR, "Cannot find color '%s'\n", color_string);

            return -1;

        }

        memcpy(rgba_color, entry->rgba_color, 4);

    }



    return 0;

}

static int wv_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    WVContext *wc = s->priv_data;

    AVStream *st;

    int ret;



    wc->block_parsed = 0;

    for (;;) {

        if ((ret = wv_read_block_header(s, pb, 0)) < 0)

            return ret;

        if (!AV_RN32(wc->extra))

            avio_skip(pb, wc->blksize - 24);

        else

            break;

    }



    /* now we are ready: build format streams */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->codec->codec_type            = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id              = AV_CODEC_ID_WAVPACK;

    st->codec->channels              = wc->chan;

    st->codec->channel_layout        = wc->chmask;

    st->codec->sample_rate           = wc->rate;

    st->codec->bits_per_coded_sample = wc->bpp;

    avpriv_set_pts_info(st, 64, 1, wc->rate);

    st->start_time = 0;

    st->duration   = wc->samples;



    if (s->pb->seekable) {

        int64_t cur = avio_tell(s->pb);

        wc->apetag_start = ff_ape_parse_tag(s);

        if (!av_dict_get(s->metadata, "", NULL, AV_DICT_IGNORE_SUFFIX))

            ff_id3v1_read(s);

        avio_seek(s->pb, cur, SEEK_SET);

    }



    return 0;

}

static int add_shorts_metadata(int count, const char *name,

                               const char *sep, TiffContext *s)

{

    char *ap;

    int i;

    int16_t *sp;



    if (bytestream2_get_bytes_left(&s->gb) < count * sizeof(int16_t))

        return -1;



    sp = av_malloc(count * sizeof(int16_t));

    if (!sp)

        return AVERROR(ENOMEM);



    for (i = 0; i < count; i++)

        sp[i] = tget_short(&s->gb, s->le);

    ap = shorts2str(sp, count, sep);

    av_freep(&sp);

    if (!ap)

        return AVERROR(ENOMEM);

    av_dict_set(&s->picture.metadata, name, ap, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

static av_always_inline void thread_park_workers(ThreadContext *c, int thread_count)

{

    while (c->current_job != thread_count + c->job_count)

        pthread_cond_wait(&c->last_job_cond, &c->current_job_lock);

    pthread_mutex_unlock(&c->current_job_lock);

}

bool cpu_exec_all(void)

{

    int r;



    /* Account partial waits to the vm_clock.  */

    qemu_clock_warp(vm_clock);



    if (next_cpu == NULL) {

        next_cpu = first_cpu;

    }

    for (; next_cpu != NULL && !exit_request; next_cpu = next_cpu->next_cpu) {

        CPUState *env = next_cpu;



        qemu_clock_enable(vm_clock,

                          (env->singlestep_enabled & SSTEP_NOTIMER) == 0);



#ifndef CONFIG_IOTHREAD

        if (qemu_alarm_pending()) {

            break;

        }

#endif

        if (cpu_can_run(env)) {

            if (kvm_enabled()) {

                r = kvm_cpu_exec(env);

                qemu_kvm_eat_signals(env);

            } else {

                r = tcg_cpu_exec(env);

            }

            if (r == EXCP_DEBUG) {

                cpu_handle_guest_debug(env);

                break;

            }

        } else if (env->stop || env->stopped) {

            break;

        }

    }

    exit_request = 0;

    return !all_cpu_threads_idle();

}

static int extract_header(AVCodecContext *const avctx,

                          const AVPacket *const avpkt) {

    const uint8_t *buf;

    unsigned buf_size;

    IffContext *s = avctx->priv_data;

    int palette_size;



    if (avctx->extradata_size < 2) {

        av_log(avctx, AV_LOG_ERROR, "not enough extradata\n");

        return AVERROR_INVALIDDATA;


    palette_size = avctx->extradata_size - AV_RB16(avctx->extradata);



    if (avpkt) {

        int image_size;

        if (avpkt->size < 2)

            return AVERROR_INVALIDDATA;

        image_size = avpkt->size - AV_RB16(avpkt->data);

        buf = avpkt->data;

        buf_size = bytestream_get_be16(&buf);

        if (buf_size <= 1 || image_size <= 1) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid image size received: %u -> image data offset: %d\n",

                   buf_size, image_size);

            return AVERROR_INVALIDDATA;


    } else {

        buf = avctx->extradata;

        buf_size = bytestream_get_be16(&buf);

        if (buf_size <= 1 || palette_size < 0) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid palette size received: %u -> palette data offset: %d\n",

                   buf_size, palette_size);

            return AVERROR_INVALIDDATA;





    if (buf_size > 8) {

        s->compression  = bytestream_get_byte(&buf);

        s->bpp          = bytestream_get_byte(&buf);

        s->ham          = bytestream_get_byte(&buf);

        s->flags        = bytestream_get_byte(&buf);

        s->transparency = bytestream_get_be16(&buf);

        s->masking      = bytestream_get_byte(&buf);

        if (s->masking == MASK_HAS_MASK) {

            if (s->bpp >= 8) {

                avctx->pix_fmt = PIX_FMT_RGB32;


                av_freep(&s->mask_palbuf);

                s->mask_buf = av_malloc((s->planesize * 32) + FF_INPUT_BUFFER_PADDING_SIZE);

                if (!s->mask_buf)







                s->mask_palbuf = av_malloc((2 << s->bpp) * sizeof(uint32_t) + FF_INPUT_BUFFER_PADDING_SIZE);

                if (!s->mask_palbuf) {





            s->bpp++;

        } else if (s->masking != MASK_NONE && s->masking != MASK_HAS_TRANSPARENT_COLOR) {

            av_log(avctx, AV_LOG_ERROR, "Masking not supported\n");

            return AVERROR_PATCHWELCOME;


        if (!s->bpp || s->bpp > 32) {

            av_log(avctx, AV_LOG_ERROR, "Invalid number of bitplanes: %u\n", s->bpp);

            return AVERROR_INVALIDDATA;

        } else if (s->ham >= 8) {

            av_log(avctx, AV_LOG_ERROR, "Invalid number of hold bits for HAM: %u\n", s->ham);

            return AVERROR_INVALIDDATA;




        av_freep(&s->ham_buf);

        av_freep(&s->ham_palbuf);



        if (s->ham) {

            int i, count = FFMIN(palette_size / 3, 1 << s->ham);

            int ham_count;

            const uint8_t *const palette = avctx->extradata + AV_RB16(avctx->extradata);



            s->ham_buf = av_malloc((s->planesize * 8) + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!s->ham_buf)




            ham_count = 8 * (1 << s->ham);

            s->ham_palbuf = av_malloc((ham_count << !!(s->masking == MASK_HAS_MASK)) * sizeof (uint32_t) + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!s->ham_palbuf) {

                av_freep(&s->ham_buf);





            if (count) { // HAM with color palette attached

                // prefill with black and palette and set HAM take direct value mask to zero

                memset(s->ham_palbuf, 0, (1 << s->ham) * 2 * sizeof (uint32_t));

                for (i=0; i < count; i++) {

                    s->ham_palbuf[i*2+1] = 0xFF000000 | AV_RL24(palette + i*3);


                count = 1 << s->ham;

            } else { // HAM with grayscale color palette

                count = 1 << s->ham;

                for (i=0; i < count; i++) {

                    s->ham_palbuf[i*2]   = 0xFF000000; // take direct color value from palette

                    s->ham_palbuf[i*2+1] = 0xFF000000 | av_le2ne32(gray2rgb((i * 255) >> s->ham));



            for (i=0; i < count; i++) {

                uint32_t tmp = i << (8 - s->ham);

                tmp |= tmp >> s->ham;

                s->ham_palbuf[(i+count)*2]     = 0xFF00FFFF; // just modify blue color component

                s->ham_palbuf[(i+count*2)*2]   = 0xFFFFFF00; // just modify red color component

                s->ham_palbuf[(i+count*3)*2]   = 0xFFFF00FF; // just modify green color component

                s->ham_palbuf[(i+count)*2+1]   = 0xFF000000 | tmp << 16;

                s->ham_palbuf[(i+count*2)*2+1] = 0xFF000000 | tmp;

                s->ham_palbuf[(i+count*3)*2+1] = 0xFF000000 | tmp << 8;


            if (s->masking == MASK_HAS_MASK) {

                for (i = 0; i < ham_count; i++)

                    s->ham_palbuf[(1 << s->bpp) + i] = s->ham_palbuf[i] | 0xFF000000;






    return 0;

