            out0 = __msa_copy_u_w(tmp7, 0);

            out1 = __msa_copy_u_h(tmp5, 4);

            out2 = __msa_copy_u_w(tmp7, 1);

            out3 = __msa_copy_u_h(tmp5, 5);



            src += img_width;

