static int parse_dsd_prop(AVFormatContext *s, AVStream *st, uint64_t eof)

{

    AVIOContext *pb = s->pb;

    char abss[24];

    int hour, min, sec, i, ret, config;

    int dsd_layout[6];

    ID3v2ExtraMeta *id3v2_extra_meta;



    while (avio_tell(pb) + 12 <= eof) {

        uint32_t tag      = avio_rl32(pb);

        uint64_t size     = avio_rb64(pb);

        uint64_t orig_pos = avio_tell(pb);



        switch(tag) {

        case MKTAG('A','B','S','S'):

            if (size < 8)

                return AVERROR_INVALIDDATA;

            hour = avio_rb16(pb);

            min  = avio_r8(pb);

            sec  = avio_r8(pb);

            snprintf(abss, sizeof(abss), "%02dh:%02dm:%02ds:%d", hour, min, sec, avio_rb32(pb));

            av_dict_set(&st->metadata, "absolute_start_time", abss, 0);

            break;



        case MKTAG('C','H','N','L'):

            if (size < 2)

                return AVERROR_INVALIDDATA;

            st->codecpar->channels       = avio_rb16(pb);

            if (size < 2 + st->codecpar->channels * 4)

                return AVERROR_INVALIDDATA;

            st->codecpar->channel_layout = 0;

            if (st->codecpar->channels > FF_ARRAY_ELEMS(dsd_layout)) {

                avpriv_request_sample(s, "channel layout");

                break;

            }

            for (i = 0; i < st->codecpar->channels; i++)

                dsd_layout[i] = avio_rl32(pb);

            for (i = 0; i < FF_ARRAY_ELEMS(dsd_channel_layout); i++) {

                const DSDLayoutDesc * d = &dsd_channel_layout[i];

                if (av_get_channel_layout_nb_channels(d->layout) == st->codecpar->channels &&

                    !memcmp(d->dsd_layout, dsd_layout, st->codecpar->channels * sizeof(uint32_t))) {

                    st->codecpar->channel_layout = d->layout;

                    break;

                }

            }

            break;



        case MKTAG('C','M','P','R'):

            if (size < 4)

                return AVERROR_INVALIDDATA;

            tag = avio_rl32(pb);

            st->codecpar->codec_id = ff_codec_get_id(dsd_codec_tags, tag);

            if (!st->codecpar->codec_id) {

                av_log(s, AV_LOG_ERROR, "'%c%c%c%c' compression is not supported\n",

                    tag&0xFF, (tag>>8)&0xFF, (tag>>16)&0xFF, (tag>>24)&0xFF);

                return AVERROR_PATCHWELCOME;

            }

            break;



        case MKTAG('F','S',' ',' '):

            if (size < 4)

                return AVERROR_INVALIDDATA;

            st->codecpar->sample_rate = avio_rb32(pb) / 8;

            break;



        case MKTAG('I','D','3',' '):

            id3v2_extra_meta = NULL;

            ff_id3v2_read(s, ID3v2_DEFAULT_MAGIC, &id3v2_extra_meta, size);

            if (id3v2_extra_meta) {

                if ((ret = ff_id3v2_parse_apic(s, &id3v2_extra_meta)) < 0) {

                    ff_id3v2_free_extra_meta(&id3v2_extra_meta);

                    return ret;

                }

                ff_id3v2_free_extra_meta(&id3v2_extra_meta);

            }



            if (size < avio_tell(pb) - orig_pos) {

                av_log(s, AV_LOG_ERROR, "id3 exceeds chunk size\n");

                return AVERROR_INVALIDDATA;

            }

            break;



        case MKTAG('L','S','C','O'):

            if (size < 2)

                return AVERROR_INVALIDDATA;

            config = avio_rb16(pb);

            if (config != 0xFFFF) {

                if (config < FF_ARRAY_ELEMS(dsd_loudspeaker_config))

                    st->codecpar->channel_layout = dsd_loudspeaker_config[config];

                if (!st->codecpar->channel_layout)

                    avpriv_request_sample(s, "loudspeaker configuration %d", config);

            }

            break;

        }



        avio_skip(pb, size - (avio_tell(pb) - orig_pos) + (size & 1));

    }



    return 0;

}

int ff_h264_execute_ref_pic_marking(H264Context *h, MMCO *mmco, int mmco_count)

{

    int i, av_uninit(j);

    int current_ref_assigned = 0, err = 0;

    Picture *av_uninit(pic);



    if ((h->avctx->debug & FF_DEBUG_MMCO) && mmco_count == 0)

        av_log(h->avctx, AV_LOG_DEBUG, "no mmco here\n");



    for (i = 0; i < mmco_count; i++) {

        int av_uninit(structure), av_uninit(frame_num);

        if (h->avctx->debug & FF_DEBUG_MMCO)

            av_log(h->avctx, AV_LOG_DEBUG, "mmco:%d %d %d\n", h->mmco[i].opcode,

                   h->mmco[i].short_pic_num, h->mmco[i].long_arg);



        if (mmco[i].opcode == MMCO_SHORT2UNUSED ||

            mmco[i].opcode == MMCO_SHORT2LONG) {

            frame_num = pic_num_extract(h, mmco[i].short_pic_num, &structure);

            pic       = find_short(h, frame_num, &j);

            if (!pic) {

                if (mmco[i].opcode != MMCO_SHORT2LONG ||

                    !h->long_ref[mmco[i].long_arg]    ||

                    h->long_ref[mmco[i].long_arg]->frame_num != frame_num) {

                    av_log(h->avctx, AV_LOG_ERROR, "mmco: unref short failure\n");

                    err = AVERROR_INVALIDDATA;


                continue;





        switch (mmco[i].opcode) {

        case MMCO_SHORT2UNUSED:

            if (h->avctx->debug & FF_DEBUG_MMCO)

                av_log(h->avctx, AV_LOG_DEBUG, "mmco: unref short %d count %d\n",

                       h->mmco[i].short_pic_num, h->short_ref_count);

            remove_short(h, frame_num, structure ^ PICT_FRAME);

            break;

        case MMCO_SHORT2LONG:

                if (h->long_ref[mmco[i].long_arg] != pic)

                    remove_long(h, mmco[i].long_arg, 0);



                remove_short_at_index(h, j);

                h->long_ref[ mmco[i].long_arg ] = pic;

                if (h->long_ref[mmco[i].long_arg]) {

                    h->long_ref[mmco[i].long_arg]->long_ref = 1;

                    h->long_ref_count++;


            break;

        case MMCO_LONG2UNUSED:

            j   = pic_num_extract(h, mmco[i].long_arg, &structure);

            pic = h->long_ref[j];

            if (pic) {

                remove_long(h, j, structure ^ PICT_FRAME);

            } else if (h->avctx->debug & FF_DEBUG_MMCO)

                av_log(h->avctx, AV_LOG_DEBUG, "mmco: unref long failure\n");

            break;

        case MMCO_LONG:

                    // Comment below left from previous code as it is an interresting note.

                    /* First field in pair is in short term list or

                     * at a different long term index.

                     * This is not allowed; see 7.4.3.3, notes 2 and 3.

                     * Report the problem and keep the pair where it is,

                     * and mark this field valid.

                     */



            if (h->long_ref[mmco[i].long_arg] != h->cur_pic_ptr) {

                remove_long(h, mmco[i].long_arg, 0);






                h->long_ref[mmco[i].long_arg]           = h->cur_pic_ptr;

                h->long_ref[mmco[i].long_arg]->long_ref = 1;

                h->long_ref_count++;




            h->cur_pic_ptr->reference |= h->picture_structure;

            current_ref_assigned = 1;

            break;

        case MMCO_SET_MAX_LONG:

            assert(mmco[i].long_arg <= 16);

            // just remove the long term which index is greater than new max

            for (j = mmco[i].long_arg; j < 16; j++) {

                remove_long(h, j, 0);


            break;

        case MMCO_RESET:

            while (h->short_ref_count) {

                remove_short(h, h->short_ref[0]->frame_num, 0);


            for (j = 0; j < 16; j++) {

                remove_long(h, j, 0);


            h->frame_num  = h->cur_pic_ptr->frame_num = 0;

            h->mmco_reset = 1;

            h->cur_pic_ptr->mmco_reset = 1;

            for (j = 0; j < MAX_DELAYED_PIC_COUNT; j++)

                h->last_pocs[j] = INT_MIN;

            break;

        default: assert(0);





    if (!current_ref_assigned) {

        /* Second field of complementary field pair; the first field of

         * which is already referenced. If short referenced, it

         * should be first entry in short_ref. If not, it must exist

         * in long_ref; trying to put it on the short list here is an

         * error in the encoded bit stream (ref: 7.4.3.3, NOTE 2 and 3).

         */

        if (h->short_ref_count && h->short_ref[0] == h->cur_pic_ptr) {

            /* Just mark the second field valid */

            h->cur_pic_ptr->reference = PICT_FRAME;

        } else if (h->cur_pic_ptr->long_ref) {

            av_log(h->avctx, AV_LOG_ERROR, "illegal short term reference "

                                           "assignment for second field "

                                           "in complementary field pair "

                                           "(first field is long term)\n");

            err = AVERROR_INVALIDDATA;

        } else {

            pic = remove_short(h, h->cur_pic_ptr->frame_num, 0);

            if (pic) {

                av_log(h->avctx, AV_LOG_ERROR, "illegal short term buffer state detected\n");

                err = AVERROR_INVALIDDATA;




            if (h->short_ref_count)

                memmove(&h->short_ref[1], &h->short_ref[0],

                        h->short_ref_count * sizeof(Picture*));



            h->short_ref[0] = h->cur_pic_ptr;

            h->short_ref_count++;

            h->cur_pic_ptr->reference |= h->picture_structure;





    if (h->long_ref_count + h->short_ref_count > FFMAX(h->sps.ref_frame_count, 1)) {



        /* We have too many reference frames, probably due to corrupted

         * stream. Need to discard one frame. Prevents overrun of the

         * short_ref and long_ref buffers.

         */

        av_log(h->avctx, AV_LOG_ERROR,

               "number of reference frames (%d+%d) exceeds max (%d; probably "

               "corrupt input), discarding one\n",

               h->long_ref_count, h->short_ref_count, h->sps.ref_frame_count);

        err = AVERROR_INVALIDDATA;



        if (h->long_ref_count && !h->short_ref_count) {

            for (i = 0; i < 16; ++i)

                if (h->long_ref[i])

                    break;



            assert(i < 16);

            remove_long(h, i, 0);

        } else {

            pic = h->short_ref[h->short_ref_count - 1];

            remove_short(h, pic->frame_num, 0);





    print_short_term(h);

    print_long_term(h);



    if(err >= 0 && h->long_ref_count==0 && h->short_ref_count<=2 && h->pps.ref_count[0]<=1 + (h->picture_structure != PICT_FRAME) && h->cur_pic_ptr->f.pict_type == AV_PICTURE_TYPE_I){

        h->cur_pic_ptr->sync |= 1;

        if(!h->avctx->has_b_frames)

            h->sync = 2;




    return (h->avctx->err_recognition & AV_EF_EXPLODE) ? err : 0;

void qpci_msix_enable(QPCIDevice *dev)

{

    uint8_t addr;

    uint16_t val;

    uint32_t table;

    uint8_t bir_table;

    uint8_t bir_pba;

    void *offset;



    addr = qpci_find_capability(dev, PCI_CAP_ID_MSIX);

    g_assert_cmphex(addr, !=, 0);



    val = qpci_config_readw(dev, addr + PCI_MSIX_FLAGS);

    qpci_config_writew(dev, addr + PCI_MSIX_FLAGS, val | PCI_MSIX_FLAGS_ENABLE);



    table = qpci_config_readl(dev, addr + PCI_MSIX_TABLE);

    bir_table = table & PCI_MSIX_FLAGS_BIRMASK;

    offset = qpci_iomap(dev, bir_table, NULL);

    dev->msix_table = offset + (table & ~PCI_MSIX_FLAGS_BIRMASK);



    table = qpci_config_readl(dev, addr + PCI_MSIX_PBA);

    bir_pba = table & PCI_MSIX_FLAGS_BIRMASK;

    if (bir_pba != bir_table) {

        offset = qpci_iomap(dev, bir_pba, NULL);

    }

    dev->msix_pba = offset + (table & ~PCI_MSIX_FLAGS_BIRMASK);



    g_assert(dev->msix_table != NULL);

    g_assert(dev->msix_pba != NULL);

    dev->msix_enabled = true;

}

static void alloc_picture(VideoState *is)

{

    VideoPicture *vp;

    int64_t bufferdiff;



    vp = &is->pictq[is->pictq_windex];



    if (vp->bmp)

        SDL_FreeYUVOverlay(vp->bmp);



    video_open(is, 0, vp);



    vp->bmp = SDL_CreateYUVOverlay(vp->width, vp->height,

                                   SDL_YV12_OVERLAY,

                                   screen);

    bufferdiff = vp->bmp ? FFMAX(vp->bmp->pixels[0], vp->bmp->pixels[1]) - FFMIN(vp->bmp->pixels[0], vp->bmp->pixels[1]) : 0;

    if (!vp->bmp || vp->bmp->pitches[0] < vp->width || bufferdiff < vp->height * vp->bmp->pitches[0]) {

        /* SDL allocates a buffer smaller than requested if the video

         * overlay hardware is unable to support the requested size. */

        av_log(NULL, AV_LOG_FATAL,

               "Error: the video system does not support an image\n"

                        "size of %dx%d pixels. Try using -lowres or -vf \"scale=w:h\"\n"

                        "to reduce the image size.\n", vp->width, vp->height );

        do_exit(is);

    }



    SDL_LockMutex(is->pictq_mutex);

    vp->allocated = 1;

    SDL_CondSignal(is->pictq_cond);

    SDL_UnlockMutex(is->pictq_mutex);

}

