#endif

}

static int vaapi_encode_h264_init_picture_params(AVCodecContext *avctx,

                                                 VAAPIEncodePicture *pic)

{

    VAAPIEncodeContext                *ctx = avctx->priv_data;

    VAEncSequenceParameterBufferH264 *vseq = ctx->codec_sequence_params;

    VAEncPictureParameterBufferH264  *vpic = pic->codec_picture_params;

    VAAPIEncodeH264Context           *priv = ctx->priv_data;

    int i;



    if (pic->type == PICTURE_TYPE_IDR) {

        av_assert0(pic->display_order == pic->encode_order);

        vpic->frame_num = 0;

        priv->next_frame_num = 1;

        priv->cpb_delay = 0;

    } else {

        vpic->frame_num = priv->next_frame_num;

        if (pic->type != PICTURE_TYPE_B) {

            // nal_ref_idc != 0

            ++priv->next_frame_num;

        }

        ++priv->cpb_delay;

    }

    priv->dpb_delay = pic->display_order - pic->encode_order + 1;



    vpic->frame_num = vpic->frame_num &

        ((1 << (4 + vseq->seq_fields.bits.log2_max_frame_num_minus4)) - 1);



    vpic->CurrPic.picture_id          = pic->recon_surface;

    vpic->CurrPic.frame_idx           = vpic->frame_num;

    vpic->CurrPic.flags               = 0;

    vpic->CurrPic.TopFieldOrderCnt    = pic->display_order;

    vpic->CurrPic.BottomFieldOrderCnt = pic->display_order;



    for (i = 0; i < pic->nb_refs; i++) {

        VAAPIEncodePicture *ref = pic->refs[i];

        av_assert0(ref && ref->encode_order < pic->encode_order);

        vpic->ReferenceFrames[i].picture_id = ref->recon_surface;

        vpic->ReferenceFrames[i].frame_idx  = ref->encode_order;

        vpic->ReferenceFrames[i].flags = VA_PICTURE_H264_SHORT_TERM_REFERENCE;

        vpic->ReferenceFrames[i].TopFieldOrderCnt    = ref->display_order;

        vpic->ReferenceFrames[i].BottomFieldOrderCnt = ref->display_order;

    }

    for (; i < FF_ARRAY_ELEMS(vpic->ReferenceFrames); i++) {

        vpic->ReferenceFrames[i].picture_id = VA_INVALID_ID;

        vpic->ReferenceFrames[i].flags = VA_PICTURE_H264_INVALID;

    }



    vpic->coded_buf = pic->output_buffer;



    vpic->pic_fields.bits.idr_pic_flag = (pic->type == PICTURE_TYPE_IDR);

    vpic->pic_fields.bits.reference_pic_flag = (pic->type != PICTURE_TYPE_B);



    pic->nb_slices = 1;



    return 0;

}

static int video_read_header(AVFormatContext *s,

                             AVFormatParameters *ap)

{

    AVStream *st;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR_NOMEM;



    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = s->iformat->value;

    st->need_parsing = 1;



    /* for mjpeg, specify frame rate */

    /* for mpeg4 specify it too (most mpeg4 streams dont have the fixed_vop_rate set ...)*/

    if (ap && ap->time_base.num) {

        av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

    } else if ( st->codec->codec_id == CODEC_ID_MJPEG ||

                st->codec->codec_id == CODEC_ID_MPEG4 ||

                st->codec->codec_id == CODEC_ID_H264) {

        av_set_pts_info(st, 64, 1, 25);

    }



    return 0;

}

static void ide_flush_cache(IDEState *s)

{

    if (s->blk == NULL) {

        ide_flush_cb(s, 0);

        return;

    }



    s->status |= BUSY_STAT;

    ide_set_retry(s);

    block_acct_start(blk_get_stats(s->blk), &s->acct, 0, BLOCK_ACCT_FLUSH);

    s->pio_aiocb = blk_aio_flush(s->blk, ide_flush_cb, s);

}

static void decode_block(BinkAudioContext *s, short *out, int use_dct)

{

    int ch, i, j, k;

    float q, quant[25];

    int width, coeff;

    GetBitContext *gb = &s->gb;



    if (use_dct)

        skip_bits(gb, 2);



    for (ch = 0; ch < s->channels; ch++) {

        FFTSample *coeffs = s->coeffs_ptr[ch];

        q = 0.0f;

        coeffs[0] = get_float(gb) * s->root;

        coeffs[1] = get_float(gb) * s->root;



        for (i = 0; i < s->num_bands; i++) {

            /* constant is result of 0.066399999/log10(M_E) */

            int value = get_bits(gb, 8);

            quant[i] = expf(FFMIN(value, 95) * 0.15289164787221953823f) * s->root;

        }



        // find band (k)

        for (k = 0; s->bands[k] < 1; k++) {

            q = quant[k];

        }



        // parse coefficients

        i = 2;

        while (i < s->frame_len) {

            if (get_bits1(gb)) {

                j = i + rle_length_tab[get_bits(gb, 4)] * 8;

            } else {

                j = i + 8;

            }



            j = FFMIN(j, s->frame_len);



            width = get_bits(gb, 4);

            if (width == 0) {

                memset(coeffs + i, 0, (j - i) * sizeof(*coeffs));

                i = j;

                while (s->bands[k] < i)

                    q = quant[k++];

            } else {

                while (i < j) {

                    if (s->bands[k] == i)

                        q = quant[k++];

                    coeff = get_bits(gb, width);

                    if (coeff) {

                        if (get_bits1(gb))

                            coeffs[i] = -q * coeff;

                        else

                            coeffs[i] =  q * coeff;

                    } else {

                        coeffs[i] = 0.0f;

                    }

                    i++;

                }

            }

        }



        if (CONFIG_BINKAUDIO_DCT_DECODER && use_dct) {

            coeffs[0] /= 0.5;

            ff_dct_calc (&s->trans.dct,  coeffs);

            s->dsp.vector_fmul_scalar(coeffs, coeffs, s->frame_len / 2, s->frame_len);

        }

        else if (CONFIG_BINKAUDIO_RDFT_DECODER)

            ff_rdft_calc(&s->trans.rdft, coeffs);

    }



    s->fmt_conv.float_to_int16_interleave(out, (const float **)s->coeffs_ptr,

                                          s->frame_len, s->channels);



    if (!s->first) {

        int count = s->overlap_len * s->channels;

        int shift = av_log2(count);

        for (i = 0; i < count; i++) {

            out[i] = (s->previous[i] * (count - i) + out[i] * i) >> shift;

        }

    }



    memcpy(s->previous, out + s->block_size,

           s->overlap_len * s->channels * sizeof(*out));



    s->first = 0;

}

